window.KURAN_DATA = [{"id":1,"name":"Fatiha Suresi","verses":[{"n":1,"t":"Rahman, Rahim Allah’ın ismiyle"},{"n":2,"t":"Övgü, evrenlerin Efendisi ALLAH’adır."},{"n":3,"t":"Rahman, Rahim (Merhametli)."},{"n":4,"t":"Yargı Gününün sahibi."},{"n":5,"t":"Ancak sana hizmet eder, ancak senden yardım dileriz."},{"n":6,"t":"Bizi doğru yola ilet."},{"n":7,"t":"Gazaba uğrayanların ve sapmışların değil; kendilerine iyilikte bulunduğun kimselerin yoluna…"}]},{"id":2,"name":"Bakara Suresi","verses":[{"n":1,"t":"A. L. M."},{"n":2,"t":"Bu, erdemliler için yol gösterici, kuşku içermeyen bir kitaptır."},{"n":3,"t":"Onlar ki duyularıyla algılayamadıkları gerçekleri de onaylarlar, namazı (salat) gözetirler, kendilerine verdiğimiz rızıktan muhtaçlara verirler."},{"n":4,"t":"Sana indirileni ve senden önce indirileni onaylarlar. Ahiret konusunda da hiçbir kuşkuları yoktur."},{"n":5,"t":"İşte, Rab’leri tarafından yol gösterilenler ve mutluluğa erenler bunlardır."},{"n":6,"t":"İnkar edenlere gelince, onları uyarsan da uyarmasan da onlar için birdir; onlar onaylamazlar."},{"n":7,"t":"ALLAH kalplerini ve kulaklarını mühürler. Gözlerinde perde vardır ve büyük azap onlar içindir."},{"n":8,"t":"Halktan öyle kimseler var ki aslında onaylamadıkları halde \"ALLAH’a ve ahiret gününü onayladık\" derler."},{"n":9,"t":"ALLAH’ı ve müminleri aldatmak isterler. Halbuki kendi kendilerini aldatıyorlar. Farkında bile değiller."},{"n":10,"t":"Kalplerinde hastalık var. ALLAH da hastalıklarını arttırır. Yalanları yüzünden acı bir azabı hak ederler."},{"n":11,"t":"Kendilerine, \"Yeryüzünde bozgunculuk yapmayın\" denildiğinde \"Bizler sadece düzeltenleriz\" derler."},{"n":12,"t":"Oysa onlardır asıl bozguncu; farkında bile değiller."},{"n":13,"t":"Kendilerine, \"Şu halkın gerçeği onayladığı gibi onaylayın\" denildiğinde, \"Beyinsizlerin onayladığı gibi mi onaylayacağız\" derler. Gerçek beyinsizler onlardır; fakat bilmezler."},{"n":14,"t":"Gerçeği onaylayanlarla karşılaştıkları vakit, \"Gerçeği onaylıyoruz\" derler; fakat sapkınlarıyla başbaşa kaldıklarında, \"Sizinle beraberiz. Biz sadece hafife almaktayız\" derler."},{"n":15,"t":"ALLAH da, taşkınlıkları içinde bocalar durumda bırakarak asıl onları hafife alır."},{"n":16,"t":"Onlar hidayet karşılığında sapıklığı satın aldı. Ticaretleri ne kâr bırakır, ne de onları gerçeğe ulaştırır."},{"n":17,"t":"Durumları, ateş yakan kimselerin şu durumuna benzer: Ateş çevrelerini aydınlatmaya başlayınca ALLAH onların ışığını giderir ve onları karanlıklar içinde görmez bir halde bırakır."},{"n":18,"t":"Sağır, dilsiz ve kördürler; yönlerini değiştiremezler."},{"n":19,"t":"Ya da, karanlık, gök gürültüsü ve şimşekler arasında gökten boşanan bir yağmur altında yıldırımlardan ölmek korkusuyla parmaklarını kulaklarına tıkayan kimseye benzerler. ALLAH inkârcıları böyle kuşatır."},{"n":20,"t":"Şimşek neredeyse gözlerini kapıverecek! Önlerini aydınlattıkça ışığında yürürler. Üzerlerine karanlık basınca da dikilir kalırlar. ALLAH dileseydi işitme ve görmelerini giderirdi. ALLAH her şeye gücü yetendir."},{"n":21,"t":"İnsanlar! Sizi ve sizden öncekileri yaratan Efendinize hizmet edin ki korunasınız."},{"n":22,"t":"O, yeryüzünü sizin için oturulabilir hale soktu ve göğü de bir yapı kıldı. Gökten su indirdi ve onunla rızık olarak size çeşitli ürünler çıkardı. Bile bile ALLAH’a eşler koşmayın."},{"n":23,"t":"Kulumuza indirdiğimizden kuşku içinde iseniz, buna benzer bir sure getirin. ALLAH’tan başka tüm tanıklarınızı da yardıma çağırın, doğru sözlü iseniz."},{"n":24,"t":"Bunu yapamazsanız –ki asla yapamayacaksınız– o takdirde inkârcılar için hazırlanan ve yakıtı insanlar ile taşlar olan ateşten sakının."},{"n":25,"t":"Gerçeği onaylayıp erdemli davrananları, içlerinde ırmaklar akan bahçelerle müjdele. Kendilerine oradaki ürünlerden rızıklar sunulduğunda \"Bu, daha önce bize sunulan nimetlerdir\" derler. Böylece, kendilerine mecazi tanımlar (benzetmeler) verilir. Onlar için orada tertemiz eşler vardır ve onlar orada ebedi kalıcıdırlar."},{"n":26,"t":"ALLAH bir sivrisineği hatta onun üzerindekini örnek vermekten çekinmez. Gerçeği onaylayanlar, bunun Rab’lerinden gelen bir gerçek olduğunu bilir. İnkarcılar ise \"ALLAH bu benzetme ile neyi amaçladı\" derler. O, bununla birçok kişiyi saptırır ve birçok kişiyi de doğruya iletir. O, bununla sadece fasıkları saptırır."},{"n":27,"t":"Onlar ki ALLAH ile yaptıkları anlaşmaya bağlılık sözü verdikten sonra onu bozarlar, ALLAH’ın birleştirilmesini emrettiği şeyi keserler ve yeryüzünde bozgunculuk yaparlar. İşte onlar kaybedenlerdir."},{"n":28,"t":"ALLAH’ı nasıl inkâr edersiniz? Siz ölüler idiniz o sizi diriltti. Sonra sizi öldürür ve tekrar diriltir ve sonunda ona döndürülürsünüz."},{"n":29,"t":"Yeryüzünde her şeyi sizin için yaratan O’dur. Nitekim göğe yönelip onu yedi gök olarak düzenledi. O, her şeyi Bilir."},{"n":30,"t":"Efendin, meleklere şöyle demişti: \"Yeryüzüne bir halife yerleştireceğim.\" melekler de: \"Orada bozgunculuk yapacak, kan akıtacak birisini mi yerleştireceksin? Halbuki biz seni överek yüceltiyor ve mutlak otoriteni onaylıyoruz\" dediler. \"Bilmediğinizi Ben bilirim\" dedi."},{"n":31,"t":"Adem’e tüm isimleri (nitelemeleri) öğretti, sonra onları meleklere sunup, \"Doğru iseniz, şunların isimlerini (özelliklerini, niteliklerini) siz bana bildirin\" dedi."},{"n":32,"t":"Dediler: \"Sen Yücesin, senin bize öğrettiğinden başka bir bilgimiz yok. Sen Bilensin, Bilgesin.\""},{"n":33,"t":"Dedi: \"Adem! Onların isimlerini şunlara haber ver.\" İsimlerini onlara haber verince, \"Size, yerin ve göklerin sırlarını biliyorum, açıkladığınızı da gizlediğinizi de biliyorum dememiş miydim\" dedi."},{"n":34,"t":"Denetçilere, \"Adem’e secde edin\" dedik. İblis hariç hepsi secde ettiler, o ise diretti, büyüklük tasladı ve nankörlük etti."},{"n":35,"t":"\"Adem! Eşinle birlikte bahçede kal. Dilediğiniz yerde ondan bolca yeyin; ancak şu ağaca yaklaşmayın, yoksa zalimlerden olursunuz!\" dedik."},{"n":36,"t":"Sapkın, onları oradan kaydırıp bulundukları yerden çıkarttı. Nihayet, \"Birbirinize düşman olarak aşağı inin. Yeryüzünde belli bir süre kalıp yaşayacaksınız\" dedik."},{"n":37,"t":"Adem, Efendinden kelimeler aldı. Bunun üzerine onun tövbesini kabul etti. O, yönelişlere karşılık verendir, Rahim’dir."},{"n":38,"t":"\"Oradan topluca ininiz\" dedik, \"Benden size bir yol gösterici geldiği zaman, o yol göstericiye uyanlar için artık bir korku yok ve onlar üzülmeyecekler.\""},{"n":39,"t":"\"Ayetlerimizi yalanlayıp inkâr edenler ise ateşe mahkûmdur; orada sürekli kalacaklar.\""},{"n":40,"t":"İsrailoğulları! Size verdiğim nimetimi hatırlayın, bana verdiğiniz sözü tutun ki ben de size verdiğim sözü tutayım; yalnız benden korkun!"},{"n":41,"t":"Yanınızdakini doğrulayıcı olarak indirdiğimi onaylayın. Ona karşı çıkanların ilki olmayın. Ayetlerimi değeri düşük şeylerle değişmeyin; sadece benden çekinin."},{"n":42,"t":"Bile bile gerçeği yanlış ile karıştırmayın, gerçeği gizlemeyin."},{"n":43,"t":"Namazı gözetin, zekatı verin ve eğilenlerle birlikte eğilin."},{"n":44,"t":"Halkı iyilik yapmaya çağırıp dururken kendinizi unutuyor musunuz? Üstelik Kitabı da okuyorsunuz? Aklınızı kullanmaz mısınız?"},{"n":45,"t":"Güçlüklere karşı direnerek (sabır) ve namazla yardım isteyiniz. Elbette bu, halka ağır gelir; ancak saygılı olanlar hariç."},{"n":46,"t":"Nitekim onlar, Rab’lerine kavuşacaklarına ve O’na döneceklerine inanırlar."},{"n":47,"t":"İsrailoğulları! Size verdiğim nimetlerimi ve sizi tüm halklara üstün tutmamı hatırlayın."},{"n":48,"t":"Öyle bir günden sakının ki, kimse kimsenin yerine bir şey ödeyemez, aracılık (şefaat) kabul edilmez, kimseden bir fidye alınmaz ve yardım da edilmez."},{"n":49,"t":"İşkencenin en kötüsünü size uygulayan, kadınlarınızı utandırıp oğullarınızı öldüren Firavunun adamlarından sizi kurtarmıştık. Bu ikisi, Efendinizden büyük bir sınav idi."},{"n":50,"t":"Denizi yararak sizi kurtarmış, Firavunun adamlarını da gözlerinizin önünde boğmuştuk."},{"n":51,"t":"Musa’yla kırk gece için sözleşmiştik. Ancak siz onun ardından kendinize zulmederek buzağıya hizmet ettiniz."},{"n":52,"t":"Bunlara rağmen, şükredersiniz diye sizi affettik."},{"n":53,"t":"Yola gelmeniz için de Musa’ya kitabı ve yasayı verdik."},{"n":54,"t":"Musa, halkına demişti ki: \"Ey halkım, sizler buzağıya hizmet etmekle nefsinize (kişilik, öz, ruh) zulmettiniz. Yaratıcınıza tövbe edin ve nefsinizi (egonuzu) öldürün/nefsinizle yüzleşin. Bu, yaratıcınız katında sizin için daha iyidir.\" O, sizi affeder. Elbette O, tövbeleri kabul edendir, Rahim’dir."},{"n":55,"t":"Bir zamanlar, \"Ey Musa, ALLAH’ı fiziksel olarak görmedikçe onaylamayız\" demiştiniz. Bakınıp dururken size yıldırım çarpmıştı."},{"n":56,"t":"Sonra, belki şükredersiniz diye ölümünüzün ardından sizi diriltmiştik."},{"n":57,"t":"Sizi bulutlarla gölgelendirmiş ve sizin için menna ve bıldırcın indirmiştik: \"Size verdiğimiz iyi rızıklardan yiyin.\" Fakat onlar bize değil, sadece kendilerine zulmediyorlardı."},{"n":58,"t":"\"Bu şehre girin. Orada dilediğiniz yerden bol bol yiyin. Kapıdan alçak gönüllü olarak girin ve dostça konuşun ki hatalarınızı bağışlayalım. Güzel davrananlara daha fazlasını veririz\" demiştik."},{"n":59,"t":"Ancak içinizdeki zalimler, kendilerine verilen kelimeleri başka kelimelerle değiştirdiler. Nitekim, yoldan çıktıkları için zulmedenlerin üzerine gökten bir azap indirdik."},{"n":60,"t":"Musa, bir zamanlar halkı için su aramıştı. \"Değneğinle taşa vur\" demiştik. Bunun üzerine taştan on iki pınar fışkırmıştı. Her kabile, içmesi için ayrılan pınarı bilmişti: \"ALLAH’ın rızkından yiyin için, yeryüzünde bozgunculuk ve düzenbazlık yapmayın.\""},{"n":61,"t":"Fakat siz, \"Musa! Artık tek bir çeşit yiyeceğe dayanamayacağız. Efendini bizim için çağır da bize fasulye, kabak, sarımsak, mercimek, soğan gibi toprağın bitirdiğinden yetiştirsin\" demiştiniz de, \"İyi olanı daha düşük olanla mı (özgürlüğü kölelikle mi) değiştirmek istiyorsunuz? İsterseniz Mısır’a geri dönün, orada aradığınızı bulabilirsiniz!\" demişti. Böylece alçaklık ve yoksulluğa mahkûm edildiler ve ALLAH’ın gazabına uğradılar. Çünkü onlar ALLAH’ın ayetlerine karşı sürekli nankörce davranıyorlar, peygamberleri haksız yere öldürüyorlardı. Çünkü onlar, karşı gelip taşkınlıkta bulunuyorlardı."},{"n":62,"t":"Gerçeği onaylayanlar, Yahudiler, Hıristiyanlar ve diğer dinlerden her kim: ALLAH’ı ve ahiret gününü onaylar ve erdemli bir hayat sürdürürse, onların ödülleri Rab’leri katındadır. Onlar için korku ve üzüntü yoktur."},{"n":63,"t":"Sina dağını üzerinize kaldırarak bir zamanlar sizden söz almıştık: \"Size verdiğimize kuvvetle sarılın, içindekileri hatırlayın ki korunasınız\" demiştik."},{"n":64,"t":"Fakat bundan sonra da yüz çevirdiniz. ALLAH’ın size bol nimeti ve merhameti olmasaydı kaybederdiniz."},{"n":65,"t":"Sizden Cumartesi yasağını çiğneyenleri elbette biliyorsunuz. Onlara \"Aşağılık maymunlar olun\" dedik."},{"n":66,"t":"Bu cezayı çağdaşlarına ve sonraki kuşaklara bir ibret ve erdemli insanlar için de bir öğüt yaptık."},{"n":67,"t":"Hani, Musa halkına: \"ALLAH bir inek boğazlamanızı emrediyor\" demişti. \"Bizimle alay mı ediyorsun\" deyince de \"Cahilce davranmaktan ALLAH’a sığınırım\" dedi."},{"n":68,"t":"\"Bizim için Efendini çağır da onun niteliğini bize açıklasın\" dediler. \"O diyor ki, o ne kart ne körpe, ikisinin ortasında bir düvedir. Size emredileni yapın\" dedi."},{"n":69,"t":"\"Bizim için Efendini çağır da onun rengini de açıklasın\" dediler. \"O diyor ki, o rengi parlak sarı bir düvedir, bakanların içini açar\" dedi."},{"n":70,"t":"\"Bizim için Efendini çağır da, onun niteliğini bize daha da açıklasın. Çünkü düveler bizce birbirine benziyor. ALLAH dilerse yolu buluruz\" dediler."},{"n":71,"t":"\"O diyor ki, o düve yeri sürüp ekini sulayarak boyunduruk altında ezilmemiş, kusursuz, alacasız bir düvedir\" dedi. \"İşte şimdi gerçeği getirdin!\" diyerek sonunda düveyi boğazladılar; az kalsın bunu yapmayacaklardı."},{"n":72,"t":"Hani bir kişiyi öldürmüş ve suçu birbirinize atmıştınız. Oysa ALLAH gizlediklerinizi açığa çıkaracaktı."},{"n":73,"t":"\"Bir parçasıyla ona vurun\" dedik. İşte, ALLAH ölüleri böyle diriltir ve düşünesiniz diye ayetlerini böyle gösterir."},{"n":74,"t":"Tüm bunlara rağmen yine kalpleriniz katılaştı; taş gibi, hatta daha katı. Çünkü öyle taşlar var ki kendisinden ırmaklar fışkırır. Bazıları yarılır, bağrından su çıkarır. Bazıları ise ALLAH’a olan saygıdan dolayı siner. ALLAH yaptıklarınızdan habersiz değildir."},{"n":75,"t":"Onların sizi onaylayacaklarını mı umuyorsunuz? Halbuki onların bir kısmı, ALLAH’ın sözünü işitip kavradıktan sonra, bile bile çarpıtıp tahrif ederlerdi."},{"n":76,"t":"Gerçeği onaylayanlarla karşılaşınca, \"Gerçeği onayladık\" derler; baş başa kaldıklarında ise \"Efendiniz katında size karşı delil olarak kullanmaları için, ALLAH’ın size açıkladığını mı onlara anlatıyorsunuz, akletmez misiniz\" derler."},{"n":77,"t":"Bilmezler mi ki ALLAH gizledikleri ve açıkladıkları her şeyi biliyor?"},{"n":78,"t":"Aralarında ümmiler var ki kuruntu ve söylentilerin dışında kitabı bilmezler; bildiklerini zannederler."},{"n":79,"t":"Kitab’ı elleriyle yazdıktan sonra onu ucuz bir fiyata satmak için onun ALLAH’tan olduğunu söyleyenlerin vay haline. Ellerinin yazdığından dolayı vay haline onların. Kazandıklarından dolayı vay haline onların!"},{"n":80,"t":"\"Sayılı birkaç gün dışında ateş bize değmeyecek\" dediler. De ki: \"ALLAH’tan böyle bir söz mü aldınız –ki ALLAH verdiği sözden dönmez– yoksa ALLAH adına bilmediğiniz bir şeyi mi söylüyorsunuz?\""},{"n":81,"t":"Evet, günah işleyip suçu kendisini kuşatan kimseler ateş halkıdır; orada sürekli kalırlar."},{"n":82,"t":"Gerçeği onaylayıp erdemli bir hayat sürenler ise bahçe halkıdır; onlar da orada sürekli kalırlar."},{"n":83,"t":"İsrailoğullarından şöyle söz almıştık: ALLAH’tan başkasına hizmet etmeyecek, anaya babaya, yakınlara, yetimlere ve yoksullara iyilik edeceksiniz. İnsanlarla dostça konuşacaksınız. Namazı gözetecek, zekatı vereceksiniz. Fakat bundan sonra pek azınız hariç geri döndünüz."},{"n":84,"t":"Birbirinizin kanını dökmeyeceksiniz ve birbirinizi yurtlarından çıkarmayacaksınız diye de sizden söz almıştık. Bunu kabul etmiş ve tanık olmuştunuz."},{"n":85,"t":"Tüm bunlardan sonra, sizler hâlâ birbirinizi öldürüyor, aranızdan bir grubu yurtlarından çıkarıyor, kötülük ve düşmanlıkta onlara karşı birleşiyorsunuz. Onları yurtlarından çıkarmanız zaten size haramken, bu yetmiyormuş gibi size esir düştüklerinde bir de onlardan fidye istiyorsunuz. Yoksa siz kitabın bir kısmını onaylayıp bir kısmını inkâr mı ediyorsunuz? Böyle davrananların cezası dünya hayatında rezil olmak ve Diriliş Gününde de azabın en çetinine uğratılmaktan başka ne olabilir? ALLAH yaptıklarınızdan gafil değil."},{"n":86,"t":"Onlar, ahiret karşılığında dünya hayatını satın alan kimselerdir. Bu yüzden azapları hafifletilmez ve kendilerine yardım edilmez."},{"n":87,"t":"Musa’ya kitabı verdik ve ondan sonra ard arda elçiler gönderdik. Meryemoğlu İsa’ya da apaçık deliller verdik ve onu Kutsal Ruh ile destekledik. Hoşunuza gitmeyen bir şeyle ne zaman size bir elçi geldiyse büyüklük taslamadınız mı? Nitekim, bir kısmınız yalanladınız ve bir kısmınız da öldürüyordunuz."},{"n":88,"t":"Hatta \"Sabit fikirliyiz\" dediler. Halbuki, inkârlarından dolayı ALLAH onları lanetlemişti! Bu yüzden onların pek azı gerçeği onaylar."},{"n":89,"t":"İnkarcılara karşı yardım beklemelerine rağmen, onlara ALLAH katından yanlarındakini doğrulayıcı bir kitap, bu bekledikleri şey, kendilerine gelince onu inkâr ettiler. ALLAH’ın laneti, inkarcılara olsun!"},{"n":90,"t":"ALLAH’ın, lütfunu kullarından dilediğine indirmesini çekemeyerek ALLAH’ın indirdiğini inkâr etmek için kişiliklerini satmaları ne kötü! Böylece gazap üstüne gazaba uğradılar. Kafirlere alçaltıcı bir azap var."},{"n":91,"t":"Kendilerine, \"ALLAH’ın indirdiğini onaylayın\" denildiğinde, \"Bize indirileni onaylarız\" diyerek ondan sonrasını inkâr ederler. Oysa bu, yanlarında bulunanı doğrulayan gerçektir. \"Gerçeği onayladı iseniz, neden daha önce ALLAH’ın peygamberlerini öldürüyordunuz\" de."},{"n":92,"t":"Musa, size mucizelerle gelmişti; fakat onun ardından buzağıyı tanrı edinerek zalimlerden oldunuz."},{"n":93,"t":"Hani üzerinize Tur dağını kaldırıp sizden söz almıştık: \"Size verdiğim emirlere sıkıca sarılın ve dinleyin.\" Fakat \"Dinledik ve karşı geldik\" dediler. İnkarlarından dolayı kalpleri buzağı ile kandı. De ki: \"Onaylamışsanız, onayınız size ne de kötü yön veriyor!\""},{"n":94,"t":"De ki: \"İleri sürdüğünüz gibi, ahiret yurdu ALLAH tarafından hiç kimseye değil sadece size ayrılmışsa ve bu savınızda samimi iseniz haydi ölümü isteyin!\""},{"n":95,"t":"Ellerinin işlediklerinden ötürü bunu asla dilemeyeceklerdir. ALLAH zalimleri bilir."},{"n":96,"t":"Onları, yaşamaya en düşkün insanlar olarak bulacaksın; putperestlerden bile fazla… Onlardan her biri bin sene yaşamak ister. Oysa, uzun yaşaması onu azaptan uzaklaştırmaz. ALLAH yaptıklarını görendir."},{"n":97,"t":"Şunu de: \"Cibril’e her kim düşman olursa,\" ki kendinden öncekileri doğrulayıcı, gerçeği onaylayanlara yol gösterici ve müjde olarak ALLAH’ın izniyle bunu kalbine indirmiştir."},{"n":98,"t":"\"Evet, ALLAH’a, meleklerine, elçilerine, Cibril’e ve Mikail’e kim düşman olursa bilsin ki ALLAH da kafirlerin düşmanıdır.\""},{"n":99,"t":"Sana apaçık ayetler indirdik. Yoldan çıkmış olanlardan başkası onları inkâr etmez."},{"n":100,"t":"Her ne zaman bir anlaşma yaptılarsa onlardan bir grup onu bozup atmadı mı? Zaten onların çoğu gerçeği onaylamaz."},{"n":101,"t":"Yanlarındakini doğrulayan bir elçi ALLAH tarafından görevli olarak kendilerine gelince, kitap verilenlerin bazısı, ALLAH’ın kitabını sırtlarının ardına attı. Bilmezlermiş gibi…"},{"n":102,"t":"Süleyman’ın otoritesi hakkında sapkınların anlattığına uydular. Oysa Süleyman inkâr etmedi; halka büyücülüğü ve Babil’de Harut ve Marut adlı iki meleğe indirileni öğreten sapkınlar inkâr etmişti. Bu ikisi: \"Bu bir sınavdır, nankör olmayın!\" demedikçe kimseye onu öğretmezlerdi. Fakat o ikisinden öğrendiklerini, koca ile karısının arasını açmak için kullandılar. Oysa ALLAH’ın izni olmadan onlar hiç kimseye bir zarar veremezdi. Kendilerine yarar vereni değil, zarar vereni öğreniyorlardı. Üstelik, ona müşteri olanların ahirette bir payı olmadığını da iyi biliyorlardı. Karşılığında kişiliklerini sattıkları şey ne kötü. Bir bilselerdi!"},{"n":103,"t":"Onlar gerçeği onaylayıp günahlardan sakınmış olsalardı elbette ALLAH’tan alacakları ödül çok daha hayırlı olurdu. Bir bilselerdi!"},{"n":104,"t":"Gerçeği onaylayanlar! \"Bize çobanlık et (raina)\" demeyin; \"Bizi gözetiniz (unzurna)\" deyin ve dinleyin. İnkarcılar için acı bir azap var."},{"n":105,"t":"Kitaplıların inkârcıları da, putperestler de Efendinizden size bir iyilik indirilmesini istemez. ALLAH rahmetini dilediğine verir. ALLAH büyük lütuf sahibidir."},{"n":106,"t":"Daha iyisini veya benzerini getirmedikçe bir mucize veya şeriatı yürürlükten kaldırmaz veya unutturmayız. ALLAH’ın her şeye gücü yettiğini bilmez misin?"},{"n":107,"t":"Yerin, göklerin egemenliğinin ALLAH’a ait olduğunu ve ALLAH’tan başka bir sahip ve yardımcın olmadığını bilmez misin?"},{"n":108,"t":"Daha önce Musa’dan istendiği gibi, siz de elçinizden isteklerde mi bulunmayı arzuluyorsunuz? Kim gerçeği onaylamayı inkâr ile değiştirirse o doğru yolu kaybetmiştir."},{"n":109,"t":"Kitap ehlinin birçoğu, gerçek kendilerine belli olduğu halde, özlerindeki kıskançlıktan ötürü sizi onayınızdan sonra inkâra döndürmeyi arzular. ALLAH emrini getirinceye kadar onları affediniz, tolerans gösteriniz. ALLAH her şeye gücü yetendir."},{"n":110,"t":"Namazı gözetin, zekatı verin. Kendiniz için yapıp gönderdiğiniz her iyiliği elbette ALLAH katında bulacaksınız. ALLAH yaptığınız her şeyi görür."},{"n":111,"t":"\"Yahudi veya Hıristiyanlardan başkası bahçeye giremez\" dediler. Bu, onların kuruntusudur. De ki: \"Doğru sözlüler iseniz delilinizi getirin.\""},{"n":112,"t":"Doğrusu, kim iyilik yaparak kendini ALLAH’a teslim ederse, onun ödülü Efendinin yanındadır; onlara korku yoktur ve onlar üzülmeyecektir."},{"n":113,"t":"Yahudiler: \"Hıristiyanların bir temeli yok\" derken, Hıristiyanlar da: \"Yahudilerin bir temeli yok\" dediler. Oysa hepsi de kitabı okuyorlar. Cahiller de tıpkı onlar gibi konuşur. Diriliş günü ALLAH ayrılığa düştükleri konularda aralarında hüküm verecektir."},{"n":114,"t":"ALLAH’ın mescitlerinde, O’nun isminin anılmasına engel olan ve oraların yıkılması için çalışan kimseden daha kötü kim olabilir? Halbuki onların oralara ancak korkarak girmeleri gerekir. Onlar için dünyada rezillik, ahirette de büyük azap var."},{"n":115,"t":"Doğu da batı da ALLAH’ındır. Nereye yönelirseniz ALLAH’ın yüzü oradadır. ALLAH her şeyi kuşatan ve her şeyi bilendir."},{"n":116,"t":"\"ALLAH çocuk edindi\" dediler. Haşa, O yücedir. Göklerde ve yerde olanların hepsi O’nundur, hepsi O’na boyun eğmiştir."},{"n":117,"t":"Gökleri ve yeri yoktan var edendir. Bir işin olmasını dilerse, ona sadece \"Ol\" der ve olur."},{"n":118,"t":"Cahiller, \"ALLAH bizimle konuşmalı veya bize bir ayet gelmeli değil miydi\" dediler. Daha öncekiler de onlar gibi konuşmuşlardı. Kafaları birbirine benziyor. Biz ayetleri, onaylayacak olanlara sergileriz."},{"n":119,"t":"Biz seni, gerçekle, müjdeleyici ve uyarıcı olarak gönderdik. Cehennem halkından sen sorumlu değilsin."},{"n":120,"t":"Dinlerine girmedikçe ne Yahudiler, ne de Hıristiyanlar, senden hoşnut olmazlar. De ki: \"Doğru yol ALLAH’ın yoludur.\" Sana gelen bilgiden sonra onların fantezilerine uyarsan ALLAH’a karşı seni savunacak ne bir dost ne de bir destekleyici bulamazsın."},{"n":121,"t":"Kendilerine verdiğimiz kitabı gereği gibi izleyenler bu gerçeği onaylar; inkâr edenlerse kaybeder."},{"n":122,"t":"İsrailoğulları, size verdiğim nimetimi ve diğer halklardan daha çok size bağışta bulunduğumu hatırlayın."},{"n":123,"t":"Kimsenin kimseden yana bir şey ödeyemediği, hiç kimseden fidye alınmadığı ve hiç kimseye aracılığın (şefaat) yarar sağlamadığı ve yardımın kesildiği bir günden sakının."},{"n":124,"t":"Efendisi, bir zamanlar İbrahim’i birtakım kelimelerle sınamış; o da onları tamamlamıştı: \"Seni insanlara önder yapacağım\" demişti. \"Soyumdan da?..\" deyince, \"Zalimler benim sözüme dahil olmaz\" buyurmuştu."},{"n":125,"t":"Ev’i halk için bir odak noktası ve bir güven yeri kıldık. İbrahim’in makamını bir namaz yeri olarak kullanın. \"Ziyaretçiler, kendini ibadete verenler ve eğilip secde edenler için ikiniz Evimi temiz tutun\" diye İbrahim ve İsmail’i görevlendirmiştik."},{"n":126,"t":"İbrahim, \"Efendim, burayı güvenlik yeri kıl. ALLAH’a ve ahiret gününü onaylayan halkına ürünlerle rızık ver\" deyince, \"İnkar edene de rızık vereceğim. Onu kısa bir süre geçindirir, sonra onu ateş cezasına mahkûm ederim. Ne kötü bir uğrak yeridir orası!\" dedi."},{"n":127,"t":"İbrahim, İsmail ile birlikte Ev’in temellerini yükseltiyor: \"Efendimiz, bizden kabul et, şüphesiz sen İşitensin, Bilensin.\""},{"n":128,"t":"\"Efendimiz, ikimizi sana barış içinde teslim olanlar (Müslümanlar) yap. Soyumuzdan da sana barış içinde teslim olan bir topluluk çıkar. Bize nasıl ibadet edeceğimizi göster, sana yönelmemizi kabul et, kuşkusuz sen yönelişleri kabul edensin, Rahimsin.\""},{"n":129,"t":"\"Efendimiz, onların arasından, ayetlerini onlara okuyacak, onlara kitabı ve bilgeliği öğretecek ve onları temizleyecek bir elçi gönder. Sen Yücesin, Bilgesin.\""},{"n":130,"t":"Kendini kandırandan başkası İbrahim’in dininden yüz çevirmez. Onu bu dünyada seçtik, ahirette de erdemli kişilerden olacak."},{"n":131,"t":"Efendisi, kendisine \"Barış içinde teslim ol\" dediğinde; \"Evrenlerin Efendisine barış içinde teslim oldum\" diye karşılık vermişti."},{"n":132,"t":"İbrahim ve daha sonra Yakup şunu çocuklarına öğütledi: \"Evlatlarım! ALLAH sizin için bu dini seçti; Müslüman olarak ölmeye bakın.\""},{"n":133,"t":"Yakup can verirken tanık olsaydınız. O, çocuklarına: \"Benden sonra kime hizmet edeceksiniz\" diye sormuştu. Onlar da, \"Senin Tanrın, ataların İbrahim, İsmail ve İshak’ın Tanrısı olan tek Tanrıya hizmet edeceğiz, biz O’na teslim olanlarız\" demişlerdi."},{"n":134,"t":"Geçmişteki bir toplum bu! Onların kazandıkları kendilerinin, sizin kazandıklarınız sizindir. Siz onların yaptıklarından sorulmazsınız."},{"n":135,"t":"\"Yahudi veya Hıristiyan olun ki doğru yolu bulasınız\" dediler. De ki: \"Hayır, biz İbrahim’in tektanrıcı dinine uyarız. O, ortak koşanlardan olmadı.\""},{"n":136,"t":"\"ALLAH’a, bize indirilene, İbrahim, İsmail, İshak, Yakub ve torunlarına indirilenlere, Musa’ya, İsa’ya verilene ve tüm peygamberlere Rab’leri tarafından verilenleri onayladık. Onların hiçbiri arasında ayrım yapmayız. Biz sadece O’na teslim olanlarız\" deyiniz."},{"n":137,"t":"Sizin onayladığınız gibi onaylasalar doğru yolu bulmuş olurlar. Yüz çevirirlerse, karşıt olmuş olurlar. Onlara karşı ALLAH sana yeter. O İşitendir, Bilendir."},{"n":138,"t":"Budur ALLAH’ın sistemi! Kimin sistemi ALLAH’ınkinden daha iyidir? \"Biz yalnız O’na hizmet ederiz.\""},{"n":139,"t":"\"Bizimle ALLAH hakkında mı tartışıyorsunuz? Oysa O, bizim de Efendimiz, sizin de Efendinizdir. Biz işlediğimizden, siz de işlediğinizden sorumlusunuz. Biz kendimizi sadece O’na adadık\" de."},{"n":140,"t":"İbrahim, İsmail, İshak, Yakub ve torunlarının Yahudi veya Hıristiyan olduğunu mu ileri sürüyorsunuz? De ki: \"Siz mi daha iyi biliyorsunuz yoksa ALLAH mı? ALLAH’ın bildirdiğini gizleyenden daha zalim kim olabilir? ALLAH yaptıklarınızdan gafil değil.\""},{"n":141,"t":"İşte onlar bir toplumdu; gelip geçtiler. Onların kazandıkları kendilerinin, sizin kazandıklarınız sizindir. Siz onların yaptıklarından sorulmazsınız."},{"n":142,"t":"Halktan bazı beyinsizler: \"Yöneldikleri kıbleden onları çeviren nedir?\" diyecekler. De ki: \"Doğu da batı da ALLAH’ındır. O dilediğini/dileyeni doğru yola iletir.\""},{"n":143,"t":"Böylece sizi açık fikirli bir toplum kıldık ki halkın arasında tanıklar olabilesiniz ve elçi de aranızda tanık olabilsin. Elçiye uyanlarla topukları üzerinde geriye dönenleri birbirinden ayırmak için eskiden yöneldiğin kıbleyi değiştirdik. ALLAH’ın yol gösterdiği kimseden başkasına elbette bu ağır gelir. ALLAH onayınızı boşa çıkarmaz. ALLAH insanlara Şefkatlidir, Rahimdir."},{"n":144,"t":"Yüzünü göğe çevirip durduğunu görüyoruz. Seni, hoşlanacağın bir kıbleye çevireceğiz. Artık yüzünü Sınırlanmış Mescid’e çevir. Nerede olursanız olun yüzlerinizi o yöne çevirin. Kuşkusuz, kendilerine kitap verilenler, bunun Rab’lerinden gelen bir gerçek olduğunu bilirler. ALLAH onların yaptığından gafil değildir."},{"n":145,"t":"Kitap verilenlere her türlü ayeti (mucizeyi) getirsen de onlar yine senin kıblene yönelmez. Sen de onların kıblesine uyacak değilsin. Onlar birbirlerinin kıblesine de uymaz. Sana gelen bu bilgiden sonra, onların keyfine uyarsan zalimlerden olursun."},{"n":146,"t":"Kendilerine kitap verdiklerimiz, bu gerçekleri çocuklarını tanıdıkları gibi tanırlar; ama yine de onlardan bir grup bile bile gerçeği gizler."},{"n":147,"t":"Bu, Efendinden gelen gerçektir; artık kuşkulanma."},{"n":148,"t":"Her birinizin seçtiği bir yön ve yöntem var; siz iyilikte yarışın. Nerede olursanız olun ALLAH sizi bir araya getirir. ALLAH elbette her şeye gücü yetendir."},{"n":149,"t":"Her nereden yola çıkarsan çık, yüzünü Sınırlanmış Mescide doğru çevirmelisin. Bu, elbette Efendinden gelen bir gerçektir. ALLAH yaptığınız hiçbir şeyden habersiz değildir."},{"n":150,"t":"Her nereden yola çıkarsan çık, yüzünü Sınırlanmış Mescide doğru çevir. Nerede olursanız olun, yüzünüzü onun tarafına çevirin ki halkın size karşı bir eleştiri malzemesi olmasın. Zalimlere gelince, onlardan çekinmeyin, benden çekinin ki size olan nimetimi tamamlayayım ve siz de doğruya ulaşabilesiniz."},{"n":151,"t":"Nitekim, bir elçiyi aranızdan seçip size gönderdik; size ayetlerimi okuyorlar. Böylece sizleri temizler, size kitap ve bilgeliği öğretir, bilmediklerinizi öğretir."},{"n":152,"t":"Beni hatırlayın ki ben de sizi hatırlayayım. Bana teşekkür edin; nankörlük etmeyin."},{"n":153,"t":"Gerçeği onaylayanlar! Güçlüklere karşı sabır ve namaz ile yardım dileyin. ALLAH sabredenlerle beraberdir."},{"n":154,"t":"ALLAH yolunda öldürülenlere, \"Onlar ölülerdir\" demeyin. Aksine onlar diridir fakat siz farkında değilsiniz."},{"n":155,"t":"Sizi korkuyla, açlıkla, para, can ve ürün kaybıyla sınayacağız. Müjde ver sabredenlere…"},{"n":156,"t":"Ki onlara bir musibet geldiğinde, \"Biz ALLAH’a aidiz ve O’na dönücüyüz\" derler."},{"n":157,"t":"İşte onlara, Rab’lerinden destek ve rahmet vardır. Onlar doğruya ulaşanlardır."},{"n":158,"t":"Sükunet ve mertlik ALLAH’ın işaretlerindendir. Konferans veya ziyaret (umre) için Ev’e varan birisi o ikisi arasında gidip gelebilir. Kim gönülden bir iyilik yaparsa, ALLAH teşekküre karşılık verendir, Bilendir…"},{"n":159,"t":"İndirdiğimiz açık delilleri ve hidayeti, –biz kitapta halka açıkladıktan sonra– gizleyenleri hem ALLAH ve hem de tüm lanetleyenler lanetler."},{"n":160,"t":"Ancak, yönelip kendilerini düzeltenler ve açıklayanlar hariç; onların tövbesini kabul ederim. Ben tövbeleri kabul edenim, Rahim’im."},{"n":161,"t":"İnkar edip inkârcı olarak ölenler ise hem ALLAH’ın, hem meleklerin ve hem halkın lanetini kazanır."},{"n":162,"t":"O durumda sürekli kalırlar. Azapları hafifletilmez ve ertelenmez."},{"n":163,"t":"Tanrınız bir tek tanrı; O’ndan başka tanrı yoktur. Rahman’dır, Rahim’dir."},{"n":164,"t":"Göklerin ve yerin yaratılışında, gecenin ve gündüzün birbiriyle yer değiştirmesinde, insanların yararı için okyanusta akıp giden gemilerde, ALLAH’ın gökten su indirip ölümünden sonra yeryüzünü diriltmesinde ve orada yaydığı her çeşit canlıda, rüzgarları ve gök ile yer arasında hazır bekleyen bulutları evirip çevirmesinde aklını kullanan bir toplum için elbette dersler/kanıtlar (ayaat) vardır."},{"n":165,"t":"ALLAH’tan başkasını tanrı edinen ve ALLAH’ı sever gibi onları seven kimseler var. Gerçeği onaylayanlar ise en çok ALLAH’ı sever. O zulmedenler, azabı gördükleri zaman tüm gücün ALLAH’a ait ve ALLAH’ın azabının çetin olduğunu anlayacaklarını bir bilselerdi!"},{"n":166,"t":"O zaman, uyulanlar kendilerine uyanlardan uzak duracaktır. Artık azabı görmüşlerdir ve aralarındaki tüm bağlar kesilmiştir."},{"n":167,"t":"Uyanlar şöyle diyecek: \"Keşke bir şansımız daha olsaydı da onların şimdi bizden uzak durdukları gibi biz de onlardan uzak dursaydık.\" Böylece ALLAH yaptıklarını pişmanlığa dönüştürür; ateşten çıkamazlar."},{"n":168,"t":"İnsanlar! Yerin helal ve temiz ürünlerinden yiyin, sapkının adımlarını izlemeyin; o size açık düşmandır."},{"n":169,"t":"O size kötülüğü, hayasızlığı ve ALLAH’a bilmediğiniz şeyleri yakıştırmanızı emreder."},{"n":170,"t":"Onlara, \"ALLAH’ın indirdiğine uyun\" dense, \"Hayır, biz atalarımızın izlediği yolu izleriz\" derler. Peki, ataları bir şey düşünemeyen ve doğru yolu bulamayan kimseler olsalar da mı?!"},{"n":171,"t":"İnkarcıların durumu, sözleri ancak bağırma ve çağırma biçiminde algılayarak anlamadan tekrarlayan kişi gibidir. Sağır, dilsiz ve kördürler; düşünmezler."},{"n":172,"t":"Gerçeği onaylayanlar, size verdiğimiz rızıkların iyilerinden yiyin. ALLAH’a şükredin, sadece O’na hizmet ediyorsunuz."},{"n":173,"t":"O, size sadece leş, kan, domuz eti ve ALLAH’tan başkası adına kesileni haram kılmıştır. Her kim mecbur kalırsa, suistimal yolunu aramamak ve sınırı aşmamak koşuluyla günah işlemiş olmaz. ALLAH Bağışlayandır, Rahimdir."},{"n":174,"t":"ALLAH’ın indirdiği kitaptan bir şey gizleyip onu az bir değere değişenler, karınlarına ateş tıkınıyorlar. Diriliş Gününde ALLAH onlarla konuşmaz ve onları arındırmaz. Onlara acı verici bir azap var."},{"n":175,"t":"Onlar, hidayet karşılığında sapıklığı ve affedilme karşılığında azabı satın almışlardır. Ateşe ne kadar da dayanıklıdırlar!"},{"n":176,"t":"Böyledir; çünkü ALLAH gerçeği içeren kitabı indirmiştir ve kitap hakkında tartışanlar ise doğrusu derin bir anlaşmazlık içindedir."},{"n":177,"t":"Yüzlerinizi doğu veya batı yönüne çevirmeniz iyilik değil. İyiler o kimseler ki ALLAH’ı, ahiret gününü, melekleri, kitabı ve peygamberleri onaylarlar; akrabalara, yetimlere, muhtaçlara, evsizlere, dilencilere ve köleleri özgürlüğe kavuşturmaya seve seve para yardımında bulunurlar; namazı gözetir, zekatı verir, sözleştikleri vakit sözlerinde dururlar; zorluğa, sıkıntıya ve zulme karşı direnirler. İşte doğru olanlar onlardır, erdemli olanlar da onlardır."},{"n":178,"t":"Gerçeği onaylayanlar! Öldürmede size eşitlik farz kılındı. Hürre karşı hür, köleye köle, kadına kadın… Ama kim maktulun hısımları tarafından bağışlanırsa, o zaman uygun olanı yapması ve diyeti güzelce ödemesi gerekir. Bu, Efendinizden bir hafifletme ve rahmettir. Bundan sonra kim sınırı aşarsa onun için acı bir azap var."},{"n":179,"t":"Sizin için bu eşitlikte hayat kurtarma vardır, ey akıl sahipleri, böylece korunursunuz."},{"n":180,"t":"Sizden birine ölüm yaklaştığında, bir mal bırakacaksa anaya babaya, yakınlara, uygun bir biçimde vasiyet etmesi farz kılındı. Bu, erdemliler için bir görevdir."},{"n":181,"t":"Kim işittikten sonra onu değiştirirse, günahı onu değiştirenleredir. ALLAH İşitendir, Bilendir."},{"n":182,"t":"Vasiyet edenin yanlışlık veya haksız bir paylaşım yapacağını sezen birisi olaya karışıp durumu düzeltirse günah işlemiş olmaz. ALLAH Bağışlayandır, Rahimdir."},{"n":183,"t":"Gerçeği onaylayanlar, sizden öncekilere oruç farz kılındığı gibi, sakınmanız için size de farz kılındı."},{"n":184,"t":"Sayılı günlerde… Hasta olanlarınız veya yolculukta bulunanlarınız tutamadığı günlerin sayısınca diğer günlerde tutar. Güç yetirenler bir yoksulu doyurarak adakta bulunsunlar. Kim gönül isteğiyle iyilik yaparsa kendisi için daha iyidir; ancak oruç tutmanız sizin için en iyisidir, bir bilseniz!"},{"n":185,"t":"Ramazan, insanlara yol gösterici, apaçık bir öğreti ve yasa kitabı olan Kuran’ın indirildiği aydır. Kim o aya ulaşırsa oruç tutsun. Hasta veya yolcu olanlarınız, tutamadığı günlerin sayısınca diğer günlerde oruç tutar. ALLAH sizin için kolaylık ister, zorluk istemez. Böylece sayıyı tamamlar, sizi doğruya ulaştıran ALLAH’ı yüceltip şükredersiniz."},{"n":186,"t":"Kullarım beni sana soracak olurlarsa bilsinler ki ben yakınım. Beni çağırdığı vakit çağıranın çağrısına karşılık veririm. Doğru yolu bulmaları için onlar da bana karşılık vermeli ve beni onaylamalı."},{"n":187,"t":"Oruç gecelerinde kadınlarınızla cinsel ilişkide bulunmanız size helal kılındı. Onlar sizin örtüleriniz, siz de onların örtülerisiniz. ALLAH, kendinizi kandırıp durduğunuzu bildi de tövbenizi kabul etti ve sizi bağışladı. Artık ALLAH’ın sizin için belirlediğini dileyerek onlarla cinsel ilişkide bulunabilirsiniz. Şafağın beyaz ve siyah ipliğini birbirinden ayırt edinceye kadar yiyin, için. Sonra geceye kadar orucu tamamlayın. Mescitlere kapanmış durumdayken onlarla cinsel ilişkide bulunmayın. Bunlar ALLAH’ın koyduğu sınırlardır; onları çiğnemeyin. ALLAH korunmaları için ayetlerini halka böyle açıklar."},{"n":188,"t":"Paralarınızı aranızda haksız yollarla yemeyin. Halkın parasını haksız yere yemek amacıyla bile bile memurlara/yöneticilere rüşvet vermeyin."},{"n":189,"t":"Sana ayın evrelerini soruyorlar. De ki o, insanlar ve konferans ibadeti için bir zaman ölçüsüdür. İyilik, lafı dolandırmak değildir, iyilik sakınmaktır. Dürüst olun. Kurtuluşunuz için ALLAH’ı dinleyin."},{"n":190,"t":"Sizinle savaşanlarla ALLAH yolunda savaşın. Saldırgan olmayın. ALLAH saldırganları sevmez."},{"n":191,"t":"Onlarla karşılaştığınız yerde onlarla savaşın ve sizi çıkardıkları yerden onları çıkarın; zulüm ve işkence öldürmekten beterdir. Sınırlanmış Mescid’in yanında sizinle savaşmadıkça onlarla savaşmayın. Size saldırırlarsa siz de onlara saldırın. İnkarcıların cezası böyledir."},{"n":192,"t":"Son verirlerse, ALLAH Bağışlayandır, Rahimdir."},{"n":193,"t":"Zulüm ve işkence ortadan kalkıncaya ve din ALLAH için oluncaya kadar onlarla savaşın. Son verirlerse, artık zalimlerden başkasına düşmanlık yoktur."},{"n":194,"t":"Sınırlanmış ay ancak iki taraflı gözetilebilir. Ateşkese uymak karşılıklıdır. Size saldırırlarsa onlara aynen saldırın. ALLAH’ı dinleyin ve bilin ki ALLAH erdemlilerin yanındadır."},{"n":195,"t":"ALLAH yolunda harcayın, kendi kendinizi zarara sokmayın. İyilik edin. ALLAH iyilik edenleri sever."},{"n":196,"t":"Yıllık Tartışma Konferansı ve umreyi ALLAH için tamamlayın. Engellenirseniz kolayınıza gelen bir hediye gönderin. Hediye, yerine ulaşıncaya kadar başınızı traş etmeyin; ancak hasta olan veya başından bir rahatsızlığı bulunanlar, oruç, sadaka veya herhangi bir ibadetle fidye vermeli. Güven ortamında, her kim Konferans zamanına kadar ziyaretten yararlanırsa, kolayına gelen bir hediye göndermeli. Bunu yerine getiremeyenler, konferans anında üç gün ve döndükten sonra da yedi gün olmak üzere toplam on gün oruç tutmalı. Bu, ailesi Sınırlanmış Mescid civarında oturmayanlar içindir. ALLAH’ı dinleyin ve bilin ki ALLAH’ın azabı çetindir."},{"n":197,"t":"Bilimsel tartışma konferansı, bilinen aylarda uygulanmalı. Kim o aylarda konferansa karar vermişse bilsin ki, konferansta cinsel ilişki, kötülük yapmak, çekişmek yoktur. Yaptığınız her iyiliği ALLAH bilir. Yol için azığınızı hazırlarken en hayırlı azığın erdemlilik olduğunu unutmayın. Anlayış sahipleri! Beni dinleyin."},{"n":198,"t":"Efendinizin iyiliğini aramanızda sakınca yok. Tanışma/kimlik istasyonundan ayrıldığınızda Sınırlanmış Bölgede ALLAH’ı anın. Sizi doğru yola ilettiği için O’nu anın; bundan önce siz sapıtmıştınız."},{"n":199,"t":"Sonra, halkın topluca yayıldığı yerden siz de yayılın, ALLAH’tan bağışlanma dileyin. ALLAH Bağışlayandır, Rahimdir."},{"n":200,"t":"Töreninizi bitirdiğiniz zaman, atalarınızı andığınız gibi, hatta daha güçlü olarak ALLAH’ı anmayı sürdürün. Halktan kimi \"Efendimiz, bize bu dünyada ver\" der; onun ahiretten bir payı olmaz."},{"n":201,"t":"Kimi de, \"Efendimiz, bize dünyada da iyilik ver, ahirette de iyilik ver. Bizi ateşin azabından koru\" der."},{"n":202,"t":"Hepsinin kazandıklarından bir payı vardır. ALLAH hesabı çabuk görendir."},{"n":203,"t":"Sayılı günlerde ALLAH’ı anın. Erdemli davrandıkları sürece, bunu iki günde bitirmek için acele edene bir günah yoktur, geri kalana da bir günah yoktur. ALLAH’ı dinleyin ve O’nun huzurunda toplanacağınızı unutmayın."},{"n":204,"t":"Dünya hayatı hakkında, sözleri senin hoşuna giden bazı kişiler var. Azılı bir düşman olduğu halde kalbinde olana ALLAH’ı tanık tutar."},{"n":205,"t":"Dönüp gidince, yeryüzünde bozgunculuk yapmak, malı ve nesli yok etmek için çabalar. ALLAH bozgunculuğu sevmez."},{"n":206,"t":"Kendisine \"ALLAH’ı dinle\" dendiğinde kibir ve gurur içinde hiddetlenir. Onun hakkından cehennem gelir; ne kötü bir meskendir!"},{"n":207,"t":"Halktan öylesi de var ki kendini ALLAH’ın rızasını kazanmaya adar. ALLAH kullarına çok şefkatlidir."},{"n":208,"t":"Gerçeği onaylayanlar, tümüyle teslim olun. Sapkının adımlarını izlemeyin; çünkü o sizin apaçık düşmanınızdır."},{"n":209,"t":"Size apaçık deliller gelmesine rağmen doğru yoldan kayarsanız, bilesiniz ki ALLAH Üstündür, Bilgedir."},{"n":210,"t":"ALLAH’ın ve meleklerin yoğun bulutlar arasından kendilerine gelmesini mi bekliyorlar? O zaman her şey biterdi ve her şey ALLAH’a döndürülürdü."},{"n":211,"t":"İsrailoğullarına sor, onlara nice apaçık ayetler verdik! Kendisine ALLAH’ın nimeti geldikten sonra onu değiştirenler için ALLAH ağır bir ceza verir."},{"n":212,"t":"İnkar edenler için dünya hayatı çekicidir. Bu yüzden gerçeği onaylayanları aşağılarlar. Oysa erdemliler Diriliş Günü onların üstündedir. ALLAH dilediğine hesapsız şekilde nimetler bahşeder."},{"n":213,"t":"İnsanlar bir tek topluluktu. ALLAH peygamberleri müjdeleyici ve uyarıcı olarak gönderdi ve anlaşmazlığa düştükleri konularda halkın arasında hükmetmeleri için onlarla birlikte gerçeği içeren kitabı indirdi. Oysa kitap verilenler kendilerine açık kanıtlar geldikten sonra aralarındaki kıskançlıktan ötürü onun hakkında anlaşmazlığa düştüler. Fakat ALLAH, izniyle gerçeği onaylayanları onların anlaşmazlığa düştüğü gerçeğe ulaştırdı. ALLAH dilediğini/dileyeni doğru yola iletir."},{"n":214,"t":"Yoksa siz, sizden öncekilerin başına gelenler gibisi sizin de başınıza gelmeden bahçeye gireceğinizi mi sanıyorsunuz? Onlar zorluk ve sıkıntıya uğradılar ve öylesine sarsıldılar ki elçi ve beraberindeki gerçeği onaylayanlar, \"ALLAH’ın yardımı ne zaman\" dediler. İyi bilin ki ALLAH’ın yardımı yakındır."},{"n":215,"t":"Nasıl yardım edeceklerini soruyorlar sana. De ki: \"Para ve mal yardımlarınızı ana-babaya, yakınlara, öksüzlere, yoksullara ve yolda kalmışlara yapmalısınız.\" İşlediğiniz her iyiliği ALLAH bilir."},{"n":216,"t":"Sevmediğiniz halde savaş size zorunlu kılındı. Sevmediğiniz bir şey sizin için iyi ve sevdiğiniz bir şey de sizin için kötü olabilir. Siz bilmeseniz de ALLAH bilir."},{"n":217,"t":"Sana, Sınırlanmış Ayda savaşmak konusunu da soruyorlar. De ki: \"Onda savaş büyük bir günahtır. Fakat ALLAH’ın yolundan çevirmek, O’na ve Sınırlanmış Mescid’e nankörlük etmek ve halkını oradan çıkarmak ALLAH yanında daha büyük bir günahtır. Çünkü kargaşa ve zulüm, öldürmekten daha büyük bir suçtur.\" Güçleri yetse sizi dininizden döndürünceye kadar sizinle savaşırlar. Sizden kim dininden döner ve inkârcı olarak ölürse, tüm yaptıkları dünyada ve ahirette boşa çıkar. Onlar ateş halkıdır ve orada sürekli kalıcıdırlar."},{"n":218,"t":"Gerçeği onaylayanlar, ALLAH yolunda göç edenler ve çaba harcayanlar ALLAH’ın rahmetini umar. ALLAH Bağışlayandır, Rahimdir."},{"n":219,"t":"Sana sarhoş edicilerden ve kumardan sorarlar: \"O ikisinde büyük bir günah ve insanlar için yararlar var; ancak günahları yararlarından daha büyüktür\" de. Ayrıca, sadaka olarak neyi vereceklerini senden sorarlar: \"artanı\" de. ALLAH ayetlerini işte böyle açıklıyor ki düşünesiniz…"},{"n":220,"t":"Bu dünya ve ahiret hakkında… Sana bir de öksüzler hakkında sorarlar: De ki: \"Onları erdemli kişiler olarak yetiştirmeniz en büyük iyiliktir. Mallarını mallarınıza katarsanız aile bireyiniz olurlar.\" ALLAH bozanı düzeltenden ayırt etmesini bilir. ALLAH dileseydi sizi zora sokardı. ALLAH Güçlüdür, Bilgedir."},{"n":221,"t":"Gerçeği onaylamadıkça, ortak koşan kadınlarla evlenmeyin. Gerçeği onaylayan bir hizmetçi kadın ortak koşan bir kadından daha hayırlıdır; ondan hoşlansanız bile. Ortak koşan erkeklerle de gerçekleri onaylayıncaya kadar evlenmeyin. Gerçeği onaylayan bir hizmetçi erkek ortak koşandan daha hayırlıdır, hoşlansanız bile… Onlar, ateşe çağırıyor. ALLAH ise bahçeye ve bağışlanmaya çağırır ve öğüt almaları için ayetlerini halka açıklar."},{"n":222,"t":"Sana aybaşı halini sorarlar: De ki: \"O bir rahatsızlıktır. Aybaşı halinde olan kadınlarla cinsel ilişkiye girmeyin ve ondan kurtuluncaya kadar onlara yaklaşmayın. Kurtuldukları zaman ALLAH’ın size uygun gördüğü yerden onlarla cinsel ilişkide bulunun. ALLAH yönelenleri sever, arınanları sever.\""},{"n":223,"t":"Kadınlarınız, tohum ektiğiniz tarlalarınızdır. Tarlanıza dilediğiniz gibi varın. Kendiniz için geleceğe hazırlanın. ALLAH’ı dinleyin ve onunla mutlaka karşılaşacağınızı bilin. Gerçeği onaylayanlara müjde ver."},{"n":224,"t":"Halk arasında iyi, erdemli ve dürüst görünmek için ALLAH’ı yeminlerinize alet etmeyin. ALLAH İşitir, Bilir."},{"n":225,"t":"ALLAH yaptığınız kasıtsız yeminlerinizden sizi sorumlu tutmaz; ancak kalbinizdeki gerçek niyetinizden sorumlu tutar. ALLAH Bağışlayandır, Şefkatlidir."},{"n":226,"t":"Kadınlarını boşamayı tasarlayanlar dört ay beklemeli. Vazgeçip uzlaşırlarsa ALLAH Bağışlayandır, Rahim’dir."},{"n":227,"t":"Boşamaya kararlıysalar, ALLAH İşiten ve Bilendir."},{"n":228,"t":"Boşanan kadınlar kendi kendilerine üç aybaşı beklemeli. ALLAH’a ve ahiret gününü onaylıyorlarsa ALLAH’ın rahimlerinde yarattığını gizlemeleri uygun olmaz. Bu durumda kocaları barışmak isterlerse onları geri almaya daha fazla hak sahibidirler. Erkeklerin kadınlar üzerindeki hakları gibi, kadınların da erkekler üzerinde eşit hakları vardır. (Gebelik durumunda) Erkeklerin onların üzerinde bir derecesi vardır. ALLAH Güçlüdür, Bilgedir."},{"n":229,"t":"Boşama iki defadır. Boşanmış kadınları ya iyilikle barındırmak ya da iyilikle bırakmak gerekir. Onlara vermiş bulunduğunuz şeyleri geri almanız size helal olmaz; eşler ALLAH’ın sınırını gözetememekten korkarlarsa başka. ALLAH’ın sınırlarını gözetememekten korkarsanız, o zaman kadının isteyerek geri verdiği şeylerden dolayı günaha girmezler. Bunlar ALLAH’ın sınırlarıdır; onları çiğnemeyin. ALLAH’ın sınırlarını kimler çiğnerse işte zalimler onlardır."},{"n":230,"t":"Kadını yine (üçüncü kez) boşarsa, kadın başka birisiyle evlenmedikçe ona bundan sonra helal olmaz. Öteki adam da kadını boşarsa, ALLAH’ın yasasını gözeteceklerine inanırlarsa tekrar birbirlerine dönmelerinde bir sakınca yoktur. Bu ALLAH’ın yasasıdır; onu bilen bir toplum için açıkladık."},{"n":231,"t":"Kadınları boşadığınız zaman, bekleme sürelerini (üç aybaşını) bitirdiler mi onları ya iyilikle yanınızda tutun veya iyilikle bırakın. İntikam almak için onlara zarar verecek şekilde tutmayın. Bunu yapan kendisine zulmetmiş olur. ALLAH’ın ayetlerini hafife almayın. ALLAH’ın size verdiği nimetlerini ve size öğüt vermek için size indirdiği kitabı ve hikmeti düşünün. ALLAH’ı dinleyin ve bilin ki ALLAH her şeyi Bilir."},{"n":232,"t":"Boşanan kadınlar bekleme sürelerini bitirdikten sonra, kocalarıyla güzellikle anlaştıkları taktirde o kadınların tekrar evlenmelerine engel olmayın. İçinizden ALLAH’a ve ahiret gününü onaylayan kimseler bundan öğüt alır. Bu sizin için daha arı ve daha sağlıklıdır. Siz bilmeseniz de ALLAH bilir."},{"n":233,"t":"Emzirme süresini tamamlamak isteyenler için analar bebeklerini tam iki yıl emzirmeli. Ananın yiyecek ve giyecek ihtiyacını ise çocuğun babası güzel ve uygun bir şekilde karşılamalı. Kimse kapasitesinin üzerinde sorumlu tutulamaz. Ne anne çocuğu yüzünden, ne de babası çocuğu yüzünden zarara sokulmasın. Bunu gerçekleştirmek mirasçısının da görevidir. Ana ve baba danışıp anlaştıktan sonra sütten kesmek isterse, ikisine de bir günah yoktur. Çocuklarınızı sütanneye emzirtmek isterseniz ücretini uygun bir biçimde ödediğiniz sürece size bir sorumluluk yoktur. ALLAH’ı dinleyin, ALLAH yaptıklarınızı Görür."},{"n":234,"t":"İçinizden ölen erkeklerin geride bıraktığı eşleri, dört ay ve on beklerler. Sürelerini doldurunca artık kendileri için uygun olanı yapmalarında size sorumluluk yoktur. ALLAH yaptıklarınızdan Haberlidir."},{"n":235,"t":"Evlenme önerilerinizi o kadınlara bildirmenizden, ya da bu niyetinizi içinizde tutmanızdan dolayı size bir günah yoktur. ALLAH onlar hakkında düşüneceğinizi bilir. Onlarla uygun ve erdemli bir şekilde konuşma amacının dışında gizlice sözleşip buluşmayın. Bekleme süreleri dolmadan onlarla nikah bağını kurmaya kalkışmayın. Bilin ki ALLAH içinizde olanı bilir; öyleyse O’ndan çekinin. Yine bilin ki ALLAH Bağışlayandır, Şefkatlidir."},{"n":236,"t":"Henüz dokunmadan, yahut mehirlerini biçmeden önce kadınları boşamanızda bir sakınca yok. Bu durumda ödemede bulunun. Zengin, kendi gücü oranında, yoksul da kendi gücü oranında verdikleri zarara uygun bir tazminat vermeli. Bu, güzel davrananların görevidir."},{"n":237,"t":"Mehir biçtikten sonra, ancak onlara dokunmadan önce onları boşamışsanız kendilerine söz verdiğiniz mehrin yarısını vermelisiniz. Ancak, kadın hakkından vazgeçerse veya koca mehrin tümünü vermek isterse başka… Vazgeçmeniz daha erdemli bir davranıştır. Aranızdaki dostluğu unutmayın. ALLAH yaptıklarınızı Görendir."},{"n":238,"t":"Namazlara, özellikle orta namaza dikkat edin. Kendinizi tümüyle ALLAH’a vererek namaza durun."},{"n":239,"t":"Bir kaygı ve endişeniz varsa, yaya veya binmiş olarak (namazı kılın.) Güvene kavuştuğunuz zaman, bilmediğiniz şeyleri size öğrettiği gibi ALLAH’ı anın."},{"n":240,"t":"Ölüp de geriye eşler bırakan erkekleriniz, eşlerinin evlerinden çıkarılmaksızın bir yıl boyunca geçimlerinin sağlanmasını vasiyet etsinler. Çıkarlarsa, kendileri için uygun olanı yapmalarından siz sorumlu değilsiniz. ALLAH Güçlüdür, Bilgedir."},{"n":241,"t":"Boşanmış kadınlar için de uygun bir geçim yardımı yapılmalı. Bu, erdemli kişilerin görevidir."},{"n":242,"t":"Düşünesiniz diye ALLAH ayetlerini böyle açıklar."},{"n":243,"t":"Sayıları binlerce olduğu halde ölüm korkusuyla yurtlarını terk edenler dikkatini çekti mi? ALLAH onlara \"Ölün\" dedi de sonra onları diriltti. ALLAH insanlara lütuf sahibidir; ancak insanların çoğu şükretmez."},{"n":244,"t":"ALLAH yolunda savaşın. Bilesiniz ki ALLAH İşitir, Bilir."},{"n":245,"t":"Kat kat ödenecek güzel bir ödüncü kim ALLAH’a sunar? Kısan da açan da ALLAH’tır. O’na döndürüleceksiniz."},{"n":246,"t":"Şu olay dikkatini çekmedi mi? İsrailoğullarının ileri gelenleri, Musa’dan sonra peygamberlerinden birine, \"Bize bir lider atasan da ALLAH uğrunda savaşsak\" demişlerdi. \"Ya savaş gerekir de savaşmazsanız?!\" demişti. Onlar, \"Yurdumuzdan ve çocuklarımızdan uzaklaştırılmış durumda iken neden ALLAH yolunda savaşmayalım\" diye karşılık vermişlerdi. Fakat kendilerine savaş farzedilince pek azı hariç yüz çevirdiler. ALLAH zalimleri Bilir."},{"n":247,"t":"Peygamberleri onlara, \"ALLAH size lider olarak Talut’u atadı\" dedi. Onlar, \"Biz yönetime ondan daha layık olduğumuz halde nasıl olur da üzerimize buyruk sahibi olabilir? Üstelik zengin biri de değil\" dediler. O da, \"ALLAH onu üzerinize seçti. Onun bilgi ve beden gücünü arttırdı\" dedi. ALLAH mülkünü dilediğine verir. ALLAH Cömerttir, Bilendir."},{"n":248,"t":"Peygamberleri onlara: \"Onun hükümdarlığının kanıtı, sandığın size gelmesidir. Onda Efendinizden bir huzur ve Musa ile Harun’un halkının geriye bıraktığı bir kalıntı bulacaksınız. Onu melekler taşımaktadır. Gerçeği onaylıyorsanız bunda sizi ikna edecek bir delil var.\""},{"n":249,"t":"Talut ordunun kumandasını alınca şunları bildirdi: \"ALLAH sizi bir ırmakla sınayacak. Kim ondan içerse benden değildir. Kim onu tatmayıp sadece eliyle bir yudum alırsa bendendir.\" Pek azı dışında hepsi ondan içti. O, beraberindeki gerçeği onaylayanlarla ırmağı geçince, \"Bugün Calut ve ordusuna karşı koyacak gücümüz yok\" dediler. ALLAH ile karşılaşacaklarını sananlar ise şöyle dediler: \"Sayıca az nice bölük, ALLAH’ın izniyle kalabalık bölükleri yenmiştir. ALLAH sabredenlerle beraberdir.\""},{"n":250,"t":"Calut ve ordusuyla karşılaştıklarında şöyle dediler: \"Efendimiz, bize direnme gücü ver, ayaklarımızı sağlam tut, inkârcılara karşı bize yardım et.\""},{"n":251,"t":"Nihayet ALLAH’ın izniyle onları bozguna uğrattılar. Talut Calut’u öldürdü. ALLAH ona hükümdarlık ve anlayış verdi, ona dilediğini öğretti. ALLAH insanların bir kısmıyla bir kısmını savmasaydı yeryüzü bozulurdu. Fakat ALLAH tüm yaratıklara karşı lütuf sahibidir."},{"n":252,"t":"Bunlar, sana gerçek olarak okuduğumuz ALLAH’ın ayetleridir ve elbette sen elçilerden birisin."},{"n":253,"t":"O elçilerin bazısına diğerlerinden daha fazla lütufta bulunduk.Örneğin, kimileriyle ALLAH konuştu, kimilerini de derecelerle yükseltti. Meryem oğlu İsa’ya apaçık deliller verdik ve onu Kutsal Ruh ile destekledik. ALLAH dileseydi, onların ardından gelenler kendilerine apaçık deliller geldikten sonra birbirleriyle kavga etmezlerdi. Fakat anlaşmazlığa düştüler. Kimisi onayladı, kimisi inkâr etti. ALLAH dileseydi birbirleriyle savaşmazlardı. Fakat, ALLAH dilediğini yapar."},{"n":254,"t":"Gerçeği onaylayanlar, ne alışverişin ne dostluğun ve ne de aracılığın (şefaat) olmadığı gün gelmeden önce size verdiklerimizden dağıtın. İnkar edenler zalimlerdir."},{"n":255,"t":"ALLAH: O’ndan başka tanrı yoktur, Yaşayandır, Sürekli Gözetendir. Kendisini ne dalgınlık ne de uyuklama tutmaz. Göklerde ve yerde ne varsa O’nundur. İzni olmadan kim O’nun katında aracılık edebilir? Onların geçmişini ve geleceğini bilir. Dilediği miktar dışında O’nun bilgisinden hiçbir şeyi kavrayamazlar. Egemenliği gökleri ve yeri kapsamıştır. Onları düzen içinde korumak onu yormaz. O Yücedir, Büyüktür."},{"n":256,"t":"Dinde zorlama yoktur. Artık doğruluk, sapıklıktan ayrılmıştır. Kim ki azgın küstahı inkâr edip ALLAH’ı onaylarsa, kopmaz ve sağlam bir bağa yapışmıştır. ALLAH İşitir, Bilir."},{"n":257,"t":"ALLAH gerçeği onaylayanların egemeni ve dostudur; onları karanlıklardan aydınlığa çıkarır. İnkar edenlerin dostları ise azgın ve küstahlardır; onları aydınlıktan karanlığa çıkarırlar. Onlar ateş halkıdır, onlar orada sürekli kalıcıdır."},{"n":258,"t":"ALLAH kendisine hükümdarlık verdiği halde, İbrahim ile Efendisi hakkında tartışan dikkatini çekmedi mi? İbrahim, \"Benim Efendim O’dur ki yaşatır ve öldürür\" deyince, \"Ben de yaşatır ve öldürürüm\" demişti. İbrahim, \"ALLAH güneşi doğudan getiriyor. Sen de batıdan getirsene\" deyince inkârcı adam şaşırıp kalmıştı. ALLAH zalim toplumu doğruya iletmez."},{"n":259,"t":"Yahut şu kimse gibisi de… Altı üstüne gelmiş yıkıntı bir kasabaya uğrar ve \"ALLAH bunu ölümünden sonra nasıl diriltebilir\" der. Bunun üzerine ALLAH onu yüz sene ölü bıraktıktan sonra diriltti. \"Burada ne kadar kaldın\" dedi. \"Birgün yahut günün bir parçası kadar kaldım\" dedi. \"Hayır, sen yüz yıl kaldın. Yiyeceğine ve içeceğine bak hâlâ bozulmamış. Eşeğine de bak. Seni halk için bir delil yaptık. Kemiklere dikkat et, onları nasıl üstüste koyuyor, sonra onlara nasıl da et giydiriyoruz.\" Durum kendisine aydınlanınca, \"Artık ALLAH’ın her şeye gücü yettiğini biliyorum\" dedi."},{"n":260,"t":"İbrahim, \"Efendim, ölüleri nasıl dirilttiğini bana göster\" demişti. \"Yoksa onaylamıyor musun\" dedi. \"Elbette; ancak kalbimi güçlendirmesi için\" dedi. \"Dört kuş al ve onları iyice incele. Sonra her bir dağın üzerine onlardan bir parça yerleştir. Daha sonra onları çağır. Sana hemen gelecekler. Bilesin ki ALLAH Güçlüdür, Bilgedir\" dedi."},{"n":261,"t":"Paralarını ALLAH yolunda harcayanların örneği, her birinde yüz tane olmak üzere yedi başak veren tanenin durumuna benzer. ALLAH dileyene katlayarak verir. ALLAH Cömerttir, Bilendir."},{"n":262,"t":"Paralarını ALLAH yolunda harcadıktan sonra iyiliklerini başa kakıp eziyet etmeyenler için Rab’leri katında ödülleri vardır. Onlara korku ve üzüntü yok."},{"n":263,"t":"Güzel bir söz ve hoşgörü, peşinden onur kırıcı davranışlar getiren bir yardımdan daha hayırlıdır. ALLAH Zengindir, Şefkatlidir."},{"n":264,"t":"Gerçeği onaylayanlar! ALLAH’ı ve ahiret gününü onaylamadığı halde halka gösteriş için yardımda bulunan kişi gibi yardımlarınızı başa kakmakla ve eziyet etmekle boşa çıkarmayın. Bu tip davranışın örneği, üzerinde toz toprak biriken bir kayaya benzer ki şiddetli bir sağanak onu çıplak bırakır. Yaptıklarından hiçbir şey kazanamazlar. ALLAH inkârcı toplumu doğruya iletmez."},{"n":265,"t":"ALLAH’ın rızasını kazanmak istedikleri ve buna ikna oldukları için paralarını harcayanların örneği, bol yağmur aldığında iki kat ürün veren, bol yağmur almasa bile çisentiyle yetinen yüksek verimli bir bahçe örneği gibidir. ALLAH yaptıklarınızı görmektedir."},{"n":266,"t":"Biriniz ister mi ki, altından ırmaklar akan, her çeşit meyveyi içeren hurma ve üzüm bahçelerine ve küçük çocuklara sahip olsun da, kendisine yaşlılık, bahçesine de ateşli bir kasırga vursun yakıp kül etsin. Düşünmeniz için ALLAH size ayetlerini böyle açıklar."},{"n":267,"t":"Gerçeği onaylayanlar, kazandıklarınızdan ve sizin için yerden çıkardığımız nimetlerden yardım olarak verin. Size verilse, ancak gözünüz kapalı olarak kabul edebileceğiniz kötü mallarınızı yardım olarak vermeye kalkmayın. Bilin ki ALLAH Zengindir, Övgüye layıktır."},{"n":268,"t":"Sapkın size fakirliği söz verir ve kötülüğü emreder. ALLAH ise kendi tarafından sizin için bağışlama ve lütuf söz verir. ALLAH Cömerttir, Bilendir."},{"n":269,"t":"Bilgeliği dilediğine verir. Kime bilgelik verilmişse ona çok büyük iyilik yapılmıştır. Düşünce sahiplerinden başkası öğüt almaz."},{"n":270,"t":"ALLAH ettiğiniz her ekonomik yardımı, adadığınız her adağı bilir. Zalimlerin yardımcısı yoktur."},{"n":271,"t":"Yardımlarınızı açıklasanız, ne güzel. Ancak onları gizleyerek muhtaçlara verseniz daha iyidir ve bu bazı günahlarınızı örter. ALLAH yaptığınızı haber alır."},{"n":272,"t":"Onları doğruya iletmek sana düşmez. Ancak ALLAH dilediğini doğruya iletir. Muhtaçlara ettiğiniz her iyilik kendi yararınızadır. Yardımlarınız yalnız ALLAH için olmalı. Yaptığınız her iyiliğin karşılığı size eksiksiz ödenecektir. Haksızlığa uğratılmayacaksınız."},{"n":273,"t":"ALLAH yolundaki çalışmasından ötürü özgürlükleri kısıtlanarak göç etme imkanından yoksun bırakılmış ihtiyaç sahiplerine verin. Onları tanımayanlar, onurlu tavırlarından ötürü onları zengin sanır. Onları yüzlerinden tanırsın. Halktan yardım dilenmezler. Ettiğiniz her iyiliği ALLAH bilir."},{"n":274,"t":"Paralarını gece ve gündüz gizli ve açık yardım için verenlerin ödülü Rab’lerinin yanındadır. Onlara korku yoktur ve onlar üzülmezler."},{"n":275,"t":"Tefecilikle para yiyenler, sapkının çarptığı kimse gibi ayağa kalkarlar. Bu, onların, \"Tefecilik alışveriş gibidir\" demelerinden ötürüdür. Halbuki ALLAH alışverişi helal, tefeciliği ise haram kıldı. Kime Efendisinden bir öğüt gelir de vazgeçerse, geçmişte kazandıklarını tutabilir; işi de ALLAH’a kalmıştır. Devam edenler ise cehennem halkıdır ve orada sürekli kalırlar."},{"n":276,"t":"ALLAH tefeciliği mahkûm eder, karşılıksız yardımı destekler. ALLAH hiçbir günahkar nankörü sevmez."},{"n":277,"t":"Gerçeği onaylayıp erdemli bir hayat sürerek namazı gözetenlerin ve zekatı verenlerin ödülleri Rab’leri katındadır. Onlar için korku yoktur ve onlar üzülmezler."},{"n":278,"t":"Ey gerçeği onaylayanlar, gerçekten Gerçeği onaylıyorsanız ALLAH’ı dinleyin ve her çeşit tefecilik kalıntısını terk edin."},{"n":279,"t":"Böyle yapmazsanız ALLAH’tan ve elçisinden bir savaş bekleyin. Tövbe ederseniz anaparanız yine sizindir. Ne haksızlık edin ne de haksızlığa uğrayın."},{"n":280,"t":"Borçlu darlık içinde ise, bir kolaylığa çıkıncaya kadar beklemek gerekir. Borcu karşılıksız yardım olarak bağışlarsanız sizin için daha iyidir, bir bilseniz."},{"n":281,"t":"ALLAH’a döndürüleceğiniz günden sakının. Herkese kazandığının karşılığı haksızlık edilmeden ödenecek."},{"n":282,"t":"Gerçeği onaylayanlar! Belirli bir süre için birbirinize borç verdiğiniz zaman onu yazın. Sizden bir yazıcı onu adaletle yazsın. Yazıcı, ALLAH’ın kendisine öğrettiği gibi yazmaktan kaçınmasın, yazsın. Borçlanan kişi de dikte ettirsin. Efendisi olan ALLAH’tan korksun, onda sahtekârlık yapmasın. Borçlanan kişi aklı ermez veya çaresiz, ya da dikte etmekten aciz ise velisi adaletle yazdırmalı. Erkeklerinizden iki şahit de tanıklık etsin. İki erkek şahit bulamazsanız dilediğiniz şahitlerden bir erkek ve iki kadın seçiniz ki kadınlardan biri yanıldığında diğeri ona hatırlatsın. Şahitler, çağrıldıkları vakit çekinmesin. Az olsun, çok olsun, ödeme tarihi ile birlikte onu yazmaktan üşenmeyin. Bu, ALLAH katında daha adaletli, tanıklık açısından daha sağlam ve kuşkulanmamanız için daha uygundur. Yalnız, ticaret peşin olursa onu yazmamanızda bir sakınca yok. Alışveriş yaptığınızda tanıklarınız bulunsun. Yazana da tanığa da zarar verilmesin. Aksi halde kendinize kötülük edersiniz. ALLAH’ı dinleyin. ALLAH size öğretiyor. ALLAH her şeyi bilir."},{"n":283,"t":"Yolculukta olup bir yazıcı bulamasanız, ödemeyi garantileyecek bir senet veya makbuz gönderin. Birbirinize bu şekilde güvenirseniz, senedin sahibi ödemeyi zamanında yapsın ve Efendisi olan ALLAH’ı saysın. Tanıklığı gizlemeyin. Kim gizlerse kalbi günahkardır. ALLAH tüm yaptıklarınızı bilir."},{"n":284,"t":"Yerde ve göklerde olanlar ALLAH’ındır. İçinizdekini açıklasanız da gizleseniz de ALLAH sizi ondan sorumlu tutar. Dilediğini bağışlar, dilediğini cezalandırır. ALLAH her şeye gücü yetendir."},{"n":285,"t":"Elçi, Efendisinden kendisine indirileni onayladı, gerçeği onaylayanlar da… Hepsi, ALLAH’ı, meleklerini, kitaplarını ve elçilerini onaylarlar: \"Elçilerinin hiçbirisi arasında ayrım yapmayız.\" Derler ki: \"İşittik ve uyduk. Efendimiz bizi bağışla; dönüş sanadır.\""},{"n":286,"t":"ALLAH kişiye ancak kapasitesi kadar yükler. Herkesin kazandığı iyilik kendi yararına, kazandığı kötülükse kendi zararınadır. \"Efendimiz, unutur yahut yanılırsak bizi sorumlu tutma! Efendimiz, bizden öncekilere yüklediğin gibi bize ağır sorumluluk yükleme! Efendimiz, gücümüzün yetmeyeceği şeyleri bize yükleme! Bizi hoşgör, bizi bağışla ve bize acı! Sensin bizim efendimiz/egemenimiz (mevlana). İnkarcılar topluluğuna karşı bize yardım et!\""}]},{"id":3,"name":"Âl-i İmrân Suresi","verses":[{"n":1,"t":"A. L. M."},{"n":2,"t":"ALLAH: O’ndan başka tanrı yoktur; Diridir, Gözetendir."},{"n":3,"t":"Sana bu kitabı, kendisinden öncekileri onaylayıcı olarak gerçekle indirdi. Tevrat’ı ve İncil’i de indirdi,"},{"n":4,"t":"Bundan önce insanlara yol gösterici olarak… Yasalar kitabını indirdi. ALLAH’ın ayetlerini inkâr edenlere çetin bir azap vardır. ALLAH Üstündür, Öç Alandır."},{"n":5,"t":"Yerde ve gökte hiçbir şey ALLAH’a gizli kalmaz."},{"n":6,"t":"Rahimlerde size dilediği şekilde biçim veren O’dur. O’ndan başka tanrı yoktur; Üstündür, Bilgedir."},{"n":7,"t":"O ki sana bu kitabı indirdi. Onun bazı ayetleri kesin anlamlıdır (muhkem), ki bunlar kitabın özüdür. Diğerleri de benzer anlamlıdır (müteşabih). Kalplerinde hastalık bulunanlar, insanları şaşırtmak ve farklı anlam vermek için benzer anlamlı olanlarının ardına düşerler. Onların tevilini yalnızca ALLAH bilir. İlim sahipleri de. \"Hepsi Efendimiz katındandır, hepsini onayladık.\" derler. Akıl ve anlayış sahiplerinden başkası öğüt almaz."},{"n":8,"t":"\"Efendimiz, bizi doğruya ulaştırdıktan sonra kalplerimizin eğrilmesine izin verme. Üzerimize rahmetini yağdır; kuşkusuz sen Bağışta Bulunansın.\""},{"n":9,"t":"\"Efendimiz, gerçekleşmesi kuşku götürmeyen günde insanları toplayacak olan sensin.\" ALLAH sözünden dönmez."},{"n":10,"t":"İnkârcıların ne paraları ne de çocukları ALLAH’a karşı hiçbir yarar sağlamaz. Onlar ateşin yakıtıdır."},{"n":11,"t":"Firavunun halkı veya onlardan öncekilerin durumu gibi… Ayetlerimizi (vahiy ve mucizelerimizi) yalanladılar ve ALLAH da onları suçüstü yakaladı. ALLAH’ın cezalandırması şiddetlidir."},{"n":12,"t":"İnkârcılara şunu söyle: \"Yenilecek ve cehenneme sürüleceksiniz.\" Ne kötü bir konuttur."},{"n":13,"t":"Karşılaşan iki orduda sizin için bir ders var. Ordulardan birisi ALLAH yolunda savaşırken diğeri de inkârcı idi. Onları gözleriyle kendilerinin iki katı olarak görüyorlardı. ALLAH dilediğini zaferle destekler. Bunda görüş sahipleri için bir ibret vardır."},{"n":14,"t":"Kadınları, çocukları, yığınlarla altın ve gümüşü, eğitilmiş atları, davarları ve ekinleri sevmek gibi zevkler insanlara alımlı görünür. Bunlar dünya hayatının nimetleridir. Oysa gidilecek en güzel yer ALLAH katındadır."},{"n":15,"t":"De ki: \"Bundan daha iyisini size haber vereyim mi? Erdemliler için Rab’lerinin yanında altlarından ırmaklar akan, içinde sonsuz kalacakları bahçeler, tertemiz eşler ve ALLAH’ın onayını kazanmaktan dolayı mutluluk vardır.\" ALLAH kulları görür."},{"n":16,"t":"Onlar ki: \"Efendimiz, biz onayladık, günahlarımızı bağışla ve bizi cehennem azabından koru\" derler."},{"n":17,"t":"Onlar, sabredenlerdir, doğru sözlülerdir, gönülden teslim olanlardır, insanlara yardım edenler ve seherlerde/gönülden bağışlanma dileyenlerdir."},{"n":18,"t":"ALLAH, kendisinden başka tanrı olmadığına şehadet eder; melekler ve adaleti gözeten ilim sahipleri de… O’ndan başka tanrı yoktur. Üstündür, Bilgedir."},{"n":19,"t":"ALLAH tarafından onaylanan biricik din, barış içinde teslim olmak (İslam) tır. Kitap verilmiş olanlar, kendilerine bilgi geldikten sonra sırf aralarındaki kıskançlık yüzünden anlaşmazlığa düştüler. ALLAH’ın ayetlerini inkâr edenler için ALLAH hesabı çabuk görür."},{"n":20,"t":"Seninle tartışırlarsa, \"Ben ve beni izleyenler kendimizi ALLAH’a teslim ettik\" de. Kitap verilenlere ve kitap verilmeyenlere (ümmilere), \"Teslim oldunuz mu\" de. Teslim olurlarsa, doğruyu bulurlar. Yüz çevirirlerse, görevin sadece duyurmaktır. ALLAH kulları görür."},{"n":21,"t":"ALLAH’ın ayetlerini inkâr edenlere, haksız yere peygamberleri öldürenlere ve halkın arasında adaleti savunanları öldürenlere acıklı bir azabı müjdele."},{"n":22,"t":"Onlar, dünya ve ahirette yaptıkları boşa çıkanlardır. Onlara yardım eden de olmayacak."},{"n":23,"t":"Kitaptan kendilerine bir pay verilmiş olanlara baksana, aralarında hükmetmeleri için ALLAH’ın kitabına çağrılıyorlar da onlardan bir grup yüz çevirip geri dönüyor."},{"n":24,"t":"Çünkü onlar, \"Cehennem sayılı birkaç günün dışında bize dokunmayacak\" dediler. Uydurdukları şeyler onları dinlerinde böylece yanıltmıştır."},{"n":25,"t":"Herkese kazandığının karşılığı haksızlık yapılmadan ödeneceği, gerçekleşmesinde kuşku olmayan o gün için onları topladığımızda halleri nice olacak?"},{"n":26,"t":"De ki: \"Yöneticilerin Yöneticisi olan Tanrım, yönetimi dilediğine verir, dilediğini de yönetimden indirirsin. Dilediğini yükseltir, dilediğini de alçaltırsın. Tüm iyilikler senin elinde. Sen her şeye gücü yetensin!\""},{"n":27,"t":"\"Geceyi gündüze katarsın, gündüzü de geceye katarsın. Diriyi ölüden çıkarırsın, ölüyü de diriden çıkarırsın. Dilediğini hesapsız rızıklandırırsın.\""},{"n":28,"t":"Gerçeği onaylayanlar, gerçeği onaylayanları bırakıp inkârcıları dost edinmesin. Kim bunu yaparsa ALLAH ile bir ilgisi kalmaz. Ancak onlardan korkmanız hali başka… ALLAH kendisi hakkında sizi uyarıyor. Dönüş ALLAH’adır."},{"n":29,"t":"De ki: \"İçinizdeki düşüncelerinizi ister gizleyin, ister açıklayın, ALLAH bilir.\" Göklerde ve yerde olan her şeyi bilir. ALLAH’ın gücü her şeye yeter."},{"n":30,"t":"Gün gelecek, her kişi yaptığı her iyiliği önünde hazır bulacaktır. İşlediği her kötülük ile kendisi arasında uzun bir mesafe olmasını isteyecek. ALLAH kendisi hakkında sizi uyarıyor. ALLAH kullara şefkatlidir."},{"n":31,"t":"De ki: \" ALLAH’ı seviyorsanız beni izleyin ki ALLAH da sizi sevsin ve günahlarınızı bağışlasın. ALLAH Bağışlayandır, Rahimdir.\""},{"n":32,"t":"\"ALLAH’a ve elçiye itaat edin\" de. Yüz çevirirlerse, elbette ALLAH inkârcıları sevmez."},{"n":33,"t":"ALLAH Adem’i, Nuh’u, İbrahim ailesini ve İmran ailesini halkların arasından seçti."},{"n":34,"t":"Birbirlerinin soyundan olarak… ALLAH İşitir, Bilir."},{"n":35,"t":"İmran’ın karısı demişti ki: \"Efendim, karnımdakini tamamıyla sana adadım, adağımı kabul buyur. Sen İşitensin, Bilensin.\""},{"n":36,"t":"Onu doğurunca, \"Efendim, onu kız doğurdum\" dedi – ALLAH onun ne doğuracağını biliyordu– \"Erkek kız gibi değil. Ona Meryem adını verdim. Onu ve soyunu, kovulmuş sapkından koruman için sana yalvarırım.\""},{"n":37,"t":"Efendisi, adağını güzel bir şekilde kabul etti ve onu Zekeriya’nın himayesinde güzel bir çiçek gibi yetiştirdi. Zekeriya, odanın köşesinde onun yanına her girişinde yanında yiyecekler bulurdu. \"Meryem, bunlar sana nereden geliyor\" diye sorduğunda, \"Bu, ALLAH katındandır. ALLAH dilediğine hesapsız rızık verir\" derdi."},{"n":38,"t":"Zekeriya oracıkta Efendisine dua etti: \"Efendim\" dedi, \"katından bana tertemiz bir soy ver, Sen duaları işitensin.\""},{"n":39,"t":"Tapınakta durmuş namaz kılıyorken melekler ona, \"ALLAH seni, ALLAH’ın Sözünü doğrulayacak, onurlu, iffetli ve erdemli bir peygamber olan Yahya ile müjdeliyor\" diye seslendiler."},{"n":40,"t":"\"Efendim, ben yaşlı ve karım kısırken nasıl olur da bir oğlum olur\" deyince, o, \"Evet; ama ALLAH dilediğini yapar\" dedi."},{"n":41,"t":"\"Efendim, bana bir alamet ver\" dedi. \"Alametin, üç gün işaretle anlaşmanın dışında halk ile konuşmamandır. Efendini çokça an, akşam sabah O’nu düşün,\" dedi."},{"n":42,"t":"Denetçiler şöyle demişti: \"Meryem, ALLAH seni seçip arındırdı; seni tüm kadınların üzerine seçti."},{"n":43,"t":"\"Meryem, Efendine teslim ol, secdeye kapan, eğilenlerle birlikte eğil.\""},{"n":44,"t":"Bunlar, sana vahyettiğimiz metafizik haberlerindendir. Meryem’e hangisi kefil olacak diye kura çekerlerken sen onların yanında değildin; çekiştikleri zaman da sen onların yanında değildin."},{"n":45,"t":"Denetçiler demişti ki: \"Meryem, ALLAH seni kendisinden bir Söz ile müjdeliyor. Onun adı Meryem oğlu İsa Mesih’tir. Dünyada da ahirette de önderlerdendir ve yakın olanlardandır."},{"n":46,"t":"\"Beşikteyken de büyüyünce de insanlarla konuşacak ve iyilerden olacak.\""},{"n":47,"t":"\"Efendim! Bana bir beşer dokunmamışken nasıl olur da çocuğum olur\" deyince, şöyle cevap verdi: \"ALLAH dilediğini böyle yaratır. Herhangi bir şeyin olmasını dilediği an ona ‘Ol’ der ve o şey oluverir."},{"n":48,"t":"\"Ona kitabı, bilgeliği, Tevrat’ı ve İncil’i öğretecek."},{"n":49,"t":"\"İsrailoğullarına gönderilen bir elçi olarak: ‘Ben size, Efendinizden bir kanıt ile geldim. Size balçıktan kuş heykeli yapıp ona üflerim ve ALLAH’ın izniyle bir kuş oluverir. ALLAH’ın izniyle körü ve cüzzamlıyı iyileştirir, ölüyü diriltirim. Ne yediğinizi ve evlerinizde neler biriktirdiğinizi size bildirebilirim. Onaylayacaksanız bu kanıtlar sizin için yeterlidir."},{"n":50,"t":"\"Benden önceki Tevrat’ı doğrulamak ve size haram edilen bazı şeyleri helal etmek için gönderildim. Size Efendinizden bir kanıt getirdim. ALLAH’ı dinleyin ve beni izleyin."},{"n":51,"t":"\"ALLAH benim de Efendim, sizin de Efendiniz; O’na hizmet edin. Budur doğru yol.\""},{"n":52,"t":"İsa onlardan inkârcı bir tavır sezince, \"ALLAH yolunda kim bana yardımcı olacak\" dedi. Öğrencileri, \"Biz ALLAH’ın yardımcılarıyız; ALLAH’ı onayladık. Müslüman oluşumuza tanık ol\" diye karşılık verdiler."},{"n":53,"t":"\"Efendimiz, indirdiğini onayladık ve elçiye uyduk, bizi tanıklar listesine yaz!\""},{"n":54,"t":"Tuzak kurdular, ALLAH da tuzak kurdu. ALLAH tuzak kuranların en iyisidir."},{"n":55,"t":"ALLAH İsa’ya şöyle demişti: \"Senin dünyadaki hayatına son vereceğim ve kendime yükselteceğim. Seni inkâr edenlerden kurtaracağım ve sana uyanları Diriliş Günü’ne kadar inkâr edenlerin üzerinde tutacağım. Sonra, dönüşünüz banadır ve anlaşmazlığa düştüğünüz konularda aranızda ben hüküm vereceğim.\""},{"n":56,"t":"\"Kâfirleri ise dünyada ve ahirette şiddetli bir şekilde cezalandıracağım; yardımcıları da olmayacak.\""},{"n":57,"t":"Gerçeği onaylayıp erdemli bir hayat sürenlere gelince, ödülleri tam olarak ödenecek. ALLAH zalimleri sevmez."},{"n":58,"t":"Sana bu okuduklarımız, ayetlerden ve hikmetli mesajdandır."},{"n":59,"t":"ALLAH’a göre İsa’nın örneği, Adem’in örneği gibidir; topraktan biçimlendirdikten sonra ona \"Ol\" dedi ve o da oldu."},{"n":60,"t":"Bu, Efendinden gelen gerçektir; kuşkulananlardan olma."},{"n":61,"t":"Sana gelen bu bilgiden sonra her kim bu konuda seninle tartışırsa, de ki: \"Gelin, çocuklarımızı, çocuklarınızı, kadınlarımızı, kadınlarınızı çağırarak bizlerle sizler bir araya gelelim ve sonra ALLAH’ın lanetinin yalancıların üzerine olması için lanetleşelim."},{"n":62,"t":"İşte, söylentilerin gerçeği bu. ALLAH’tan başka hiçbir tanrı yoktur ve elbette ALLAH Güçlüdür, Bilgedir."},{"n":63,"t":"Yüz çevirirlerse, elbette ALLAH bozguncuları bilir."},{"n":64,"t":"De ki: \"Kitaplılar! Bizimle sizin aranızda aynı olan bir ilkeye geliniz: ALLAH’tan başkasına hizmet etmeyelim ve O’na hiçbir şeyi ortak koşmayalım, birimiz diğerini ALLAH’tan sonra Efendiler edinmesin.\" Kabul etmezlerse, \"Şahit olun, biz Müslümanlarız!\" deyin."},{"n":65,"t":"Ey kitap halkı, neden İbrahim hakkında tartışıp duruyorsunuz? Oysa İncil de Tevrat da ondan sonra indirildi. Aklınızı kullanmaz mısınız?"},{"n":66,"t":"Bilgi sahibi olduğunuz konularda tartışıp duruyorsunuz! Peki hakkında hiçbir bilgiye sahip olamadığınız bir konuda nasıl tartışabiliyorsunuz? Siz bilmeyebilirsiniz; ama ALLAH bilir."},{"n":67,"t":"İbrahim ne Yahudi idi ne de Hıristiyan; tektanrıcı bir Müslümandı. Hiçbir zaman ortak koşanlardan olmadı."},{"n":68,"t":"İnsanların İbrahim’e en yakın olanları, onu izleyenler, bu peygamber ve gerçeği onaylayanlardır. ALLAH gerçeği onaylayanların egemeni ve dostudur."},{"n":69,"t":"Kitap halkından bir grup sizi saptırmak ister. Onlar sadece kendilerini saptırıyor. Farkında bile değiller."},{"n":70,"t":"Kitap halkı! Tanık olduğunuz halde neden ALLAH’ın ayetlerini inkâr ediyorsunuz?"},{"n":71,"t":"Kitap halkı! Neden doğru ile yanlışı birbirine karıştırıyor ve bile bile gerçeği gizliyorsunuz?"},{"n":72,"t":"Kitap halkından bir grup dedi ki: \"Gerçeği onaylayanlara indirilmiş olana gündüzün başında onaylayın ve sonunda inkâr edin. Böylece belki dinlerinden dönerler.\""},{"n":73,"t":"\"Sizin dininize uyandan başkasını onaylamayın.\" Sen de onlara, \"Hidayet ALLAH’ın hidayetidir\" de. \"Size verilenin benzerinin bir başkasına verildiğini de onaylamayın; yoksa Efendiniz hakkında sizinle tartışma hakkı kazanırlar\" derlerse, \"Lütuf ALLAH’ın elindedir, dilediğine verir\" de. ALLAH Cömerttir, Bilendir."},{"n":74,"t":"Rahmetini dilediğine özgü kılar. ALLAH Büyük Lütuf Sahibidir."},{"n":75,"t":"Kitap halkından öylesi var ki kendisine yığınla emanet bıraksan sana aynen öder. Fakat onlardan öylesi de var ki kendisine bir dinar emanet etsen, başına dikilip durmadıkça geri ödemez. \"Ümmilere karşı bizim bir sorumluluğumuz yok\" dedikleri için böyle davranıyorlar ve bile bile yalanlarını ALLAH’a yakıştırıyorlar."},{"n":76,"t":"Kim sözünü yerine getirir ve erdemli bir yaşam sürerse, bilsin ki ALLAH erdemlileri sever."},{"n":77,"t":"ALLAH’a verdikleri sözü ve yeminlerini az bir fiyata değişenlerin ahirette bir payları yoktur. ALLAH onlarla konuşmaz, Diriliş Günü’nde onlara bakmaz ve onları arındırmaz. Onlar için acıklı bir azap var."},{"n":78,"t":"Onların bazısı, kitapta olmayanı kitaptan sanasınız diye dillerini bükerek kitaba benzetmeye çalışır ve ALLAH katından olmadığı halde, \"Bu ALLAH katındandır\" derler. Bile bile, ALLAH adına yalan söylerler."},{"n":79,"t":"ALLAH’ın kendisine kitap, bilgelik ve peygamberlik verdiği hiçbir insan, \"ALLAH’tan sonra bana da hizmet ediniz\" diye halkı kendisine çağırmaz. Aksine, \"Öğrenip öğrettiğiniz kitap gereğince kendisini Efendisine adayan kullar olun\" der."},{"n":80,"t":"Ve size, melekleri ve peygamberleri Efendiler edinmenizi de emretmez. Siz Müslüman olduktan sonra, size hiç inkârı emreder mi?"},{"n":81,"t":"ALLAH peygamberlerden (nebilerden) şöyle misak almıştı: \"Size kitap ve hikmet vereceğim. Daha sonra, beraberinizdekileri doğrulayan bir elçi (resul) geldiğinde onu onaylayacak ve onu destekleyeceksiniz. Bunu kabul ettiniz mi ve bu sözleşmeyi yerine getireceğinize söz verdiniz mi\" demişti. Onlar \"Kabul ettik\" deyince, \"Öyleyse şahit olun, ben de sizinle beraber şahit olanlardanım\" demişti."},{"n":82,"t":"Bundan sonra kim dönerse yoldan çıkmıştır."},{"n":83,"t":"ALLAH’ın dininden başkasını mı arıyorlar? Oysa göklerde ve yerde kim varsa ister istemez O’na teslim olmuştur ve hepsi O’na döndürülecektir."},{"n":84,"t":"De ki: \"ALLAH’ı, bize indirileni, İbrahim’i, İsmail’i, İshak’ı, Yakub’u ve torunlara indirileni; Musa’yı, İsa’yı ve peygamberlere Rab’leri tarafından verilenleri onayladık. Onların hiçbiri arasında ayrım yapmayız ve biz O’na teslim olanlarız.\""},{"n":85,"t":"Kim İslam’dan (Tanrı’ya barış içinde teslim olmaktan) başka bir din ararsa kendisinden kabul edilmeyecek ve o ahirette kaybedenlerden olacaktır."},{"n":86,"t":"Gerçeği onayladıktan, elçinin doğru olduğuna tanık olduktan ve kendilerine açık deliller geldikten sonra, inkâr eden bir toplumu, ALLAH nasıl olur da doğruya iletir? ALLAH zalim toplumu hidayete ulaştırmaz."},{"n":87,"t":"Onlar, ALLAH’ın, meleklerin ve insanların toplu lanetini hak etmişlerdir."},{"n":88,"t":"Orada sürekli kalıcıdırlar; azapları hafifletilmez ve kendilerine bakılmaz."},{"n":89,"t":"Ancak, bundan sonra yönelip durumlarını düzeltenler başka. ALLAH Bağışlayandır, Rahimdir."},{"n":90,"t":"Gerçeği onaylamalarından sonra inkâr edip de inkârlarında ileri gidenlerin tövbeleri kabul edilmez; onlar artık tümüyle sapmış demektir."},{"n":91,"t":"İnkâr edip inkârcı olarak ölenler, dünya dolusu altını fidye olarak verseler dahi kendilerinden kabul edilmeyecektir. Onlar acıklı bir azabı hak ettiler ve hiçbir yardımcıları da olmayacak."},{"n":92,"t":"Sevdiğiniz şeylerden ekonomik yardım olarak vermedikçe erdemli bir kişi olamazsınız. Her neyi verirseniz ALLAH mutlaka onu bilir."},{"n":93,"t":"Tevrat indirilmeden önce İsrail kendisine haram kılıncaya kadar İsrailoğullarına tüm yiyecekler helal idi. \"Doğru sözlülerseniz Tevrat’ı getirip okuyun\" de."},{"n":94,"t":"Artık kim yalanları ALLAH’a yakıştırırsa, işte zalimler onlardır."},{"n":95,"t":"De ki: \"ALLAH doğruyu söyler; İbrahim’in tektanrıcı dinine uyun. O ortak koşanlardan olmadı.\""},{"n":96,"t":"Halk için kurulan ilk ev, tüm halklara bir hidayet kaynağı olan Bekke’deki kutlu evdir."},{"n":97,"t":"Orada apaçık işaretler var: İbrahim’in (putperestliğe karşı) duruş yeridir. Oraya giren güvenlik içinde olmalı. Halktan yolculuğa gücü yetenler o Ev’i ALLAH için konferansa gitmekle yükümlüdür. Kim inkâr ederse bilsin ki ALLAH kimseye muhtaç değildir."},{"n":98,"t":"De ki: \"Kitap halkı, ALLAH yaptıklarınıza tanıkken neden ALLAH’ın ayetlerini tanımıyorsunuz?\""},{"n":99,"t":"De ki: \"Kitap halkı, doğruya tanık olduğunuz halde neden ALLAH’ın yolunu değiştirmeye yeltenerek gerçeği onaylayanları saptırıyorsunuz? ALLAH yaptıklarınızdan habersiz değildir.\""},{"n":100,"t":"Gerçeği onaylayanlar! Kitap halkından bir kısmına uyarsanız gerçeği onaylamanızdan sonra sizi inkârcılığa döndürürler."},{"n":101,"t":"ALLAH’ın ayetleri size okunduğu ve O’nun elçisi aranızda olduğu halde nasıl olur da inkâr edersiniz? Kim ALLAH’a sarılırsa dosdoğru yola iletilmiştir."},{"n":102,"t":"Gerçeği onaylayanlar! ALLAH’ı gereğince dinleyin ve Müslümanlar (Tanrı’ya barış içinde teslim olanlar) olarak ölün."},{"n":103,"t":"ALLAH’ın ipine topluca sımsıkı sarılın; ayrılığa düşmeyin. ALLAH’ın size olan nimetini anımsayın. Siz birbirinize düşmanlar idiniz de kalplerinizi birleştirdi ve O’nun nimeti sayesinde kardeşler oldunuz. Bir ateş çukurunun kenarında idiniz, sizi ondan kurtardı. Yola gelesiniz diye ALLAH ayetlerini böyle açıklıyor."},{"n":104,"t":"İçinizde, iyiliğe çağıran, sağduyuyu öğütleyen ve kötülükten sakındıran bir topluluk olsun. Bunlar başaranlardır."},{"n":105,"t":"Kendilerine apaçık deliller geldikten sonra ayrılık ve anlaşmazlığa düşenler gibi olmayınız. Onlar için büyük bir azap var."},{"n":106,"t":"O gün bazı yüzler aklanır, bazı yüzlerse kararır. Yüzleri kararanlara: \"Gerçeği onayladıktan sonra inkâr mı ettiniz? İnkârınızdan dolayı azabı tadın.\""},{"n":107,"t":"Yüzleri aklananlar ise ALLAH’ın rahmeti içindedir. Orada sürekli kalırlar."},{"n":108,"t":"Bunlar, sana dosdoğru olarak okuduğumuz ALLAH’ın ayetleridir. ALLAH hiç kimseye zulmetmek istemez."},{"n":109,"t":"Göklerde ve yerde ne varsa ALLAH’ındır ve tüm işler ALLAH tarafından kontrol edilir."},{"n":110,"t":"Siz, halk için çıkarılmış en iyi topluluksunuz. İyiliği öğütler, kötülükten sakındırır ve ALLAH’ı onaylarsınız. Kitap halkı onaylasaydı kendileri için iyi olurdu. İçlerinde gerçeği onaylayanlar olmakla birlikte çoğunluğu yoldan çıkmıştır."},{"n":111,"t":"Size hakaretten başka bir zarar veremezler. Sizinle savaşırlarsa dönüp kaçarlar; kendilerine yardım da edilmez."},{"n":112,"t":"Nerede bulunurlarsa bulunsunlar – ALLAH ile bağlantı kuranlar veya halk ile bağlantı kuranlar hariç– horlandılar. ALLAH’ın gazabını hak ettiler ve yoksulluğa mahkûm edildiler. Zira onlar, ALLAH’ın ayetlerini inkâr ediyor ve peygamberleri haksız yere öldürüyorlardı. Tüm bunlar, karşı gelmeleri ve sınırı aşmalarının bir sonucu idi."},{"n":113,"t":"Ancak hepsi bir değil. Kitap halkından dosdoğru bir grup var ki geceleri ALLAH’ın ayetlerini okuyup secde ederler."},{"n":114,"t":"ALLAH’ı ve ahiret gününü onaylarlar, iyiliği öğütler kötülükten sakındırır ve iyi işlere koşuşurlar. İşte onlar iyilerdendir."},{"n":115,"t":"Yaptıkları hiçbir iyilik karşılıksız kalmayacaktır. ALLAH erdemlileri çok iyi bilir."},{"n":116,"t":"İnkâr edenlerin ne paraları ne de çocukları ALLAH’a karşı kendilerine hiçbir yarar sağlamayacaktır. Onlar ateşin halkıdır ve orada sürekli kalıcıdırlar."},{"n":117,"t":"Bu dünya hayatındaki harcamaları, kendi kendilerine zulmeden bir topluluğun ekinine vurup mahveden dondurucu bir rüzgar gibidir. ALLAH onlara zulmetmedi; fakat onlar kendi kendilerine zulmediyorlardı."},{"n":118,"t":"Gerçeği onaylayanlar, size kötülük etmekten geri durmayan, sizin sıkıntıya düşmenizi isteyen kimseleri sırdaş edinmeyin. Ağızlarından kin ve nefret taşmaktadır. Göğüslerinde gizledikleri ise daha büyük. Size ayetleri açıkladık; düşünürseniz,"},{"n":119,"t":"İşte sizler, onlar sizi sevmediği halde onları sevenlersiniz! Üstelik siz kitabın tümünü onaylarsınız. Sizinle karşılaştıkları zaman \"Gerçeği onayladık\" derler, yalnız kaldıklarında ise size olan öfkelerinden dolayı parmaklarını ısırırlar. De ki: \"Öfkenizden canınız çıksın.\" Kuşkusuz ALLAH göğüslerin özünü Bilendir."},{"n":120,"t":"Size bir iyilik dokunsa onlara üzüntü verir, başınıza bir kötülük gelse ona sevinirler. Zorluklara karşı direnir ve erdemli davranırsanız entrikaları size hiçbir zarar vermez. ALLAH tüm yaptıklarını kontrol eder."},{"n":121,"t":"Hani sen, sabah erkenden ailenden ayrılarak gerçeği onaylayanları savaşta tutacakları noktalara yerleştiriyordun. Elbette ALLAH İşitir, Bilir."},{"n":122,"t":"Sizden iki grup nerede ise bozguna uğradı. Oysa ALLAH onların Sahibiydi. Gerçeği onaylayanlar ALLAH’a güvensin."},{"n":123,"t":"Nitekim siz zayıf durumda iken, Bedir’de, ALLAH size yardım edip zafere ulaştırdı. Teşekkürünüzü belirtmek için ALLAH’ı dinlemelisiniz."},{"n":124,"t":"Gerçeği onaylayanlara şunları diyordun: \"İndirilmiş üç bin melek ile Efendinizin sizi desteklemesi size yetmez mi?\""},{"n":125,"t":"Evet, güçlüklere karşı direnir ve erdemli davranırsanız size şu anda ani bir baskın yapsalar, Efendiniz sizi eğitilmiş beş bin melek ile destekler."},{"n":126,"t":"ALLAH bunu, kalbinizi yatıştıracak bir müjde olsun diye anlatıyor. Zafer, yalnızca Güçlü ve Bilge olan ALLAH katındandır."},{"n":127,"t":"Böylece inkârcıların bir kısmını imha eder veya onları etkisiz hale getirip bozguna uğratır."},{"n":128,"t":"Tövbelerini kabul etmesi veya işledikleri zulümden dolayı onları azaplandırması seni ilgilendirmez."},{"n":129,"t":"Göklerde ve yerde bulunan her şey ALLAH’ındır. Affedilmeyi hakedeni affeder, cezayı hak edeni cezalandırır. ALLAH Bağışlayandır, Rahimdir."},{"n":130,"t":"Gerçeği onaylayanlar, faizi kat kat arttırılmış olarak yemeyin. Başarılı olmak için ALLAH’ı dinleyin."},{"n":131,"t":"İnkârcılar için hazırlanmış olan ateşten sakının."},{"n":132,"t":"Merhamet edilmeniz için ALLAH’a ve elçiye uyun."},{"n":133,"t":"Efendiniz tarafından bağışlanmaya, eni göklerle yeri kapsayan ve erdemliler için hazırlanmış olan bahçeye doğru koşun."},{"n":134,"t":"O erdemliler ki bollukta ve darlıkta yardım için para harcarlar, öfkelerini kontrol ederler, insanların kusurlarını görmemezlikten gelirler. ALLAH iyilik yapanları sever."},{"n":135,"t":"Onlar ki bir günah işledikleri, yahut kendilerine zulmettikleri zaman ALLAH’ı anımsar ve günahları için bağışlanma dilerler –zaten ALLAH’tan başka kim günahları bağışlayabilir ki?– ve onlar bile bile günah işlemeye devam etmez."},{"n":136,"t":"Onlara, Rab’lerinden bağışlanma ve altından ırmaklar akan bahçelerle karşılık verilir; orada sürekli kalırlar. Çalışanların ödülü ne güzeldir."},{"n":137,"t":"Sizden önce de yasalar uygulanmıştı. Yeryüzünde dolaşın da yalanlayıcıların sonunun ne olduğunu görün."},{"n":138,"t":"Bu, insanlara bir bildiri, erdemlilere de bir yol gösterici ve öğüttür."},{"n":139,"t":"Gevşemeyin, üzülmeyin; Gerçeği onaylıyorsanız üstün sizsiniz!"},{"n":140,"t":"Size bir sıkıntı dokunduysa, düşman topluluğa da benzeri bir sıkıntı dokunmuştur. Böyle günleri, halkın arasında döndürüp duruyoruz ki ALLAH gerçeği onaylayanları ayırsın ve sizden bazılarını şahitler edinsin. ALLAH zalimleri sevmez."},{"n":141,"t":"ALLAH böylece gerçeği onaylayanları sağlamlaştırır ve kâfirlerin gururunu kırar."},{"n":142,"t":"ALLAH aranızdaki çalışanları ortaya çıkarmadan, sabredenleri ayırmadan bahçeye gireceğinizi mi sandınız?"},{"n":143,"t":"Siz ölümle karşılaşmadan önce onu arzuluyordunuz. Fakat şimdi onu gördüğünüz halde bekliyorsunuz."},{"n":144,"t":"Muhammed sadece bir elçidir ve ondan önce de nice elçiler gelip geçmiştir. Ölür yahut öldürülürse geriye mi döneceksiniz. Dönekler ALLAH’a hiçbir zarar veremez. ALLAH şükredenleri ödüllendirecektir."},{"n":145,"t":"ALLAH’ın izni olmadan hiç kimse ölemez. Ölümün belirlenmiş bir süresi var. Kim dünya nimetini isterse ona ondan veririz, kim ahiret nimetini isterse ona da ondan veririz. Şükredenleri ödüllendireceğiz."},{"n":146,"t":"Nice peygamberler var ki yanlarında kendilerini Rab’lerine adamış birçok kişi ile birlikte savaştılar. ALLAH yolunda başlarına gelenden ötürü gevşemediler, yılmadılar, boyun eğmediler. ALLAH direnenleri sever."},{"n":147,"t":"Sözleri yalnızca şuydu: \"Efendimiz, günahlarımızı ve işlerimizdeki aşırılıklarımızı bağışla, ayaklarımızı sağlam tut ve inkârcı topluluğa karşı bize zafer ver.\""},{"n":148,"t":"ALLAH da onlara hem dünya nimetini hem de ahiret nimetinin en güzelini verdi. ALLAH güzel davrananları sever."},{"n":149,"t":"Ey gerçeği onaylayanlar, inkâr edenlere uyarsanız sizi gerisin geriye döndürürler ve kaybedenlerden olursunuz."},{"n":150,"t":"Hayır, sahibiniz ve dostunuz (mevlanız) ALLAH’tır. O, yardım edenlerin en iyisidir."},{"n":151,"t":"Güçsüz ve yetkisiz kişileri ALLAH’a ortak koştukları için inkârcıların kalplerine korku salacağız. Yerleri ateştir. Zalimlerin durağı ne kötü!"},{"n":152,"t":"ALLAH size verdiği sözde durdu ve nitekim izniyle onları darmadağın ettiniz. Ama, sevdiğinizi size gösterdikten sonra duraksadınız, savaş hakkında birbirinizle çekiştiniz ve emirleri dinlemediniz. Kiminiz dünyayı istiyordu, kiminiz de ahireti… Sonra, sınamak için sizi onlardan çevirdi ve her şeye rağmen sizi affetti. ALLAH’ın gerçeği onaylayanlara nimeti boldur."},{"n":153,"t":"Elçi arkanızdan çağırmasına rağmen siz hiç kimseye dönüp bakmaksızın tepeyi tırmanıyordunuz. Yitirdiklerinize ve başınıza gelenlere üzülmeyesiniz diye size keder üstüne keder verdi. ALLAH yaptıklarınızdan Haberdardır."},{"n":154,"t":"Sonra o üzüntünün ardından, içinizden bir grubu sakinleştiren güven dolu bir uykuyu üzerinize indirdi. Bir kısmınız bencilce kendi derdine düşmüş, cahiliye döneminde olduğu gibi ALLAH hakkında yanlış düşünceler üretiyor ve, \"Bu işte bir karar yetkimiz olsaydı öldürülmezdik\" diyordu. \"Tüm yetki ALLAH’ındır\" de. Sana açmadıklarını içlerinde gizliyorlardı. \"Bizim bir yetkimiz olsaydı burada öldürülmezdik\" diyorlar. De ki: \"Evlerinizde dahi olsaydınız, aranızda ölmesi kararlaştırılanlar devrilecekleri yere doğru sürüneceklerdi.\" ALLAH böylece göğüslerinizdekini dener ve kalplerinizdekini arıtır. ALLAH en gizli düşünceleri bilir."},{"n":155,"t":"İki ordunun çarpıştığı gün geriye dönenlerinizi yaptıkları bazı işlerden dolayı sapkın kaydırmak istemişti. Ancak ALLAH onları affetti. ALLAH gerçekten çok Bağışlayıcı, çok Şefkatlidir."},{"n":156,"t":"Gerçeği onaylayanlar! Yolculuğa çıkan veya savaşa giden kardeşleri için, \"Bizimle kalsalardı ne ölür ne de öldürülürlerdi\" diyen inkârcılar gibi olmayın. ALLAH bu tip düşünceyi kalplerinde bir üzüntü kaynağı yapar. Yaşatan da öldüren de ALLAH’tır. ALLAH yaptıklarınızı Görüyor."},{"n":157,"t":"ALLAH yolunda ölür yahut öldürülürseniz, ALLAH’ın bağışlaması ve rahmetine kavuşmuş olursunuz ki bu onların tüm topladıklarından daha iyidir."},{"n":158,"t":"Ölürseniz de öldürülürseniz de ALLAH’ın huzuruna çıkarılacaksınız."},{"n":159,"t":"ALLAH’ın sana bir bağışı olarak onlara yumuşak davrandın. Kaba ve katı yürekli olsaydın çevrenden dağılır giderlerdi. Onları affet, bağışlanmalarını dile ve yapılacak işler hakkında onlara danış. Karar verince de ALLAH’a güven; ALLAH güvenenleri sever."},{"n":160,"t":"ALLAH sizi desteklerse hiçbir güç sizi yenemez. Sizi terk ederse, artık size kim yardım edebilir ki? Gerçeği onaylayanlar ALLAH’a güvensin."},{"n":161,"t":"Bir peygamber ganimet mallarını zimmetine geçiremez. Kim hakkından fazlasını alırsa diriliş günü o fazlalıkla gelir. Sonra herkese kazandığının karşılığı tam ödenir ve haksızlığa uğratılmazlar."},{"n":162,"t":"ALLAH’ın rızasını gözeten bir kimse ALLAH’ın öfkesine uğrayıp cehennemi boylayan gibi olur mu? O ne kötü bir yerdir!"},{"n":163,"t":"Onlar ALLAH katında derece derecedir. ALLAH yaptıkları her şeyi görmektedir."},{"n":164,"t":"ALLAH gerçeği onaylayanların içinden, onlara ayetlerini okuyan, onları arındıran, onlara kitap ve bilgelik öğreten bir elçiyi göndermekle iyilikte bulundu. Oysa onlar daha önce apaçık bir sapıklık içindeydiler!"},{"n":165,"t":"Uğradığınız zararın iki katını verdiğiniz halde, \"Bu da niçin\" dediniz. De ki: \"musibet, kendi tarafınızdandır.\" ALLAH her şeye Kadirdir."},{"n":166,"t":"İki ordu çarpıştığı gün başınıza gelenler ALLAH’ın izniyle oldu. Gerçeği onaylayanlar böylece ayırt edilir."},{"n":167,"t":"İkiyüzlüler de böylece açığa çıkarılır. Kendilerine, \"Gelin, ALLAH yolunda savaşın ya da katkıda bulunun\" denildiğinde, onlar, \"Savaştan anlasaydık size katılırdık\" dediler. O an onlar onaydan daha çok inkâra yakın idiler. Kalplerinde olmayanı ağızlarıyla söylüyorlar. Halbuki ALLAH onların gizlediğini çok iyi biliyor."},{"n":168,"t":"Onlar oturup, akrabaları için şunu söylediler: \"Bize uysalardı öldürülmeyeceklerdi.\" De ki: \"Ölümü kendinizden savın da doğru sözlü olduğunuzu kanıtlayın.\""},{"n":169,"t":"ALLAH yolunda vurulanları ölü sanmayın; bilakis onlar Rab’leri katında nimetler içinde diridirler."},{"n":170,"t":"ALLAH’ın onlara bolca verdiği nimetlerle neşe içindedirler. Kendilerine daha katılmamış yoldaşlarına bir korku ve üzüntü olmadığını müjdelemek isterler."},{"n":171,"t":"ALLAH’ın bol nimetini ve ALLAH’ın gerçeği onaylayanların ödülünü yitirmeyeceği gerçeğini müjdelemek isterler."},{"n":172,"t":"O gerçeği onaylayanlar ki, savaşta yara aldıktan sonra bile ALLAH’ın ve elçisinin çağrısına uydular. İyilik yapıp erdemli davrananları için büyük bir ödül var."},{"n":173,"t":"Onlar ki insanlar kendilerine, \"Halk size karşı birleşip harekete geçmiş; korkun onlardan\" dediklerinde, bu onların ancak onaylamasını arttırır ve şöyle derler: \"Bize ALLAH yeter; o ne güzel Koruyucudur.\""},{"n":174,"t":"Böylece, kendilerine hiçbir kötülük dokunmadan, ALLAH’tan bir nimet ve lütufla geri döndüler. ALLAH’ın rızasını gözetmişlerdi. Büyük lütfun sahibi ALLAH’tır."},{"n":175,"t":"Sapkın ancak kendi dostlarına korku verir. Onlardan korkmayın, benden korkun; gerçekten onaylamışsanız."},{"n":176,"t":"İnkârcılıkta yarışanlar seni üzmesin. Onlar ALLAH’a hiçbir zarar veremez. ALLAH ahirette onlara bir pay vermemek diliyor. Onlar için büyük bir azap var."},{"n":177,"t":"Gerçeği onaylamayı bırakıp küfrü satın alanlar ALLAH’a hiçbir zarar veremezler ve onlar için acıklı bir azap var."},{"n":178,"t":"İnkârcılar, vermiş bulunduğum sürenin kendileri için iyi olduğunu sanmasınlar. Günahlarının artması için kendilerine süre veriyoruz. Onlara alçaltıcı bir azap var."},{"n":179,"t":"ALLAH gerçeği onaylayanları şu içinde bulunduğunuz durumda bırakacak değil. İyiyi kötüden ayıracaktır. ALLAH size geleceği bildirecek de değil. Fakat ALLAH elçilerinden dilediğini seçer. ALLAH’ı ve elçilerini onaylayın. Gerçeği onaylayıp erdemli davranırsanız size büyük bir ödül var."},{"n":180,"t":"ALLAH’ın lütfundan kendilerine bağışladığı nimetlerde cimrilik edenler onu kendileri için hayırlı sanmasın. Aksine, o kendileri için zararlıdır. Toplayıp biriktirdikleri, Diriliş Günü boyunlarına dolanacak. Göklerin ve yerin mirası ALLAH’ındır. ALLAH yaptıklarınızdan haberdardır."},{"n":181,"t":"\"ALLAH fakir, biz ise zenginiz\" diyenlerin sözünü ALLAH işitmekte. Söylediklerini ve haksız yere peygamberleri öldürmelerini kaydedeceğiz ve \"Yakıcı azabı tadın\" diyeceğiz."},{"n":182,"t":"\"Bu, kendi yaptıklarınızın bir sonucudur.\" Kuşkusuz ALLAH kullara karşı zalim değildir."},{"n":183,"t":"Onlar, \"Ateşin yiyeceği bir kurban getirmedikçe hiçbir elçiyi onaylamamamız konusunda ALLAH bizden söz aldı\" diyorlar. De ki: \"Benden önce, apaçık delillerle birlikte bu dediğinizi de size getiren elçiler geldi. Sözünüzün eriyseniz niçin onları öldürdünüz?\""},{"n":184,"t":"Seni yalanlarlarsa, senden önce apaçık deliller, bilgelik dolu kitaplar (zebur) ve aydınlatıcı kitap getiren elçiler de yalanlanmıştı."},{"n":185,"t":"Herkes ölümü tadacaktır. Diriliş Günü ödülleriniz size eksiksiz olarak verilir. Kim ateşten kurtarılıp bahçeye sokulursa, zafer kazanmış olur. Dünya hayatı ancak aldatıcı bir zevkten ibarettir."},{"n":186,"t":"Paralarınızla, canlarınızla sınanacaksınız. Sizden önce kendilerine kitap verilenlerden ve ortak koşanlardan çok hakaretler işiteceksiniz. Direnir ve erdemli bir hayat sürerseniz büyük iş yapmış olursunuz."},{"n":187,"t":"ALLAH kendilerine kitap verilenlerden, \"Onu mutlaka insanlara açıklayacaksınız, gizlemeyeceksiniz\" diye söz almıştı. Fakat onlar, onu arkalarına atıp az bir fiyata sattılar. Ne kötü bir alışveriş!"},{"n":188,"t":"Sanma ki verdikleriyle gururlanan ve yapmadıkları şeylerden ötürü övülmeyi sevenler, evet sanma ki onlar azaptan kurtulacak. Onlara acıklı bir azap var."},{"n":189,"t":"Göklerin ve yerin egemenliği ALLAH’ındır. ALLAH her şeye Kadirdir."},{"n":190,"t":"Göklerin ve yerin yaratılmasında, gece ile gündüzün birbirini izlemesinde akıl sahipleri için ayetler var."},{"n":191,"t":"Onlar ki ayaktayken, otururken ve yanları üzerine yatarken ALLAH’ı anarlar. Göklerin ve yerin yapısı ve yaratılışı hakkında düşünürler: \"Efendimiz, sen bunları boş yere yaratmadın, sen yücesin, bizi ateş azabından koru.\""},{"n":192,"t":"\"Efendimiz, sen kimi ateşe sokarsan elbette onu rezil etmişsindir. Zalimlere yardım eden olmaz.\""},{"n":193,"t":"\"Efendimiz, biz,’Efendinizi onaylayın’ diye onaylamaya çağıran bir davetçiyi işittik ve onayladık. Efendimiz, günahlarımızı bağışla, kötülüklerimizi ört ve iyi kişiler olarak canımızı al.\""},{"n":194,"t":"\"Efendimiz, elçilerin yoluyla bize söz verdiğin şeyi ver, diriliş gününde bizi rezil etme. Sen sözünden hiç caymazsın.\""},{"n":195,"t":"Rab’leri onlara cevap verdi: \"Ben, sizden hiçbir çalışanın yaptığını ödülsüz bırakmam, ister erkek olsun, ister kadın olsun; hepiniz eşitsiniz. Göç edenler, yurtlarından çıkarılanlar, yolumda işkence ve hakarete uğrayanlar, vuruşanlar, öldürülenler… Onların kötülüklerini örteceğim ve onları içlerinde ırmaklar akan bahçelere yerleştireceğim. ALLAH’tan bir karşılık olarak… En güzel karşılık ALLAH’ın yanındadır."},{"n":196,"t":"İnkârcıların ülkelerdeki egemenliği seni aldatmasın.\""},{"n":197,"t":"Bu kısa süreli bir yararlanmadır, sonra cehennemi boylayacaklar; ne kötü bir durak!"},{"n":198,"t":"Rab’lerini dinleyenler için içlerinde ırmaklar akan bahçeler var. ALLAH tarafından bir konut olarak orada ebedî kalacaklar. İyiler için ALLAH’ın yanında bulunanlar daha hayırlıdır."},{"n":199,"t":"Kitaplıların öyleleri var ki ALLAH’a, size indirilene ve kendilerine indirileni onaylarlar. ALLAH’a karşı derin saygıya sahiptirler. ALLAH’ın ayetlerini az bir değere satmazlar. Onların ödülleri Rab’lerinin yanındadır. ALLAH hesabı çabuk görendir."},{"n":200,"t":"Gerçeği onaylayanlar! Başarmak için, güçlüklere karşı tek tek direnin, topluca direnin, birlik olun ve ALLAH’ı dinleyin."}]},{"id":4,"name":"Nisa Suresi","verses":[{"n":1,"t":"İnsanlar! Sizi bir tek nefisten yaratan, ondan da eşini yaratan, ikisinden pek çok erkek ve kadın üreten Efendinizi dinleyin. Adına birbirinizden isteklerde bulunduğunuz ALLAH’a saygı gösterin; akrabalara da… ALLAH elbette sizi gözetlemektedir."},{"n":2,"t":"Yetimlere mallarını verin. Temiz olanı pis olanla değişmeyin. Mallarını kendi mallarınıza katıp yemeyin. Bu büyük bir adaletsizlik olur."},{"n":3,"t":"Yetimler hakkında adaletli davranamamaktan korkuyorsanız uygun gördüğünüz kadınlarla ikişer, üçer, dörder evlenebilirsiniz. Onlara eşit davranamamaktan korkuyorsanız bir taneyle veya yeminlerinizin/anlaşmalarınızın hak sahibi oldukları ile yetinin. Sapmamanız için en uygunu budur."},{"n":4,"t":"Kadınlara mehirlerini tam verin. Kendi istekleriyle o mehrin bir kısmını size bağışlarlarsa onu gönül huzuruyla yiyebilirsiniz."},{"n":5,"t":"ALLAH’ın sizi gözetici kıldığı mallarınızı aklı ermezlere vermeyin. O mallarla onları besleyin, giydirin ve onlarla güzel iletişim kurun."},{"n":6,"t":"Evlenme yaşına eriştiklerinde yetimleri sınayın. Onlarda olgunluk görürseniz kendilerine mallarını verin. Onlar büyüyecek diye savurganlık ve aceleyle mallarını yemeyin. Zengin, (malın korumasına gösterdiği çabanın ücretinden) vazgeçsin. Fakir ise uygun bir miktarda harcasın. Mallarını kendilerine tanıklar huzurunda geri verin. Hesap görücü olarak ALLAH yeter."},{"n":7,"t":"Ana babanın ve akrabaların bıraktığından erkeklere bir pay vardır. Ana babanın ve akrabaların bıraktığından kadınlara da bir pay vardır. Miras ister az olsun ister çok olsun kadın bir pay almalıdır."},{"n":8,"t":"Miras bölüşümünde, akrabalar, yetimler ve yoksullar da hazır bulunursa güzel sözler söyleyerek onlara da verin."},{"n":9,"t":"Geriye zayıf çocuklar bırakan ve onların durumlarından endişe duyanlar dikkat etsinler! ALLAH’ı düşünsünler ve uygun kararlar versinler."},{"n":10,"t":"Yetimlerin mallarını haksız yere yiyenler karınlarını ateşle doldurmuş olurlar ve cehennemi boylayacaklar."},{"n":11,"t":"ALLAH size çocuklarınız hakkında öğütte bulunuyor. Erkek, kadının iki katı pay alır. Mirasçılar sadece kadın olup iki kişiden fazla iseler kalıtın üçte ikisi onlarındır. Çocuk sadece bir kadınsa kalıtın yarısı onundur. Ölen kişi ardında çocuk bırakmışsa, ana ve babasının her birisine altıda bir düşer. Çocuğu yok da kendisine sadece ana ve babası varis oluyorsa bu durumda annesine üçte bir pay düşer. Kardeşi varsa bu durumda annesine altıda bir düşer. Tüm bu paylaşma oranları, ölenin yaptığı vasiyetten ve borçların ödenmesinden sonra gelir. Analarınız, babalarınız ve çocuklarınızdan hangisinin size daha yararlı olduğunu bilemezsiniz. Bu ALLAH’ın yasasıdır. ALLAH Bilendir, Bilgedir."},{"n":12,"t":"Çocukları yoksa, hanımlarınızın bıraktığı mirasın yarısı sizindir. Çocukları var ise, bıraktıklarının dörtte biri sizindir. Bu pay, borçlarının ödenmesinden ve yaptıkları vasiyetteki payların dağıtılmasından sonradır. Çocuklarınız yoksa bıraktığınızın dörtte biri onlarındır. Çocuklarınız varsa, bıraktığınızın sekizde biri onlarındır. Bu pay, borçlarınızın ödenmesinden ve yaptığınız vasiyetteki payların dağıtılmasından sonradır. Miras bırakan erkeğin veya kadının, çocuğu ve eşi olmayıp bir erkek veya bir kız kardeşi var ise bu durumda her birine altıda bir düşer. Bundan fazla iseler, üçte biri paylaşırlar. Bu paylaşım vasiyetteki payların dağıtılmasından ve borçların ödenmesinden sonra uygulanmalıdır ki kimseye zarar verilmesin. Bu, ALLAH’tan bir vasiyettir. ALLAH Bilir, Şefkatlidir."},{"n":13,"t":"Bunlar ALLAH’ın yasalarıdır. ALLAH’a ve elçisine uyanları içinden ırmaklar akan bahçelere yerleştirir. Orada sürekli kalırlar. Bu, en büyük başarıdır."},{"n":14,"t":"Kim ALLAH’a ve elçisine isyan eder ve yasalarını çiğnerse, onu içinde sürekli kalacağı bir ateşe sokar. Onun için alçaltıcı bir azap var."},{"n":15,"t":"Kadınlarınızdan fuhuş yapanlara karşı içinizden dört tanık getirin. Tanıklık ederlerse, onları, ölünceye veya ALLAH onlara bir yol açıncaya kadar evlerde tutun."},{"n":16,"t":"Sizden zina işleyen çifti cezalandırın. Tövbe edip düzelirlerse onlardan vazgeçin. ALLAH yönelişleri kabul edendir, Rahim’dir."},{"n":17,"t":"Cahillik yüzünden bir kötülük işleyen ve hemen ardından tövbe edenlerin tövbesinin kabulu ALLAH’a aittir. ALLAH tövbelerini kabul eder. ALLAH Bilendir, Bilgedir."},{"n":18,"t":"Sürekli kötülük işleyen ve kendilerini ölüm yakalayınca, \"Ben artık tövbe ettim\" diyenlerin tövbesi geçersizdir. İnkârcı olarak ölenlerin de tövbesi geçersizdir. Onlar için acıklı bir azap var."},{"n":19,"t":"Gerçeği onaylayanlar! Kadınların mirasına onların isteklerine aykırı olarak mirasçı olmanız sizin için yasal değil. Kendilerine önceden vermiş bulunduğunuz malları onlardan geri almak için onları sıkıştırmayın. Bir fuhuş işlemeleri hali istisna. Onlarla iyi geçinin. Onlardan hoşlanmıyorsanız, olur ki hoşlanmadığınız bir şeye ALLAH çok hayır koymuştur."},{"n":20,"t":"Mevcut eşinizi bırakıp bir başka eşle evlenmek istiyorsanız, birincisine büyük miktarda mal vermişseniz bile ondan hiçbir şeyi geri almayın. Sahtekârlık ve iftira ederek ve günah işleyerek mi geri alacaksınız?"},{"n":21,"t":"Bir zamanlar birbirinizin en yakın içli dışlı dostu olmanıza ve sizden sağlam bir söz almalarına rağmen nasıl olur da onu geri alırsınız?"},{"n":22,"t":"Babanızın evlenmiş bulunduğu kadınlarla artık evlenmeyin. Fakat geçmişte yaptığınız bu tip evlilikleri de bozmayın. O davranış büyük bir günahtır, iğrenç ve kötü bir yoldur."},{"n":23,"t":"Size şunlar yasaklandı: Anneleriniz, kızlarınız, kız kardeşleriniz, halalarınız, teyzeleriniz, kardeş kızları, kız kardeş kızları, sizi emziren analarınız, süt bacılarınız, karılarınızın anaları, kendileriyle gerdeğe girdiğiniz karılarınızdan olup evlerinizde bulunan üvey kızlarınız –eğer onlarla gerdeğe girmemişseniz kızlarıyla evlenebilirsiniz–, öz oğullarınızın eşleri ve iki kız kardeşi bir arada almanız… Mevcut evlilikler bu yasanın dışındadır. ALLAH Bağışlayandır, Rahimdir."},{"n":24,"t":"Ayrıca yeminlerinize/anlaşmalarınıza sahip olanlar hariç, (evlilik yoluyla) korunmuş kadınlar. Bunlar, ALLAH’ın üzerinize farz kıldığı yasalardır. Bunların dışındakiler, iffetli yaşamanız, zina etmemeniz ve mehirleriyle istemeniz koşuluyla size helaldir. Onlardan hoşlandıklarınıza, bir farz olarak mehirlerini ödeyin. Bu farzı yerine getirirken mehri ayarlamak için karşılıklı anlaşmanızda bir sakınca yoktur. ALLAH Bilendir, Bilgedir."},{"n":25,"t":"Sizden (bekar veya dul) korunmuş kadınlarla evlenmeye güç yetiremeyenler, yeminlerinize/anlaşmalarınıza sahip olanlar gerçeği onaylamış kadınlarla evlensinler. Onaylamanızın aslını en iyi bilen ALLAH’tır. Birbirinize eşitsiniz. Sahiplerinin izniyle ve uygun şekilde mehirlerini ödeyerek onlarla nikahlanın. İffetli yaşasınlar, zina etmesinler ve gizli dostlar edinmesinler. Evlilik yoluyla özgürlüklerine kavuştuktan sonra zina yaparlarsa, kendilerine korunmuş kadınlara verilen cezanın yarısı uygulanmalı. Bu, günaha girmekten korkanlarınız içindir. Sabrederseniz sizin için daha iyi. ALLAH Bağışlayandır, Rahimdir."},{"n":26,"t":"ALLAH size bunları açıklamak, sizden öncekilerin yoluna sizi iletmek ve kendisine yönelişinize (tövbe) karşılık vermek ister. ALLAH Bilendir, Bilgedir."},{"n":27,"t":"ALLAH sizin kendisine yönelişinize karşılık vermek ister; fantezilerine uyanlar ise sizin büsbütün sapıtmanızı ister."},{"n":28,"t":"ALLAH ise yükünüzü hafifletmek istiyor. Çünkü insan zayıf yaratıldı."},{"n":29,"t":"Gerçeği onaylayanlar! Birbirinizin malını karşılıklı rıza ile yapılan ticaret dışında haksızlık ve hile ile yemeyin;. Birbirinizi öldürmeyin. ALLAH size Rahimdir."},{"n":30,"t":"Kim düşmanlık ve zulüm ile bunu işlerse onu ateşe göndeririz. Bu, ALLAH’a kolaydır."},{"n":31,"t":"Büyük yasaklardan kaçınırsanız günahlarınızı örter ve sizi onurlu bir girişle kabul ederiz."},{"n":32,"t":"ALLAH’ın her birinize bağışladığı yeteneklere imrenmeyin. Erkeklere kazandıklarından bir pay, kadınlara da kazandıklarından bir pay var. ALLAH’tan size lütfunu bağışlamasını isteyin. ALLAH her şeyi Bilir."},{"n":33,"t":"Ananın, babanın, akrabaların ve evlenme yoluyla size akraba olanların bıraktıklarından her biriniz için paylar ayırdık. Her birine payını vermelisiniz. Elbette ALLAH her şeye Tanıktır."},{"n":34,"t":"Erkekler kadınları gözetirler. Zira ALLAH her birine farklı yetenekler ve özellikler vermiştir. Zira erkekler evin geçiminden sorumludur. Erdemli kadınlar, (Tanrı’nın yasasına) boyun eğer ve ALLAH’ın korumasını emrettiğini (onur ve iffetlerini) tek başlarına bile olsalar korurlar. İffetlerinden endişe duyduğunuz kadınlara öğüt verin, yataklarınızı ayırın ve nihayet onları çıkarın. Size itaat ederlerse onlara karşı bir yol aramayın. ALLAH Yücedir, Büyüktür."},{"n":35,"t":"Evli çiftin aralarının açılmasından endişeleniyorsanız, erkeğin ailesinden bir hakem, kadının ailesinden de bir hakem atamalısınız. (Karı ve koca) barışmayı isterlerse ALLAH ikisinin arasını bulur. ALLAH Bilir, Haber alır."},{"n":36,"t":"ALLAH’a hizmet edin O’na hiçbir şeyi ve kimseyi ortak koşmayın. Ana babaya, yakınlara, yetimlere, yoksullara, yakın komşuya, uzak komşuya, yanınızdaki arkadaşa, yolcuya ve yeminlerinizin/anlaşmalarınızın hak sahibi olduklarına iyi davranın. ALLAH kendini beğenmiş kibirli kişileri sevmez."},{"n":37,"t":"Bunlar üstelik cimridirler ve halka cimriliği öğütlerler. ALLAH’ın kendi lütfundan onlara verdiğini gizlerler. İnkârcılara acıklı bir azap hazırladık."},{"n":38,"t":"Bunlar, mallarını gösteriş için halka verir. ALLAH’ı ve ahiret gününü onaylamazlar. Kimin arkadaşı sapkın olmuşsa çok kötü bir arkadaşa sahip olmuştur."},{"n":39,"t":"ALLAH’ı ve ahiret gününü onaylasalardı ve ALLAH’ın kendilerine vermiş olduğu rızıktan yardım olarak harcasalardı ne olurdu? ALLAH onları Bilir."},{"n":40,"t":"ALLAH bir atom ağırlığınca bile haksızlık yapmaz. Aksine iyiliğin karşılığını kat kat verir ve kendi katından büyük bir ödül de verir."},{"n":41,"t":"Her ulusun üzerine bir tanık getirdiğimizde, seni de bunların üzerine tanık olarak getirsek halleri nice olur?"},{"n":42,"t":"İnkâr edenler ve elçiye karşı gelenler o gün yerle bir olmak isterler. ALLAH’tan hiçbir hadis gizleyemezler."},{"n":43,"t":"Gerçeği onaylayanlar! Sarhoşken, ne dediğinizi bilinceye kadar, yolcu olanlar hariç cinsel ilişkiden sonra yıkanıncaya kadar namaza durmayın. Hasta veya yolcu iseniz, yahut biriniz tuvaletten gelmişse, yahut kadınlarla cinsel ilişkiye girmiş olup da su bulamamışsanız, temiz ve kuru bir toprağa niyetlenin. ALLAH Affeder, Bağışlar."},{"n":44,"t":"Kendilerine kitaptan bir pay verilenlerin, sapıklığı satın aldıklarını ve sizin de yolu sapıtmanızı istediklerini görmüyor musun?"},{"n":45,"t":"ALLAH düşmanlarınızı daha iyi bilir. Dost ve sahip olarak ALLAH yeter, yardımcı olarak ALLAH yeter."},{"n":46,"t":"Yahudilerin bir kısmı kelimeleri bağlamından kaydırırlar ve \"İşittik ancak kabul etmiyoruz\" veya \"Sözünüz sağır kulağa giriyor\" veya din ile alay etmek için dillerini eğip bükerek, \"Çobanımız ol (raina)\" derler. Onlar, \"İşittik ve itaat ettik\" \"Dinliyoruz\" ve \"Bizi gözet\" deselerdi kendileri için daha iyi ve daha doğru olurdu. Ne var ki ALLAH inkârlarından ötürü onları lanetlemiştir. Çokları onaylamaz."},{"n":47,"t":"Kitaplılar! Bazı yüzleri çevirip sürgüne göndermeden ve Cumartesi Halkını lanetlediğimiz gibi lanetlenmeden önce, yanınızdakileri onaylayıcı olarak indirdiğimizi onaylayın. ALLAH’ın emri sürekli uygulanmıştır."},{"n":48,"t":"ALLAH kendisine ortak koşulmasını bağışlamaz; bundan aşağısını dilediğini bağışlar. Kim ALLAH’a ortak koşarsa çok büyük bir hakaret etmiş olur."},{"n":49,"t":"Kendilerini temize çıkaranları görmüyor musun? Oysa ALLAH dilediğini temize çıkarır. Onlara en ufak bir haksızlık yapılmaz."},{"n":50,"t":"Bak, nasıl da yalan yere ALLAH’a iftira ediyorlar. Büyük bir hakaret olarak bu yeter."},{"n":51,"t":"Kendilerine kitaptan bir pay verilenleri görmüyor musun? Azgınları ve küstahları onaylıyorlar ve inkâr edenler için, \"Bunlar, gerçeği onaylayanlardan daha doğru yoldadır\" diyorlar."},{"n":52,"t":"Onlar ALLAH’ın lanetine uğradılar. ALLAH kimi lanetlerse onun için bir yardımcı bulamazsın."},{"n":53,"t":"Yoksa onların yönetimde bir payı mı var? Öyle olsaydı insanlara bir çekirdek bile vermezlerdi."},{"n":54,"t":"Yoksa ALLAH’ın lütfundan insanlara verdiğini mi çekemiyorlar? Oysa biz, İbrahim ailesine kitap ve bilgelik verdik. Onlara büyük bir otorite verdik."},{"n":55,"t":"Onlardan kimi onu onayladı, kimi de ondan yüz çevirdi. Onlara ceza olarak cehennem yeter."},{"n":56,"t":"Ayet ve mucizelerimizi inkâr edenleri bir ateşe atacağız. Derileri yandıkça, azabı tatmaları için başka derilerle yenileyeceğiz. ALLAH Üstündür, Bilgedir."},{"n":57,"t":"Gerçeği onaylayıp erdemli davrananları ise içinden ırmaklar akan bahçelere yerleştireceğiz; orada sürekli kalırlar. Onlar için orada tertemiz eşler var. Onları serin gölgelere sokacağız."},{"n":58,"t":"ALLAH emaneti sahiplerine vermenizi, insanlar arasında hükmettiğiniz zaman adaletle hükmetmenizi emreder. ALLAH size ne güzel öğüt veriyor. ALLAH İşitendir, Görendir."},{"n":59,"t":"Gerçeği onaylayanlar! ALLAH’a uyun, elçisine uyun; sizden görev başında olanlara da. Herhangi bir konuda anlaşmazlığa düşerseniz onu ALLAH’a ve elçisine havale ediniz. ALLAH’a ve ahiret gününe Gerçeği onaylıyorsanız… Bu, sizin için daha iyi ve en güzel çözüm yoludur."},{"n":60,"t":"Seni ve senden önce indirilenleri onayladıklarını iddia ettikleri halde azgınların ve küstahların yasalarını uygulamak isteyenleri görmüyor musun? Oysa onu inkâr etmekle emredilmişlerdi; fakat sapkın onları büsbütün saptırmak istiyor."},{"n":61,"t":"Kendilerine, \"ALLAH’ın indirdiğine ve elçisine geliniz\" dendiğinde, o ikiyüzlülerin senden alabildiğine kaçtıklarını görüyorsun."},{"n":62,"t":"İşlediklerinin sonucu olarak başlarına bir musibet gelse hemen sana gelerek, \"Amacımız ancak iyilik yapmak ve uzlaştırmaktı\" diye ALLAH adına yemin ederler."},{"n":63,"t":"ALLAH onların kalplerindekini bilir. Onlara aldırma, onları aydınlat ve kişiliklerini etkileyecek güzel sözler söyle."},{"n":64,"t":"Biz her elçiyi, ALLAH’ın izniyle kendisine itaat edilsin diye gönderdik. Onlar, kişiliklerine zulmettikleri zaman sana gelip ALLAH’tan günahlarının bağışlanmasını dileselerdi ve elçi de onlar için bağışlanma dileseydi, elbette ALLAH’ı Affedici ve Rahim bulacaklardı."},{"n":65,"t":"Hayır, Efendine andolsun, anlaşmazlıklarında seni aralarında hakem kılmadıkça ve verdiğin kararı, kalplerinde bir burukluk duymadan kabul etmedikçe ve tam teslim olmadıkça gerçeği onaylamış olmazlar."},{"n":66,"t":"\"Canınızı adayın\" yahut \"Yurtlarınızdan çıkın\" diye emretmiş olsaydık, pek azı hariç bunu yapmazlardı. Kendilerine öğütleneni uygulasalardı onlar için daha iyi ve daha sağlam olurdu."},{"n":67,"t":"Kendilerine katımızdan büyük bir ödül verirdik."},{"n":68,"t":"Ve onları doğru bir yola iletirdik."},{"n":69,"t":"ALLAH’a ve elçisine uyanlar, ALLAH’ın kendilerine iyilikte bulunduğu peygamberler, doğrulayıcılar, tanıklar ve salihler ile beraberdirler. Onlar ne güzel arkadaştır."},{"n":70,"t":"Bu lütuf ALLAH’tandır. Bilen olarak ALLAH yeter."},{"n":71,"t":"Gerçeği onaylayanlar! Tetikte durun. Bölük bölük ya da topluca harekete geçin."},{"n":72,"t":"İçinizde ağır davrananlar var. Size bir musibet gelirse, \"ALLAH bana iyilik etti de onlarla birlikte (musibete) tanık olmadım\" der."},{"n":73,"t":"ALLAH’tan size bir lütuf erişirse sanki önce aranızda hiçbir dostluk yokmuş gibi, \"Keşke ben de onlarla birlikte olsaydım da büyük bir başarı kazansaydım\" der."},{"n":74,"t":"Dünya hayatını ahirete değişenler ALLAH yolunda savaşsınlar. Kim ALLAH yolunda savaşır, ölür yahut yenerse, kendisine büyük bir ödül vereceğiz."},{"n":75,"t":"Size ne oldu ki \"Efendimiz, bizi halkı zalim olan bu ülkeden kurtar, bize sahip çık, bize yardım et\" diye feryat eden ezilmiş erkekler, kadınlar ve çocuklara rağmen hâlâ ALLAH yolunda savaşmıyorsunuz?"},{"n":76,"t":"Gerçeği onaylayanlar ALLAH yolunda savaşırlar. Kâfirler ise azgınların ve küstahların yolunda savaşırlar. Öyleyse sapkının dostlarıyla savaşın; sapkının planı zayıftır."},{"n":77,"t":"Kendilerine, \"Elinizi savaştan çekin, namazı gözetin, zekâtı verin\" denilenlere dikkat etmedin mi? Kendilerine savaşmaları emredildiğinde, insanlardan ALLAH’tan korkar gibi, belki daha fazla korkmaya başladılar ve \"Efendimiz, neden bize savaşı yükledin, bizi yakın bir zamana kadar erteleyemez miydin!\" dediler. De ki: \"Bu dünyanın varlığı azdır, erdemliler için ahiret daha hayırlıdır; en ufak bir haksızlığa uğratılmayacaksınız.\""},{"n":78,"t":"Nerede olursanız olun, sağlam kalelerde bile olsanız ölüm sizi yakalar. Başlarına iyi bir şey gelse, \"Bu ALLAH tarafındandır\" derler. Kendilerine bir kötülük dokunsa, \"Bu senin tarafındandır\" derler. De ki: \"Hepsi ALLAH tarafındandır.\" Bu topluma ne oluyor ki neredeyse hiçbir hadis (söz) anlamıyorlar!"},{"n":79,"t":"Sana gelen her iyilik ALLAH’tan, sana gelen her kötülük ise kendindendir. Seni insanlara elçi olarak gönderdik. Tanık olarak ALLAH yeter."},{"n":80,"t":"Elçiye uyan ALLAH’a uymuş olur. Kim yüz çevirirse çevirsin; biz seni onların üzerine bekçi göndermedik."},{"n":81,"t":"\"Tamam, itaat ediyoruz\" derler. Ancak senin yanından çıktıklarında onlardan bir takımı, söylemiş olduklarının tersini kuruyor. ALLAH onların planlayıp kurdukları şeyleri kaydediyor. Onlara aldırma; ALLAH’a güven. Destekleyici olarak ALLAH yeter."},{"n":82,"t":"Kuran’ı incelemiyorlar mı? ALLAH’tan başkasının olsaydı onda birçok çelişki bulacaklardı."},{"n":83,"t":"Onlara güvenlik ve tehlikeyle ilgili bir söylenti ulaşsa onu yayarlar. Durumu elçiye ve aralarındaki yetkililere iletselerdi uzmanları onu değerlendirirdi. Size ALLAH’ın lütfu ve rahmeti olmasaydı pek azınız hariç sapkına uyacaktınız."},{"n":84,"t":"ALLAH yolunda savaşmalısın. Sen ancak kendinden sorumlusun. Gerçeği onaylayanları da aynı şeye özendir ki ALLAH kâfirlerin gücünü etkisiz hale getirsin. ALLAH’ın gücü daha şiddetli, cezası daha çetindir."},{"n":85,"t":"Kim bir iyiliğe aracılık ederse kendisi için ondan bir pay var. Kim bir kötülüğe aracılık ederse, kendisi için ondan bir pay var. ALLAH her şeyi kontrol eder."},{"n":86,"t":"Herhangi bir selam ile selamlandığınız zaman daha güzeliyle veya aynen iade ederek selamı alın. Kuşkusuz ALLAH her şeyi hesaba katar."},{"n":87,"t":"ALLAH: O’ndan başka tanrı yoktur. Gerçekleşmesi mutlak olan diriliş gününde sizleri biraraya toplayacaktır. ALLAH’tan daha doğru hadis sahibi kim olabilir?"},{"n":88,"t":"Size ne oluyor da ikiyüzlüler hakkında iki gruba ayrılıyorsunuz? İşlediklerinden ötürü ALLAH onları baş aşağı çevirdi. ALLAH’ın saptırdığını siz mi doğru yola ulaştırmak istiyorsunuz? ALLAH’ın saptırdığı kimseye sen hiçbir yol bulamazsın."},{"n":89,"t":"Sizin de kendileri gibi inkâr etmenizi istediler ki onlarla bir olasınız. ALLAH yolunda harekete geçinceye kadar onlardan kimseyi dost edinmeyin. Size karşı dönerlerse onları yakalayın, onları bulduğunuz yerde öldürün. Onları ne dost ne de yardımcı edinmeyin;"},{"n":90,"t":"Ancak aranızda anlaşma bulunan bir topluluğa katılan, yahut sizinle veya kendi halkıyla savaşmaktan dolayı göğüslerinde sıkıntı duyarak size gelenler hariç… ALLAH dileseydi onları başınıza musallat eder ve onlar da sizinle savaşırdı. Sizi yalnız bırakır, sizinle savaşmaz ve size barış önerirlerse ALLAH sizin onlara saldırmanıza izin vermez."},{"n":91,"t":"Hem sizinle hem kendi toplumlarıyla güven içinde durmak isteyen bir başka grup bulacaksınız. Ne zaman kargaşalığa çağrılsalar içine dalarlar. Sizi yalnız bırakmaz, barış yapmak istemez ve ellerini sizden çekmezlerse karşılaştığınız yerde onları öldürebilirsiniz. Böylelerine karşı size apaçık yetki verdik."},{"n":92,"t":"Gerçeği onaylamış bir kişi, kaza hali hariç gerçeği onaylamış birisini öldüremez. Kim bir gerçeği onaylayanı kazara öldürmüşse gerçeği onaylamış bir köleyi salmalı ve ölenin ailesine diyet ödemeli. Ancak diyetten vazgeçip sadaka olarak kabul ederlerse başka. Öldürülen, sizinle savaş halinde olan bir topluluğa mensup bir gerçeği onaylayan ise, o zaman gerçeği onaylayan bir köleyi salmalısınız. Ancak, maktul aranızda anlaşma olan bir topluluktan ise ailesine diyet vermeli ve gerçeği onaylamış bir köleyi salmalısınız. Kim (gerekli parayı veya salacağı bir köle) bulamıyorsa, ALLAH tarafından tövbesinin kabul edilmesi için iki ay aralıksız oruç tutmalıdır. ALLAH Bilendir, Bilgedir."},{"n":93,"t":"Kim gerçeği onaylamış birisini kasten öldürürse yeri, sürekli kalacağı cehennemdir. ALLAH kendisine gazap ve lanet etmiştir. Ve onun için büyük bir azap hazırlamıştır."},{"n":94,"t":"Gerçeği onaylayanlar, ALLAH yolunda çarpışmaya çıktığınız zaman dikkatli olun. Size barış önerene, dünya hayatının geçici yararını gözeterek \"Sen onaylamıyorsun\" demeyin. Çünkü ALLAH’ın yanında çok ganimetler var. Daha önceleri siz de onlar gibiydiniz; fakat ALLAH size lütfetti. Öyleyse iyice araştırıp emin olun. ALLAH yaptıklarınızdan Haberdardır."},{"n":95,"t":"Yerlerinde oturanlar ile mallarıyla canlarıyla ALLAH yolunda savaşım verenler bir olmaz. ALLAH mallarıyla, canlarıyla savaşım verenleri derece bakımından oturanlardan üstün kıldı. ALLAH hepsine güzellikler söz veriyor. Bununla birlikte, ALLAH savaşım verenleri oturanlar üzerine daha büyük bir ödülle üstün kıldı;"},{"n":96,"t":"Kendi katından derecelerle, bağışlama ve rahmet ile… ALLAH Bağışlayandır, Rahimdir."},{"n":97,"t":"Kendilerine zulmedenlerin canlarını alırken melekler: \"Ne halde idiniz\" derler. \"Bizler yeryüzünde ezilmiş kimselerdik\" diye cevap verirler. \"ALLAH’ın yeri geniş değil miydi ki oralara göç edeydiniz\" derler. Onların yeri cehennem. O ne kötü bir dönüş noktası."},{"n":98,"t":"Ancak, hiçbir çıkış yoluna gücü yetmeyen ve göç etmeye yol bulamayan erkek, kadın ve çocuk ezilmişler hariç."},{"n":99,"t":"Böylelerinin ALLAH tarafından affedilmesi umulur. ALLAH Affedicidir, Bağışlayandır."},{"n":100,"t":"Kim ALLAH yolunda göç ederse yeryüzünde barınacak çok yer ve bolluk bulur. Kim ALLAH’a ve elçisine göç etmek için evinden çıkar ve sonra kendisini ölüm yakalarsa, ödülünü vermek ALLAH’a düşer. ALLAH Bağışlayandır, Rahimdir."},{"n":101,"t":"Yeryüzünde yolculuğa çıktığınız zaman inkârcıların size saldırmasından korkuyorsanız namazı kısaltmanızda bir sakınca yok. Kuşkusuz inkârcılar sizin açık düşmanınızdır."},{"n":102,"t":"Sen içlerinde olup onlara namaz kıldırdığın zaman, onlardan bir grup sizi korumak için yanınızda bulunsun ve silahlarını da yanlarına alsın. Namaza duranlar secdeye vardıklarında arkanızda bulunsunlar. Sonra namaz kılmamış olan grup gelsin ve seninle birlikte namaza dursunlar, diğer grup silahlarını alıp nöbet tutsunlar. İnkârcılar, silahlarınız ve eşyanız hakkında dikkatsiz davranmanızı ve böylece sizi ani bir baskınla bozguna uğratmayı umarlar. Yağmur ve hastalık gibi özürlerden ötürü silahlarınızı bırakmanızda bir sakınca yok. Ancak alarmda olun. ALLAH kâfirlere alçaltıcı bir azap hazırladı…"},{"n":103,"t":"Namazı bitirdiğiniz zaman ayakta, oturarak ve uzanarak ALLAH’ı anın. Güvene kavuştuğunuzda namazı gözetiniz. Namaz, gerçeği onaylayanlar üzerine belirli vakitlerde farz kılınmıştır."},{"n":104,"t":"O topluluğu izlemekte gevşeklik göstermeyin. Siz acı çekiyorsanız onlar da sizin gibi acı çekiyor. Fakat siz, onların ALLAH’tan ummadığını umuyorsunuz. ALLAH Bilendir, Bilgedir."},{"n":105,"t":"Halkın arasında ALLAH’ın sana gösterdiği gibi yargı veresin diye Biz sana gerçeği içeren kitabı indirdik. Hainlerden yana olma."},{"n":106,"t":"ALLAH’tan bağışlanma dile. ALLAH Bağışlayandır, Rahimdir."},{"n":107,"t":"Kendi özlerine hainlik edenleri savunma; ALLAH ihanet edenleri ve günah işleyenleri sevmez."},{"n":108,"t":"Halktan gizlerler ama ALLAH’tan gizleyemezler. Oysa O’nun hoşlanmadığı düşünceleri kurarlarken O onlarla beraberdir. ALLAH onların tüm yaptıklarını Kuşatır."},{"n":109,"t":"İşte sizler bu tür kişileri dünya hayatında savunuyorsunuz. Peki, diriliş gününde ALLAH’a karşı kim onları savunacak? Ya da kim onlara avukat olacak?"},{"n":110,"t":"Kim bir kötülük işler veya özüne zulmeder de sonra ALLAH’tan bağışlanma dilerse ALLAH’ı Bağışlayıcı ve Rahim bulur."},{"n":111,"t":"Kim bir günah kazanırsa kendisine karşı kazanmış olur. ALLAH Bilendir, Bilgedir."},{"n":112,"t":"Kim bir hata yahut bir günah işler de sonra onu bir suçsuzun üzerine atarsa şüphesiz büyük bir iftira ve apaçık bir günah yüklenmiş olur."},{"n":113,"t":"ALLAH’ın sana lütfu ve rahmeti olmasaydı, onlardan bir grup seni saptıracaktı. Onlar, yalnız kendilerini saptırır; sana hiçbir zarar veremezler. ALLAH sana kitap ve bilgeliği indirdi ve sana bilmediğin şeyleri öğretti. ALLAH’ın sana olan lütfu büyüktür."},{"n":114,"t":"Onların gizli görüşmelerinin çoğunda hayır yoktur; sadakayı, iyiliği veya halkın arasını düzeltmeyi savunmaları başka. Kim ALLAH’ın rızasını arayarak bunları yaparsa ona büyük bir ödül vereceğiz."},{"n":115,"t":"Doğru yol kendisine belli olduktan sonra kim elçiye karşı gelir ve gerçeği onaylayanların yolundan farklı bir yol edinirse, seçtiği yöne kendisini yöneltir ve onu cehenneme atarız. Ne kötü bir dönüş noktasıdır orası."},{"n":116,"t":"ALLAH kendisine ortak koşulmasını affetmez; bunun aşağısındaki günahları ise dilediği kişiye affeder. Kim ALLAH’a ortak koşarsa tamamen sapıtmış olur."},{"n":117,"t":"O’ndan ayrı olarak tanrıçalara hizmet ederler. Aslında inatçı sapkından başkasına hizmet etmezler."},{"n":118,"t":"ALLAH ona lanet etmiş ve o da, \"Elbette senin kullarından belli bir pay alacağım\" demişti,"},{"n":119,"t":"\"Onları saptıracağım, onları kuruntularla oyalayacağım, hayvanların kulaklarını yarmalarını (böylece etlerini haram etmelerini) emredeceğim, ALLAH’ın yaratışını/tasarımını değiştirmelerini emredeceğim.\" Kim ALLAH yerine sapkını dost ve egemen edinirse apaçık bir kayba uğramıştır."},{"n":120,"t":"Onlara söz verir, ümit verir. Gerçekte, sapkının onlara verdiği söz kandırmadan başka bir şey değil."},{"n":121,"t":"Varacakları nokta cehennemdir; ondan kaçamazlar."},{"n":122,"t":"Gerçeği onaylayıp erdemli işler yapanları, içlerinde ırmaklar akan bahçelere yerleştireceğiz; orada ebedî kalacaklar. ALLAH’ın sözü gerçektir. ALLAH’tan daha doğru sözlü kim olabilir?"},{"n":123,"t":"Bu, ne sizin kuruntularınız ne de kitap halkının kuruntularına göredir: Kim bir kötülük işlerse karşılığını bulur ve ALLAH’tan başka bir Sahip ve Yardımcı bulamaz."},{"n":124,"t":"Erkek veya kadın, her kim gerçeği onaylayarak erdemli bir hayat sürerse bahçeye girer ve en ufak bir haksızlık görmez."},{"n":125,"t":"ALLAH’a teslim olarak iyilik yapan ve İbrahim’in tek tanrıcı dinine uyandan daha güzel bir dine kim sahip olabilir? ALLAH İbrahim’i arkadaş edindi."},{"n":126,"t":"Yerde ve göktekilerin hepsi ALLAH’ındır. ALLAH her şeyi Kuşatır."},{"n":127,"t":"Sana kadınlar hakkında soruyorlar. De ki: \"ALLAH bu Kitap yoluyla kadınlar hakkında sizi aydınlatıyor. Yasal hakları olan mallarını vermeyip kendileriyle evlenmek istediğiniz kadınların yetimleri ve zavallı çocukları hakkında Kitapta size okunan ayetler yetimlere adaletli davranmanızı emretmektedir. Yaptığınız her iyiliği ALLAH Biliyor.\""},{"n":128,"t":"Bir kadın kocasının iffetsiz davranışından, yahut kendisinden yüz çevirmesinden endişe ediyorsa uzlaşmayla tekrar aralarını düzeltmelerinde bir sakınca yoktur. Uzlaşma daha iyidir. Kişi bencil ve kıskanç davranmaya eğilimlidir. İyilik yapar ve erdemli davranırsanız, elbette ALLAH yaptıklarınızı haber alır."},{"n":129,"t":"Ne kadar isteseniz de kadınlara eşit davranamazsınız. Öyleyse tamamen birine yönelip de diğerini askıdaymış gibi bırakmayın. Bu durumu düzeltip erdemli olursanız ALLAH Bağışlayandır, Rahimdir."},{"n":130,"t":"Çiftler birbirlerinden ayrılırlarsa, her birisini bol nimetiyle yoksulluktan kurtarır. ALLAH Cömerttir, Bilgedir."},{"n":131,"t":"Göklerde ve yerde ne varsa ALLAH’ındır. Sizden önce kendilerine kitap verilenlere de size de, \"ALLAH’ı sayıp dinleyin\" diye öğütledik. İnkâr ederseniz, bilesiniz ki göklerde ve yerde ne varsa ALLAH’ındır. Kuşkusuz ALLAH kimseye muhtaç değildir, övgüye layıktır."},{"n":132,"t":"Göklerde ve yerde ne varsa ALLAH’ındır. Koruyucu olarak ALLAH yeter."},{"n":133,"t":"İnsanlar! O dilerse sizi ortadan kaldırıp başkalarını getirir. ALLAH’ın gücü buna yeter."},{"n":134,"t":"Her kim dünya nimetini isterse, bilsin ki hem dünya hem ahiret nimeti ALLAH’ın yanındadır. ALLAH İşitendir, Görendir."},{"n":135,"t":"Gerçeği onaylayanlar! Kendiniz, ananız, babanız ve yakınlarınız aleyhinde dahi olsa ALLAH için tanıklık ederek adaleti gözetin. İster zengin, ister fakir olsun, ALLAH her iki gruba da bakar. Öyleyse, kişisel çıkar ve duygularınıza uyarak taraflı davranmayın. Gerçeği çarpıtırsanız veya tanıklık etmekten çekinirseniz, bilesiniz ki ALLAH yaptıklarınızı haber alır."},{"n":136,"t":"Gerçeği onaylayanlar! ALLAH’a, elçisine, elçisine indirdiği kitaba ve daha önceden indirdiği kitabı onaylayın. Kim ALLAH’ı, meleklerini, kitaplarını, elçilerini ve ahiret gününü inkâr ederse büsbütün sapıtmış olur."},{"n":137,"t":"Gerçeği onaylayıp sonra inkâr eden, tekrar gerçeği onaylayıp tekrar inkâr eden ve daha sonra inkârlarında ileri giden kimseleri ALLAH affetmeyecek ve onlara yol göstermeyecek."},{"n":138,"t":"İkiyüzlülere acıklı bir azabı müjdele."},{"n":139,"t":"Onlar ki gerçeği onaylayanlara ek olarak inkârcılarla da iş birliği yapar. Onların yanında onur mu arıyorlar? Oysa, onur tümüyle ALLAH’a aittir."},{"n":140,"t":"Size kitapta bildirilmiştir ki: ALLAH’ın ayetlerinin inkâr edilip alaya alındığını işittiğiniz zaman, onlar başka bir söze dalıncaya kadar onlarla birlikte oturmayın; yoksa siz de onlar gibi olursunuz. ALLAH bütün ikiyüzlüleri ve inkârcıları cehennemde toplayacak."},{"n":141,"t":"Onlar sizi gözetleyip dururlar. ALLAH’tan size bir zafer geldiğinde, \"Biz sizinle birlikte değil miydik\" derler. Kazanma sırası inkârcılara gelirse bu sefer, \"Biz size destek olarak sizi gerçeği onaylayanlardan korumadık mı\" derler. Diriliş günü, ALLAH aranızda hüküm verecektir. ALLAH inkârcılara, gerçeği onaylayanlar üzerine egemen olma fırsatını vermeyecek."},{"n":142,"t":"İkiyüzlüler ALLAH’ı aldattıklarını zanneder. Halbuki O, onları aldanmış bırakır. Onlar namaza kalktıklarında üşene üşene kalkar. Çünkü insanlara gösteriş yaparlar ve ALLAH’ı pek az anarlar."},{"n":143,"t":"Arada bocalayıp dururlar; ne bunlara ne de onlara katılırlar. ALLAH’ın şaşırttığına bir yol bulamazsın."},{"n":144,"t":"Gerçeği onaylayanlar, gerçeği onaylayanları bırakıp inkârcıları dost edinmeyin. ALLAH’a, size karşı kullanacağı bir delil mi vermek istiyorsunuz!"},{"n":145,"t":"İkiyüzlüler ateşin en aşağı katındadır. Onlara yardım edecek kimse bulamazsın."},{"n":146,"t":"Ancak tövbe eden, durumunu düzelten, ALLAH’a sarılan ve dinlerini sadece ALLAH’a ait kılanlar başka… Bunlar, gerçeği onaylayanlarla birliktedir. ALLAH gerçeği onaylayanlara daha sonra büyük bir ödül verecek."},{"n":147,"t":"Sizler gerçeği onaylar ve şükrederseniz ALLAH sizi neden cezalandırsın ki? ALLAH Şükredendir, Bilendir."},{"n":148,"t":"ALLAH kötü dil kullanılmasını sevmez. Zulme uğrayanlar başka. ALLAH İşitendir, Bilendir."},{"n":149,"t":"Bir iyiliği açığa vurur veya gizlerseniz, yahut bir kötülüğü affederseniz, ALLAH Affedendir, Güçlüdür."},{"n":150,"t":"ALLAH’a ve elçisine karşı çıkanlar, ALLAH ile elçilerinin arasını ayırmak isteyenler, \"Bir kısmını gerçek olarak onaylayıp bir kısmını inkâr ederiz\" diyenler ve bu ikisi arasında bir yol edinmek isteyenler…"},{"n":151,"t":"İşte bunlar gerçek inkârcılardır. İnkârcılar için acıklı bir azap hazırlıyoruz."},{"n":152,"t":"ALLAH’ı ve elçilerini onaylayan ve onların hiçbiri arasında ayrım yapmayanların da ödüllerini ileride verecek. ALLAH Bağışlayandır, Rahimdir."},{"n":153,"t":"Kitap halkı, senin kendilerine gökten bir kitap indirmeni istiyor. Musa’dan bunun daha büyüğünü istemiş ve, \"Bize ALLAH’ı fiziksel olarak göster\" demişlerdi. Böyle sınırı aşmalarından ötürü onlara yıldırım çarptı. Kendilerine apaçık deliller gelmesine rağmen buzağıya hizmet ettiler. Onları yine affettik. Musa’ya da apaçık bir yetki verdik."},{"n":154,"t":"Kendilerinden söz alırken Sina Dağı’nı üzerlerine yükselttik. Onlara, \"Kapıdan alçak gönüllü olarak girin\" dedik. Onlara, \"Cumartesi yasağını çiğnemeyin\" dedik; onlardan sağlam bir söz aldık."},{"n":155,"t":"Sözlerini bozmalarından, ALLAH’ın ayet ve delillerini inkâr etmelerinden, peygamberleri haksız yere öldürmelerinden ve \"Sabit fikirliyiz\" demelerinden ötürü, evet inkârlarından ötürü ALLAH onların anlayışlarını mühürledi. Bunun için pek azı gerçeği onaylar."},{"n":156,"t":"İnkârlarından ve Meryem hakkında büyük bir yalan uydurmalarından ötürü…"},{"n":157,"t":"Ve ALLAH’ın elçisi \"Meryem oğlu İsa Mesih’i öldürdük\" demelerinden ötürü… Oysa onu öldürmediler ve onu asmadılar; fakat öyle yaptıklarını sandılar. Tüm mezhepler bu konuda kuşku içindedir. Onların bu konuda bir bilgisi yok; sadece zanna uyuyorlar. Kesin olarak onu öldürmediler."},{"n":158,"t":"Tersine, ALLAH onu kendisine yükseltti; ALLAH Üstündür, Bilgedir."},{"n":159,"t":"Kendilerine kitap verilenlerden her biri ölümünden önce bu gerçeği onaylamak zorundadır. Diriliş Günü ise o onlara karşı tanık olacaktır."},{"n":160,"t":"Yahudilerin işledikleri zulümlerden ve birçok kişiyi ALLAH yolundan çevirmelerinden dolayı kendilerine daha önce helal kılınmış temiz nimetleri yasakladık."},{"n":161,"t":"Menedildikleri halde tefecilik yapmalarından ve halkın parasını haksızlıkla yemelerinden ötürü… Onların inkârcılarına acıklı bir azap hazırladık."},{"n":162,"t":"Ancak aralarındaki derin ilim sahipleri ve gerçeği onaylayanlar, sana indirileni ve senden önce indirilenleri onaylar. Namazı gözetir, zekâtı verir, ALLAH’ı ve ahiret gününü onaylarlar; bunlara büyük bir ödül vereceğiz."},{"n":163,"t":"Nuh’a ve ondan sonra gelen peygamberlere vahyettiğimiz gibi sana da vahyettik. İbrahim’e, İsmail’e, İshak’a, Yakup’a ve soyuna, İsa’ya, Eyyup’a, Yunus’a, Harun’a ve Süleyman’a da vahyetmiş, Davut’a da Zebur vermiştik."},{"n":164,"t":"Sana önceden anlattığımız elçilere ve anlatmadığımız elçilere de… Ve ALLAH Musa ile de kelimelerle konuşmuştu."},{"n":165,"t":"Müjdeler ve uyarılar getiren elçiler… Ki tüm bu elçilerden sonra insanların ALLAH’a karşı bir bahaneleri kalmasın. ALLAH Üstündür, Bilgedir."},{"n":166,"t":"Fakat ALLAH, sana indirdiğine tanıklık eder. Onu kendi bilgisiyle indirdi. melekler de buna tanıklık eder. Tanık olarak ALLAH yeter."},{"n":167,"t":"İnkâr edenler ve ALLAH’ın yolundan alıkoyanlar tamamıyla sapıtmışlardır."},{"n":168,"t":"İnkâr edip zulmedenleri ALLAH ne bağışlayacak, ne de onlara bir yol gösterecektir."},{"n":169,"t":"Yalnız cehennemin yolu hariç. Orada sürekli kalacaklar. Bu, ALLAH’a pek kolaydır."},{"n":170,"t":"İnsanlar! Elçi Efendinizden gerçeği getirmiştir. Kendi yararınız için onaylamalısınız. İnkâr ederseniz, bilin ki göklerde ve yerde ne varsa ALLAH’ındır. ALLAH Bilendir, Bilgedir."},{"n":171,"t":"Kitaplılar! Dininizde sınırı aşmayın. ALLAH hakkında yalnız gerçeği söyleyin. Meryem oğlu İsa Mesih, sadece ALLAH’ın elçisi ve Meryem’e gönderdiği kelimesi ve O’ndan gelen bir candır. ALLAH’a ve elçilerini onaylayın. \"Üçtür\" demeyin. Kendi yararınız için buna son verin. Biricik tanrı yalnız ALLAH’tır. O, çocuk sahibi olmaktan yücedir. Göklerde ve yerde ne varsa O’nundur. Vekil olarak ALLAH yeter."},{"n":172,"t":"Ne Mesih, ne de yakın melekler ALLAH’ın kulu olmayı küçüklük saymaz. Kim O’na kulluğu küçük görür de büyüklük taslarsa, bilsin ki O, onların hepsini huzuruna toplayacak."},{"n":173,"t":"Gerçeği onaylayıp erdemli davrananların ödüllerini eksiksiz ödeyecek ve lütfundan onlara daha fazla verecektir. Küçümseyip kibirlenenleri ise acıklı bir azapla cezalandıracak. Kendilerine ALLAH’tan başka ne bir sahip ve ne de bir yardımcı bulamayacaklardır."},{"n":174,"t":"İnsanlar! Efendinizden size bir kanıt geldi ve üzerinize apaçık bir ışık indirdik."},{"n":175,"t":"ALLAH’ı onaylayıp O’na sarılanları ise kendi rahmetine ve lütfuna kabul edecek, onları dosdoğru bir yola sokarak kendisine yöneltecektir."},{"n":176,"t":"Sana danışıyorlar. De ki: \"ALLAH size eşsiz ve çocuksuz olan kişinin mirası hakkında şu hükmü açıklıyor: Ölen erkeğin çocuğu olmayıp bir kız kardeşi varsa, bıraktığı mirasın yarısı kız kardeşinindir. Fakat, (ölen kişi) çocuğu olmayan kız kardeşse, erkek kız kardeşinin mirasının tamamını alır. Varisler iki kız kardeş ise, bırakılanın üçte ikisi onlarındır. Kardeşler, erkeklerden ve kadınlardan oluşuyorsa, erkeğe kadının iki katı kadar pay verilir.\" Şaşırmamanız için ALLAH size böylece açıklıyor. ALLAH her şeyi Bilendir."}]},{"id":5,"name":"Maide Suresi","verses":[{"n":1,"t":"Gerçeği onaylayanlar, anlaşmalarınızı uygulayın. Size okunacak olanların dışındaki hayvanlar size helal kılındı. Yalnız yasaklı iken avlanmayı helal saymamak koşuluyla… ALLAH dilediği hükmü verir."},{"n":2,"t":"Gerçeği onaylayanlar! Ne ALLAH’ın koyduğu dinsel törenlere, ne sınırlanmış aya, ne kurbana, ne onları işaretleyen çelenklere ve ne de Rab’lerinin lütuf ve rızasını aramak için Sınırlanmış Ev’e doğru yola çıkanlara saygısızlık etmeyin. İhramdan çıktığınız zaman avlanabilirsiniz. Sizi Sınırlanmış Mescit’ten çeviren bir topluluğa olan kininizden dolayı provokasyona gelip saldırganlaşmayın. İyilik ve erdemlilikte yardımlaşın. Kötülük ve düşmanlıkta yardımlaşmayın. ALLAH’ı dinleyin. ALLAH’ın cezası çetindir."},{"n":3,"t":"Leş, kan, domuzun eti ve ALLAH’tan başkasına adananlar size haram kılındı. Canları çıkmadan kesmeniz hariç, boğulmuş, vurulmuş, düşmüş, boynuzlanmış ve canavar tarafından yenmiş hayvanlar, putlaştırılmış taşlar üzerinde boğazlanarak fal oklarıyla dağıtılanlar, evet bunlar kötüdür. Bugün size dininizi olgunlaştırdım, size nimetimi tamamladım ve size din olarak İslam’ı beğendim. İnkarcılar bugün dininizden umut kesmişlerdir. Onlardan çekinmeyin; benden çekinin. Kim açlıktan dolayı zorda kalırsa, günaha istekle yönelmeden yerse ona günah yoktur. Çünkü ALLAH Bağışlayandır, Rahimdir."},{"n":4,"t":"Kendilerine neyin helal olduğunu sana soruyorlar. De ki: \"Size temiz yiyecekler helal edilmiştir. ALLAH’ın size öğrettiğinden öğreterek yetiştirdiğiniz köpek ve şahin gibi avcı hayvanların sizin için yakaladıklarını da yiyin ve üzerlerinde ALLAH’ın ismini anın.\"ALLAH’ı dinleyin. ALLAH hesabı çabuk görür."},{"n":5,"t":"Bugün size iyi ve temiz şeyler helal kılındı. Kitap halkının yiyeceği size helaldir. Sizin de yiyecekleriniz onlara helaldir. Mehirlerini ödemeniz, zina etmeyip namuslu davranmanız ve gizli dost tutmamanız koşuluyla, gerçeği onaylayanlardan korunmuş kadınlarla ve sizden önce kendilerine kitap verilenlerden korunmuş kadınlarla evlenmeniz size helaldir. Kim gerçeği onaylamayı reddederse tüm yaptıkları boşa çıkmıştır ve o, ahirette de kaybedenlerdendir."},{"n":6,"t":"Gerçeği onaylayanlar! Namaza kalktığınız zaman, yıkayınız: Yüzünüzü, dirseklere kadar ellerinizi. Sıvazlayınız: Başınızı. Ayaklarınızı da topuklara kadar... Cinsel ilişkide bulunmuşsanız yıkanınız. Hasta veya yolcu iseniz, yahut tuvaletten gelmiş, yahut kadınlarla cinsel ilişkide bulunmuş ve su bulamamışsanız, temiz bir toprağa yönelip yüzünüzü ve ellerinizi onunla sıvazlayın. ALLAH size güçlük çıkarmak istemez. Ancak sizi temizlemek ve üzerinizdeki nimetini tamamlamak istiyor. Olur ki şükredersiniz."},{"n":7,"t":"ALLAH’ın üzerinizdeki nimetini ve O’nunla yaptığınız sözleşmeyi hatırlayın: \"İşittik ve itaat ettik\" demiştiniz. ALLAH’ı dinleyin; ALLAH içinizde olanları biliyor."},{"n":8,"t":"Gerçeği onaylayanlar! ALLAH için adaleti gözeterek tanıklık edin. Bir topluluğa olan kininiz sizi adaletli davranmaktan alıkoymasın. Adaletli davranın; bu erdemliliğe daha yakındır. ALLAH’ı dinleyin. ALLAH yaptıklarınızı haber alır."},{"n":9,"t":"ALLAH, Gerçeği onaylayıp iyi işler yapanlara bir bağışlanma ve büyük bir ödülü söz verdi."},{"n":10,"t":"İnkâr edip ayetlerimizi yalanlayanlara gelince, onlar cehennem halkıdır."},{"n":11,"t":"Gerçeği onaylayanlar! ALLAH’ın size olan nimetini hatırlayın: Hani bir topluluk size el uzatmaya yeltenmişti de onların ellerini sizden çekmişti. ALLAH’ı dinleyin. Gerçeği onaylayanlar ALLAH’a güvensin."},{"n":12,"t":"ALLAH, İsrailoğullarından söz almıştı ve içlerinden on iki başkan göndermiştik. ALLAH demişti ki: \"Namazı gözetirseniz, zekâtı verirseniz, elçilerimi onaylayıp onlara saygılı olursanız ve ALLAH’a güzel bir borç verirseniz sizinle beraberim. Günahlarınızı örter, içlerinden ırmaklar akan bahçelerde ağırlarım. Artık sizden kim bundan sonra inkâr ederse doğru yolu sapıtmış olur.\""},{"n":13,"t":"Sözlerini bozdukları için onları lanetledik, kalplerini katılaştırdık. Sözlerin anlamını bağlamından kaydırırlar. Uyarıldıkları şeylerin bir kısmını unuttular. Onların çoğundan sürekli ihanet göreceksin. Onları affet ve aldırma. ALLAH güzel davrananları sever."},{"n":14,"t":"\"Biz Hıristiyan’ız\" diyenlerden de söz almıştık. Ancak onlar da uyarıldıkları şeylerin bir kısmını unuttu. Bu yüzden diriliş gününe kadar aralarına düşmanlık ve kin saldık. Yaptıkları her şeyi ALLAH onlara bildirecek."},{"n":15,"t":"Kitap halkı, kitabın gizlediğiniz birçok bölümünü açığa çıkaran ve birçoğunu da yüzünüze vurmayan elçimiz geldi size. ALLAH’tan bir ışık ve apaçık bir kitap da geldi size."},{"n":16,"t":"Onunla ALLAH, rızasını gözetenleri barış ve huzur yollarına ulaştırır, izniyle onları karanlıklardan aydınlığa çıkararak onları dosdoğru yola iletir."},{"n":17,"t":"\"ALLAH Meryem oğlu Mesih’tir\" diyenler elbette kâfir olmuşlardır. De ki: \"ALLAH Meryem oğlu Mesih’i, annesini ve hatta yeryüzündekilerin tümünü helak etmek isterse, kim buna engel olabilir?\" Göklerin, yerin ve arasındakilerin egemenliği ALLAH’a aittir. Dilediğini yaratır. ALLAH her şeye Gücü Yetendir."},{"n":18,"t":"Yahudiler ve Hıristiyanlar, \"Biz ALLAH’ın çocukları ve sevgilileriyiz\" dediler. \"Öyleyse günahlarınızdan ötürü neden sizi cezalandırıyor? Siz sadece O’nun yarattığı insanlardansınız\" de. Dileyeni/dilediğini de bağışlar, dileyeni/dilediğini de cezalandırır. Göklerin, yerin ve bunlar arasındakilerin egemenliği ALLAH’a ait olup dönüş de O’nadır."},{"n":19,"t":"Kitap halkı! Elçiler arasındaki bir boşluk döneminden sonra size elçimiz gelmiş bulunuyor ve size gerçekleri anlatıyor ki \"Bize bir müjdeleyici ve uyarıcı gelmedi\" demeyesiniz. Oysa size bir müjdeleyici ve uyarıcı gelmiş bulunuyor. ALLAH her şeye Gücü Yetendir."},{"n":20,"t":"Musa, halkına şöyle demişti: \"Ey halkım, ALLAH’ın üzerinizdeki nimetini hatırlayın: aranızdan peygamberler çıkardı, sizi özgür kimseler kıldı ve toplumların hiçbirine vermediğini size verdi.\""},{"n":21,"t":"\"Halkım! ALLAH’ın size ayırdığı kutsal toprağa girin. Geri dönmeyin, yoksa kaybedersiniz.\""},{"n":22,"t":"Dediler ki: \"Musa, orada zorba bir topluluk var. Onlar oradan çıkmadıkça biz asla oraya girmeyiz. Çıkarlarsa gireriz.\""},{"n":23,"t":"Korku duyanların arasında, ALLAH’ın kendisine nimet verdiği iki kişi, \"Üstlerine kapıdan yürüyün. Kapıdan girerseniz kesinlikle siz yeneceksiniz. Gerçeği onaylıyorsanız ALLAH’a güvenin\" dedi."},{"n":24,"t":"\"Musa, onlar orada oldukça biz oraya asla girmeyiz. Sen ve Efendin gidip savaşın; biz burda oturuyoruz\" dediler."},{"n":25,"t":"O da bunun üzerine: \"Efendim, ben ancak kendime ve kardeşime söz geçirebiliyorum. Bizimle yoldan çıkmış bu topluluğun arasını ayır\" dedi."},{"n":26,"t":"Dedi ki: Orası onlara kırk yıl boyunca yasaklanmıştır; yeryüzünde şaşkın şaşkın dolaşacaklar. Yoldan çıkmış bir topluluk için üzme kendini."},{"n":27,"t":"Onlara Adem’in iki oğlunun olayını doğru anlat. Birer kurban adamışlardı da, birisinden kabul edilmiş, diğerinden edilmemişti. \"Seni öldüreceğim!\" dedi. \"ALLAH ancak erdemli olanlardan kabul eder\" dedi."},{"n":28,"t":"\"Beni öldürmek için elini bana uzatırsan, seni öldürmek için ben elimi sana uzatmayacağım. Ben, tüm yaratıkların sahibi ALLAH’tan korkarım.\""},{"n":29,"t":"\"Günahımı günahınla birlikte yüklenerek cehenneme girmeni isterim. Zalimler böyle cezalandırılır.\""},{"n":30,"t":"Egosu onu, kardeşini öldürmeye kışkırttı. Onu öldürdü ve böylece kaybetti."},{"n":31,"t":"ALLAH kardeşinin cesedini nasıl gömeceğini göstermek için yeri eşeleyen bir karga gönderdi. \"Yazık bana; kardeşimin cesedini gömme konusunda bu karga kadar bile olamadım\" diyerek pişman oldu."},{"n":32,"t":"Bunun için İsrailoğullarına şunu yazdık: Kim, cinayet işlememiş veya yeryüzünde bozgunculuk yapmamış bir kişiyi öldürürse tüm insanları öldürmüş gibidir. Kim de o canı yaşatırsa, bütün insanları yaşatmış gibi olur. Elçilerimiz onlara apaçık delillerle geldiler. Buna rağmen onların çoğu hemen sonra yeryüzünde azgınlık yapmaya başladılar."},{"n":33,"t":"ALLAH ve elçisi ile savaşan ve yeryüzünde bozgunculuk için uğraşanların cezası: Öldürülmeleri veya asılmaları veya el ve ayaklarının çaprazlama kesilmesi veya yerlerinden sürülmeleridir. Bu, dünyada görecekleri bir aşağılanma. Ahirette ise büyük bir ceza var."},{"n":34,"t":"Kendilerini yakalamadan önce tövbe edenler başka. Bilesiniz ki ALLAH Bağışlayandır, Rahimdir."},{"n":35,"t":"Gerçeği onaylayanlar ALLAH’ı dinleyin, O’na ulaşmak için yol arayın ve O’nun yolunda cihat edin ki başarasınız."},{"n":36,"t":"İnkârcılar, yeryüzündekilerin hepsine ve bir o kadarına da sahip olsalardı ve onları diriliş gününün azabından kurtulmak için fidye verselerdi kendilerinden kabul edilmezdi. Onlara acıklı bir azap var."},{"n":37,"t":"Ateşten çıkmak isterler; ama çıkamazlar. Onlar sürekli bir cezaya mahkûm olmuşlardır."},{"n":38,"t":"Erkek hırsızın ve kadın hırsızın ellerini, yaptıklarına karşılık kesin. Bu ALLAH’ın öngördüğü bir caydırma yöntemidir. ALLAH Güçlüdür, Bilgedir."},{"n":39,"t":"Kim yaptığı bu haksızlıktan sonra tövbe ederek düzelirse, ALLAH yönelişini kabul eder. ALLAH kuşkusuz Bağışlayandır, Rahimdir."},{"n":40,"t":"Göklerin ve yerin egemenliğinin ALLAH’a ait olduğunu bilmez misin? Dilediğine azap eder, dilediğini bağışlar. ALLAH her şeye Gücü Yetendir."},{"n":41,"t":"Ey elçi, ağızlarıyla \"Onayladık\" dedikleri halde kalpleriyle onaylamayanların inkârcılıktaki gayretleri seni üzmesin. Yahudilerin bir grubu var ki yalana kulak veriyor, seninle hiç karşılaşmamış bir topluluğu dinliyor. Kelimelerin anlamını kaydırıp: \"Size bu verilirse alın, bu verilmezse sakının\" diyorlar. ALLAH birini sınamak isterse ALLAH’a karşı kimse ona yardım edemez. İşte onlar, ALLAH’ın kalplerini temizlemeyi dilemediği kişiler. Onlar için dünyada aşağılanma ve ahirette de büyük bir azap var."},{"n":42,"t":"Yalana kulak veriyor, yasa dışı yoldan yiyorlar. Sana gelirlerse, ister aralarında hüküm ver, istersen yüz çevir. Onlardan yüz çevirdiğin taktirde sana hiçbir zarar veremezler. Hüküm verirsen, aralarında adaletle hüküm ver. ALLAH adaletli olanları sever."},{"n":43,"t":"İçinde ALLAH’ın hükmü bulunan Tevrat yanlarında dururken nasıl olur da ondan yüz çevirip de seni hakem yapıyorlar? Onlar aslında gerçeği onaylamıyor."},{"n":44,"t":"İçinde hidayet ve ışık bulunan Tevrat’ı biz indirdik. Müslüman peygamberler onunla Yahudiler arasında hüküm veriyorlardı. Hahamlar ve din bilginleri de ALLAH’ın kitabından emredildikleri şeylerle hüküm verirler ve onun üzerine tanık olurlardı. Halkı yüceltmeyin, beni yüceltin ve ayetlerimi ucuz bir fiyata satmayın. ALLAH’ın indirdiği ile hüküm vermeyenler inkârcıdır."},{"n":45,"t":"Orada onlara: Cana can, göze göz, buruna burun, kulağa kulak, dişe diş ve yaralara ödeşmeyi emrettik. Kim bu hakkından vazgeçerse günahlarını örter. ALLAH’ın indirdiği ile hüküm vermeyenler zalimdir."},{"n":46,"t":"Onların ardından, önceki Tevrat’ı doğrulayıcı olarak Meryem oğlu İsa’yı gönderdik. Ona, içinde hidayet ve ışık bulunan, önceki Tevrat’ı doğrulayan ve erdemliler için bir kılavuz ve öğüt olan İncil’i verdik."},{"n":47,"t":"İncil halkı ALLAH’ın onda indirdiğiyle hüküm versin. Kim ALLAH’ın indirdiği ile hüküm vermezse işte onlar yoldan çıkanlardır."},{"n":48,"t":"Kendinden önceki kitapları doğrulayan, onların yerine geçen bu kitabı, gerçekleri kapsayıcı olarak sana indirdik. ALLAH’ın sana indirdiğiyle aralarında hüküm ver. Sana gelen gerçekleri bırakıp onların hevesine uyma. Her biriniz için bir yasa ve yöntem belirledik. ALLAH dileseydi hepinizi bir tek toplum yapardı. Ancak, size verdikleriyle sizleri sınıyor. İyilikte yarışın. Hepinizin dönüşü ALLAH’adır. Ayrılığa düştüğünüz konuları size bildirecek."},{"n":49,"t":"Aralarında ALLAH’ın indirdiği ile hüküm vermelisin. Onların keyfine uyma. ALLAH’ın sana indirdiklerinin bir kısmından sakın seni şaşırtmasınlar. Yüz çevirirlerse, demek ki ALLAH bazı günahları yüzünden onları cezalandırmak istiyor. Gerçekten insanların çoğu yoldan çıkmıştır."},{"n":50,"t":"Yoksa cahillik dönemindeki yasaları mı arıyorlar? Kuşkusuz bir bilgiye sahip olanlar için ALLAH’tan daha güzel yasa koyucu olabilir mi?"},{"n":51,"t":"Gerçeği onaylayanlar, Yahudileri ve Hıristiyanları dost edinmeyin. Onlar birbirlerinin dostudur. Sizden kim onlarla dost olursa onlardan sayılır. ALLAH zalim toplumu doğru yola iletmez."},{"n":52,"t":"Kalplerinde hastalık bulunanların, \"Başımıza bir bela gelmesinden korkuyoruz\" diyerek onların arasında dolanıp durduklarını göreceksin. Olur ki ALLAH, zaferi veya kendi tarafından bir emri getirir de, içlerinde gizledikleri düşüncelerinden dolayı pişman olurlar."},{"n":53,"t":"O zaman gerçeği onaylayanlar, \"Sizinle beraber olduklarına bütün güçleriyle ALLAH adına yemin edenler bunlar mı\" diyecek. Çabaları boşa çıkmış ve zarar etmişlerdir."},{"n":54,"t":"Gerçeği onaylayanlar, kim dininden dönerse şunu bilsin: ALLAH sevdiği bir toplumu getirir; onlar da O’nu sever. Gerçeği onaylayanlara karşı alçak gönüllü, kâfirlere karşı güçlü ve pektirler. ALLAH yolunda cihat ederler, kınayanın kınamasından çekinmezler. Bu, ALLAH’ın lütfudur; onu dilediğine verir. ALLAH Cömerttir, Bilendir."},{"n":55,"t":"Gerçek dostlarınız, ALLAH, elçisi ve namazı gözetip alçak gönüllü olarak zekâtı veren müminlerdir."},{"n":56,"t":"Kim ALLAH’ı, elçisini ve gerçeği onaylayanları dost edinirse bilsin ki ALLAH’ın partisi üstün gelecek."},{"n":57,"t":"Gerçeği onaylayanlar, sizden önceki kitap halkı ve inkârcılar arasında dininizi alay ve eğlence konusu yapanları dost edinmeyin. Onaylamış iseniz ALLAH’ı dinlemelisiniz."},{"n":58,"t":"Namaza çağırdığınızda onunla alay edip eğlendiler. Düşünmeyen bir topluluktur onlar."},{"n":59,"t":"De: \"Kitaplılar! ALLAH’ı, bize indirileni ve önceki indirilenleri onayladık diye mi yoldan çıkmış olan çoğunluğunuzla bize karşı nefret besliyorsunuz?\""},{"n":60,"t":"De: \"ALLAH katında bundan daha kötü bir durumu size bildireyim mi? ALLAH kime lanet ve gazap ederek maymunlar, domuzlar, azgınların ve küstahların kulları haline sokmuşsa, işte o kimseler yer bakımından daha kötü ve doğru yoldan en çok sapmış olanlardır."},{"n":61,"t":"Size geldiklerinde, \"Gerçeği onayladık\" dediler. Oysa yanınıza inkârlarıyla girip inkârlarıyla çıkmışlardı. Onların gizlediklerini ALLAH daha iyi biliyor."},{"n":62,"t":"Onların çoğunu günahta, düşmanlıkta ve haram yemekte koşuşurken görürsün. Yaptıkları ne kötü!"},{"n":63,"t":"Hahamları ve din adamları onları bu günah sözleri söylemekten, haram yemekten menetmeli değil miydi? İşledikleri ne fena!"},{"n":64,"t":"Yahudiler \"ALLAH’ın eli bağlı\" dedi. Aslında elleri bağlı olanlar kendileri. Söylediklerinden ötürü lanetlendiler. Halbuki O’nun iki eli de açık olup dilediği gibi harcamakta. Efendinden sana indirilenler çoğunun azgınlığını ve inkârını arttıracak. Diriliş Gününe kadar aralarına düşmanlık ve kin saldık. Her ne zaman savaş için ateş yaksalar ALLAH onu söndürmüştür. Yeryüzünde bozgunculuk yapmak için dolaşırlar. ALLAH ise bozguncuları sevmez."},{"n":65,"t":"Kitap halkı gerçeği onaylayıp erdemli davransa günahlarını örterek onları bol nimetli bahçelere yerleştirirdik."},{"n":66,"t":"Tevrat’ı, İncil’i ve kendilerine indirilenleri uygulasalardı onları baştan ayağa nimetlere boğardık. İçlerinde ılımlı bir toplum varsa da çoğu kötülük işlemekte."},{"n":67,"t":"Elçi, Efendinden sana indirileni duyur. Bunu yapmazsan O’nun elçiliğini duyurmamış olursun. ALLAH seni halktan koruyacak. ALLAH inkârcıları doğru yola iletmez."},{"n":68,"t":"De, \"Kitaplılar! Tevrat’ı, İncil’i ve Efendinizden size indirileni uygulamadıkça hiçbir dayanağınız olmaz.\" Efendinden sana indirilenler, onların çoğunun azgınlık ve inkârını arttırır. İnkârcı toplum için kendini üzme."},{"n":69,"t":"Gerçeği onaylayanlar, Yahudiler, diğer dinlerden olanlar ve Hıristiyanlardan kim ALLAH’ı ve ahiret gününü onaylar ve erdemli bir yaşam sürerse onlar için bir korku yoktur ve onlar üzülmeyecekler de…"},{"n":70,"t":"İsrailoğullarından söz almış, onlara elçiler göndermiştik. Her ne zaman hoşlarına gitmeyen bir şeyle onlara bir elçi gittiyse bir kısmını yalanlayıp bir kısmını da öldürdüler."},{"n":71,"t":"Test edilmeyeceklerini sandılar, körleşip sağırlaştılar. Sonra ALLAH yönelişlerini kabul etti; fakat buna rağmen çoğu yine körleşip sağırlaştı. ALLAH Yaptıklarını görmekte."},{"n":72,"t":"\"ALLAH, Meryem oğlu Mesih’tir\" diyenler elbette inkâr etmiştir. Oysa Mesih, \"İsrailoğulları! benim de sizin de Efendiniz olan ALLAH’a kul olun\" demişti. Kim ALLAH’a ortak koşarsa ALLAH ona bahçeyi yasaklar, yeri de ateş olur. Zalimler için yardımcı da bulunmaz."},{"n":73,"t":"\"ALLAH, üçün üçüncüsüdür\" diyenler inkâr etmiştir. Oysa bir tek Tanrı’dan başka tanrı yok. Bu sözlerine son vermezlerse, inkârcılarına acıklı bir azap dokunacak."},{"n":74,"t":"Hâlâ ALLAH’a yönelip ondan bağışlanma dilemeyecekler mi? ALLAH Bağışlayandır, Rahimdir."},{"n":75,"t":"Meryem oğlu Mesih elçiden başka bir şey değildi. Ondan önce de nice elçiler gelip geçmişti. Annesi de doğru sözlüydü. Her ikisi de yemek yerdi. Ayetlerimizi onlara nasıl açıkladığımıza dikkat et de buna rağmen nasıl da yüz çevirmekte olduklarını gör!"},{"n":76,"t":"De, \"ALLAH’tan başka, size zarar ve yarar veremeyenlere mi hizmet ediyorsunuz? ALLAH İşitir, Bilir.\""},{"n":77,"t":"De, \"Kitaplılar, dininiz konusunda gerçeğin ötesine gitmeyin. Daha önce sapan, çok kimseyi de saptıran, böylece doğru yolu kaybeden bir topluluğun heveslerini izlemeyin."},{"n":78,"t":"İsrailoğullarının inkârcıları, hem Davut’un hem Meryem oğlu İsa’nın diliyle lanetlenmişti. Zira onlar isyan edip sınır tanımıyorlardı."},{"n":79,"t":"Yaptıkları kötülükler konusunda birbirlerini uyarmıyorlardı. Yaptıkları ne kötü idi."},{"n":80,"t":"Çoklarının inkârcılarla dost olduğunu görürsün. Nefislerinin kendileri için gönderdiği şey ne kötü. ALLAH onlara gazap etmiştir; azapta sürekli kalacaklar."},{"n":81,"t":"ALLAH’ı, peygamberi ve ona indirileni onaylasalardı onları dost edinmezlerdi. Ne var ki, çoğu yoldan çıkmış bulunuyor."},{"n":82,"t":"İnsanlar arasında gerçeği onaylayanların en azılı düşmanı olarak Yahudileri ve müşrikleri bulacaksın. Gerçeği onaylayanlara sevgice en yakınları da \"Biz Hıristiyan’ız\" diyenleri bulursun. Çünkü onlar arasında büyüklük taslamayan papazlar ve rahipler var."},{"n":83,"t":"Elçiye inenleri işittiklerinde, gerçeği tanımalarından ötürü gözlerinin yaşla dolup taştığını görürsün. Derler ki, \"Efendimiz, gerçeği onayladık, bizi tanıklardan say.\""},{"n":84,"t":"\"Efendimizin bizi iyiler arasına katmasını umduğumuz halde neden ALLAH’ı ve bize ulaşan gerçeklere onaylamayalım?\""},{"n":85,"t":"Bu sözlerinden ötürü ALLAH onlara, içlerinde ırmaklar akan ve sürekli kalacakları bahçeler verdi. İyi davrananların karşılığı budur."},{"n":86,"t":"İnkâr edip ayet ve mucizelerimizi yalanlayanlar ise cehennem halkı."},{"n":87,"t":"Gerçeği onaylayanlar, ALLAH’ın size helal yaptığı iyi şeyleri haram etmeyin. Sınırı aşmayın. ALLAH sınırı aşanları sevmez."},{"n":88,"t":"ALLAH’ın size rızık olarak verdiklerini, helal ve temiz olarak yiyin. Onayladığınız ALLAH’ı dinleyin."},{"n":89,"t":"ALLAH rastgele ettiğiniz yeminlerden sizi sorumlu tutmaz. Ancak bile bile ettiklerinizden sizi sorumlu tutar. Yemininizi bozarsanız cezası, ailenize genellikle yedirdiğiniz yemeklerden on yoksulu doyurmak veya giydirmek veya bir köleyi salmaktır. Kim bulamazsa üç gün oruç tutmalı. Bu, bile bile ettiğiniz yeminlerinizin cezası. Yeminlerinizi tutun. ALLAH güzel karşılık veresiniz diye ayetlerini böyle açıklıyor."},{"n":90,"t":"Gerçeği onaylayanlar, sarhoş edici maddeler, kumar, putlaştırılmış taş ve türbeler, şans oyunları sapkın işi birer pisliktir. Bunlardan sakının ki kurtulasınız."},{"n":91,"t":"Sapkın, sarhoş edicilerle, kumarla aranıza düşmanlık ve kin sokmak, sizi ALLAH’ı anmaktan, namazdan alıkoymak ister. Artık vazgeçiyorsunuz değil mi?"},{"n":92,"t":"ALLAH’a uyun, elçiye uyun, dikkatli olun. Yüz çevirirseniz bilesiniz ki elçimize düşen görev, açıkça bildirmektir."},{"n":93,"t":"Gerçeği onaylayıp erdemli işler yapanlar, emirlere uyarak gerçeği onaylayıp erdemli davrandıkları, günahlardan sakınıp onayladıkları ve yine sakınıp iyilik yaptıkları sürece yediklerinden ötürü kendilerine bir günah yoktur. ALLAH iyi davrananları sever."},{"n":94,"t":"Gerçeği onaylayanlar, ellerinizin ve mızraklarınızın ulaşacağı avlarla ALLAH sizi sınayacak ki yalnızken de kendisinden korkanları ALLAH ayırsın. Kim bundan sonra sınırı aşarsa onun için acıklı bir azap var."},{"n":95,"t":"Gerçeği onaylayanlar, yasaklıyken/sınırlanmışken av hayvanı öldürmeyin. Sizden kim kasten onu öldürürse cezası, aranızdan iki adaletli kişinin kararlaştıracağı ona denk bir evcil hayvanı hediye olarak Kâbe’ye göndermesidir. Yahut ceza olarak, yoksulları doyurması ya da buna denk oruç tutması gerekir. Böylece yaptığının vebalini tatmış olsun. Geçmiştekileri ALLAH affetti. Kim bunu tekrarlarsa ALLAH ondan öç alır. ALLAH Üstündür, Öç alandır."},{"n":96,"t":"Deniz hayvanlarını avlamak ve onları yemek size helal kılındı. Size ve yolculara geçimlik olmak üzere… İhramlı bulunduğunuz sürece kara avı size yasaklandı. Huzuruna toplanacağınız ALLAH’ı dinleyin."},{"n":97,"t":"ALLAH, sınırlanmış ev Kâbe’yi, sınırlanmış ayları, adakları ve onları işaretleyen çelenkleri, insanlar için güvenlik unsuru yaptı. Bilesiniz ki ALLAH göklerde ve yerde olanları biliyor. ALLAH her şeyi Bilir."},{"n":98,"t":"Bilin ki ALLAH’ın cezası çetindir. ALLAH Bağışlayandır, Rahimdir."},{"n":99,"t":"Elçiye düşen görev sadece duyurmak. ALLAH ise açıkladıklarınızı da gizlediklerinizi de bilir."},{"n":100,"t":"De: \"Kötü ile iyi bir olmaz; kötünün çokluğu ilgini çekse bile… Akıl sahipleri, başarmak istiyorsanız ALLAH’ı dinleyin.\""},{"n":101,"t":"Gerçeği onaylayanlar, açıklandığı vakit hoşunuza gitmeyecek şeyler hakkında sorular sormayın. Kuran’ın ışığında sorarsanız size açık olurlar. ALLAH özellikle onlardan söz etmedi. ALLAH Bağışlayandır, Yumuşaktır."},{"n":102,"t":"Sizden önce bir topluluk o tip soruları sordu da, o sorularından dolayı inkârcı oldular."},{"n":103,"t":"Belli bir erkek ve dişi kombinasyonuyla yavrulayanların, yemin sonucu salıverilenlerin, arka arkaya iki erkek doğuranların ve on kez döl veren erkek develerin haram edilişini ALLAH onaylamıyor; inkârcılar ALLAH’a iftira ediyor. Çoğu akletmez onların."},{"n":104,"t":"Kendilerine, \"ALLAH’ın indirdiğine ve elçiye gelin\" denildiğinde, \"Atalarımızı üzerinde bulduğumuz yol bize yeter!\" derler. Ataları, bir şey bilmeyen ve doğru yolu bulamayan kimseler olsa da mı?"},{"n":105,"t":"Gerçeği onaylayanlar, siz kendinize bakın. Doğru yolda iseniz sapıtan kimse size zarar veremez. Hepinizin dönüşü ALLAH’adır. Yaptıklarınızı size haber verecek."},{"n":106,"t":"Gerçeği onaylayanlar, birinize ölüm yaklaşınca, vasiyet anında aranızdan iki adil şahit tanık bulunsun. Yolculuk anında size ölüm gelirse, sizden olmayan iki kişi… Kuşkulanıyorsanız, namazdan sonra tanıkları alıkoyup ALLAH adıyla: \"Akraba dahi olsa tanıklığımızı hiçbir değerle değiştirmeyeceğiz, ALLAH’ın tanıklığını gizlemeyeceğiz. Aksi taktirde, günahkarlardan oluruz\" diye yemin ettirin."},{"n":107,"t":"Tanıkların taraflı olduğu anlaşılırsa, önceki tanıkların haksızlığına uğrayan taraftan iki tanık onların yerine geçer ve ALLAH adına şöyle yemin ederler: \"Tanıklığımız diğer ikisinin tanıklığından daha doğrudur. Biz sapmayacağız; yoksa zalim oluruz.\""},{"n":108,"t":"Bu uygulama, tanıklığı gereği gibi yapmalarını ve yemin ettikten sonra yeminlerinin reddedilmesinden korkmalarını sağlamak içindir. ALLAH’ı sayın ve dinleyin. ALLAH yoldan iyice çıkmış topluluğu doğru yola iletmez."},{"n":109,"t":"ALLAH elçileri topladığı gün: \"Size ne cevap verildi\" der. \"Bir bilgimiz yok. Gizemleri sen bilirsin\" derler."},{"n":110,"t":"ALLAH diyecek ki: Ey Meryem oğlu İsa, sana ve annene bağışladığım nimetimi hatırla. Seni Kutsal Ruh ile desteklemiştim; böylece beşikteyken de yetişkin iken de halkla konuşuyordun. Sana kitabı, bilgeliği, Tevrat’ı ve İncil’i öğretmiştim. İznimle balçıktan kuş heykeli yaratıyordun ve ona üfleyince de iznimle kuş oluveriyordu. Körü ve cüzzamlıyı iznimle iyileştiriyordun. Yine benim iznimle ölüleri diriltiyordun. İsrailoğullarına apaçık kanıtlar götürmene rağmen, içlerindeki inkârcılar, \"Bu apaçık bir büyüden başka bir şey değil\" demişlerdi de seni onlardan kurtarmıştım."},{"n":111,"t":"Sohbet arkadaşlarına (havariyun), \"Beni ve elçimi onaylayın\" diye vahyettiğimde; \"Onayladık, bizim barış içinde teslim (müslimun) oluşumuza tanık ol\" demişlerdi."},{"n":112,"t":"Havariler, \"Meryem oğlu İsa, Efendin bize gökten bir ziyafet çekebilir mi\" demişlerdi. \"Gerçeği onaylıyorsanız ALLAH’a saygı gösterin\" demişti."},{"n":113,"t":"\"İstiyoruz ki ondan yiyelim, kalbimiz yatışsın, senin bize doğru söylediğini bilelim ve ona tanık olalım.\""},{"n":114,"t":"Meryem oğlu İsa: \"Tanrımız, Efendimiz, bize gökten bir ziyafet indir de hepimiz ve her birimiz için bir bayram ve Sen’den bir delil olsun. Bizi rızıklandır. Sen en iyi rızık verensin\" dedi."},{"n":115,"t":"ALLAH, \"Onu size indireceğim\" dedi, \"Kim artık bundan sonra inkâr ederse, onu, hiç kimseye vermediğim bir azapla cezalandıracağım.\""},{"n":116,"t":"ALLAH şöyle diyecek: \"Ey Meryem oğlu İsa, sen mi halka, ’ALLAH’tan başka beni ve annemi de tanrı edinin’ dedin?\" O şöyle cevap verecek: \"Sen yücesin, hakkım olmayan bir şeyi söylemek bana yakışmaz. Zaten böyle bir şey söylemiş olsaydım sen bilirdin. Sen benim düşüncemi bilirsin; ancak ben senin düşünceni bilmem. Sen tüm gizemleri biliyorsun.\""},{"n":117,"t":"\"Ben onlara ‘Efendim ve Efendiniz olan ALLAH’a hizmet edin’ diye bana emrettiğinden başkasını demedim. Aralarında bulunduğum sürece onlara tanıktım. Canımı aldıktan sonra ise sen onların üzerine gözetleyici oldun. Sen her şeye Tanıksın.\""},{"n":118,"t":"\"Onları cezalandırırsan, onlar senin kullarındır. Onları bağışlarsan, kuşkusuz sen Üstünsün, Bilgesin.\""},{"n":119,"t":"ALLAH ilan edecek: \"Bu, doğrulara doğruluklarının yarar sağladığı gündür.\" Onlar için içlerinden ırmaklar akan ve orada sürekli kalacakları bahçeler var. ALLAH onlardan, onlar da O’ndan hoşnut olmuştur. Büyük başarı işte bu…"},{"n":120,"t":"Göklerin, yerin ve aralarındaki her şeyin egemenliği ALLAH’a aittir. O’nun gücü her şeye yeter."}]},{"id":6,"name":"En'âm Suresi","verses":[{"n":1,"t":"Övgü, gökleri ve yeri yaratan, karanlığı ve ışığı var eden ALLAH’a yaraşır. Buna rağmen, inkârcılar Rab’lerini başkalarıyla denk tutuyor."},{"n":2,"t":"O ki sizi balçıktan yarattı ve sonra yaşam süresi belirledi. Belirlenmiş süre O’nun katındadır. Siz ise hâlâ kuşku duyuyorsunuz."},{"n":3,"t":"O, göklerde ve yerde olan ALLAH. Sizin gizlinizi açığınızı bilir, kazandıklarınızı da bilir."},{"n":4,"t":"Onlara Rab’lerinin işaretlerinden (ayaat) hangi bir işaret (ayet) gelmişse ondan yüz çevirmişlerdir."},{"n":5,"t":"Kendilerine gerçek gelince onu yalanladılar. Alay ettikleri şeyin haberleri yakında kendilerine gelecek."},{"n":6,"t":"Kendilerinden önce nice nesilleri yok ettiğimizi görmüyorlar mı? Sizi yerleştirmediğimiz bir biçimde onları yeryüzüne yerleştirmiştik. Onları nimetlere boğmuş, ülkelerini ırmaklarla donatmıştık. Fakat günahlarından ötürü onları yok ettik ve onlardan sonra başka nesiller yetiştirdik."},{"n":7,"t":"Sana kağıt üzerine yazılı bir kitap indirseydik ve elleriyle dokunsalardı bile, inkârcılar, \"Bu ancak apaçık bir büyüdür\" diyeceklerdi."},{"n":8,"t":"\"Ona bir melek indirilmeli değil miydi!\" diyorlar. Bir melek indirseydik, iş bitirilmiş olurdu. Onlara zaman da verilmezdi."},{"n":9,"t":"Onu bir melek yapsaydık, onu bir adam biçiminde gönderir ve mevcut kuşkuları içinde bırakırdık."},{"n":10,"t":"Senden önceki elçiler de aşağılanmıştı. Ne var ki, alay edenleri eğlendikleri gerçek kuşatıverdi."},{"n":11,"t":"De: \"Yeryüzünü dolaşın da yalanlayıcıların sonu nasıl olmuş bir bakın.\""},{"n":12,"t":"De ki: \"Göklerde ve yerde olanlar kimin?\" \"ALLAH’ın\" de. Kendisine merhametli olmayı gerekli kıldı. Hakkında kuşku olmayan Diriliş Günü sizi toplayacak. Kişiliklerini yitirenler onaylamayanlardır."},{"n":13,"t":"Geceleyin de gündüzün de barınan her şey O’nundur. O İşitendir, Bilendir."},{"n":14,"t":"\"Gökleri ve yeri yoktan var eden, besleyen, fakat beslenmeyen ALLAH’tan başka sahip mi edineyim\" de. \"Ben, herkesten önce teslim olmakla emrolundum\" de. Ortak koşmayın!"},{"n":15,"t":"\"Efendime isyan ettiğim taktirde büyük günün azabından korkarım\" de."},{"n":16,"t":"O gün kimden azap çevrilirse ona rahmet edilmiştir. En büyük zafer budur."},{"n":17,"t":"ALLAH sana bir zarar dokundurmuşsa O’ndan başkası onu gideremez. Sana bir iyilikte bulunmuşsa O her şeye Kadirdir."},{"n":18,"t":"O, kullarına tam anlamıyla egemendir. O Bilgedir, Haber Alandır."},{"n":19,"t":"Sor: \"Kimin tanıklığı büyüktür?\" De ki: \"Benimle sizin aranızda ALLAH tanıktır. Sizi ve ulaştığı herkesi uyarmak için bana bu Kuran verildi. ALLAH’tan başka tanrı olduğuna mı tanıklık ediyorsunuz?\" \"Ben böyle tanıklık etmem\" de ve ardından şunu da söyle: \"O bir tek tanrı, ben sizin ortak koştuğunuz şeyden uzağım.\""},{"n":20,"t":"Kendilerine kitap verdiklerimiz, çocuklarını tanır gibi bunu tanır. Kişiliklerini yitirenler onaylamayanlardır."},{"n":21,"t":"ALLAH’a iftira eden veya ayetlerini inkâr edenden daha zalim kim olabilir? Zalimler başarıya ulaşamaz."},{"n":22,"t":"Hepsini topladığımız gün ortak koşanlara, \"Nerede iddia etmekte olduğunuz ortaklarınız?\""},{"n":23,"t":"Onların tek savunması şu olacak: \"Efendimiz ALLAH’a andolsun ki biz ortak koşmadık.\""},{"n":24,"t":"Kendilerine karşı nasıl yalan söylediklerine dikkat et. Uydurdukları şeyler kendilerini nasıl da terk etti."},{"n":25,"t":"Onların bir kısmı seni dinler. Fakat, kalpleri üzerine anlamalarına engel olacak örtüler, kulaklarına da ağırlık koyarız. Her bir mucizeyi görseler de onu onaylamazlar. Bundan ötürü sana geldiklerinde seninle tartışır ve inkârcılar, \"Bu ancak bir efsanedir\" der."},{"n":26,"t":"Kendileri uzaklaştıkları gibi başkasını da ondan menediyorlar. Böylece farkında olmadan kendilerini mahvediyorlar."},{"n":27,"t":"Ateşin başında durduruldukları vakit onların \"Keşke geri döndürülseydik de Efendimizin vahiy ve işaretlerini (ayat) inkâr etmeseydik ve gerçeği onaylayanlardan olsaydık\" dediklerini bir görsen!"},{"n":28,"t":"Daha önce gizledikleri ortaya çıktığı için... Geri döndürülselerdi, yine menedildikleri şeye dönerlerdi. Yalan söylüyorlar."},{"n":29,"t":"\"Bizim için sadece dünya hayatı vardır, diriltilecek değiliz\" diyorlardı."},{"n":30,"t":"Rab’lerinin huzurunda durdurulmuş halde onları bir görsen! \"Bu doğru değil mi?\" diyecek. \"Evet, Efendimize andolsun doğru\" diyecekler. \"İnkâr etmenizden ötürü azabı tadın!\" diyecek."},{"n":31,"t":"Kaybedenler, ALLAH ile karşılaşmayı yalanlayanlardır. O an kendilerini ansızın yakalayınca, günah yüklerini sırtlarında taşıyarak, \"Oradaki hayatımızı boşa harcamamızdan ötürü vay halimize\" diyecekler. Yüklendikleri şey ne de kötü!"},{"n":32,"t":"Dünya hayatı ancak bir oyun ve eğlence. Erdemliler için ahiret yurdu daha hayırlı. Düşünmez misiniz?"},{"n":33,"t":"Söyledikleri şeylerin seni üzdüğünü biliyoruz. O zalimler seni değil ALLAH’ın ayetlerini reddediyor."},{"n":34,"t":"Senden önceki elçileri de yalancılıkla suçladılar. Yalanlanmalara karşı direndiler. Zaferimiz ulaşıncaya dek sıkıntı çektiler. ALLAH’ın sistemi değişmeyecek. Nitekim elçilerin tarihi sana ulaşmış bulunuyor."},{"n":35,"t":"Yüz çevirmeleri sana ağır geldiyse, bilesin ki, yerin içine bir delik açmaya ya da göğe merdiven dayamaya gücün yetse de bir mucize ortaya koysan yine kâr etmez.. ALLAH dileseydi onları doğru yola toplardı. Öyleyse cahillerden olma."},{"n":36,"t":"Ancak dinleyenler yönelir. Ölüleri ALLAH diriltir, sonra da her şey O’na döndürülür."},{"n":37,"t":"\"Ona Efendisinden bir ayet inmeli değil miydi!\" diyorlar. De ki: \"ALLAH istediği an bir ayet indirebilir; fakat çoğu bunu bilmez.\""},{"n":38,"t":"Kanatlarıyla uçan kuşlar dahil yeryüzündeki tüm yaratıklar sizin gibi birer toplum. Biz kitapta hiçbir şeyi eksik bırakmadık. Sonra onlar Rab’lerinin huzuruna toplanacak."},{"n":39,"t":"Ayetlerimizi yalanlayanlar karanlıklar içinde bulunan birer sağır ve dilsizdirler. ALLAH kimi dilerse saptırır, kimi de dilerse doğru yola iletir."},{"n":40,"t":"De: \"Doğruysanız söyleyin bakalım, size ALLAH’ın azabı, yahut o an gelse, ALLAH’tan başkasına mı yalvarırsınız?\""},{"n":41,"t":"Doğrusu, yalnız O’na yalvarırsınız. Dilerse yalvardığınız konudaki probleminizi giderir, siz de ortak koştuklarınızı unutursunuz."},{"n":42,"t":"Senden önceki toplumlara da elçiler gönderdik. Yalvarsınlar diye onları darlık ve sıkıntılarla sınadık."},{"n":43,"t":"Hiç olmazsa başlarına musibetimiz geldiğinde yalvarsalardı! Fakat kalpleri katılaştı ve sapkın işlerini kendilerine süslü gösterdi."},{"n":44,"t":"Kendilerine iletilen mesajı unuttuklarında kendilerine her şeyin kapısını ardına kadar açtık. Kendilerine verilenlerle şımarınca onları ansızın yakaladık ve böylece şaşkın ve umutsuz kaldılar."},{"n":45,"t":"Zulmeden topluluğun ardı böyle kesilir. Övgü, evrenlerin Rabbi ALLAH’a yaraşır."},{"n":46,"t":"De: \"Bir düşünün, ALLAH sizin işitme ve görme duyunuzu alıp belleğinizi kapasa, ALLAH’tan başka hangi tanrı onları size geri verebilir?\" Ayetleri nasıl açıkladığımıza ve buna rağmen nasıl da yüz çevirdiklerine dikkat et!"},{"n":47,"t":"De: \"ALLAH’ın azabı size ansızın veya duyurudan sonra gelse… Zalim toplumdan başkası mı yok edilir?\""},{"n":48,"t":"Biz elçileri, ancak müjdeleyiciler ve uyarıcılar olarak gönderiyoruz. Kim Gerçeği onaylayıp kendini düzeltirse, onlara bir korku yok, onlar üzülmeyecekler de."},{"n":49,"t":"Ayetlerimizi yalanlayanlara gelince, yoldan çıktıklarından ötürü onlara azap dokunacak."},{"n":50,"t":"De: \"ALLAH’ın hazineleri benim yanımda demiyorum size. Gizlilikleri de bilmiyorum. Size, bir melek olduğumu da söylemiyorum. Sadece bana vahyedileni izliyorum.\" Şunu da söyle: \"Kör ile gören bir mi?\""},{"n":51,"t":"Rab’lerinin huzuruna çıkacaklarının heyecanıyla dolanları bununla uyar: O’ndan başka bir sahipleri ve aracıları (şefaatçileri) yok. Belki korunurlar."},{"n":52,"t":"Sabah akşam Rab’lerine yalvarıp sadece O’nun hoşnutluğunu arzulayanları kovma. Onların hesabından sen sorumlu değilsin. Senin hesabından da onlar sorumlu değil. Onları kovarsan zalim olursun."},{"n":53,"t":"Birbiriyle böylece sınadık ki \"ALLAH’ın aramızdan seçip nimetlendirdiği kişiler bunlar mı\" desinler. ALLAH güzel karşılık verenleri daha iyi bilmiyor mu!"},{"n":54,"t":"Ayetlerimizi onaylayanlara gelince, \"Size selam olsun. Efendiniz merhametli davranmayı prensip edindi. Bunun için, her kim bilmeyerek işlediği bir kötülükten sonra tövbe ederek kendini düzeltirse, bilsin ki O Bağışlayandır, Rahimdir.\""},{"n":55,"t":"Suçluların yolunun besbelli olması için ayetleri böyle açıklarız."},{"n":56,"t":"De: \"ALLAH’ın dışında çağırdıklarınıza hizmet etmekten menedildim.\" De: \"Sizin keyfinize uymayacağım. Aksi taktirde sapar ve doğru yolu bulamam.\""},{"n":57,"t":"De: \"Ben Efendimden bir delile dayanmaktayım. Siz ise onu yalanladınız. Ona meydan okuyarak istediğiniz şeyi getirmek benim elimde değil. Hüküm, ancak ve ancak ALLAH’ın. Gerçeği anlatıyor. O, en iyi ayırandır."},{"n":58,"t":"De: \"Sizin acele istediğiniz şeye sahip olsaydım aramızda iş biterdi. ALLAH zalimleri iyi biliyor.\""},{"n":59,"t":"Gizliliklerin anahtarı onun elinde. O’ndan başkası onları bilmez. Karada ve denizde ne varsa onları bilir. Bilgisi dışında bir yaprak bile düşmez. Yerin karanlığında bir tane, yaş veya kuru hiçbir şey yok ki apaçık bir kitapta kayıtlı olmasın."},{"n":60,"t":"O’dur, geceleyin sizi öldüren, gündüzün ne işlediğinizi bilen, belli yaşam süresi dolsun diye gündüzün sizi dirilten… Sonra dönüşünüz O’nadır ve yaptıklarınızı size haber verecektir."},{"n":61,"t":"O, kulları üzerinde egemendir ve üzerinize koruyucu melekler gönderir. Sizden birine ölüm geldiği zaman elçilerimiz onun canını hiç vakit geçirmeden alırlar."},{"n":62,"t":"Sonra gerçek Mevla’ları olan ALLAH’a döndürülürler. Bilesiniz ki yargı O’nundur ve O, en hızlı hesap görendir."},{"n":63,"t":"De ki: \"Gizli ve açık olarak ‘Bizi bundan kurtarsan şükredenlerden olacağız.’ diye O’na yalvardığınızda sizi karanın ve denizin karanlıklarından kim kurtarabilir?\""},{"n":64,"t":"De ki: \"Ondan ve bütün sıkıntılardan sizi ALLAH kurtarıyor. Buna rağmen siz yine ortak koşuyorsunuz.\""},{"n":65,"t":"De ki: \"Üstünüzden veya ayaklarınızın altından size bir azap göndermeye, yahut sizleri mezheplere bölüp birbirinizin kötülüğünü tattırmaya O’nun gücü yeter.\" Bak, anlasınlar diye ayetlerimizi nasıl da açıklıyoruz."},{"n":66,"t":"Gerçek olmasına rağmen senin halkın bunu yalanladı. De ki: \"Ben üzerinizde gözetici değilim.\""},{"n":67,"t":"Her bir haberin gerçekleşeceği bir zaman vardır. İleride bilecekler."},{"n":68,"t":"Ayet ve mucizelerimizle alay edenleri gördüğün vakit, başka bir söze dalıncaya kadar onlardan yüz çevir. Sapkın sana unutturursa, hatırladıktan sonra böyle zalim kimselerle birlikte oturma."},{"n":69,"t":"Erdemliler böylelerinin hesabından sorumlu tutulmaz. Fakat, olur ki dinlerler diye hatırlatmak iyi olur."},{"n":70,"t":"Dinlerini oyun eğlenceye alanları ve dünya hayatına aldananları bırak. Sen bununla hatırlat ki, bir kişi kazandığının felaketli sonucunu çekmesin. Onun ALLAH’tan başka bir sahibi ve şefaatçisi yoktur. Her türlü fidyeyi verse bile kendisinden kabul edilmez. Bunlar, kazandıklarından dolayı felaketli sonuca uğrayanlardır; inkârları yüzünden kaynar sudan bir içkiyi ve acı verici bir azabı hak etmişlerdir."},{"n":71,"t":"De ki: \"ALLAH’tan başka, bize yarar ve zarar veremeyenlere mi yalvaralım? ALLAH bizi doğru yola ulaştırdıktan sonra ökçelerimiz üzerinde gerisin geriye mi dönelim? sapkınların ayartıp yeryüzünde şaşırttığı ve arkadaşlarının, ’Gel, bizimle birlikte doğru yola gel’ diye çağırdıkları şaşkın bir kimse gibi mi olalım?\" De ki: \"Gerçek yol gösterme ALLAH’ın yol göstermesidir. Evrenlerin Efendisine teslim olmakla emredildik.\""},{"n":72,"t":"\"Namazı gözetmeli ve O’nu sayıp dinlemelisiniz. Huzurunda toplanacağınız O’dur.\""},{"n":73,"t":"O’dur gökleri ve yeri yaratan. \"Ol\" dediği gün hemen oluverir. Sözü mutlak doğrudur. Boruya üfürüldüğü gün egemenlik tümüyle O’nundur. Gizliyi ve açığı Bilendir. Bilgedir, her şeyden Haberdardır."},{"n":74,"t":"İbrahim, babası Azer’e şöyle demişti: \"Heykelleri mi tanrı ediniyorsun? Seni ve halkını tümüyle apaçık bir sapıklık içinde görüyorum.\""},{"n":75,"t":"Kesin bir onaylamaya sahip olması için, İbrahim’e göklerin ve yerin yönetimini şöylece gösterdik:"},{"n":76,"t":"Üzerine gece basınca bir gezegen gördü, \"Budur benim Efendim!\" dedi. Batınca, \"Ben batanları sevmem\" dedi."},{"n":77,"t":"Ay’ı doğarken görünce, \"Budur benim Efendim!\" dedi. Batınca da, \"Efendim bana doğru yolu göstermezse sapıtanlardan olurum\" dedi."},{"n":78,"t":"Güneşi doğarken görünce, \"Budur benim Efendim. Bu, daha büyük!\" dedi. O da batınca: \"Ey halkım, ben sizin ortak koştuğunuz şeylerden uzağım\" dedi."},{"n":79,"t":"Ben yüzümü tümüyle, gökleri ve yeri yaratana çevirdim ve ben ortak koşanlardan değilim."},{"n":80,"t":"Halkı onunla tartıştı. \"Beni doğruya ulaştırmış iken benimle hâlâ ALLAH hakkında mı tartışıyorsunuz? Sizin ortak koştuklarınızdan korkmam, meğer Efendim bir şey dilerse… Efendim, bilgice her şeyi kuşatmıştır. Öğüt almıyor musunuz?\""},{"n":81,"t":"\"ALLAH’ın kendileri hakkında size hiçbir delil vermediklerini O’na ortak koşmaktan korkmuyorsunuz da ben nasıl olur da sizin ortak koştuklarınızdan korkarım? Hangi taraf güvenliği daha çok hak etmektedir? Bir bilseniz!\""},{"n":82,"t":"Gerçeği onaylayanlar ve onaylarını bir zulümle bulaştırmayanlar güvenliği hak etmişlerdir ve onlar doğruyu bulmuşlardır."},{"n":83,"t":"Bunlar, halkına karşı kullanması için İbrahim’e verdiğimiz tartışma yöntemidir. Dilediğimizi derecelerle yükseltiriz. Efendin Bilgedir, Bilendir."},{"n":84,"t":"Ona İshak’ı ve Yakup’u bağışladık. Her birisine yol gösterdik. Daha önce de Nuh’a ve onun soyundan Davut’a, Süleyman’a, Eyyub’a, Yusuf’a, Musa’ya ve Harun’a da yol gösterdik. Güzel davrananları işte böyle ödüllendiririz."},{"n":85,"t":"Zekeriyya, Yahya, İsa ve İlyas’a da… Hepsi de iyilerden idi."},{"n":86,"t":"İsmail, El-Yasa’, Yunus ve Lut’a da… Hepsini halklara üstün kıldık."},{"n":87,"t":"Atalarından, soylarından, kardeşlerinden birçoğunu seçip doğru yola ilettik."},{"n":88,"t":"ALLAH’ın hidayeti böyledir. Kullarından dilediğini ve/veya dileyeni ona ulaştırır. Ortak koşsalardı yaptıkları boşa çıkardı."},{"n":89,"t":"İşte onlar, kendilerine kitap, hikmet ve peygamberlik verdiklerimizdir. Eğer şu halk, bunları inkâr ederse, biz onları inkâr etmeyecek bir toplumu yerlerine geçiririz."},{"n":90,"t":"Bunlar, ALLAH’ın doğru yola ulaştırdıklarıdır. Onların yoluna uy. De ki: \"Ben buna karşılık sizden bir ücret istemiyorum. Bu, sadece tüm halklara bir mesajdır.\""},{"n":91,"t":"\"ALLAH hiçbir insana bir şey indirmez\" demekle ALLAH’ı gereği gibi değerlendirmediler. De ki: \"Halka bir hidayet ve ışık olarak Musa’nın getirdiği kitabı kim indirdi –ki göstermek için onu kağıtlara yazdığınız halde çoğunu gizliyordunuz. Sizin ve atalarınızın bilmediği şeyleri onun yoluyla öğrendiniz–?\" \"ALLAH\" de ve onları daldıkları sapıklıkta bırak, oynayadursunlar."},{"n":92,"t":"Bu, kendisinden öncekileri doğrulayan kutlu bir kitap olup ülkelerin anasını ve etrafındakileri uyarman için indirilmiştir. Ahireti onaylayanlar, onu onaylarlar ve onlar namazlarına da devam ederler."},{"n":93,"t":"ALLAH adına yalan uydurandan ve kendisine hiçbir şey vahyedilmediği halde, \"Bana vahyediliyor\" diyenden ve \" ALLAH’ın indirdiği gibi ben de indireceğim\" diyenden daha zalim kim olabilir! Can çekişmesi anında zalimleri bir görsen! melekler, ellerini uzatmıştır: \"Canınızı verin! ALLAH hakkında gerçek olmayanı söylemenizden ve onun vahiy ve işaretlerini (ayat) kibir ve gururla karşılamanızdan dolayı bugün utanç verici azapla cezalandırılacaksınız.\""},{"n":94,"t":"\"Sizi ilk defa yarattığımız gibi bize tek olarak geldiniz. Size hayal gibi gösterdiğimiz şeyleri ardınızda bıraktınız. Sizinle ortak olduklarını ileri sürdüğünüz aracılarınızı (şefaatçılarınızı) yanınızda görmüyoruz. Aranızdaki bağlar kesilmiştir. İleri sürdükleriniz sizi terk etmiştir.\""},{"n":95,"t":"ALLAH taneyi ve çekirdeği yarıp filizlendirendir. Ölüden diriyi çıkarır ve diriden de ölüyü çıkarandır. İşte budur ALLAH. Nasıl yüz çevirebilirsiniz!"},{"n":96,"t":"Sabahı ortaya çıkarandır. Geceyi dinlenme zamanı, güneşi ve ayı da bir hesaplama aracı yapmıştır. Bu, her şeyden Üstün ve her şeyi Bilen’in planıdır."},{"n":97,"t":"Karanın ve denizin karanlıklarında yollarınızı bulasınız diye sizin için yıldızları yaratan O’dur. Bilen bir toplum için ayetleri detaylı olarak açıklamış bulunuyoruz."},{"n":98,"t":"O’dur sizi bir tek kişiden inşa eden. Bir kalış ve izleyen bir ayrılış. Ayetleri, anlayan bir toplum için açıklamışızdır."},{"n":99,"t":"O’dur gökten su indiren. Onunla her çeşit bitkiyi çıkardık. O bitkiden ürettiğimiz yeşil madde ile de sayısız taneler çıkardık. Tomurcuğundan salkımlar sarkan hurma ağaçları, üzüm bağları, zeytin ve nar gibi birbirine benzeyen ve benzemeyen ürünler çıkardık. Her birinin meyve verme zamanında meyvesine ve olgunluğuna bakın. Gerçeği onaylayan bir toplum için bunda deliller ve ibretler vardır."},{"n":100,"t":"ALLAH’a cinleri ortak koştular. Halbuki onları O yaratmıştır. Bilmeden O’na oğullar ve kızlar yakıştırdılar. O’nun şanı yücedir, onların nitelemelerinden çok üstündür."},{"n":101,"t":"Gökleri ve yeri yoktan var edendir. Kız arkadaşı olmadığı halde nasıl olur da çocuğu olur? Her şeyi O yaratmıştır ve O, her şeyi Bilendir."},{"n":102,"t":"Efendiniz ALLAH işte budur. O’ndan başka tanrı yoktur. Her şeyin Yaratıcısıdır. O’na hizmet edin. O, her şeyi Kontrol Edendir."},{"n":103,"t":"Gözler O’na erişemez O, gözlere erişir. O Şefkatlidir, Haberdardır."},{"n":104,"t":"Efendinizden size aydınlatıcı belgeler gelmiş bulunuyor. Kim görürse kendi yararına, kim körlük ederse kendi zararınadır. Ben üzerinize bekçi değilim."},{"n":105,"t":"\"Sen ders almışsın\" demeleri için ve bilen bir topluma açıklamak için ayetleri böyle sergiliyoruz."},{"n":106,"t":"Efendinden sana indirilene uy. O’ndan başka tanrı yoktur. Ortak koşanlardan da yüz çevir."},{"n":107,"t":"ALLAH isteseydi ortak koşamazlardı. Seni onların üzerine bekçi yapmadık. Onların avukatı da değilsin."},{"n":108,"t":"ALLAH’ın dışında yalvardıklarına sövmeyiniz ki onlar da sınırı aşıp cehaletten dolayı ALLAH’a sövmesinler. Biz her topluluğa yaptıkları işi böyle süslü gösterdik. Sonunda dönüşleri Rab’lerinedir ve onlara yapmış bulunduklarını haber verir."},{"n":109,"t":"Kendilerine bir mucize gelse onu mutlaka onaylayacaklarına dair tüm güçleriyle ALLAH’a yemin ederler. De ki: \"Mucizeler ALLAH’ın yanındadır.\" Mucize geldiği zaman da onların onaylamayacağını bilmez misiniz?"},{"n":110,"t":"İlk başta gerçeği onaylamamaya karar verdikleri için anlama yeteneklerini ve gözlerini çevirip azgınlıkları içinde bocalar durumda bırakırız."},{"n":111,"t":"Onlara melekleri indirsek, kendileriyle ölüler konuşsa ve her şeyi getirip önlerine toplasak, ALLAH’ın diledikleri hariç, yine onaylayacak değillerdir. Fakat çoğu bu gerçeği bilmez."},{"n":112,"t":"Böylece, her peygambere insanlardan ve cinlerden olan sapkınları düşman kıldık. Aldatmak için birbirlerine yaldızlı sözleri vahyederler. Efendin dileseydi bunu yapamazlardı. Onlara ve ettikleri iftiralara aldırma."},{"n":113,"t":"Ahiret onaylamayanların kalbi ona kansın, ondan hoşlansın ve gerçekten yapmak istediklerini yapabilsinler diye…"},{"n":114,"t":"ALLAH’tan başka yasa koyucu mu arayayım? O ki size kitabı detaylı olarak indirmiştir. Kendilerine kitap vermiş olduklarımız onun Efendin tarafından indirilmiş olduğunu bilirler. O halde kuşkulananlardan olma."},{"n":115,"t":"Efendinin kelimeleri doğruluk ve adaletle tamamlanmıştır. O’nun sözlerini değiştirebilecek yoktur. O, İşitendir, Bilendir."},{"n":116,"t":"Yeryüzündekilerin çoğuna uyarsan seni ALLAH’ın yolundan saptırırlar. Onlar ancak zanna uyuyorlar ve onlar sadece tahminde bulunup saçmalıyorlar."},{"n":117,"t":"Efendin, yolundan sapanları en iyi bilendir. Doğru yolda olanları da o daha iyi bilir."},{"n":118,"t":"Ayetlerine Gerçeği onaylıyorsanız, üzerinde ALLAH’ın ismi anılanlardan yiyin."},{"n":119,"t":"Size ne oluyor ki, üzerinde ALLAH’ın ismi anılanlardan yemiyorsunuz? Halbuki zorunlu haller haricinde size yasaklananları detayıyla size açıklamış bulunuyor. Birçokları, bilgiye dayanmayan kişisel görüşleriyle halkı saptırıyor. Efendin sınırı aşanları en iyi bilendir."},{"n":120,"t":"Günahların açığını da gizlisini de bırakın. Günah kazananlar işlediklerinin karşılığını alacaklardır."},{"n":121,"t":"Üzerinde ALLAH’ın ismi anılmayanlardan yemeyin. Çünkü o, yoldan çıkmadır. Sapkınlar, sizinle tartışmaları için dostlarına vahyeder. Onlara uyarsanız siz de ortak koşmuş olursunuz."},{"n":122,"t":"Ölüyken dirilttiğimiz ve kendisine insanlar arasında yürüyebileceği bir ışık verdiğimiz kimse, karanlıklar içinde olup da ondan çıkamayan kimse gibi olur mu? İnkârcıların yaptıkları işler böyle süslü gösterilmiştir."},{"n":123,"t":"Her ülkenin önde gelen suçlularına, orada hile ve entrika yapmaları için izin verdik. Aslında kendilerinden başkasını kandırmıyorlar. Ama farkında değiller."},{"n":124,"t":"Kendilerine bir mucize geldiğinde: \"ALLAH’ın elçilerine verilenlerin benzeri bize verilmedikçe onaylamayız\" derler. ALLAH mesajını nereye koyacağını daha iyi bilir. Yaptıkları hilelerden ötürü suçlulara ALLAH katından bir aşağılama ve çetin bir azap dokunacaktır."},{"n":125,"t":"ALLAH kimi doğru yola ulaştırmak dilerse onun gönlünü barış içinde teslim olmaya (İslam) açar. Kimi de saptırmak dilerse göğsünü, göğe yükseliyormuş gibi dar ve sıkıntılı kılar. ALLAH onaylamayanları işte böyle kötü duruma sokar."},{"n":126,"t":"Bu, Efendinin dosdoğru yoludur. Öğüt alan bir toplum için ayetleri detayıyla açıklamış bulunuyoruz."},{"n":127,"t":"Onlar, Rab’lerinin yanında barış yurdunu hak etmişlerdir. Yaptıklarından ötürü onların sahibi O’dur."},{"n":128,"t":"Hepsini sürüp topladığı gün: \"Ey cinler topluluğu, siz çok sayıda insan harcadınız.\" Onların insanlardan olan dostları: \"Efendimiz, bize verdiğin sürenin sonuna erişinceye kadar birbirimizden hoşlandık\" derler. \"Yeriniz ateştir\" der. ALLAH’ın dilemesi hariç, orada ebedî kalacaklardır. Efendin Bilgedir, Bilendir."},{"n":129,"t":"Zalimleri böylece eşleyerek birbirinin dostları yaparız. Yaptıklarından ötürü…"},{"n":130,"t":"Ey cinler ve insanlar topluluğu, size, ayetlerimi anlatan ve bugünle karşılaşmanız konusunda sizi uyaran sizden elçiler gelmedi mi? \"Kendimize karşı tanığız\" dediler. Dünya hayatı onları aldattı ve inkârcı olduklarına dair kendi kendilerine karşı tanıklık ettiler."},{"n":131,"t":"Bu böyledir. Efendin, halkı habersiz bir durumda iken ülkeleri zulüm ile helak etmez."},{"n":132,"t":"Yaptıklarına karşılık olarak her biri için dereceler vardır. Efendin, onların yaptıklarından habersiz değil."},{"n":133,"t":"Efendin Zengindir, Rahmet Sahibidir. Dilerse sizi götürür ve sizi başkaların soyundan nasıl getirmişse sizden sonra da yerinize dilediklerini yerleştirir."},{"n":134,"t":"Size söz verilenler elbette yerine gelecektir ve onun önüne geçemezsiniz."},{"n":135,"t":"De ki: \"Ey halkım, elinizden geleni yapın, ben de elimden geleni yapacağım. Yakında kimin nihai başarıya ulaştığını göreceksiniz!\" Zalimler başaramazlar."},{"n":136,"t":"ALLAH’ın ürettiği ekinlerden ve çiftlik hayvanlarından O’na bir pay ayırarak, kafalarına göre, \"Bu ALLAH’ın, bu da ortaklarımızındır\" dediler. Ortaklarının payı ALLAH’a ulaşmıyor; ancak ALLAH’ın payı ortaklarına ulaşıyor! Ne de kötü hüküm veriyorlar."},{"n":137,"t":"Böylece onların (Tanrı adına din ve mezhep üreten) ortakları, çocuklarını öldürmeyi bile müşriklerin çoğuna iyi bir şeymiş gibi gösterdiler. Böylece onları mahvettiler ve dinlerini karıştırıp bozdular. ALLAH dileseydi bunu yapamazlardı. Onlardan ve uydurdukları şeylerden uzak dur."},{"n":138,"t":"Zanlarına göre şöyle dediler: \"Bunlar dokunulmaz çiftlik hayvanları ve ekinlerdir. Dilediğimizden başkası bunları yiyemez.\" Binilmesi yasaklanan çiftlik hayvanları… ALLAH’ın ismini üzerlerinde anmadıkları çiftlik hayvanları… O’na yakıştırdılar. Onları iftiralarıyla cezalandıracaktır."},{"n":139,"t":"\"Şu çiftlik hayvanlarının karınlarındakiler sadece erkeklerimize ait olup kadınlarımıza haramdır. Ölü doğarlarsa o zaman paylaşabilirler\" dediler. Bu nitelemelerinin hesabını onlara ödetecektir. O Bilgedir, Bilendir."},{"n":140,"t":"Cehaletleri yüzünden ALLAH’a iftiralar ederek çocuklarını budalaca öldürenler ve ALLAH’ın kendilerine verdiği rızıkları haram edenler kaybetmişlerdir, şaşırmışlardır. Doğruyu göremezler."},{"n":141,"t":"Çardaklı ve çardaksız bahçeleri, ürünleri, çeşit çeşit hurmaları, ekinleri, zeytinleri ve narları –benzer veya farklı– yaratan O’dur. Her biri meyve verdiği zaman meyvesinden yiyin ve hakkını da hasat gününde verin. Savurganlık yapmayın; O, savurganları sevmez."},{"n":142,"t":"Çiftlik hayvanları, binmeniz, kesmeniz veya kendilerinden yatak malzemesi çıkarmanız içindir. ALLAH’ın size verdiği rızıklardan yiyin ve sapkının adımlarını izlemeyin; çünkü o sizin apaçık düşmanınızdır."},{"n":143,"t":"Sekiz çift: Koyundan iki, keçiden iki… De ki: \"İki erkeği mi haram etti, iki dişiyi mi, yoksa o iki dişinin rahimlerindekileri mi?\" Doğru sözlüler iseniz, bir bilgiye dayanarak bana cevap verin."},{"n":144,"t":"Deveden iki, sığırdan iki. De ki: \"İki erkeği mi haram etti, iki dişiyi mi, yoksa o iki dişinin rahimlerindekini mi? ALLAH’ın size böyle emrettiğine tanık mı oldunuz? Halkı bilgisizce yoldan saptırmak için, yalan uydurup onları ALLAH’a yakıştırandan daha zalim kim olabilir? ALLAH zalim toplumu doğru yola iletmez.\""},{"n":145,"t":"De ki: \"Bana vahyedilende, yiyen birisi için şunların dışında haram edilmiş bir madde bulamıyorum: (1) Leş, (2) akıtılmış kan, (3) domuzun eti –ki pistir–, (4) ALLAH’tan başkasına sapıkça adanmış yiyecekler.\" Zorda kalan bir kimse, istekli olmaz ve sınırı aşmazsa kuşkusuz senin Efendin Bağışlayandır, Rahimdir."},{"n":146,"t":"Yahudilere tüm tırnaklı hayvanları haram kıldık. Sığır ve koyunun da yağlarını haram ettik; ancak sırtlarında yahut bağırsaklarında taşıdıkları veya kemiklerine karışmış olanlar hariç. Aşırı gitmelerinden ötürü onları böyle cezalandırdık. Biz doğru sözlüyüz."},{"n":147,"t":"Seni yalanlarlarsa: \"Efendiniz geniş rahmet sahibidir ve O’nun cezası suçlu toplumlardan geri çevrilemez\" de."},{"n":148,"t":"Ortak koşanlar, \"ALLAH dilemeseydi, ne biz, ne atalarımız ortak koşmaz ve hiçbir şeyi de haram etmezdik\" diyeceklerdir. Onlardan öncekiler de azabımızı tadıncaya kadar aynı şekilde yalanlamışlardı. De ki: \"Yanınızda bize göstereceğiniz herhangi bir bilgi var mı? Siz ancak kuşkulu ve çelişkili rivayetlere (zanna) uyuyorsunuz ve siz sadece tahminde bulunuyorsunuz.\""},{"n":149,"t":"De ki: \"En güçlü delil ALLAH’ındır. Dileseydi, elbette hepinizi doğruya ulaştırırdı.\""},{"n":150,"t":"De ki: \"ALLAH’ın şunu haram ettiğine tanıklık edecek tanıklarınızı getirin.\" Tanıklık ederlerse onlarla beraber tanıklık etme. Ayetlerimizi yalanlayanların ve ahireti onaylamayanların keyfine uyma. Onlar, Rab’lerine başkalarını eş koşmaktadırlar."},{"n":151,"t":"De ki: \"Gelin, Efendinizin size neleri haram ettiğini söyleyeyim: O’na hiçbir şeyi ortak koşmayın. Ana babaya iyi davranın. Yoksulluk korkusuyla çocuklarınızı öldürmeyin; sizi de onları da biz besliyoruz. Büyük günahların açığına da gizlisine de yaklaşmayın ve ALLAH’ın yasakladığı cana haksız yere kıymayın. Bunlar, düşünesiniz diye O’nun size verdiği öğütlerdir."},{"n":152,"t":"Erginlik çağına erişinceye kadar yetim malına yaklaşmayın. Ölçüyü ve tartıyı doğru dürüst yapın. Kişiye kapasitesinin yetmediğini yüklemeyiz. Konuştuğunuz zaman akrabanız aleyhinde bile olsa doğru olun. ALLAH’a verdiğiniz sözü tutunuz. Bunlar, ders alasınız diye O’nun size verdiği öğütlerdir."},{"n":153,"t":"İşte bu benim dosdoğru yolumdur. Ona uyun, başka yollara uymayın; çünkü onlar, sizi O’nun yolundan ayırırlar. Bunlar, dinlersiniz diye O’nun size verdiği öğütlerdir."},{"n":154,"t":"Nitekim, en güzel biçimde tamamlanmış, her şeyin detaylı açıklaması, hidayet ve rahmet olarak Musa’ya Kitabı verdik ki Rab’leriyle kavuşmayı onaylasınlar."},{"n":155,"t":"Bu da indirdiğimiz kutlu bir kitaptır. Öyleyse size merhamet edilmesi için ona uymalısınız, erdemli davranmalısınız."},{"n":156,"t":"Artık, \"Bizden önceki iki gruba kitap verildi; biz ise onların öğretilerinden habersizdik\" diyemezsiniz."},{"n":157,"t":"Yahut, \"Bize de kitap indirilseydi onlardan daha doğru yolda olurduk\" da diyemezsiniz. Size Efendinizden bir kanıt (beyyine), bir hidayet ve bir rahmet gelmiş bulunuyor. ALLAH’ın ayetlerini yalanlayıp ondan yüz çevirenden daha zalim kim olabilir? Ayetlerimizden yüz çevirenleri, yüz çevirmelerinden ötürü azabın en kötüsüyle cezalandıracağız."},{"n":158,"t":"Kendilerine meleklerin gelmesini mi, yoksa Efendinin, yahut Efendinin bazı işaretlerinin gelmesini mi bekliyorlar? Efendinin bazı işaretleri geldiği gün, daha önce onaylamamış veya onaylamasında bir hayır kazanmamış kişiye bir yarar sağlamaz. De ki: \"Bekleyin, biz de beklemekteyiz.\""},{"n":159,"t":"Dinlerini parçalara ayırıp mezhep mezhep olanlarla senin hiçbir ilişkin yoktur. Onların işi ALLAH’a kalmıştır; sonra onlara durumlarını haber verecektir."},{"n":160,"t":"Kim iyilik getirirse, kendisine getirdiğinin on katı vardır. Kim kötülük getirirse, ancak dengiyle cezalandırılır ve kendilerine haksızlık edilmez."},{"n":161,"t":"De ki: \"Efendim beni dosdoğru olan yola iletmiş bulunuyor: tek tanrılı olan İbrahim’in mükemmel dinine… O, ortak koşanlardan olmadı.\""},{"n":162,"t":"De ki: \"Namazım, ibadetlerim, hayatım ve ölümüm evrenlerin Rabbi olan ALLAH içindir.\""},{"n":163,"t":"\"O’nun ortağı yoktur. Bununla emredildim ve ben herkesten önce teslim olurum.\""},{"n":164,"t":"De ki: \"Her şeyin Rabbi iken, ALLAH’tan başka Rab mi arayayım? Herkes kendi yaptığından yarar görür ve kimse kimsenin yükünü çekmez. Sonunda dönüşünüz Efendinizedir. Ayrılığa düştüğünüz konuda size haber verecektir."},{"n":165,"t":"O ki sizi yeryüzünün mirasçıları kıldı ve size verdikleriyle sizi sınamak için kiminizi kiminize derecelerle üstün kıldı. Efendin çabuk sonuçlandırandır. Bağışlayandır, Rahimdir."}]},{"id":7,"name":"A'raf Suresi","verses":[{"n":1,"t":"A. L. M. S."},{"n":2,"t":"Bu, sana indirilen bir kitaptır. Onunla uyarman ve gerçeği onaylayanlara öğüt vermen konusunda göğsünde bir kuşku ve sıkıntı olmasın."},{"n":3,"t":"Efendinizden size indirileni izleyin, O’ndan başkalarını dost edinerek izlemeyin. Ne kadar az öğüt alıyorsunuz!"},{"n":4,"t":"Yok ettiğimiz nice topluluklar, uyurlarken yahut gündüzün işlerine dalmış haldeyken azabımız kendilerine ulaştı."},{"n":5,"t":"Kendilerine azabımız geldiği vakit, \"Gerçekten bizler zalimler imişiz\" demekten başka sözleri olmadı."},{"n":6,"t":"Kendilerine mesaj gönderilenleri de sorguya çekeceğiz, elçileri de sorguya çekeceğiz."},{"n":7,"t":"Onlara bir bilgiyle bildireceğiz; biz onlardan hiç uzak kalmadık."},{"n":8,"t":"O gün tartı dosdoğrudur. Tartıları ağır gelenler başarmış olanlardır."},{"n":9,"t":"Tartıları hafif gelenler ise ayetlerimize karşı haksız davranarak kişiliklerini yitirmiş olanlardır."},{"n":10,"t":"Sizleri yeryüzüne yerleştirdik ve orada size yaşama imkânları sağladık. Ne kadar da az şükrediyorsunuz."},{"n":11,"t":"Sizi yarattık, sonra size biçim verdik, sonra meleklere, \"Adem’e secde edin\" dedik. İblis hariç hepsi secde etti; o secde edenlerden olmadı."},{"n":12,"t":"Dedi: \"Sana emrettiğim zaman seni secde etmekten ne alıkoydu?\" Dedi: \"Ben ondan daha iyiyim; Sen beni ateşten yarattın, onu ise balçıktan yarattın\""},{"n":13,"t":"\"Oradan aşağı in\" dedi, \"Orada büyüklük taslayamazsın. Defol. Değerini yitirdin!\""},{"n":14,"t":"\"Dirilecekleri güne kadar bana süre tanı\" dedi."},{"n":15,"t":"\"Sana süre tanınmıştır\" dedi."},{"n":16,"t":"\"Beni saptırmana karşılık, onlar için senin dosdoğru yolun üzerine sinsice oturacağım.\""},{"n":17,"t":"\"Sonra önlerinden, arkalarından, sağlarından ve sollarından kendilerine sokulacağım. Böylece çoklarını şükreder bulmayacaksın.\""},{"n":18,"t":"Dedi ki: \"Horlanmış ve kovulmuş olarak oradan çık. Onlardan sana uyanlara gelince, hepinizle cehennemi dolduracağım.\""},{"n":19,"t":"\"Adem, sen ve eşin bahçede durup dilediğiniz yerden yeyin. Şu ağaçtan yemeyin; yoksa zalimlerden olursunuz.\""},{"n":20,"t":"Sapkın, kendilerinden gizlenmiş olan bedenlerini ortaya çıkarmak için onlara fısıldadı: \"Efendinizin sizi bu ağaçtan menetmesinin sebebi, ikinizin birer melek veya birer ebedî varlık olmamanız içindir\" dedi."},{"n":21,"t":"Kendilerine yemin de etti: \"Ben size öğüt veriyorum.\""},{"n":22,"t":"Böylece onları yalanlarla aldattı. Ağacı tadınca bedenleri kendilerine göründü. Üzerlerini bahçe yapraklarıyla örtmeye başladılar. Rab’leri kendilerini çağırdı: \"O ağaçtan ikinizi menetmedim mi ve sapkının ikinize düşman olduğunu söylemedim mi?\""},{"n":23,"t":"Her ikisi: \"Efendimiz, kendimize zulmettik. Bizi bağışlamaz ve bize acımazsan kaybedenlerden oluruz\" dediler."},{"n":24,"t":"Dedi ki: \"Birbirinize düşmanlar olarak aşağı ininiz. Bir süreye kadar yeryüzünde yerleşip geçineceksiniz.\""},{"n":25,"t":"Dedi ki: \"Orada yaşayacak, orada ölecek ve oradan çıkarılacaksınız.\""},{"n":26,"t":"Ademoğulları, size, bedeninizi örtecek ve süsleyecek elbiseler hazırladık. Erdemlilik elbisesi ise daha hayırlıdır. Bunlar, ALLAH’ın işaretleridir, olur ki öğüt alırsınız."},{"n":27,"t":"Ademoğulları, sapkın, ana babanızın vücutlarını kendilerine göstermek için elbiselerini soyarak bahçeden çıkardığı gibi sizi de şaşırtmasın. O ve kabilesi sizin onları görmediğiniz yerden sizi görürler. Biz, sapkınları, onaylamayanların dostları yaptık."},{"n":28,"t":"Herhangi bir kötü şey işledikleri zaman, \"Atalarımızı, ecdadımızı böyle yapar bulduk; ALLAH da bize öyle emretti\" derler. De ki: \"ALLAH kötü bir şeyi emretmez. ALLAH hakkında nasıl olur da bilmediklerinizi söylersiniz?\""},{"n":29,"t":"De ki: \"Efendim adaleti emreder. Her mescitte dini sadece O’na ait kılarak O’na yalvarın. Sizi ilk yarattığı gibi O’na döneceksiniz.\""},{"n":30,"t":"Bir grubu doğru yola iletti, bir grup da sapıklığı hak etti. Onlar, sapkınları ALLAH’tan başka dostlar edindiler ama kendilerini doğru yolda sanıyorlar."},{"n":31,"t":"Ademoğulları, mescitlere giderken süsleniniz. Yeyiniz içiniz; ancak oburluk ve savurganlık yapmayınız. O, oburları ve savurganları sevmez."},{"n":32,"t":"De ki: \"ALLAH’ın, kendi kulları için yarattığı süsleri ve güzel rızıkları kim haram edebilir?\" De ki: \"Onlar dünya hayatında gerçeği onaylayanlar içindir, ahirette ise sadece onlar içindir.\" Bilen bir toplum için ayetlerimizi böyle detaylı açıklarız."},{"n":33,"t":"De ki: \"Efendim, ancak kötü işlerin açığını ve gizlisini, günahları, haksız yere saldırmayı, kendilerine hiçbir otorite ve güç vermediği bir şeyi ALLAH’a ortak koşmanızı ve ALLAH hakkında bilmediğiniz şeyleri söylemenizi haram kılmıştır.\""},{"n":34,"t":"Her bir toplumun bir süresi vardır. Süreleri gelince ne bir an erteleyebilirler, ne de öne alabilirler."},{"n":35,"t":"Ademoğulları, size içinizden elçiler gelip size ayetlerimi bildirdikleri zaman dinleyip kendilerini düzeltenlere ne bir korku vardır ne de onlar üzülürler."},{"n":36,"t":"Büyüklük taslayarak ayetlerimizi yalanlayanlar ise ateş halkıdır; orada ebedî kalıcıdırlar."},{"n":37,"t":"ALLAH’a yalan iftira edenden veya ayetlerini yalanlayandan daha zalim kim olabilir? Onların kitapta anlatılan payları kendilerine erişecektir. Elçilerimiz kendilerine gelip canlarını alırken: \"Allah’ın dışında hizmet ettikleriniz nerede\" dediklerinde, \"Bizi terk ettiler\" derler. İnkârcı olduklarına dair kendi aleyhlerinde tanıklık ederler."},{"n":38,"t":"\"Sizden önce geçen cin ve insan topluluklarıyla birlikte ateşe girin\" dedi. Her ne zaman bir topluluk girdiyse bir öncekine lanet etti. Hepsi oraya vardığında sonrakiler öncekiler için: \"Efendimiz, bizi bunlar saptırdı. Bunlara ateşten bir kat daha fazla azap ver\" dediler. \"Hepsi için iki kat vardır. Ancak bilmezsiniz\" dedi."},{"n":39,"t":"Öncekiler sonrakilere, \"Sizin bize bir üstünlüğünüz yoktur. Kazandıklarınızdan ötürü azabı tadın\" dediler."},{"n":40,"t":"Ayetlerimizi inkâr edenlere ve onlara karşı büyüklük taslayanlara göğün kapısı açılmaz ve deve iğne deliğinden geçmedikçe de bahçeye girmezler. Suçluları böyle cezalandırırız."},{"n":41,"t":"Onlar için cehennemden bir yatak ve üstlerinde de bir örtü vardır. Zalimleri işte böyle cezalandırırız."},{"n":42,"t":"Gerçeği onaylayıp erdemli bir hayat sürenlere gelince, biz hiç kimseye kapasitesinin üstünde sorumluluk yüklemeyiz; onlar bahçe halkıdır. Onlar orada ebedî kalıcıdırlar."},{"n":43,"t":"Göğüslerinden kin ve kıskançlık duygularını çıkardık. Altlarından nehirler akarken: \"Bizi buna ulaştıran ALLAH’a övgüler olsun. ALLAH bizi doğruya iletmeseydi biz doğruyu bulamazdık. Efendimizin elçileri gerçeği getirmişlerdi\" dediler. Kendilerine: \"İşte bu bahçe sizindir. Yaptıklarınıza karşılık olarak onu miras aldınız\" diye seslendik."},{"n":44,"t":"Bahçe halkı cehennem halkına seslenir: \"Efendimizin bize söz verdiğini gerçek olarak bulduk. Efendinizin size söz verdiğini siz de gerçek olarak buldunuz mu?\" \"Evet!\" derler. Biri aralarında şunu ilan eder: \"ALLAH’ın laneti zalimlerin üzerine olsun.\""},{"n":45,"t":"Onlar ki ALLAH’ın yolundan alıkoyarlar ve onu eğriltmek isterler. Ahiret konusunda da inkârcıdırlar."},{"n":46,"t":"Aralarını bir perde böler. Kimlik istasyonunda bazı kimseler var ki herkesi görünüşlerinden tanırlar. Bahçe halkına, \"Selam size\" diye seslenirler. Bunlar oraya, canları istedikleri halde giremediler."},{"n":47,"t":"Gözleri ateş halkına çevrildiğinde, \"Efendimiz, bizi zalim toplulukla birlikte bulundurma\" derler."},{"n":48,"t":"Kimlik istasyonunda bulunanlar, görünüşlerinden tanıdıkları kimselere seslenirler: \"Sizin cemaatiniz ve büyüklük taslamış olmanız size hiçbir yarar sağlamadı.\""},{"n":49,"t":"\"ALLAH onlara bir rahmet dokundurmayacak’ diye yemin ettiğiniz kimseler bunlar mıydı? Bahçeye girin; size bir korku yoktur ve üzülmeyeceksiniz de.\""},{"n":50,"t":"Ateş halkı, bahçe halkına seslendi: \"Suyunuzdan, yahut ALLAH’ın size verdiği bazı nimetlerden üstümüze akıtın.\" Onlar da dediler ki: \"ALLAH bu ikisini kâfirlere haram kılmıştır.\""},{"n":51,"t":"Onlar dinlerini hafife aldılar ve dünya hayatı kendilerini aldattı. Bugünleriyle karşılaşacaklarını unuttukları ve ayetlerimizi reddettikleri için bugün onları unuturuz!"},{"n":52,"t":"Bilgiyle detaylandırdığımız, gerçeği onaylayan bir toplum için yol gösterici ve rahmet olan bir kitabı onlara getirdik."},{"n":53,"t":"Onun haberlerinin gerçekleşmesini mi bekliyorlar? Haberleri gerçekleştiği gün, onu daha önce önemsemeyenler, \"Efendimizin elçileri gerçeği getirmişlerdi. Bizim için aracılık edecek bir şefaatçi var mı? Yahut, öncekinden farklı davranmak için geri gönderilsek\" derler. Kişiliklerini yitirmişlerdir ve uydurdukları şeyler de onları terk etmiştir."},{"n":54,"t":"Efendiniz ALLAH, gökleri ve yeri altı günde yaratan ve sonra otoritesini kurandır. Geceyi, onu durmadan kovalayan gündüze bürüyüp örter. Güneş, ay ve yıldızlar O’nun yönetimine boyun eğmiştir. Yaratılış da, yönetim de O’na aittir. Evrenlerin Rabbi olan ALLAH ne uludur!"},{"n":55,"t":"Efendinizi içtenlikle ve gizlice çağırın. O, sınırı aşanları sevmez."},{"n":56,"t":"Düzeltildikten sonra yeryüzünde bozgunculuk yapmayın. O’na korku ve umutla yalvarın. ALLAH’ın rahmeti güzel davrananlara yakındır."},{"n":57,"t":"O, rahmetinin bir ön müjdesi olarak rüzgarları gönderendir. Toplanıp yüklendikten sonra ağır bulutları ölü bir toprağa süreriz. Onunla su indirir ve onunla her çeşit ürünü çıkarırız. Ölüleri de böyle çıkarırız. Belki bundan bir öğüt alırsınız."},{"n":58,"t":"İyi arazi, Efendinin izniyle bitki verir. Kötü olanı ise, pek yararlı bir şey vermez. Şükreden bir topluluk için ayetleri böyle açıklarız."},{"n":59,"t":"Nuh’u halkına gönderdik: \"Ey halkım, ALLAH’a hizmet edin. O’ndan başka bir tanrınız yoktur. Sizin için büyük günün azabından korkarım\" dedi."},{"n":60,"t":"Halkının ileri gelenleri, \"Seni apaçık bir sapıklık içinde görüyoruz\" dediler."},{"n":61,"t":"Dedi ki: \"Halkım, bende bir sapıklık yoktur; ancak ben evrenlerin Rabbi tarafından gönderilmiş bir elçiyim.\""},{"n":62,"t":"\"Size Efendimin mesajını iletiyor ve size öğüt veriyorum. Sizin bilmediklerinizi ALLAH aracılığıyla biliyorum.\""},{"n":63,"t":"\"Sizi uyarmak için ve erdemli bir hayat sürüp merhamet edilmeniz için sizden bir adama Efendinizden bir mesajın gelmesine mi şaştınız?\""},{"n":64,"t":"Onu yalanladılar. Bunun üzerine onu ve gemide beraberinde bulunanları kurtardık. Ayetlerimizi yalanlayanları ise boğduk. Onlar kör bir halktı."},{"n":65,"t":"Ad halkına da kardeşleri Hud’u gönderdik. \"Halkım, ALLAH’a hizmet edin. O’ndan başka bir tanrınız yoktur. Erdemli olmayacak mısınız?\" dedi."},{"n":66,"t":"Halkından ileri gelen inkârcılar, \"Biz seni beyinsizlik içinde görüyoruz. Biz seni yalancı sanıyoruz.\""},{"n":67,"t":"Dedi ki: \"Ey halkım, ben beyinsiz değilim; fakat ben, evrenlerin Efendisinden bir elçiyim.\""},{"n":68,"t":"\"Size Efendimin mesajını iletiyorum. Sizin için güvenilir bir öğütçüyüm.\""},{"n":69,"t":"\"Sizi uyarmak amacıyla Efendinizden bir mesajın aranızdan bir adama gelmesine mi şaştınız? Nuh’un halkından sonra sizi vârisler yaptığını ve yaratılışta sizi onlardan güçlü kıldığını hatırlayın. Başarmanız için ALLAH’ın nimetlerini düşünün.\""},{"n":70,"t":"Dediler ki: \"Sadece ALLAH’a hizmet edelim ve atalarımızın hizmet ettiklerini terk edelim diye mi bize geldin? Doğru sözlü isen bizi kendisiyle tehdit ettiğin şeyi getir bakalım.\""},{"n":71,"t":"Dedi ki: \"Efendinizden bir azap ve öfkeye mahkûm edilmiş bulunuyorsunuz. Sizin ve atalarınızın uydurduğu ve ALLAH’ın kendilerine hiçbir güç vermediği isimler konusunda mı benimle tartışıyorsunuz? Bekleyiniz, ben de sizinle birlikte bekleyenlerdenim.\""},{"n":72,"t":"Bizden bir rahmet olarak, onu ve onunla birlik olanları kurtardık. Ayetlerimizi yalanlayarak onaylamayanların da ardını kestik."},{"n":73,"t":"Semud halkına da kardeşleri Salih’i gönderdik. Dedi ki: \"Ey halkım, ALLAH’a hizmet edin. O’ndan başka bir tanrınız yoktur. Efendinizden, size bir kanıt (beyyine) gelmiştir. Şu ALLAH’ın devesi sizin için bir işaret olacaktır. Onu bırakın, ALLAH’ın toprağında otlasın. Ona bir zarar vermeyin; yoksa sizi acı bir azap yakalar.\""},{"n":74,"t":"\"Ad halkından sonra sizi vârisler kıldığını hatırlayın. Sizi yeryüzüne yerleştirdi. Düzlüklerinde köşkler kurup dağlarında evler yontuyorsunuz. ALLAH’ın nimetlerini hatırlayın da yeryüzünde bozgunculuk yaparak karışıklık çıkarmayın.\""},{"n":75,"t":"Halkının büyüklük taslayan ileri gelenleri, aşağılayıp zulmettikleri gerçeği onaylayanlara, \"Salih’in gerçekten Rabbi tarafından gönderilmiş olduğunu nereden biliyorsunuz\" dediler. Onlar da: \"Biz onun getirdiği mesajı onaylıyoruz\" dediler."},{"n":76,"t":"Büyüklük taslayanlar, \"Biz, sizin onayladığınız şeyi inkâr ediyoruz\" dediler."},{"n":77,"t":"Deveyi işkence ederek kestiler ve Rab’lerinin emrine başkaldırdılar: \"Salih, gerçekten elçilerden birisi isen, bizi tehdit ettiğin azabı başımıza getir\" dediler."},{"n":78,"t":"Bunun üzerine, onları o sarsıntı yakaladı; evlerinde dizüstü çöküverdiler."},{"n":79,"t":"O da onlardan yüz çevirdi ve \"Ey halkım, size Efendimin elçiliğini ilettim, size öğüt verdim; fakat siz öğüt verenleri sevmiyorsunuz\" dedi."},{"n":80,"t":"Ve Lut’u da gönderdik. Halkına dedi ki: \"Sizden önce hiç kimsenin kıramadığı birgünahın rekorunu mu kırıyorsunuz?\""},{"n":81,"t":"\"Siz kadınları bırakıp erkeklere cinsel duygularla yöneliyorsunuz. Siz sınırı aşan bir topluluksunuz!\""},{"n":82,"t":"Halkının cevabı, ancak şunları söylemek oldu: \"Onları kentinizden çıkarın. Bunlar çok temiz insanlarmış!\""},{"n":83,"t":"Onu ve ailesini kurtardık. Karısı hariç. O geride kalanlardan oldu."},{"n":84,"t":"Üstlerine bir yağmur yağdırdık. Suçluların sonuna bak!"},{"n":85,"t":"Medyen’e de kardeşleri Şuayb’ı gönderdik. Dedi ki: \"Ey halkım, ALLAH’a hizmet edin. O’ndan başka tanrınız yoktur. Efendinizden size açık bir kanıt gelmiş bulunuyor. Ölçü ve tartıyı tam uygulayın. Halkın hakkını yemeyin. Düzeltildikten sonra yeryüzünde bozgunculuk yapmayın. Gerçeği onaylıyorsanız bunlar sizin için daha hayırlıdır.\""},{"n":86,"t":"\"ALLAH’ın yolunu eğriltmek ve gerçeği onaylayanları tehdit edip ondan çevirmek için her yolun başına oturmayın. Sayıca az iken sizi nasıl da çoğalttığını düşünün. Bozguncuların sonunun nasıl olduğuna bir bakın.\""},{"n":87,"t":"\"Madem ki sizden bir kısmı benimle gönderilen mesajı onaylamış, bir kısmı da onaylamamış bulunuyor, öyleyse ALLAH aramızda hükmedinceye kadar sabredin. O, hükmedenlerin en iyisidir.\""},{"n":88,"t":"Halkının büyüklük taslayan ileri gelenleri, \"Şuayb, ya seni ve seninle beraber gerçeği onaylayanları kentimizden süreceğiz ya da dinimize geri dönersin!\" dediler. O da şöyle dedi: \"Biz istemesek de mi?\""},{"n":89,"t":"\"ALLAH bizi sizin dininizden kurtardıktan sonra ona dönersek ALLAH’a yalan yakıştırmış oluruz. Efendimiz ALLAH dilemedikçe ona tekrar dönmemiz söz konusu olamaz. Efendimiz her şeyi bilgisiyle kuşatmıştır. Biz yalnız ALLAH’a güvendik. Bizimle halkımızın arasını hak ile aç ey Efendimiz. Sen açığa çıkaranların en hayırlısısın."},{"n":90,"t":"Halkının ileri gelen inkârcıları, \"Şuayb’a uyarsanız kaybedenlerden olursunuz\" dediler."},{"n":91,"t":"Bunun üzerine onları bir sarsıntı yakaladı da evlerinde dizüstü çöküverdiler."},{"n":92,"t":"Şuayb’ı yalanlayanlar sanki hiç orada yaşamamışlar gibi yok oldular. Şuayb’ı yalanlayanlar, asıl kaybedenler onlar oldular."},{"n":93,"t":"Onlardan yüz çevirdi ve \"Ey halkım, size Efendimin mesajını ilettim, öğüt verdim. İnkârcı bir topluluğa nasıl acırım?\""},{"n":94,"t":"Her ne zaman bir ülkeye bir peygamber gönderdiysek, yalvarsınlar diye halkını darlık ve sıkıntıya uğrattık."},{"n":95,"t":"Sonra kötülüğün yerine iyiliği getirdik. Ne var ki anlayışlarını yitirdiler: \"Sıkıntı ve refah atalarımıza da dokunmuştu\" dediler. Bunun üzerine, haberleri olmadan onları ansızın yakaladık."},{"n":96,"t":"Ülkelerin halkları Gerçeği onaylayıp erdemli davransalardı, göklerden ve yerden üzerlerine bolluk kapısını açardık. Ama yalanladılar ve bunun üzerine kazandıklarıyla birlikte onları yakaladık."},{"n":97,"t":"Ülkelerin halkları, azabımızın geceleyin onlar uyurlarken kendilerine gelmeyeceğinden emin mi oldular?"},{"n":98,"t":"Ülkelerin halkları, azabımızın gündüzün onlar oynarlarken kendilerine gelmeyeceğinden emin mi oldular?"},{"n":99,"t":"ALLAH’ın planından emin mi oldular? Kaybedenlerden başkası ALLAH’ın planından emin olmaz."},{"n":100,"t":"Önceki nesillerin yerine yeryüzüne vâris olanlara belli olmadı mı ki, eğer dilesek onları da günahlarıyla cezalandırarak kalplerini mühürleriz de işitemezler."},{"n":101,"t":"Bunlar, sana haberlerini aktardığımız toplumlardır. Elçileri, onlara apaçık delillerle gitmişlerdi. Ama daha önceden yalanladıklarını onaylayacak değillerdi. ALLAH kâfirlerin kalplerini böyle damgalar."},{"n":102,"t":"Çoğunu, verdikleri sözü tutanlar olarak bulmadık, aksine çoğunu yoldan çıkmış bulduk."},{"n":103,"t":"Sonra, onların ardından Firavun ve erkanına Musa’yı ayet ve mucizelerimizle gönderdik; fakat ayet ve mucizelerimize karşı haksızlık ettiler. Bozguncuların sonunun nasıl olduğuna dikkat et!"},{"n":104,"t":"Musa: \"Firavun, ben alemlerin Efendisinden bir elçiyim.\""},{"n":105,"t":"\"ALLAH hakkında gerçeğin dışında bir şey söylememek benim görevimdir. Efendinizden size bir kanıt ile geldim; İsrailoğullarını benimle birlikte salıver.\""},{"n":106,"t":"Dedi: \"Bir ayet ile gelmişsen ve gerçekten doğru sözlüysen getir onu bakalım.\""},{"n":107,"t":"Asasını attı, iri bir yılan oluverdi."},{"n":108,"t":"Elini çıkardı, bakanlar için bembeyaz oluverdi."},{"n":109,"t":"Firavunun halkından ileri gelenler, durumu tartıştılar ve \"Bu, uzman bir sihirbazdır\" dediler,"},{"n":110,"t":"\"Sizi yurdunuzdan çıkarmak istiyor. Ne önerirsiniz?\""},{"n":111,"t":"Dediler ki: \"Onu ve kardeşini beklet ve şehirlere toplayıcılar yolla.\""},{"n":112,"t":"\"Bütün uzman sihirbazları sana getirsinler.\""},{"n":113,"t":"Sihirbazlar Firavuna geldiler ve \"Kazanırsak bize bir ödül var mı\" dediler."},{"n":114,"t":"\"Evet\" dedi, \"Siz benim yakın çevreme de girersiniz.\""},{"n":115,"t":"Dediler: \"Musa, sen at, yoksa biz atacağız.\""},{"n":116,"t":"\"Siz atın!\" dedi. Onlar atınca, halkın gözünü büyülediler, onları korkuttular ve böylece büyük bir sihir ortaya koydular."},{"n":117,"t":"Biz de Musa’ya \"Asanı at\" diye vahyettik. Nitekim o, onların uydurduklarını toplayıp yutuverdi."},{"n":118,"t":"Böylece, gerçek gerçekleşti ve yaptıkları boşa çıktı."},{"n":119,"t":"İşte orada yenildiler ve küçük düşürüldüler."},{"n":120,"t":"Ve sihirbazlar secdeye kapandılar."},{"n":121,"t":"\"Evrenlerin Efendisini onayladık\" dediler,"},{"n":122,"t":"\"Musa’nın ve Harun’un Efendisine…\""},{"n":123,"t":"Firavun: \"Ben size izin vermeden mi onu onayladınız? Bu bir plandır. Şehirde bu planı kurdunuz ki halkını oradan çıkarasınız. Ama yakında bileceksiniz!\" dedi,"},{"n":124,"t":"\"Ellerinizi ve ayaklarınızı çaprazlama keseceğim ve sonra topunuzu asacağım!\""},{"n":125,"t":"Dediler ki: \"Biz zaten Efendimize döneceğiz.\""},{"n":126,"t":"\"Efendimizin işaretleri bize geldiğinde onu onayladık diye bizden öç alıyorsun. Efendimiz, bize dayanma gücü ver ve canımızı Müslümanlar olarak al.\""},{"n":127,"t":"Firavunun halkının elit takımı, \"Musa’yı ve halkını, seni ve tanrılarını bıraksınlar ve yeryüzünde bozgunculuk çıkarsınlar diye mi bırakıyorsun\" dediler. \"Kadınlarını utandırıp oğullarını öldüreceğiz. Biz onlardan çok daha güçlüyüz\" dedi."},{"n":128,"t":"Musa, halkına: \"ALLAH’tan yardım dileyin, sabırla direnin. Yeryüzü ALLAH’ındır ve onu kullarından dilediğine verir. Sonuç erdemli davrananlarındır\" dedi."},{"n":129,"t":"\"Sen bize gelmeden önce de, bize geldikten sonra da eziyet edildik\" dediler. (Musa da) \"Umulur ki Efendiniz düşmanınızı yok ederek onların yerine sizleri yeryüzüne yerleştirsin ve sonra nasıl davranacağınıza baksın\" dedi."},{"n":130,"t":"Firavun tarafını, öğüt alsınlar diye yıllarca kuraklık ve ürün kıtlığına mahkûm ettik."},{"n":131,"t":"Kendilerine bir iyilik geldiği zaman, \"Bunu biz hak ettik\" derler, kendilerine bir kötülük dokunduğu zaman ise Musa ve beraberindekileri uğursuzlukla suçlarlardı. Doğrusu, onların uğursuzluğu ALLAH tarafından kararlaştırılır. Ancak çokları bilmezler."},{"n":132,"t":"\"Bizi büyülemek için ne kadar işaret (ayet) getirirsen getir, biz seni onaylayacak değiliz\" dediler."},{"n":133,"t":"Üzerlerine tufan, çekirge, haşerat, kurbağa ve kan gibi ayrı ayrı işaretler gönderdik. Buna rağmen büyüklük taslamaya devam ettiler ve suçlu bir topluluk oldular."},{"n":134,"t":"Her ne zaman başlarına bir musibet gelse, \"Ey Musa, sana verdiği sözden dolayı Efendine yalvar. Bizi bu felaketlerden kurtarırsan seni onaylar ve İsrailoğullarını da seninle beraber yollarız\" dediler."},{"n":135,"t":"Onları söz konusu felaketlerden herhangi bir süre için kurtarınca da sözlerinden dönüyorlardı."},{"n":136,"t":"Bunun üzerine onlardan öç aldık. Ayetlerimizi yalanlayıp aldırış etmedikleri için onları denizde boğduk."},{"n":137,"t":"Ülkenin verimli kıldığımız doğularına ve batılarına, horlanan ve zayıf düşürülen insanları mirasçı kıldık. Sıkıntılara direndikleri için, Efendinin İsrailoğullarına verdiği güzel söz gerçekleşti. Firavun ve halkının oluşturduğu yapı ve kurumları da yerle bir ettik."},{"n":138,"t":"İsrailoğullarını denizden geçirdik. Kendilerine özgü heykellere hizmet eden bir topluluğa rastladılar ve: \"Musa, bunların tanrıları gibi bize de bir tanrı yap\" dediler. \"Siz, gerçekten cahil bir topluluksunuz!\" dedi."},{"n":139,"t":"\"Bunlar, daldıkları bu şeylerle helak olacaklar ve yaptıkları ise hiçbir temele dayanmıyor.\""},{"n":140,"t":"\"Size Allah’tan aşağı bir tanrı mı arayayım? Oysa O, lütfuyla sizi başkalarına tercih etti.\""},{"n":141,"t":"\"Hani size en kötü azabı uygulayan Firavunun taraftarlarından sizi kurtarmıştık. Kadınlarınızı utandırıp çocuklarınızı öldürüyorlardı. Bunda Efendinizden sizin için büyük bir sınav vardı.\""},{"n":142,"t":"Musa ile otuz gece için sözleştik ve ona on gece daha ekledik. Böylece Efendinin belirlediği vakit kırk geceye tamamlandı. Musa, kardeşi Harun’a, \"Halkım içinde benim yerime geç, doğru davran. Bozgunculuk yapanların yoluna da uyma\" dedi."},{"n":143,"t":"Musa, belirlenen vakitte bize gelince ve Rabbi kendisiyle konuşunca, \"Efendim, bana görün, sana bakayım\" dedi. \"Beni göremezsin. Ancak şu dağa bak; yerinde durursa o zaman beni göreceksin\" dedi. Rabbi, dağa görününce onu paramparça etti ve bunun üzerine Musa kendinden geçti. Ayılınca, \"Sen yücesin, sana yöneliyorum. Ben gerçeği onaylayanların en önde olanıyım\" dedi."},{"n":144,"t":"Dedi ki: \"Musa, mesajlarımla ve seninle konuşmamla seni halkın üzerine seçtim. Sana verdiklerimi al ve şükredenlerden ol.\""},{"n":145,"t":"Her şeyin detaylı açıklaması ve öğüt olarak her ne varsa Musa için levhalara yazdık: \"Bu öğretilere sıkı sarıl, halkına da söyle ona en güzel biçimde sarılsınlar. Yoldan çıkmışların son durağını size göstereceğim.\""},{"n":146,"t":"Yeryüzünde haksız yere büyüklenenleri mucizelerimden çevireceğim. Her türlü mucizeyi de görseler onaylamazlar. Doğru yolu görseler onu yol edinmezler. Ama azgınlık yolunu görseler onu yol edinirler. Zira onlar ayetlerimizi yalanladılar ve aldırış etmediler."},{"n":147,"t":"Ayetlerimizi ve ahiret buluşmasını inkâr edenlerin yaptıkları boşunadır. Yaptıklarının karşılığını almayacaklar mı?"},{"n":148,"t":"Musa’nın halkı kendisinden sonra, süs eşyalarından, böğürmesi olan bir buzağı heykeli yapıp putlaştırdılar. Onun, konuşmaktan ve kendilerine yol göstermekten aciz olduğunu görmediler mi? Onu benimseyerek zalimlerden oldular."},{"n":149,"t":"Yaptıklarına pişman olup sapmış olduklarını anlayınca da, \"Efendimiz bize acımaz ve bizi bağışlamazsa kaybedenlerden oluruz\" dediler."},{"n":150,"t":"Musa, kızgın ve hayal kırıklığına uğramış olarak halkına döndüğü zaman, \"Benden sonra arkamdan ne kötü işler yaptınız! Efendinizin emrine dayanamadınız mı\" dedi, levhaları yere attı, kardeşinin başını tutup kendine doğru çekti. Bunun üzerine, \"Anamın oğlu,\" dedi, \"bu halk benim zayıflığımdan yararlandı, neredeyse beni öldüreceklerdi. Üzerime vararak düşmanı güldürme, beni bu zalim halkla bir tutma.\""},{"n":151,"t":"Dedi ki: \"Efendim, beni ve kardeşimi bağışla. Bize acı. Sen merhametlilerin en merhametlisisin.\""},{"n":152,"t":"Buzağıyı putlaştıranlar, Rab’lerinden bir gazaba ve dünya hayatında bir alçaklığa uğrayacaktır. İftiracıları böyle cezalandırırız."},{"n":153,"t":"Kötülük işledikten sonra tövbe edip gerçeği onaylayanlar için Efendin elbette ondan sonra Bağışlayandır, Rahimdir."},{"n":154,"t":"Musa’nın sinirleri yatışınca levhaları aldı. Onda Rab’lerini sayanlar için bir yol gösterme ve rahmet yazılıydı."},{"n":155,"t":"Bizimle randevu için, Musa, halkı arasından yetmiş kişi seçti. Kendilerini sarsıntı tutunca: \"Efendim, dileseydin beni ve onları daha önce yok ederdin. İçimizdeki beyinsizlerin yaptıklarından ötürü bizi yok mu edeceksin? Bu, Senin düzenlediğin bir sınav olmalı. Dilediğini onunla saptırır, dilediğini de onunla doğru yola iletirsin. Sahibimiz sensin; bizi bağışla bize acı. Sen en iyi Bağışlayansın\" dedi,"},{"n":156,"t":"\"Bu dünyada da bizim için iyilik yaz, ahirette de… Biz sana yöneldik.\" Dedi ki: \"Azabım dilediğim kimseye dokunacaktır. Rahmetim ise her şeyi kapsamıştır; onu özellikle: erdemli bir hayat sürenlere, zekâtı verenlere ve ayetlerimizi onaylayanlara yazacağım.\""},{"n":157,"t":"Nitekim onlar yanlarındaki Tevrat ve İncil’de yazılı buldukları o elçiyi, o ümmi (Tevrat ve İncil okumamış/başkentli) peygamberi izlerler. (O peygamber) onlara iyiliği emreder ve onları kötülükten meneder; onlara güzel şeyleri helal, pis şeyleri de haram kılar; üzerlerindeki ağırlıkları ve onlara vurulan prangaları kaldırıp atar. Onu onaylayanlar, ona saygı duyanlar, ona yardım edenler, kendisiyle birlikte indirilen ışığı izleyenler başarıya ulaşanlardır."},{"n":158,"t":"De ki: \"Ey halk, ben, hepiniz için, göklerin ve yerin egemenliğine sahip olan ALLAH’ın elçisiyim. O’ndan başka tanrı yok. Diriltir, öldürür.\" ALLAH’ı ve ümmi olan elçisini onaylayın, nitekim o da ALLAH’ı ve sözlerini onaylamaktadır. Ona uyun ki doğruyu bulasınız."},{"n":159,"t":"Musa’nın halkından bir topluluk var ki gerçeği gösterirler ve onunla adaleti sağlarlardı."},{"n":160,"t":"Onları on iki kabile halinde topluluklara ayırdık. Halkı kendisinden su istediği zaman Musa’ya, \"Asan ile taşa vur\" diye vahyettik. Ondan on iki göze fışkırdı ve her kabile içeceği yeri bildi. Ayrıca onları bulutlarla gölgelendirdik ve üzerlerine menna ve bıldırcın indirdik: \"Size verdiğim rızıklardan yiyin.\" Onlar bize haksızlık etmiyorlardı, kendi kendilerine haksızlık ediyorlardı."},{"n":161,"t":"Hatırla ki kendilerine, \"Bu şehirde oturun, oradan dilediğiniz gibi yiyin, dostça konuşun ve kapıdan alçak gönüllü olarak girin ki hatalarınızı bağışlayalım. İyilik yapanlara fazlasını vereceğiz\" denildiğinde,"},{"n":162,"t":"İçlerindeki zalimler kendilerine emredileni kendilerine emredilmeyenle değiştirdiler. Biz de haksızlık etmelerinden ötürü üzerlerine gökten bir felaket gönderdik."},{"n":163,"t":"Onlara deniz kenarındaki topluluktan sor. Hani Cumartesi çalışma yasağını çiğniyorlardı. Cumartesiye uydukları gün balıkları onlara akın akın geliyordu; ancak Cumartesiyi uygulamadıkları gün onlara balık gelmiyordu. Yoldan çıktıkları için onları böyle sınıyorduk."},{"n":164,"t":"İçlerinden bir topluluk: \"ALLAH’ın helak edeceği veya çetin bir biçimde azaplandıracağı bir halka ne diye öğüt veriyorsunuz\" dedi. Dediler ki: \"Efendinizden özür dileyin\" belki dinleyip kurtulurlar."},{"n":165,"t":"Kendilerine hatırlatılanları önemsemeyip unutunca, kötülüklerle mücadele edenleri kurtardık; haksızlık edenleri de yoldan çıkmalarına karşılık olarak feci bir azap ile yakaladık."},{"n":166,"t":"Kendilerine yasaklananlara uymayınca da onlara, \"Aşağılık maymunlar olun!\" dedik."},{"n":167,"t":"Ayrıca Efendin, diriliş gününe kadar onlara cezaların en kötüsünü verecek kimseler göndereceğini bildirdi. Efendin çabuk sonuçlandırandır ve elbette O, Bağışlayandır, Rahimdir."},{"n":168,"t":"Onları yeryüzünde topluluklara ayırdık. Bir kısmı iyi, diğer bir kısmı ise aşağılık durumdaydı. Dönerler diye onları iyilikler ve kötülüklerle sınadık."},{"n":169,"t":"Onların yerine, kitaba mirasçı olan başka nesiller geçti. Ancak, \"Nasıl olsa bağışlanacağız\" diyerek aşağılık ve geçici menfaatleri seçtiler. Kendilerine, benzeri geçici menfaatler gelse yine seçerler. Onlardan, kitaba bağlı kalacaklarına ve ALLAH hakkında ancak gerçeği söyleyeceklerine dair söz alınmamış mıydı? Onu okuyup öğrenmediler mi? Erdemliler için ahiret yurdu daha hayırlıdır. Anlamıyor musunuz?"},{"n":170,"t":"Kitaba sarılanlar ve namaz kılanlara gelince, iyiliğe çalışanları ödülsüz bırakmayız."},{"n":171,"t":"Dağı bir şemsiye gibi üzerlerinde sarsmıştık. Öyle ki tepelerine düşeceğini sanmışlardı: \"Size verdiğime sımsıkı sarılın. Kurtulabilmeniz için içeriği üzerinde düşünün.\""},{"n":172,"t":"Efendin, Ademoğullarının bellerinden soylarını çıkarırken onları kendi kendilerine tanık tutar: \"Ben, Efendiniz değil miyim?\" \"Evet, tanıklık ediyoruz\" derler. Böylece diriliş günü, \"Biz bundan habersizdik\" diyemezsiniz."},{"n":173,"t":"Yahut, \"Atalarımız önceden ortak koştu ve biz de onlardan sonra gelen soylarıyız, bizi bidat ve hurafelere dalanlardan dolayı mı yok edeceksin\" diyemezsiniz."},{"n":174,"t":"Ayetleri böyle açıklıyoruz ki (bize) dönebilsinler."},{"n":175,"t":"Kendisine ayetlerimizi verdiğimiz, ancak onlardan sıyrılmış-geçmiş kimsenin ne duruma düştüğünü anlat onlara. Sapkın onu saptırıncaya kadar izlemişti."},{"n":176,"t":"Dileseydik onu ayetlerimizle yükseltirdik. Fakat o, dünyaya saplandı ve hevesinin ardına takıldı. Onun durumu, üstüne varsan da bıraksan da dili dışarıda soluyan huysuz bir köpeğin durumuna benzer. Ayetlerimizi yalanlayan toplulukların durumu işte böyledir. Bu olayı aktar, olur ki düşünürler."},{"n":177,"t":"Ayetlerimizi yalanlayan ve yalnızca kendi kendilerine haksızlık eden topluluğun örnekliği ne kötüdür!"},{"n":178,"t":"ALLAH kimi doğruya iletirse, doğruyu bulan odur. Kimi de saptırırsa, kaybedenler de onlardır."},{"n":179,"t":"İnsanlardan ve cinlerden çok sayıda kişiyi cehenneme mahkûm ettik. Kalpleri var, fakat kavrayamazlar; gözleri var, fakat görmezler; kulakları var, fakat işitmezler. Onlar, çiftlik hayvanları gibidir, hatta daha da kötü… Ve onlar, olup bitenden habersizdirler."},{"n":180,"t":"En güzel isimler ALLAH’ındır; öyleyse O’nu onlarla çağırın. O’nun isimlerini tahrif edenleri bırakın; yaptıklarının cezasını çekeceklerdir."},{"n":181,"t":"Yarattıklarımızın arasında bir topluluk var ki gerçek ile yol gösterirler ve yine onunla hakkı gözetirler."},{"n":182,"t":"Ayetlerimizi yalanlayanlara gelince, onlar farkına varmadan onları yavaş yavaş sonlarına yaklaştıracağız."},{"n":183,"t":"Hatta onlara umut veririm. Planım çetindir."},{"n":184,"t":"Düşünmezler mi? Arkadaşlarında hiçbir delilik yoktur. O, ancak apaçık bir uyarıcıdır."},{"n":185,"t":"Göklerin ve yerin egemenliğine ve ALLAH’ın yarattığı şeylere bakmazlar mı? Son anlarının yaklaşmış olabileceğini hiç düşünmezler mi? Bundan sonra artık hangi hadisi (sözü) onaylarlar?"},{"n":186,"t":"ALLAH’ın saptırdığı kimseler için yol gösterici bulunmaz. Onları, azgınlıkları içinde bocalar durur halde bırakır."},{"n":187,"t":"Sana o anın ne zaman geleceğini soruyorlar. \"O’nun bilgisi Efendimin yanındadır\" de. Onu vakti gelince O’ndan başkası ortaya çıkarmaz. Göklere ve yere ağır gelen o an size ansızın gelecektir. Sanki ondan haberdar imişsin gibi sana soruyorlar. \"Onun bilgisi ALLAH’ın yanındadır\" de. Fakat insanların çoğu bilmez."},{"n":188,"t":"De ki: \"ALLAH’ın dilediğinden başka ben kendime ne bir yarar ne de bir zarar veremem. Gizliyi bilseydim mal varlığımı arttırırdım, bana kötülük de dokunmazdı. Ben ancak gerçeği onaylayan bir topluma bir müjdeci ve uyarıcıyım.\""},{"n":189,"t":"O sizi bir tek nefisten (aynı genetik özellikten) yarattı. Ondan da eşini yarattı ki dinginlik bulsun. Eşine yaklaşınca, hafif bir yükle yüklendi ve onunla gezindi. Yükü ağırlaşınca her ikisi Rab’leri ALLAH’a: \"Bize kusursuz bir çocuk verirsen şükredenlerden olacağız\" diye yalvardılar."},{"n":190,"t":"Onlara kusursuz bir çocuk verince, O’nun kendilerine verdiği bu hediyeyle ilgili olarak O’na ortaklar koşmaya başladılar. ALLAH onların ortak koştukları her şeyden çok yücedir."},{"n":191,"t":"Bir şey yaratamayan, aksine yaratılmış olan şeyleri mi eş koşuyorlar?"},{"n":192,"t":"Putlar, ne onlara yardım edebilir, ne de kendilerine yardım edebilirler."},{"n":193,"t":"Onları doğruya çağırsanız size uymazlar. Onları ha çağırmışsınız, ha sessiz kalmışsınız, sizin için birdir."},{"n":194,"t":"ALLAH’ın dışında çağırdıklarınız, sizin gibi kullardır. Haydi onları çağırın da size cevap versinler, sözünüzde doğru iseniz!"},{"n":195,"t":"Üzerinde yürüyecekleri ayakları mı var? Tutmaları için elleri mi var? Görmeleri için gözleri mi var? İşitmeleri için kulakları mı var? De ki: \"Ortaklarınızı çağırın ve benim için plan kurun. Hiç durmayın!\""},{"n":196,"t":"\"Biricik Sahibim (Velim), kitabı indiren ALLAH’tır. O, dürüst insanları korur.\""},{"n":197,"t":"\"O’nun dışında çağırdıklarınız ne size yardım edebilirler, ne de kendilerine yardım edebilirler.\""},{"n":198,"t":"Onları hidayete çağırsan işitmezler. Onların sana baktığını görürsün; fakat onlar görmezler."},{"n":199,"t":"Affedici ol, toleransı öğütle ve cahillere aldırış etme."},{"n":200,"t":"Sapkından ne zaman kötü bir düşünce zihnini tırmalarsa, ALLAH’a sığın; O İşitendir, Bilendir."},{"n":201,"t":"Erdemlilere her ne zaman sapkından karanlık bir öneri ulaşsa hemen hatırlarlar. Böylece hemen görürler."},{"n":202,"t":"(Sapkınlar) kardeşlerini ise azgınlığa sürüklerler ve bundan hiç geri durmazlar."},{"n":203,"t":"Kendilerine bir mucize getirmediğin zaman: \"Mucize isteseydin ne olurdu\" derler. De ki: \"Ben, ancak Efendimden bana vahyedilene uyuyorum.\" Bunlar, Efendinizden aydınlatmalardır, gerçeği onaylayan bir toplum için bir hidayet ve rahmettir."},{"n":204,"t":"Kuran okunduğu zaman, onu dinleyip kulak verin ki merhamet edilesiniz."},{"n":205,"t":"Efendini gönülden yalvararak, gizlice ve sessizce sabah akşam an; gafillerden olma."},{"n":206,"t":"Efendinin yanındakiler, ona hizmet etmekten kaçınıp büyüklenmezler, O’nu yüceltirler ve O’na secde ederler."}]},{"id":8,"name":"Enfal Suresi","verses":[{"n":1,"t":"Savaş ganimetleri hakkında senden soruyorlar. De ki: \"Ganimetler, ALLAH’ın ve elçisinindir.\" ALLAH’ı dinleyin, aranızı düzeltin. Gerçeği onaylıyorsanız, ALLAH’a ve elçisine uyun."},{"n":2,"t":"Gerçeği onaylayanlar öyle kimselerdir ki, ALLAH anıldığında yürekleri titrer, O’nun ayetleri kendilerine okunduğunda onayları artar ve Rab’lerine güvenirler."},{"n":3,"t":"Onlar ki namazı gözetirler ve kendilerine verdiğimiz rızıklardan yardım olarak verirler."},{"n":4,"t":"Böyleleri gerçek gerçeği onaylayanlardır. Onlar için Rab’leri yanında dereceler, bağışlanma ve tükenmez rızık vardır."},{"n":5,"t":"Nitekim Efendin seni belli bir planın gerçekleşmesi için evinden çıkarmıştı. Gerçeği onaylayanlardan bir grup bundan hoşlanmamıştı."},{"n":6,"t":"Gerçek ortaya çıkmasına rağmen, göz göre göre ölüme sürükleniyorlarmış gibi seninle onu tartışıyorlardı."},{"n":7,"t":"ALLAH iki gruptan birisini size söz vermişti; siz ise, güçsüz olanıyla karşılaşmayı istiyordunuz. Oysa ALLAH kelimeleriyle gerçeği gerçekleştirmek ve kâfirlerin ardını kesmeyi diliyor."},{"n":8,"t":"Ki suçlular hoşlanmasa da hakkı gerçekleştirsin ve haksızlığı ortadan kaldırsın."},{"n":9,"t":"Sizi kurtarması için Efendinize yalvarıyordunuz ve O da, \"Ben sizi birbiri ardınca bin melek ile destekleyeceğim\" diye size karşılık vermişti."},{"n":10,"t":"ALLAH bunu, ancak bir müjde olsun ve kalpleriniz yatışsın diye yaptı. Zafer yalnız ALLAH’tandır. ALLAH Üstündür, Bilgedir."},{"n":11,"t":"Kendisinden bir güvenlik olarak sizi bir uyuklama bürüyüp yatıştırıyordu. Sizi temizlemek, sapkının pisliğini (umutsuzluğu) sizden savmak, kalbinizi ikna etmek ve ayaklarınızı pekiştirmek için üzerinize gökten su indiriyordu."},{"n":12,"t":"Efendin meleklere, \"Sizinle beraberim, gerçeği onaylayanları destekleyin. İnkârcıların yüreğine korku salacağım. Vurun boyunlara, vurun onların her parmağına\" diye vahyediyordu."},{"n":13,"t":"Çünkü onlar ALLAH’a ve elçisine karşı aktif olarak savaştılar. Kim ki ALLAH ve elçisiyle savaşırsa elbette ALLAH’ın cezası çetindir."},{"n":14,"t":"İşte bunu tadın. Kâfirler için bir de ateş azabı var."},{"n":15,"t":"Ey gerçeği onaylayanlar, size karşı düşmanca harekâta geçen kâfirlerle karşılaştığınızda, onlara arkanızı dönmeyin."},{"n":16,"t":"Kim o gün, savaş taktiği veya başka bir birliğe katılma amacının dışında sırtını dönüp kaçarsa ALLAH’tan bir gazaba uğramıştır ve yeri de cehennemdir. Ne kötü bir duraktır."},{"n":17,"t":"Onları siz öldürmediniz, fakat ALLAH öldürdü. Attığın zaman da sen atmıyordun; ALLAH atıyordu. Fakat böylece gerçeği onaylayanları güzel bir sınavla sınadı. ALLAH İşitendir, Bilendir."},{"n":18,"t":"İşte böyle; ALLAH kâfirlerin planını bozar."},{"n":19,"t":"Zafer istiyorduysanız, işte size zafer geldi! Saldırmaktan vazgeçerseniz sizin için daha iyi olur. Dönerseniz biz de döneriz ve ordunuz sayıca çok da olsa sizden hiçbir şeyi savamaz. ALLAH gerçeği onaylayanlarla beraberdir."},{"n":20,"t":"Ey gerçeği onaylayanlar, ALLAH’a ve elçisine uyunuz. İşittiğiniz halde ondan yüz çevirmeyiniz."},{"n":21,"t":"İşitmedikleri halde, \"İşittik\" diyenler gibi olmayın."},{"n":22,"t":"ALLAH yanında, yaratıkların en kötüsü, akıllarını kullanmayan sağır ve dilsizlerdir."},{"n":23,"t":"ALLAH onlarda bir iyilik olduğunu görseydi, onlara işittirirdi. Onlara işittirseydi bile yine yüz çevirerek dönerlerdi."},{"n":24,"t":"Ey gerçeği onaylayanlar, size hayat verecek şeylere çağırdığında ALLAH’a ve elçisine yanıt verin. Bilin ki ALLAH kişi ile kalbi arasına girer ve O’nun huzuruna toplanacaksınız."},{"n":25,"t":"Sizden sadece zalimlere çatmakla kalmayacak olan sınavdan sakının. Bilesiniz ki ALLAH’ın cezası çetindir."},{"n":26,"t":"Sayıca az olduğunuz, yeryüzünde ezilip horlandığınız ve insanların sizi kapıp kaçıracaklarından korktuğunuz zamanları hatırlayın. O size barınak sağladı, sizi yardımıyla destekledi ve güzel şeylerden size rızıklar verdi ki şükredesiniz."},{"n":27,"t":"Ey gerçeği onaylayanlar, ALLAH’a ve elçisine ihanet etmeyin; sorumluluklarınıza bile bile ihanet etmiş olursunuz."},{"n":28,"t":"Bilesiniz ki mallarınız ve evlatlarınız sizin için bir sınavdır ve ALLAH’ın yanında büyük ödül vardır."},{"n":29,"t":"Ey gerçeği onaylayanlar, ALLAH’ı dinlerseniz, size doğruyu yanlıştan ayıracak anlayışı verir, kötülüklerinizi örter ve sizi bağışlar. ALLAH Büyük Lütuf Sahibidir."},{"n":30,"t":"İnkârcılar seni etkisiz hale getirmek veya seni öldürmek ya da seni sürmek için planlar yapıyorlardı. Onlar plan kuruyorlarsa ALLAH da plan kuruyor. ALLAH plan kuranların en ustasıdır."},{"n":31,"t":"Ayetlerimizi dinledikleri zaman, \"İşittik\" diyorlardı, \"İstesek biz de bunun bir benzerini getiririz. Bu, geçmişlerin efsanelerinden başka bir şey değil.\""},{"n":32,"t":"Hatta, \"Efendimiz, bu senden gelen bir gerçek ise, üstümüze gökten taşlar yağdır veya başımıza acıklı bir azap getir\" diyorlardı."},{"n":33,"t":"Sen onların arasında bulunduğun sürece ALLAH onlara azap edecek değildir. Onlar, bağışlanma dilerlerken de ALLAH onları cezalandıracak değildir."},{"n":34,"t":"Başkalarını Sınırlanmış Mescit’ten menederlerken neden ALLAH’ın azabını hak etmesinler? Oysa onlar onun koruyucuları değiller. Onun gerçek koruyucuları gerçeği onaylayanlardır; ancak çokları bunu bilmez."},{"n":35,"t":"Onların, Ev’deki namazları hile ve menetmekten başka bir şey değil. İnkârınızdan dolayı azabı tadın."},{"n":36,"t":"İnkâr edenler, insanları ALLAH yolundan menetmek için paralarını harcarlar ve daha da harcamaya devam edecekler. Fakat bu, sonradan kendileri için bir üzüntü kaynağı olacak ve ardından yenilecekler. İnkâr edenler cehenneme sürüleceklerdir."},{"n":37,"t":"Böylece ALLAH kötüyü iyiden ayırt eder, kötüleri üst üste koyup topluca yığar ve cehenneme yollar. İşte kaybedenler onlardır."},{"n":38,"t":"İnkâr edenlere söyle: \"Son verirlerse geçmişte yaptıkları bağışlanacaktır. Dönerlerse, daha öncekilerin yasası (sünneti) geçerlidir.\""},{"n":39,"t":"Baskı ve zulmü ortadan kaldırıncaya ve dini sadece ALLAH’a ait kılıncaya dek onlarla savaşın. Düşmanlığa son verirlerse, elbette ALLAH yaptıklarınızı Görür."},{"n":40,"t":"Dönerlerse, bilin ki sahibiniz ALLAH’tır. O en iyi Egemen/ Dost/Koruyucu (Mevla) ve en iyi Yardımcıdır."},{"n":41,"t":"Ayrım gününde, iki ordunun karşılaştığı günde kulumuza indirdiğimize ve ALLAH’a Gerçeği onaylıyorsanız, bilin ki elinize geçen her ganimetin beşte biri ALLAH’ın ve elçisinindir. Bu pay, akrabalar, öksüzler, yoksullar ve yolda kalmışların hakkıdır. ALLAH her şeye Güç Yetirendir."},{"n":42,"t":"Hani siz vadinin beri yamacında, onlar da vadinin öte yamacında mevzilenmişti. Kervan da sizden daha aşağıda idi. Bu karşılaşmayı siz kararlaştırsaydınız karşılaşma konusunda anlaşmazlığa düşecektiniz. Oysa ALLAH, yapılması önceden planlanmış bir işi gerçekleştirmekte idi. Böylece, yok edilen, apaçık bir delille yok edilsin, yaşayan da apaçık bir delille yaşatılsın. ALLAH İşitendir, Bilendir."},{"n":43,"t":"ALLAH onları rüyanda sana az gösteriyordu. Onları sana çok gösterseydi, dağılacak ve o konuda çekişip duracaktınız. Fakat ALLAH (sizi) kurtardı. O, göğüslerin özünü bilendir."},{"n":44,"t":"Zamanı gelip kendileriyle karşılaştığınızda sizin gözlerinizde onları az gösteriyor, onların da gözlerinde sizi az gösteriyordu ki ALLAH önceden planlanmış işi gerçekleştirsin. İşler, sonunda ALLAH’a döner."},{"n":45,"t":"Ey gerçeği onaylayanlar bir ordu ile karşılaştığınızda dayanın ve ALLAH’ı çokça anın ki başarasınız."},{"n":46,"t":"ALLAH’a ve elçisine uyun, çekişmeyin, yoksa zayıflayıp gücünüzü yitirirsiniz. Güçlüklere karşı direnin. Elbette ALLAH sabredenlerle beraberdir."},{"n":47,"t":"ALLAH’ın yoluna engel olmak amacıyla, halka gösteriş yaparak yurtlarından çıkan o kendini beğenmişler gibi olmayın. ALLAH yaptıklarını çepeçevre Kuşatır."},{"n":48,"t":"Sapkın, işlerini onlara süslemiş ve: \"Bugün halktan kimse sizi yenemez, ben sizin yanınızdayım\" demişti. İki ordu yüz yüze gelince de, topukları üzerine geri dönüp, \"Sizinle bir ilgim yok, sizin görmediğinizi görüyorum ve ALLAH’tan korkarım. ALLAH’ın cezası çetindir\" demişti."},{"n":49,"t":"İkiyüzlüler ve kalplerinde hastalık bulunanlar, \"Bunları dinleri aldatmış\" diyorlardı. Kim ALLAH’a güvenirse, kuşkusuz ALLAH Üstündür, Bilgedir."},{"n":50,"t":"İnkâr edenlerin canlarını melekler alırken bir görseydin! Yüzlerine ve arkalarına (saldıran ve kaçan düşmanlarınıza) vuruyorlardı: \"Tadın yakıcı azabı!\""},{"n":51,"t":"\"Bu, ellerinizin yaptığına karşılıktır. ALLAH elbette kullara zalim değildir.\""},{"n":52,"t":"Tıpkı Firavunun yandaşlarının ve onlardan öncekilerin gidişi gibi… ALLAH’ın ayetlerini inkâr ettiler. Günahlarından ötürü ALLAH da onları yakalayıp cezalandırdı. ALLAH Güçlüdür, cezası çetindir."},{"n":53,"t":"Zira, bir topluluk kendilerini değiştirmedikçe, ALLAH onlara verdiği nimetleri değiştirecek değildir. ALLAH İşitendir, Bilendir."},{"n":54,"t":"Örneğin, Firavunun yandaşları ve onlardan öncekiler gibi. Rab’lerinin ayetlerini yalanladılar. Biz de günahlarından ötürü onları yıkıma uğrattık. Firavunun yandaşlarını suda boğduk. Hepsi de zalim idiler."},{"n":55,"t":"ALLAH yanında yaratıkların en kötüsü kâfirlerdir; onlar gerçeği onaylamazlar."},{"n":56,"t":"Onlar, sen kendileriyle anlaşma yaptığın halde her defasında anlaşmalarını bozanlardır. Onlar erdemli davranmazlar."},{"n":57,"t":"Savaşta onları yakalarsan, onları arkalarındakilere ibret olacak şekilde darmadağın et. Belki ders alırlar."},{"n":58,"t":"Bir topluluğun ihaneti seni endişelendiriyorsa, sen de aynı şekilde (diplomatik ilişkiyi kesip) at. Kuşkusuz ALLAH hainleri sevmez."},{"n":59,"t":"Kâfirler, kurtulduklarını sanmasınlar. Kaçamazlar."},{"n":60,"t":"Onlar için elinizden gelen kuvvet ve binekler veya sanal bağlantılar hazırlayıp seferber edin. Böylece onlarla ALLAH’ın düşmanlarını, düşmanlarınızı ve onlardan başka bilmediğiniz, ancak ALLAH’ın bildiği kimseleri caydırırsınız. ALLAH yolunda ne harcarsanız size tam olarak ödenir ve hiç haksızlığa uğratılmazsınız."},{"n":61,"t":"Onlar barışa eğilim gösterirlerse sen de ona eğilim göster ve ALLAH’a güven. O, İşitendir, Bilendir."},{"n":62,"t":"Seni aldatmak isterlerse, ALLAH sana yeter. O ki seni yardımıyla ve gerçeği onaylayanlarla destekledi."},{"n":63,"t":"Ve onların kalplerini uzlaştırdı. Sen, yeryüzünde bulunanların hepsini harcasaydın bile kalplerini uzlaştıramazdın. Ancak, onların kalplerini ALLAH uzlaştırdı. O, Üstündür, Bilgedir."},{"n":64,"t":"Ey peygamber, ALLAH sana ve seni izleyen gerçeği onaylayanlara yeter."},{"n":65,"t":"Ey peygamber, gerçeği onaylayanları savaşa özendir. Sizden dirençli yirmi kişi olsa, iki yüz kişiyi yenebilir. Sizden yüz kişi, kâfirlerden bin kişiyi yenebilir. Çünkü onlar, anlamayan bir topluluktur."},{"n":66,"t":"Ancak, ALLAH sizde zayıflık bulunduğunu bildiğinden şimdi sizden yükü hafifletti. Sizden dirençli yüz kişi olsa, iki yüz kişiyi yenebilir. Sizden bin kişi olsa, ALLAH’ın izniyle iki bin kişiyi yenebilir. ALLAH sabredip direnenlerle beraberdir."},{"n":67,"t":"Hiçbir peygambere, yeryüzünde savaşa katılmaksızın esirler edinmesi yakışmaz. Siz bu dünyanın geçici malını istiyorsunuz; ALLAH ise (sizin için) ahireti ister. ALLAH Üstündür, Bilgedir."},{"n":68,"t":"ALLAH’ın daha önce koyduğu bir yasa olmasaydı aldıklarınızdan ötürü size büyük bir azap dokunacaktı."},{"n":69,"t":"Artık ele geçirdiğiniz ganimetleri helal ve temiz olarak yiyebilirsiniz. ALLAH’ı dinleyin. ALLAH Bağışlayandır, Rahimdir."},{"n":70,"t":"Ey peygamber, elinizde bulunan esirlere de ki: \"ALLAH kalbinizde bir iyilik bilse, yitirdiklerinizden daha iyisini size verir ve sizi bağışlar. ALLAH Bağışlayandır, Rahimdir."},{"n":71,"t":"Yok, sana ihanet etmek istiyorlarsa, zaten daha önce ALLAH’a ihanet etmişlerdi. Bunun üzerine onları yenik düşürdü. ALLAH Bilendir, Bilgedir."},{"n":72,"t":"Gerçeği onaylayanlar, ALLAH yolunda göç edenler, mallarıyla ve canlarıyla cihat edenler ve onları barındırıp onlara yardım edenler birbirlerinin dostudur. Gerçeği onayladığı halde sizinle birlikte göç etmeyenler göç edinceye kadar onlardan sorumlu değilsiniz. Ancak onlar, din bağından ötürü sizden yardım isterlerse, aranızda anlaşma bulunan bir topluma karşı olmaması koşuluyla kendilerine yardım etmelisiniz. ALLAH yaptıklarınızı Görendir."},{"n":73,"t":"İnkâr edenler de birbirlerinin dostudur. Bu emirleri uygulamazsanız, yeryüzünde kaos ve büyük bir fesat olur."},{"n":74,"t":"Gerçeği onaylayanlar, ALLAH yolunda göç edip çaba gösterenler ve onları barındırıp yardım edenler, işte bunlar gerçek gerçeği onaylayanlardır. Onlar için bağışlanma ve bol rızık vardır."},{"n":75,"t":"Sonradan gerçeği onaylayanlar, göç edenler ve sizinle birlikte çaba gösterenler de sizdendir. ALLAH’ın Kitabı’na göre akrabalar birbirlerine önceliklidir. ALLAH her şeyi Bilendir."}]},{"id":9,"name":"Tevbe Suresi","verses":[{"n":1,"t":"Bu, ALLAH ve elçisinden, kendileriyle anlaşma yapmış bulunduğunuz putperestlere bir ültimatomdur:"},{"n":2,"t":"Yeryüzünde dört ay daha dolaşın, bilin ki siz ALLAH’ı aciz bırakamazsınız ve ALLAH inkârcıları rezil eder."},{"n":3,"t":"Bu, aynı zamanda, ALLAH ve elçisinden tüm halka, büyük konferans günü yayımlanmış bir bildiridir: ALLAH putperestlerden uzaktır, elçisi de… Tövbe ederseniz sizin için daha iyidir. Dönerseniz, bilin ki siz ALLAH’ı aciz bırakamazsınız. İnkârcılara acı bir azabı müjdele."},{"n":4,"t":"Ancak, kendileriyle yaptığınız anlaşmanın koşullarına eksiksiz uyan ve size karşı başkalarıyla iş birliğinde bulunmayan putperestlerin anlaşmasını tanıdığınız süreye kadar uygulayın. ALLAH erdemlileri sever."},{"n":5,"t":"Sınırlanmış aylar çıkınca, (hâlâ barışa yanaşmıyorlarsa) o putperestlerle karşılaştığınız yerde savaşın. Onları yakalayın, onları kuşatın ve her hareketlerini izleyin. Tövbe edip namaz kılar ve zekât verirlerse yollarını serbest bırakın. ALLAH Bağışlayandır, Rahimdir."},{"n":6,"t":"Putperestlerden biri sizden geçiş emniyeti dilerse ona koruma sağla ki ALLAH’ın sözünü işitsin; sonra onu kendisinin güvenlik bölgesine ulaştır. Çünkü onlar bilgisiz bir topluluktur."},{"n":7,"t":"Putperestlerin ALLAH ve elçisi yanında nasıl bir anlaşması olabilir ki? Sınırlanmış Mescitte sizinle anlaşma yapmış olanlar hariç. Onlar sizin haklarınızı gözettikleri sürece siz de onların haklarını gözetin. ALLAH erdemlileri sever."},{"n":8,"t":"Nasıl olabilir ki? Size üstün gelselerdi ne bir akrabalık ilişkisini gözetirlerdi, ne de bir anlaşmayı… Ağızlarıyla sizi pasifleştirecek hoş sözler söylerler, fakat kalpleri tersini ister. Çokları yoldan çıkmıştır."},{"n":9,"t":"ALLAH’ın ayetlerini az bir fiyata satıp onun yolundan saptılar. Yaptıkları ne kadar da kötüdür."},{"n":10,"t":"Gerçeği onaylamış birisi hakkında ne bir akrabalık bağı ne de bir anlaşma gözetmezler; saldırganlar ve haddi aşanlar onlardır."},{"n":11,"t":"Tövbe ederlerse, namaz kılar ve zekât verirlerse din kardeşleriniz olurlar. Bilenlere ayetleri böyle açıklarız."},{"n":12,"t":"Anlaşma yaptıktan sonra antlarını bozar ve dininize saldırırlarsa, o inkârcılığın önderleriyle savaşın; çünkü onların andı artık geçersizdir. Belki vazgeçerler."},{"n":13,"t":"Antlarını bozan, elçiyi sürmeye yeltenen ve sizinle (savaşı) ilk başlatan topluluğa karşı savaşmayacak mısınız? Yoksa onlardan korkuyor musunuz? Gerçeği onaylıyorsanız asıl çekinmeniz gereken Allah’tır."},{"n":14,"t":"Onlarla savaşın ki, ALLAH ellerinizle onları cezalandırıp rezil etsin, sizi zafere ulaştırsın ve gerçeği onaylayan toplumun göğsünü ferahlatsın,"},{"n":15,"t":"Yüreklerinin öfkesini gidersin. ALLAH dilediğinin tövbesini kabul eder. ALLAH Bilendir, Bilgedir."},{"n":16,"t":"ALLAH, içinizden kendisi uğrunda cihat edenleri, ALLAH’tan, elçisinden ve gerçeği onaylayanlardan başkasını yakın dost edinmeyenleri bilip ayırmadan bırakılacağınızı mı sandınız? ALLAH yaptıklarınızı Haber Alır."},{"n":17,"t":"Putperestler, kendi inkârlarına bizzat tanık oldukları halde, ALLAH’ın mescitlerini sıkça ziyaret etmemeli. İşleri boşa çıkmıştır. Onlar ateşte ebedîdirler."},{"n":18,"t":"ALLAH’ın mescitlerini, ancak ALLAH’a ve ahiret gününü onaylayanlar, namazı gözetenler, zekâtı verenler ve ALLAH’tan başkasından korkmayanlar sıkça ziyaret ederler. Onlar, doğru yolu bulanlardandır."},{"n":19,"t":"Konferansa katılanlara su verme ve Sınırlanmış Mescidi ziyarete hazır bulundurma işini, ALLAH’ı ve ahiret gününü onaylamakla, namazı gözetmek, zekât vermek ve ALLAH yolunda cihat etmekle bir mi tutuyorsunuz? ALLAH yanında onlar bir değildir. ALLAH zalim toplumu doğruya ulaştırmaz."},{"n":20,"t":"Gerçeği onaylayanlar, göç edenler, paralarıyla canlarıyla ALLAH yolunda çaba gösterenler için ALLAH yanında daha büyük bir derece vardır. Onlar kazananlardır."},{"n":21,"t":"Rab’leri onlara, kendisinden bir rahmet, bir onama ve içinde ebedî nimetlerin bulunduğu bahçeleri müjdeler."},{"n":22,"t":"Orada ebedî kalıcılar. Büyük ödül ALLAH katındadır."},{"n":23,"t":"Ey gerçeği onaylayanlar, inkârı gerçeği onaylamaya tercih ettikleri taktirde ana babalarınızı ve kardeşlerinizi dost edinmeyin. Kim onları dost edinirse onlar zalimlerdir."},{"n":24,"t":"De ki: \"Ana babalarınız, çocuklarınız, kardeşleriniz, eşleriniz, aileniz, kazandığınız paralar, bozuk gitmesinden korktuğunuz iş ve hoşlandığınız evler, ALLAH ve elçisinden ve O’nun yolunda çaba göstermekten daha sevgili ise, ALLAH emrini getirinceye kadar bekleyiniz.\" ALLAH yoldan çıkmış toplumları doğruya iletmez."},{"n":25,"t":"ALLAH birçok durumda size yardım etti. Huneyn günü sayısal çokluğunuz sizi böbürlendirmişti. Fakat sayınızın size hiçbir yararı da olmamıştı. Nitekim, tüm genişliğine rağmen yeryüzü size dar gelmiş ve sonunda dönüp kaçmıştınız."},{"n":26,"t":"Sonra ALLAH, elçisi ve gerçeği onaylayanların üzerine tarafından güven ve rahatlık indirdi, ek olarak, görmediğiniz ordular indirdi ve böylece kâfirleri cezalandırdı. Kâfirlerin cezası işte budur."},{"n":27,"t":"Nitekim ALLAH, sonunda dilediğinin tövbesini kabul eder. ALLAH Bağışlayandır, Rahimdir."},{"n":28,"t":"Ey gerçeği onaylayanlar, müşrikler pistir; bu yıldan sonra Sınırlanmış Mescide yaklaşmasınlar. Yoksulluğa düşmekten korkuyorsanız, (bilin ki) ALLAH dilerse sizi kendi lütfuyla zenginleştirecektir. ALLAH Bilendir, Bilgedir."},{"n":29,"t":"Kendilerine kitap verilenler arasından, ALLAH’ı ve ahiret gününü onaylamayan, ALLAH’ın ve elçisinin yasakladığını yasaklamayan ve gerçek dine uymayan kimselerle boyunlarını eğip elleriyle tazminat ödeyinceye kadar savaşın."},{"n":30,"t":"Yahudiler: \"Uzeyr ALLAH’ın oğludur\" dediler. Hıristiyanlar da, \"Mesih ALLAH’ın oğludur\" dediler. Bu, ağızlarından çıkan sözleridir. Önceden inkâr etmiş olanların sözlerini taklit ediyorlar. ALLAH onları mahkûm eder. Nasıl da çevriliyorlar?"},{"n":31,"t":"Din bilginlerini, din adamlarını ve Meryem oğlu Mesih’i ALLAH’ın dışında Efendiler edindiler. Oysa, yalnız tek Tanrı’ya hizmet etmekle emredilmişlerdi. O’ndan başka tanrı yoktur. O, eş koştukları kimselerden de çok Yücedir."},{"n":32,"t":"ALLAH’ın ışığını ağızlarıyla söndürmek isterler. Kâfirler istemese de ALLAH ışığını tamamlayacaktır."},{"n":33,"t":"O, elçisini hidayetle ve gerçek dinle gönderdi ki onu tüm dinlere üstün kılsın. Putperestler istemese de…"},{"n":34,"t":"Ey gerçeği onaylayanlar, din bilginlerinin ve din adamlarının çoğu halkın parasını hak etmeden yerler ve ALLAH’ın yolundan saptırırlar. Altın ve gümüşü yığıp ALLAH yolunda harcamayanlara acı bir azap müjdele."},{"n":35,"t":"Gün gelir o biriktirdikleri altınlar ve paralar cehennem ateşinde ısıtılarak onlarla alınları, yanları ve sırtları dağlanır: \"Kendiniz için biriktirdiğiniz işte budur. Biriktirdiğinizi tadın.\""},{"n":36,"t":"Gökleri ve yeri yarattığı gün ALLAH’ın kitabında ayların sayısı, ALLAH’a göre on ikidir. Bunlardan dördü ise sınırlanmıştır. İşte kusursuz din budur; o aylarda (savaşarak) kendinize zulmetmeyiniz. Ama putperestler sizinle toptan savaşırlarsa siz de onlarla toptan savaşın. Bilesiniz ki ALLAH erdemli davrananların yanındadır."},{"n":37,"t":"Sınırlanmış Ayların yerini değiştirmek inkârın ileri noktasıdır. İnkârcılar onunla saptırılırlar. ALLAH’ın sınırlanmış saydığı ayların sayısına denk düşürmek amacıyla onu bir yıl helal, bir yıl da sınırlanmış sayarlar. Böylece, ALLAH’ın sınırladığı ayları ihlal ederler. İşledikleri kötülükler, gözlerinde güzel görünüyor. ALLAH inkârcı topluluğu doğruya ulaştırmaz."},{"n":38,"t":"Ey gerçeği onaylayanlar, size ne oldu ki, \"ALLAH yolunda harekete geçin\" dendiği zaman yere çakılıp kaldınız? Ahiret yerine bu dünya hayatına mı razı oldunuz? Dünya hayatının nimetleri ahiret hayatına oranla pek azdır."},{"n":39,"t":"Harekete geçmezseniz sizi acıklı bir azapla cezalandırarak yerinize başka bir toplumu geçirir. Siz O’na asla zarar veremezsiniz. ALLAH her şeye Gücü Yetendir."},{"n":40,"t":"Siz ona yardım etmezseniz, ALLAH ona yardım etmişti. (Örneğin) kâfirler onu, ikinin ikincisi olarak çıkarmışlardı. Hani ikisi mağarada iken, arkadaşına, \"Üzülme, ALLAH bizimle beraberdir\" diyordu… ALLAH ona huzur ve güven indirdi; görmediğiniz ordularla destekleyerek inkârcıların sözünü alçalttı. Yüce olan, yalnızca ALLAH’ın sözüdür. ALLAH Üstündür, Bilgedir."},{"n":41,"t":"İster donanımsız ister donanımlı olarak savaşa çıkınız. Paralarınızla ve canlarınızla ALLAH yolunda cihat edin. Bu sizin için daha iyidir, bir bilseydiniz."},{"n":42,"t":"Yakın bir menfaat ve orta uzunlukta bir yolculuk olsaydı seni izleyeceklerdi; ancak zorluk onlara fazla geldi. ALLAH’a yemin edeceklerdir: \"Gücümüz yetseydi sizinle birlikte çıkacaktık!\" Böylece kendilerini mahvediyorlar. ALLAH onların yalancı olduklarını bilir."},{"n":43,"t":"ALLAH seni affetti: Doğrular ve yalancılar sana belli olmadan önce neden onlara izin verdin?"},{"n":44,"t":"ALLAH’a ve ahiret gününü onaylayanlar, paralarıyla ve canlarıyla çaba göstermekten (kaçmak için) senden izin istemezler. ALLAH erdemlileri hakkıyla Bilir."},{"n":45,"t":"Ancak ALLAH’a ve ahiret gününü onaylamayanlar senden izin ister. Kalpleri kuşku ile doludur. Onlar kuşkuları içinde bocalamaktadırlar."},{"n":46,"t":"Savaşa çıkmayı istemiş olsalardı, onun için bir hazırlık yaparlardı. Fakat ALLAH onların katkısını istemedi ve onları yüreksiz ve isteksiz yaptı. Kendilerine, \"Oturanlarla birlikte oturun!\" denildi."},{"n":47,"t":"Sizinle çıksalardı, size yalnız karışıklık katarlardı, aranıza fitne ve çekişme sokarlardı. İçinizde de onlara kulak verenler var. ALLAH zalimleri çok iyi Bilir."},{"n":48,"t":"Daha önce de kargaşalık çıkarmayı arzulamışlardı ve senin işlerini tersine çevirmişlerdi. Nihayet gerçek geldi ve ALLAH’ın yasası, onlara rağmen egemen oldu."},{"n":49,"t":"Onlardan bazıları, \"Bana izin ver, beni sıkıntıya sokma\" diyor. Onlar zaten bu tavırlarıyla sıkıntının içine düşmüşlerdir; kâfirleri cehennem kuşatmaktadır."},{"n":50,"t":"Sana bir iyilik dokunsa onları üzer, sana bir kötülük dokunsa, \"Biz önceden önlem almıştık\" derler ve sevinç içinde dönüp giderler."},{"n":51,"t":"De ki: \"ALLAH’ın bizim için yazdığından başkası bize dokunmaz. O’dur bizim Mevla’mız, sahibimiz. Gerçeği onaylayanlar, ALLAH’a güvensinler.\""},{"n":52,"t":"De ki: \"Biz sizin için, ALLAH’ın, ya kendi tarafından veya bizim elimizle sizi cezalandırmasını umarken siz bizim için ancak iki güzelden birini (gazilik veya şehitlik) umabilirsiniz. Umutla bekleyin, biz de umutla bekliyoruz.\""},{"n":53,"t":"De ki: \"Yoksullara ister gönüllü, ister gönülsüz yardım edin; sizden kabul edilmeyecektir. Çünkü siz yoldan çıkmış bir topluluksunuz.\""},{"n":54,"t":"Yardımlarının kabul edilmesine engel sadece şudur: ALLAH’ı ve elçisini inkâr ettiler, namaza ancak üşenerek yaklaşırlar ve yardımları da isteksiz yaparlar."},{"n":55,"t":"Onların paraları ve çocukları seni etkilemesin. ALLAH bunlarla, onları dünya hayatında cezalandırmayı ve canlarının inkârcı olarak çıkmasını istiyor."},{"n":56,"t":"Sizden olduklarına dair ALLAH’a yemin ederler; oysa sizden değiller, onlar anlaşmazlık çıkaran bir topluluktur."},{"n":57,"t":"Nitekim onlar, sığınacak bir yer, mağaralar yahut girilecek bir delik bulsalardı panik içinde oraya yönelirlerdi."},{"n":58,"t":"Onların bir kısmı, sadakaların dağıtımı konusunda seni eleştiriyor; kendilerine ondan verilince razı oluyorlar, ancak ondan kendilerine verilmeyince öfkeleniyorlar."},{"n":59,"t":"Onlar, ALLAH’ın ve elçisinin kendilerine verdikleri paya razı olmalı ve \"ALLAH bize yeter. ALLAH elçisi yoluyla kendi lütfundan bize verecektir. Biz sadece ALLAH’ı arzularız\" demeliydiler."},{"n":60,"t":"Sadakalar, ALLAH’tan bir yükümlülük olarak, yoksullara, düşkünlere, bu konuda çalışan görevlilere, sempatizanlara, kölelerin özgürlüğü için, borçlulara, ALLAH yoluna ve yolda kalmışlara verilmeli. ALLAH Bilendir, Bilgedir."},{"n":61,"t":"Onlardan kimi de, \"O (haber toplayan) bir kulaktır\" diyerek peygamberi incitiyorlar. De ki: \"O, sizin için bir hayır kulağıdır. O, ALLAH’ı onaylar ve gerçeği onaylayanlara güvenir. İçiniz-deki gerçeği onaylayanlar için de bir rahmettir. ALLAH’ın elçisini incitenler için acı bir azap vardır."},{"n":62,"t":"Sizi hoşnut etmek için ALLAH’a yemin edip dururlar. Gerçekten onaylıyorlarsa bilmelidirler ki ALLAH ve elçisi hoşnut edilmeye daha layıktır."},{"n":63,"t":"Bilmediler mi ki, kim ALLAH ve elçisine karşı gelirse, içinde ebedî kalacağı cehenneme mahkûm olur. Bu büyük bir aşağılanmadır."},{"n":64,"t":"İkiyüzlüler, kalplerindekini kendilerine haber verecek bir surenin inmesinden çekiniyorlar. De ki: \"Alay edin bakalım, ALLAH korktuğunuz şeyi açığa çıkaracak.\""},{"n":65,"t":"Kendilerine sorarsan, \"Biz sadece şakalaşıp oynuyorduk\" derler. De ki: \"Siz, ALLAH ile, ayetleriyle ve elçisiyle mi alay ediyorsunuz?\""},{"n":66,"t":"Özür dilemeyiniz. Siz onayladıktan sonra inkâr ettiniz. Sizden bir kısmını affetsek bile, suç işlemiş oldukları için bir kısmını cezalandıracağız."},{"n":67,"t":"İkiyüzlü erkekler ve ikiyüzlü kadınlar birbirlerindendir. Onlar, kötülüğü öğütlerler, iyilikten menederler. Elleri sıkıdır. Onlar ALLAH’ı unuttular, O da onları unuttu. İkiyüzlüler, iyice yoldan çıkmış olanlardır."},{"n":68,"t":"ALLAH, ikiyüzlü erkeklere, ikiyüzlü kadınlara ve kâfirlere ebedî kalacakları cehennem ateşini söz verir. O onlara yeter. ALLAH onları lanetlemiştir ve onlar için tükenmez bir azap vardır."},{"n":69,"t":"Tıpkı sizden öncekilere benziyorsunuz; sizden daha güçlüydüler, sizden daha çok mal ve çocuklara sahiptiler. Kendilerine düşen paydan hoşlandılar, sizden öncekilerin kendi paylarından hoşlanmaları gibi siz de kendi payınızdan hoşlandınız. Kendilerini kaptıranlar gibi siz de kaptırdınız. Onlar, işleri dünya ve ahirette boşa çıkmış kimselerdir. Onlar, kaybedenlerdir."},{"n":70,"t":"Nuh’un halkı, Ad, Semud, İbrahim’in halkı, Medyen sakinleri ve altüst olmuş ülkelerin (Sadom ve Gomore) halkları gibi kendilerinden öncekilerin haberleri onlara ulaşmadı mı? Elçileri kendilerine apaçık belgelerle gitmişlerdi. ALLAH onlara zulmediyor değildi, aksine onlar kendi kendilerine zulmediyorlardı."},{"n":71,"t":"Gerçeği onaylayan erkekler ve gerçeği onaylayan kadınlar birbirlerinin dostudur. İyiliği emrederler, kötülükten menederler, namazı gözetirler, zekâtı verirler, ALLAH’a ve elçisine uyarlar. İşte onlara ALLAH rahmet edecektir. ALLAH Üstündür, Bilgedir."},{"n":72,"t":"ALLAH, gerçeği onaylayan erkeklere ve gerçeği onaylayan kadınlara içinden ırmaklar akan ebedî kalacakları bahçeler ve Adn bahçelerinde güzel evler söz vermiştir. ALLAH’ın hoşnut olması ise hepsinden daha büyük bir şeydir. İşte en büyük kurtuluş budur."},{"n":73,"t":"Ey peygamber, kâfirler ve ikiyüzlülerle mücadele et ve onlara karşı güçlü ve sert ol. Varacakları yer cehennemdir. Ne kötü bir dönüş yeridir orası!"},{"n":74,"t":"İnkâr sözlerini konuşmalarına ve teslim olduktan sonra inkâr etmelerine rağmen, onları söylemediklerine dair ALLAH’a yemin ediyorlar. Aslında, ulaşamayacakları şey için çaba gösterdiler. ALLAH ve O’nun lütfuyla elçisi kendilerini zenginleştirdikten sonra öç almaya kalktılar! Tövbe ederlerse kendileri için iyi olur. Yüz çevirirlerse, ALLAH onları dünya ve ahirette acı bir azapla cezalandırır; yeryüzünde ne bir dostları ne de bir yardımcıları olur."},{"n":75,"t":"Hatta bazıları, \"Bize lütfundan verirse, paramızı yardım için harcayacağız ve dürüst insanlardan olacağız\" diye ALLAH’a söz verdiler."},{"n":76,"t":"Fakat, onlara kendi lütfundan verince, cimrileştiler ve yüz çevirerek döndüler."},{"n":77,"t":"ALLAH’a verdikleri sözden caydıkları ve yalan söyledikleri için kendisiyle karşılaşacakları güne kadar kalplerine ikiyüzlülük soktu."},{"n":78,"t":"Bilmezler mi ki, ALLAH onların hem gizlediklerini hem açıkladıklarını bilir ve ALLAH tüm gizlileri Bilendir?"},{"n":79,"t":"Gönüllü olarak yardımda bulunan gerçeği onaylayanların cömertliklerini eleştirenler ve aynı zamanda fazla veremeyen yoksulları aşağılayanlar yok mu, ALLAH onları aşağılar. Onlar için acıklı bir azap vardır."},{"n":80,"t":"İster onlar için bağışlanma dile, ister bağışlanma dileme. Onlar için yetmiş kere bağışlanma dilesen bile ALLAH onları bağışlamayacaktır. Çünkü onlar ALLAH ve elçisini yalanladılar. ALLAH yoldan iyice çıkmış toplumları doğruya iletmez."},{"n":81,"t":"Geride kalanlar, ALLAH elçisinin ardındaki yerlerini beğendiler, ALLAH yolunda paralarıyla, canlarıyla çaba göstermekten hoşlanmadılar ve: \"Bu sıcakta harekete geçmeyin\" dediler. \"Cehennem ateşi daha sıcaktır\" de. Bir anlasalardı!"},{"n":82,"t":"Kazandıklarına karşılık az gülüp çok ağlasınlar."},{"n":83,"t":"Sefere çıkma konusunda onlardan bir grubun senden izin isteyecekleri bir fırsatı ALLAH sana tekrar verse, \"Benimle birlikte ebediyen harekâta çıkmayacaksınız ve benimle birlikte hiçbir düşmanla savaşmayacaksınız. Çünkü siz, ilk başta oturmayı seçmiştiniz. Öyle ise, geri kalanlarla beraber oturun\" de."},{"n":84,"t":"Onlardan ölen birisini destekleme, mezarı başında da durma. Çünkü onlar ALLAH’a ve elçisine karşı geldiler ve yoldan çıkmışlar olarak öldüler."},{"n":85,"t":"Paraları ve çocukları seni etkilemesin. ALLAH bunlarla, onları dünyada cezalandırmayı ve canlarının inkârcılar olarak çıkmasını ister."},{"n":86,"t":"\"ALLAH’ı onaylayın, elçisiyle birlikte cihat edin\" diye bir sure indiği zaman, onların güçlü ve varlıklı olanları bile senden izin istediler ve \"Bizi bırak oturanlarla beraber olalım\" dediler."},{"n":87,"t":"Geride kalanlarla birlikte olmaya razı oldular. Sonunda kalpleri mühürlendi. Bundan ötürü anlayamazlar."},{"n":88,"t":"Fakat elçi ve beraberinde bulunanlar, paralarıyla ve canlarıyla cihat ettiler. Tüm iyilikleri onlar hak etmiştir. Kazananlar onlardır."},{"n":89,"t":"ALLAH onlara ebedî kalacakları ve içinden ırmaklar akan bahçeler söz vermiştir. Bu, en büyük başarıdır."},{"n":90,"t":"Araplardan özür uyduranlar, izin almak için sana geldiler. AL-LAH ve elçisini yalanlayanlar böylece oturdular. İnkârcılarına acı bir azap dokunacaktır."},{"n":91,"t":"ALLAH’a ve elçisine içten bağlı oldukları taktirde, zayıflara, hastalara ve yardım için verecek bir şeyi bulunmayanlara bir ayıplama yoktur. İyi davrananlar kınanamaz. ALLAH Bağışlayandır, Rahimdir."},{"n":92,"t":"Aynı şekilde, kendilerini bindirmen için sana geldiklerinde, \"Sizi bindirecek bir taşıt bulamıyorum\" dediğin ve mali yetersizliklerinden dolayı üzüntüden gözlerinden yaş akarak geri dönenler de kınanamaz."},{"n":93,"t":"Yalnız, zengin oldukları halde senden izin isteyenler kınanabilir. Geride kalanlarla birlikte olmayı istediler, ALLAH da kalplerini damgaladı. Bunun için bilmezler."},{"n":94,"t":"Kendilerine döndüğünüzde size özürler sayarlar. De ki: \"Boşuna özür saymayın; sizi artık onaylamayız, ALLAH durumunuzu bize bildirmiş bulunuyor. ALLAH ve elçisi sizin işlerinizi görecek ve sonra da gizliyi ve açığı Bilenin huzuruna döndürüleceksiniz. O yaptıklarınız her şeyi size bildirecektir."},{"n":95,"t":"Onlara döndüğünüzde, kendilerinden vazgeçesiniz diye ALLAH’a yemin ederler. Onlardan vazgeç. Onlar kirlidir. Kazandıklarına karşılık, yerleri cehennemdir."},{"n":96,"t":"Kendilerinden hoşnut olasınız diye yemin ediyorlar. Onlardan hoşnut olsanız bile ALLAH yoldan çıkmış toplumlardan hoşnut olmaz."},{"n":97,"t":"Araplar inkârcılıkta ve ikiyüzlülükte en aşırıdırlar. ALLAH’ın elçisine indirdiğini tanımamaya da en yakındırlar. ALLAH Bilendir, Bilgedir."},{"n":98,"t":"Bazı Araplar, yardımlarını bir kayıp ve angarya sayar ve sizin için felaketler gözetlerler. En kötü felaketler onlar içindir. ALLAH İşitendir, Bilendir."},{"n":99,"t":"Araplardan, ALLAH’a ve ahiret gününü onaylayanlar da vardır. Harcadıklarını ise ALLAH’a yaklaştıracak bir vesile ve elçiye destek sayarlar. Gerçekten o, onlar için bir yaklaşma vesilesidir. ALLAH onları rahmetine sokacaktır. ALLAH Bağışlayandır, Rahimdir."},{"n":100,"t":"Göç edenlerin (muhacir) ve yardımcıların (ensar) öncülerinden ve onları güzelce izleyenlerden ALLAH razı olmuştur, onlar da O’ndan razı olmuşlardır. Onlara, içlerinde ırmaklar akan ve ebedî kalacakları bahçeler hazırlamıştır. İşte büyük zafer budur."},{"n":101,"t":"Gerek çevrenizden ve gerekse şehir halkından olan Araplardan bazıları ikiyüzlüdür. İkiyüzlülükte küstahlaşmışlardır. Sen onları bilmezsin, biz onları biliyoruz. Onları iki kat azapla cezalandıracağız ve sonra da büyük bir azaba uğratılacaklardır."},{"n":102,"t":"Diğerleri ise günahlarını itiraf ettiler, iyi işlerle kötü işleri birbirine karıştırdılar. Umulur ki ALLAH kendilerini affetsin. ALLAH Bağışlayandır, Rahimdir."},{"n":103,"t":"Onları temizlemek ve yüceltmek için paralarından bir sadaka al ve onları özendir/destekle. Zira senin desteğin onları memnun eder. ALLAH İşitendir, Bilendir."},{"n":104,"t":"Bilmezler mi ki kullarından tövbeleri kabul eden, sadakaları alan ALLAH’tır ve ALLAH Tövbeleri Kabul Edendir, Rahimdir."},{"n":105,"t":"\"Çalışın; ALLAH, elçisi ve gerçeği onaylayanlar yaptığınızı görecektir. Gizliyi ve açığı Bilene döndürüleceksiniz ve O da yapmış olduklarınızı size bildirecektir\" de."},{"n":106,"t":"Bir başka grup da ALLAH’ın hükmünü bekliyor. Kendilerini ya cezalandırır veya tövbelerini kabul eder. ALLAH Bilendir, Bilgedir."},{"n":107,"t":"Zarar vermek, inkârcılığı uygulamak, gerçeği onaylayanların arasını açmak ve önceden ALLAH ve elçisiyle savaşmış olanlara bir gözetleme yeri hazırlamak için mescit kullananlar da var. \"Amacımız sadece iyiliktir\" diye yemin ederler. ALLAH onların yalancılığına tanıktır."},{"n":108,"t":"Böyle bir yerde ebediyen namaza durma. İlk günden itibaren erdemlilik üzere kurulan mescit, namaz kılman için çok daha uygundur. Orada temizlenmek isteyen insanlar vardır ve ALLAH temizlenenleri sever."},{"n":109,"t":"Yapısını ALLAH’ın onayı ve erdemlilik üzerine kuran mı, yoksa yapısını bir uçurumun kenarına kurup onunla birlikte cehennem ateşine yuvarlanan mı daha iyidir? ALLAH zulmeden bir toplumu doğruya ulaştırmaz."},{"n":110,"t":"Kurdukları yapı, yürekleri parçalanıncaya dek kalplerinde bir kuşku kaynağı olarak kalacaktır. ALLAH Bilendir, Bilgedir."},{"n":111,"t":"ALLAH gerçeği onaylayanların canlarını ve mallarını bahçe karşılığında satın almıştır. ALLAH yolunda savaşırlar, öldürürler ve öldürülürler. Bu, O’nun Tevrat’ta, İncil’de ve Kuran’da verdiği bir sözdür. Verdiği sözü, ALLAH’tan daha iyi kim yerine getirebilir? Öyleyse bu alışverişinizden dolayı sevinin. En büyük başarı budur."},{"n":112,"t":"Onlar: Tövbe eden, hizmet yapan, yücelterek öven, aktif, eğilen, secde eden, iyiliği savunan, kötülükten meneden ve ALLAH’ın yasalarını koruyan insanlardır. Gerçeği onaylayanları müjdele."},{"n":113,"t":"Akraba bile olsalar, ne peygamber, ne de gerçeği onaylayanlar, cehennem halkı oldukları kendilerine belli olduktan sonra ortak koşanlar için bağışlanma dileyemez."},{"n":114,"t":"İbrahim’in babası için bağışlanma dilemesinin biricik sebebi ona önceden söz vermiş olmasıydı. Ne zaman ki onun ALLAH düşmanı olduğu kendisine belli olunca ondan uzaklaştı. İbrahim, çok duygulu ve çok şefkatli idi."},{"n":115,"t":"ALLAH bir toplumu doğru yola ilettikten sonra, sakınacakları şeyleri bildirmeden, onları sapıklığa mahkûm edecek değildir. ALLAH her şeyi Bilendir."},{"n":116,"t":"Göklerin ve yerin egemenliği ALLAH’a aittir. Diriltir, öldürür. Sizin için ALLAH’tan başka ne bir sahip ne de bir yardımcı yoktur."},{"n":117,"t":"ALLAH, peygamberin, göç edenlerin ve yardım edenlerin tövbesini kabul etmiştir. Onlar, içlerinden bir bölümünün neredeyse kalplerinin kaydığı güç anda onu izlemişlerdi. Sonra onların yönelişini (tövbesini) kabul etti. O, onlara karşı çok Şefkatlidir, Rahimdir."},{"n":118,"t":"Geride kalan o üç kişinin de... Yeryüzü, tüm genişliğine rağmen onlara dar gelmişti. Bunalmışlardı. Sonunda, ALLAH’tan kaçamayacaklarını anladılar. Bunun üzerine, yönelmeleri için O, onlara yöneldi. ALLAH yönelişleri Onaylayandır, Rahimdir."},{"n":119,"t":"Ey gerçeği onaylayanlar, ALLAH’ı dinleyin ve doğrularla beraber olun."},{"n":120,"t":"Ne şehir halkı ne de onların çevresindeki Araplar ALLAH’ın elçisinden geri kalmamalı ve kendilerini ona tercih etmemelidir. Zira ALLAH yolunda uğrayacakları her bir susuzluk, bir yorgunluk ve bir açlık, kâfirleri öfkelendirecek her bir adım ve düşmana karşı kazandıkları her bir başarı, kendileri için iyi bir iş olarak yazılır. ALLAH iyi davrananların mükafatını yitirmez."},{"n":121,"t":"Büyük veya küçük, yaptıkları her yardım ve aştıkları her vadi onlar için iyi bir iş olarak yazılır. ALLAH yaptıklarının en güzeliyle kendilerini ödüllendirir."},{"n":122,"t":"Gerçeği onaylayanların, topluca yola çıkmaları doğru olmaz. Her gruptan sadece bir kaç kişi, dini anlayıp öğrenmek için harekete geçmeli. Nitekim böylece, halklarına geri döndüklerinde, halklarının uyanık bulunması için onları uyarabilsinler."},{"n":123,"t":"Ey gerçeği onaylayanlar, sizi kuşatıp saldıran kâfirlerle savaşın. Sizde sertlik bulsunlar. Bilin ki ALLAH erdemlilerle beraberdir."},{"n":124,"t":"Her ne zaman bir sure inse, \"Bu sure hanginizin gerçeği onaylamasını arttırdı\" diye soranlar var. Gerçeği onaylayanların onayını arttırdı ve onlar sevinip birbirlerini müjdelerler."},{"n":125,"t":"Kalplerinde hastalık bulunanlara gelince… Onların da kötülüklerini arttırmıştır ve onlar kâfirler olarak ölürler."},{"n":126,"t":"Her sene, bir iki defa belalarla sınandıklarını görmüyorlar mı? Buna rağmen ne tövbe ediyorlar, ne de öğüt alıyorlar."},{"n":127,"t":"Ne zaman bir sure inse, \"Kimse sizi görüyor mu?\" diye bakışırlar. Sonra da dönüp giderler. Anlamaz bir topluluk olduklarından ALLAH kalplerini çevirmiştir."}]},{"id":10,"name":"Yunus Suresi","verses":[{"n":1,"t":"A. L. R. Bunlar (bu harfler/rakamlar), hikmet sahibi Kitab’ın mucizeleridir."},{"n":2,"t":"Kendilerinden bir adama: \"İnsanları uyar ve gerçeği onaylayanlara Rab’leri katında önemli bir yere sahip olduklarını müjdele\" diye vahyetmemiz halka garip mi geliyor? İnkârcılar, \"Bu, apaçık bir büyücüdür\" dediler."},{"n":3,"t":"Gökleri ve yeri altı günde yaratan ve sonra tüm otoriteyi kuran Efendiniz (sahibiniz) ALLAH’tır. Her işi yönetir. İzni olmadan hiç kimse aracılık (şefaat) edemez. Efendiniz ALLAH budur, O’na hizmet edin. Öğüt almaz mısınız?"},{"n":4,"t":"Hepinizin dönüşü O’nadır. Bu, ALLAH’ın verdiği gerçek sözdür. O, yaratılışı başlatır ve sonra tekrarlar; böylece Gerçeği onaylayıp erdemli işler yapanları adaletle ödüllendirir. Kâfirlere ise, inkârlarından ötürü sıcak bir içecek ve acı bir azap vardır."},{"n":5,"t":"O, güneşi bir ışık kaynağı, ayı da bir ışık yaptı. Yılların sayısını ve hesabı bilmeniz için ona evreler düzenleyip belirledi. ALLAH bunları ancak bir gerçek için yaratmıştır. Bilen bir topluma ayetleri böyle açıklar."},{"n":6,"t":"Gecenin gündüzle yer değiştirmesinde ve ALLAH’ın göklerde ve yerde yarattığı şeylerde erdemli bir toplum için deliller ve ibretler vardır."},{"n":7,"t":"Bizimle karşılaşmayı ummayanlar, dünya hayatını sevip ona bağlananlar ve ayetlerimizden gafil olanlar…"},{"n":8,"t":"İşte onların yeri, kazandıklarından ötürü ateştir."},{"n":9,"t":"Gerçeği onaylayıp erdemli işler yapanlara gelince, Rab’leri gerçeği onaylamalarından dolayı onları doğruya iletir. Nimet bahçelerinde ayaklarının altından ırmaklar akar."},{"n":10,"t":"Oradaki duaları: \"Tanrımız, sen yücesin,\" oradaki selamlaşmaları: \"Selam\" ve dualarının sonu da: \"Evrenlerin Rabbi ALLAH’a övgüler olsun\" dur."},{"n":11,"t":"İnsanların iyiliği acele istemeleri gibi, ALLAH da onlara azabı acele verse idi, süreleri bitirilmiş olurdu. Bizimle karşılaşmayı ummayanları, azgınlıkları içinde şaşkın durumda bırakırız."},{"n":12,"t":"İnsana bir zarar dokundu mu, yanı üzerine yatarken veya ayaktayken veya oturmuşken bizi çağırır. Ona zarar veren şeyi kendisinden giderdik mi, sanki kendisine dokunan o zarardan dolayı bizi hiç çağırmamış gibi davranır. Sınırı aşanlara, yaptıkları işler işte böyle süslü gösterilir."},{"n":13,"t":"Sizden önceki nice nesilleri, zulmettikleri zaman yok etmişizdir. Elçileri kendilerine açık delillerle gitmişlerdi, ancak onlar onaylamayı reddetmişlerdi. Suçlu toplumları böyle cezalandırırız."},{"n":14,"t":"Sonra, ne yapacağınızı görmek için onların yerine sizi yeryüzüne vâris kıldık."},{"n":15,"t":"Onlara apaçık olan ayetlerimiz okunduğu zaman, bize kavuşmayı ummayanlar, \"Bundan başka bir Kuran getir, yahut onu değiştir!\" derler. De ki: \"Onu kendi tarafımdan değiştiremem. Ben yalnız bana vahyedilene uyarım. Efendime karşı gelirsem, büyük günün azabından korkarım.\""},{"n":16,"t":"De ki: \"ALLAH dileseydi onu size okuyamazdım ve sizin de ondan haberiniz olmazdı. Bundan önce bir ömür boyu aranızda yaşadım. Anlamaz mısınız?\""},{"n":17,"t":"ALLAH’a yalan uydurup iftira eden veya mucize ve ayetlerini yalanlayandan daha zalim kim olabilir? Suçlular başaramaz."},{"n":18,"t":"ALLAH’ı bırakıp, kendilerine ne zarar ne de yarar veremeyenlere hizmet ediyorlar ve \"Bunlar, ALLAH yanında bize şefaat edecekler\" diyorlar. De ki: \"ALLAH’ın göklerde ve yerde bilmediği şeyleri mi O’na bildiriyorsunuz? O çok yücedir, ortak koştuklarınızdan uzaktır.\""},{"n":19,"t":"İnsanlar bir tek toplumdu; sonra anlaşmazlığa düştüler. Efendinin vermiş olduğu bir sözü olmasaydı, anlaşmazlığa düştükleri konuda hemen aralarında hüküm verilecekti."},{"n":20,"t":"\"O’na Efendisinden bir mucize indirilmeli değil mi\" diyorlar. De ki: \"Gizemler ALLAH’ın yanındadır; öyleyse bekleyin, ben de sizinle birlikte beklemekteyim.\""},{"n":21,"t":"Kendilerine dokunan bir sıkıntıdan sonra insanlara bir rahmet tattırdığımız zaman, ayet ve mucizelerimize karşı hemen bir plan düzenlerler. De ki: \"Plan yapmada ALLAH daha hızlıdır. Elçilerimiz, düzenlediğiniz tüm planları kaydetmektedir.\""},{"n":22,"t":"Sizi karada ve denizde yürüten O’dur. Gemidesiniz… Bir meltemle yolcuları alıp götürdüğü zaman gemiden memnundurlar. Aniden şiddetli bir fırtınaya yakalanırlar. Her yönden gelen dalgaların arasında tümüyle kuşatıldıklarını sandıkları an, dini sadece ALLAH’a ait kılarak, \"Bizi bundan kurtarırsan şükredenlerden olacağız\" diye yalvarırlar."},{"n":23,"t":"Onları kurtarınca da yeryüzünde haksız yere taşkınlık yapmaya başlarlar. Ey insanlar, taşkınlığınız kendinize karşıdır. Dünya hayatının geçici zevkine düşkünsünüz; hâlbuki dönüşünüz bizedir ve yapmış olduğunuz her şeyi size haber veririz."},{"n":24,"t":"Dünya hayatı, tıpkı şu örnek gibidir; gökten indirdiğimiz su insanların ve hayvanların yediği bitkilerin yapısına karışır. Bu durum, yeryüzünün süslenip bezendiği ve halkının da artık doğaya egemen olduklarını sandıkları ana kadar sürer. Nihayet geceleyin veya gündüzün ona emrimiz gelir. Sanki bir önceki gün hiçbir şeye sahip değilmiş gibi onu kökünden biçilmiş bir duruma sokarız. Düşünen bir toplum için ayetleri böyle açıklarız."},{"n":25,"t":"ALLAH barış yurduna çağırır ve dilediğini doğru bir yola iletir."},{"n":26,"t":"Güzel davrananlara daha fazlası vardır. Yüzlerini ne bir yoksunluk ne de bir aşağılanma duygusu kaplar. Onlar bahçe halkıdır. Orada ebedî kalıcıdırlar."},{"n":27,"t":"Kötülük ve günah kazananlara ise kötülüğünün aynısıyla karşılık verilir. Yüzlerini bir aşağılanma duygusu kaplar. ALLAH’tan başka bir koruyucuları yoktur. Yüzleri sanki karanlık geceden bir parçayla bürünmüştür. Onlar ateş halkıdır; onlar orada ebedî kalacaklardır."},{"n":28,"t":"Onları bir araya topladığımız gün, ortak koşanlara; \"Siz ve ortaklarınız haydi yerinize!\" diyerek birbirlerinden ayırırız. Ortakları ise: \"Siz bize hizmet etmiyordunuz\" derler."},{"n":29,"t":"\"Bizimle sizin aranızda ALLAH tanıktır ki, biz sizin hizmet etmenizden habersizdik.\""},{"n":30,"t":"İşte orada her can, geçmişte yapmış olduğunu bulur. Gerçek Mevla’ları olan ALLAH’a döndürülürler. Uydurdukları ise kendilerinden uzaklaşıp kaybolur."},{"n":31,"t":"De ki: \"Size gökten ve yerden kim rızık veriyor? İşitme ve görme duyularınızı kim kontrol ediyor? Ölüden diriyi, diriden ölüyü kim çıkarıyor? Tüm işleri kim yönetiyor?\" \"ALLAH\" diyecekler. De ki: \"Öyleyse neden erdemli davranmıyorsunuz?\""},{"n":32,"t":"İşte Gerçek Efendiniz ALLAH budur. Öyleyse gerçeği terk ettikten sonra sapıklıktan başka ne kalır? Nasıl da çevriliyorsunuz?"},{"n":33,"t":"Yoldan çıkmış olanların onaylamayacağına dair Efendinin sözü işte böyle gerçekleşir."},{"n":34,"t":"De ki: \"Ortaklarınızdan hangisi yaratmayı başlatıp tekrarlayabilir?\" De ki: \"ALLAH yaratmayı başlatır ve onu tekrarlar. Nasıl da çevriliyorsunuz?\""},{"n":35,"t":"De ki \"Ortaklarınızdan hangisi gerçeğe ulaştırabilir?\" De ki: \"ALLAH gerçeğe ulaştırır. Gerçeğe ulaştıran mı uyulmaya daha yaraşır, yoksa gerçeğe ulaştırılmadıkça gerçeği bulamayan mı? Ne biçim hüküm veriyorsunuz?\""},{"n":36,"t":"Onların çoğu, ancak zanna uyarlar. Zan ise gerçeğin yerini tutamaz. ALLAH onların yaptıklarını Bilendir."},{"n":37,"t":"Bu Kuran, ALLAH’tan başkası tarafından düzenlenen bir kitap değildir. Ancak kendisinden öncekileri onaylayan ve yasaların (kitap) detaylı bir açıklamasıdır. Bunda kuşkunuz olmasın; evrenlerin Efendisindendir."},{"n":38,"t":"\"Onu uydurdu\" mu diyorlar? De ki: \"Doğru sözlüler iseniz, buna benzer bir sure getirin ve ALLAH’tan başka çağırabildiklerinizi çağırın.\""},{"n":39,"t":"Hayır, onlar bilgisini kavramadan ve asıl anlamına ulaşmadan onu yalanladılar. Kendilerinden öncekiler de böyle yalanladı. Zalimlerin sonuna dikkatle bak."},{"n":40,"t":"Onlardan kimi bunu onaylar, kimi de onaylamaz. Efendin bozgunculuk yapanları daha iyi bilir."},{"n":41,"t":"Seni yalanlarlarsa de ki: \"Benim yaptığım bana, sizin yaptığınız ise size! Siz benim yaptığımdan sorumlu değilsiniz, ben de sizin yaptığınızdan sorumlu değilim.\""},{"n":42,"t":"Onlardan seni dinleyenler de var; akıllarını kullanmayan sağırlara sen mi işittireceksin?"},{"n":43,"t":"Onlardan sana bakanlar da var; görüşü olmayan körleri sen mi doğruya ileteceksin?"},{"n":44,"t":"ALLAH insanlara hiç zulmetmez; ancak insanlar kendi kendilerine zulmederler."},{"n":45,"t":"Onları topladığımız gün, sanki gündüzden bir an kadar kalmışlar gibi birbirlerini tanırlar. ALLAH ile karşılaşmayı yalanlayanlar kaybedenlerdir. Doğruyu da bulmamışlardır."},{"n":46,"t":"Onlara söz verdiklerimizin bir kısmını sana göstersek de veya canını alsak da, onların son dönüş yeri bizedir. Sonra ALLAH onların yaptıkları her şeye de tanıktır."},{"n":47,"t":"Her bir toplum için bir elçi vardır. Elçileri geldiği zaman adaletle yargılanırlar ve hiç zulmedilmezler."},{"n":48,"t":"\"Bu söz ne zaman gerçekleşecek?\" diyorlar."},{"n":49,"t":"De ki: \"ALLAH’ın dilemesi dışında, ben kendime dahi ne bir zarar ne de bir yarar verme gücüne sahip değilim. Her toplumun bir süresi vardır. Süreleri bitince ne bir an geciktirilir ne de öne alınırlar."},{"n":50,"t":"De ki: \"O’nun azabı ister gece veya gündüz gelsin, ama neden suçlular o konuda acele içindedirler?\""},{"n":51,"t":"\"Gerçekleştikten sonra mı onu onaylayacaksınız? Öyleyse neden onu şimdi çabuk isteyip duruyorsunuz?\""},{"n":52,"t":"Sonra zulmedenlere: \"Ebedî azabı tadın\" denir, \"Kazandığınızdan başka bir karşılık mı bekliyordunuz?\""},{"n":53,"t":"\"Bu sahiden doğru mudur?\" diye senden haber bekliyorlar. De ki: \"Elbette, Efendime andolsun o gerçektir ve siz onu engelleyemezsiniz!\""},{"n":54,"t":"Zulmetmiş bir can yeryüzündeki her şeye sahip olsa, onu fidye olarak vermek isteyecektir. Azabı gördüklerinde derin pişmanlık duyacaklar. Adaletle yargılanacaklar ve onlara zulmedilmeyecektir."},{"n":55,"t":"Göklerde ve yerde olanlar elbette ALLAH’ındır. ALLAH’ın sözü tamamıyla gerçektir; fakat onların çoğu bilmez."},{"n":56,"t":"O diriltir ve öldürür. O’na döndürüleceksiniz."},{"n":57,"t":"Ey halk, Efendinizden size bir öğüt, gönülleri sıkan her şeye karşı bir şifa, gerçeği onaylayanlara bir yol gösterici ve bir rahmet gelmiş bulunuyor."},{"n":58,"t":"De ki: \"Sadece, ALLAH’ın lütfu ve rahmetiyle sevinsinler. Bu, topladıkları her şeyden daha hayırlıdır.\""},{"n":59,"t":"De ki: \"ALLAH’ın size indirdiği rızıkların bir kısmını helal, bir kısmını da haram ettiğinizi görmez misiniz?\" De ki: \"ALLAH mı size izin verdi, yoksa ALLAH’a iftira mı ediyorsunuz?\""},{"n":60,"t":"ALLAH adına yalan uyduranlar diriliş gününü düşünmezler mi? ALLAH insanlara karşı bol lütuf sahibidir; ancak onların çoğu şükretmez."},{"n":61,"t":"Ne durumda bulunursanız bulunun, Kuran’dan ne okursanız okuyun, hangi işi yaparsanız yapın, siz onlarla uğraşırken biz mutlaka size tanık oluruz. Göklerde ve yerde bulunan bir atom ağırlığı bile Efendinin kontrolünün dışına çıkamaz. Atomdan da küçük olsun büyük olsun, her şey apaçık bir kitapta kayıtlıdır."},{"n":62,"t":"ALLAH’ın dostları için ne bir korku vardır, ne de üzülürler."},{"n":63,"t":"Onlar ki, gerçeği onayladılar ve erdemli davrandılar."},{"n":64,"t":"Dünya hayatında da ahirette de mutluluk onlarındır. ALLAH’ın verdiği sözler (kelimat) değişmez. İşte bu, en büyük zaferdir."},{"n":65,"t":"Sözleri seni üzmesin. Üstünlük tümüyle ALLAH’a aittir. O İşitendir, Bilendir."},{"n":66,"t":"Göklerde ve yerde ne varsa ALLAH’ındır. ALLAH’tan başkalarına yalvaranlar aslında koştukları ortakları izlememektedirler. Onlar sadece tahmin yürütüyorlar ve sadece saçmalıyorlar."},{"n":67,"t":"O ki geceyi sizin dinlenmeniz için elverişli, gündüzü de aydınlık kıldı. Dinleyen bir topluluk için bunda deliller vardır."},{"n":68,"t":"\"ALLAH çocuk edindi!\" dediler. O bundan çok yücedir. O, hiçbir şeye ihtiyacı olmayandır. Göklerde ve yerde ne varsa O’nundur. Sizin bu konuda hiçbir kanıtınız yoktur. ALLAH hakkında bilmediğiniz bir şeyi mi söylüyorsunuz?"},{"n":69,"t":"De ki: \"ALLAH hakkında yalan uyduranlar başarıya ulaşamazlar.\""},{"n":70,"t":"Dünyada paylarını alırlar, sonra dönüşleri bizedir. Sonra da inkârlarından ötürü onlara şiddetli azabı tattırırız."},{"n":71,"t":"Onlara Nuh’un tarihini anlat. Halkına şunları demişti: \"Ey halkım, durumum ve ALLAH’ın ayetlerini hatırlatmam size ağır geldiyse, ben ALLAH’a güveniyorum. Ortaklarınız ve liderlerinizle birlikte toplanın, pişman olmayacağınız son kararınızı alın ve bekletmeden bana karşı uygulayın.\""},{"n":72,"t":"\"Yüz çevirirseniz, hâlbuki ben sizden herhangi bir ücret istememiştim. Benim ücretim ancak ALLAH’ın üzerinedir. Müslümanlardan olmakla emredildim.\""},{"n":73,"t":"Onu yalanladılar. Bunun üzerine onu ve gemide onunla beraber olanları kurtardık. Onları yöneticiler yaptık. Ayetlerimizi yalanlayanları ise boğduk. Uyarılanların akıbetine dikkat et."},{"n":74,"t":"Sonra onun ardından, elçiler gönderdik, halklarına apaçık deliller getirdiler. Geçmişte yalanlamış bulundukları gerçekleri onaylayacak değillerdi. Azgınların kalplerini böyle damgalarız."},{"n":75,"t":"Sonra onların ardından Musa ve Harun’u Firavuna ve konseyine mucizelerimizle gönderdik. Fakat büyüklük tasladılar ve suçlu bir topluluk oldular."},{"n":76,"t":"Tarafımızdan kendilerine gerçek gelince, \"Bu apaçık bir büyüdür\" dediler."},{"n":77,"t":"Musa, \"Size gelen gerçeği böyle mi nitelendiriyorsunuz? Bu bir büyü müdür? Oysa büyücüler başarıya ulaşamaz.\""},{"n":78,"t":"Dediler: \"Sen, yeryüzünde büyüklük ikinize kalsın diye, atalarımızı üzerinde bulduğumuz şeyden bizi çevirmek için mi bize geldin? Biz sizi asla onaylamayız!\""},{"n":79,"t":"Firavun, \"Tüm uzman büyücüleri bana getirin!\" dedi."},{"n":80,"t":"Büyücüler gelince, Musa onlara, \"Ne atacaksanız atın!\" dedi."},{"n":81,"t":"Onlar atınca, Musa: \"Sizin bu getirdiğiniz bir büyüdür. ALLAH elbette onu boşa çıkaracaktır. ALLAH bozguncuların işlerini düzeltmez\" dedi."},{"n":82,"t":"ALLAH sözleriyle hakkı gerçekleştirir. Suçlular hoşlanmasa da…"},{"n":83,"t":"Firavun ve erkanının işkence ve baskısından korktukları için Musa’yı, halkından ancak bir kaç kişi onayladı. Firavun, yeryüzünde haddi çok aşan bir zorba idi."},{"n":84,"t":"Musa: \"Ey halkım, eğer gerçekten ALLAH’ı onaylamış ve O’na teslim olmuş iseniz O’na güvenin.\""},{"n":85,"t":"Dediler ki: \"ALLAH’a güvendik. Efendimiz, bizi zalim halkın baskısına maruz bırakma.\""},{"n":86,"t":"\"Rahmetinle bizi inkârcı halktan kurtar.\""},{"n":87,"t":"Musa’ya ve kardeşine: \"Halkınız için Mısır’da evler hazırlayın. Evlerinizi odak noktası yapın ve namazı gözetin. Gerçeği onaylayanları müjdeleyin\" diye vahyettik."},{"n":88,"t":"Musa dedi ki: \"Efendimiz, sen Firavun ve konseyine dünya hayatında lüks ve mal verdin. Efendimiz, senin yolundan saptırsınlar diye mi? Efendimiz, onların mallarını silip süpür ve acı azabı görünceye kadar gerçeği onaylamasınlar diye kalplerini katılaştır.\""},{"n":89,"t":"Dedi ki: \"İkinizin duası kabul edilmiştir. Doğru olun ve bilmeyenlerin yolunu izlemeyin.\""},{"n":90,"t":"İsrailoğullarını denizden geçirdik. Firavun ve ordusu ise küstahça ve düşmanca arkalarına düştü. Boğulmak üzereyken, \"İsrailoğullarının onayladığından başka tanrı olmadığını onayladım, ben Müslümanım\" dedi."},{"n":91,"t":"\"Çok geç! Daha önce başkaldırmış ve bozgunculardan olmuştun.\""},{"n":92,"t":"\"Senden sonraki kuşaklara ibret olman için bugün senin cesedini koruyacağız. Ne var ki insanların çoğunluğu işaretlerimizden habersizdirler.\""},{"n":93,"t":"İsrailoğullarına onurlu bir yer bağışladık ve onlara güzel rızıklar verdik. Fakat, kendilerine ilim geldikten sonra ayrılığa düştüler. Efendin, diriliş günü, ayrılığa düştükleri konuda aralarında hüküm verecektir."},{"n":94,"t":"Sana indirdiğimiz hakkında bir kuşkun varsa, kitabı önceden okumuş olanlara sor. Sana Efendinden gerçek gelmiş bulunuyor. Şüphecilerden olma."},{"n":95,"t":"Sakın, ALLAH’ın ayetlerini yalanlayanlardan olma. Yoksa kaybedenlerden olursun."},{"n":96,"t":"Efendinin kararıyla mahkûm edilenler gerçeği onaylamazlar."},{"n":97,"t":"Acı azabı görünceye kadar onlara her çeşit mucize gelse bile..."},{"n":98,"t":"Gerçeği onaylaması kendine yarar vermeyen bir toplum olsaydı bile Yunus halkı onun istisnası olurdu. Gerçeği onayladıkları zaman, bu dünya hayatındaki aşağılayıcı azabı kendilerinden kaldırdık. Bir süreye kadar onları nimetlerle yaşattık."},{"n":99,"t":"Efendin dileseydi, yeryüzündekilerin hepsi gerçeği onaylardı. Öyleyse, sen mi halkı onaylamaları için zorlayacaksın?"},{"n":100,"t":"Hiçbir kişi ALLAH’ın izni olmadan gerçeği onaylayamaz ve O, akıllarını kullanmayanları rezilliğe mahkûm eder."},{"n":101,"t":"De ki: \"Göklerde ve yerde neler var, bir bakın! Gerçeği onaylamayan bir topluma deliller ve uyarılar kâr etmez.\""},{"n":102,"t":"Kendilerinden öncekilerin yaşadığı günlerin bir benzerini mi bekliyorlar? De ki: \"Bekleyin, ben de sizinle birlikte beklemekteyim.\""},{"n":103,"t":"Sonunda elçilerimizi ve gerçeği onaylayanları kurtarırız. Evet, gerçeği onaylayanları kurtarmak bizim değişmez bir yasamızdır."},{"n":104,"t":"De ki: \"Ey halk, dinimden bir kuşku duyuyorsanız, bilesiniz ki, sizin ALLAH’tan başka hizmet ettiğiniz kimselere hizmet etmem. Ben yalnızca, sizin canınızı alan ALLAH’a hizmet ederim. Gerçeği onaylayanlardan olmakla emredildim.\""},{"n":105,"t":"Ve: \"Tektanrıcı olarak dine yönel; ortak koşanlardan olma.\""},{"n":106,"t":"\"ALLAH’ı bırakıp, sana yarar ve zarar veremeyenleri çağırma. Böyle yaparsan o zaman zalimlerden olursun.\""},{"n":107,"t":"ALLAH sana bir zarar dokundurursa O’ndan başka onu ortadan kaldıracak yoktur. Senin için bir iyilik dilerse de, O’nun lütfunu geri çevirecek yoktur. Kullarından dilediğine bunu verir. O, Bağışlayandır, Rahimdir."},{"n":108,"t":"De ki: \"Ey halk, Efendinizden size gerçek gelmiş bulunuyor. Kim yola gelirse kendisi için yola gelmiş olur, kim de saparsa kendi zararına sapar. Ben sizden sorumlu değilim.\""},{"n":109,"t":"Sana vahyedileni izle; ALLAH hüküm verinceye kadar sabret. O, hüküm verenlerin en iyisidir."}]},{"id":11,"name":"Hud Suresi","verses":[{"n":1,"t":"A. L. R. Öyle bir kitaptır ki, Bilge ve her şeyden Haberdar biri tarafından ayetleri sağlamlaştırılmış ve sonra da açıklanıp detaylanmıştır."},{"n":2,"t":"Ki ALLAH’tan başkasına hizmet etmeyesiniz. Kuşkusuz ben, O’ndan size bir uyarıcı ve bir müjdeciyim."},{"n":3,"t":"Efendinizin bağışlamasını dileyip O’na tövbe etmelisiniz. O zaman, sizi belli bir süreye kadar güzelce geçindirir ve lütfu hakkeden herkese lütfundan verir. Dönerseniz, sizin için büyük günün azabından korkarım."},{"n":4,"t":"Dönüşünüz ALLAH’adır. O her şeye Gücü Yetendir."},{"n":5,"t":"Onlar, göğüslerindekini bilinç altına itip O’ndan gizlemek isterler. İyi bilin ki elbiselerini büründükleri zaman dahi onların gizlediklerini ve açıkladıklarını bilir. O, gizli düşünceleri bilendir."},{"n":6,"t":"Yeryüzünde hiçbir yaratık yoktur ki rızkı ALLAH tarafından garanti edilmesin. Onların konaklarını ve uğrak yerlerini bilir. Tüm bunlar apaçık bir kitaptadır."},{"n":7,"t":"O, hanginizin daha iyi iş yaptığını test etmek için gökleri ve yeri altı günde yaratandır. Egemenliği suyun üzerinde idi. Buna rağmen, kâfirlere, \"Siz ölümden sonra diriltileceksiniz\" desen, kâfirler, \"Bu, ancak açık bir büyüdür (kandırıcı bir sözdür)\" diyeceklerdir."},{"n":8,"t":"Onlardan azabı belli bir süre için ertelesek, \"Onu tutan nedir?\" derler. Doğrusu, onlara geldiği gün, kendilerinden geri çevrilemez ve alay ettikleri şey kendilerini kuşatacaktır."},{"n":9,"t":"İnsana kendimizden bir rahmet tattırsak ve sonra ondan çekip alsak, umutsuzlaşır, nankörleşir."},{"n":10,"t":"Kendisine dokunan zararlardan sonra ona nimetler tattırsak, \"Kötülükler benden gitti\" der. Bu kez sevinçlidir, kibirlidir."},{"n":11,"t":"Sabredenler ve erdemli işler yapanlar için ise bir bağışlanma ve büyük bir ödül vardır."},{"n":12,"t":"\"Ona bir hazine, yahut onunla birlikte bir melek inmeli değil miydi?\" dedikleri için neredeyse göğsün daralacak ve sana vahyedilenin bir kısmını terk edeceksin. Sen yalnız bir uyarıcısın; ALLAH her şeyi kontrol edendir."},{"n":13,"t":"\"Onu o uydurdu\" mu diyorlar? De ki: \"Haydi ona benzer, uydurulmuş on sure getirin. ALLAH’tan başka tüm dostlarınızı da çağırın, doğru sözlülerseniz!\""},{"n":14,"t":"Size cevap veremedilerse bilesiniz ki o ALLAH’ın bilgisiyle indirilmiştir ve O’ndan başka tanrı yoktur. Artık Müslüman olacak mısınız?"},{"n":15,"t":"Kim dünya hayatını ve lüksünü ararsa, yaptıklarının karşılığını orada tam öderiz ve onlar orada hiçbir eksikliğe uğratılmazlar."},{"n":16,"t":"Bunlar için ahirette, yalnız ateş vardır. Yaptıklarının hepsi orada boş çıkmıştır. Bütün yaptıkları geçersizdir."},{"n":17,"t":"Daha önce Musa’nın kitabı bir önder ve rahmet iken, şimdi Rab’lerinden gelen bir tanığın ilettiği kesin bir kanıta sahip olanlar var ya işte onlar onu onaylarlar. Hangi grup onu inkâr ederse yeri ateştir. Ondan hiçbir kuşkun olmasın. O, Efendinden gelen bir gerçektir. Ne var ki halkın çoğunluğu gerçeği onaylamaz."},{"n":18,"t":"Uydurmaları ALLAH’a yakıştırandan daha zalim kim olabilir? Onlar Rab’lerinin huzuruna çıkarılır ve tanıklar: \"İşte Rab’leri hakkında yalan uyduranlar bunlardır!\" diyecekler. ALLAH’ın laneti zalimleredir."},{"n":19,"t":"Onlar ki ALLAH’ın yolundan alıkoyarlar ve onu çarpıtmak isterler. Onlar ahireti de inkâr ederler."},{"n":20,"t":"Onlar, yeryüzünde kaçamazlar ve ALLAH’tan aşağı dost ve sahipleri yoktur. Onlar için azap katlanır. Çünkü onlar işitemediler, göremediler."},{"n":21,"t":"Onlar, kişiliklerini yitirenlerdir. Uydurdukları şeyler bile kendilerini terk edip kaybolmuştur."},{"n":22,"t":"Hiç kuşku yok ki, ahirette en çok kaybedenler onlardır."},{"n":23,"t":"Gerçeği onaylayıp erdemli davrananlar ve Rab’lerine gönülden boyun eğenler ise bahçe halkıdır. Onlar orada ebedî kalıcıdır."},{"n":24,"t":"Her iki grubun örneği, kör ve sağır olan biri ile gören ve işiten biri gibidir. Durumları bir midir? Öğüt almaz mısınız?"},{"n":25,"t":"Nuh’u halkına gönderdik: \"Ben sizin için apaçık bir uyarıcıyım\""},{"n":26,"t":"\"ALLAH’tan aşağısına hizmet etmeyin. Acı bir günün azabına uğramanızdan korkarım.\""},{"n":27,"t":"Halkından inkâr eden ileri gelenler, \"Seni sadece bizim gibi bir insan olduğunu görüyoruz ve aramızdaki sığ görüşlü ayak takımının dışında kimsenin seni izlemediğini görüyoruz. Sizin bizden herhangi bir üstünlüğünüzü de görmüyoruz. Tersine, biz sizin yalancı olduğunuzu sanıyoruz\" dediler."},{"n":28,"t":"Dedi ki: \"Ey halkım, ya ben Efendimden gelen kesin bir kanıta sahip isem ve bana bir rahmet vermiş de bunlar gözünüze görünmüyorsa? Siz onu istemezken sizi ona biz mi zorlayacağız?\""},{"n":29,"t":"\"Ey halkım, buna karşılık sizden herhangi bir para istemiyorum. Ücretim ancak ALLAH’tan gelir. Gerçeği onaylayanları da kovamam; onlar, Rab’leriyle karşılaşacaklar. Fakat, sizi cahillik eden bir topluluk olarak görüyorum.\""},{"n":30,"t":"\"Ey halkım, onları kovarsam ALLAH’a karşı kim bana yardım edecek? Düşünmez misiniz?\""},{"n":31,"t":"\"ALLAH’ın hazinelerinin yanımda olduğunu söylemiyorum, gizliyi bilmiyorum, melek olduğumu da ileri sürmüyorum. Gözlerinizin horladığı kimselere ALLAH’ın bir iyilik bağışlamayacağını da söylemiyorum. Onların gizli düşüncelerini ALLAH daha iyi bilir. Aksi taktirde zalimlerden olurum.\""},{"n":32,"t":"Dediler ki: \"Ey Nuh, sen bizimle tartıştın ve bizimle tartışmayı uzattın. Doğru sözlü isen haydi bizi tehdit ettiğin şeyi getir bakalım.\""},{"n":33,"t":"Dedi ki: \"Onu, dilerse, sizin başınıza ancak ALLAH getirebilir. Siz engel olamazsınız.\""},{"n":34,"t":"\"ALLAH azmanızı dilemişse, ben size öğüt vermek istesem de size o öğüdümün bir yararı olmayacaktır. O’ dur Efendiniz ve siz O’na döndürüleceksiniz.\""},{"n":35,"t":"\"Bunu o uydurdu\" mu diyorlar? De ki: \"Onu ben uydurmuş isem, suçumdan ben sorumlu olacağım ve sizin işlediğiniz suçlarla da benim bir ilişkim yok.\""},{"n":36,"t":"Nuh’a vahyedildi: \"Şu ana kadar gerçeği onaylamış olanların dışında artık halkından hiç kimse onaylamayacaktır. Onların tavırları seni üzmesin.\""},{"n":37,"t":"\"Gözetimimiz altında vahyimizle gemiyi yap. Zalimler için bana baş vurma; onlar suda boğulacaklardır.\""},{"n":38,"t":"Gemiyi yapıyorken, halkının ileri gelenleri her yanından geçişte onunla aşağılıyorlardı. Dedi ki: \"Bizi aşağılıyorsanız, sizin bizi aşağıladığınız gibi biz de aşağılıyoruz.\""},{"n":39,"t":"\"Alçaltıcı azabın kime geleceğini ve kimin kalıcı azaba mahkûm olacağını yakında bileceksiniz.\""},{"n":40,"t":"Nihayet emrimiz gelip de gök kaynayıp taşınca, kendisine dedik ki: \"Her türden birer çifti, daha önce mahkûm edilmiş olanlar hariç, çoluk çocuğunu ve gerçeği onaylayanları ona yükle.\" Kendisiyle birlikte gerçeği onaylamış olanlar zaten birkaç kişiydi."},{"n":41,"t":"Dedi ki: \"Gemiye binin. Akması ve durması ALLAH’ın adıyladır. Efendim çok Bağışlayandır, Rahimdir.\""},{"n":42,"t":"Gemi, onları dağ gibi dalgaların arasından geçirirken, Nuh bir kenarda ayrı duran oğluna seslendi: \"Yavrum, gel bizimle birlikte bin. Kâfirlerle birlik olma.\""},{"n":43,"t":"O ise, \"Beni sudan koruması için bir tepeye sığınacağım\" dedi. \"Bugün ALLAH’ın yargısından koruyacak hiçbir şey yoktur; ancak O’nun acıdıkları hariç\" dedi. Dalgalar ikisi arasından geçti; o, boğulanların arasındaydı."},{"n":44,"t":"Ve denildi ki: \"Ey toprak suyunu yut, ey gök sen de tut.\" Su yatıştı, karar yerine getirildi, Cudi (Judea) üzerine oturdu ve \"Zalimler uzak olsunlar!\" dendi."},{"n":45,"t":"Nuh Efendisine seslendi: \"Ey Efendim, oğlum benim ailemdendir, Senin verdiğin söz ise elbette gerçektir ve Sen, yargıda bulunanların en iyisisin.\""},{"n":46,"t":"Dedi ki: \"Ey Nuh, o senin ailenden olamaz. Bilmediğin bir konuda benden istekte bulunman erdemli bir tavır değildir. Cahillerden olmamanı sana öğütlerim.\""},{"n":47,"t":"Dedi ki: \"Efendim, bilgim olmayan bir konuda sana yalvardığım için sana sığınırım. Beni bağışlamaz ve bana acımazsan kaybedenlerden olurum.\""},{"n":48,"t":"Dendi ki: \"Ey Nuh, sana ve seninle birlikte olan uluslara bizden barış ve bereketlerle in. Ayrıca öyle uluslar var ki onları bir süre yaşatacağız ve sonra onlara bizden acı bir azap dokunacaktır.\""},{"n":49,"t":"Bunlar, sana vahyettiğimiz metafizik haberleridir. Ne sen, ne de senin halkın bundan önce onları bilmezdi. Sabret. Sonuç, erdemlilerindir."},{"n":50,"t":"Ad halkına da kardeşleri Hud’u… Dedi ki: \"Ey halkım, ALLAH’a hizmet edin. O’ndan başka tanrınız yoktur. Siz ancak uyduruyorsunuz.\""},{"n":51,"t":"\"Ey halkım, buna karşılık olarak sizden herhangi bir ücret de istemiyorum. Benim ücretim, beni ilk yaratandan başkasına düşmez. Aklınızı kullanmıyor musunuz?\""},{"n":52,"t":"\"Ey halkım, Efendinizden bağışlanma dileyin, sonra O’na yönelin ki gökten üzerinize bol rahmet yağdırsın, gücünüze güç katsın. Suçlular olarak yüz çevirmeyin!\""},{"n":53,"t":"Dediler ki: \"Ey Hud, sen bize kesin bir kanıt ile gelmedin. Biz, sırf senin sözünle dinimizi bırakacak değiliz, seni onaylayacak değiliz.\""},{"n":54,"t":"\"Senin tanrılarımızdan biri tarafından çarpıldığını söyleriz,\" Dedi ki: \"ALLAH’ı tanık tutuyorum, siz de tanık olun ki ben uzağım sizin ortak koştuğunuz...\""},{"n":55,"t":"\"O’ndan başkalarından. Haydi, topunuz birleşip bana karşı plan hazırlayın. Hiç de beklemeyin.\""},{"n":56,"t":"\"Ben, Efendim ve Efendiniz olan ALLAH’a güvendim. O’nun kontrol etmediği hiçbir yaratık yoktur. Efendim dosdoğru yolun üzerindedir.\""},{"n":57,"t":"\"Yüz çevirirseniz, artık ben, kendisiyle gönderildiğim mesajı size bildirdim. Efendim yerinize başka bir halk geçirecek ve siz O’na hiçbir zarar veremezsiniz. Benim Efendim her şeyi Gözetip Kontrol Edendir.\""},{"n":58,"t":"Emrimiz gelince Hud’u ve beraberindeki gerçeği onaylayanları bizden bir rahmetle kurtardık. Onları dehşetli bir azaptan kurtardık."},{"n":59,"t":"İşte Ad halkı böyleydi. Rab’lerinin ayetlerini reddettiler, elçilerine isyan ettiler ve her inatçı zorbanın emrini izlediler."},{"n":60,"t":"Bunun üzerine, hem dünya hayatında ve hem diriliş gününde bir lanete uğradılar. Kısacası, Ad halkı, Rab’lerine karşı çıktı. Hud’un halkı Ad yok olmuştur."},{"n":61,"t":"Semud’a da kardeşleri Salih’i… Dedi ki: \"Ey halkım, ALLAH’a hizmet edin, O’ndan başka tanrı yoktur. Sizi yerden çıkarıp yaratan, sizi oraya yerleştiren O’dur. Öyleyse O’ndan bağışlanma dileyin ve sonra O’na yönelin. Kuşkusuz Efendim Yakındır, Yanıtlayandır.\""},{"n":62,"t":"Dediler ki: \"Ey Salih, sen bundan önce, aramızda popüler bir umut kaynağıydın. Atalarımızın hizmet etmiş olduklarından sen şimdi bizi men mi ediyorsun? Biz, senin bizi çağırdığın şeylerden kuşku içindeyiz.\""},{"n":63,"t":"Dedi ki: \"Ey halkım, ya ben Efendimden kesin bir delile sahipsem ve kendisinden bana rahmet vermişse? O’na isyan edecek olursam beni ALLAH’tan kim kurtarabilir? Siz ancak benim kayıplarımı arttırabilirsiniz.\""},{"n":64,"t":"\"Ey halkım, ALLAH’ın bu devesi sizin için bir ayettir. ALLAH’ın toprağında bırakın otlansın. Ona kötülük dokundurmayın. Yoksa sizi yakın bir azap yakalar.\""},{"n":65,"t":"Fakat, onu işkenceyle kestiler. \"Yurdunuzda yaşamanız için üç gününüz var. Bu, yalan olmayan bir sözdür!\" dedi."},{"n":66,"t":"Emrimiz gelince, Salih’i ve beraberinde gerçeği onaylamış olanları bizden bir rahmet ile o günün rezilliğinden kurtardık. Efendin, kuşkusuz Güçlü ve Üstündür."},{"n":67,"t":"Zalimleri korkunç bir ses yakaladı, yurtlarında çöküp kaldılar."},{"n":68,"t":"Sanki orada hiç yaşamamışlardı. Doğrusu Semud (halkı) Rab’lerine karşı geldi; Semud yok olup gitti."},{"n":69,"t":"Elçilerimiz İbrahim’e müjdeyi götürdüklerinde \"Selam!\" (Barış olsun) dediler. O da \"Selam!\" dedi ve hemen (onlara) kızartılmış bir buzağı sundu."},{"n":70,"t":"Ellerinin ona uzanmadığını görünce, durumlarını beğenmedi; içine bir korku düştü. \"Korkma\" dediler, \"Biz Lut’un halkına gönderilmiş bulunuyoruz.\""},{"n":71,"t":"Ayakta duran karısı gülünce biz de ona İshak’ı ve İshak’ın ardından Yakup’u müjdeledik."},{"n":72,"t":"\"Vay başıma gelenler!\" dedi, \"Ben bir yaşlı kadın ve kocam da ihtiyar bir adam iken çocuk mu doğuracağım? Bu çok garip bir şey!\""},{"n":73,"t":"\"ALLAH’ın işine mi şaşıyorsun\" dediler, \"ALLAH’ın rahmeti ve bereketi sizin üzerinizedir ey ev halkı. O Övgüye En Layıktır, Yücelerin Yücesidir.\""},{"n":74,"t":"İbrahim’den korku gidip kendisine bu müjde verilince Lut halkı hakkında bizimle tartışmaya başladı."},{"n":75,"t":"Doğrusu, İbrahim çok yumuşak, çok duygulu ve sürekli yönelen biriydi."},{"n":76,"t":"\"Bundan vazgeç İbrahim. Efendinin emri gelmiş bulunuyor; onlar önlenemez bir azaba mahkûm olmuşlardır.\""},{"n":77,"t":"Elçilerimiz Lut’a gelince, onlara kötü davranıldı. Bu durum canını sıktı ve \"Zor birgün olacak\" dedi."},{"n":78,"t":"Halkı koşarak oraya geldiler; günah işlemeyi adet haline getirmişlerdi. \"Ey halkım, işte kızlarım, onlar sizin için daha temizdir. ALLAH’ı sayın, konuklarım önünde beni rezil etmeyin. İçinizde aklı başında bir adam yok mu?\" dedi."},{"n":79,"t":"\"Bilirsin ki senin kızlarına bizim bir ihtiyacımız yok. Sen bizim ne istediğimizi iyi bilirsin\" dediler."},{"n":80,"t":"\"Keşke size gücüm yetseydi veya güçlü dostlara sahip olsaydım\" dedi."},{"n":81,"t":"\"Ey Lut\" dediler, \"Biz, Efendinin elçileriyiz. Onlar sana dokunamazlar. Aileni gecenin bir anında yürüyüşe çıkart, sizden hiç kimse geriye bakmasın; fakat senin karın istisna. Ötekilerin başına gelecek olanlar onun da başına gelecektir. Onların belirlenmiş zamanı sabahtır. Sabah yakın değil mi?\""},{"n":82,"t":"Emrimiz gelince onun üstünü altına getirdik, üzerlerine sertleşmiş kat kat taş yağdırdık."},{"n":83,"t":"Zalimleri bulsun diye Efendin tarafından belirlenmiş…"},{"n":84,"t":"Medyen’e de kardeşleri Şuayb’ı… Dedi ki: \"Ey halkım, ALLAH’a hizmet edin, O’ndan başka tanrınız yoktur. Ölçüyü tartıyı eksik tutmayın. Sizi refah içinde görüyorum ve sizin için, kuşatıcı bir günün azabından korkuyorum.\""},{"n":85,"t":"\"Ey halkım, ölçüyü ve tartıyı adaletle tam uygulayın. Halkın hakkını eksik vermeyin ve yeryüzünde bozgunculuk yaparak kötülük işlemeyin.\""},{"n":86,"t":"\"Gerçeği onaylıyorsanız, ALLAH’ın bıraktığı, sizin için daha iyidir. Ben sizin üzerinize bekçi değilim.\""},{"n":87,"t":"Dediler ki: \"Şuayb, atalarımızın hizmet etmiş olduklarından veya ticaretimizi dilediğimiz gibi çevirmekten vazgeçmemizi senin namazın mı gerektiriyor? Sen aslında yumuşak huylusun, akıllısın.\""},{"n":88,"t":"\"Halkım\" dedi, \"Bakın, ya ben Efendimden kesin bir kanıta sahip isem ve bana kendisinden güzel bir nimet bağışlamışsa?… Sizi bazı şeyleri yasaklamam, size zıt gitmek istediğim için değildir. Ben sadece gücüm yettiğince bir reform gerçekleştirmek istiyorum. Başarım ancak ALLAH’tandır. O’na güvendim ve O’na yöneliyorum.\""},{"n":89,"t":"\"Halkım, bana karşı çıkışınız, sakın sizi Nuh halkının veya Hud halkının, yahut Salih halkının başına gelenler gibi bir felakete uğratmasın. Üstelik, Lut halkı sizden pek uzakta değil.\""},{"n":90,"t":"\"Efendinizden bağışlanma dileyin, sonra O’na tövbe edin. Kuşkusuz Efendim Rahimdir, Sevendir.\""},{"n":91,"t":"\"Şuayb\" dediler, \"Senin söylediklerinin birçoğunu anlamıyoruz. Üstelik biz, seni aramızda güçsüz görüyoruz. Kabilen olmasaydı seni taşlardık/kovardık. Senin bize karşı herhangi bir üstünlüğün yoktur.\""},{"n":92,"t":"Dedi ki: \"Ey halkım, kabilem size göre ALLAH’tan daha mı üstündür ki O’na sırt çevirdiniz? Efendim, sizin tüm yaptıklarınızı Kuşatandır.\""},{"n":93,"t":"\"Halkım, elinizden geleni yapın; ben de yapacağım. Alçaltıcı azabın kime geleceğini ve kimin yalancı olduğunu ileride bileceksiniz. Umutla bekleyin, ben de sizinle birlikte umutla bekliyorum.\""},{"n":94,"t":"Emrimiz gelince Şuayb’ı ve kendisiyle beraber gerçeği onaylamış olanları bizden bir rahmetle kurtardık. Zulmedenleri korkunç gürültü yakaladı; yurtlarında çöküp kaldılar."},{"n":95,"t":"Sanki orada hiç yaşamamışlar gibi… Semud, nasıl yok edildiyse, Medyen de öylece yok edildi."},{"n":96,"t":"Musa’yı işaretlerimizle (ayat) ve kesin bir yetkiyle gönderdik;"},{"n":97,"t":"Firavun ve konseyine… Ancak onlar Firavunun buyruğuna uydular. Firavunun buyruğu ise akıllıca değildi."},{"n":98,"t":"Diriliş gününde halkına öncülük edip onları ateşe sokacaktır. Girdikleri yer ne kötü bir mekandır!"},{"n":99,"t":"Burada da, ahirette de peşlerine lanet takılmıştır. Aldıkları armağan ne kötü armağandır!"},{"n":100,"t":"Sana bu aktardıklarımız, o kentlerin haberlerindendir. Onlardan kimi hâlâ ayakta, kimi de biçilmiştir."},{"n":101,"t":"Biz onlara zulmetmedik, onlar kendi kendilerine zulmettiler. Efendinin emri geldiği zaman, ALLAH’tan aşağı yalvardıkları tanrıları onları hiçbir şeyden kurtaramadı. Aslında, onların yalnızca ziyanlarını arttırdı."},{"n":102,"t":"İşte Efendin, zulmetmekte olan kentleri yakaladığı zaman böyle yakalar. O’nun yakalaması acıdır, çetindir."},{"n":103,"t":"Ahiret azabından korkanlar için bunda bir ders vardır. Halkın toplandığı birgündür o. Tanık olunan bir gündür o."},{"n":104,"t":"Onu ancak sayılı bir süre için erteliyoruz."},{"n":105,"t":"O gün geldiği zaman, hiç kimse O’nun izni olmadan konuşamaz. Onlardan kimi talihsiz, kimi de mutludur."},{"n":106,"t":"Talihsizler ateştedir. Onlar orada sızlayıp inlerler."},{"n":107,"t":"Gökler ve yer durduğu sürece orada kalıcıdırlar; ancak Efendin dilerse başka. Efendin dilediğini Yapandır."},{"n":108,"t":"Mutluluğu hak edenler ise, gökler ve yer kaldığı sürece bahçede kalıcıdırlar. Efendin dilerse başka. Kesintisiz bir ödüldür bu."},{"n":109,"t":"Şunların hizmet ettiklerinden hiçbir kuşkun olmasın. Aynen daha önceki atalarının hizmet ettiği gibi hizmet ediyorlar. Onların nasiplerini eksiksiz olarak kendilerine ödeyeceğiz."},{"n":110,"t":"Musa’ya kitabı verdik; ancak onda anlaşmazlığa düştüler. Efendinin verilmiş bir sözü olmasaydı aralarında hüküm verilecekti. Onlar ondan kuşku içindedirler, kararsızdırlar."},{"n":111,"t":"Efendin hepsinin yaptıklarının karşılığını tam olarak verecektir. O, onların yaptıklarından Haberdardır."},{"n":112,"t":"Emredildiğin gibi dosdoğru ol, seninle beraber yönelmiş olanlarla birlikte… Aşma ve azgınlaşma. O, sizin yaptıklarınızı Görendir."},{"n":113,"t":"Zalimlere sakın sempati duymayın, onları desteklemeyin, yoksa size ateş dokunur. Sizin ALLAH’tan aşağı dostlarınız yoktur, sonra size yardım da edilmez."},{"n":114,"t":"Gündüzün iki ucunda, gecenin yakın kısmında namazı gözet. İyilikler kötülükleri silip götürür. Bu, öğüt alacak olanlara bir öğüttür."},{"n":115,"t":"Sabret, çünkü ALLAH, iyilik yapanların ödülünü savsamaz."},{"n":116,"t":"Sizden önceki nesillerin erdem sahibi olanları, yeryüzünde kötülüklere engel olmalı değil miydiler? Onlardan kurtardığımız az kişi hariç… Zalimler ise, kendilerine verilen refaha dalıp şımardılar; böylece suçlulara katıldılar."},{"n":117,"t":"Halkı erdemli davrandığı sürece, Efendin kentleri yok edecek değildir."},{"n":118,"t":"Efendin dileseydi halkı tek bir toplum yapardı. Fakat onlar sürekli olarak tartışıp duracaklar."},{"n":119,"t":"Efendinin acıdıkları hariç. Bunun içindir ki onları yarattı. Efendinin sözü yerine gelmiştir: \"Cehennemi cinler ve halkla, topluca dolduracağım.\""},{"n":120,"t":"Gönlünü pekiştirmek için elçilerin tarihlerinden sana yeterince aktarmaktayız. Bunda, senin için bir gerçek ve gerçeği onaylayanlar için de bir aydınlatma ve uyarı gelmiştir."},{"n":121,"t":"Gerçeği onaylamayanlara de ki: \"Elinizden geleni yapın, biz de yapacağız.\""},{"n":122,"t":"\"Sonra bekleyin, biz de beklemekteyiz.\""},{"n":123,"t":"Göklerin ve yerin gizlilikleri ALLAH’a aittir. Tüm işler sonunda ona döner. O’na hizmet edin ve O’na güvenin. Efendin onların yaptığından habersiz değildir."}]},{"id":12,"name":"Yusuf Suresi","verses":[{"n":1,"t":"A. L. R. Bunlar apaçık kitabın mucizeleridir."},{"n":2,"t":"Onu Arapça bir Kuran olarak indirdik ki anlayasınız."},{"n":3,"t":"Sana bu Kuran’ı vahyederek, sana en güzel bir anlatımla tarihi aktarıyoruz. Sen daha önce bundan habersizdin."},{"n":4,"t":"Yusuf, bir zamanlar babasına: \"Babacığım, on bir gezegeni, güneşi ve ay’ı gördüm, onların bana secde ettiklerini gördüm\" dedi."},{"n":5,"t":"\"Yavrum\" dedi, \"Rüyanı kardeşlerine anlatma, olur ki sana karşı bir plan kurarlar. Çünkü sapkın, insana apaçık bir düşmandır.\""},{"n":6,"t":"\"Böylece Efendin seni seçmekte, sana rüyaların yorumunu öğretmekte ve daha önceki ataların İbrahim ve İshak’a nimetini tamamladığı gibi sana ve Yakup ailesine de tamamlamaktadır. Efendin Bilendir, Bilgedir.\""},{"n":7,"t":"Dileyenler için, Yusuf ve kardeşlerinde dersler vardır:"},{"n":8,"t":"Demişlerdi ki: \"Babamız, Yusuf ve (öz) kardeşini bizden daha çok seviyor, biz ise çoğunluğuz. Babamız açıkça yanlış bir tutum içindedir.\""},{"n":9,"t":"\"Yusuf’u öldürün, ya da onu uzak bir yere yollayın ki babanızın ilgisi sizde odaklansın. Daha sonra da erdemli bir topluluk olursunuz.\""},{"n":10,"t":"Onlardan birisi şöyle dedi: \"Yusuf’u öldürmeyin, onu kuyunun dibine atın. Böyle yaparsanız kervanlardan biri onu bulup götürebilir.\""},{"n":11,"t":"Dediler ki: \"Ey babamız, neden Yusuf hakkında bize güvenmiyorsun? Oysa biz onun candan dostlarıyız.\""},{"n":12,"t":"\"Onu bizimle birlikte yolla ki koşup oynasın. Kuşkusuz biz onu koruyacağız.\""},{"n":13,"t":"Dedi ki: \"Onu götürmeniz beni endişelendirir. Korkarım ki haberiniz yokken onu kurt yer.\""},{"n":14,"t":"Dediler ki: \"Biz kalabalık bir grup olduğumuz halde onu kurt yerse, o zaman gerçekten kaybedenler oluruz.\""},{"n":15,"t":"Onu götürdükleri ve kuyunun dibine atmak için topluca karar verdikleri sırada biz ona: \"Onların bu yaptıklarını, hiç farkında olmayacakları bir anda onlara anlatacaksın\" diye vahyettik."},{"n":16,"t":"Akşamleyin ağlayarak babalarına geldiler."},{"n":17,"t":"\"Ey babamız\" dediler, \"Gittik, yarışıyorduk. Yusuf’u da eşyamızın yanında bırakmıştık. Sonunda onu kurt yedi. Doğru konuşsak bile sen bizi onaylamayacaksın.\""},{"n":18,"t":"Gömleğine yalandan kan bulaştırmışlardı. Dedi ki: \"Doğrusu, egonuz sizi bir işe sürüklemiş. Bana düşen güzelce dayanmaktır. Sizin komplonuza karşı ancak ALLAH’tan yardım istenir.\""},{"n":19,"t":"Oradan geçmekte olan bir kervan, sucularını gönderdi, kovasını sarkıtınca: \"Müjde, burada bir erkek çocuğu var!\" dedi. Onu ticari bir mal olarak sakladılar. ALLAH onların yaptıklarını biliyordu."},{"n":20,"t":"Ona ihtiyaçları olmadığı için ucuz bir fiyata, birkaç dirheme sattılar."},{"n":21,"t":"Onu Mısır’da satın alan kişi, karısına, \"Ona iyi bak, olur ki bize yararı dokunur, ya da onu evlat ediniriz\" dedi. Böylece Yusuf’u o yerde yerleştirip ona rüyaların yorumunu öğretiyorduk. ALLAH işini sonuçlandırandır; fakat halkın çoğu bunu bilmez."},{"n":22,"t":"Büyüyüp erginleşince ona bilgelik ve bilgi verdik. Güzel davrananları böyle ödüllendiririz."},{"n":23,"t":"Evinde bulunduğu kadın onu baştan çıkarmak istedi, kapıları kilitledi ve: \"Tümüyle sana aidim\" dedi. Dedi ki: \"ALLAH’a sığınırım. O benim efendimdir (Efendimdir), ki bana iyi bir yer verdi. Zalimler başarmaz.\""},{"n":24,"t":"Kadın onu çok arzulamıştı, efendisinin (rabbinin) işaretini görmeseydi o da onu çok arzulamıştı. Böylece kötülük ve fenalığı ondan çevirdik. O, katışıksız kullarımızdandı."},{"n":25,"t":"Kapıya doğru koşuştular. Kadın onun gömleğini arkadan çekip yırttı. Kapının yanında kadının beyiyle karşılaştılar. Kadın: \"Karına tecavüz etmek isteyen kişinin ya hapsedilmesi veya acı bir azapla cezalandırılması gerekmez mi?\" dedi."},{"n":26,"t":"Dedi ki: \"Aslında senin karın beni baştan çıkarmak istedi.\" Aileden bir tanık: \"Gömleği ön taraftan yırtılmışsa kadın doğruyu söylüyor, o ise bir yalancıdır.\""},{"n":27,"t":"\"Yok eğer gömleği arkadan yırtılmışsa, o zaman kadın yalancı, o doğru sözlüdür\" diye tanıklıkta bulundu."},{"n":28,"t":"Gömleğinin arkadan yırtılmış olduğunu görünce, \"Bu, siz kadınların planıdır. Planınız müthiştir\" dedi."},{"n":29,"t":"\"Yusuf, sen bu olayı unut. Sen de (ey kadınım) günahından dolayı bağışlanma dile. Sen hata işledin.\""},{"n":30,"t":"Şehirde birtakım kadınlar: \"Valinin karısı hizmetçisini baştan çıkarmaya çalışıyor\" dediler, \"Ona çılgıncasına aşık. Onu açık bir sapıklık içinde görüyoruz.\""},{"n":31,"t":"Dedikodularını işitince kadın onları davet etti. Onlar için konforlu yerler hazırladı. Her birine birer bıçak verdi. \"Huzurlarına çık!\" dedi. Onu gören kadınlar ellerini kestiler ve: \"ALLAH korusun, bu bir insan değil; bu ancak asil bir melekdir!\" dediler."},{"n":32,"t":"\"İşte siz beni bunun için suçlamıştınız. Onu baştan çıkarmak istedim, ancak kendisini koruyup beni reddetti. Kendisine emrettiğimi yapmazsa hapishaneye atılacak ve aşağılanacaktı!\" dedi."},{"n":33,"t":"\"Efendim, hapishane, onların beni çağırdığı şeyden daha iyidir. Planlarını benden savmazsan onlara meyledip cahillerden olurum\" dedi."},{"n":34,"t":"Rabbi onun duasına yanıt verdi ve kadınların planlarını ondan savdı. O İşitendir, Bilendir."},{"n":35,"t":"Sonra, kanıtları görmelerine rağmen, onu belli bir süreye kadar hapishaneye atmayı uygun gördüler."},{"n":36,"t":"Onunla birlikte hapishaneye iki genç adam da girdi. Onlardan biri: \"Kendimi şarap yaparken gördüm\" dedi. Diğeri: \"Ben de başımın üzerinde ekmek taşırken kendimi gördüm, onu kuşlar yiyordu. Bunların yorumunu bize bildir. Seni iyilerden görüyoruz.\""},{"n":37,"t":"\"Size ayrılan karavana yemeği elinize geçmeden önce size onun yorumunu bildirebilirim. Bunlar, Efendimin bana öğrettiği şeylerdendir. Ben, ALLAH’ı onaylamayan bir toplumun dinini terk etmiş bulunuyorum, onlar ahiret konusunda da inkârcıdırlar.\""},{"n":38,"t":"\"Ben, atalarım İbrahim, İshak ve Yakup’un dinine uydum. ALLAH’a herhangi bir şeyi ortak koşmak bize yakışmaz. Bu, ALLAH’ın bize ve halka olan lütfudur. Ancak insanların çoğu şükretmez.\""},{"n":39,"t":"\"Ey hapishane arkadaşlarım, çeşitli Efendiler mi daha iyidir, yoksa Tek ve her şeye Egemen olan ALLAH mı?\""},{"n":40,"t":"\"O’ndan başka hizmet ettikleriniz, sizin ve atalarınızın uydurduğu isimlerden ibarettir. ALLAH onlara herhangi bir güç vermemiştir. Hüküm ancak ALLAH’ındır. Yalnızca kendisine hizmet etmenizi emretmiştir. Dosdoğru din işte budur. Ne var ki halkın çoğu bunu bilmiyor.\""},{"n":41,"t":"\"Hapishane arkadaşlarım, biriniz efendisine (rabbine) şarap sunacak, diğeriniz ise çarmıha gerilecek ve kuşlar onun başından yiyecek. Sorduğunuz iş çözülmüştür.\""},{"n":42,"t":"O ikisinden, kurtulacağını öngördüğü kimseye, \"Beni efendinin (rabbinin) yanında an\" dedi. Efendini (rabbini) anmayı/andırmayı sapkın ona unutturunca hapiste birkaç yıl daha kaldı."},{"n":43,"t":"Kral dedi ki: \"Rüyamda yedi semiz inek görüyorum, onları yedi zayıf inek yiyor; ayrıca yedi yeşil ve yedi kuru başak… Ey seçkinler, rüyaların yorumunu yapabiliyorsanız bu rüyamı bana çözüverin.\""},{"n":44,"t":"\"Karmakarışık rüyalardır bunlar. Biz böyle rüyaların yorumunu bilmeyiz\" dediler."},{"n":45,"t":"O iki kişiden kurtulmuş olanı, nice zaman sonra hatırladı ve \"Beni gönderirseniz size onun yorumunu bildireceğim\" dedi."},{"n":46,"t":"\"Yusuf, ey can arkadaşım, bize yedi sıska inek tarafından yenen yedi semiz inek, yedi yeşil ve kuru başak hakkında açıklama getir de halka bilgi vereyim.\""},{"n":47,"t":"Dedi ki: \"Yedi yıl boyunca ekip biçtiğinizi, yediğiniz az bir kısmının dışında, başaklarında bırakıp depolayın.\""},{"n":48,"t":"\"Sonra, onun ardından yedi kurak gelecek ve sizin koruduklarınızdan az bir bölümü hariç, o yıllar için önceden biriktirdiklerinizi yiyip bitirecektir.\""},{"n":49,"t":"\"Ondan sonra ise öyle bir yıl gelir ki onda halk ferahlanacak ve onda (meyve) sıkıp, (hayvan) sağacaklar.\""},{"n":50,"t":"Kral, \"Onu bana getirin\" dedi. Elçi ona gidince, \"Efendine (rabbine) dön ve parmaklarını kesen kadınların durumunu ondan sor. Kuşkusuz benim Efendim, onların entrikalarını bilir\" dedi."},{"n":51,"t":"\"Yusuf’u baştan çıkarmak isterken durumunuz neydi?\" Kadınlar, \"ALLAH korusun; biz ondan bir kötülük görmedik!\" dediler. Bunun üzerine, valinin karısı şöyle dedi: \"Gerçek artık ortaya çıktı. Onu ben yoldan çıkarmaya çalışmıştım. O doğru konuşuyor.\""},{"n":52,"t":"\"Umarım ki arkasında kendisine ihanet etmediğimi bilir, zira ALLAH hainlerin planını onaylamaz.\""},{"n":53,"t":"\"Suçsuz olduğumu ileri sürmüyorum. Kuşkusuz, kişi kötülüğe eğilimlidir. Ben ancak Efendimin merhametini umuyorum; Efendim Bağışlayandır, Rahimdir.\""},{"n":54,"t":"Kral dedi ki: \"Getirin onu, yanımda çalışması için onu atayayım.\" Kendisiyle konuşup görüşünce, \"Sen artık bugün yanımızda önemli bir makamı olan güvenilir birisin\" dedi."},{"n":55,"t":"Dedi ki: \"Beni ülkenin maliye işlerinin başına getir. Kuşkusuz ben iyi korur, iyi bilirim\" dedi."},{"n":56,"t":"Böylece Yusuf’u o ülkede yerleştirdik. Dilediği gibi hareket edebiliyordu. Dilediğimiz kimseye rahmetimizi yağdırırız. Güzel davrananları ödülsüz bırakmayız."},{"n":57,"t":"Gerçeği onaylayanların ve erdemli davrananların ahiret ödülü elbette daha da iyidir."},{"n":58,"t":"Yusuf’un kardeşleri gelip onun huzuruna girdiler. Onları tanıdı; ancak onlar onu tanımadı."},{"n":59,"t":"Yüklerini hazırlatınca şöyle dedi: \"Baba tarafından olan kardeşinizi getirin. Görmüyor musunuz ben ölçüyü tartıyı tam, ev sahipliğini de iyi yapıyorum.\""},{"n":60,"t":"\"Onu bana getirmezseniz, artık benden ölçülüp tartılacak bir şey beklemeyin ve bana yaklaşmayın.\""},{"n":61,"t":"Dediler ki: \"Onun hakkında babasını ikna etmeye çalışacağız. Kuşkun olmasın ki buna çalışacağız.\""},{"n":62,"t":"Memurlarına da şöyle emir verdi: \"Ailelerine döndüklerinde bulmaları için, takas eşyalarını yüklerinin içine sokun, belki böylece geri dönerler.\""},{"n":63,"t":"Babalarına döndüklerinde, \"Ey babamız\" dediler, \"Bundan böyle bize erzak yasaklandı. Kardeşimizi bizimle yolla da erzak alalım. Biz onu koruruz\" dediler."},{"n":64,"t":"\"Daha önce kardeşi için size nasıl güvendiysem şimdi de onun içinde mi size güveneyim? ALLAH en iyi Koruyucudur ve O, Merhametlilerin Merhametlisidir.\""},{"n":65,"t":"Erzak yüklerini açınca, eşyalarının kendilerine geri verilmiş olduğunu gördüler ve, \"Ey babamız, daha ne isteriz? İşte eşyalarımız bize geri verilmiş. Ailemizin geçimini sağlar, kardeşimizi korur ve bir deve yükü daha erzak alırız. Bu, kolay bir iştir\" dediler."},{"n":66,"t":"\"Hepiniz kuşatılıp engellenmedikçe onu bana getireceğinize dair bana, ALLAH adına sağlam bir söz vermezseniz, onu sizinle beraber göndermem. Onlar ona söz verince, \"Söylediklerimize ALLAH tanıktır\" dedi."},{"n":67,"t":"Dedi ki: \"Yavrularım, bir tek kapıdan girmeyin; farklı kapılardan girin. Ne var ki, ALLAH’ın önceden belirlediği şeyden sizi kurtaramam. Hüküm ALLAH’ındır ancak. Ben O’na güvendim. Güvenenler O’na güvenmeli.\""},{"n":68,"t":"Babalarının kendilerine emrettiği yerlerden girdiler. Bu, onları ALLAH’ın hiçbir takdirinden kurtaramazdı; ancak Yakup onlardan bunu istemekte özel bir nedene sahipti. O, kendisine öğrettiğimiz belli bir bilgiye sahipti; fakat halkın çoğu bilmez."},{"n":69,"t":"Yusuf’un huzuruna girdiklerinde, kardeşini yanına yaklaştırdı ve \"Ben senin kardeşinim; onların yaptıklarına üzülme\" dedi."},{"n":70,"t":"Onların erzak yükünü hazırlatınca bir su kabını kardeşinin torbasına koydu. Daha sonra birisi şöyle seslendi: \"Ey kervan siz hırsızlarsınız.\""},{"n":71,"t":"Onları karşılayarak, \"Neyi kaybettiniz?\" dediler."},{"n":72,"t":"\"Kralın su tasını kaybettik. Kim onu getirirse ona bir deve yükü ödül verilecektir. Ben bunu garantiliyorum.\""},{"n":73,"t":"Dediler ki: \"ALLAH’a andolsun, siz de bilirsiniz ki biz bu ülkede bozgunculuk çıkarmaya gelmedik, biz hırsız da değiliz.\""},{"n":74,"t":"Dediler: \"Peki, yalan söylüyorsanız onun cezası nedir?\""},{"n":75,"t":"\"Onun cezası\" dediler, \"Kimin torbasında bulunursa o kişi alıkonur. Biz zalimleri böyle cezalandırırız.\""},{"n":76,"t":"Kardeşinin yükünden önce onların yüklerinden başladı ve sonra su kabını kardeşinin yükünden çıkardı. Biz Yusuf’a böyle bir planı öğretmiştik. Kralın yasasını uygulasaydı kardeşini alıkoyamazdı; ALLAH dilese başka. Dilediğimizi derecelerle yükseltiriz. Her bilenin üstünde daha iyi bir bilen vardır."},{"n":77,"t":"\"O çalmışsa, daha önce kardeşi de çalmıştı\" dediler. Yusuf onlara belli etmeden: \"Siz gerçekten kötüsünüz. ALLAH anlattığınızın içyüzünü bilir\" diye söylendi."},{"n":78,"t":"Dediler ki: \"Sayın ekselans, onun oldukça yaşlı bir babası var; onun yerine bizden birimizi al. Biz seni iyilik edenlerden olduğunu görüyoruz.\""},{"n":79,"t":"Dedi ki: \"Yanında eşyamızı bulduğumuz kimseden başkasını alıkoymaktan ALLAH’a sığınırız, o zaman biz zalimlerden oluruz.\""},{"n":80,"t":"Ondan ümitlerini kesince, danışmak üzere bir kenara çekildiler. Büyükleri: \"Babanızın sizden ALLAH adına bir söz aldığını ve daha önce Yusuf konusunda da sınırı aşmış olduğunuzu bilmez misiniz? Babam bana izin verinceye, yahut ALLAH hakkımda hüküm verinceye kadar buradan ayrılmayacağım. O, en iyi Hükmedendir\" dedi,"},{"n":81,"t":"\"Babanıza dönün ve şunları söyleyin: «Ey babamız, oğlun hırsızlık yaptı. Biz ancak bildiğimiz şeye tanıklık ediyoruz. Gizli işlenen bir şeyi önleyemezdik.»"},{"n":82,"t":"\"Bulunduğumuz topluluğa ve beraber geldiğimiz kervana sor. Biz doğruyu anlatıyoruz.\""},{"n":83,"t":"\"Hayır, egonuz sizi bir işe sürüklemiş. Bana düşen artık güzelce sabretmektir. Olur ki ALLAH, bana onları topluca getirir. O, Bilendir, Bilgedir\" dedi."},{"n":84,"t":"Onlardan yüz çevirdi ve, \"Vah, yazık oldu Yusuf’a!\" dedi. Üzüntüden gözlerinde katarakt oluştu, acısını içine gömdü."},{"n":85,"t":"Dediler ki: \"ALLAH’a andolsun, Yusuf’u anmaya devam edersen ya hasta düşeceksin veya öleceksin.\""},{"n":86,"t":"\"Ben kahrımı ve tasamı ancak ALLAH’a şikayet ederim, sizin bilmediğinizi ALLAH’tan biliyorum\" dedi."},{"n":87,"t":"\"Oğullarım, gidin, Yusuf’u ve kardeşini araştırın. ALLAH’ın rahmetinden umut kesmeyin. İnkârcılardan başkası ALLAH’ın rahmetinden umut kesmez.\""},{"n":88,"t":"Huzuruna girince, \"Sayın ekselans, bize ve ailemize darlık dokundu; bu yüzden değersiz bir eşya ile geldik. Ama sen bize tam ölçü ver, bize yardımda bulun. ALLAH sadaka verenleri ödüllendirir\" dediler."},{"n":89,"t":"\"Sizler cahiller iken, Yusuf ve kardeşine neler yaptığınızı biliyor musunuz\" dedi."},{"n":90,"t":"\"Yoksa sen, sen gerçekten Yusuf musun?\" dediler. \"Ben Yusuf’um, bu da kardeşimdir. ALLAH bize iyilikte bulundu. Kim erdemli davranır ve sabrederse elbette ALLAH güzel davrananları ödülsüz bırakmaz\" dedi."},{"n":91,"t":"\"ALLAH’a andolsun ki ALLAH seni bizden üstün tutmuştur. Biz gerçekten hatalıydık\" dediler."},{"n":92,"t":"Dedi ki: \"Bugün size kınama yoktur. ALLAH sizi affetsin. O, merhametlilerin En Merhametlisidir.\""},{"n":93,"t":"\"Bu gömleğimi götürün ve onu babamın yüzüne atın; gözü açılsın. Tüm ailenizle birlikte bana gelin.\""},{"n":94,"t":"Kervan ayrılınca, babaları, \"Beni bunamış saymayın, Yusuf’un kokusunu işitiyorum\" dedi."},{"n":95,"t":"\"ALLAH’a andolsun sen hâlâ eski şaşkınlığın içindesin\" dediler."},{"n":96,"t":"Müjdeci gelip de onu yüzüne atınca, tekrar görmeye başladı ve şöyle dedi: \"ALLAH’tan sizin bilmediğiniz şeyleri biliyorum dememiş miydim?\""},{"n":97,"t":"Dediler ki: \"Ey babamız, günahlarımızın bağışlanmasını dile. Biz gerçekten yanlış davrandık.\""},{"n":98,"t":"Dedi ki: \"Sizin için Efendimden bağışlanma dileyeceğim; O, Bağışlayandır, Rahimdir.\""},{"n":99,"t":"Yusuf’un yanına vardıklarında, ana-babasını kucakladı ve: \"ALLAH’ın izniyle güven içinde Mısır’a girin\" dedi."},{"n":100,"t":"Ana ve babasını tahtın üzerine kaldırdı. Hepsi onun için secdeye kapandılar. Dedi ki: \"Babacığım, bu, önceden görmüş bulunduğum rüyanın gerçekleşmesidir. Efendim onu gerçekleştirdi. Sapkın, benimle kardeşlerimin arasını açtıktan sonra O beni hapishaneden çıkararak ve sizi çölden getirerek bana iyilikte bulundu. Gerçekten Efendim dilediğine karşı çok şefkatlidir. O, Bilendir, Bilgedir.\""},{"n":101,"t":"\"Efendim, sen bana hükümranlık verdin ve rüyaların yorumunu öğrettin. Yeri ve göğü ayırarak yaratansın. Dünya ve ahirette sensin benim dostum (velim). Canımı Müslüman olarak al ve beni iyilere kat.\""},{"n":102,"t":"Bunlar, sana vahyettiğimiz geçmişin haberleridir. Onlar topluca karar alıp düzen kurarlarken sen onların yanında değildin."},{"n":103,"t":"Ne kadar istesen de halkın çoğunluğu gerçeği onaylamayacaktır."},{"n":104,"t":"Hâlbuki sen onlardan herhangi bir ücret de istemiyorsun. Bu, sadece halka bir uyarıdır."},{"n":105,"t":"Göklerde ve yerde nice deliller var ki yanından dikkatsizce geçerler."},{"n":106,"t":"Onların da çoğu, ortak koşmadan ALLAH’ı onaylamaz."},{"n":107,"t":"Onlar, ALLAH tarafından kuşatıcı bir azabın kendilerine çatmasından, yahut o anın aniden kendilerine gelmesinden emin mi oldular?"},{"n":108,"t":"De ki: \"Benim yolum şudur: Açık bir delille ALLAH’a çağırırım, aynı şekilde beni izleyenler de… ALLAH Yücedir, ben ortak koşan birisi değilim.\""},{"n":109,"t":"Senden önce, kentler halkının arasından seçip vahyettiğimiz adamlardan başkasını göndermedik. Yeryüzünü dolaşıp kendilerinden öncekilerin akıbetine bakmazlar mı? Erdemliler için ahiret yurdu daha iyidir; anlamaz mısınız?"},{"n":110,"t":"Ne zaman ki elçiler umutlarını kestiler ve kendilerinin yalancı çıkarıldığını sandılar, işte o zaman onlara zaferimiz geldi. Nitekim, dilediğimiz kurtulur. Azabımız suçlular topluluğundan geri çevrilemez."},{"n":111,"t":"Onların tarihinde, bilinç sahipleri için bir ders vardır. Bu, uydurma bir hadis değil; fakat kendisinden öncekilerin doğrulayıcısı, her şeyin detaylı açıklaması ve gerçeği onaylayanlar için bir hidayet ve Rahmettir."}]},{"id":13,"name":"Ra'd Suresi","verses":[{"n":1,"t":"A. L. M. R. Bu (harfler/rakamlar), kitabın mucizeleridir. Efendinden sana indirilen, gerçektir; fakat halkın çoğu gerçeği onaylamaz."},{"n":2,"t":"Görebileceğiniz bir direk olmadan gökleri yükselten, sonra tüm yönetime egemen olan, güneşi ve ayı buyruk altına alan ALLAH’tır. Hepsi belli bir süre için akıp gitmektedir. Tüm işleri kontrol eder ve ayetleri detaylı olarak açıklar ki Efendinizle kavuşma konusunda kuşkunuz kalmasın."},{"n":3,"t":"O ki yeryüzünü inşa edip üzerine sağlam dağlar, ırmaklar ve erkekli dişili yarattığı her çeşit meyveyi yerleştirdi. Geceyi gündüze bürüyor. Düşünen bir toplum için elbette bunda işaretler ve dersler vardır."},{"n":4,"t":"Yeryüzünde, birbirine komşu toprak parçaları, üzüm bağları, ekinler, çatallı ve çatalsız hurmalıklar vardır. Bunların hepsi aynı su ile sulanmalarına rağmen lezzetçe birbirinden farklı kılmışızdır. Aklını kullanan bir toplum için elbette bunda işaretler ve dersler vardır."},{"n":5,"t":"Şaşacaksan, onların şu sözlerine şaşmalısın: \"Biz toprak olduktan sonra yeniden mi yaratılacağız?\" İşte onlar, Rab’lerini inkâr edenlerdir. Onlar, boyunlarına prangalar hak edenlerdir. Onlar ateşin halkıdır; nitekim orada ebedî kalıcıdırlar."},{"n":6,"t":"İyilik isteyeceklerine, başlarına hemen bir felaket getirmeni isterler; oysa kendilerinden önce örnekler gelip geçti. Efendin, işledikleri zulme rağmen halka karşı bağışlayıcıdır. Efendinin azabı çetindir."},{"n":7,"t":"İnkârcılar, \"Ona bir mucize inmeli değil miydi?\" diyorlar. Sen ancak bir uyarıcısın. Her toplum için bir yol gösterici vardır."},{"n":8,"t":"ALLAH her dişinin yüklendiğini, rahimlerin eksilttiğini ve arttırdığını bilir. O’nun yanında her şey belli bir ölçüye göredir."},{"n":9,"t":"Gizliyi ve açığı Bilendir; Büyüktür, Yücedir."},{"n":10,"t":"Sözü ister gizleyin, ister açıklayın, ister gecenin karanlığında saklanın, ister gündüzün ortaya çıkın O’nun için birdir."},{"n":11,"t":"Önünden ve ardından (görünen ve görünmeyen) izleyiciler var da kendisini ALLAH’ın emrinden mi korurlar? Bir topluluk kendisini değiştirmedikçe ALLAH onların durumunu değiştirmez. ALLAH bir topluluk için fenalık istedi mi, hiçbir güç onu durduramaz; onların O’ndan başka bir koruyup kollayanları da olmaz."},{"n":12,"t":"O, size korku ve umut olarak şimşeği gösteren ve ağır bulutları oluşturandır."},{"n":13,"t":"Gök gürlemesi O’nu överek, melekler de O’nu saygıyla yüceltirler. O, yıldırımları gönderir ve dilediğini onlarla çarpar. Onlar hâlâ ALLAH hakkında tartışıyorlar. O, dayanılmaz güce sahiptir."},{"n":14,"t":"Gerçek dua O’na yöneltilendir. O’nun dışında çağırdıkları ise onlara hiçbir şekilde karşılık veremezler. Tıpkı suya avuçlarını uzatan; ancak ağzına hiçbir şey ulaşmayan kimse gibi… İnkârcıların duası boşunadır."},{"n":15,"t":"Göklerde ve yerde olan herkes ister istemez ALLAH’a secde eder. Gölgeleri de sabah akşam…"},{"n":16,"t":"De ki: \"Göklerin ve yerin Rabbi kim?\" De ki: \"ALLAH\" De ki: \"O’ndan başka, kendilerine dahi yarar ve zarar veremeyen kimseleri evliyalar mı edindiniz?\" De ki: \"Hiç körle gören bir olur mu, yahut hiç karanlıkla ışık bir olur mu?\" Yoksa ALLAH’ın yarattığı gibi yaratan ortaklar buldular da yaratmalarını birbiriyle mi karıştırdılar? De ki: \"ALLAH her şeyin yaratıcısıdır, O Tektir, Egemendir.\""},{"n":17,"t":"Gökten bir su indirir, dereler onunla dolar taşar ve sel bol köpük yüklenir. Aynı şekilde, mücevherat yahut eşya yapmak için erittikleri maddelerden de benzer bir köpük elde ederler. ALLAH gerçeği ve batılı böyle bir örnekle tanıtır. Köpük, kaybolup gider; ancak insanlara yarar veren ise yerde kalır. İşte ALLAH örnekleri böyle verir."},{"n":18,"t":"Rab’lerinin çağrısına uyanlar güzeli hak ederler. O’nun çağrısına uymayanlar ise, yeryüzündekilerin hepsine ve bir o kadarına sahip olsalar dahi kurtulmak için hepsini fidye olarak vermeye hazır olacaklardır. Sorgulamanın en kötüsü onlar içindir ve yerleri cehennemdir; ne de felaketli bir konaktır o!"},{"n":19,"t":"Sana indirilenin gerçek olduğunu bilen biri, görmeyen gibi midir? Ancak akıl sahipleri öğüt alır."},{"n":20,"t":"Onlar ki ALLAH’a verdikleri sözü yerine getirirler ve sözleşmeyi bozmazlar."},{"n":21,"t":"Onlar ki ALLAH’ın birleştirmesini emrettiği şeyi birleştirirler, Rab’lerini sayarlar ve kötü hesaptan korkarlar."},{"n":22,"t":"Ve onlar ki sadece Rab’lerinin onayını kazanmak için sabredip direnirler, namazı gözetirler, kendilerine verdiğimiz rızıklardan gizli ve açık yardım için harcarlar ve kötülüğü iyilik ile savarlar. Son durağı onlar hak etmişlerdir."},{"n":23,"t":"Adn bahçelerine girerler. Atalarından, eşlerinden ve soylarından iyi olanlar da onunla beraberdir. melekler de her kapıdan yanlarına varırlar."},{"n":24,"t":"\"Sabrettiğinizden ötürü selam (barış ve huzur) size olsun. Bu ne güzel son durak!\""},{"n":25,"t":"ALLAH’a verdikleri sözden sonra sözleşmeyi bozanlar, ALLAH’ın birleştirmeyi emrettiğini birleştirmeyenler ve yeryüzünde bozgunculuk yapanlar laneti hak etmişlerdir ve onlar için kötü bir sonuç vardır."},{"n":26,"t":"ALLAH dilediğine rızkı açar veya kısar. Onlar dünya hayatı ile sevindiler, hâlbuki bu dünya hayatı ahiret ile karşılaştırıldığında bir geçimlikten ibarettir."},{"n":27,"t":"İnkâr edenler, \"Ona Efendisinden bir mucize indirilmeli değil miydi?\" diyorlar. De ki: \"ALLAH dileyeni saptırır ve yöneleni doğruya ulaştırır.\""},{"n":28,"t":"Onlar ki onaylarlar ve kalpleri ALLAH’ı anmakla huzur bulur. Bilesiniz ki, kalpler ALLAH’ı anmakla yatışır."},{"n":29,"t":"Gerçeği onaylayıp erdemli bir hayat sürenler için müjde ve en güzel dönüş yeri vardır."},{"n":30,"t":"Daha önceki toplumlara olduğu gibi seni de bu topluma gönderdik ki sana vahyettiğimizi onlara okuyasın, hâlbuki onlar Rahman’a nankörlük ediyorlar. De ki: \"O’dur benim Efendim; O’ndan başka tanrı yoktur. O’na güvendim; dönüş O’nadır.\""},{"n":31,"t":"Kendisiyle dağlar yürütülen, yahut yeryüzü parçalanan, yahut ölüler dirilten bir Kuran olsaydı bile (onlar yine onaylamazdı). Tüm işler ALLAH’ın kontrolündedir. Gerçeği onaylayanlar hâlâ anlamadılar mı ki ALLAH dileseydi tüm insanları doğruya ulaştırırdı. İnkâr edenler, ALLAH’ın sözü yerine gelinceye kadar yaptıklarına karşılık olarak ya başlarına ya da yakınlarına konacak bir felakete uğrayıp duracaklardır. ALLAH sözünden dönmez."},{"n":32,"t":"Senden önceki elçilerle de alay edildi. İnkârcılara fırsat verdim ve sonunda onları yakaladım. Sonuç nasıldı?"},{"n":33,"t":"Herkesin yaptığını kontrol eden O değil midir? Buna rağmen ALLAH’a ortaklar koştular. De ki: \"Onları isimlerle tanımlayın! Siz O’nun yeryüzünde bilmediği bir şeyi mi O’na haber veriyorsunuz, yoksa boş sözler mi uyduruyorsunuz?\" Aslında, inkârcıların hileleri kendilerine süslü gösterilir ve böylece yoldan saparlar. ALLAH kimi saptırırsa ona doğruyu gösterecek yoktur."},{"n":34,"t":"Onlar dünya hayatında azap hak etmişlerdir. Ahiret azabı ise daha kötüdür. Onları ALLAH’tan kimse kurtaramaz."},{"n":35,"t":"Erdemlilere söz verilen bahçenin örneği şudur: Altından ırmaklar akar, yemişi de süreklidir gölgesi de. Bu, erdemlilerin sonudur. Kâfirlerin sonu ise ateştir."},{"n":36,"t":"Kendilerine kitap vermiş olduklarımız sana indirilene sevinirler. Bazı gruplar onun bir kısmını inkâr ederler. De ki: \"ALLAH’a kul olmakla ve O’na ortak koşmamakla emredildim. O’na çağırırım ve dönüşüm de O’nadır.\""},{"n":37,"t":"Böylece onu Arapça bir yasa olarak indirdik. Sana gelen bilgiden sonra onların keyfine uyarsan ALLAH’a karşı ne bir dostun ne de bir koruyucun olamaz."},{"n":38,"t":"Senden önce elçiler gönderdik ve onlara eşler ve çocuklar verdik. ALLAH’ın izni olmadan hiçbir elçi bir mucize getiremez. Her dönemin bir yazgısı vardır."},{"n":39,"t":"ALLAH dilediğini siler, dilediğini bırakır. Ana Kitap O’nun yanındadır."},{"n":40,"t":"Onlara söz verilenlerin bir kısmını sana göstersek de, senin canını alsak da, sana düşen görev bildirmektir. Hesap ise bize düşer."},{"n":41,"t":"Yeryüzünün uçlarından eksilttiğimizi görmüyorlar mı? ALLAH hüküm verir ve O’nun hükmünü izleyip çevirecek de yoktur. O, en hızlı hesaplayandır."},{"n":42,"t":"Onlardan öncekiler de düzenler kurdular; hâlbuki tüm düzenler ALLAH’a aittir. Her kişinin kazandığını bilir. Kâfirler de zaferin kime ait olduğunu bileceklerdir."},{"n":43,"t":"İnkâr edenler, \"Sen bir elçi değilsin!\" diyorlar. De ki: \"Benimle sizin aranızda şahit olarak yeter ALLAH; kitabın bilgisine sahip olandır.\""}]},{"id":14,"name":"İbrahim Suresi","verses":[{"n":1,"t":"A. L. R. Bir kitaptır. Onu sana indirdik ki, halkı Rab’lerinin izniyle karanlıklardan aydınlığa çıkarasın, O Güçlü ve Övgüye layık olanın yoluna…"},{"n":2,"t":"Yani ALLAH’ın. O ki göklerde ve yerde bulunanların hepsine sahiptir. Hak ettikleri çetin azaptan dolayı vay kâfirlerin haline."},{"n":3,"t":"Onlar ki dünya hayatını ahirete yeğlerler, ALLAH’ın yolundan saptırırlar ve onu eğriltmek isterler. Bunlar, alabildiğine sapmışlardır."},{"n":4,"t":"Biz her elçiyi ancak halkının diliyle göndeririz ki onlara bildirebilsin. ALLAH dileyeni/dilediğini saptırır, dileyeni/dilediğini de doğruya ulaştırır. O, Güçlüdür, Bilgedir."},{"n":5,"t":"Musa’yı, \"Halkını karanlıklardan aydınlığa çıkar ve onlara ALLAH’ın günlerini hatırlat\" diye mucizelerimizle gönderdik. Sabreden ve şükreden herkes için elbette bunda dersler vardır."},{"n":6,"t":"Hani, Musa halkına, \"ALLAH’ın üzerinizdeki nimetini hatırlayın. Size işkencenin en kötüsünü uygulayan, oğullarınızı kesip kadınlarınızı utandıran Firavunun adamlarından sizi O kurtardı. Bu, Efendinizden sizin için büyük bir test idi\" demişti."},{"n":7,"t":"Efendin, \"Şükrederseniz size daha bol veririm, ama nankörlük ederseniz azabım çetindir\" diye bildirmişti."},{"n":8,"t":"Musa: \"Yeryüzünde bulunan herkesle birlikte nankörlük etseniz, bilesiniz ki ALLAH muhtaç değildir, övgüye layıktır\" demişti."},{"n":9,"t":"Sizden öncekilerin, Nuh, Ad ve Semud halkının ve onlardan sonra gelip de sadece ALLAH’ın bildiği kimselerin haberleri size ulaşmadı mı? Elçileri onlara apaçık delillerle gittiler, fakat onları küçümsediler ve \"Biz getirdiğiniz şeyi inkâr ediyoruz ve bizi çağırdığınız mesaj hakkında kuşkumuz ve şüphemiz var\" dediler."},{"n":10,"t":"Elçileri: \"Gökleri ve yeri yarıp yaratan ALLAH’tan mı kuşkulanıyorsunuz? Günahlarınızı bağışlamak için sizi çağırıyor ve size belli bir süre tanıyor\" dediler. Onlar da, \"Siz, ancak bizim gibi insanlarsınız, atalarımızın hizmet etmekte olduğu şeyden bizi çevirmek istiyorsunuz. Bize açık bir yetki belgesi getiriniz\" dediler."},{"n":11,"t":"Elçileri ise kendilerine şöyle dediler: \"Biz, elbette sizin gibi birer insanız. Ancak, ALLAH, kullarından dilediğini seçerek ona lütufta bulunur. ALLAH’ın izni olmadan size bir yetki belgesi getirmemiz olanaksızdır. Gerçeği onaylayanlar ALLAH’a güvenmeli.\""},{"n":12,"t":"\"Bize yollarımızı göstermişken neden ALLAH’a güvenmeyelim? Sizin bize yaptığınız eziyete karşı sabırla direneceğiz. Güvenenler ALLAH’a güvenmeli.\""},{"n":13,"t":"İnkârcılar elçilerine, \"Ya bizim dinimize geri dönersiniz ya da sizi yurdumuzdan kovarız!\" dediler. Rab’leri onlara, \"Zalimleri yok edeceğiz\" diye vahyetti,"},{"n":14,"t":"\"Onlardan sonra o yurda sizi yerleştireceğiz. Bu, otoriteme saygı duyan ve tehditlerimden korkanlar içindir.\""},{"n":15,"t":"Zafer istediler, böylece her inatçı zorba perişan oldu."},{"n":16,"t":"Ardından da cehennem… Tadı bozuk sudan içirilirler."},{"n":17,"t":"Onu yutmaya çalışır, ama boğazından geçiremez. Ölüm kendisine her yandan gelir, ama ölemeyecek. Ardından da çetin bir azap gelecektir."},{"n":18,"t":"Rab’lerini inkâr edenlerin yaptıkları işler, fırtınalı bir günde rüzgarın savurduğu kül gibidir. Kazandıklarından hiçbir şey elde edemezler. İşte gerçek kayıp budur."},{"n":19,"t":"ALLAH’ın gökleri ve yeri belli bir amaç için yarattığını görmez misiniz? Dilerse sizi götürüp, yerinize yeni yaratıklar getirir."},{"n":20,"t":"Bu, ALLAH için güç değildir."},{"n":21,"t":"Hepsi ALLAH’ın huzuruna durduklarında. Zayıflar, büyüklük taslamış olanlara: \"Biz sizin izleyicileriniz idik. Bizi ALLAH’ın azabından bir parça kurtarabilir misiniz?\" dediler. Onlar da: \"ALLAH bize bir yol gösterseydi biz de size gösterirdik. Artık sızlansak da dayansak da bizim için birdir, kaçıp kurtulacak bir yerimiz yok.\""},{"n":22,"t":"Karar yayımlandıktan sonra sapkın onlara şöyle dedi: \"ALLAH size gerçeği söz verdi, ben ise size söz verdim ve sözümden caydım. Benim sizin üzerinize herhangi bir gücüm yoktu; ben sizi çağırdım, siz de bana katıldınız. Bundan dolayı beni kınamayın, yalnızca kendinizi kınayın. Ne siz beni kurtarabilirsiniz ne de ben sizi kurtarabilirim. Beni ortak koşmanızı zaten önce de inkâr etmiştim. Zalimler için acı bir azap vardır.\""},{"n":23,"t":"Gerçeği onaylayan ve erdemli davrananlar, içinden ırmaklar akan bahçelere sokulmuşlardır. Rab’lerinin izniyle orada sürekli kalırlar. Oradaki dirlik temennileri, \"Selam\" dır."},{"n":24,"t":"Görmez misin ki ALLAH güzel bir sözü güzel bir ağaca benzetir: Kökü sabit, dalları ise göktedir."},{"n":25,"t":"Efendinin izniyle her mevsim meyvelerini verir. Öğüt almaları için ALLAH insanlara böyle örnekler verir."},{"n":26,"t":"Kötü bir söz de, yerden koparılmış köksüz kötü bir ağaç gibidir."},{"n":27,"t":"ALLAH gerçeği onaylayanları dünya hayatında da, ahirette de kanıtlanmış sözle destekler. ALLAH zalimleri ise saptırır ve ALLAH dilediğini yapar."},{"n":28,"t":"ALLAH’ın nimetini nankörlükle karşılayarak halklarını felaket yurduna mahkûm edenleri görmedin mi?"},{"n":29,"t":"Cehennemde yanacaklardır. Ne kötü bir duraktır o!"},{"n":30,"t":"ALLAH’ın yolundan saptırmak için O’na eşler koştular. De ki: \"Biraz eğlenin, son yolculuğunuz ateşe olacaktır.\""},{"n":31,"t":"Gerçeği onaylayan kullarıma söyle, alışverişin ve dostluğun olmadığı gün gelmeden önce namazı gözetsinler, kendilerine verdiğimiz rızıklardan gizli ve açık yardım için versinler."},{"n":32,"t":"ALLAH gökleri ve yeri yaratan, gökten bir su indirip sizin için çeşitli meyvelerden besinler çıkarandır. Koyduğu yasaya göre sizi denizde taşıması için gemileri emrinize verdi. Aynı şekilde ırmakları da emrinize verdi."},{"n":33,"t":"Görevlerini aksatmayan güneşi ve ayı hizmetinize sundu, geceyi ve gündüzü de hizmetinize sundu."},{"n":34,"t":"O’ndan ne dilediyseniz size verdi. ALLAH’ın nimetlerini sayarsanız bitiremezsiniz. İnsanoğlu gerçekten çok zalimdir, çok nankördür."},{"n":35,"t":"Bir zamanlar İbrahim demişti ki: \"Efendim, bu beldeyi güvenli kıl, beni ve çocuklarımı putlara hizmet etmekten koru.\""},{"n":36,"t":"\"Efendim, onlar, insanlardan birçoğunu saptırdılar. Beni izleyenler bendendir. Bana karşı gelenlere gelince, elbette sen Bağışlayansın, Rahimsin.\""},{"n":37,"t":"\"Efendimiz, ben çocuklarımdan bazısını, Sınırlanmış Ev’inin yanındaki ekinsiz bir vadiye yerleştirdim. Efendimiz, onlar namazı gözetsinler diye… İnsanların gönüllerini onlara karşı sempatiyle doldur ve onları ürünlerle rızıklandır ki şükretsinler.\""},{"n":38,"t":"\"Efendimiz, bizim gizlediğimizi ve açıkladığımızı bilirsin. Yerde ve gökte hiçbir şey ALLAH’a gizli kalmaz.\""},{"n":39,"t":"\"İhtiyarlık çağımda bana İsmail’i ve İshak’ı bahşeden ALLAH’a övgüler olsun. Efendim, dualarımı işitir.\""},{"n":40,"t":"\"Efendim, beni namazı gözeten biri kıl, çocuklarımı da… Efendimiz dualarımı kabul et.\""},{"n":41,"t":"\"Efendimiz, hesabın görüleceği gün, beni, anamı, babamı ve gerçeği onaylayanları bağışla.\""},{"n":42,"t":"Zalimlerin yapmakta olduklarından ALLAH’ı habersiz sanma. Onları sadece, gözlerin dehşetten donup kalacağı güne kadar ertelemektedir."},{"n":43,"t":"Başları boyunları üstüne kaskatı dikilmiş, göz kapakları kıpırdamaksızın korkudan dolayı zihinleri bomboş bir halde koşuşurlar."},{"n":44,"t":"Halkı, azabın kendilerine geleceği gün konusunda uyar. Zalimler, \"Efendimiz bizi yakın bir süreye kadar ertele de senin çağrına katılalım ve elçilere uyalım\" diyecekler. Oysa daha önce siz, sonunuzun gelmeyeceğine yemin etmemiş miydiniz?"},{"n":45,"t":"Hatta, sizden önce kendilerine zulmetmiş olanların konutlarına yerleşmiştiniz ve onlara yaptıklarımız da size belli olmuştu. Üstelik, size örnekler de vermiştik."},{"n":46,"t":"Onlar planlarını yaptılar, hâlbuki planları ALLAH’ın kontrolündeydi. Planları dağları yerinden oynatacak kadar olsa bile…"},{"n":47,"t":"ALLAH’ın, elçilerine verdiği sözden döneceğini sanmayın. ALLAH elbette Üstündür, Öç alandır."},{"n":48,"t":"Yerin başka bir yer ile değiştirildiği ve göklerin de... Herkesin Tek ve En yüce olan ALLAH’ın huzuruna getirildiği gün…"},{"n":49,"t":"O gün suçluları, zincirlere vurulmuş olarak görürsün."},{"n":50,"t":"Giysileri katrandandır ve yüzlerini ateş kaplar."},{"n":51,"t":"Böylece ALLAH herkese yaptığının karşılığını verir. ALLAH hızlı hesap görendir."},{"n":52,"t":"Bu, insanlara bir bildiridir. Bu uyarıyı dinlesinler, O’nun yalnız tek Tanrı olduğunu bilsinler ve akıl sahipleri öğüt alsınlar."}]},{"id":15,"name":"Hicr Suresi","verses":[{"n":1,"t":"A. L. R. Bu (harfler/rakamlar) kitabın ve apaçık Kuran’ın mucizesidir."},{"n":2,"t":"İnkar edenler, keşke Müslüman olsaydık diye arzulayacaklardır."},{"n":3,"t":"Bırak onları, yesinler, eğlensinler ve umutlarıyla oyalansınlar; mutlaka öğreneceklerdir."},{"n":4,"t":"Biz hiçbir topluluğu belirlenmiş bir yazgı olmaksızın yok etmeyiz."},{"n":5,"t":"Hiçbir toplum belirlenmiş süresini ne geçebilir, ne de gerisinde kalır."},{"n":6,"t":"Dediler ki: \"Ey kendisine mesaj (zikr) indirilmiş olan, sen bir delisin.\""},{"n":7,"t":"\"Doğru sözlü isen bize melekleri getirsene.\""},{"n":8,"t":"Biz melekleri ancak belli bir amaç için göndeririz, o zaman da kimseye süre tanınmaz."},{"n":9,"t":"Kuşkusuz mesajı biz, evet biz indirdik ve onu koruyacak da elbette yine biziz."},{"n":10,"t":"Senden önce, geçmiş topluluklara da elçiler gönderdik."},{"n":11,"t":"Onlara her ne zaman bir elçi geldiyse onu alaya aldılar."},{"n":12,"t":"İşte suçluların kalbine böyle (bir tavrı) sokarız."},{"n":13,"t":"Nitekim, onu onaylamazlar. Kendilerinden öncekilerin yasası (sünneti) de böyleydi."},{"n":14,"t":"Onlara gökten bir kapı açsak ve onun içinde yükselecek olsalardı,"},{"n":15,"t":"\"Gözlerimiz sarhoş edildi, büyülendik\" diyeceklerdi."},{"n":16,"t":"Gökte galaksiler yerleştirdik ve gözleyenler için onları süsledik."},{"n":17,"t":"Ve onları her kovulmuş sapkından koruduk."},{"n":18,"t":"Ancak onlardan kulak hırsızlığı eden olursa onu alevli bir ateş mermisi kovalar."},{"n":19,"t":"Yeryüzünü genişletip içine sağlam dağlar yerleştirdik ve orada her şeyi mükemmel bir ölçüye göre bitirdik."},{"n":20,"t":"Orada hem sizin için ve hem sizin beslemediğiniz yaratıklar için yaşanacak bir ortam oluşturduk."},{"n":21,"t":"Hiçbir şey yoktur ki onun hazineleri bizim yanımızda olmasın, ancak biz onu belirlenmiş bir ölçüyle indiririz."},{"n":22,"t":"Rüzgarı aşılayıcı olarak gönderdik; gökten bir su indirip sizi onunla suladık. Oysa siz onu depo edemezdiniz."},{"n":23,"t":"Biz, elbette biz diriltir ve öldürürüz, sonunda her şeyin sahibi olarak kalacak olan yine biziz."},{"n":24,"t":"İlerleyenlerinizi de biliriz, geride kalanları da biliriz."},{"n":25,"t":"Onları, senin Efendin toplayacak. O Bilgedir, Bilendir."},{"n":26,"t":"İnsanı, kurumuş, yıllanmış balçıktan yarattık."},{"n":27,"t":"Cinleri de önceden, içe işleyen parlak ateşten yarattık."},{"n":28,"t":"Efendin meleklere, \"Kurumuş, yıllanmış balçıktan bir insan yaratacağım\" demişti."},{"n":29,"t":"\"Onu düzenleyip ona ruhumdan üflediğimde hemen onun için secdeye varın\" demişti."},{"n":30,"t":"Tüm melekler topluca secde ettiler;"},{"n":31,"t":"Ancak Sapkın (İblis) hariç. Secde edenlerle beraber olmayı red etti."},{"n":32,"t":"Dedi ki: \"Seni secde edenlerle beraber olmaktan alıkoyan şey nedir, İblis?\""},{"n":33,"t":"Dedi ki: \"Kurumuş, yıllanmış balçıktan yarattığın insana secde edecek değilim.\""},{"n":34,"t":"\"Öyleyse çık oradan; sen kovuldun!\""},{"n":35,"t":"\"Yargı gününe kadar laneti hakettin\" dedi."},{"n":36,"t":"\"Efendim, dirilecekleri güne kadar beni ertele\" dedi."},{"n":37,"t":"Dedi ki: \"Tamam, sen ertelendin\""},{"n":38,"t":"\"Bilinen vaktin gününe kadar…\""},{"n":39,"t":"Dedi ki: \"Efendim, beni yoldan çıkarttığın için, onları yeryüzünde ayartıp topluca saptıracağım.\""},{"n":40,"t":"\"Kendilerini sadece sana adayanlar hariç.\""},{"n":41,"t":"Dedi ki: \"İşte benim değişmez yasam budur.\""},{"n":42,"t":"\"Elbette, sadece bana hizmet edenlere karşı bir gücün yoktur. Ancak sana uyan sapıklara gücün yeter.\""},{"n":43,"t":"\"Cehennem hepsinin buluşma yeridir.\""},{"n":44,"t":"\"Onun yedi kapısı vardır ve her bir kapı için onlardan belli bir pay vardır.\""},{"n":45,"t":"Erdemliler ise bahçeler ve pınarlar içindedir."},{"n":46,"t":"Oraya barış ve güvenlik içinde girin."},{"n":47,"t":"Göğüslerindeki kötü duyguları kaldırırız; kardeşçe karşılıklı yerleştirilmiş koltuklar üzerindedirler."},{"n":48,"t":"Orada onlara hiçbir yorgunluk dokunmaz ve oradan çıkarılacak da değillerdir."},{"n":49,"t":"Kullarıma haber ver ki ben Bağışlayıcıyım, Rahimim."},{"n":50,"t":"Ve azabım da çok acı bir azaptır."},{"n":51,"t":"Onlara İbrahim’in konuklarından haber ver."},{"n":52,"t":"Onun yanına varıp, \"Selam!\" demişlerdi. O da, \"Biz sizden korkuyoruz\" demişti."},{"n":53,"t":"\"Endişelenme, biz sana bilgin bir oğul müjdesini veriyoruz\" demişlerdi."},{"n":54,"t":"\"İyice yaşlanmışken beni mi müjdeliyorsunuz! Beni ne ile müjdeliyorsunuz?\" dedi."},{"n":55,"t":"\"Sana gerçeği müjdeledik, umudunu kesme\" dediler."},{"n":56,"t":"\"Sapıtmışlardan başka Efendisinin rahmetinden kim umut keser?\" dedi."},{"n":57,"t":"\"Ey elçiler, göreviniz nedir?\" dedi."},{"n":58,"t":"\"Biz, suçlu bir topluma gönderildik;\""},{"n":59,"t":"\"Ancak Lut’un ailesi hariç. Hepsini kurtaracağız.\""},{"n":60,"t":"\"Yalnız karısı hariç; onun geride kalanlardan olmasını kararlaştırdık\" dediler."},{"n":61,"t":"Elçiler Lut’un ailesine geldiklerinde"},{"n":62,"t":"\"Siz, bizce tanınmayan bir topluluksunuz\" dedi."},{"n":63,"t":"Dediler ki: \"Onların kuşkulandıkları şeyi sana getirdik.\""},{"n":64,"t":"\"Sana gerçeği getirdik, biz elbette doğru konuşuyoruz.\""},{"n":65,"t":"\"Geceleyin ailenle birlikte çık. Arkalarından izle ve hiçbiriniz arkaya bakmasın. Size emredilen yere gidin.\""},{"n":66,"t":"‘Şu halk, sabahleyin yok edilecektir’ şeklindeki emri kendisine bildirdik."},{"n":67,"t":"Kent halkı neşe içinde geldiler."},{"n":68,"t":"\"Bunlar konuklarımdır, sakın beni utandırmayın.\""},{"n":69,"t":"\"ALLAH’tan korkun, beni rezil etmeyin!\" dedi."},{"n":70,"t":"\"İnsanlarla diyalog kurmaktan seni menetmemiş miydik?\" dediler."},{"n":71,"t":"\"İşte benim kızlarım\" dedi, \"İlla da istiyorsanız!\""},{"n":72,"t":"Ne yazık ki onlar, sarhoşlukları içinde bocalıyorlardı."},{"n":73,"t":"Tan ağarırken onları felaketli bir gürültü yakaladı."},{"n":74,"t":"Onun altını üstüne getirdik. Üzerlerine çamurdan yapılmış sert taşlar indirdik."},{"n":75,"t":"Bunda, inceleyip araştıranlar için dersler vardır."},{"n":76,"t":"Ve o yol üzerinde durmaktadır."},{"n":77,"t":"Bunda, gerçeği onaylayanlar için bir işaret vardır."},{"n":78,"t":"Gerçekten Orman Halkı da zalimlerden idi."},{"n":79,"t":"Onlardan öc aldık. Her ikisi de belgelenmiştir."},{"n":80,"t":"Mağara Halkı da elçileri yalanladı."},{"n":81,"t":"Kendilerine ayetlerimizi verdik, fakat ondan yüz çevirdiler."},{"n":82,"t":"Dağlardan güvenli evler yontuyorlardı."},{"n":83,"t":"Sabahleyin onları da o korkunç gürültü yakaladı."},{"n":84,"t":"Kazandıklarının hiçbiri onları kurtaramadı."},{"n":85,"t":"Biz, gökleri, yeri ve aralarındaki şeyleri belli bir amaç için yarattık. O an elbette gelecektir, öyleyse onlara güzel ve yumuşak davran."},{"n":86,"t":"Efendin elbette Yaratandır, Bilendir."},{"n":87,"t":"Biz sana yedi çifti ve büyük Kuran’ı verdik."},{"n":88,"t":"Onlardan bazılarına verdiklerimizi kıskanma ve onlardan ötürü de üzülme. Gerçeği onaylayanlara kanatlarını indir."},{"n":89,"t":"De ki: \"Ben apaçık bir uyarıcıyım.\""},{"n":90,"t":"Aynı şekilde o bölücülerle de ilgileneceğiz."},{"n":91,"t":"Onlar ki Kuran’ı parçalara ayırdılar."},{"n":92,"t":"Efendine and olsun ki, hepsinden soracağız,"},{"n":93,"t":"Yaptıkları şeylerden."},{"n":94,"t":"Öyleyse sana emredileni açıkça ortaya koy ve müşriklere de aldırma."},{"n":95,"t":"Alay edenlere karşı biz sana yeteriz."},{"n":96,"t":"Onlar ki ALLAH ile beraber başka tanrılar oluşturdular. Yakında bilecekler."},{"n":97,"t":"Söylediklerinden ötürü göğsünün daraldığını biliyoruz."},{"n":98,"t":"Efendini yüceltip coşkuyla an ve yerlere kapan."},{"n":99,"t":"Efendine hizmet et ki kesin bir onaya sahip olasın."}]},{"id":16,"name":"Nahl Suresi","verses":[{"n":1,"t":"ALLAH’ın emri gelmiş bulunuyor, öyleyse acele etme. Onların ortak koştuklarından uzaktır, yücedir."},{"n":2,"t":"Kullarından dilediğine, melekleri vahiyle indirerek, emrini iletir: \"İnsanları uyarın: Benden başka tanrı yoktur ve beni dinleyin.\""},{"n":3,"t":"Gökleri ve yeri belli bir amaç için yaratmıştır. Ortak koştuklarından çok yücedir."},{"n":4,"t":"İnsanı küçük bir damladan yarattı, fakat buna rağmen o, apaçık bir düşman kesildi."},{"n":5,"t":"Ve, çiftlik hayvanlarını da sizin için yarattı, onlarda ısıtma ve diğer yararlar vardır ve onlardan yersiniz."},{"n":6,"t":"Ayrıca boş zamanlarınızda ve seyahatlerinizde siz onları toplarken ve salıverirken sizin için onlarda bir konfor ve zevk vardır."},{"n":7,"t":"Ve sizin yüklerinizi de, kendi kendinize ancak zorlukla varacağınız bölgelere taşırlar. Efendiniz elbette Şefkatlidir, Rahimdir."},{"n":8,"t":"Binmeniz ve eğlenmeniz için atları, katırları ve eşekleri yarattı ve daha bilmediğiniz birçok şeyi de yaratır."},{"n":9,"t":"Yolları göstermek ALLAH’a aittir; bazısı eğridir. Dileseydi hepinizi doğruya iletirdi."},{"n":10,"t":"O ki gökten bir su indirdi, ondan içersiniz ve yine beslendiğiniz bitkiler ve ağaçları onunla sularsınız."},{"n":11,"t":"Onunla sizin için ekin, zeytin, hurma ağaçları, üzümler ve her çeşit meyveler bitirmektedir. Düşünen bir toplum için bunda elbette bir ayet vardır."},{"n":12,"t":"Geceyi, gündüzü, güneşi ve ayı hizmetinize sundu. Yıldızlar da O’nun emri altındadır. Aklını kullanan bir toplum için elbette bunda işaretler vardır."},{"n":13,"t":"Ve sizin için yeryüzünde yarattığı rengarenk nesneleri de… Düşünen bir toplum için elbette bunda bir ders vardır."},{"n":14,"t":"O ki denizi emrinize sunmuştur; ondan taze et yersiniz, ondan giyim ve takı için süsler çıkarırsınız. Gemilerin denizi yara yara akıp gittiğini görürsünüz. Böylece O’nun lütfunu ararsınız ve belki ona şükredersiniz."},{"n":15,"t":"Ve sarsılmamanız için yeryüzüne denge sağlayıcılar yerleştirdi, yolu bulmanız için de nehirler, yollar,"},{"n":16,"t":"Ve göze çarpan işaretler… Yıldızlarla da yol bulurlar."},{"n":17,"t":"Yaratan, yaratamayan gibi olur mu? Düşünmez misiniz?"},{"n":18,"t":"ALLAH’ın nimetini saysanız bitiremezsiniz. ALLAH Bağışlayandır, Rahimdir."},{"n":19,"t":"ALLAH gizlediklerinizi de açıkladıklarınızı da bilir."},{"n":20,"t":"Allah’ın yakınından/aşağısından çağırdıkları kişiler hiçbir şey yaratamazlar, aksine kendileri yaratılmışlardır."},{"n":21,"t":"Ölüdürler, diri değildirler. Ne zaman dirileceklerini de bilmezler."},{"n":22,"t":"Tanrınız bir tek tanrıdır. Ahirete onaylamayanların kalpleri inkârcıdır ve onlar büyüklük taslarlar."},{"n":23,"t":"Kuşkusuz ALLAH onların gizlediklerini de açığa vurduklarını da bilir. O, büyüklük taslayanları sevmez."},{"n":24,"t":"Kendilerine, \"Efendiniz ne indirdi?\" denildiğinde, \"Geçmişlerin efsanelerini…\" diye yanıtlarlar."},{"n":25,"t":"Diriliş gününde kendi günahlarının tamamını, ayrıca saptırdıkları kimselerin günah yüklerinden de bir payı bilgisizce yüklenirler. Yükleri ne de kötüdür."},{"n":26,"t":"Kendilerinden öncekiler de tuzak kurmuşlardı; ancak ALLAH, binalarını temelinden yıkmış, üzerlerindeki tavan başlarına çökmüştü; azap onlara ummadıkları yerden gelmişti."},{"n":27,"t":"Sonra, diriliş gününde onları rezil eder ve \"Uğrunda tartışıp mücadele verdiğiniz ‘ortaklarım’ nerede\" der. Kendilerine bilgi verilenler de şöyle derler: \"Bugün rezillik ve kötülük kafirleredir.\""},{"n":28,"t":"Onlar ki, nefislerine zulmedip dururlarken melekler canlarını alır. Sonunda teslim olup \"Biz herhangi bir kötülük yapmıyorduk\" derler. Hayır, ALLAH sizin yaptıklarınızı iyi bilir."},{"n":29,"t":"İçinde sürekli kalacağınız cehennemin kapısından girin. Kibirlenenlerin yeri ne kötüdür."},{"n":30,"t":"Erdemlilere, \"Efendiniz ne indirdi?\" denir. \"İyilik\" diye karşılık verirler. Bu dünyada güzel davrananlar için güzellik vardır. Ahiret yurdu ise daha hayırlıdır. Erdemlilerin yurdu ne de iyidir."},{"n":31,"t":"İçlerinden ırmaklar akan Adn bahçelerine girerler. Orada her diledikleri şeyi bulurlar. ALLAH erdemlileri işte böyle ödüllendirir."},{"n":32,"t":"İyi durumdayken melekler canlarını almaya geldiklerinde, \"Selam size olsun. Yaptıklarınızın karşılığı olarak bahçeye giriniz\" derler."},{"n":33,"t":"Kendilerine meleklerin gelmesini yahut Efendinin emrinin gelmesini mi bekliyorlar? Kendilerinden öncekiler de aynı şekilde davranmışlardı. Onlara ALLAH zulmetmedi, onlar kendi kendilerine zulmettiler."},{"n":34,"t":"Yapmış olduklarının kötü sonuçları onlara dokundu ve alaya almış oldukları şeyler onları kuşattı."},{"n":35,"t":"Ortak koşanlar, \"ALLAH dilemeseydi ne biz, ne de atalarımız O’ndan başka bir şeye hizmet etmez ve O’nun haram ettiğinden başkasını da haram kılmazdık.\" Kendilerinden öncekiler de böyle davranmıştı. Elçinin açıkça bildirmekten başka bir görevi mi var?"},{"n":36,"t":"Her bir toplum içinde, \"ALLAH’a hizmet edin ve azgınlıktan/küstahlıktan sakının\" diyen bir elçi gönderdik. Onlardan kimine ALLAH yol gösterdi, kimi de sapıklıkta kalmaya mahkûm oldu. Yeryüzünü dolaşın ve yalanlayanların sonunun nasıl olduğuna dikkat edin."},{"n":37,"t":"Doğruyu bulmaları için ne kadar uğraşsan da, ALLAH saptırdığını doğruya ulaştırmaz. Onların bir yardımcısı da olmaz."},{"n":38,"t":"\"ALLAH ölmüş olanı diriltmez diye tüm güçleriyle ALLAH’a yemin ederler. Hayır, O’nun verdiği gerçek bir sözdür o. Ancak insanların çoğu bunu bilmiyor."},{"n":39,"t":"Anlaşmazlığa düştükleri konuları onlara açıklasın ve kafirler de kendilerinin yalancı olduğunu öğrensin."},{"n":40,"t":"Bir şeyin olmasını istediğimiz zaman ona sadece \"Ol\" deriz ve o da olur."},{"n":41,"t":"Zulme uğradıktan sonra ALLAH uğrunda göç edenleri, dünyada güzelce yerleştireceğiz. Ahiret ödülleri ise daha büyüktür; bir bilseler…"},{"n":42,"t":"Onlar, sabrederek Rab’lerine güvenenlerdir."},{"n":43,"t":"Senden önce, adamlardan/iki ayak üzerinde yürüyenlerden başkasını elçi olarak göndermedik; onlara vahyettik. Bilmiyorsanız uzmanlara sorun."},{"n":44,"t":"Belgeler ve kitaplarla… Sana bu mesajı indirdik ki, kendilerine indirileni halka açıklayasın (bildiresin) ve onlar da düşünsünler."},{"n":45,"t":"Kötülük planlayanlar ALLAH’ın kendilerini yerin dibine geçirmeyeceğinden, yahut ummadıkları bir yerden kendilerine azabın gelmeyeceğinden emin mi oldular?"},{"n":46,"t":"Yahut dönüp dururlarken kendilerini yakalamayacağından...? Onlar kurtulamazlar."},{"n":47,"t":"Yahut onları korku ve endişe içinde iken yakalamayacağından? Efendiniz elbette Şefkatlidir, Rahimdir."},{"n":48,"t":"ALLAH’ın yarattığı şeylere bakmıyorlar mı ki, gölgeleri ALLAH’a secde ederek sağdan ve soldan sürünerek gidip gelir."},{"n":49,"t":"Göklerde ve yerde bulunan tüm yaratıklar ve melekler ALLAH’a secde ederler ve büyüklük taslamazlar."},{"n":50,"t":"Kendilerinden çok yüce olan Rab’lerini sayarlar ve kendilerine emredileni uygularlar."},{"n":51,"t":"ALLAH, \"İki tanrı edinmeyin, O’ndan başka tanrı yoktur. Sadece benden çekinin\" demiştir."},{"n":52,"t":"Göklerde ve yerde ne varsa O’nundur. Din de sürekli sadece O’nundur. ALLAH’tan aşağısını mı sayıyorsunuz?"},{"n":53,"t":"Size ulaşan her nimet ALLAH’tandır. Nitekim, bir sıkıntıya uğradığınızda sadece O’na yalvarırsınız."},{"n":54,"t":"Ne var ki, sizden o sıkıntıyı kaldırdığı zaman, sizden bir grup hemen Rab’lerine ortak koşmaya başlar,"},{"n":55,"t":"Kendilerine verilene nankörlük ederek… Keyfinize bakın; yakında mutlaka bileceksiniz!"},{"n":56,"t":"Kendilerine verdiğimiz rızıklardan bilinçsizlere bir pay ayırırlar. ALLAH’a andolsun ki siz bu uydurduğunuz şeylerden sorulacaksınız."},{"n":57,"t":"Yüce ALLAH’a kızları ayırıyorlar; kendilerine de hoşlandıklarını…"},{"n":58,"t":"Onlardan birine dişi müjdelendiği zaman, büyük bir öfkeyle yüzü kapkara kesilir."},{"n":59,"t":"Kendisine müjdelenen ‘kötülükten’ utanarak halkından kendini gizlemeye çalışır. Şimdi onu utana utana tutsun mu, yoksa toprağa mı gömsün! Ne kötü yargıda bulunuyorlar."},{"n":60,"t":"Ahireti onaylamayanlar kötü örneği oluştururlar; halbuki en yüce örnekler ALLAH’ındır. O Üstündür, Bilgedir."},{"n":61,"t":"ALLAH zulümlerinden dolayı insanları cezalandırsaydı orada bir yaratık bırakmazdı; ne var ki onları belli bir süreye kadar erteler. Sürelerinin sonu geldiği zaman da ne bir an öne alınırlar, ne de ertelenirler."},{"n":62,"t":"Hoşlanmadıkları şeyleri ALLAH’a malediyorlar ve kendilerinin iyiyi hakettikleri yalanını dillerinde geveliyorlar. Elbette, ateşe terkedilecekler."},{"n":63,"t":"ALLAH’a andolsun ki senden önceki toplumlara da elçiler gönderdiğimizde sapkın işlerini onlara güzel gösterdi. Nitekim onların dostu (veli) bugün odur. Onlar acı bir azaba mahkûm olmuşlardır."},{"n":64,"t":"Sana bu kitabı indirdik ki, anlaşmazlığa düştükleri konuları kendilerine bildiresin. Bu kitap, gerçeği onaylayan bir topluluk için bir yol göstericidir, bir rahmettir."},{"n":65,"t":"ALLAH gökten bir su indirir ve onunla yeryüzünü ölümünden sonra diriltir. Dinleyen bir toplum için bunda bir işaret vardır."},{"n":66,"t":"Sizin için çiftlik hayvanlarında da dersler vardır. İçmeniz için karınlarından, yani sindirilmiş yiyecek ile kan arasından çıkan bir maddeyi size sunuyoruz: İçimi lezzetli saf süt."},{"n":67,"t":"Ve hurma ağaçlarının meyvelerinden, üzümlerden hem sarhoş edici içkiler ve hem de güzel bir rızık elde edersiniz. Akleden bir toplum için bunda bir işaret vardır."},{"n":68,"t":"Ve Efendin dişi arıya vahyetti: \"Dağlardan, ağaçlardan ve kovanlardan evler edin\""},{"n":69,"t":"\"Sonra, her çeşit meyveden ye ve Efendinin planını aynen izle.\" Karınlarından, insanlar için şifa içeren çeşitli renklerden bir içecek çıkar. Düşünen insanlar için bunda bir işaret vardır."},{"n":70,"t":"Ve sizi ALLAH yarattı, sonra da yaşamınıza son verir. Sizden bazıları hayatın en kötü zamanına kadar yaşatılır ki bilgiden sonra hiçbir şeyi bilmesin. ALLAH Bilendir, Her şeye Gücü Yetendir."},{"n":71,"t":"ALLAH rızık açısından sizi birbirinize üstün kılmıştır. Nitekim, üstün kılınanlar, emirleri altındakilerle varlıklarını eşit paylaşmazlar. ALLAH’ın nimetini mi reddediyorlar?"},{"n":72,"t":"Ve ALLAH kendi cinsinizden sizin için eşler yarattı, eşlerinizden de sizin için çocuklar ve torunlar yarattı ve size güzel rızıklar verdi. Böyleyken onlar batılı gerçek diye onaylayıp ALLAH’ın nimetine nankörlük mü ediyorlar?"},{"n":73,"t":"ALLAH’ı bırakıp, kendilerine göklerden ve yerden rızık sağlamayan aciz kişilere hizmet ediyorlar."},{"n":74,"t":"Öyleyse, ALLAH’a örnekler vermeyiniz; siz bilmezken ALLAH bilir."},{"n":75,"t":"ALLAH, hiçbir şeye gücü yetmeyen, sahiplenilmiş bir köle ile kendi tarafımızdan güzelce rızıklandırdığımız, o rızıktan gizli ve açık yardım için harcayan kişiyi örnek olarak verir. Bu ikisi hiçbir olur mu? Övgü ALLAH’adır, ancak çokları bilmezler."},{"n":76,"t":"ALLAH şu iki adamı da örnek verir: Birisi bir şey yapacak yeteneğe sahip olmayıp tümüyle efendisine/sahibine bağımlıdır, onu ne işe koşsa bir şey beceremez. İşte böyle bir kişi ile doğru yol üzerinde bulunup adaleti uygulayan kişi hiçbir olur mu?"},{"n":77,"t":"Göklerin ve yerin gizemleri ALLAH’a aittir. O an bir göz kırpması kadar veya daha kısadır. ALLAH her şeye Gücü Yetendir."},{"n":78,"t":"ALLAH sizi annelerinizin karnından çıkardığı zaman bir şey bilmiyordunuz. Size işitme, görme duyuları ve beyinler verdi ki şükredesiniz."},{"n":79,"t":"Göğün atmosferine uygun yaratılmış kuşları görmüyorlar mı? Onları ALLAH’tan başkası tutmaz. Bunda gerçeği onaylayan bir toplum için elbette ayetler vardır."},{"n":80,"t":"Ve ALLAH evlerinizi sizin için barınaklar yaptı. Çiftlik hayvanlarının derilerinden, yolculuk günü ve ikamet günü kullanacağınız portatif evler sağladı. Yünlerinden, kürklerinden ve kıllarından da bir süreye kadar giyip döşeyeceğiniz eşyalar çıkardı."},{"n":81,"t":"Ve ALLAH yarattığı şeylerden sizin için gölgeler oluşturdu. Sizin için dağları sığınak yaptı. Sizi sıcaktan koruyacak elbiseler ve sizi savaşlarınızda koruyacak elbiseler hazırladı. Teslim olasınız diye nimetlerini size böyle tamamlıyor."},{"n":82,"t":"Yüz çevirirlerse, sana düşen, yalnızca açık bir biçimde iletmektir."},{"n":83,"t":"ALLAH’ın nimetlerini çok iyi tanıdıkları halde onları inkâr ederler. Onların çoğu kafirlerdir."},{"n":84,"t":"Her topluluktan bir tanık gönderdiğimiz gün, inkâr edenlere ne izin verilir ne de özürleri kabul edilir."},{"n":85,"t":"Zulmedenler azabı gördükleri zaman artık onlar için hafifletilmez, ertelenmez."},{"n":86,"t":"Ortak koşanlar, ortak koştukları kimseleri gördükleri zaman, \"Efendimiz, senden başka çağırdığımız ortaklarımız işte bunlardır\" derler. (Onlar da), \"Siz yalancılarsınız,\" diye karşılık verirler."},{"n":87,"t":"O gün tamamıyla ALLAH’a teslim olmuşlardır ve uydurdukları şeyler de kendilerini terketmiştir."},{"n":88,"t":"İnkar edip ALLAH’ın yolundan sapanlara gelince, onlara yaptıkları bozgunculuktan ötürü azap üstüne azap arttırırız."},{"n":89,"t":"Her topluluk içinden, kendilerine karşı bir tanık gönderdiğimiz, şunlara karşı da seni tanık olarak getirdiğimiz gün… Biz sana bu kitabı, her şeyi açıklayan, bir yol gösterici, bir rahmet ve Müslümanlara bir müjde olarak indirdik."},{"n":90,"t":"ALLAH adaleti, iyilik yapmayı ve akrabaya yardım etmeyi emreder. Kötülükten, fenalıktan ve azgınlıktan ise sizi meneder. Öğüt almanız için sizi böyle aydınlatır."},{"n":91,"t":"Anlaşma yaptığınızda ALLAH’ın ahdini yerine getirin. Pekiştirdiğiniz yeminleri bozmayın. ALLAH’ı kendinize kefil kılmıştınız. ALLAH yaptıklarınızı bilir."},{"n":92,"t":"İpliğini sağlamca eğirdikten sonra çözen kadın gibi olmayın. Bir topluluğun diğer bir topluluktan güçlü olmasından yararlanarak yeminlerinizi aranızda kötüye kullanmayın. ALLAH sizi böylece dener. Anlaşmazlığa düştüğünüz konuları diriliş günü size açıklayacak."},{"n":93,"t":"ALLAH dileseydi sizi bir tek toplum kılardı. Ancak, dilediğini saptırır, dilediğine de yol gösterir. Elbette yaptıklarınızdan sorulacaksınız."},{"n":94,"t":"Yeminlerinizi aranızda kötüye kullanmayın ki sağlam basmış ayağınız kaymasın. ALLAH’ın yolundan saptığınız için perişanlığı tadar ve acı bir azabı hakedersiniz."},{"n":95,"t":"ALLAH’a verdiğiniz sözü ucuza satmayın. Sizin için ALLAH’ın yanındakiler daha iyidir; bir bilseniz."},{"n":96,"t":"Sizin yanınızda bulunanlar biter; ancak ALLAH’ın yanındakiler ise süreklidir. Güçlüklere karşı direnenlerin ödüllerini, yaptıkları iyiliklere uygun olarak elbette vereceğiz."},{"n":97,"t":"Erkek olsun, kadın olsun, her kim gerçeği onaylamış olarak iyi bir iş yaparsa ona bu dünyada güzel bir hayat bağışlarız ve yaptıkları iyi işlere karşılık ödüllerini de tam veririz."},{"n":98,"t":"Kuran okuduğunda kovulmuş sapkından ALLAH’a sığın."},{"n":99,"t":"Gerçeği onaylayıp Rab’lerine güvenenlere onun bir gücü yoktur."},{"n":100,"t":"Onun gücü, kendisini dost edinenlere ve onu Rab’lerine ortak koşanlaradır."},{"n":101,"t":"Biz bir delilin yerine bir başka delili getirdiğimiz zaman ki ALLAH neyi indirdiğini iyi bilir, \"Sen, ancak bir iftiracısın!\" derler. Gerçekten çokları bilmiyor."},{"n":102,"t":"De ki: \"Gerçeği onaylayanları sağlamlaştırsın, Müslümanlara bir yol gösterici ve müjde olsun diye Kutsal Ruh onu Efendinden gerçekle indirdi."},{"n":103,"t":"\"Ona bir insan öğretiyor\" biçimindeki sözlerini elbette biliyoruz. Amaçladıkları kişinin dili yabancıdır, bu ise apaçık Arapça bir dildir."},{"n":104,"t":"ALLAH’ın ayetlerini onaylamayanları ALLAH doğru yola iletmez; onlar için acı bir azap vardır."},{"n":105,"t":"Yalan uydurup iftira edenler ALLAH’ın ayetlerini onaylamayanlardır. Onlar gerçek yalancılardır."},{"n":106,"t":"Kalbi gerçeği onaylayıp ikna olduğu halde zorlanan dışında, onaydan sonra inkâra göğsünü açıp ALLAH’ı inkâr edenler, ALLAH’tan bir gazabı haketmişlerdir ve onlar için büyük bir azap vardır."},{"n":107,"t":"Çünkü onlar dünya hayatını ahirete tercih ettiler. İnkarcı topluluğu ALLAH doğru yola iletmez."},{"n":108,"t":"İşte onlar, ALLAH’ın kalplerini, işitme ve görüşlerini mühürlediği kişilerdir. Onlar gafillerdir."},{"n":109,"t":"Hiç kuşku yok ki onlar ahirette kaybedeceklerdir."},{"n":110,"t":"Sonra Efendin, baskıya uğradıktan sonra göç eden, cihad eden ve direnenler için, evet senin Efendin, kuşkusuz onlar için Bağışlayandır, Rahimdir."},{"n":111,"t":"O gün herkes gelir kendini kurtarmaya çalışır ve herkese yaptığının karşılığı tam ödenir ve onlara asla zulmedilmez."},{"n":112,"t":"ALLAH güven içinde başarılı bir topluluğu örnek olarak verir: O topluluğun rızkı kendilerine her taraftan bol miktarda ulaşırdı. Ancak daha sonra, ALLAH’ın nimetlerine karşı nankör davranınca ALLAH onlara açlık ve korku belasını tattırdı."},{"n":113,"t":"Onlara kendilerinden bir elçi geldi, onu yalanladılar. Sonunda, zulmederlerken onları azap yakaladı."},{"n":114,"t":"ALLAH’ın size verdiği helal ve güzel rızıklardan yiyin ve ALLAH’ın nimetlerine şükredin; sadece O’na hizmet ediyorsanız."},{"n":115,"t":"Size yalnızca leş, kan, domuz eti ve ALLAH’tan başkası için adananları haram kılmıştır. Kim zorda kalırsa, istekli olmamak ve sınırı aşmamak koşuluyla ALLAH Bağışlayandır, Rahimdir."},{"n":116,"t":"Dillerinizin yalan yere nitelendirmesinden ötürü \"Bu helaldir, bu haramdır\" demeyin. Böylece ALLAH’a yalan yakıştırmış olursunuz. ALLAH’a yalan yakıştıranlar başarıya ulaşamazlar."},{"n":117,"t":"Kısa süren bu zevkten sonra onlar için acı bir azap vardır."},{"n":118,"t":"Yahudilere, daha önce sana anlattığımız şeyleri haram kıldık. Biz onlara zulmetmedik; fakat onlar kendi kendilerine zulmediyorlardı."},{"n":119,"t":"Bunlara rağmen Efendin, bilgisizlik yüzünden kötülük işledikten sonra ardından tövbe edip düzelenlere, evet senin Efendin ondan sonra Bağışlayandır, Rahimdir."},{"n":120,"t":"İbrahim, ALLAH’a boyun eğen, tek tanrıcı bir öncü idi. Hiçbir vakit ortak koşmadı."},{"n":121,"t":"O’nun nimetlerine şükredici idi. Onu seçti ve onu doğru yola iletti."},{"n":122,"t":"Ve ona bu dünyada mutluluk verdik, ahirette ise erdemlilerle birlikte olacaktır."},{"n":123,"t":"Nitekim, İbrahim’in dinini tek tanrılı olarak izlemen için sana vahyettik; o asla putperestlerden olmadı."},{"n":124,"t":"Cumartesi tatili, sadece onda ayrılığa düşenlere farz kılınmıştı. Efendin, ayrılığa düştükleri konuda diriliş günü aralarında hüküm verecektir."},{"n":125,"t":"Efendinin yoluna bilgelikle ve güzel bir aydınlatma ile çağır. Onlarla en güzel biçimde tartış. Efendin, yolundan sapanları ve doğru yolda olanları en iyi bilendir."},{"n":126,"t":"Karşılık verecekseniz, size verilen karşılığın bir benzeriyle karşılık verin. Sabrederseniz, elbette bu sabredenler için daha hayırlıdır."},{"n":127,"t":"Sabret, sabrın ancak ALLAH’ın yardımıyladır. Onlar için üzülme ve onların tuzaklarından da endişelenme."},{"n":128,"t":"ALLAH erdemli davrananlar ve iyilikte bulunanlar ile beraberdir."}]},{"id":17,"name":"İsra Suresi","verses":[{"n":1,"t":"Bazı ayetlerimizi kendisine göstermek için kulunu geceleyin Sınırlanmış Mescitten, çevresini kutlu kıldığı en uzak mescide alıp götüren çok Yücedir. O kuşkusuz İşitendir, Görendir."},{"n":2,"t":"Aynı şekilde, Musa’ya kitabı vermiştik. İsrailoğullarını şu gerçeğe iletmek için: \"Benden başka bir sahip edinmeyin.\""},{"n":3,"t":"Onlar, Nuh ile birlikte taşıttığımız kimselerin soyudur; o şükreden bir kuldu."},{"n":4,"t":"Kitapta, İsrailoğullarına: \"Yeryüzünde iki kere bozgunculuk çıkaracaksınız ve alabildiğine kibirleneceksiniz\" diye bildirdik,"},{"n":5,"t":"\"Birincisinin zamanı gelince, büyük güce sahip kullarımızı üstünüze göndeririz. Evlerinize kadar girerek araştırırlar. Gerçekleşmesi gereken bir sözdü bu.\""},{"n":6,"t":"\"Sonra onları yenme olanağını size vereceğiz, sizi mal ve soy ile destekleyerek savaşçılarınızı çoğaltacağız.\""},{"n":7,"t":"\"İyi davranırsanız, kendiniz için iyi davranmış olursunuz. Kötü davranırsanız yine kendiniz içindir. Sonuncusunun zamanı gelince, sizi kedere boğacaklar ve ilk defa girdikleri gibi mescide girecekler. Ele geçirdiklerini yerle bir edecekler.\""},{"n":8,"t":"Efendiniz size rahmet eder. Siz dönerseniz biz de döneriz. Cehennemi kafirler için kuşatıcı kıldık."},{"n":9,"t":"Bu Kuran en iyi yola ulaştırır ve erdemli davranan müminleri büyük bir ödülle müjdeler."},{"n":10,"t":"Ahireti onaylamayanlara gelince, onlar için acı bir azap hazırlamış bulunuyoruz."},{"n":11,"t":"İnsan, iyi bir şey için dua ettiğini sanırken aslında kötü bir şey için dua eder. İnsan çok acelecidir."},{"n":12,"t":"Geceyi ve gündüzü iki ayet kıldık. Efendinizin nimetlerini arayasınız ve yılların hesabını bilesiniz diye gecenin ayetini sildik, gündüzün ayetini aydınlık kıldık. Biz her şeyi ayrıntısıyla açıklarız."},{"n":13,"t":"Her insanın kaderini kendi kişisel seçimine bağlamışızdır. Diriliş gününde, kendisi için bir kayıt çıkarıp yayımlarız."},{"n":14,"t":"Kaydını oku. Bugün hesap görücü olarak sen kendine yetersin."},{"n":15,"t":"Kim doğru yola gelirse kendisi için yola gelmiş bulunur. Kim saparsa kendi aleyhine sapar. Hiç kimse başkasının yükünü çekmez. Biz bir elçi göndermeden hiç kimseyi cezalandırmayız."},{"n":16,"t":"Biz bir toplumu yok etmek istediğimiz zaman onun ileri gelen varlıklılarının orada kötülük yapmasına izin veririz. Böylece o topluma verilmiş söz gerçekleşir ve onu yerle bir ederiz."},{"n":17,"t":"Nuh’tan sonra nice toplumları yok ettik. Kullarının günahlarını haber alıcı ve görücü olarak Efendin yeter."},{"n":18,"t":"Kim bu geçici dünyayı isterse, orada istediğimize dilediğimiz kadar veririz. Ancak daha sonra onu, kınanmış ve kovulmuş olarak cehenneme mahkûm ederiz."},{"n":19,"t":"Kim ahireti seçer ve mümin olarak gereken çabayı gösterirse, işte onların çabası takdir edilir."},{"n":20,"t":"Hepsine, onlara da bunlara da, Efendinin nimetlerinden ulaştırırız. Efendinin nimetleri sınırlanmamıştır."},{"n":21,"t":"İnsanları birbirinden nasıl üstün kıldığımıza dikkat et. Ahiretin dereceleri ve üstünlükleri daha büyüktür."},{"n":22,"t":"ALLAH ile birlikte başka tanrı edinme, yoksa kınanmış ve yalnız bırakılmış olarak oturup kalırsın."},{"n":23,"t":"Efendin, yalnız kendisine hizmet etmenizi, anaya ve babaya karşı iyi davranmanızı emretti. Onlardan biri veya ikisi yanında yaşlanırsa onlara \"Öf\" bile deme ve onları azarlama. Onlarla güzel bir biçimde konuş."},{"n":24,"t":"Sevip kollayarak onlar için alçak gönü kanadını ger ve de ki: \"Efendim, beni küçükken yetiştirdikleri gibi sen de onlara acı.\""},{"n":25,"t":"Efendiniz içinizdekileri çok iyi bilir. Erdemli davranırsanız, elbette O, tövbe edenleri bağışlayandır."},{"n":26,"t":"Akrabalara haklarını ver. İhtiyaç sahiplerine ve yolcuya da… Ancak saçıp savurma."},{"n":27,"t":"Kuşkusuz, saçıp savuranlar sapkınların dostlarıdır ve sapkın Efendisine karşı nankördür."},{"n":28,"t":"Efendinden umduğun bir rahmeti elde etmek için onlardan yüz çevirmek zorunda kalırsan onlara yumuşak söz söyle."},{"n":29,"t":"Elini boynuna bağlama ve tümüyle de açma yoksa pişman olur, üzülürsün."},{"n":30,"t":"Efendin, dilediğine rızkını bol verir veya kısar. Kuşkusuz O, kullarından haberdardır, onları görendir."},{"n":31,"t":"Doğan çocuklarınızı fakirlik korkusuyla öldürmeyin. Sizi de onları da biz rızıklandırıyoruz. Onları öldürmek, büyük bir suçtur."},{"n":32,"t":"Zinaya yaklaşmayın; çünkü o büyük bir günah ve kötü bir davranıştır."},{"n":33,"t":"ALLAH’ın yasakladığı canı haksız yere öldürmeyin. Kim haksızlığa uğrayarak öldürülürse onun mirasçılarına yetki vermişizdir. İntikam duygusuyla öldürmede sınırı aşmasın; zira kendisine yardım edilmiştir."},{"n":34,"t":"Öksüzlerin malına, erginlik çağına ulaşıncaya kadar dokunmayın; yararlarına olursa başka. Sözleşmeleri yerine getiriniz; zira sözleşmeler sorumluluktur."},{"n":35,"t":"Ölçtüğünüz zaman ölçüyü tam yapın ve doğru teraziyle tartın. Elbette bu daha iyidir ve sonucu daha güzeldir."},{"n":36,"t":"Bilmediğin bir şeye ardına körü körüne düşme, çünkü işitme, görme duyusu ve beyin, hepsi ondan sorumludur."},{"n":37,"t":"Yeryüzünde kibirli kibirli dolaşma sen ne yeri delebilirsin ne de dağlar kadar boylu olabilirsin."},{"n":38,"t":"Tüm bunlar, Efendin tarafından hoş görülmeyen kötü davranışlardır."},{"n":39,"t":"Bunlar, Efendinin sana vahyettiği hikmetlerdendir. ALLAH ile birlikte başka tanrı edinme; aksi taktirde kınanmış ve kovulmuş olarak cehenneme atılırsın."},{"n":40,"t":"Efendiniz oğulları size seçti de kendisine meleklerden kızlar mı edindi? Çok büyük bir iddiada bulunuyorsunuz."},{"n":41,"t":"Biz, öğüt almaları için Kuran’da açıkladık. Ne var ki bu, sadece onların nefretini arttırır."},{"n":42,"t":"De ki: \"İleri sürüdükleri gibi beraberinde başka tanrılar olsaydı, onlar da Egemenliğin Sahibine doğru yol ararlardı.\""},{"n":43,"t":"O, onların dediklerinden uzaktır ve çok yücedir."},{"n":44,"t":"Yedi gök, yer ve onların içindekiler O’nu yücelterek anarlar. Hiçbir şey yoktur ki O’nu överek ve yücelterek anmasın; ama siz onların anışlarını anlamazsınız. O Şefkatlidir, Bağışlayandır."},{"n":45,"t":"Kuran okuduğun zaman, seninle ahireti onaylamayanlar arasına görünmez bir engel yerleştiririz."},{"n":46,"t":"Ve onu anlamalarını engellemek için kalplerine kabuklar, kulaklarına da ağırlık koyarız. Efendini yalnızca Kuran’da andığın zaman nefretle geriye dönerler."},{"n":47,"t":"Seni dinlerlerken nasıl işittiklerini ve kendi aralarında konuşurlarken zalimlerin, \"Siz sadece büyülenmiş bir adamı izliyorsunuz\" dediklerini iyi biliyoruz."},{"n":48,"t":"Dikkat et, seni nasıl da tanımlayarak sapıyorlar ve artık bir daha yol bulamazlar."},{"n":49,"t":"Dediler ki: \"Kemik ve ufak parçalar haline geldikten sonra mı yeni bir yaratılışla diriltileceğiz?!\""},{"n":50,"t":"De ki: \"İsterse taş veya demire dönüşün\""},{"n":51,"t":"\"Yahut sizce imkansız görünen bir biçime girin, fark etmez.\" Buna karşılık, \"Bizi kim geri döndürecek?\" diyecekler. De ki: \"Sizi ilk önce kim yarattıysa O!\" Sonra başlarını sallayıp, \"Peki ne zaman?\" diyecekler. De ki: \"Belki düşündüğünüzden daha yakın…\""},{"n":52,"t":"Sizi çağıracağı gün, siz ona övgüyle karşılık verirsiniz ve çok kısa bir süre kalmış olduğunuzu anlarsınız."},{"n":53,"t":"Kullarıma söyle: En güzel biçimde konuşup tartışsınlar. Çünkü sapkın aralarına girer. Sapkın, insanın apaçık düşmanıdır."},{"n":54,"t":"Efendiniz sizi daha iyi bilir. Dilerse size acır, dilerse sizi cezalandırır. Seni onlara avukatlık yapasın diye göndermedik."},{"n":55,"t":"Efendin göklerdekileri ve yerdekileri en iyi bilendir. Peygamberlerden bir kısmını diğerlerine üstün kıldık. Örneğin; Davud’a Zebur’u verdik."},{"n":56,"t":"De ki: \"O’nun dışında iddia ettiklerinizi çağırın bakalım, onlar sizden ne sıkıntıyı kaldırabilirler ne de önleyebilirler.\""},{"n":57,"t":"Onların çağırdıkları kişiler bile Rab’lerine yaklaşmak için yol ararlar. O’nun rahmetini umar, cezasından korkarlar. Efendinin cezası sakınılacak bir şeydir."},{"n":58,"t":"Hiçbir ülke yok ki diriliş gününden önce onu yok edecek veya şiddetli bir biçimde cezalandıracak olmayalım. Bu, kitapta yazılmış bulunuyor."},{"n":59,"t":"Öncekilerin onları yalanlamış olması bizi ayetler göndermekten alıkoymadı. Örneğin; Semud’a deveyi açıkça vermiştik. Fakat ona haksızlık ettiler. Biz ayetleri yalnızca uyarı amacıyla göndeririz."},{"n":60,"t":"Efendinin insanları kuşatmış olduğunu sana bildirmiştik. Fakat sana gösterdiğimiz görüntü ile ve Kuran’da lanetlenen ağaçla sadece insanları denedik. Biz onları uyarırız, ancak bu, onların azgınlığına büyük bir katkıda bulunmaktan başka sonuç vermiyor."},{"n":61,"t":"Denetçilere, \"Adem’e secde edin!\" dediğimizde, İblis hariç hepsi secde ettiler. \"Balçıktan yarattığına mı secde edecekmişim?\" dedi."},{"n":62,"t":"\"Benden üstün kıldığın şu kişiyi görüyor musun? Beni diriliş gününe kadar geciktirirsen, onun soyunu, pek azı hariç sahiplenip perişan edeceğim.\" dedi."},{"n":63,"t":"Dedi ki: \"Onlardan seni izleyenler ile birlikte git. Tam size göre bir ceza olan cehenneme kadar yolunuz var.\""},{"n":64,"t":"\"Onlardan gücünün yettiğini sesinle yerinden oynat, onlara karşı tüm gücünü ve adamlarını seferber et, paralarının ve çocuklarının bir bölümüne ortak ol ve onlara umut ver.\" Sapkın, onlara ancak sahte umutlar verir."},{"n":65,"t":"\"Kullarıma gelince, senin onlar üzerine hiçbir gücün yoktur.\" Koruyucu olarak Efendin yeter."},{"n":66,"t":"Efendiniz, nimetlerini aramanız için gemileri okyanuslarda yüzdürendir. O size karşı Rahim’dir."},{"n":67,"t":"Okyanusta size bir sıkıntı dokunursa O’ndan başka çağırmakta olduklarınız kaybolur. Fakat sizi kurtarıp karaya çıkarınca, dönersiniz. İnsan nankördür."},{"n":68,"t":"Kıyıyı üstünüze çevirip sizi yutmasından, yahut üzerinize şiddetli bir kasırga yollamasından emin misiniz? Sonra hiçbir koruyucu da bulamazsınız."},{"n":69,"t":"Sizi tekrar denize göndermeyeceğinden ve üstünüze kırıp geçiren bir fırtına salarak inkârınızdan dolayı sizi boğmayacağından emin misiniz? Sonra sizin için peşinize düşecek birini de bulamazsınız."},{"n":70,"t":"Ademoğullarına onur verdik. Onları karada ve denizde taşıdık. Onları güzel nimetlerle besledik. Yarattıklarımızın birçoğundan daha üstün kıldık."},{"n":71,"t":"Her bir halkı önderleriyle birlikte çağırdığımız gün, kitabı sağından verilenler kitaplarını okurlar ve en ufak bir haksızlığa uğratılmazlar."},{"n":72,"t":"Bu dünyada kör olanlara gelince, onlar ahirette de kördür ve yol bakımından daha da sapıktır."},{"n":73,"t":"Başka bir şeyi uydurup bize yakıştırman için nerdeyse seni sana vahyettiğimizden ayırıp saptıracaklardı. İşte o zaman seni dost edineceklerdi."},{"n":74,"t":"Seni sağlamlaştırmasaydık, onlara neredeyse bir parça meyledecektin."},{"n":75,"t":"O zaman da hayatın ve ölümün azabını katlayarak sana tattırırdık. Sonra bize karşı bir yardımcı da bulamazdın."},{"n":76,"t":"Seni ülkeden çıkarmak için neredeyse seni zorla sürecekler. Bu taktirde senden sonra onlar da fazla kalmayacaklar."},{"n":77,"t":"Senden önce gönderdiğimiz tüm elçiler için öngördüğümüz yasa (sünnet) budur. Yasamızda herhangi bir değişiklik göremezsin."},{"n":78,"t":"Güneşin kaymasından gecenin kararmasına kadar namazı gözet. Sabah okumasını da (Kuran) da gözet. Sabahleyin okunan (Kuran) tanık olunur."},{"n":79,"t":"Fazladan iyi iş olarak geceleyin düşünceye dal ki Efendin seni onurlu bir makama yükseltsin."},{"n":80,"t":"Ve de ki: \"Efendim, girişimlerimi ve vazgeçişlerimi doğru ve tutarlı kıl. Katından beni destekleyecek bir güç ver.\""},{"n":81,"t":"Ve şunu bildir ki: \"Gerçek gelmiş, yanlış ise ortadan kalkmıştır. Zaten yanlış, yok olmaya mahkûmdur.\""},{"n":82,"t":"Kuran’ı, gerçeği onaylayanlar için bir şifa ve rahmet olarak indirdik. Zalimlerin ise ancak zararını arttırır."},{"n":83,"t":"İnsana nimet verdiğimiz zaman, yüz çevirip yan çizer. Kendisine kötülük dokununca da umutsuzluğa düşer."},{"n":84,"t":"De ki: \"Herkes onayladığı tezlere göre davranır. Kimin daha doğru yolda olduğunu ise Efendim daha iyi bilir.\""},{"n":85,"t":"Sana ruhtan sorarlar. De ki: \"Ruh Efendimden gelir. Size verilen bilgi ise pek azdır.\""},{"n":86,"t":"Dilesek sana vahyettiğimizi geri alırız ve bize karşı herhangi bir koruyucu da bulamazsın."},{"n":87,"t":"Ancak Efendinin rahmeti var… O’nun sana olan nimeti büyüktür."},{"n":88,"t":"De ki: \"Tüm insanlar ve cinler bu Kuran’ın bir benzerini oluşturmak amacıyla toplansalar ve bu konuda birbirlerine destek olsalar bile onun bir benzerini oluşturamazlar.\""},{"n":89,"t":"Biz bu Kuran’da her türlü örneği verdik, ne var ki halkın çoğunluğu inkârda direniyor."},{"n":90,"t":"Dediler ki: \"Yerden bize bir kaynak fışkırtmadıkça seni onaylamayız.\""},{"n":91,"t":"\"Veya hurma ve üzüm bahçelerin olup aralarında ırmaklar fışkırtmalısın.\""},{"n":92,"t":"\"Veya ileri sürdüğün gibi gökten üzerimize parçalar düşürmeli, yahut ALLAH’ı ve melekleri karşımıza getirmelisin.\""},{"n":93,"t":"\"Ya da altın bir evin olmalı veya göğe yükselmelisin. Yükselsen bile okuyacağımız bir kitabı üzerimize indirmedikçe onu onaylamayız.\" De ki: \"Efendim yücedir. Ben elçi olan bir insandan başka bir şey miyim ki!\""},{"n":94,"t":"Kendilerine hidayet geldiğinde, halk: \"ALLAH bir insanı mı elçi olarak gönderdi\" diyerek onaylamadı."},{"n":95,"t":"De ki: \"Yeryüzünde yerleşip dolaşan melekler olsaydı onlara gökten bir meleği elçi gönderirdik.\""},{"n":96,"t":"De ki: \"Benimle sizin aranızda ALLAH tanıktır. O, kullarından haber alır, görür.\""},{"n":97,"t":"ALLAH kime yol gösterirse o kişi doğruyu bulmuştur. Kimi de saptırırsa onlar için O’ndan başka bir koruyucu da bulamazsın. Diriliş günü de onları kör, dilsiz ve sağır olarak yaka paça toplarız. Cehennemdir yerleri. Soğudukça alevlerini arttırırız."},{"n":98,"t":"Ayetlerimizi yalanladıkları, \"Kemik ve ufalanmış toprak olduktan sonra biz mi yeni bir yaratılışla diriltileceğiz!\" dedikleri için cezaları budur."},{"n":99,"t":"Gökleri ve yeri yaratan ALLAH’ın onların bir benzerini tekrar yaratmaya gücü yeteceğini düşünmüyorlar mı? Nitekim onlar için belli ve kesin bir süre koymuştur. Zalimler hâlâ inkâr ediyorlar."},{"n":100,"t":"De ki: \"Efendimin rahmet hazineleri sizin elinizde olsaydı, harcamakla tükenir korkusuyla onları tutacaktınız. İnsan cimridir.\""},{"n":101,"t":"Musa’ya apaçık dokuz mucize verdik. Dilersen İsrailoğullarına sor. Onlara gittiğinde, Firavun ona, \"Musa, senin büyülenmiş olduğunu sanıyorum\" demişti."},{"n":102,"t":"\"Göklerin ve yerin Rabbi’nden başkasının bu delilleri indirmediğini iyi biliyorsun. Firavun, seni mahvolmuş biri olarak görüyorum!\""},{"n":103,"t":"Onları yeryüzünden kaldırmak isteyince de onu ve beraberindekileri topluca suda boğduk."},{"n":104,"t":"Ondan sonra İsrailoğullarına, \"Bu ülkede yerleşin. Verilen son söz geldiğinde sizi bir araya toplayacağız\" dedik."},{"n":105,"t":"Gerçekten onu biz indirdik ve o gerçek ile indi. Seni de ancak bir müjdeleyici ve uyarıcı olarak gönderdik."},{"n":106,"t":"Uzun bir zaman dilimi içerisinde halka okuman için ayırdığımız bir Kuran’dır. Onu topluca indirmiştik."},{"n":107,"t":"De ki: \"Onu ister onaylayın, ister onaylamayın!\" Daha önce kendilerine bilgi verilmiş olanlara okunduğu zaman secde ederek yüzüstü kapanırlar."},{"n":108,"t":"\"Efendimiz yücedir. Efendimizin sözü gerçekleşmiştir\" derler."},{"n":109,"t":"Ağlayarak yüzüstü kapanırlar; çünkü onların saygısını arttırır o."},{"n":110,"t":"De ki: \"İster ALLAH diye çağırın, ister Rahman diye çağırın. Hangisiyle çağırırsanız, tüm güzel isimler O’nundur. \" Namazda ne ilan et, ne de gizle; ikisinin arasında bir yol tut."},{"n":111,"t":"Ve de ki: \"Övgü, ALLAH’adır. O çocuk edinmemiştir, yönetimde ortağı ve zayıflıktan ötürü de bir yardımcısı yoktur.\" O’nu alabildiğine Yücelt."}]},{"id":18,"name":"Kehf Suresi","verses":[{"n":1,"t":"ALLAH’a övgü olsun, kuluna kitabı indirmiş ve onda hiçbir eğriliğe yer vermemiştir."},{"n":2,"t":"Dosdoğru... O’ndan gelecek şiddetli bir cezaya karşı uyarsın ve erdemli davranan müminlere kendileri için güzel bir ödülü müjdelesin."},{"n":3,"t":"Ki orada sürekli kalacaklardır."},{"n":4,"t":"Ve \"ALLAH çocuk edindi\" diyenleri de uyarsın."},{"n":5,"t":"Ne onların, ne de atalarının bu konuda bir bilgileri yoktur. Ağızlarından ne büyük bir söz çıkıyor! Yalandan başka şey söylemiyorlar."},{"n":6,"t":"Bu hadisi onaylamazlarsa onların ardından kendini sorumlu tutarak suçlayıp üzülecek misin?"},{"n":7,"t":"Biz, kimlerin erdemli davranacağını sınamak için, üzerindeki maddelerle yeryüzünü süsledik."},{"n":8,"t":"Ve elbette biz onun üzerinde bulunanları çorak bir toprak haline dönüştüreceğiz."},{"n":9,"t":"Mağaradakilerin ve onlarla ilgili rakamların ilginç kanıtlarımızdan başka bir şey olduğunu mu sandın?"},{"n":10,"t":"Gençler mağaraya sığındıklarında, \"Efendimiz bize merhametini yağdır ve bu durumdan bize bir kurtuluş yolu göster\" demişlerdi."},{"n":11,"t":"Bunun üzerine sayılı yıllar süresince mağarada kulaklarını kapadık."},{"n":12,"t":"Sonra onları dirilttik ki onların orada kalış sürelerini hangi grubun daha iyi hesaplayacağını bilelim."},{"n":13,"t":"Onların haberini sana gerçek olarak anlatıyoruz. Onlar Rab’lerini onaylamış gençlerdi. Onların hidayetini arttırmıştık."},{"n":14,"t":"Kalktıklarında kalplerini sağlamlaştırmıştık. \"Efendimiz, göklerin ve yerin Rabbidir. O’ndan başka tanrı edinmeyeceğiz. Yoksa, yanlış söz söylemiş oluruz.\""},{"n":15,"t":"\"Şu halkımız O’ndan başkasını tanrılar edindi. Onların tanrı olduğunu açık bir delille kanıtlamaları gerekmez miydi? ALLAH’a karşı yalan uydurandan daha zalim kim olabilir?\""},{"n":16,"t":"\"Madem ki siz onlardan ve Allah’ın dışında hizmet ettiklerinden ayrıldınız, öyleyse mağaraya sığının. Olur ki Efendiniz size rahmetini yağdırır, işinizde size olumlu sonuç hazırlar.\""},{"n":17,"t":"Tan ağardığında, onlar mağara boşluğunda iken, mağaralarının üzerinden Güneşin sağa doğru hareket ettiğini, battığı zaman da onları yalayıp sola doğru kaydığını görürdün. Bu, ALLAH’ın işaretlerindendir. ALLAH kime yol gösterirse o kişi doğruyu bulmuştur; kimi de saptırırsa onun için aydınlatıcı bir dost bulamazsın."},{"n":18,"t":"Uykuda olmalarına rağmen onları uyanık sanırsın. Onları sağa ve sola doğru çeviririz. Köpekleri de kollarını eşikte uzatmıştır. Onlara baksaydın onlardan dönüp kaçardın ve onlardan dolayı korkuyla dolardın."},{"n":19,"t":"Böylece onları uyandırdık ki birbirlerine sorsunlar. Onlardan biri, \"Ne kadar kaldınız?\" diye sordu. \"Birgün, yahut günün bir parçası kadar kaldık\" dediler. \"Ne kadar kaldığınızı Efendiniz daha iyi bilir. Birinizi şu para ile şehre gönderelim de en temiz ve leziz yiyecekleri seçip size bir azık getirsin. Dikkatli davranarak kimsenin dikkatini üstüne çekmesin\" diye eklediler."},{"n":20,"t":"\"Onlar sizi görseler sizi taşlarlar/kovarlar veya sizi zorla kendi dinlerine döndürürler ki bu durumda asla başarıya ulaşamazsınız.\""},{"n":21,"t":"Böylece onları buldurduk ki ALLAH’ın sözünün gerçek olduğunu öğrensinler ve o an konusunda da kuşkuları kalmasın. Halk onların durumunu aralarında tartışırken bir kısmı, \"Onların üzerine bir bina yapın\" dedi. Rab’leri onları daha iyi bilir. Onların durumuna karar verme yetkisini ellerine geçirenler, \"Onların üstüne bir mescid yapacağız\" dediler."},{"n":22,"t":"Tahminde bulunanların bazıları, \"Onlar üçtür, dördüncüleri köpekleridir\" derken diğerleri de, \"Beştir, altıncıları köpekleridir\" diyecekler. Başkaları ise, \"Yedidir, sekizincileri köpekleridir\" diye bilinmeyen hakkında atıp tutacaklar. De ki: \"Onların sayısını en iyi bilen Efendimdir.\" Onları bilen azdır. Onlarla yüzeysel olması hariç tartışmaya girme ve onlardan hiç kimseye de bu konuyu danışma."},{"n":23,"t":"Hiçbir şey için, \"Bunu yarın yapacağım\" deme."},{"n":24,"t":"Ancak, \"ALLAH dilerse (inşallah)\" diyerek Efendini an. Unutursan, o zaman da, \"Belki Efendim bir dahaki sefere beni daha iyiye ulaştırır\" de."},{"n":25,"t":"Mağaralarında üç yüz yıl kalıp dokuz arttırdılar."},{"n":26,"t":"\"Onların orada ne kadar kaldıklarını ALLAH daha iyi bilir\" de. Göklerin ve yerin tüm gizemleri O’nundur. O ne güzel Görendir! O ne güzel İşitendir! Onların O’ndan başka bir yardımcısı yoktur. O, hükmüne kimseyi ortak etmez."},{"n":27,"t":"Efendinin kitabından sana vahyedileni oku. Kelimelerini hiçbir şey değiştirip kaldıramaz ve O’ndan başka bir sığınak da bulamazsın."},{"n":28,"t":"Rab’lerinin rızasını dileyerek sabah akşam hizmet edenlerle birlikte olmaya çalış. Dünya hayatının çekici materyallerini arzu edip de gözlerini onlardan ayırma. Kalbini mesajımızdan gafil kıldığımız ve hevesine uyarak işlerini karıştıran kimseleri izleme."},{"n":29,"t":"De ki: \"Bu gerçek senin Efendindendir.\" Dileyen onaylasın, dileyen inkâr etsin. Biz zalimler için onları çepeçevre saracak bir ateş hazırladık. Onlar her ne zaman feryad ederek yardım isteseler, derişik asit gibi yüzleri haşlayan bir su sunulur. Ne kötü bir içecek, ne kötü bir son!"},{"n":30,"t":"Gerçeği onaylayıp erdemli davrananlara gelince, elbette biz iyi işlerde bulunanların ödülünü yitirmeyiz."},{"n":31,"t":"Onlar için, içlerinden ırmaklar akan Adn bahçeleri vardır. Orada altından bileziklerle süslenirler, ipek ve kadifeden dokunmuş yeşil elbiseler giyerler. Orada koltuklar üzerine yaslanırlar. Ne güzel bir ödül ve ne güzel bir durak…"},{"n":32,"t":"Onlara iki adamın örneğini ver: Birisine, etrafını hurma ağaçlarıyla çevirip aralarına başka ekinler bitirdiğimiz iki üzüm bahçesi vermiştik."},{"n":33,"t":"Aralarına bir ırmak yerleştirdiğimiz için, her iki bağ da yemişini hiç esirgemeden cömertçe vermişti."},{"n":34,"t":"Artık bir ürüne sahipti! Nitekim, sohbet ettiği arkadaşına, \"Ben senden daha zenginim ve daha fazla ere sahibim\" dedi."},{"n":35,"t":"Böylece nefsine zulmederek bağına girdi ve, \"Bunun yok olacağını hiç sanmıyorum\" dedi."},{"n":36,"t":"\"O anın da geleceğini sanmıyorum. Efendime döndürülürsem de orada daha iyisini bulurum.\""},{"n":37,"t":"Kendisiyle konuşan arkadaşı ona dedi ki: \"Seni topraktan, ufak bir damladan yaratıp seni bir adam biçimine sokan Efendini mi inkâr ediyorsun?\""},{"n":38,"t":"\"Bana gelince… O ALLAH benim Efendimdir, ben Efendime hiçbir şeyi ortak koşmam.\""},{"n":39,"t":"\"Bağına girerken, ’Bu ALLAH’ın bir bağışıdır (maşallah), kuvvet ancak ALLAH iledir (la havle vela kuvvete illa billah)’ demen gerekmez miydi? Senden daha az para ve çocuğa sahip olduğumu görüyor olabilirsin ama,\""},{"n":40,"t":"\"Efendim, belki senin bahçenden daha iyisini bana verir ve olur ki bahçene gökten bir felaket gönderir de kupkuru bir toprağa dönüşür."},{"n":41,"t":"\"Yahut suyu dibe çöker de bir daha su bulamazsın.\""},{"n":42,"t":"Derken, ürünü yok edildi. Çardakları üzerine yığılmış olan bağına verdiği emekten ötürü matem tutmaya ve \"Keşke Efendime ortak koşmasaydım\" demeye başladı."},{"n":43,"t":"ALLAH’tan aşağı kendisine yardım edecek bir destek bulamadı. Kendini de kurtaramadı."},{"n":44,"t":"O an, otorite tümüyle gerçek olan ALLAH’ındır. O, en iyi ödülü ve en iyi sonucu verendir."},{"n":45,"t":"Onlara dünya hayatının örneği olarak, gökten indirdiğimiz suyla beslenen ve sonra rüzgarın savurduğu çer çöpe dönen yeryüzünün bitkisini ver. ALLAH her şeye gücü yetendir."},{"n":46,"t":"Para ve çocuklar bu dünya hayatının çekici materyalleridir. Ama, sürekli kalacak erdemli işler, Efendinin katında bir ödül ve umut olarak çok daha iyidir."},{"n":47,"t":"Dağları silip götürdüğümüz ve yeri çıplak bıraktığımız gün onları toplarız; bir tanesini bile bırakmadan."},{"n":48,"t":"Ve sırayla Efendine sunulurlar. Bize, ilk başta sizi nasıl yarattıysak öyle gelirsiniz. Oysa, böyle bir buluşmayı gerçekleştirmeyeceğimizi ileri sürüyordunuz."},{"n":49,"t":"Kitap ortaya konmuştur. Suçluların onun içeriğinden korkuya kapıldığını ve \"Bize yazıklar olsun, meğer bu kitap küçük büyük hiçbir şeyi bırakmayıp saymış\" dediklerini görürsün. Yaptıkları her şeyi önlerinde hazır bulmuşlardır. Efendin hiç kimseye haksızlık etmez."},{"n":50,"t":"Denetçilere, \"Adem’e secde edin!\" dediğimiz zaman hepsi secde ettiler; yalnız İblis hariç. Efendisinin emrine karşı geldiği için cinlerden oldu. Beni bırakıp onu ve soyunu mu dostlar ediniyorsunuz? Oysa onlar, sizin düşmanlarınızdır. Zalimler için bu ne kötü bir değişmedir."},{"n":51,"t":"Onları ne göklerin ve yerin yaratılışına, ne de kendilerinin yaratılışına tanık yapmadım. Saptıranları hiçbir zaman egemenliğimde görevlendirmem."},{"n":52,"t":"\"Ortaklarım olduğunu ileri sürdüğünüz kişileri çağırın\" diye emrettiği gün, onları çağırırlar da onlar kendilerine karşılık vermezler. Onların arasına bir öfke ve nefret uçurumu koymuşuzdur."},{"n":53,"t":"Suçlular ateşi gördüler ve içine düşeceklerini anladılar; ondan kaçacak bir yer de bulamadılar."},{"n":54,"t":"Biz bu Kuran’da halk için her türlü örneği verdik. Fakat insan tartışmaya çok düşkündür."},{"n":55,"t":"Kendilerine yol gösterici geldiğinde, halkı gerçeği onaylamaktan ve Rab’lerinden bağışlanma dilemekten alıkoyan şey, öncekilerin yasalarının (sünnetinin, benzer uygulamanın, örneğin, geçmiş toplumlara verilen mucizelerin bir benzerinin) kendilerine de gelmesini veya azabın açıkça karşılarına gelmesini dilemeleridir."},{"n":56,"t":"Biz, elçileri ancak müjdeleyiciler ve uyarıcılar olarak gönderdik. Kafirler, gerçeği sahte ve yanlış ile ortadan kaldırmak için gayret ediyor. Ayetlerimi (işaret ve mucizeleri) ve uyarıldıkları şeyleri alaya aldılar."},{"n":57,"t":"Efendisinin ayet ve mucizeleri kendisine hatırlatıldığı halde, yaptıklarını unutarak ondan yüz çevirenden daha zalim kim olabilir? Kalplerine, onu (Kuran’ı) anlamalarına engel olacak bir örtü, kulaklarına da bir ağırlık koymuşuzdur. Onları hidayete ne kadar çağırırsan çağır, onlar asla doğruyu bulamaz."},{"n":58,"t":"Efendin Bağışlayandır, Merhamet Sahibidir. Yaptıklarıyla hemen onları hesaba çekse onlar için azabı çabuklaştırmış olurdu. Ancak, onlara belirli bir süre verir de onun ötesine kaçamazlar."},{"n":59,"t":"İşte, haksızlık ettikleri için yok ettiğimiz toplumlar… Hepsinin helakı için belli bir süre belirlemiştik."},{"n":60,"t":"Musa, genç yoldaşına, \"Yıllarca yürümeyi gerektirse de iki denizin birleştiği yere varmadan dinlenmeyeceğim\" demişti."},{"n":61,"t":"İki denizin birleştiği yere vardıklarında, balıklarını unuttular. Sinsice kayıp denizin yolunu tuttu."},{"n":62,"t":"Orayı geçtiklerinde, genç yoldaşına, \"Yemeğimizi getir. Bu yolculuğumuz bizi gerçekten yordu\" dedi."},{"n":63,"t":"Dedi ki: \"Bak gördün mü, o kayalığa vardığımızda balığı unuttum. Onu bana sapkın unutturdu ve böylece denizde yolunu tutup gitti. Ne kadar da ilginç!\""},{"n":64,"t":"\"İşte aradığımız yer orası idi\" dedi ve böylece izleri üzerinde geri döndüler."},{"n":65,"t":"Katımızdan kendisine rahmet verdiğimiz ve bilgimizden öğrettiğimiz kullarımızdan bir kulu buldular."},{"n":66,"t":"Musa ona, \"Sana öğretilenden, aydınlatıcı prensipleri bana öğretmen için seni izleyebilir miyim\" deyince,"},{"n":67,"t":"\"Sen benimle birlikte olmaya dayanamazsın\" dedi,"},{"n":68,"t":"\"Bilmediğin bir şeye nasıl dayanabilirsin?\""},{"n":69,"t":"Dedi: \"ALLAH dilerse beni sabırlı bulacaksın; sana hiçbir işte karşı gelmeyeceğim.\""},{"n":70,"t":"Dedi: \"Bana uyacaksan, ben sana anlatmadıkça bana hiçbir şey hakkında soru sorma.\""},{"n":71,"t":"Böylece yürüdüler. Nihayet gemiye bindiklerinde, onda delik açtı. \"Halkını boğmak için mi gemide delik açtın? Gerçekten müthiş bir iş yaptın\" dedi."},{"n":72,"t":"\"Bana dayanamayacağını sana söylememiş miydim\" diye karşılık verdi."},{"n":73,"t":"\"Unuttuğum şeyden dolayı beni kınama; bu işimde bana güçlük çıkarma\" dedi."},{"n":74,"t":"Böylece yürüdüler. Nihayet bir delikanlıya rastladıklarında onu hemen öldürdü. \"Kimseye kıymamış suçsuz bir kimseyi niçin öldürdün? Sen, çok kötü bir iş yaptın\" dedi."},{"n":75,"t":"\"Bana dayanamayacağını sana söylememiş miydim?\" diye tekrarladı."},{"n":76,"t":"\"Sana daha başka bir şey sorarsam o zaman artık benimle arkadaş olma. Benden yeterli özür dinledin\" dedi."},{"n":77,"t":"Böylece yürüdüler. Nihayet bir köy halkına rastladılar ve halkından yiyecek istediler. Fakat onları misafir kabul etmeyi reddettiler. Derken orada yıkılmak isteyen bir duvar buldular, hemen onu doğrultuverdi. \"Dileseydin, o işten dolayı bir ücret alabilirdin\" dedi."},{"n":78,"t":"Dedi ki: \"İşte bu, benim seninle olan beraberliğimin sonudur. Dayanamadığın şeylerin açıklamasını ise sana bildireceğim.\""},{"n":79,"t":"\"Gemi, denizde çalışan yoksullara aitti. Gemiyi kusurlu yapmak istedim; zira peşlerinde, tüm gemileri zorla ele geçiren bir kral vardı.\""},{"n":80,"t":"\"Çocuğa gelince, ana babası iki gerçeği onaylayan kişi idi. Taşkınlık ve nankörlük ile o ikisine yük olmasından endişelendik.\""},{"n":81,"t":"\"İstedik ki Rab’leri onun yerine kendilerine ondan daha temiz ve merhametli birini versin.\""},{"n":82,"t":"\"Duvar ise kentteki iki öksüze aitti. Duvarın altında onlara ait bir hazine vardı. Babaları da erdemli birisiydi. Efendin diledi ki onlar büyüyüp tam güçlerine kavuştuktan sonra Efendinden bir rahmet olarak hazinelerini ortaya çıkarsınlar. Bunları kendi irademle yapmadım. İşte bunlar, dayanamadığın şeylerin açıklamasıdır.\""},{"n":83,"t":"Sana, iki nesil kadar yönetime sahip olan kişiden sorarlar. De ki: \"Size ondan bir öğüt ve hatırlatma aktaracağım.\""},{"n":84,"t":"Biz ona yeryüzünde yönetim gücünü ve her türlü imkanı verdik."},{"n":85,"t":"Nitekim, o bir yol izledi."},{"n":86,"t":"Uzak batıya varınca güneşi büyük bir okyanusta batar buldu ve orada bir topluluk ile karşılaştı. \"Ey İki Nesil Sahibi, dilersen onları cezalandır, dilersen onlara iyi davran\" dedik."},{"n":87,"t":"Dedi ki, \"Kim haksızlık ederse onu cezalandıracağız, Efendisine döndürülünce de O onu görülmemiş bir cezaya çarpacaktır.\""},{"n":88,"t":"\"Gerçeği onaylayıp erdemli davranana gelince, ona güzel bir ödül vardır. Ona kolaylık göstereceğiz.\""},{"n":89,"t":"Sonra bir yol tuttu."},{"n":90,"t":"Uzak doğuya varınca, güneşi, kendilerini güneşten koruyacak herhangi bir şeye sahip olmayan bir topluluk üzerine doğar buldu."},{"n":91,"t":"İşte böyle… Onun her bulduğunu tamamıyla biliyorduk."},{"n":92,"t":"Sonra yine bir yol tuttu."},{"n":93,"t":"İki seddin arasına varınca, ötesinde, nerdeyse söz anlamayan bir topluluk buldu."},{"n":94,"t":"Dediler ki, \"Ey İki Nesle Sahip Olan (Zül Karneyn), Yecuc ve Mecuc yeryüzünde kötülük işliyorlar. Bizimle onların arasında bir engel koyman için sana bir vergi ödeyebilir miyiz?\""},{"n":95,"t":"Dedi ki, \"Efendimin bana verdikleri daha iyidir. Bana gücünüzle yardım edin de sizinle onların arasına bir duvar kurayım.\""},{"n":96,"t":"\"Bana demir kütleleri getirin.\" Her iki barikatın arasını doldurunca, \"Üfleyin!\" dedi. Onu bir ateş haline sokunca da, \"Getirin, üstüne erimiş bakır dökeyim\" dedi."},{"n":97,"t":"Artık onu ne aşabildiler, ne de delebildiler."},{"n":98,"t":"\"Bu, Efendimden bir rahmettir\" dedi. \"Efendimin belirlediği an gelince onu paramparça eder. Efendimin sözü gerçektir.\""},{"n":99,"t":"O gün onları bırakırız. Dalgalar halinde birbirlerine girerler. Boruya üflenir; hepsini bir araya toplarız."},{"n":100,"t":"O gün cehennemi sunarız o kafirlere…"},{"n":101,"t":"Onlar ki mesajıma karşı gözleri perdeliydi, dinleyemezlerdi de…"},{"n":102,"t":"İnkarcılar, benim dışımda kullarımı veliler edinerek kurtulacaklarını mı sandılar? O inkârcıların konağı olarak cehennemi belirledik."},{"n":103,"t":"De ki: \"İş yapanların en kötüsünün kim olduğunu size bildireyim mi?\""},{"n":104,"t":"\"Onlar, iyi iş yaptıklarını zannettikleri halde dünyadaki çabaları boşa çıkanlardır.\""},{"n":105,"t":"Onlar, Rab’lerinin ayetlerini ve O’nunla karşılaşmayı inkâr edenlerdir. Bu yüzden işleri boşa çıkar ve diriliş gününde de onlar için bir değer biçmeyiz."},{"n":106,"t":"İnkar ettikleri, ayetlerimi ve elçilerimi hafife aldıkları için, onlara en uygun ceza cehennemdir."},{"n":107,"t":"Gerçeği onaylayıp erdemli davrananlara gelince, onlar durak olarak neşe ve mutluluk dolu bahçeleri haketmişlerdir."},{"n":108,"t":"Orada sürekli kalıcıdırlar, orayı hiçbir şeyle değişmek istemezler."},{"n":109,"t":"De ki: \"Efendimin sözleri için okyanus mürekkep olsa ve hatta bir o kadarını da katsak, Efendimin sözleri tükenmeden okyanus tükenir.\""},{"n":110,"t":"De ki: \"Ben sizin gibi bir insandan başka bir şey değilim. Tanrınızın bir tek Tanrı olduğu bana vahyedildi. Rabbiyle karşılaşmayı uman herkes erdemli işler yapsın ve Efendine olan kulluğa hiç kimseyi ortak koşmasın.\""}]},{"id":19,"name":"Meryem Suresi","verses":[{"n":1,"t":"K. H. Y. A. S. (Kef Ha Ya Ayn Sad)"},{"n":2,"t":"Bu, Efendinin, kulu Zekeriyya’ya olan rahmetini anıştır."},{"n":3,"t":"Efendisine gizli bir yalvarışla seslenmişti."},{"n":4,"t":"\"Efendim\" dedi, \"Vücudumdaki kemik gevşedi, başım ağarıp tutuştu. Sana yalvarışta, Efendim, hiçbir vakit umut kesmedim.\""},{"n":5,"t":"\"Bana bağımlı olanların benden sonraki durumundan endişeleniyorum. Karım da kısır. Katından bana bir kalıtçı bağışla.\""},{"n":6,"t":"\"Bana ve Yakup boyuna varis olsun. Efendim, onu beğendiğin biri yap.\""},{"n":7,"t":"\"Zekeriyya, sana bir oğul müjdeleriz. İsmi Yahya’dır. Onun gibisini daha önce yaratmadık.\""},{"n":8,"t":"\"Efendim, benim nasıl bir oğlum olabilir? Karım kısır, bense alabildiğine yaşlıyım\" dedi."},{"n":9,"t":"\"Evet öyledir\" dedi, \"Efendin, ’O iş bana kolaydır. Seni daha önce yaratmıştım ve sen hiçbir şey değildin’ diyor.\""},{"n":10,"t":"\"Efendim, bana bir işaret ver\" dedi. \"Senin işaretin, birbirini izleyen üç gece boyunca halkla konuşmamandır.\""},{"n":11,"t":"Tapınaktan halkının arasına çıktı ve \"O’nu sabah akşam düşünüp anın\" diye onlara işaretle bildirdi."},{"n":12,"t":"\"Yahya, kitaba iyice sarıl.\" Çocuk yaşta kendisine bilgelik vermiştik."},{"n":13,"t":"Ek olarak katımızdan bir şefkat ve dürüstlük… Erdemli birisiydi."},{"n":14,"t":"Ana babasına karşı iyi davranırdı, asla bir zorba ve isyankâr olmadı."},{"n":15,"t":"Doğduğu gün, öleceği gün ve diri olarak kaldırılacağı gün ona selam olsun!"},{"n":16,"t":"Kitapta Meryem’i de an. Ailesinden ayrılıp doğu tarafında bir yere çekilmişti."},{"n":17,"t":"Kendisiyle onlar arasına bir perde çekmişti. Bu durumda ona Ruhumuzu gönderdik ve önünde mükemmel bir insan olarak biçimlendi."},{"n":18,"t":"\"Senden Rahman’a sığınırım\" dedi, \"Erdemliysen…\""},{"n":19,"t":"(Denetçi:) \"Ben, sana tertemiz bir erkek çocuğu vermek için görevlendirilmiş Efendinin bir elçisiyim\" dedi."},{"n":20,"t":"\"Bana hiçbir insan eli değmemiş ve ben iffetsizlik etmemişken nasıl olur da bir oğlum olur?\" dedi."},{"n":21,"t":"\"Öyledir\" dedi, \"Efendin, ’O iş bana kolaydır. Onu halk için bir işaret ve bizden bir rahmet kılacağız. Bu, artık kararlaştırılmış bir iştir’ diyor.\""},{"n":22,"t":"Ona gebe kalınca onunla uzak bir bölgeye çekildi."},{"n":23,"t":"Doğum sancısı onu bir hurma dalına kadar sürükledi. \"Keşke bundan önce ölseydim, unutulsaydım\" dedi."},{"n":24,"t":"\"Üzülme, Efendin senin altında bir su arkı hazırlamıştır\" diye (ağacın) altından kendisine seslendi."},{"n":25,"t":"\"Hurmanın dalını kendine doğru silkele, üzerine olgun hurmalar dökülsün.\""},{"n":26,"t":"\"Ye, iç ve gözün aydın olsun. İnsanlardan birini görürsen, ’Ben Rahman için oruç tutmaya karar verdim. Bugün hiçbir insanla konuşmayacağım’ de.\""},{"n":27,"t":"Onu alıp halkına getirdi. \"Meryem, sen şaşılacak bir şey işledin!\" dediler."},{"n":28,"t":"\"Ey Harun’un kız kardeşi, baban kötü bir adam değildi. Annen de iffetsiz değildi.\""},{"n":29,"t":"(Tanıklık için) Onu gösterdi. \"Nasıl olur da beşikteki bir çocukla konuşuruz?\" dediler."},{"n":30,"t":"(Çocuk:) \"Ben ALLAH’ın bir kuluyum. Bana kitap verdi ve beni peygamber kıldı\" dedi."},{"n":31,"t":"\"Nerede bulunursam bulunayım beni kutlu kıldı. Yaşadığım sürece bana namazı ve zekatı ve \""},{"n":32,"t":"\"anneme karşı iyi huylu olmamı emretti. Beni baş kaldıran bir zorba yapmadı.\""},{"n":33,"t":"\"Doğduğum gün, öldüğüm gün ve diri olarak kaldırılacağım gün bana selam olsun.\""},{"n":34,"t":"İşte, Meryem oğlu İsa böyleydi. Hakkında kuşkuya düştükleri konunun gerçeği budur."},{"n":35,"t":"ALLAH için bir çocuk edinmek söz konusu olamaz. O yücedir. Bir iş diledi mi, ona sadece \"Ol!\" der, o da olur."},{"n":36,"t":"\"ALLAH benim de Efendim, sizin de Efendinizdir; O’na hizmet ediniz. Doğru yol budur.\""},{"n":37,"t":"Mezhepler, (İsa’nın kimliği üzerinde) aralarında anlaşmazlığa düştüler. Büyük birgüne tanık olacak kafirlerin vay haline!"},{"n":38,"t":"Bize geldikleri gün onları dinle ve seyret! Zalimler, o gün apaçık bir sapıklık içindedirler."},{"n":39,"t":"Yargının noktalanacağı Pişmanlık Günü hakkında onları uyar. Onlar hâlâ aymazlık içinde gerçeği onaylamıyorlar."},{"n":40,"t":"Yer ve üzerindekiler bize kalacak; onlar bize döndürülecekler."},{"n":41,"t":"Kitapta İbrahim’i an; peygamber olan bir doğrucu idi."},{"n":42,"t":"Babasına, \"Babacığım, işitmeyen, görmeyen ve sana bir yararı dokunmayan şeylere niye hizmet ediyorsun?\" demişti."},{"n":43,"t":"\"Babacığım, bana, sana gelmeyen bir bilgi geldi. Beni izle de seni düzgün yola ileteyim.\""},{"n":44,"t":"\"Babacığım, sapkına hizmet etme. Sapkın, Rahman’a karşı çıkmıştır.\""},{"n":45,"t":"\"Babacığım, Rahman tarafından bir cezaya çarpılman ve sapkına dost olmandan korkuyorum.\""},{"n":46,"t":"(Babası:) \"Sen benim tanrılarıma yüz mü çeviriyorsun İbrahim? Buna son vermezsen seni taşlarım/kovarım. Benden uzaklaş!\" dedi."},{"n":47,"t":"\"Sana selam (barış) olsun\" dedi, \"Senin bağışlanman için Efendim’e yalvaracağım; O, bana karşı çok merhametlidir.\""},{"n":48,"t":"\"Sizden ve ALLAH dışında yalvardıklarınızdan ayrılıyorum. Ben Efendime yalvarıyorum. Umarım ki Efendime yalvarmakla bahtsız olmam.\""},{"n":49,"t":"Onları ve ALLAH dışında hizmet ettiklerini terkedince ona İshak’ı ve Yakub’u verdik. Hepsini peygamber yaptık."},{"n":50,"t":"Onlara rahmetimizden verdik. Onlara, doğru ve onurlu bir dil bağışladık."},{"n":51,"t":"Kitapta Musa’yı an. O kendini tümüyle adayan biriydi. Peygamber olan bir elçiydi."},{"n":52,"t":"Ona Tur dağının sağ tarafından seslendik. Konuşmak için onu yaklaştırdık."},{"n":53,"t":"Katımızdan bir rahmet olarak kardeşi Harun’u kendisine peygamber olarak armağan ettik."},{"n":54,"t":"Kitapta İsmail’i an. O sözünde duran biriydi. Aynı zamanda peygamber olan bir elçiydi."},{"n":55,"t":"Ailesine namazı gözetmeyi ve zekatı vermeyi emrederdi. Rabbi tarafından beğenilmişti."},{"n":56,"t":"Kitapta İdris’i an. O peygamber olan bir doğrucu idi."},{"n":57,"t":"Onu yüce bir makama yükselttik."},{"n":58,"t":"İşte bunlar, ALLAH’ın nimetlendirdiği peygamberlerin bir kısmıdır. Adem’in soyundan, Nuh ile birlikte taşıdıklarımızdan, İbrahim’in ve İsrail’in soyundan… Doğruya ulaştırdığımız ve seçtiğimiz kimselerdir onlar. Kendilerine Rahman’ın ayetleri okunduğu zaman ağlayarak secdeye varırlar."},{"n":59,"t":"Onlardan sonra gelenler namazı yitirdiler ve heveslerine uydular. Nitekim, felakete uğrayacaklar."},{"n":60,"t":"Tövbe eden, gerçeği onaylayan ve erdemli davrananlar hariç. Onlar en ufak bir haksızlığa uğramadan bahçeye girerler."},{"n":61,"t":"Rahman’ın kulları için söz verdiği, duyular ötesi Adn bahçelerine… O’nun sözü, kuşkusuz yerine gelecektir."},{"n":62,"t":"Orada boş söz işitmezler; sadece barış… Rızıklarını da sabah akşam alırlar."},{"n":63,"t":"Erdemli kullarımıza vereceğimiz bahçe işte budur."},{"n":64,"t":"Biz (Denetçiler) ancak Efendinin emriyle ineriz. Geçmişimiz, geleceğimiz ve ikisi arasında ne varsa O’na aittir. Efendin unutkan değildir."},{"n":65,"t":"Göklerin, yerin ve bunlar arasında bulunanların Rabbidir. O’na hizmet et ve O’na olan kulluğunda dirençli ol. O’na benzer birini biliyor musun?"},{"n":66,"t":"\"Öldüğüm zaman diri olarak çıkarılacak mıyım?\" diye soruyor insan."},{"n":67,"t":"İnsan, önceden hiçbir şey değilken kendisini nasıl yarattığımızı düşünmez mi?"},{"n":68,"t":"Efendine and olsun, onları ve sapkınları toplayacağız. Sonra onları cehennemin çevresine getireceğiz. Diz çökmüş halde…"},{"n":69,"t":"Sonra her gruptan, Rahman’a karşı azgınlıkta ileri gidenleri ayıklayacağız."},{"n":70,"t":"Orada yanmayı en çok kimin hakettiğini elbette biz gayet iyi biliriz."},{"n":71,"t":"İçinizden oraya gelmeyecek yoktur; bu, Efendinin gerçekleştireceği kesin bir karardır."},{"n":72,"t":"Sonra, erdemlileri kurtaracağız. Zalimleri ise orada diz üstü bırakacağız."},{"n":73,"t":"Kendilerine ayetlerimiz apaçık olarak okunduğu zaman inkâr edenler gerçeği onaylayanlara, \"Hangimiz daha güçlü ve hangimiz sayısal üstünlüğe sahiptir?\" derler."},{"n":74,"t":"Onlardan önce, daha varlıklı ve daha gösterişli nice nesilleri yok ettik."},{"n":75,"t":"De ki: \"Sapıklığa dalanlara Rahman bir süre verir. Cezayı veya o anı görünceye kadar… Kötü yere ve zayıf orduya kimin sahip olduğunu öğrenecekler.\""},{"n":76,"t":"ALLAH, doğru yolu seçenlerin hidayetini arttırır. Erdemli işler, Efendinin katında ebedi olarak en iyi ödülü ve en iyi sonucu hak eder."},{"n":77,"t":"Ayetlerimizi reddeden ve, \"Bana mal ve çocuk verilecek!\" diyeni gördün mü?"},{"n":78,"t":"Geleceğin bilgisine mi sahip oldu? Yoksa Rahman’dan bir söz mü aldı?"},{"n":79,"t":"Hayır. Söylediklerini kaydedeceğiz ve cezasını arttıracağız."},{"n":80,"t":"Sözünü ettikleri bize kalacak ve bize yalnız gelecektir."},{"n":81,"t":"Kendilerine destek olsunlar diye ALLAH’ın yanında tanrılar edindiler."},{"n":82,"t":"Tam tersine! Bu hizmet etmeyi reddedeceklerdir ve onlara karşıt olacaklardır."},{"n":83,"t":"İnkarcıların üzerlerine sapkınları yolladığımızı görmez misin? Onları kışkırtıp duruyorlar."},{"n":84,"t":"Acele etme; biz onlar için saydıkça sayıyoruz."},{"n":85,"t":"Erdemlileri, Rahman’ın huzurunda konuk grupları halinde toplayacağımız,"},{"n":86,"t":"Ve suçluları, susuz olarak cehenneme sürdüğümüz gün,"},{"n":87,"t":"Rahman’ın yanında söz almış olanlardan başkası şefaat (aracılık) edemez."},{"n":88,"t":"Hatta \"Rahman çocuk edindi\" dediler."},{"n":89,"t":"Siz, küstahça bir tez ileri sürdünüz."},{"n":90,"t":"Bu küstahlıktan ötürü neredeyse gökler parçalanacak, yer yarılacak ve dağlar göçecektir."},{"n":91,"t":"Rahman’a çocuk yakıştırdılar diye…"},{"n":92,"t":"Çocuk edinmek Rahman’a yakışmaz."},{"n":93,"t":"Göklerde ve yerde kim varsa, Rahman’a kul olarak gelecektir."},{"n":94,"t":"Onları kuşatmış ve tek tek saymıştır."},{"n":95,"t":"Onların hepsi, Diriliş günü O’na tek başına gelecektir."},{"n":96,"t":"Gerçeği onaylayıp erdemli davrananlara Rahman sevgi bağışlar."},{"n":97,"t":"Bunu senin dilinle kolaylaştırdık; onunla erdemlileri müjdeleyesin ve inatçı toplumu uyarasın diye."},{"n":98,"t":"Onlardan önce nice toplumları yok ettik: Hiçbirini algılıyor musun, ya da fısıltılarını işitiyor musun?"}]},{"id":20,"name":"Ta-Ha Suresi","verses":[{"n":1,"t":"T. H."},{"n":2,"t":"Biz bu Kuran’ı sıkıntı çekesin diye göndermedik."},{"n":3,"t":"Ancak saygı duyanlar için bir öğüttür."},{"n":4,"t":"Yeri ve yüksek gökleri Yaratan tarafından indirilmiştir."},{"n":5,"t":"Rahman, yönetim ve egemenliği elinde bulundurur."},{"n":6,"t":"Göklerde, yerde, her ikisinin arasında ve hatta toprağın altında ne varsa onundur."},{"n":7,"t":"(Niyetini) Sözle açıklasan da (açıklamasan da) O, gizliyi ve gizlinin gizlisini bilir."},{"n":8,"t":"ALLAH, O’ndan başka tanrı yoktur. Tüm güzel isimler O’na aittir."},{"n":9,"t":"Musa’nın haberi sana ulaştı mı?"},{"n":10,"t":"Bir ateş görmüştü ve ailesine, \"Burada durun, ben bir ateş gördüm. Olur ki size ondan bir kor getiririm, yahut ateşin yanında bir yol gösterici bulurum\" demişti."},{"n":11,"t":"Oraya varınca, \"Ey Musa!\" diye seslenildi."},{"n":12,"t":"\"Ben, evet Ben senin Efendinim. Sandaletlerini çıkar. Çünkü sen kutsal vadide, Tuva’dasın.\""},{"n":13,"t":"\"Ben seni seçtim, öyleyse vahyolanı dinle.\""},{"n":14,"t":"\"Ben, evet Ben ALLAH’ım; Benden başka tanrı yoktur. Bana hizmet et ve Beni anmak için namazı gözet.\""},{"n":15,"t":"O an elbette gelecektir. Herkes yaptığının karşılığını görsün diye Ben nerdeyse onu gizleyeceğim."},{"n":16,"t":"Onu onaylamayıp hevesine uyanlar seni ondan saptırmasın, sonra başüstü düşersin."},{"n":17,"t":"\"Şu elindeki nedir, Musa?\""},{"n":18,"t":"\"O, benim değneğimdir. Ona dayanırım, onunla koyunlarıma yaprak silkelerim ve bana daha başka yararları da dokunmaktadır\" dedi."},{"n":19,"t":"\"At onu Musa!\" dedi."},{"n":20,"t":"Onu atınca, hareketli bir yılana dönüşüverdi."},{"n":21,"t":"Dedi, \"Al onu, korkma. Onu ilk durumuna sokacağız.\""},{"n":22,"t":"\"Bir başka delil olarak, elini koltuğunun altına koy; lekesiz bembeyaz olarak çıksın.\""},{"n":23,"t":"\"Böylece sana en büyük mucizelerimizden bazılarını gösterelim.\""},{"n":24,"t":"\"Firavuna git, çünkü o azdı.\""},{"n":25,"t":"\"Efendim\" dedi, \"göğsümü aç.\""},{"n":26,"t":"\"Bana işimi kolaylaştır.\""},{"n":27,"t":"\"Dilimdeki düğümü çöz.\""},{"n":28,"t":"\"Ki sözümü anlasınlar.\""},{"n":29,"t":"\"Ailemden bana bir yardımcı ata.\""},{"n":30,"t":"\"Kardeşim Harun’u…\""},{"n":31,"t":"\"Beni onunla destekleyip güçlendir.\""},{"n":32,"t":"\"Bu işimde onu bana ortak yap.\""},{"n":33,"t":"\"Ki seni çokça yüceltelim.\""},{"n":34,"t":"\"Seni çokça analım.\""},{"n":35,"t":"\"Sen, elbette bizi Görensin.\""},{"n":36,"t":"Dedi ki: \"Dilediğin sana verildi, Musa.\""},{"n":37,"t":"\"Sana bir kez daha lütufta bulunduk.\""},{"n":38,"t":"\"Hani annene şu vahyi vahyetmiştik:\""},{"n":39,"t":"\"Onu bir sandığa koyup ırmağa at. Irmak da onu kıyıya atsın ve Bana da ona da düşman olan birisi onu alsın. diye… Gözümün önünde yetişesin diye sana sevgimi yağdırmıştım.\""},{"n":40,"t":"\"Hani kız kardeşin gidip, ’ona bakacak birini size göstereyim mi?’ diyordu. Böylece, gözü aydınlansın ve üzülmesin diye seni annene geri döndürmüştük. Hatta sen bir kişiyi öldürmüştün de seni tasadan kurtarmış ve çeşitli testlerden geçirmiştik. Medyen halkı arasında yıllarca kaldıktan sonra belli bir plan gereği şimdi geri gelmiş bulunuyorsun, Musa.\""},{"n":41,"t":"\"Seni kendim için tasarladım.\""},{"n":42,"t":"\"Sen ve kardeşin mucize ve ayetlerimi iletin. Beni anmakta gevşek olmayın.\""},{"n":43,"t":"\"İkiniz Firavuna gidin; çünkü o azdı.\""},{"n":44,"t":"\"Ona yumuşak bir dil kullanın; olur ki öğüt alır veya saygı duyar.\""},{"n":45,"t":"Dediler ki: \"Efendimiz, onun bize karşı saldırı ve taşkınlıkta bulunmasından korkuyoruz.\""},{"n":46,"t":"\"Korkmayın\" dedi, \"Ben sizinle birlikteyim; görüyorum ve işitiyorum.\""},{"n":47,"t":"\"Ona varın ve deyin ki,’Biz ikimiz Efendinin elçileriyiz. İsrailoğullarına yaptığın işkenceye son ver ve onları bizimle gönder. Biz sana, Efendinden bir ayet ile geldik. Doğru yolu izleyenlere selam (barış) olsun.\""},{"n":48,"t":"\"Bize vahyedildi: Yalanlayıp yüz çevirenler cezalandırılacaktır.\""},{"n":49,"t":"(Firavun) dedi ki: \"Efendiniz kimdir, Musa?\""},{"n":50,"t":"\"Efendimiz, Her şeye biçimini veren ve sonra yolunu gösterendir\" dedi."},{"n":51,"t":"\"Peki geçmiş nesillerin hali ne olacak?\" dedi."},{"n":52,"t":"\"Onların bilgisi Efendimin yanında kayıtlıdır. Efendim yanılmaz, unutmaz!\""},{"n":53,"t":"O ki yeryüzünü sizin için yaşanılır kıldı, sizin için onda yollar açtı, gökten bir su indirdi ve nitekim onunla çeşit çeşit bitkiler çıkardık."},{"n":54,"t":"Çiftlik hayvanlarını yiyiniz, otlatınız. Zeka sahipleri için bunda işaretler vardır."},{"n":55,"t":"Sizi o yerden yarattık, sizi tekrar ona döndüreceğiz ve bir kez daha sizi ondan çıkartacağız."},{"n":56,"t":"Ona tüm işaret ve delillerimizi göstermemize rağmen yalanlayıp reddetti."},{"n":57,"t":"Dedi ki, \"Sen bizi büyünle yurdumuzdan çıkarmak için mi geldin, Musa?\""},{"n":58,"t":"\"Biz de sana benzer bir büyü göstereceğiz. Her iki taraf için de uygun olan yerde ne senin ne de bizim caymayacağımız bir randevu zamanı belirle.\""},{"n":59,"t":"Dedi ki: \"Buluşma zamanınız bayram günüdür. Öğleden önce halk orada toplansın.\""},{"n":60,"t":"Firavun gitti, planını hazırlayıp geri döndü."},{"n":61,"t":"Musa onlara dedi ki: \"Size yazıklar olsun. ALLAH’a karşı yalan uydurmayın. Sonra sizi bir azap ile perişan eder. İftira edenler kuşkusuz kaybedecektir.\""},{"n":62,"t":"Aralarında işlerini tartıştılar ve konuşmalarını gizli tuttular."},{"n":63,"t":"Dediler ki, \"Bu iki büyücünün tek amacı, büyüleriyle sizi yurdunuzdan çıkarmak ve sizin ideal yaşam biçiminizi yıkmaktır.\""},{"n":64,"t":"\"Haydi, planlarınızı birleştirip birleşik bir cephe oluşturun. Bugün üstün gelen başarmıştır.\""},{"n":65,"t":"\"Musa\" dediler, \"Ya sen at, yahut ilk önce atan biz olalım?\""},{"n":66,"t":"\"Hayır, siz atın!\" dedi. Bunun üzerine, büyülerinden (hipnotik telkin ve illüzyondan) ötürü, halatları ve değnekleri ona (Musa’ya) sanki hareket ediyorlarmış gibi göründü."},{"n":67,"t":"Musa içinde bir korku duydu."},{"n":68,"t":"\"Korkma\" dedik, \"Sen üstün geleceksin.\""},{"n":69,"t":"\"Sağ elindekini at, onların uydurdukları şeyleri yutacaktır. Onların yaptığı bir büyücü planından ibarettir. Büyücünün ortaya koyduğu şeyler başarıya ulaşamaz.\""},{"n":70,"t":"Büyücüler, \"Harun’un ve Musa’nın Efendisini onayladık\" diyerek secdeye kapandılar."},{"n":71,"t":"\"Size izin vermeden mi onu onayladınız? O, size büyü öğreten ustanız olmalı. Ellerinizi ve ayaklarınızı çaprazlama kesip sizi hurma ağaçlarına asacağım. Hangimizin cezası daha çetin ve sürekli imiş öğreneceksiniz!\" dedi."},{"n":72,"t":"Dediler ki: \"Bize gelen apaçık kanıtları ve bizi Yaratan’ı bırakıp seni seçmeyiz. Nasıl yargı vereceksen ver. Yargın bu dünya hayatıyla sınırlıdır!\""},{"n":73,"t":"\"Biz Efendimizi onayladık ki hatalarımızı ve bize zorla yaptırdığın büyücülüğü bağışlasın. ALLAH daha İyidir ve daha Süreklidir.\""},{"n":74,"t":"Kim Efendisine suçlu olarak gelirse cehennemi hakeder; orada ne ölür, ne de yaşar."},{"n":75,"t":"Gerçeği onaylamış ve erdemli bir hayat sürmüş olarak O’na gelenler ise, yüksek dereceleri hakederler:"},{"n":76,"t":"Adn bahçeleri ki altından ırmaklar akar. Orada ebedi kalıcıdırlar. Arınanların ödülü işte böyledir."},{"n":77,"t":"Musa’ya: \"Kullarımı geceleyin yürüyüşe çıkar ve onlar için denizde kuru bir yol aç. Yakalanmaktan korkma, endişe etme\" diye vahyettik."},{"n":78,"t":"Firavun, ordusuyla birlikte ardlarına düştü. Ne var ki, deniz üstlerine kapanıp onları içine aldı."},{"n":79,"t":"Firavun, halkını saptırdı, doğru yola iletmedi."},{"n":80,"t":"Ey İsrailoğulları, sizi düşmanlarınızdan kurtarmış, Sina dağının sağ yanında size söz vermiş ve üzerinize bal ve bıldırcın indirmiştik."},{"n":81,"t":"Size verdiğimiz rızıkların iyilerinden yiyiniz ve bu konuda taşkınlıkta bulunmayın; yoksa gazabıma uğrarsınız. Gazabıma uğrayanlar düşmüştür."},{"n":82,"t":"Tövbe eden, gerçeği onaylayan, erdemli yaşayan ve sürekli doğruyu arayanlar için Bağışlayıcıyım."},{"n":83,"t":"\"Niçin halkını bırakmakta acele ettin, Musa?\""},{"n":84,"t":"\"Onlar öğretimi izliyorlar\" dedi, \"Hoşnut olasın diye sana doğru acele ettim, Efendim.\""},{"n":85,"t":"\"Halkını, senden sonra sınadık. Samiri onları saptırdı\" dedi."},{"n":86,"t":"Musa, kızgın ve hayal kırıklığına uğramış olarak halkına döndü ve \"Halkım, Efendiniz size güzel bir söz vermemiş miydi? Bekleyemediniz mi? Yoksa, Efendinizin gazabına uğramak için mi benimle yaptığınız sözleşmeyi bozdunuz?\" dedi."},{"n":87,"t":"\"Sana verdiğimiz sözü kendi kafamıza göre bozmadık. O halkın süs eşyaları bize taşıtıldı. Onları attık. Samiri işte böyle bir şey ortaya çıkardı\" dediler."},{"n":88,"t":"Onlar için, böğüren bir buzağı heykeli çıkardı. \"İşte sizin ve Musa’nın tanrısı budur, fakat o (Musa) unuttu\" dediler."},{"n":89,"t":"Görmediler mi ki, o, onlara ne bir yanıt verebiliyor, ne de onlara bir zarar ve yarar dokundurabiliyordu."},{"n":90,"t":"Harun ise: \"Halkım, onunla sınanıyorsunuz. Efendiniz Rahman’dır. Beni izleyin ve emrime uyun\" diye onları önceden uyarmıştı."},{"n":91,"t":"\"Musa gelinceye kadar ona hizmet etmeye devam edeceğiz\" diye karşılık vermişlerdi."},{"n":92,"t":"Dedi ki, \"Harun! Seni engelleyen neydi, onları saparken gördüğün zaman\""},{"n":93,"t":"\"Bana uymazlarken? Emrime karşı mı geldin?\""},{"n":94,"t":"Dedi ki, \"Anamın oğlu, sakalımı ve başımı çekme. ‘İsrailoğullarını neden böldün, neden sözümü tutmadın?’ diye bana çıkışacağından korktum.\""},{"n":95,"t":"Dedi ki, \"Peki, senin savunman nedir, Samiri?\""},{"n":96,"t":"Dedi ki, \"Onların görmediğini gördüm, elçinin öğretisinden bir kısmını alıp attım. Böyle uygun gördüm.\""},{"n":97,"t":"Dedi ki, \"Defol! Hayatın boyunca yakına bile gelme. Sana söz verilen bir an var ki ondan kaçamayacaksın. Hizmet etmekte olduğun tanrına bak, biz onu yakıp denize savuracağız.\""},{"n":98,"t":"Tanrınız, kendisinden başka tanrı olmayan ALLAH’tır. Bilgisi her şeyi içine almıştır."},{"n":99,"t":"Geçmişlerin haberlerini, sana böylece aktarıyoruz. Sana katımızdan bir mesaj vermiş bulunuyoruz."},{"n":100,"t":"Kim ondan yüz çevirirse Diriliş Gününde bir (günah) yükü taşıyacaktır."},{"n":101,"t":"Orada ebedi kalırlar. Diriliş günü bu onlar için ne de kötü bir yüktür."},{"n":102,"t":"Boruya üfürüldüğü gün, suçluları o gün mavi (kederden yüzleri morarmış) olarak toplarız."},{"n":103,"t":"Aralarında gizli gizli konuşurlar, \"Siz (dünyada) sadece on kaldınız.\""},{"n":104,"t":"Onların ne konuştuğunu iyi biliriz. En doğru görüşlüleri, \"Siz sadece birgün kaldınız\" diyordu."},{"n":105,"t":"Senden dağları sorarlar. De ki: \"Efendim onları ufalayıp savuracak.\""},{"n":106,"t":"\"Yerlerini dümdüz, bomboş bırakacaktır.\""},{"n":107,"t":"\"Orda ne ufak bir eğrilik ne de bir tümsek göreceksin.\""},{"n":108,"t":"O gün, en ufak bir sapma göstermeden çağırıcıya uyarlar. Sesler Rahman’ın huzurunda kısılmıştır; fısıltıdan başka bir şey işitemezsin."},{"n":109,"t":"O gün, kimseden başkasının şefaati (aracılığı) yarar vermez. Rahman’ın izin verdiği ve sözünü uygun gördüğü hariç."},{"n":110,"t":"Hiç kimse O’nu bilgice kavrayamazken, O onların geçmişini de geleceğini de bilir."},{"n":111,"t":"Tüm yüzler O Yaşayan, Ebedi Yöneticiye çevrilmiştir. Zulüm yüklenenler kaybedecektir."},{"n":112,"t":"Gerçeği onaylayıp erdemli davrananlar herhangi bir haksızlıktan ve güçlükten korkmayacaktır."},{"n":113,"t":"Biz, böylece onu Arapça bir Kuran olarak indirdik. Erdemli davranırlar veya onlar için bir öğüt olur diye onda geleceğin haberlerini çeşitli biçimlerde açıkladık."},{"n":114,"t":"Gerçek Yönetici olan ALLAH çok yücedir. Sana vahyi tamamlanmadan önce Kuran’ı (anlamak için) acele etme ve, \"Efendim, bilgimi arttır\" de."},{"n":115,"t":"Geçmişte Adem’den söz almıştık; ancak unuttu. Biz onda bir azim ve kararlılık görmedik."},{"n":116,"t":"\"Adem’e secde edin\" dediğimizde melekler secde ettiler, ancak İblis hariç; o reddetti."},{"n":117,"t":"\"Adem\" dedik, \"Bu senin ve eşinin düşmanıdır. Sakın sizi bahçeden çıkarmasın, yoksa perişan olursun.\""},{"n":118,"t":"\"Burda ne acıkırsın, ne de açıkta kalırsın.\""},{"n":119,"t":"\"Burda ne susuzluk çeker, ne de sıcaktan bunalırsın.\""},{"n":120,"t":"Sapkın, \"Adem, sana ebedilik ağacını ve tükenmez bir egemenliği göstereyim mi?\" diye ona fısıldadı."},{"n":121,"t":"İkisi de ondan yediler ve bunun üzerine vücutları kendilerine göründü. Bahçenin yaprakları ile örtünmeye çalıştılar. Adem Efendisine karşı geldi ve şaşırdı."},{"n":122,"t":"Sonra Rabbi onu seçip affetti ve ona yol gösterdi."},{"n":123,"t":"Dedi ki, \"Birbirinize düşmanlar olarak ordan aşağı inin. Size benden bir yol gösterici geldiğinde, kim benim yoluma uyarsa o sapmaz ve perişan olmaz.\""},{"n":124,"t":"\"Kim mesajımdan yüz çevirirse sıkıntılarla dolu bir hayata mahkûm olur. Diriliş günü de onu kör olarak meydana çıkarırız.\""},{"n":125,"t":"\"Efendim\" der, \"Toplantı alanına beni niye kör olarak sürdün, oysa ben görür idim?\""},{"n":126,"t":"Der ki: \"Çünkü sana ayetlerimiz ve mucizelerimiz geldiğinde sen onları unuttun. Bugün de sen unutuluyorsun.\""},{"n":127,"t":"Sınırı aşanları ve Efendinin ayet ve mucizelerini onaylamayanları işte böyle cezalandırırız. Ahiretin cezası elbette daha çetin ve daha süreklidir."},{"n":128,"t":"Önceki nesillerin yerleşim bölgelerinde dolaşanlar, onları yok edişimizden ders almazlar mı? Bunda akıl sahipleri için işaretler ve kanıtlar vardır."},{"n":129,"t":"Efendinin verilmiş bir sözü ve önceden belirlediği plan olmasaydı bunların da icabına hemen bakılırdı."},{"n":130,"t":"Sözlerine karşı dayanıklı ol, güneşin doğumundan ve batımından önce Efendini yücelterek an. Geceleyin ve günün her iki ucunda da an ki mutlu olabilesin."},{"n":131,"t":"Onların bazılarına, sınamak için verdiğimiz dünya hayatının süslerine gözünü dikme. Efendinin senin için hazırladığı nimetler daha iyidir ve süreklidir."},{"n":132,"t":"Ailene namazı emret ve bu konunun üstünde önemle dur. Biz senden herhangi bir rızık beklemiyoruz. Aksine biz seni besliyoruz. Sonuç, erdemlilerindir."},{"n":133,"t":"\"Bize hiç olmazsa bir ayet getirmeliydi!\" dediler. Daha önceki kitaplarda bulunan beyyine (delil) kendilerine gelmedi mi?"},{"n":134,"t":"Onları, ondan önce bir ceza ile helak etseydik, \"Efendimiz, bize bir elçi gönderseydin de böyle alçak ve rezil olmadan önce senin ayetlerine uysaydık!\" derlerdi."},{"n":135,"t":"De ki: \"Herkes gözlemekte. Siz de gözleyin. Düzgün yolun sahiplerinin kimler olduğunu ve kimlerin hidayet üzerinde olduğunu ileride bileceksiniz!"}]},{"id":21,"name":"Enbiya Suresi","verses":[{"n":1,"t":"İnsanların hesapları yaklaştı; ancak onlar hâlâ bir aymazlık içinde yüz çevirmektedirler."},{"n":2,"t":"Her ne zaman Rab’lerinden kendilerine yeni bir mesaj (zikr) gelse, onu ciddiye almadan dinlerler."},{"n":3,"t":"Kalpleri pervasızdır. Zalimler gizlice birbirleriyle görüştüler: \"Bu adam sizin gibi bir insan değil mi? Göz göre göre büyüye mi kapılacaksınız?\""},{"n":4,"t":"Dedi ki, \"Efendim yerde ve gökte her sözü bilir. O İşitendir, Bilendir.\""},{"n":5,"t":"Hatta, \"Boş hayallerdir\" \"Onu o uydurmuş\" ve \"O bir şairdir, daha önceki elçiler gibi o da bize mucizeler getirsin\" dediler."},{"n":6,"t":"Bunlardan önce yok ettiğimiz toplumlardan hiçbiri gerçeği onaylamamıştı. Şimdi bunlar mı onaylayacak?"},{"n":7,"t":"Senden önce, insanların dışında elçi göndermedik; onlara vahyediyorduk. Bilmiyorsanız uzmanlara sorunuz."},{"n":8,"t":"Onları, yemek yemeyen bedenler olarak yaratmadık. Onlar ölümsüz de değillerdi."},{"n":9,"t":"Sonra onlara verdiğimiz sözü yerine getirdik; onları dilediklerimizle birlikte kurtardık; aşırı gidenleri de helak ettik."},{"n":10,"t":"Size, size olan mesajı içeren bir kitabı indirmiş bulunuyoruz. Aklınızı kullanmaz mısınız?"},{"n":11,"t":"Nice ülkeleri, haksızlık etmelerinden ötürü kırıp geçirdik ve ardlarından başka toplumlar varettik."},{"n":12,"t":"Azabımızı hissettikleri anda ondan kaçmaya çalışıyorlardı."},{"n":13,"t":"Kaçmayın, lüks ve savurganlık içinde yaşadığınız yere, evlerinize dönünüz. Çünkü sorguya çekileceksiniz."},{"n":14,"t":"\"Vay bize, biz gerçekten zulmedenlermişiz\" dediler."},{"n":15,"t":"Onları biçip tüketinceye kadar bu yalvarışlarını tekrarlayıp duracaklar."},{"n":16,"t":"Göğü, yeri ve aralarındakileri oyun oynamak için yaratmadık."},{"n":17,"t":"Bir eğlence edinmek dileseydik, onu kendi katımızdan edinirdik. Evet, böyle bir işi dileseydik!"},{"n":18,"t":"Hayır, biz gerçeği batılın üstüne atarız da onu tepeler ve yok eder. Yakıştırdıklarınızdan ötürü vay halinize."},{"n":19,"t":"Göklerde ve yerde kim varsa O’na aittir. Yanındakiler, O’na hizmet etmekten büyüklenmez ve duraksamazlar."},{"n":20,"t":"Gece ve gündüz, hiç yorulmadan O’nu yüceltip anarlar."},{"n":21,"t":"Onlar, diriltebilecek yeteneğe sahip tanrılar mı edindiler yeryüzünden?"},{"n":22,"t":"O ikisinde (gökler ve yerde) ALLAH’tan başka tanrılar olsaydı ikisi de kaosa girecekti. Mutlak otoritenin sahibi ALLAH onların nitelemelerinden çok yücedir."},{"n":23,"t":"O, yaptığından sorulmaz; fakat onlar sorulurlar."},{"n":24,"t":"O’nun dışında tanrılar mı edindiler? De ki: \"Delilinizi getirin. Bu, benim çağımdakilerin de mesajıdır, benden öncekilerin de mesajıdır.\" Ne var ki onların çoğu gerçeği bilmediğinden yüz çevirirler."},{"n":25,"t":"Senden önce bir elçi göndermedik ki kendisine, \"Benden başka tanrı yoktur; sadece Bana hizmet ediniz\" diye vahyetmiş olmayalım."},{"n":26,"t":"\"Rahman bir çocuk edindi\" dediler. O yücedir. Oysa onlar onurlu kullardır."},{"n":27,"t":"Onlar O’ndan önce söz söylemezler; O’nun emirlerini ise titizlikle uygularlar."},{"n":28,"t":"O onların geçmişini ve geleceğini bilir. Onlar O’nun hoşnut olduğu kullarından başkası için şefaat etmezler. Onlar bile O’nun karşısında saygıyla titrerler."},{"n":29,"t":"Onlardan kim, \"Ben O’nun yanında bir tanrıyım\" derse onu cehennemle cezalandırırız; zalimleri biz böyle ödüllendiririz."},{"n":30,"t":"İnkar edenler, görmezler mi ki gökler ve yer bitişik durumda idi de biz onları patlattık? Ayrıca her canlıyı da sudan yarattık. Hâlâ gerçeği onaylamayacaklar mı?"},{"n":31,"t":"Onları sarsmasın diye yeryüzüne dağları yerleştirdik. Yolu bulmaları için onda geniş geçitler açtık."},{"n":32,"t":"Göğü korunmuş bir tavan yaptık. Buna rağmen onlar ondaki işaretlere ilgisiz durmaktadırlar."},{"n":33,"t":"O ki geceyi, gündüzü, güneşi ve ayı yaratmıştır. Bunların hepsi bir yörüngede yüzer."},{"n":34,"t":"Senden önce hiçbir insanı ölümsüz kılmadık. Sen ölürsen onlar ebedi mi kalacaklar?"},{"n":35,"t":"Her can ölümü tadacaktır. Sizi bir test olarak iyi ve kötü olaylarla sınarız ve dönüşünüz bizedir."},{"n":36,"t":"Kafirler (gerçeği örtenler) seni gördüklerinde, \"Tanrılarınızı diline dolayan bu mu\" diye alaylarına hedef yapmaktan başka bir tepki göstermiyorlar. Rahman’ın mesajını tümüyle inkâr etmektedir onlar."},{"n":37,"t":"İnsanlar aceleci olarak yaratılmıştır. Size ayetlerimi (işaretlerimi) göstereceğim; acele etmeyin."},{"n":38,"t":"\"Doğru sözlü iseniz O verilen söz ne zaman gerçekleşecek\" diye meydan okuyorlar."},{"n":39,"t":"İnkar edenler, yüzlerinden ve arkalarından ateşi savamayacakları ve yardım da görmeyecekleri anı bir bilselerdi."},{"n":40,"t":"Nitekim, onlara ansızın gelecek ve onları şaşkına çevirecektir. Ne onu geri çevirmeye güçleri yeter, ne de kendilerine süre verilir."},{"n":41,"t":"Senden önceki elçilerle de alay edildi. Ancak onlarla alay edenleri, eğlenceye aldıkları şey kuşatıverdi."},{"n":42,"t":"De ki: \"Sizi Rahman’dan başka kim gece ve gündüz koruyabilir?\" Ama onlar, Rab’lerinin mesajından tümüyle yüz çeviriyorlar."},{"n":43,"t":"Yoksa onları bize karşı savunacak tanrıları mı var? Halbuki onlar kendilerine bile yardım edemezler ve biz de sahip çıkmayız."},{"n":44,"t":"Halbuki biz onları ve atalarını yaşlanıncaya kadar nimetlendirdik. Yeryüzünün uçlarından habire eksilttiğimizi görmüyorlar mı? Buna rağmen onlar mı üstün gelecek?"},{"n":45,"t":"\"Ben sizi ancak vahiy ile uyarıyorum\" de. Ne var ki, sağırlar uyarıldıkları vakit çağrıyı işitmez."},{"n":46,"t":"Kendilerine, Efendinin azabından bir esinti dokunsa, \"Vay bize, biz gerçekten zalimlermişiz\" derler."},{"n":47,"t":"Diriliş günü için adalet terazileri kurarız. Kimseye hiçbir haksızlık edilmez. Hardal tanesi kadar bir ağırlığı bile hesaba katacağız. Biz, hesapçı olarak yeteriz."},{"n":48,"t":"Musa’ya ve Harun’a Yasalar Kitabını, erdemliler için bir ışığı, bir mesajı verdik."},{"n":49,"t":"Onlar ki kimse kendilerini görmezken bile Rab’lerini sayarlar ve o anın dehşetini duyarlar."},{"n":50,"t":"Bu da ona indirdiğimiz yüce bir mesajdır. Siz şimdi ona karşı mı çıkıyorsunuz?"},{"n":51,"t":"Biz daha önce de İbrahim’e anlama ve kavrama yeteneğini bağışlamıştık. Biz onu çok iyi biliyorduk."},{"n":52,"t":"Babasına ve halkına, \"Kendinizi adadığınız bu heykeller de neyin nesidir?\" dedi."},{"n":53,"t":"\"Atalarımızı onlara hizmet eder bulduk\" dediler."},{"n":54,"t":"\"Doğrusu, siz ve atalarınız apaçık bir sapıklık içine düşmüşsünüz\" deyince,"},{"n":55,"t":"\"Bize gerçeği mi getirdin, yoksa oyun mu oynuyorsun?\" dediler."},{"n":56,"t":"Dedi ki, \"Aslında sizin Efendiniz (Sahibiniz) göklerin ve yerin Rabbidir; onları ayırarak yaratmıştır. Ben buna tanıklık edenlerdenim.\""},{"n":57,"t":"\"ALLAH’a and içerim ki, siz gider gitmez, ardınızdan heykellerinize karşı bir plan uygulayacağım.\""},{"n":58,"t":"Hepsini param parça etti, ancak belki ona danışırlar diye en büyüklerine dokunmadı."},{"n":59,"t":"\"Her kim Tanrılarımıza bunu yaptıysa gerçek bir zalimdir!\" dediler."},{"n":60,"t":"\"Onları diline dolayan bir delikanlı işittik, kendisine İbrahim deniliyormuş\" dediler."},{"n":61,"t":"\"Onu kamunun huzuruna çıkarın ki tanık olsunlar\" dediler."},{"n":62,"t":"\"İbrahim, tanrılarımıza bunu sen mi yaptın?\" dediler."},{"n":63,"t":"\"Hayır, o işi işte şu büyükleri yaptı. Onlara sorun, eğer konuşurlarsa!\" dedi."},{"n":64,"t":"Kendi vicdanlarına dönüp, kendi kendilerine şunu söylediler: \"Gerçekten sizler haksızsınız.\""},{"n":65,"t":"Sonra tekrar eski kafalarına döndüler: \"Bunların konuşamadığını sen gayet iyi bilirsin!\""},{"n":66,"t":"\"ALLAH’ın yanında size hiçbir yararı ve zararı dokunmayan şeylere mi hizmet ediyorsunuz?\" dedi."},{"n":67,"t":"\"Yuh size ve ALLAH’ın yanında hizmet ettiklerinize . Aklınızı kullanmaz mısınız?\""},{"n":68,"t":"\"Bir şey yapacaksanız onu yakın da tanrılarınızı destekleyin\" dediler."},{"n":69,"t":"\"Ey ateş, İbrahim’e karşı serin ve güvenilir ol\" dedik."},{"n":70,"t":"Böylece onun için bir plan uygulamak istediler de biz onları başarısızlığa mahkûm ettik."},{"n":71,"t":"Onu ve Lut’u, tüm insanlar için sınırladığımız topraklara ulaştırıp kurtardık."},{"n":72,"t":"Ona ödül olarak İshak’ı ve Yakub’u verdik. Hepsini erdemli kıldık."},{"n":73,"t":"Biz onları, emrimize göre yol gösteren önderler kıldık. Onlara iyi işlerin nasıl yapılacağını, namazın nasıl gözetileceğini ve zekatın nasıl verileceğini vahyettik. Onlar bize hizmet edenlerdi."},{"n":74,"t":"Lut’a da bilgi ve bilgelik verdik. Onu, çirkin işler işleyen topluluktan kurtardık. Onlar, yoldan çıkmış kötü bir toplumdu."},{"n":75,"t":"Onu merhametimizin kapsamına aldık, çünkü o erdemlilerden idi."},{"n":76,"t":"Daha önce Nuh da bizi çağırmıştı. Onu ve ailesini büyük sıkıntıdan kurtararak duasına cevap verdik."},{"n":77,"t":"Ayetlerimizi inkâr eden toplumlara karşı onu destekledik. Onlar, kötü bir toplum olduklarından hepsini boğduk."},{"n":78,"t":"Davut ve Süleyman da… Bir defasında, halkın koyunlarının yayıldığı birilerinin ekini hakkında hüküm veriyorlardı. Biz onların kararına tanık olduk."},{"n":79,"t":"Süleyman’a, doğru anlama yeteneği bağışladık. Her birine bilgi ve bilgelik verdik. Davud’un emrine dağları ve kuşları verdik. Biz bunları yapmıştık."},{"n":80,"t":"Ve sizi savaşlarınızda korusun diye ona zırh yapmayı öğrettik. Artık şükreder misiniz?"},{"n":81,"t":"Süleyman’a da, bereketli kıldığımız topraklara doğru esen boranın kumandasını verdik. Biz her şeyi iyi biliriz."},{"n":82,"t":"Ve onun için dalgıçlık yapan ve bunun yanında başka işler de gören sapkınları da… Onları biz gözetiyorduk."},{"n":83,"t":"Eyyub da… Efendisine şöyle yalvarmıştı: \"Bana felaket dokundu. Sen merhametlilerin en merhametlisisin.\""},{"n":84,"t":"Biz ona cevap vererek ne sıkıntısı varsa onu giderdik. Katımızdan bir rahmet, hizmet edenlere bir hatırlatma olarak kendisine, ailesini ve onların bir mislini verdik."},{"n":85,"t":"Ayrıca İsmail, İdris ve ZülKifl de… Hepsi güçlüklere karşı dirençli kişilerdi."},{"n":86,"t":"Biz onları rahmetimiz kapsamına aldık çünkü onlar erdemli kişilerdi."},{"n":87,"t":"ZanNun (yani isminde ‘Nun’ harfi bulunan Yunus) da… Protesto ederek görevini terketmişti. Kendisini kontrol edemeyeceğimizi sandı. Sonunda, (balığın karnındaki) karanlıklar içinde, \"Senden başka tanrı yok. Sen yücesin. Ben yanlış davrananlardan oldum\" diye yalvardı."},{"n":88,"t":"Yalvarışına karşılık verdik ve onu üzüntüden kurtardık. Gerçeği onaylayanları işte böyle kurtarırız."},{"n":89,"t":"Zekeriya da… Efendisine şöyle yalvarmıştı: \"Efendim, beni tek bırakma; sen varislerin en iyisisin.\""},{"n":90,"t":"Duasını kabul ettik ve ona Yahya’yı verdik. Kendisi için karısının durumunu düzelttik. Çünkü onlar iyi işlerde yarışıyorlar ve bize hem umutluyken ve hem de korku içindeyken yalvarıyorlardı. Onlar bize saygı duyanlardı."},{"n":91,"t":"Ve ırzını koruyan kadın da… Nitekim ona ruhumuzdan üflemiştik. Onu ve oğlunu tüm dünyaya bir işaret yaptık."},{"n":92,"t":"İşte sizin topluluğunuz böyle bir (elçiler) topluluktur. Ben sizin Efendinizim; sadece bana hizmet edin."},{"n":93,"t":"Fakat onlar işlerinde ayrılığa düştüler; hepsi bize döneceklerdir."},{"n":94,"t":"Kim gerçeği onaylayarak erdemli işler yaparsa onun bu çabası boşa gitmeyecektir; biz sürekli olarak kaydetmekteyiz."},{"n":95,"t":"Helak ettiğimiz bir toplumun tekrar dönmesi yasaktır."},{"n":96,"t":"Nihayet, Yecuc ve Mecuc’un önü açıldığı zaman, onlar her yönden saldırırlar."},{"n":97,"t":"Hak sözün gerçekleşmesi yaklaşmış ve kafirlerin gözleri korkudan dona kalmıştır: \"Vah bize, biz bundan gaflet içinde idik. Biz gerçekten zalimler olduk.\""},{"n":98,"t":"Siz ve ALLAH’ın yanında hizmet ettikleriniz cehennemin yakıtısınız; sizler oraya girmeye layıksınız."},{"n":99,"t":"Onlar tanrılar olsaydı oraya girmeyeceklerdi. Oysa hepsi orada ebedi kalıcıdırlar."},{"n":100,"t":"Onlar için orada iç çekip inlemek vardır; hiçbir şey de işitemezler."},{"n":101,"t":"Ancak kendilerine mutlu bir son belirlediklerimiz hariç, onlar ondan uzaklaştırılacaklardır."},{"n":102,"t":"Onun uğultusunu işitmezler. Canlarının istediği şeyler içinde ebedi kalırlar."},{"n":103,"t":"O en büyük korku onları üzmez. Kendilerini melekler, \"İşte bu, size söz verilen gününüzdür!\" diye karşılar."},{"n":104,"t":"O gün göğü dosyaları dürer gibi katlar ve yaratılışın ilk durumunu nasıl başlatmışsak ona çeviririz. Üzerimize söz; biz mutlaka gerçekleştiririz."},{"n":105,"t":"Zikir’den sonra Zebur’da da, \"Yeryüzüne benim erdemli kullarım varis olacak\" diye yazıp belirtmiştik."},{"n":106,"t":"Hizmet eden bir toplum için bunda bir bildiri vardır."},{"n":107,"t":"Biz seni tüm halklara bir rahmet olarak gönderdik."},{"n":108,"t":"De ki: \"Sizin tanrınızın bir tek tanrı olduğu bana vahyediliyor. Artık teslim olacak mısınız?\""},{"n":109,"t":"Eğer yüz çevirirlerse De ki: \"Size yeterli ölçüde bildirdim. Size söz verilen şeyin yakın mı, yoksa uzak mı olduğunu bilmem.\""},{"n":110,"t":"\"O, açıklanan sözü de bilir, gizlediklerinizi de bilir.\""},{"n":111,"t":"\"Hiç bilmiyorum; belki sizin için bir test ve belli bir süreye kadar bir hoşlanma vesilesi olur.\""},{"n":112,"t":"De ki: \"Efendim, hükmünü gerçekleştir. Sizin yakıştırdıklarınıza karşı sadece Rahman olan Efendimizden yardım istenir.\""}]},{"id":22,"name":"Hac Suresi","verses":[{"n":1,"t":"Ey halk, Efendinize saygı gösteriniz, çünkü o anın depremi korkunç bir şeydir."},{"n":2,"t":"Ona tanık olduğunuz gün, her emziren ana emzirdiğini atar, her gebe kadın yükünü bırakır. Sarhoş olmadıkları halde insanları sarhoş gibi göreceksin. Halbuki ALLAH’ın cezası şiddetlidir."},{"n":3,"t":"İnsanlardan öyleleri var ki ALLAH hakkında bilgisizce tartışır ve her azılı sapkına uyar."},{"n":4,"t":"\"Bu, kendisini dost edinen kimseyi saptırır ve alevli azaba yol gösterir\" diye hakkında hüküm verilmiştir."},{"n":5,"t":"Ey insanlar, diriliş konusunda kuşku besliyorsanız, (hatırlayın ki) sizi topraktan, sonra bir damlacıktan, sonra asılı duran bir madde (embriyo) dan, sonra biçimi belli ve belirsiz bir dölütten yarattık. Böylece size bildiriyoruz. Neyi dilemişsek belli bir süreye kadar onu rahimlerde tutarız. Sonra sizi bir bebek olarak çıkarırız ve ardından olgunlaşıp erginleşirsiniz. Kiminizin hayatına son verilir, kiminiz de en kötü yaşa kadar ulaştırılır. Böylece bir bilgiye sahip olduktan sonra bir şey bilemez olsun. Toprağı kuru ve ölü görürsün, ancak üzerine su yağdırdığımız zaman titreşip kabarır ve çeşit çeşit güzel bitkiler bitirir."},{"n":6,"t":"Çünkü, ALLAH tek gerçektir; ölüleri diriltir; her şeye gücü yeter;"},{"n":7,"t":"ve o an hiçbir kuşkuya yer bırakmadan gelmekte ve ALLAH mezarlardakileri diriltecektir."},{"n":8,"t":"İnsanlardan kimi, bir bilgiye, bir yol göstericiye ve aydınlatıcı bir kitaba sahip olmadan ALLAH hakkında tartışır."},{"n":9,"t":"ALLAH’ın yolundan saptırmak için kibirle kasılarak gayret eder. Bu dünya hayatında onun için rezillik vardır. Diriliş gününde de ona yakıcı azabı tattırırız."},{"n":10,"t":"\"Bu, ellerinin senin için yapıp öne sürdüğü işlerden ötürüdür.\" ALLAH kullara zulmedici değildir."},{"n":11,"t":"İnsanlardan öyleleri var ki ALLAH’a koşullu olarak hizmet eder. İşleri yolunda gidince sevinir; ancak başına bir bela gelince yüzünü çevirir. Böylece dünyayı da ahireti de kaybeder. Gerçek kayıp işte budur."},{"n":12,"t":"ALLAH’ın yakınından, kendisine yarar ve zarar veremeyenlere yalvarır. Sapıklığın en aşırı noktası budur."},{"n":13,"t":"Zararı yararından daha yakın olana yalvarır. Ne kötü bir mevla ve ne kötü bir arkadaştır."},{"n":14,"t":"ALLAH gerçeği onaylayıp erdemli davrananları, içinde ırmaklar akan bahçelere sokar. ALLAH istediğini yapar."},{"n":15,"t":"Kim ALLAH’ın dünya ve ahirette kendisine yardım edemeyeceğini sanıyorsa göğe (Tanrı’ya) doğru yönelsin ve sonra (umut bağladığı diğerlerinden) umudunu kessin de uyguladığı bu planın, kendisinin canını sıkan her şeyden kurtarıp kurtarmadığına bir baksın."},{"n":16,"t":"Böylece, biz onu apaçık ayetler olarak indirdik. ALLAH dilediğini/dileyeni doğruya ulaştırır."},{"n":17,"t":"Gerçeği onaylayanlar, Yahudiler, din değiştirenler, Hıristiyanlar, zerdüştiler ve ortak koşanlar… ALLAH diriliş günü aralarında hüküm verecektir. ALLAH her şeye tanıktır."},{"n":18,"t":"Göklerde ve yerde bulunan kimselerin, güneşin, ayın, yıldızların, dağların, ağaçların, hayvanların ve insanlardan birçok kişinin ALLAH’a secde ettiklerini (boyun eğdiklerini) görmez misin? Birçok kişi de azabı haketmiştir. ALLAH’ın alçalttığını hiç kimse onurlu kılamaz. ALLAH dilediğini yapar."},{"n":19,"t":"İşte şunlar, Rab’leri hakkında tartışan iki karşıt gruptur. İnkarcı olanlar için ateşten elbiseler biçilir ve başlarından aşağı kaynar su dökülür."},{"n":20,"t":"Onunla karınlarında ne varsa, derileriyle birlikte eritilir."},{"n":21,"t":"Onlar için demirden topuzlar vardır."},{"n":22,"t":"Her ne vakit oradaki sıkıntıdan çıkmak isteseler oraya geri çevrilirler: \"Yakıcı azabı tadın.\""},{"n":23,"t":"ALLAH gerçeği onaylayıp erdemli bir hayat sürenleri içlerinden ırmaklar akan bahçelere sokar. Orada altın bilezikler ve inciler takınırlar. Orada giysileri de ipektir."},{"n":24,"t":"Onlar sözün güzeline iletilmişlerdir, onlar En Çok Övülen’in yoluna iletilmişlerdir."},{"n":25,"t":"İnkar edenler, yerli ve dışarıdan gelen tüm insanlar için eşit olarak ayırdığımız Sınırlanmış Mescid’den ve ALLAH’ın yolundan geri çevirenler ve orada zulüm ve sapıklık arayanlar, tarafımızdan acı bir azap tadacaklardır."},{"n":26,"t":"İbrahim’i Ev’in mekanına yerleştirmiştik: \"Bana hiçbir şeyi ortak etme. Evimi de ziyaretçiler, orada yerleşenler, rüku ve secde edenler için temizle.\""},{"n":27,"t":"\"İnsanlara Konferans ziyaretini ilan et. Sana yaya olarak veya çeşitli taşıt araçlarıyla uzaklardan gelsinler.\""},{"n":28,"t":"Ki kendileri için bir takım (sosyal, politik, ekonomik) yararlara tanık olsunlar ve kendilerine çiftlik hayvanlarını rızık olarak verdiği için ALLAH’ın ismini bilinen günlerde ansınlar. \"Onlardan yiyin ve sıkıntı içindeki yoksullara da yedirin.\""},{"n":29,"t":"Sonra yükümlülüklerini tamamlasınlar, vermiş oldukları sözlerini yerine getirsinler ve o Tarihi Evi ziyaret etsinler."},{"n":30,"t":"İşte böyle. Kim ALLAH’ın yasaklarına saygı gösterirse Efendisinin yanında kendisi için daha iyidir. Size özellikle bildirilenlerin haricindeki tüm çiftlik hayvanları helal (yasal) kılınmıştır. O halde putperestliğin felaketinden kaçının, yalan sözden sakının."},{"n":31,"t":"ALLAH’a ortak koşmayarak, kendinizi sadece O’na adayın. Kim ALLAH’a ortak koşarsa sanki gökten düşmüş ve kendisini akbaba kapmış veya rüzgar tarafından derin bir uçuruma sürükleniyor gibidir."},{"n":32,"t":"Kimler ALLAH’ın emirlerine saygı gösterirse kalplerindeki erdemi sergilemiştir."},{"n":33,"t":"Onları o Tarihi Eve bağışlanmadan önce o (hayvan)lardan belli bir süre yararlanırsınız."},{"n":34,"t":"Kendilerine çiftlik hayvanlarını rızık olarak vermesinden ötürü ALLAH’ın ismini anmaları için, her topluluğa ayrı bir ibadet biçimi belirledik. Tanrınız bir tek tanrıdır. Sadece O’na teslim olun. İtaat edenlere müjde ver."},{"n":35,"t":"Onlar öyle kimselerdir ki, ALLAH’tan söz edildiğinde yürekleri ürperir. Başlarına gelene sabrederler, namazı gözetirler ve kendilerine verdiğimiz rızıktan yardım için harcarlar."},{"n":36,"t":"ALLAH’a kulluğun bir işareti olarak, hayvanların kurban edilmesinde sizin için yararlar mevcuttur. Onlar sırada diziliyken üzerlerinde ALLAH’ın ismini anmalısınız. Yanları üzerine düştükleri zaman da onlardan yiyin ve dilenene de dilenmeyen yoksula da yedirin. Şükredesiniz diye onları size amade kıldık."},{"n":37,"t":"ALLAH’a ne onların etleri, ne de kanları ulaşır; O’na ancak sizin erdemli davranışınız ulaşır. Onları böylece sizin hizmetinize vermiştir ki, sizi doğruya ulaştırdığı için ALLAH’ın büyüklüğünü anasınız."},{"n":38,"t":"ALLAH gerçeği onaylayanları savunur. ALLAH hainleri ve nankörleri sevmez."},{"n":39,"t":"Zulmedilerek kendilerine savaş açılanlara izin verilmiştir. ALLAH onları desteklemeye elbette kadirdir."},{"n":40,"t":"Onlar ki yalnızca, \"Efendimiz ALLAH’tır\" dedikleri için haksız yere ülkelerinden çıkarıldılar. Allah halkın bir kısmını bir kısmına karşı savunmasaydı silolar, alışveriş merkezleri, yardım kurumları, ve içlerinde ALLAH’ın isminin çokça anıldığı mescidler yıkılırdı. ALLAH kendisine yardım edenlere elbette yardım edecektir. ALLAH Kuvvetlidir, Güçlüdür.."},{"n":41,"t":"Onlar ki kendilerini yeryüzüne yöneticiler kıldığımız zaman namazı gözetir, zekatı verir, iyiliği emreder ve kötülükten menederler. Son karar ALLAH’a aittir."},{"n":42,"t":"Seni yalanlarlarsa, onlardan önce Nuh, Ad ve Semud halkları da yalanlamışlardı."},{"n":43,"t":"İbrahim’in halkı, Lut’un halkı da…"},{"n":44,"t":"Medyen yerlileri de… Musa dahi yalanlandı. Ben o kafirlere süre tanıdım ve sonra onları hesaba çektim; beni tanımamak da nasılmış!."},{"n":45,"t":"Nice kentlerin halkını, işledikleri haksızlıklardan ötürü helak ettik. Onlardan arta kalanlar, çökmüş çatılar, terkedilmiş kuyular ve ıssız saraylardı…"},{"n":46,"t":"Düşünen beyinlerle ve işiten kulaklarla yeryüzünü dolaşmadılar mı? Gerçek körlük, gözlerin körlüğü değil; göğüslerdeki gönüllerin körlüğüdür."},{"n":47,"t":"O azabı çabuk getirmen için sana meydan okuyorlar. ALLAH sözünü bozmaz. Rabbinin katında bir gün, onların hesabıyla bin sene gibidir."},{"n":48,"t":"Nice kentlerin halkına, zalim oldukları halde süre tanıdım ve sonra onları hesaba çektim; son dönüş Banadır."},{"n":49,"t":"De ki: \"Ey insanlar, ben sizin için ancak apaçık bir uyarıcıyım.\""},{"n":50,"t":"Gerçeği onaylayıp erdemli işler yapanlar, bağışlanma ve bol nimet haketmişlerdir."},{"n":51,"t":"Ayetlerimize karşı mücadele edenler ise cehennemin halkı olmayı haketmişlerdir."},{"n":52,"t":"Senden önce, arzularına sapkının karışmadığı hiçbir elçi ve hiçbir peygamberi göndermedik. ALLAH sapkının attığı şeyleri ortadan kaldırır ve sonra ALLAH ayetlerini sağlamlaştırır. ALLAH Bilendir, Bilgedir."},{"n":53,"t":"Böylece sapkının attığını kalplerinde hastalık bulunanlar ve kalpleri katı olanlar için bir test haline sokar. Zalimler, elbette apaçık bir karşıtlık içindedirler."},{"n":54,"t":"Bu durum, aynı zamanda, kendilerine bilgi verilmiş olanların bunun Efendinden gelen bir gerçek olduğunu anlamalarını sağlar. Böylece kalpleri onu benimser ve onaylar. ALLAH, elbette, gerçeği onaylayanları doğru yola ulaştırır."},{"n":55,"t":"İnkarcılar ise, o an kendilerine ansızın gelinceye kadar, yahut o müthiş günün cezası kendilerine çatıncaya kadar sürekli ondan kuşku duyacaklardır."},{"n":56,"t":"Yönetim ve otorite, o gün tümüyle ALLAH’a aittir. Onların arasında hüküm verecektir. Gerçeği onaylayıp erdemli davrananlar nimet bahçelerindedir."},{"n":57,"t":"Ayetlerimizi yalanlayıp inkâr edenler ise küçük düşürücü bir cezayı hakederler."},{"n":58,"t":"ALLAH yolunda göç ettikten sonra ölenler veya öldürülenler, ALLAH tarafından güzel bir rızık ile besleneceklerdir. Kuşkusuz ALLAH rızık verenlerin en iyisidir."},{"n":59,"t":"Hoşnut olacakları bir kabul ile katına alacaktır onları. ALLAH Bilendir, Şefkatlidir."},{"n":60,"t":"Bu böyledir. Kim, kendisine uygulanan haksızlığa karşı aynı şekilde karşılık verir de bundan dolayı da kendisine saldırılırsa ALLAH ona yardım edecektir. Elbette ALLAH Affedendir, Bağışlayandır."},{"n":61,"t":"Bu gerçekleşecektir. Çünkü ALLAH geceyi gündüze sokar, gündüzü geceye sokar ve ALLAH İşitendir, Bilendir."},{"n":62,"t":"Bu gerçekleşecektir. Çünkü ALLAH Gerçektir, O’nun dışında yalvardıkları ise asılsızdır ve ALLAH Yücedir, Büyüktür."},{"n":63,"t":"ALLAH’ın gökten bir su indirdiğini ve yeryüzünün yeşerdiğini görmez misin? ALLAH Şefkatlidir, Haberdardır."},{"n":64,"t":"Göklerde ve yerde ne varsa O’na aittir. Elbette ALLAH Zengindir, En Çok Övülendir."},{"n":65,"t":"ALLAH’ın yerdeki şeyleri ve emriyle denizde akıp giden gemileri hizmetinize sunduğunu ve göğü, izni olmadan yerin üzerine düşmekten alıkoyduğunu görmez misin? ALLAH insanlara karşı Şefkatlidir, Rahimdir."},{"n":66,"t":"O’dur size can veren, sonra sizi öldüren ve sonra sizi dirilten… İnsan elbette pek nankördür."},{"n":67,"t":"Her bir topluluğu, uygulayacakları bir dizi kural ile yükümlü kıldık. Onun için bu konuda seninle çekişmesinler. Sen Efendine çağır. Kuşkusuz sen doğru bir yol üzerindesin."},{"n":68,"t":"Seninle çekişirlerse De ki: \"ALLAH yaptığınız her şeyi en iyi bilendir.\""},{"n":69,"t":"Tartıştığınız konularda, diriliş günü aranızda ALLAH hüküm verecektir."},{"n":70,"t":"ALLAH’ın gökte ve yerde olan her şeyi bildiğini bilmez misin? Tüm bunlar bir kitapta kayıtlıdır. Elbette bu ALLAH’a kolaydır."},{"n":71,"t":"ALLAH’ın yanında öylelerine hizmet ediyorlar ki, kendilerine hiçbir güç verilmemiştir ve haklarında bir bilgiye de sahip değillerdir. Bu zalimlerin hiçbir yardımcısı yoktur."},{"n":72,"t":"Kendilerine apaçık ayetlerimiz okunduğunda, inkârcıların yüzünde inkârcılığı okursun. Kendilerine ayetlerimizi okuyanların üzerine neredeyse saldıracaklardır. De ki: \"Bundan daha kötüsünü size bildireyim mi? Ateş! ALLAH onu kafirlere vaadetmiştir. Ne kötü bir sonuçtur!\""},{"n":73,"t":"İnsanlar, işte size, dikkatle dinleyeceğiniz bir örnek: ALLAH’ın yanında hizmet ettikleriniz, toplansalar dahi bir sinek bile yaratamazlar. Hatta sinek onlardan bir şey kapsa onu ondan geri alamazlar. İsteyen de aciz, istenen de…"},{"n":74,"t":"Onlar ALLAH’a gereken değeri vermediler. ALLAH elbette Güçlüdür, Üstündür."},{"n":75,"t":"ALLAH meleklerden ve insanlardan elçiler seçer. Elbette ALLAH İşitendir, Görendir."},{"n":76,"t":"Onların geçmişini ve geleceğini bilir. Her şeyin nihai kontrol ve yönetimi ALLAH’a aittir."},{"n":77,"t":"Gerçeği onaylayanlar, eğiliniz, secde ediniz, Efendinize hizmet ediniz ve iyilik işleyiniz ki başarasınız."},{"n":78,"t":"Ve ALLAH uğrunda gereken çaba ve gayreti gösteriniz. O’dur sizi seçen. O, babanız İbrahim’in yolu olan bu dini, sizin için güç ve ağır kılmadı. Elçinin size tanık olması, sizin de halka tanık olmanız için, sizi, daha önce de şimdi de \"Müslümanlar = teslim olanlar\" olarak adlandıran O’dur. Namazı gözetin, zekatı verin ve ALLAH’a sarılın; Mevlanız (Sahibiniz) O’dur. Ne güzel sahip ve ne güzel Yardımcıdır!"}]},{"id":23,"name":"Mü'minun Suresi","verses":[{"n":1,"t":"Gerçeği onaylayanlar başarıya ulaşmışlardır."},{"n":2,"t":"Nitekim onlar namazlarında saygılıdırlar."},{"n":3,"t":"Boş sözlerden yüz çevirirler."},{"n":4,"t":"Zekatı pratiğe geçirirler."},{"n":5,"t":"Ve cinsel ilişkilerden sakınırlar;"},{"n":6,"t":"Ancak eşleri yani yeminlerinin/anlaşmalarının hak sahibi oldukları hariç. Onlar kınanmazlar."},{"n":7,"t":"Kim bunun ötesini ararsa sınırı aşmış olur."},{"n":8,"t":"Onlar ki kendilerine emanet edilen şeylere dikkat ederler. Verdikleri sözleri de yerine getirirler."},{"n":9,"t":"Onlar ki namazlarını düzenli olarak gözetirler."},{"n":10,"t":"İşte mirasçı olacaklar onlardır."},{"n":11,"t":"Bahçeye mirasçı olacak ve orada ebedi kalacaklar."},{"n":12,"t":"Biz, insanı özel bir balçıktan yarattık."},{"n":13,"t":"Sonra onu sağlam bir bekleme yerinde bir damlacık haline getirdik."},{"n":14,"t":"Sonra, o damlacığı, embriyo olarak biçimlendirdik, sonra embriyoyu dölüt olarak biçimlendirdik, sonra dölütü kemik olarak biçimlendirdik, sonra kemiğe et giydirdik ve sonra onu yeni bir yaratık haline soktuk. Biçim verenlerin en güzeli ALLAH çok yücedir."},{"n":15,"t":"Sonra siz, bunun ardından öleceksiniz."},{"n":16,"t":"Sonra siz, kıyamet (ayağa kalkış) günü diriltileceksiniz."},{"n":17,"t":"Üstünüzde yedi yol yarattık ve biz asla yaratıklardan habersiz olmadık."},{"n":18,"t":"Gökten belli bir oranda su indirdik ve onu toprakta depoladık. Kuşkusuz onu gidermeye de gücümüz yeter."},{"n":19,"t":"Onunla, sizin için birçok meyveler içeren hurma ve üzüm bahçeleri yaptık; onlardan yiyip duruyorsunuz."},{"n":20,"t":"Sina Dağı civarında yetişen ve yiyenler için yağ ve lezzet üreten bir ağaç…"},{"n":21,"t":"Çiftlik hayvanlarında sizin için bir ders vardır. Karınlarındaki maddeden sizi içiriyoruz, onlarda sizin için birçok yararlar mevcuttur; hatta onlardan yiyorsunuz."},{"n":22,"t":"Onların üzerinde ve gemiler üzerinde taşınıyorsunuz."},{"n":23,"t":"Nuh’u halkına göndermiştik de, \"Halkım, ALLAH’a hizmet ediniz. O’ndan başka bir tanrınız yoktur. Saygı duyup erdemli davranmaz mısınız?\" demişti."},{"n":24,"t":"Halkının ileri gelen inkârcıları, \"Bu, sizin gibi bir insandan başka bir şey değildir. Üzerinize egemen olmak istiyor. ALLAH dileseydi bir melek indirirdi. İlk atalarımızdan böyle bir şey işitmedik."},{"n":25,"t":"O, sadece deli bir adamdır. Hele bir süreye kadar onu gözleyin."},{"n":26,"t":"Dedi ki, \"Efendim, beni yalanlamalarına karşılık bana yardım et.\""},{"n":27,"t":"Bunun üzerine kendisine şöyle vahyettik: \"Gözümüzün önünde ve vahyimize uygun olarak gemiyi yap. Emrimiz gelince, kaynaklar kaynayıp taşınca her çeşit (evcil hayvanı) ve aleyhlerine hüküm verilmiş olanların dışındaki aileni al. Zalimler adına benimle konuşma; onlar boğulacaklardır.\""},{"n":28,"t":"\"Sen ve beraberindekiler gemiye yerleştiğinizde, ’Bizi o zalim halktan kurtaran ALLAH’a övgüler olsun,’ de.\""},{"n":29,"t":"\"Ve, ’Efendim, beni kutlu bir yere indir. Sen indirenlerin en iyisisin,’ de.\""},{"n":30,"t":"Bunda işaretler ve dersler vardır. Biz elbette sizleri denemekteyiz."},{"n":31,"t":"Sonra, onların ardından, başka bir soy yetiştirdik."},{"n":32,"t":"Onlara, aralarından bir elçi gönderdik: \"ALLAH’a hizmet ediniz, sizin ondan başka bir tanrınız yoktur. Saygı gösterip erdemli davranmayacak mısınız?\""},{"n":33,"t":"Dünya hayatında kendilerine alabildiğine nimetler bağışlamamıza rağmen, ahiret karşılaşmasını yalanlayıp inkâr eden, halkının ileri gelenleri şöyle dediler: \"Bu, yalnızca sizin gibi bir insandır. Sizin yediğinizden yiyor, sizin içtiğinizden içiyor.\""},{"n":34,"t":"\"Sizin gibi bir insana uyarsanız, siz o zaman gerçekten kaybedersiniz.\""},{"n":35,"t":"\"Siz öldükten, toprak ve kemik haline dönüştükten sonra, sizin geri çıkacağınızı mı söz veriyor?\""},{"n":36,"t":"\"Size söz verilen bu şey imkansızdır, imkansız!\""},{"n":37,"t":"\"Yaşantımız sadece bu dünyadadır. Yaşarız, ölürüz. Asla dirilecek değiliz.\""},{"n":38,"t":"\"O, ALLAH’a yalan yakıştıran bir adamdan başkası değildir. Biz onu onaylayacak değiliz.\""},{"n":39,"t":"Dedi ki, \"Efendim, yalanlamalarına karşılık bana yardım et.\""},{"n":40,"t":"Dedi ki, \"Az sonra onlar pişman olacaklardır.\""},{"n":41,"t":"Korkunç felaket onları hakettikleri şekilde yakaladı ve böylece onları süprüntü yığınına çevirdik. O zalim halk yok olmayı haketmişti."},{"n":42,"t":"Sonra, onların da ardından başka soylar yetiştirdik."},{"n":43,"t":"Hiçbir toplum kendisi için belirlenmiş süreyi çabuklaştıramaz, geciktiremez."},{"n":44,"t":"Sonra biz, elçilerimizi ardı ardına gönderdik. Her ne zaman bir elçi toplumuna gittiyse onu yalanladılar. Biz de onları birbiri peşinden sürüp tarihe gömdük. Gerçeği onaylamayan bir topluluk yok olmayı haketmiştir."},{"n":45,"t":"Sonra biz, Musa’yı ve kardeşi Harun’u ayetlerimizle ve apaçık bir delille gönderdik."},{"n":46,"t":"Firavun ve ileri gelen takımına… Ancak onlar büyüklendiler. Onlar küstah bir topluluk olmuştu."},{"n":47,"t":"\"O ikisinin halkı bize kölelik ederken şimdi biz tutup bizim gibi iki insanı mı onaylayalım\" dediler."},{"n":48,"t":"İkisini yalanladılar ve sonuç olarak yok edilenlerden oldular."},{"n":49,"t":"Doğruyu bulurlar diye Musa’ya Kitabı vermiştik."},{"n":50,"t":"Meryem oğlunu ve annesini bir işaret kıldık ve onları yerleşmeye elverişli ve pınarı olan bir tepede barındırdık."},{"n":51,"t":"Elçiler, iyi nimetlerden yiyiniz ve erdemli işler yapınız. Ben sizin yaptıklarınızı çok iyi bilirim."},{"n":52,"t":"Sizin bu toplumunuz bir tek toplumdur. Ben sizin Efendinizim; beni sayın."},{"n":53,"t":"Fakat, onlar işlerini çeşitli kitaplara ayırdılar. Her grup kendi yanında bulunandan hoşnut…"},{"n":54,"t":"Belli bir süreye kadar onları şaşkınlıkları içinde bırak."},{"n":55,"t":"Sanıyorlar mı ki, kendilerine bağışladığımız paralar ve çocuklar ile,"},{"n":56,"t":"Onların iyiliğine koşuyoruz? Hayır, farkında değiller."},{"n":57,"t":"Rab’lerine olan saygıdan ötürü alabildiğine dikkatli olanlar,"},{"n":58,"t":"Rab’lerinin ayetlerini onaylayanlar,"},{"n":59,"t":"Rab’lerine ortak koşmayanlar,"},{"n":60,"t":"Rab’lerine döneceklerinin bilincinde olarak verenler,"},{"n":61,"t":"İşte onlar, iyiliklerde yarışanlardır; ve onlar iyilik yapmada öncüdürler."},{"n":62,"t":"Bir kişiye ancak kapasitesi kadar yükleriz. Katımızda gerçeği konuşan bir kitap vardır. Hiç kimse haksızlığa uğratılmayacaktır."},{"n":63,"t":"Zihinleri bundan (mesajdan) gafil olup buna aykırı işlerde çalışıp durmaktadırlar."},{"n":64,"t":"Varlıklılarını cezaya çarptığımızda, yakınmaya başlarlar."},{"n":65,"t":"Yakınmayın; bugün tarafımızdan hiçbir yardım görmezsiniz."},{"n":66,"t":"Size ayetlerim okunuyordu da ardınıza dönüyordunuz."},{"n":67,"t":"Ona karşı büyüklük taslıyordunuz, saçmalayarak geceliyordunuz."},{"n":68,"t":"Onlar bu sözü incelemediler mi, yoksa geçmiş atalarına gelmeyen bir şey mi kendilerine geldi?"},{"n":69,"t":"Yoksa, kendilerine gönderilen elçiyi tanımadıkları için mi onu inkâr ediyorlar?"},{"n":70,"t":"Yoksa, onun deli olduğuna mı karar verdiler? Halbuki onlara gerçeği getirmişti. Ne var ki onların çoğu gerçekten hoşlanmaz."},{"n":71,"t":"Gerçek onların fantezilerine uysaydı, gökler, yer ve içlerindekiler kaosa girerdi. Halbuki onlara mesajlarını verdik, ancak çokları mesajlarından yüz çevirmekte."},{"n":72,"t":"Yoksa sen onlardan bir maaş mı istedin? Efendinin maaşı çok daha iyidir. O, rızık verenlerin en iyisidir."},{"n":73,"t":"Kuşku yok ki sen onları dosdoğru yola çağırıyorsun."},{"n":74,"t":"Ama ahireti onaylamayanlar yoldan sapmaktadırlar."},{"n":75,"t":"Kendilerine acıyıp başlarına gelen perişanlıklarını giderseydik bile, azgınlıklarına dalıp bocalayacaklardı."},{"n":76,"t":"Onları cezaya çarptırmamıza rağmen Rab’lerine boyun eğmediler, yalvarmadılar."},{"n":77,"t":"Kendilerine çetin bir azabın kapısını açtığımız zaman şaşırıp şoke oldular."},{"n":78,"t":"O’dur sizin için işitme, görme duyularını ve beyinler yaratan. Ne kadar da az şükrediyorsunuz!"},{"n":79,"t":"O’dur sizi yeryüzüne yerleştiren; O’nun huzurunda toplanacaksınız."},{"n":80,"t":"O’dur yaşatan ve öldüren; gecenin ve gündüzün değişmesi O’na bağlı. Aklınızı kullanmaz mısınız?"},{"n":81,"t":"Ancak onlar, öncekilerin dediklerini tekrarladılar."},{"n":82,"t":"Ve şöyle dediler: \"Biz öldüğümüz, toprak ve kemik olduğumuz zaman mı dirileceğiz?\""},{"n":83,"t":"\"Bize ve atalarımıza daha önce aynı şey söz verilmişti. Bu, geçmişlerin efsanesinden başka bir şey değildir.\""},{"n":84,"t":"De ki: \"Biliyorsanız, yer, gökler ve içlerinde bulunanlar kimindir?\""},{"n":85,"t":"\"ALLAH’ın\" diyecekler. De ki: \"Düşünmez misiniz?\""},{"n":86,"t":"De ki: \"Yedi göğün Rabbi, büyük yönetimin Rabbi kimdir?\""},{"n":87,"t":"\"ALLAH\" diyecekler. De ki: \"Öyleyse neden erdemli davranmıyorsunuz?\""},{"n":88,"t":"De ki: \"Biliyorsanız, koruyup kollayan, fakat kendisi korunup kollanmayan; her şeyin egemenliğini elinde bulunduran kimdir?\""},{"n":89,"t":"\"ALLAH\" diyeceklerdir. De ki: \"O halde nasıl da aldanıyorsunuz?\""},{"n":90,"t":"Kendilerine gerçeği getirmemize rağmen onlar yalanlamaktadırlar."},{"n":91,"t":"ALLAH çocuk edinmemiştir, O’nunla beraber bir tanrı da yoktur. Aksi taktirde her tanrı yarattığı şeylerle birlikte bağımsızlığını ilan ederek yönetim için bir biriyle çekişmeye girerdi. ALLAH, onların niteledikleri şeylerden çok uzaktır."},{"n":92,"t":"Tüm sırları ve tanık olunanları Bilendir; onların ortak koştukları şeylerden yücedir."},{"n":93,"t":"De ki: \"Efendim, onlara verilen sözü bana gösterirsen\""},{"n":94,"t":"\"Efendim, beni o zalim toplum içinde bırakma.\""},{"n":95,"t":"Biz elbette, kendilerine söz verileni sana gösterebiliriz."},{"n":96,"t":"Kötülüğe iyilikle karşılık ver. Biz onların iddialarını iyi biliriz."},{"n":97,"t":"Ve De ki: \"Efendim, sapkınların fısıltılarından sana sığınırım.\""},{"n":98,"t":"\"Yanımda bulunmalarından sana sığınırım, Efendim.\""},{"n":99,"t":"Onlardan birine ölüm gelip çattığı zaman şöyle der, \"Efendim, beni geri döndürünüz.\""},{"n":100,"t":"\"Ki terketmiş bulunduğum şeylerde erdemli işler yapayım.\" Hayır. Bu onun söylediği bir laftan ibarettir. Diriliş gününe kadar onların ardında bir engel vardır."},{"n":101,"t":"Boruya üfürüldüğünde o gün artık aralarında akrabalık yoktur ve birbirleriyle de ilgilenemezler."},{"n":102,"t":"Tartıları ağır gelenler, işte onlar kazanacaklardır."},{"n":103,"t":"Tartıları hafif gelenler ise, kendilerini zarara soktukları için cehennemde ebedi kalacak olanlardır."},{"n":104,"t":"Onlar orada perişan durumda iken, ateş de yüzlerini yalayacaktır."},{"n":105,"t":"Ayetlerim size okunmuyor muydu ve siz de onları yalanlamıyor muydunuz?"},{"n":106,"t":"\"Efendimiz\" diyecekler, \"Bizi talihsizliğimiz yendi; biz sapıtan bir toplum olduk.\""},{"n":107,"t":"\"Efendimiz, bizi buradan çıkar. Eğer (eski durumumuza) dönersek artık biz gerçekten zalimleriz.\""},{"n":108,"t":"Diyecek ki, \"Sinin orada, benimle konuşmayın.\""},{"n":109,"t":"\"Kullarımdan bir grup,’Efendimiz, gerçeği onayladık, bizi bağışla, bize merhamet et, sen merhamet edenlerin en merhametlisisin.’ derdi.\""},{"n":110,"t":"\"Sizse onları alaya aldınız ve onlar yüzünden beni anmayı unuttunuz. Onlara gülüp duruyordunuz.\""},{"n":111,"t":"\"Bugün ben, onlara sabretmelerinin karşılığını verdim. Kazananlar işte bunlardır.\""},{"n":112,"t":"Dedi ki, \"Yeryüzünde kaç sene kaldınız?\""},{"n":113,"t":"\"Birgün veya günün bir kısmı kadar kaldık. Sayanlara sor\" dediler."},{"n":114,"t":"Dedi ki, \"Siz gerçekten çok kısa bir süre kaldınız, keşke bilseydiniz.\""},{"n":115,"t":"\"Sizi boş yere yarattığımızı ve bize dönmeyeceğinizi mi sandınız?\""},{"n":116,"t":"Gerçek Yönetici olan ALLAH çok yücedir. O’ndan başka tanrı yoktur ve O, cömert yönetimin Rabbidir."},{"n":117,"t":"Her kim ALLAH ile birlikte, hiçbir delile sahip olmayan başka bir tanrıya da hizmet ederse, onun hesabı Efendinin katındadır. Kuşkusuz kafirler başaramazlar."},{"n":118,"t":"De ki: \"Efendim, (bizi) bağışla, merhamet et; sen, merhamet edenlerin en iyisisin.\""}]},{"id":24,"name":"Nur Suresi","verses":[{"n":1,"t":"Bu, indirerek yasa olarak yayımladığımız bir sure olup öğüt alasınız diye içine apaçık ayetler yerleştirdik."},{"n":2,"t":"Zina eden kadın ve erkeğin her birine yüz celde vurunuz. ALLAH’a ve ahiret gününe Gerçeği onaylıyorsanız, onlara olan acıma duygunuz ALLAH’ın yasasını uygulamakta size engel olmamalı. Gerçeği onaylayanlardan bir grup onların cezalandırılma işlemine tanık olsun."},{"n":3,"t":"Zina eden bir erkek, eninde sonunda, zina eden veya müşrik bir kadınla evlenir; zina eden bir kadın da eninde sonunda, zina eden veya müşrik bir erkekle evlenir. Bu, gerçeği onaylayanlar için yasaktır."},{"n":4,"t":"Korunan kadınları suçladıktan sonra dört tanık getiremeyenlere seksen celde vurun ve onların tanıklığını ebedi olarak kabul etmeyin. Onlar yoldan çıkmış kimselerdir."},{"n":5,"t":"Bununla birlikte, bundan sonra tövbe edip kendilerini düzeltenler için ALLAH Bağışlayandır, Rahimdir."},{"n":6,"t":"Eşlerini suçlayıp kendilerinden başka tanıkları olmayan erkeklerden birinin tanıklığı, doğru konuştuğuna dair dört kez ALLAH’a yemin etmesiyle geçerli olabilir."},{"n":7,"t":"Beşinci yeminde de, yalancı olduğu taktirde ALLAH’ın lanetinin kendisi üzerine olmasını diler."},{"n":8,"t":"Dört kez ALLAH’a yemin ederek kocasının yalan söylediğine tanıklıkta bulunduğu taktirde kadın cezayı savar."},{"n":9,"t":"Beşinci yeminde de, kocasının doğru olması halinde kendisinin ALLAH’ın gazabına uğramasını diler."},{"n":10,"t":"ALLAH size bağışı ve merhametiyle davranmasaydı, ALLAH Tövbeleri Kabul Eden ve Bilge olmasaydı…"},{"n":11,"t":"O iftirayı, sizden bir çete uydurdu. Onun sizin için kötü olduğunu sanmayın; aksine sizin için iyi (bir ders) dir. Bu arada, onlardan her biri günahı paylaşmıştır. Elebaşılık yapanları da büyük bir cezayı haketmiştir."},{"n":12,"t":"Onu işittiğinizde, siz gerçeği onaylayan erkek ve kadınların birbiriniz hakkında olumlu düşüncelere sahip olarak, \"Bu, açıkça büyük bir yalandır\" demeleri gerekmez miydi?"},{"n":13,"t":"Dört tanık getirmeli değiller miydi? Tanıklar getiremediklerine göre onlar ALLAH yanında yalancılardandır."},{"n":14,"t":"ALLAH’ın size dünya ve ahirette bağışı ve merhameti olmasaydı daldığınız o olaydan ötürü size büyük bir ceza dokunacaktı."},{"n":15,"t":"Onu dilinize dolamış ve hakkında bir bilginiz olmayan bir konuda ağzınızı açıp konuşuyordunuz. Onu basit bir şey sanmıştınız. Oysa o, ALLAH yanında büyüktür."},{"n":16,"t":"Onu işittiğinizde, \"Bunu konuşmamız doğru değil. Sen Yücesin. Bu büyük bir iftiradır!\" demeniz gerekmez miydi?"},{"n":17,"t":"Benzerini tekrarlamayasınız diye ALLAH size öğüt veriyor. Gerçeği onaylayanlar iseniz."},{"n":18,"t":"ALLAH size ayetlerini böyle açıklıyor. ALLAH Bilendir, Bilgedir."},{"n":19,"t":"Gerçeği onaylayanların arasından hayasızlığın yaygınlaşmasını arzulayanlar, dünyada ve ahirette acı verici bir cezayı haketmişlerdir. ALLAH bilir, siz bilmezsiniz."},{"n":20,"t":"ALLAH’ın size bağış ve rahmeti olmasaydı, ALLAH En Şefkatli ve Rahim (En Merhametli) olmasaydı..."},{"n":21,"t":"Ey gerçeği onaylayanlar, sapkının adımlarını izlemeyin. Kim sapkının adımlarını izlerse, kendisine hayasızlığı ve kötülüğü emreder. ALLAH’ın size bağışı ve merhameti olmasaydı sizden hiçbiriniz ebediyen temizlenemezdi. Ancak ALLAH dileyeni temizler. ALLAH İşitendir, Bilendir."},{"n":22,"t":"Sizden mal ve imkana sahip olanlar, akrabalara, yoksullara ve ALLAH yolunda göç edenlere vermemek için yemin etmesinler. Affetsinler, geçsinler. ALLAH’ın sizi bağışlamasını sevmez misiniz? ALLAH Bağışlayandır, Rahimdir."},{"n":23,"t":"Korunan ve (kötülüklerden) habersiz gerçeği onaylayan kadınlara iftira edenler, dünyada ve ahirette lanetlenirler ve onlar için büyük bir ceza vardır."},{"n":24,"t":"O gün ki, dilleri, elleri ve ayakları onların yapmış oldukları her şeye tanıklık edeceklerdir."},{"n":25,"t":"ALLAH o gün, hakettiklerini tam olarak ödeyecek ve ALLAH’ın apaçık bir gerçek olduğunu öğreneceklerdir."},{"n":26,"t":"Kötü kadınlar, kötü erkekler için, kötü erkekler de kötü kadınlar içindir. İyi kadınlar iyi erkekler için ve iyi erkekler de iyi kadınlar içindir. Bunlar (ikinci grup), onların söylentilerinden uzaktır. Bunlar bağışlanma ve cömert bir ödül haketmişlerdir."},{"n":27,"t":"Ey gerçeği onaylayanlar, evlerinizden başka evlere, izin almadan, halkına selam vermeden girmeyiniz. Düşünürseniz bunun sizin için daha iyi olduğunu görürsünüz."},{"n":28,"t":"Orada hiç kimseyi bulamazsanız (yetkililer tarafından) izin verilmeden oraya girmeyiniz. Size \"Geri dönün\" dendiğinde dönüp gidiniz. Bu, sizin için daha temiz bir davranıştır. ALLAH yaptıklarınızı Bilendir."},{"n":29,"t":"Oturulmayan ve içinde eşyanız bulunan bir eve girmenizde bir sakınca yoktur. ALLAH açığa vurduklarınızı da gizlediklerinizi de bilir."},{"n":30,"t":"Gerçeği onaylayanlara, gözlerini sakınmalarını (kadınlara gözünü dikip bakmamalarını) ve iffetlerini korumalarını bildir. Bu, onlar için daha temiz bir davranıştır. Elbette ALLAH yaptıklarından haberdardır."},{"n":31,"t":"Gerçeği onaylayan kadınlara da söyle, gözlerini sakınsınlar, iffetlerini korusunlar ve açıkta olması gereken yerleri hariç, alımlı yerlerini göstermesinler. Örtülerini göğüslerinin üzerine kapasınlar. Vücutlarının alımlı yerlerini kimseye göstermesinler; ancak kocaları, babaları, kocalarının babaları, oğulları, kocalarının oğulları, kardeşleri, erkek kardeşlerinin oğulları, kızkardeşlerinin oğulları, diğer kadınlar, cinsel iktidara sahip olmayan erkek hizmetkarlar ve işçiler ve kadınların cinsel yönlerini henüz anlamayan çocuklar hariç. Gizledikleri alımlı bölgelerini sergilemek/bildirmek için ayaklarını yere vurmasınlar. Ey gerçeği onaylayanlar, topluca ALLAH’a yöneliniz ki başarılı olasınız."},{"n":32,"t":"Bekarlarınızı, kadın ve erkek hizmetkarlarınızdan erdemli olanları evlendiriniz; eğer yoksul iseler, ALLAH onları kendi lütfundan zengin edecektir. ALLAH Cömerttir, Bilendir."},{"n":33,"t":"Evlenme imkanına sahip olmayanlar da, ALLAH kendilerini lütfuyla zenginleştirene kadar iffetli davransınlar. Yeminleriniz /anlaşmalarınız yoluyla hak sahibi olduklarınızdan yazılı belge isteyenler olursa –niyetleri dürüstse– karşılıklı yazışınız. Ve ALLAH’ın size verdiği parasından onlara veriniz. İffetli olmak isteyen kızlarınızı, bu dünyanın geçici menfaatini arzulayarak fuhuşa zorlamayın. Kim onları zorlarsa, o zaman ALLAH onların zorlandığını hesaba katar; O Bağışlayandır, Rahimdir."},{"n":34,"t":"Size apaçık ayetler, sizden önce geçmiş kimselerden örnekler ve erdemliler için bir öğüt indirmiş bulunuyoruz."},{"n":35,"t":"ALLAH göklerin ve yerin ışığıdır. Işığının örneği şuna benzer: İçinde lamba bulunan bir oyuk… Lamba bir cam kap içindedir. O cam kap ise, inci gibi (parlak ve yuvarlak) bir gezegen gibidir. Yakıtı, ne batıya ne de doğuya bağıntısı olmayan, zeytinyağı üreten bereketli bir ağaçtandır. Yağı, neredeyse ateş değmeden aydınlık verir. Işık üzerine ışıktır. ALLAH dileyeni/dilediğini ışığına ulaştırır. İşte ALLAH halka böyle örnekler verir. ALLAH her şeyi bilir."},{"n":36,"t":"(Böyle bir ışık ve hidayet), içlerinde ismi anıldığı için ALLAH’ın onaylayıp yükselttiği evlerdedir. Orada, O’nu sabah akşam yücelten…"},{"n":37,"t":"Kişiler vardır. Onları, ALLAH’ı anmaktan, namazı gözetmekten ve zekatı vermekten ne bir iş ne de bir ticaret alıkoymaz. Onlar, kalplerin ve gözlerin ters döneceği günden korkarlar."},{"n":38,"t":"ALLAH onların güzel işlerini kuşkusuz ödüllendirecek ve onlara lütfunu arttıracaktır. ALLAH dilediğini hesapsız olarak rızıklandırır."},{"n":39,"t":"İnkarcılara gelince, işleri, çöldeki bir serap gibidir. Susayan onu su sanır. Yanına varınca onu bulamaz, ancak orada ALLAH’ı bulur; O da onun hesabını tam görür. Kuşkusuz ALLAH hesabı çabuk görendir."},{"n":40,"t":"Yahut, yoğun bir sisle birlikte dalga üstüne dalganın örttüğü engin bir denizin ortasındaki karanlıklara benzer. Üstüste yığılmış karanlıklar… İnsan elini uzattığı zaman nerdeyse onu bile göremez. ALLAH’ın ışıktan yoksun bıraktığı kimsenin hiçbir ışığı olamaz."},{"n":41,"t":"Diziler halinde uçan kuşlar dahil, göklerde ve yerde bulunan herkesin ALLAH’ı yücelttiğini görmez misin? Her birisi kendi duasını ve yüceltme yöntemini bilir. ALLAH onların yaptıklarını iyi bilir."},{"n":42,"t":"Göklerin ve yerin yönetimi ALLAH’a aittir. Dönüş de ALLAH’adır."},{"n":43,"t":"Bilmez misin ki ALLAH bulutları sürer, sonra onları birleştirir, sonra onları birbiri üstüne yığar ve sen de yağmurun onların arasından çıktığını görürsün? Gökten büyük kütlelerden dolu yağdırır, dilediği kimseyi ona uğratır ve dilediğinden de onu uzak tutar. Şimşeğinin parıltısı neredeyse gözleri alır."},{"n":44,"t":"ALLAH gece ile gündüzü çevirip kontrol eder. Gözleri olanlar için elbette bunda bir ders vardır."},{"n":45,"t":"ALLAH bütün canlıları sudan yaratır. Onlardan kimi karnı üzerinde hareket eder, kimi iki ayakları üzerinde yürür, kimi de dört ayak üzerinde yürür. ALLAH dilediğini yaratır. ALLAH her şeye gücü yetendir."},{"n":46,"t":"Apaçık ayetler indirmiş bulunuyoruz. ALLAH dilediğini/ dileyeni dosdoğru yola iletir."},{"n":47,"t":"\"ALLAH’ı ve elçiyi onayladık ve itaat ettik\" derler. Fakat sonra, bunun ardından, onlardan bir grup yüz çevirir; bunlar gerçeği onaylamış değildir."},{"n":48,"t":"Aralarında hüküm vermesi için ALLAH’a ve elçisine çağrıldıkları zaman onlardan bir grup hoşlanmaz."},{"n":49,"t":"Ancak karar lehlerine olursa, ona gönüllü koşarlar."},{"n":50,"t":"Kalplerinde bir hastalık mı var? Kuşku mu duyuyorlar? ALLAH’ın ve elçisinin kendilerine haksızlık yapacağından mı korkmaktadırlar? Aslında onlar zalimlerdir."},{"n":51,"t":"Aralarında hüküm vermek üzere, ALLAH’a ve elçisine çağrıldıkları zaman gerçeği onaylayanlar yalnızca şunu söylerler: \"İşittik ve uyduk.\" Kazananlar işte bunlardır."},{"n":52,"t":"ALLAH’a ve elçisine uyan, ALLAH’ı sayıp O’nu dinleyen kimseler üstün gelenlerdir."},{"n":53,"t":"Kendilerine emrettiğin taktirde çıkacaklarına (yola veya savaşa) dair yeminlerinin en ciddi olanıyla ALLAH’a yemin ettiler. De ki: \"Yemin etmeyin. Nasıl itaat ettiğiniz ortada. ALLAH yaptığınız her şeyden haberdardır.\""},{"n":54,"t":"De ki: \"ALLAH’a ve elçiye uyunuz. Reddederseniz, o kendi görevinden sorumludur, siz de kendi görevinizden sorumlusunuz. Ona uyarsanız, doğruyu bulursunuz. Elçinin tek görevi, mesajı açıkça bildirmekten ibarettir.\""},{"n":55,"t":"ALLAH, gerçeği onaylayıp erdemli davrananlarınızı, kendilerinden öncekileri egemen kıldığı gibi onları da egemen yapacağına, kendileri için seçtiği dini yerleştireceğine ve korkularını güvene çevireceğine söz vermiştir. Çünkü onlar bana hizmet ederler ve bana hiçbir şeyi ortak koşmazlar. Bundan sonra inkâr edenler, yoldan çıkmış olanlardır."},{"n":56,"t":"Namazı gözetiniz, zekatı veriniz ve elçiye uyunuz ki merhamet edilesiniz."},{"n":57,"t":"İnkar edenlerin bizi aciz bırakacaklarını sanmayın. Onların varacağı yer ateştir; ne kötü bir varış noktasıdır."},{"n":58,"t":"Ey gerçeği onaylayanlar, yeminlerinizin/anlaşmalarınızın hak sahibi oldukları ve sizden henüz erginliğe ermemiş olanlar üç kez izin almalıdırlar: Sabah namazından önce, öğle vaktinde dinlenmek için elbisenizi çıkardığınız zaman ve Akşam namazından sonra… Bunlar, sizin özel üç vaktinizdir. Bunların dışında, birbirinizin yanına girip çıkmakta bir sakınca yoktur. ALLAH ayetleri size böyle açıklar. ALLAH Bilendir, Bilgedir."},{"n":59,"t":"Çocuklarınız erginlik çağına erişince, kendilerinden önceki yetişkinlerin izin istedikleri gibi onlar da (özel odanıza girmeden önce) izin istesinler. ALLAH ayetlerini size böyle açıklar. ALLAH Bilendir, Bilgedir."},{"n":60,"t":"Evlenme beklentisi olmayan yaşlı kadınların, alımlı yerlerini açıp saçmamak koşuluyla dış elbiselerini bırakmalarında bir sakınca yoktur. İffetli davranmaları kendileri için daha iyidir. ALLAH İşitendir, Bilendir."},{"n":61,"t":"Siz, evlerinizde, babalarınızın evlerinde, annelerinizin evlerinde, kardeşlerinizin evlerinde, kızkardeşlerinizin evlerinde, amcalarınızın evlerinde, halalarınızın evlerinde, dayılarınızın evlerinde, teyzelerinizin, anahtarlarına sahip olduğunuz ve arkadaşlarınızın evlerinde yemenizden dolayı kınanmazsınız. Aynı şekilde kör kınanmaz, topal kınanmaz, sakat ve hasta da kınanmaz. Topluca yahut ayrı ayrı yemenizde de bir sakınca yoktur. Bir eve girdiğinizde ALLAH’tan güzel, kutlu bir yaşam dileyerek selamlayınız. ALLAH size ayetleri böyle açıklar ki anlayasınız."},{"n":62,"t":"Gerçek gerçeği onaylayanlar, ALLAH’a ve elçisini onaylayan ve toplumsal bir sorun için onunla beraber iken ondan izinsiz terketmeyenlerdir. Senden izin isteyenler, ALLAH’a ve elçisini onaylayanlardır. Bazı işleri için senden izin istediklerinde dilediğine izin verebilirsin. Onlar için ALLAH’tan bağışlanma dile. ALLAH Bağışlayandır, Rahimdir."},{"n":63,"t":"Elçinin davetini, aranızda herhangi birinin diğerini davet etmesi gibi tutmayın. ALLAH sizden eften püften özürler göstererek sıvışıp gidenleri biliyor. Onun emirlerine aykırı davrananlar, başlarına bir felaketin gelmesinden veya acı bir cezaya çarpılmaktan sakınsınlar."},{"n":64,"t":"Göklerde ve yerde olanlar hep ALLAH’a aittir. İçinde bulunduğunuz her durumu bilir. Nitekim kendisine döndürülecekleri gün, yaptıkları her şeyi onlara bildirecektir. ALLAH her şeyi bilendir."}]},{"id":25,"name":"Furkan Suresi","verses":[{"n":1,"t":"Tüm dünyaya bir uyarı olarak, Yasalar Kitabını kuluna indiren çok Yücedir."},{"n":2,"t":"Göklerin ve yerin yönetimi O’na aittir. Çocuk edinmemiştir, yönetiminde de kendisinin ortağı yoktur. Her şeyi yaratmış ve en ayrıntılı ölçülerle ona düzen vermiştir."},{"n":3,"t":"Buna rağmen O’nun yanında, bir şey yaratamayan, kendileri yaratılan, kendilerine bile yarar ve zarar veremeyen, öldüremeyen, yaşatamayan ve diriltemeyen bir takım tanrılar edindiler."},{"n":4,"t":"İnkar edenler, \"Bu, başkalarının yardımıyla onun uydurduğu bir yalandan başka bir şey değildir\" diyerek haksız ve asılsız bir tez ortaya koydular."},{"n":5,"t":"Dediler, \"Yazıp durduğu şey evvelkilerin masallarıdır; gece gündüz kendisine dikte edilmektedir.\""},{"n":6,"t":"De ki: \"Onu, göklerin ve yerin gizliliklerini bilen indirmiştir. O, Bağışlayandır, Rahimdir.\""},{"n":7,"t":"Ve dediler, \"Nasıl olur da bu elçi yemek yiyor ve çarşılarda dolaşıyor? Kendisiyle birlikte uyarıcı olarak bir melek inseydi ya!\""},{"n":8,"t":"\"Yahut kendisine bir hazine atılsaydı veya kendisinin bir bahçesi olsaydı ve ondan yeseydi!\" Hatta zalimler, \"Siz, büyülenmiş bir adama uyuyorsunuz!\" dediler."},{"n":9,"t":"Bak, senin için ne örnekler verdiler de saptılar, yolu asla bulamayacaklardır."},{"n":10,"t":"Dilerse sana, bunlardan daha iyi olan, içlerinden ırmaklar akan bahçeler ve köşkler verebilen O çok yücedir."},{"n":11,"t":"Doğrusu, onlar o anı yalanladılar. O anı yalanlayanlara alevli cehennemi hazırladık."},{"n":12,"t":"Cehennem onları uzaktan görünce, onun öfkesini ve uğultusunu işitirler."},{"n":13,"t":"Zincirlenmiş olarak onun dar bir yerinden atıldıkları zaman yok olmayı isterler."},{"n":14,"t":"Bugün bir yok oluş değil, birçok yok oluş isteyin."},{"n":15,"t":"De ki: \"Bu mu, yoksa erdemlilere bir karşılık ve dönüş yeri olarak söz verilmiş ebedi bahçe mi daha iyi?\""},{"n":16,"t":"Onlar orada ebedi olarak dilediklerini elde ederler. Bu, Rabbinin mutlak surette gerçekleşecek sözüdür."},{"n":17,"t":"Onları ve onların ALLAH’tan başka hizmet ettikleri topladığı gün, \"Bu kullarımı siz mi saptırdınız, yoksa onlar mı yolu sapıttılar?\" der."},{"n":18,"t":"\"Sen yücesin, senin yanında kimseyi veliler kabul etmek bize yakışmaz. Fakat, sen onlara ve atalarına nimetler bağışladın. Nihayet, onlar mesajı unutup yozlaşan bir toplum oldular\" diye karşılık verdiler."},{"n":19,"t":"Onlar sizin bu söylediklerinizi yalanlamış bulunuyorlar. Siz ne veto edebilir, ne de yardım edebilirsiniz. Hatta sizden zulmeden olursa ona da büyük bir azap tattırırız."},{"n":20,"t":"Senden önce gönderdiğimiz tüm elçiler de yemek yerler, çarşılarda dolaşırlardı. Sizi birbiriniz için bir sınav yaptık; dayanabilecek misiniz? Efendin Görendir."},{"n":21,"t":"Bizimle karşılaşmayı ummayanlar, \"Bize ya melekler inmeli, yahut Efendimizi görmeliyiz!\" dediler. Kendi kendilerine büyüklük taslamışlar ve azgınlıkta pek ileri gitmişlerdi."},{"n":22,"t":"Denetçileri gördükleri gün, suçlular için iç açıcı birgün olmayacaktır. \"Tümüyle kuşatıldık!\" derler."},{"n":23,"t":"Yapmış oldukları işlere bakar ve onları tamamıyla etkisiz hale getiririz."},{"n":24,"t":"O gün bahçe halkının kalacağı yer çok daha iyi olup daha güzel haberler işiteceklerdir."},{"n":25,"t":"Göğün bulut kütleleri halinde parçalanacağı ve meleklerin topluca indirildiği gün,"},{"n":26,"t":"İşte o gün, yönetim tümüyle ve mutlak olarak Rahman’ındır. İnkarcılar için zor birgün olacaktır."},{"n":27,"t":"O gün zalim kimse (üzüntüden) elini ısırıp şöyle der: \"Keşke, elçi ile birlikte aynı yolu tutsaydım.\""},{"n":28,"t":"\"Vay bana, keşke falancayı arkadaş edinmeseydim.\""},{"n":29,"t":"\"Beni, bana ulaşan mesajdan saptırdı. Gerçekten, sapkın insanı yarı yolda bırakır.\""},{"n":30,"t":"Elçi de \"Efendim, halkım Kuran’ı terketti\" der."},{"n":31,"t":"Biz ayrıca her peygambere suçlulardan bir düşman var ettik. Yol gösterici ve yardımcı olarak Efendin yeter."},{"n":32,"t":"İnkarcılar, \"Kuran, ona neden bir defada indirilmedi?\" dediler. Biz böylece onu belleğine yerleştirmekte ve onu belirlenmiş bir dizilişe göre okumaktayız."},{"n":33,"t":"Onların sana yönelttikleri her teze karşı, biz sana gerçeği ve en güzel açıklamayı getiririz."},{"n":34,"t":"Cehenneme zorla sürülenler, en kötü yere ve en çarpık yola sahip olanlardır."},{"n":35,"t":"Biz Musa’ya kitabı vermiş ve kardeşi Harun’u da kendisine yardımcı olarak atamıştık."},{"n":36,"t":"\"Siz ikiniz, ayetlerimizi yalanlayan şu topluma gidin\" dedik. Bunun ardından onları yakıp yok ettik."},{"n":37,"t":"Benzer şekilde, Nuh’un toplumu da elçileri yalanlayınca, halk için bir ders olsun diye onları boğduk. Zalimler için acı bir ceza hazırlamışızdır."},{"n":38,"t":"Ad, Semud, Res halkı ve bunların arasında birçok nesilleri de…"},{"n":39,"t":"Hepsine yeterli örnekler vermiştik, sonunda hepsini kırdık geçirdik."},{"n":40,"t":"Felaket yağmuruna tutulmuş bulunan ülkenin (Sodom) yanından geçmiş bulunuyorlar. Onu görmediler mi? Aslında onlar yeniden dirilmey gerçeğini onaylamıyorlardı."},{"n":41,"t":"Seni her gördüklerinde seni alaya alırlar: \"ALLAH’ın elçi olarak gönderdiği kişi bu mu?\""},{"n":42,"t":"\"Direnmeseydik, neredeyse bizi tanrılarımızdan saptırıp ayıracaktı.\" Azabı gördüklerinde kimin gerçekten sapık yolda olduğunu öğreneceklerdir."},{"n":43,"t":"Egosunu tanrı edinen kişiyi gördün mü? Sen mi ona avukatlık edeceksin?"},{"n":44,"t":"Onların çoğunun gerçekten işittiklerini yahut anladıklarını mı sanıyorsun? Onlar sadece çiftlik hayvanları gibidir; hayır, yolca daha da sapıktırlar."},{"n":45,"t":"Efendinin gölgeyi nasıl uzattığına dikkat ettin mi? Nitekim dileseydi onu hareketsiz de yapardı. Nitekim, güneşi ona delil kıldık (gölgenin varlığını ışığa bağlı kıldık)."},{"n":46,"t":"Sonra onu yavaş yavaş çekip alırız."},{"n":47,"t":"Ve O, geceyi size bir örtü, uykuyu bir dinlenme ve gündüzü de bir dirilme zamanı yapandır."},{"n":48,"t":"Ve O, rahmetinden önce müjdeleyici olarak rüzgarları gönderendir. Ve biz gökten tertemiz bir su indiririz."},{"n":49,"t":"Ki onunla ölü bir ülkeyi diriltelim ve yarattığımız nice çiftlik hayvanlarını ve insanları onunla sulayalım."},{"n":50,"t":"Öğüt almaları için onu aralarında dağıtıp çevirdik. Ne var ki insanların çoğunluğu nankörlükte diretmektedir."},{"n":51,"t":"Dileseydik her kente bir uyarıcı gönderirdik."},{"n":52,"t":"Öyleyse, inkârcılara uyma ve bununla (bu Kuran ile) onlara karşı büyük bir cihad ile savaşım ver."},{"n":53,"t":"O, iki denizi salmıştır; bu taze ve tatlıdır, şu tuzlu ve acıdır. Her ikisinin arasına, karışmalarını engelleyen sağlam bir engel koymuştur."},{"n":54,"t":"Ve O, sudan bir insan yarattı ve ona soy sop verdi. Efendin her şeye gücü yetendir."},{"n":55,"t":"ALLAH’ın yanısıra kendilerine ne yarar ve ne de zarar veremeyenlere de hizmet ediyorlar. İnkarcı kimse Efendisine karşı çıkandır."},{"n":56,"t":"Biz seni bir müjdeleyici ve uyarıcı olmaktan başka bir görevle göndermedik."},{"n":57,"t":"De ki: \"Ben görevime karşılık sizden herhangi bir ücret istemiyorum. Sadece, Efendisine ulaşacak yolu arayanlar olmanızı istiyorum.\""},{"n":58,"t":"Ölümsüz ve Diri olana güven; O’nu överek yücelt. Kullarının günahlarını, O’nun bilmesi yeter."},{"n":59,"t":"O ki gökleri, yeri ve aralarındakileri altı günde yarattı ve sonra tüm otoritesini kurdu. Rahman’dır; O’nu iyi bilenlere sor."},{"n":60,"t":"Onlara, \"Rahman’a secde edin\" dendiği zaman, \"Rahman da neymiş? Senin bize karşı savunduğun şeye mi secde edeceğiz?\" derler. Ve bu, ancak onların nefretini arttırır."},{"n":61,"t":"Göğe takım yıldızlar vareden ve ona bir lamba ve parlayan bir ay yerleştiren çok yücedir."},{"n":62,"t":"O, geceyi ve gündüzü birbirini izler yaptı; öğüt almak veya şükretmek isteyenler için…"},{"n":63,"t":"Rahman’ın kulları öyle kimselerdir ki yeryüzünde gösterişsizce yürürler. Cahiller kendilerine laf atınca da barış önerirler."},{"n":64,"t":"Gecenin yalnızlığında Rab’lerine secde edip düşünceye dalarlar."},{"n":65,"t":"Ve onlar şöyle derler, \"Efendimiz, cehennem cezasını bizden çevir. Onun cezası korkunçtur.\""},{"n":66,"t":"\"O kötü bir durak ve kötü bir yerdir.\""},{"n":67,"t":"Onlar verirken savurganlık ve cimrilik yapmaz, ikisi arasında dengeli harcarlar."},{"n":68,"t":"Onlar, ALLAH ile birlikte başka tanrılar çağırmazlar; ALLAH’ın yasakladığı canı haksız yere öldürmezler ve zina etmezler. Bunları işleyen, günahların faturasını öder."},{"n":69,"t":"Diriliş günü cezaları katlanır ve horlanmış olarak orada ebedi kalırlar."},{"n":70,"t":"Ancak gerçeği onaylayıp erdemli bir yaşam sürenler hariç. ALLAH onların günahlarını iyiliklere çevirir. ALLAH Bağışlayandır, Rahimdir."},{"n":71,"t":"Tövbe edip iyi davrananlar ise ALLAH’a gereği gibi dönmüş olur."},{"n":72,"t":"Onlar yalan tanıklıkta bulunmazlar. Boş sözlerle karşılaştıklarında önemsemeyip geçerler."},{"n":73,"t":"Kendilerine Rab’lerinin ayetleri hatırlatıldığında, onlara karşı sağır ve kör davranmazlar."},{"n":74,"t":"Onlar ki \"Efendimiz, eşlerimizi, çocuklarımızı bizim için bir mutluluk kaynağı yap ve bizi önde giden erdemlilerden kıl\" derler."},{"n":75,"t":"Bunlar, sabrettiklerinden ötürü bahçe odalarıyla ödüllendirilirler; orada mutlu bir yaşam ve barışa kavuşturulurlar."},{"n":76,"t":"Orada ebedi kalıcıdırlar. Ne güzel bir duraktır, ne güzel bir yerdir."},{"n":77,"t":"De ki: \"Duanız olmasa Efendimin yanında değeriniz yoktur. Yalanlarsanız sonucuna katlanacaksınız.\""}]},{"id":26,"name":"Şu'ara Suresi","verses":[{"n":1,"t":"T. S. M."},{"n":2,"t":"Bunlar (harfler), açıklayıcı kitabın mucizeleridir."},{"n":3,"t":"Gerçeği onaylamıyorlar diye kendini kahrediyor olabilirsin."},{"n":4,"t":"Dilesek onların üzerine gökten bir mucize indiririz de ona boyun eğip kalırlar."},{"n":5,"t":"Her ne zaman Rahman’dan kendilerine yeni bir mesaj gelse, mutlaka ondan yüz çevirirler."},{"n":6,"t":"Yalanladıkları için, eğlenceye aldıkları şeylerin haberleri kendilerine ulaşacaktır."},{"n":7,"t":"Yeryüzüne bakmazlar mı, onda değişik türden nice güzel bitkiler bitirmişiz."},{"n":8,"t":"Bunda bir işaret vardır. Ama çokları onaylayacak değildir."},{"n":9,"t":"Kuşkusuz senin Efendin Güçlüdür, Rahimdir."},{"n":10,"t":"Bir zamanlar Efendin Musa’ya seslenmişti: \"O zalim topluma git.\""},{"n":11,"t":"\"Firavunun halkına... Dinleyip düzelmeyecekler mi?\""},{"n":12,"t":"Dedi ki, \"Efendim, onların beni yalanlamalarından korkuyorum.\""},{"n":13,"t":"\"Göğsüm daralıyor, dilim açılmıyor; kardeşim Harun’u gönder.\""},{"n":14,"t":"\"Ayrıca, onların yanında suçlu biriyim. Korkarım ki beni öldürsünler.\""},{"n":15,"t":"Dedi ki, \"Hayır, siz ikiniz ayetler (vahiy ve mucizeler)imizle gidin. Biz sizinle birlikteyiz; dinliyoruz.\""},{"n":16,"t":"\"İkiniz Firavuna varıp deyin ki, ’Biz evrenlerin Efendisinin elçileriyiz.\""},{"n":17,"t":"\"İsrailoğullarını bizimle birlikte gönder.\""},{"n":18,"t":"Dedi ki, \"Biz seni daha bebekken alıp yetiştirmedik mi ve hayatının nice yıllarını aramızda geçirmedin mi?\""},{"n":19,"t":"\"Sonunda yapacağını yaptın. Sen nankör birisin.\""},{"n":20,"t":"Dedi ki, \"O işi yaptığım zaman yanlış yoldaydım.\""},{"n":21,"t":"\"Sonra, sizden korktuğum için sizden kaçtım ve Efendim bana bilgelik verip beni elçilikle görevlendirdi.\""},{"n":22,"t":"\"Başıma kaktığın bu iyilik de, İsrailoğullarını köleleştirmen yüzündendir!\""},{"n":23,"t":"Firavun, \"Evrenlerin Rabbi de ne demek?\" dedi."},{"n":24,"t":"Dedi ki, \"Kesinlikle gerçeği onaylayacaksanız O, göklerin, yerin ve aralarındakilerin Rabbidir.\""},{"n":25,"t":"Etrafındakilere dönerek, \"İşitiyor musunuz?\" dedi."},{"n":26,"t":"Dedi ki, \"Sizin Efendiniz ve evvelki atalarınızın Rabbidir.\""},{"n":27,"t":"Dedi ki, \"Size gönderilen elçi, kesinlikle bir deli.\""},{"n":28,"t":"Dedi ki, \"Aklınızı kullanıyorsanız, O doğunun, batının ve aralarındakilerin de Rabbidir.\""},{"n":29,"t":"Dedi ki, \"Benden başka bir tanrı (otorite) edinirsen seni hapis cezasına çarpacağım.\""},{"n":30,"t":"Dedi ki, \"Size apaçık bir şey getirmiş olsam da mı?\""},{"n":31,"t":"Dedi ki, \"Doğru sözlüysen getir bakalım onu.\""},{"n":32,"t":"Değneğini atınca apaçık bir yılan oluverdi."},{"n":33,"t":"Elini çıkarınca bakanlara bembeyaz görünüverdi."},{"n":34,"t":"Çevresindeki ileri gelenlere dedi ki, \"Bu, gerçekten çok usta bir büyücü imiş.\""},{"n":35,"t":"\"Büyüsüyle sizi toprağınızdan çıkarmak istiyor. Ne önerirsiniz?\""},{"n":36,"t":"Dediler ki, \"Onu ve kardeşini alıkoy ve kentlere toplayıcılar gönder de\""},{"n":37,"t":"\"Sana tüm usta büyücüleri getirsinler.\""},{"n":38,"t":"Belirlenmiş günün randevusu için büyücüler bir araya getirildiler."},{"n":39,"t":"Halka da, \"Siz de toplanır mısınız?\" denildi."},{"n":40,"t":"\"Büyücüler üstün gelirse onlara uyabiliriz.\""},{"n":41,"t":"Büyücüler geldiklerinde Firavuna, \"Eğer biz üstün gelirsek bize bir ücret ödenecek mi?\" dediler."},{"n":42,"t":"\"Evet\" dedi, \"Hatta siz benim konseyime gireceksiniz.\""},{"n":43,"t":"Musa onlara, \"Atacağınızı atın\" dedi."},{"n":44,"t":"İplerini ve değneklerini attılar, \"Firavunun onuru için biz üstün geleceğiz\" dediler."},{"n":45,"t":"Sonra Musa değneğini attı; hemen onların uydurduklarını yutmaya başladı."},{"n":46,"t":"Büyücüler secdeye kapandılar."},{"n":47,"t":"Dediler, \"Evrenlerin Efendisini onayladık\""},{"n":48,"t":"\"Musa’nın ve Harun’un Efendisine…\""},{"n":49,"t":"Dedi ki, \"Ben size izin vermeden mi onu onayladınız? O, size büyücülüğü öğreten ustanız olmalı. Şimdi göreceksiniz: Ellerinizi, ayaklarınızı çaprazlama keseceğim ve hepinizi asacağım.\""},{"n":50,"t":"\"Umurumuzda değil\" dediler, \"Biz zaten Efendimize döneceğiz.\""},{"n":51,"t":"\"İlk gerçeği onaylayanlar olduğumuz için umarız ki Efendimiz hatalarımızı bağışlar.\""},{"n":52,"t":"Musa’ya, \"Kullarımı yola çıkar, siz izleneceksiniz\" diye vahyettik."},{"n":53,"t":"Firavun, kentlere kitle propagandacıları gönderdi:"},{"n":54,"t":"\"Bunlar küçük bir çetedir.\""},{"n":55,"t":"\"Bize karşı öfkeyle ayaklanmaktadırlar.\""},{"n":56,"t":"\"Biz ise çoğunluk olarak alarmda olmalıyız.\""},{"n":57,"t":"Sonunda, onları çıkardık: Bahçelerden, çeşmelerden,"},{"n":58,"t":"Hazinelerden, yüksek makamlardan…"},{"n":59,"t":"Daha sonra onları İsrailoğullarına miras yaptık."},{"n":60,"t":"Onları doğuya doğru izlediler."},{"n":61,"t":"Her iki topluluk birbirini görünce, Musa’nın arkadaşları, \"İşte yakalanıyoruz\" dediler."},{"n":62,"t":"\"Asla. Efendim benimle birliktedir; bana bir çıkış yolu gösterecektir\" dedi."},{"n":63,"t":"Musa’ya, \"Değneğini denize vur\" diye vahyettik. Bunun üzerine yarıldı ve her bölüm koca bir tepe gibi oldu."},{"n":64,"t":"Sonra, diğerlerini yaklaştırdık."},{"n":65,"t":"Musa’yı ve kendisiyle beraber olan herkesi kurtardık."},{"n":66,"t":"Sonra, diğerlerini boğduk."},{"n":67,"t":"Elbette bunda bir ders vardır; ama çokları onaylamaz."},{"n":68,"t":"Kuşkusuz, senin Efendin Üstündür, Rahimdir."},{"n":69,"t":"Onlara İbrahim’in tarihini anlat."},{"n":70,"t":"Babasına ve halkına, \"Neye hizmet ediyorsunuz?\" demişti."},{"n":71,"t":"\"Heykellere hizmet ediyoruz; biz kendimizi onlara adamış bulunuyoruz\" dediler."},{"n":72,"t":"\"Kendilerini çağırdığınızda sizi işitiyorlar mı?\" dedi,"},{"n":73,"t":"\"Yahut size yarar veya zarar verebiliyorlar mı?\""},{"n":74,"t":"\"Hayır; ancak biz atalarımızın böyle yaptıklarını gördük\" dediler."},{"n":75,"t":"\"Peki\" dedi, \"Hizmet etmekte olduklarınızı gördünüz mü\""},{"n":76,"t":"\"Siz ve geçmiş atalarınız?\""},{"n":77,"t":"\"Onlar benim düşmanımdır; yalnız Evrenlerin Rabbi hariç;\""},{"n":78,"t":"\"Beni yaratan ve bana yol gösteren O’dur.\""},{"n":79,"t":"\"Beni yediren ve içiren O’dur.\""},{"n":80,"t":"\"Hastalandığım zaman bana şifa veren O’dur.\""},{"n":81,"t":"\"Beni öldüren ve sonra dirilten O’dur.\""},{"n":82,"t":"\"Yargı gününde, kusurlarımı bağışlayacağını umduğum da O’dur.\""},{"n":83,"t":"\"Efendim, bana bilgelik ver ve beni iyiler arasına kat.\""},{"n":84,"t":"\"Beni, sonraki nesiller için iyi bir örnek kıl.\""},{"n":85,"t":"\"Beni, Nimetler Bahçesine varis olanlardan yap.\""},{"n":86,"t":"\"Babamı bağışla, zira o sapıtmış bulunuyor.\""},{"n":87,"t":"\"Diriliş gününde beni utandırma.\""},{"n":88,"t":"O gün, paranın ve çocukların yararı olmayacaktır."},{"n":89,"t":"ALLAH’a mükemmel bir kalp ile gelenler hariç."},{"n":90,"t":"Erdemlilere bahçe sunulacaktır."},{"n":91,"t":"Azgınlar için de cehennem ortaya konacaktır."},{"n":92,"t":"Onlara şöyle denir, \"Hani hizmet ettikleriniz nerede\""},{"n":93,"t":"\"O ALLAH’tan aşağı? Size şimdi yardım edebiliyorlar mı? Kendilerine bile yardımları dokunabiliyor mu?\""},{"n":94,"t":"Azgınlarla birlikte tepetakla oraya atılacaklardır."},{"n":95,"t":"İblis’in tüm askerleri de…"},{"n":96,"t":"Orada çekişerek şöyle konuşacaklar:"},{"n":97,"t":"\"ALLAH’a andolsun, biz gerçekten çok açık bir sapıklık içinde imişiz.\""},{"n":98,"t":"\"Çünkü sizi evrenlerin Efendisine denk tutuyorduk.\""},{"n":99,"t":"\"Bizi saptıranlar suçlulardı.\""},{"n":100,"t":"\"Şimdi bizim ne şefaatçimiz var.\""},{"n":101,"t":"\"Ne de yakın bir dostumuz.\""},{"n":102,"t":"\"Bir şansımız daha olsaydı da, gerçeği onaylayanlar olsaydık.\""},{"n":103,"t":"Bunda bir ders var; ancak çoğunluk onaylamaz."},{"n":104,"t":"Kuşkusuz senin Efendin Üstündür, Rahim’dir."},{"n":105,"t":"Nuh’un halkı elçileri yalanladı."},{"n":106,"t":"Kardeşleri Nuh onlara demişti ki, \"Dinleyip erdemli davranmaz mısınız?\""},{"n":107,"t":"\"Ben size gönderilmiş güvenilir bir elçiyim.\""},{"n":108,"t":"\"ALLAH’ı dinleyip bana uymalısınız.\""},{"n":109,"t":"\"Buna karşılık sizden herhangi bir ücret de istemiyorum. Benim ücretim, ancak evrenlerin Efendisine aittir.\""},{"n":110,"t":"\"ALLAH’ı dinleyip bana uymalısınız.\""},{"n":111,"t":"Dediler ki, \"Seni izleyenler bayağı ve kötü kimseler iken, nasıl olur da seni onaylarız?\""},{"n":112,"t":"Dedi ki, \"Onların yaptıklarından bir bilgim yok.\""},{"n":113,"t":"\"Hesapları, yalnız Efendime aittir; keşke anlasanız.\""},{"n":114,"t":"\"Kesinlikle hiçbir gerçeği onaylayanı kovamam.\""},{"n":115,"t":"\"Ben ancak apaçık bir uyarıcıyım.\""},{"n":116,"t":"Dediler ki, \"Bak Nuh, bu davranışına bir son vermezsen taşlananlardan olacaksın.\""},{"n":117,"t":"Dedi ki, \"Efendim, halkım beni yalanladı.\""},{"n":118,"t":"\"Benimle onların arasını aç; beni ve beraberimdeki gerçeği onaylayanları kurtar.\""},{"n":119,"t":"Onu ve yanındakileri yüklü bir gemiyle kurtardık."},{"n":120,"t":"Sonra bunun ardından, geride kalanları boğduk."},{"n":121,"t":"Bunda bir ders var; ancak çoğunluk onaylamaz."},{"n":122,"t":"Kuşkusuz senin Efendin Üstündür, Rahimdir."},{"n":123,"t":"Ad (halkı) da elçileri yalanladı."},{"n":124,"t":"Kardeşleri Hud onlara demişti ki, \"Erdemli davranmaz mısınız?\""},{"n":125,"t":"\"Ben, size gönderilmiş güvenilir bir elçiyim.\""},{"n":126,"t":"\"ALLAH’ı dinleyip bana uyun.\""},{"n":127,"t":"\"Buna karşılık sizden herhangi bir ücret de istemiyorum. Benim ücretim, ancak evrenlerin Efendisine aittir.\""},{"n":128,"t":"\"Her tepenin üzerine bir işaret (bir yapı) yerleştirip oyalanıyor musunuz?\""},{"n":129,"t":"\"Ebedi kalırsınız diye sağlam sanayiler/endüstriler mi kurarsınız?\""},{"n":130,"t":"\"Yakaladığınız vakit acımasız yakalıyorsunuz.\""},{"n":131,"t":"\"ALLAH’ı dinleyip bana uymalısınız.\""},{"n":132,"t":"\"Bildiğiniz her şeyi size vereni dinleyin.\""},{"n":133,"t":"\"Size çiftlik hayvanları ve çocuklar verdi.\""},{"n":134,"t":"\"Üstelik bahçeler, pınarlar…\""},{"n":135,"t":"\"Sizin için müthiş bir günün cezasından korkarım.\""},{"n":136,"t":"Dediler ki, \"Öğüt versen de vermesen de bizce birdir.\""},{"n":137,"t":"\"Bu, bizden öncekilerin izlediği yaşantı biçimidir.\""},{"n":138,"t":"\"Biz, cezalandırılacak da değiliz.\""},{"n":139,"t":"Böylece onu yalanladılar. Nihayet biz de onları yok ettik. Bunda bir ders var; ancak çoğunluk onaylamaz."},{"n":140,"t":"Kuşkusuz senin Efendin Üstündür, Rahimdir."},{"n":141,"t":"Semud (halkı) da elçileri yalanladı."},{"n":142,"t":"Kardeşleri Salih onlara demişti ki, \"Erdemli olmaz mısınız?\""},{"n":143,"t":"\"Ben size gönderilmiş güvenilir bir elçiyim.\""},{"n":144,"t":"\"ALLAH’ı dinleyip bana uymalısınız.\""},{"n":145,"t":"\"Buna karşılık sizden bir ücret de istemiyorum. Benim ücretimi ancak evrenlerin Rabbi öder.\""},{"n":146,"t":"\"Şurada güvenlik içinde mi bırakılacaksınız?\""},{"n":147,"t":"\"Bahçeler, pınarlar, \""},{"n":148,"t":"\"Ekinler ve olgun meyveli hurmalıklar içindesiniz.\""},{"n":149,"t":"\"Ve dağlardan lüks köşkler yontuyorsunuz.\""},{"n":150,"t":"\"ALLAH’ı dinleyip beni izlemelisiniz.\""},{"n":151,"t":"\"Sınırı aşanların emrine uymayın.\""},{"n":152,"t":"\"Onlar yeryüzünde iyilik değil kötülük işlerler.\""},{"n":153,"t":"Dediler ki, \"Sen büyülenmişsin.\""},{"n":154,"t":"\"Sen bizim gibi bir insansın. Doğru sözlü isen bize bir mucize getir bakalım.\""},{"n":155,"t":"Dedi ki, \"İşte şu deve. Onun su içeceği belli bir zamanı vardır. Sizin de su içeceğiniz belli bir gününüz vardır.\""},{"n":156,"t":"\"Ona bir kötülük dokundurmayın. Yoksa büyük bir günün cezasına çarpılırsınız.\""},{"n":157,"t":"Nihayet onu kestiler; ancak pişman oldular."},{"n":158,"t":"Ve ceza onları yakaladı. Bunda bir ders var; ancak çoğunluk onaylamaz.\""},{"n":159,"t":"Kuşkusuz senin Efendin Üstündür, Rahimdir."},{"n":160,"t":"Lut’un halkı da elçileri yalanladı."},{"n":161,"t":"Kardeşleri Lut onlara demişti ki, \"Erdemli olmayacak mısınız?\""},{"n":162,"t":"\"Ben size gönderilmiş güvenilir bir elçiyim.\""},{"n":163,"t":"\"ALLAH’ı dinleyip bana uyun.\""},{"n":164,"t":"\"Buna karşı sizden herhangi bir ücret de istemiyorum. Benim ücretim ancak evrenlerin Efendisine aittir.\""},{"n":165,"t":"\"Siz halkın arasından erkeklere mi yöneliyorsunuz?\""},{"n":166,"t":"\"Efendinizin sizin için yarattığı eşlerinizi terkederek? Siz gerçekten haddi çok aşan bir toplumsunuz.\""},{"n":167,"t":"Dediler, \"Bak Lut, bu tavrına son vermezsen sürülenlerden olacaksın.\""},{"n":168,"t":"Dedi ki, \"Ben, bu davranışınızı iğrenç buluyorum.\""},{"n":169,"t":"\"Efendim, beni ve ailemi bu yaptıklarından kurtar.\""},{"n":170,"t":"Onu ve tüm ailesini kurtardık"},{"n":171,"t":"Yalnız bir yaşlı kadın hariç; geride kalanlardan idi."},{"n":172,"t":"Sonra diğerlerini yerle bir ettik."},{"n":173,"t":"Üzerlerine bir çeşit yağmur yağdırdık; uyarılanların yağmuru ne felaketli bir yağmurdur."},{"n":174,"t":"Bunda bir ders var; ancak çokları onaylamaz."},{"n":175,"t":"Kuşkusuz senin Efendin Üstündür, Rahimdir."},{"n":176,"t":"Eyke halkı da elçileri yalanladı."},{"n":177,"t":"Kardeşleri Şuayb onlara demişti ki, \"Erdemli olmayacak mısınız?\""},{"n":178,"t":"\"Ben size gönderilmiş güvenilir bir elçiyim.\""},{"n":179,"t":"\"ALLAH’ı dinleyin ve beni izleyin.\""},{"n":180,"t":"\"Buna karşı sizden herhangi bir ücret de istemiyorum. Benim ücretim ancak evrenlerin Efendisine aittir.\""},{"n":181,"t":"\"Ölçüyü tam uygulayın. Kandıranlardan olmayın.\""},{"n":182,"t":"\"Doğru ölçek ile tartınız.\""},{"n":183,"t":"\"Halkın hakkını kısmayın ve yeryüzünde kötülük işleyerek karışıklık çıkarmayın.\""},{"n":184,"t":"\"Sizi ve önceki nesilleri yaratanı sayıp dinleyin.\""},{"n":185,"t":"Dediler ki, \"Sen büyülenmişsin.\""},{"n":186,"t":"\"Sen sadece bizim gibi bir insansın ve biz senin yalan söylediğini sanıyoruz.\""},{"n":187,"t":"\"Doğru sözlü isen üzerimize gökten kütleler indir.\""},{"n":188,"t":"Dedi ki, \"Efendim sizin ne yaptığınızı çok iyi bilir.\""},{"n":189,"t":"Onu yalanladılar ve sonuç olarak Sayvan Gününün cezası kendilerini yakaladı; müthiş bir günün cezasıydı."},{"n":190,"t":"Bunda bir ders var; ancak çoğunluk onaylamaz."},{"n":191,"t":"Kuşkusuz, senin Efendin Üstündür, Rahimdir."},{"n":192,"t":"Bu, evrenlerin Efendisinin indirdiği vahiydir."},{"n":193,"t":"Onu Güvenilir Ruh (Cebrail) indirmiştir."},{"n":194,"t":"Senin kalbine… Uyarıcılardan biri olasın diye."},{"n":195,"t":"Apaçık Arapça bir dille."},{"n":196,"t":"Daha önceki kitaplarda da anılmıştır."},{"n":197,"t":"İsrailoğulları bilginlerinin onu bilmiş olması onlar için yeterli bir delil oluşturmuyor mu?"},{"n":198,"t":"Onu bir takım yabancılara indirseydik,"},{"n":199,"t":"Ve onu onlara okusaydı onu onaylamayacaklardı."},{"n":200,"t":"İşte biz onu suçluların kalplerine böylece (yabancı bir dil gibi) sokarız."},{"n":201,"t":"Acı azabı görünceye kadar onu onaylamazlar."},{"n":202,"t":"Onlara ansızın, beklemedikleri bir anda gelecektir."},{"n":203,"t":"O zaman, \"Bize biraz daha süre verilmez mi?\" derler."},{"n":204,"t":"Onlar, hâlâ cezamıza karşı meydan mı okuyorlar?"},{"n":205,"t":"Gördüğün gibi, biz onları yıllarca yaşatsak"},{"n":206,"t":"Ve sonra kendilerine söz verilen başlarına gelse,"},{"n":207,"t":"O tattıkları nimetler kendilerine bir yarar sağlamaz."},{"n":208,"t":"Biz uyarıcıları olmayan hiçbir kenti yok etmedik."},{"n":209,"t":"Bu bir uyarı ve mesajdır; çünkü biz haksızlık etmeyiz."},{"n":210,"t":"Onu sapkınlar indirmemiştir."},{"n":211,"t":"Onlar bunu ne yaparlar, ne de becerirler."},{"n":212,"t":"Çünkü onlar işitmekten men edilmişlerdir."},{"n":213,"t":"ALLAH ile birlikte bir başka tanrı çağırma; yoksa cezalandırılırsın."},{"n":214,"t":"Sana en yakın olan insanları uyar."},{"n":215,"t":"Ve seni izleyen gerçeği onaylayanlara kanadını indir."},{"n":216,"t":"Sana karşı gelirlerse, \"Yaptıklarınızdan uzağım\" de."},{"n":217,"t":"Üstün ve Rahman olana güven."},{"n":218,"t":"O ki (ibadet ve düşünme için) kalktığın/uyandığın zaman seni görür."},{"n":219,"t":"Ve senin secde edenler arasındaki hareketini de."},{"n":220,"t":"Çünkü O İşitendir, Bilendir."},{"n":221,"t":"Sapkınların kime indiğini size bildireyim mi?"},{"n":222,"t":"Onlar her günahkar iftiracıya iner."},{"n":223,"t":"Kulak verirler; ancak çoğu yalancıdır."},{"n":224,"t":"Şairlere ise azgınlar uyar."},{"n":225,"t":"Onların her vadide koştuklarını (duruma göre yön değiştirdiklerini) görmez misin?"},{"n":226,"t":"Ve onlar yapmadıkları şeyleri söylerler."},{"n":227,"t":"Ancak gerçeği onaylayanlar, erdemli davrananlar, ALLAH’ı çok ananlar ve haksızlığa karşı mücadele edenler hariç. Zalimler, nasıl bir devrim ile devrileceklerini bileceklerdir."}]},{"id":27,"name":"Neml Suresi","verses":[{"n":1,"t":"T. S. Bu (harfler) Kuran’ın, apaçık bir kitabın mucizeleridir."},{"n":2,"t":"Gerçeği onaylayanlar için bir kılavuz ve müjdedir."},{"n":3,"t":"Onlar ki namazı gözetirler, zekatı verirler ve ahiret konusunda da kuşkuları yoktur."},{"n":4,"t":"Ahiret gerçeğini onaylamayanların ise yaptıklarını kendilerine süslü göstermişizdir, bocalayıp dururlar."},{"n":5,"t":"Onlar en kötü cezayı haketmişlerdir ve ahirette de en çok kayba uğrayanlardır."},{"n":6,"t":"Kuşkusuz sen bu Kuran’ı, Bilge ve Bilen birisinden almaktasın."},{"n":7,"t":"Hani Musa ailesine şöyle demişti: \"Ben bir ateş gördüm, size ondan bir haber getireyim yahut size bir meşale getireyim de ısınasınız."},{"n":8,"t":"Oraya varınca kendisine, \"Ateşin içinde bulunan da, çevresinde olan da kutludur\" diye seslenildi. Evrenlerin Rabbi olan ALLAH çok yücedir."},{"n":9,"t":"\"Musa, bu Benim, Ben Üstün ve Bilge olan ALLAH’ım.\""},{"n":10,"t":"\"Değneğini at.\" Onu küçük bir yılan gibi titreştiğini görünce, arkasına dönüp bakmadan kaçtı. \"Musa, korkma; elçiler huzurumda korkmazlar.\""},{"n":11,"t":"\"Ancak kim zulmederse, sonra günahlarını bırakıp iyilik yaparsa ona karşı ben Bağışlayıcıyım, Rahimim.\""},{"n":12,"t":"\"Elini koynuna sok da; kusursuz bembeyaz olarak çıksın. Firavun ve halkına göstereceğin dokuz mucizeden biridir. Onlar yoldan çıkan bir toplum olmuşlardır.\""},{"n":13,"t":"Onlara açıkça görünen mucizelerimiz geldiğinde, \"Bu apaçık bir büyüdür\" dediler."},{"n":14,"t":"Zulüm ve kibirlerinden dolayı kendilerinin haklı olduğunu onayladılar ve onları reddettiler. Bozguncuların sonunun nasıl olduğuna dikkat et."},{"n":15,"t":"Biz Davud’a ve Süleyman’a bilgi vermiştik de \"Bize, gerçeği onaylayan kullarının birçoğundan daha fazla bağışta bulunan ALLAH’a övgüler olsun\" demişlerdi."},{"n":16,"t":"Süleyman Davud’a varis oldu. Dedi ki, \"Ey halk, bize kuşların dilini anlamak öğretildi ve bize her şeyden verildi. Bu apaçık bir lütuftur.\""},{"n":17,"t":"Süleyman için, cinlerden, insanlardan ve kuşlardan ordular oluşturulmuştu ve düzenle sevkediliyorlardı."},{"n":18,"t":"Karınca vadisine varınca, bir karınca, \"Ey karıncalar, yuvalarınıza giriniz ki Süleyman ve orduları farkında olmayarak sizi ezmesinler.\""},{"n":19,"t":"Onun sözüne gülerek, \"Efendim, senin bana ve ana babama bağışladığın nimetlerine şükretmeye ve hoşnut olacağın erdemli davranışlarda bulunmaya beni yönelt. Rahmetinle, beni erdemli kullarının arasına sok.\""},{"n":20,"t":"Kuşları denetledi ve, \"Neden hüdhüdü görmüyorum, yoksa kaçak mı?\" dedi."},{"n":21,"t":"Bana (özür olarak) açık bir delil getirmezse, onu şiddetli bir cezaya çarpacağım, yahut onu keseceğim."},{"n":22,"t":"Çok geçmeden (hüdhüd) geldi ve, \"Senin bilmediğin bir şeyi öğrendim\" dedi, \"Sana Sebe’den önemli bir haber getirdim.\""},{"n":23,"t":"\"Onları sahiplenen bir kadın buldum. Kendisine her şeyden verilmiş ve büyük bir sarayı var.\""},{"n":24,"t":"\"Onu ve halkını Allah’ın yakınından/aşağısından güneşe secde eder buldum. Sapkın onların işlerini kendilerine süslemiş ve onları yoldan çıkarmış ve bu yüzden doğruyu görmüyorlar.\""},{"n":25,"t":"\"Halbuki onlar, göklerde ve yerde gizleneni açığa çıkaran ALLAH’a secde etmeliydiler. O, onların gizlediklerini de açığa vurduklarını da bilir.\""},{"n":26,"t":"ALLAH: O’ndan başka tanrı yoktur. O büyük yönetimin Rabbidir."},{"n":27,"t":"Dedi ki, \"Doğru mu konuştun, yoksa yalancılardan mısın, göreceğiz.\""},{"n":28,"t":"\"Şu mektubumu onlara götürüp ilet ve sonra bir yana çekilip tepkilerini gözle.\""},{"n":29,"t":"(Kadın lider) dedi, \"Ey konseyim, bana onurlu bir mektup gelmiş bulunuyor.\""},{"n":30,"t":"\"O, Süleyman’dandır ve o, ‘Rahman, Rahim ALLAH’ın ismiyle’ dir.\""},{"n":31,"t":"\"Bana karşı büyüklük taslamayın; bana Müslümanlar olarak gelin,’ diye uyarmaktadır.\""},{"n":32,"t":"\"Ey konseyim, şu işte bana bir fikir verin. Siz yanımda bulunmadıkça bir işte karar vermem\" dedi."},{"n":33,"t":"\"Biz güçlüyüz, yaman savaşçılarız ve son karar sana aittir. Kararını uygula\" dediler."},{"n":34,"t":"(Kadın lider) dedi ki, \"Krallar girdikleri ülkeleri bozarlar ve onların onurlu halkını aşağılarlar. Böyle davranırlar.\""},{"n":35,"t":"\"Onlara bir armağan göndereyim de bakayım elçiler nasıl bir tepki ile dönecekler.\""},{"n":36,"t":"(Elçi) geldiğinde Süleyman kendisine şunları dedi, \"Siz bana para ve mal mı vermek istiyorsunuz? ALLAH’ın bana verdikleri sizin bana verdiğinizden çok daha iyidir. Armağanınızla (ben değil) siz sevinebilirsiniz.\""},{"n":37,"t":"\"Onlara dön, (ve bildir ki) karşı konulamayacak ordularla üzerlerine varacağız ve onları aşağılanmış ve küçültülmüş olarak oradan çıkartacağız.\""},{"n":38,"t":"Dedi ki, \"Ey konseyim, onlar bana Müslümanlar olarak gelmeden önce hanginiz onun tahtını bana getirebilir?\""},{"n":39,"t":"Cinlerden bir ifrit, \"Sen daha yerinden kalkmadan onu sana getirebilirim. Bunu becerebilecek güce sahibim\" dedi."},{"n":40,"t":"Kitap bilgisine sahip olan birisi de \"Ben onu, gözünü kırpman için geçen süreden daha çabuk getirebilirim\" dedi. Onu yanında duruyor görünce, \"Bu Efendimin bir lütfudur. Şükür mü, yoksa nankörlük mü edeceğimi sınıyor. Şükreden kendisi için şükretmiş olur. Nankörlük eden de, bilsin ki benim Efendim Zengindir, Şereflidir\" dedi."},{"n":41,"t":"\"Tahtının biçimini değiştirin, bakalım doğruyu bulabilecek mi, yoksa doğruyu bulamayanlardan mı olacak?\""},{"n":42,"t":"(Kadın lider) varınca kendisine, \"Senin tahtın buna mı benziyor?\" dendi. \"Tıpkı o\" dedi, \"Bize ondan önce bilgi verilmişti ve biz Müslüman idik.\""},{"n":43,"t":"Onu, ALLAH’tan aşağı hizmet ettikleri saptırmıştı. İnkarcı bir topluluğun bir bireyi idi."},{"n":44,"t":"Ona, \"Sarayın salonuna gir\" dendi. Sarayın salonunu görünce, su havuzu sanarak bacaklarını sıvadı. (Süleyman) dedi ki, \"Bu, kristalle döşenmiş bir salondur.\" (Kadın lider), \"Efendim, kendime haksızlık etmişim. Süleyman ile birlikte evrenlerin Rabbi ALLAH’a teslim oldum\" dedi."},{"n":45,"t":"Semud’a kardeşleri Salih’i, \"ALLAH’a hizmet edin\" desin diye gönderdik. Bunun üzerine, çekişen iki gruba ayrıldılar."},{"n":46,"t":"\"Halkım\" dedi, \"Neden iyilik yerine kötülükte acele ediyorsunuz? Merhamet edilmeniz için ALLAH’tan bağışlanma dilemeniz gerekmez miydi?\""},{"n":47,"t":"Dediler ki, \"Sen ve beraberindekiler bize uğursuzluk getirdiniz.\" Dedi ki, \"Sizin uğursuzluğunuz ALLAH’tan gelmektedir. Doğrusu siz sınava sokulan bir toplumsunuz.\""},{"n":48,"t":"Kentte dokuzlu bir çete vardı; bölgede bozgunculuk çıkarıyorlar ve asla iyi bir şey yapmıyorlardı."},{"n":49,"t":"ALLAH’a and içerek birbirlerine, \"Ona ve ailesine bir gece baskını yapalım ve sonra onun kabilesine, onların ölümü hakkında bir şey bilmediğimizi ve doğru konuştuğumuzu söyleyelim\" dediler."},{"n":50,"t":"Böylece bir plan kurdular, ancak onlar farkına varmadan biz de bir plan kurduk."},{"n":51,"t":"Planlarının nasıl sonuçlandığına bak; biz onları, halklarıyla birlikte yerle bir ettik."},{"n":52,"t":"Zulmetmeleri yüzünden, işte çökmüş evleri… Bilen bir toplum için bunda bir ders olmalı."},{"n":53,"t":"Gerçeği onaylayanları ve erdemli davrananları kurtardık."},{"n":54,"t":"Lut da halkına demişti ki, \"Gördüğünüz halde nasıl olur da böyle bir kötülüğü işliyorsunuz?\""},{"n":55,"t":"\"Kadınları bırakıp erkeklerle mi cinsel ilişki kuruyorsunuz? Siz gerçekten pek cahil bir topluluksunuz.\""},{"n":56,"t":"Halkının yanıtı sadece, \"Lut’un ailesini kasabanızdan çıkarın, onlar temiz kalmak istiyorlar\" demek oldu."},{"n":57,"t":"Biz de onu ve ailesini kurtardık, yalnız karısı hariç; onu geride kalanlardan saydık."},{"n":58,"t":"Onların üzerine bir çeşit yağmur yağdırdık. Uyarılmış bulunanların yağmuru ne de kötü idi."},{"n":59,"t":"De ki: \"Övgü ALLAH’a özgüdür. Selam (barış) da seçtiği kullarına olsun. ALLAH mı, yoksa onların ortak koştukları mı daha iyidir?\""},{"n":60,"t":"Gökleri ve yeri yaratan, gökten bir su yağdırıp, onunla sizin bir ağacını dahi bitiremeyeceğiniz güzel bahçeler bitiren kimdir? ALLAH ile birlikte bir başka tanrı mı? Doğrusu, onlar sapan bir toplumdur."},{"n":61,"t":"Yeryüzünü bir yerleşim merkezi yapan, aralarından ırmaklar çıkaran, üzerine sağlam dağlar yerleştiren ve her iki suyun arasına bir engel koyan kimdir? ALLAH ile birlikte bir başka tanrı mı? Doğrusu, onların çoğu bilmez."},{"n":62,"t":"Darda kalmışın çağrısına karşılık veren, kötülüğü gideren ve sizi yeryüzünün varisleri kılan kimdir? ALLAH ile birlikte bir başka tanrı mı? Ne kadar az öğüt alırsınız?"},{"n":63,"t":"Karanın ve denizin karanlıklarında size yol gösteren kimdir? Rahmetinden önce rüzgarları müjde olarak gönderen kimdir? ALLAH ile birlikte bir başka tanrı mı? ALLAH ortak koştuklarından çok yücedir."},{"n":64,"t":"Yaratılışı başlatan ve sonra onu tekrarlayan kimdir? Sizi gökten ve yerden rızıklandıran kimdir? ALLAH ile birlikte bir başka tanrı mı? De ki: \"Doğru sözlüler iseniz delilinizi getirin.\""},{"n":65,"t":"De ki: \"Göklerde ve yerde, ALLAH’tan başka kimse geleceği bilemez. Ne zaman dirileceklerinin bile farkına varmazlar.\""},{"n":66,"t":"Doğrusu, onların ahiret hakkındaki bilgileri derme-çatmadır. Aslında ondan kuşku içindedirler. Daha doğrusu, onlar ondan yana tümüyle kördürler."},{"n":67,"t":"İnkar edenler dediler, \"Biz ve atalarımız toprak olduktan sonra mı çıkarılacağız?\""},{"n":68,"t":"\"Bize ve atalarımıza da daha önce aynı söz verilmişti. Bunlar geçmişlerin masallarından başka bir şey değildir.\""},{"n":69,"t":"De ki: \"Yeryüzünü dolaşın da suçluların sonunun ne olduğuna bir bakın.\""},{"n":70,"t":"Onlara üzülme, planladıkları şeylerden ötürü de canını sıkma."},{"n":71,"t":"\"Doğru iseniz, bu söz ne zaman gerçekleşecek?\" diyorlar."},{"n":72,"t":"\"Belki, meydan okuyarak istediğiniz şeylerin bir kısmı size çatmıştır bile\" de."},{"n":73,"t":"Kuşkusuz Efendin halka karşı Lütuf Sahibidir, fakat çokları şükretmez."},{"n":74,"t":"Ve Efendin onların göğüslerinin gizlediğini de açığa vurduğunu da elbette bilir."},{"n":75,"t":"Göklerde ve yerde gizli olan her şey, istisnasız apaçık bir kitaptadır."},{"n":76,"t":"Bu Kuran, İsrailoğullarının hâlâ tartışmakta olduğu birçok konuyu anlatmaktadır."},{"n":77,"t":"Elbette o bir kılavuzdur ve gerçeği onaylayanlar için bir rahmettir."},{"n":78,"t":"Efendin, onların arasında kararını verecektir. O Üstündür, Bilendir."},{"n":79,"t":"ALLAH’a güven. Sen apaçık gerçeği izlemektesin."},{"n":80,"t":"Sen ölülere duyuramazsın, aynı şekilde arkalarını dönen sağırlara da çağrıyı duyuramazsın."},{"n":81,"t":"Körü de sapıklığından çıkarıp yola iletemezsin. Sen ancak, ayetlerimizi onaylayanlara duyurabilirsin; onlar (anlattığın gerçeği) kabul ederler."},{"n":82,"t":"Zamanı gelince, onlara topraktan mamul bir yaratık çıkaracağız; onlara, halkın ayet ve mucizelerimizi onaylamadığını bildirecek."},{"n":83,"t":"Ve o gün gelecek, her toplum içinde, ayetlerimizi ve mucizelerimizi yalanlayan kimseleri toplayıp süreceğiz."},{"n":84,"t":"Geldikleri zaman, \"Ayet ve mucizelerimi bilginizle kavramadığınız halde yalanladınız mı? Yoksa yaptığınız neydi?\" der."},{"n":85,"t":"Haksızlık ettikleri için verilen söz başlarına gelir ve artık konuşamazlar."},{"n":86,"t":"Geceyi dinlenmelerine elverişli, gündüzü de aydınlık yaptığımızı görmediler mi? Gerçeği onaylayan bir toplum için elbette bunda işaretler vardır."},{"n":87,"t":"Boruya üfürüldüğü gün, göklerde ve yerde bulunan herkes, ALLAH’ın diledikleri hariç korkuya kapılacaklardır. Hepsi ona boyun bükerek gelirler."},{"n":88,"t":"Dağları durgun sanırsın, halbuki bulutlar hareket ettiği gibi hareket etmektedir. Her şeyi sapasağlam yaratan ALLAH’ın sanatıdır. O, yaptıklarınızı bilendir."},{"n":89,"t":"Kim iyilik getirirse, ona ondan daha iyisi verilir ve onlar o günün korkusundan güvenlikte olurlar."},{"n":90,"t":"Kim kötülük getirirse, ateşe yüzüstü kapaklanır.\" Yaptıklarının karşılığından başkasını mı bekliyordun? \""},{"n":91,"t":"Ben, sadece bu şehrin Efendisine hizmet etmekle emredildim. O burayı sınırlamıştır ve her şey O’nundur. Ben Müslümanlardan olmakla emredildim."},{"n":92,"t":"Ve Kuran’ı okumakla da… Kim doğruyu bulursa kendi yararına doğruyu bulmuştur. Kim saparsa ben ancak uyarıcılardan biriyim."},{"n":93,"t":"De ki: \"Övgü ALLAH’adır; ayetlerini size gösterecek, siz de onları tanıyacaksınız. Efendin onların yaptığından habersiz değildir.\""}]},{"id":28,"name":"Kasas Suresi","verses":[{"n":1,"t":"T. S. M."},{"n":2,"t":"Bu (harf)ler bu apaçık Kitabın mucizeleridir."},{"n":3,"t":"Gerçeği onaylayan bir toplum için, Musa ile Firavunun bir kısım haberini sana doğru olarak anlatmaktayız."},{"n":4,"t":"Firavun yeryüzünde despotça davrandı. Halkını sınıflara ayırıp onlardan bir grubu ezip sömürüyor, kızlarını utandırıp oğullarını kesiyordu. O, bir bozguncu idi."},{"n":5,"t":"Yeryüzünde güçsüzleştirilip ezilenlere lütfederek diledik ki onları önderler ve varisler yapalım."},{"n":6,"t":"Ve onları yeryüzüne yerleştirelim, Firavun, Haman ve ordularına, korktukları şeyi gösterelim."},{"n":7,"t":"Musa’nın annesine: \"Onu emzir, ancak ne zaman onun can güvenliğinden endişelenirsen onu ırmağa at. Korkma, üzülme. Biz onu sana döndürecek ve onu elçilerden biri yapacağız\" diye vahyettik."},{"n":8,"t":"Nihayet Firavunun ailesi, kendileri için bir düşman ve üzüntü kaynağı olacak o bebeği aldı. Firavun, Haman ve orduları suçlular idiler."},{"n":9,"t":"Firavunun karısı, \"Gözümüz aydın olsun. Onu öldürme. Belki bize yararı dokunur, yahut onu evlat ediniriz.\" Hiçbir şeyden haberleri yoktu."},{"n":10,"t":"Musa’nın annesinin gönlü bomboş sabahladı. Gerçeği onaylaması için gönlünü pekiştirmeseydik, neredeyse durumu açığa vuracaktı."},{"n":11,"t":"Kızkardeşine, \"Onu izle\" dedi. O da kimseye görünmeden uzaktan izledi."},{"n":12,"t":"Önceden, onun süt annelerini kabul etmemesini sağladık. Nihayet (kızkardeşi), \"Sizin için onun bakımını üstlenecek ve ona iyi davranacak bir aileyi göstereyim mi?\" dedi."},{"n":13,"t":"Böylece onu annesine döndürdük ki gözü aydınlansın, üzülmesin ve ALLAH’ın sözünün gerçek olduğunu bilsin. Ne var ki çokları bilmez."},{"n":14,"t":"Erginlik çağına gelip olgunlaşınca ona bilgelik ve bilgi verdik. İyi davrananları böyle ödüllendiririz."},{"n":15,"t":"Halkının haberi olmadığı bir sırada kente girmişti. Orada iki adamın kavga ettiklerini gördü; biri onun tarafından (İbrani), diğeri de düşman tarafından (Mısırlı) idi. Tarafından olan adam düşmanına karşı ondan yardım istedi. Bunun üzerine Musa da ötekine bir yumruk indirip işini bitirdi. \"Bu sapkının bir işidir; o bir düşmandır, apaçık bir saptırıcıdır\" dedi."},{"n":16,"t":"\"Efendim\" dedi, \"Ben kendime haksızlık ettim, beni bağışla.\" O da onu bağışladı. Çünkü O Bağışlayandır, Rahimdir."},{"n":17,"t":"\"Efendim\" dedi, \"Bana bağışladığın nimetlere karşılık olarak bundan böyle suçlulara yardım etmeyeceğim.\""},{"n":18,"t":"Korku içinde, etrafı kollayarak şehirde sabahladı. Kendisinden dün yardım istemiş olan adam, feryad ederek yine kendisinden yardım istiyordu. Musa ona, \"Belli ki sen bir belalısın\" dedi."},{"n":19,"t":"Ortak düşmanlarını yakalamak isteyince, \"Musa, dün birisini öldürdüğün gibi bugün de beni mi öldürmek istiyorsun? Sen, yeryüzünde erdemli biri olmak istemiyorsun; bir zorba olmak istiyorsun\" dedi."},{"n":20,"t":"Şehrin öte yanından koşa koşa gelen bir adam, \"Musa, ileri gelenler seni öldürmek için aralarında görüşüyorlar. Çabuk burayı terket; ben sana öğüt vermekteyim\" dedi."},{"n":21,"t":"Korku içinde, çevreyi kollayarak oradan kaçtı. \"Efendim, beni şu zalim toplumdan kurtar\" dedi."},{"n":22,"t":"Medyen’e doğru yönelince, \"Umarım Efendim beni doğruya iletir\" dedi."},{"n":23,"t":"Medyen suyuna vardığında, orada hayvanlarını sulayan halktan bir grup buldu. Onların gerisinde itilip kakılan iki kadın gördü. Onlara, \"Ne yapmak istiyorsunuz?\" dedi. \"Çobanlar sulayıp çekilmeden sulayamayız. Babamız da çok yaşlı bir adamdır\" dediler."},{"n":24,"t":"Onlar için suladı, sonra gölgeye çekildi ve \"Efendim, senin bana bağışlayacağın her şeye muhtacım\" dedi."},{"n":25,"t":"Çok geçmeden onlardan birisi utana utana ona doğru yürüyerek geldi ve \"Babam, bizim için sulamana karşılık olarak sana ücret vermek istiyor\" dedi. Onunla karşılaşıp ona başından geçenleri anlatınca o, \"Korkma\" dedi, \"Zalim topluluktan kurtulmuş bulunuyorsun.\""},{"n":26,"t":"Onlardan biri, \"Babacığım, ona iş ver. O, senin ücretle tuttuklarının en iyisidir; hem güçlü, hem de güvenilir biri\" dedi."},{"n":27,"t":"Dedi ki, \"Bana sekiz konferans boyunca çalışman koşuluyla seni şu kızlarımdan biriyle nikahlamak istiyorum. Dilersen onu on (yıl)a tamamlayabilirsin. Sana zorluk çıkarmak istemiyorum. ALLAH dilerse, beni erdemli davranan biri olarak bulacaksın.\""},{"n":28,"t":"Dedi ki, \"Bu, seninle benim aramda bir sözleşmedir. Hangi süreyi yerine getirirsem bana düşmanlık yok. Konuştuklarımıza ALLAH garantördür\" dedi."},{"n":29,"t":"Musa, o süreyi bitirip ailesiyle birlikte yola çıkınca Tur’un yamacında bir ateş gördü ve ailesine, \"Burada durun. Ben bir ateş gördüm. Belki size ondan bir haber veya bir ateş koru getiririm de onunla ısınırsınız\" dedi."},{"n":30,"t":"Oraya varınca (yanan) ağacın bulunduğu sınırlanmış bölgede, sağ yamacın kenarından kendisine seslenildi: \"Musa, Ben evrenlerin Rabbi ALLAH’ım.\""},{"n":31,"t":"\"Değneğini at.\" Onu bir yılan gibi titreşir görünce, ardına bile bakmadan dönüp kaçtı. \"Musa, dön, korkma, sen güvencedesin.\""},{"n":32,"t":"\"Elini koynuna sok, kusursuz bembeyaz çıksın. Korkudan açılan kanatlarını katlayıp indir. Bu ikisi, Firavun ve ileri gelen ekibine Efendinden iki delildir. Onlar yoldan çıkan bir toplum olmuşlardır.\""},{"n":33,"t":"Dedi ki, \"Efendim, ben onlardan bir kişiyi öldürmüştüm. Beni öldüreceklerinden korkarım.\""},{"n":34,"t":"\"Ayrıca, kardeşim Harun benden daha iyi konuşur. Onu benimle birlikte, beni destekleyen bir yardımcı olarak gönder. Beni yalanlamalarından korkarım.\""},{"n":35,"t":"Dedi ki, \"Senin pazunu kardeşinle güçlendireceğiz ve ikinize öyle bir yetki vereceğiz ki size dokunamayacaklar. Siz ikiniz ve sizi izleyenler mucizelerimizle zafer kazanacaksınız.\""},{"n":36,"t":"Musa onlara apaçık ayet ve mucizelerimizle gidince, \"Bu ancak uydurma bir büyüdür. Biz böyle bir şeyi önceki atalarımızdan işitmedik\" dediler."},{"n":37,"t":"Musa dedi ki, \"Efendim, kendisinden bir hidayetle gelenin kim olduğunu ve sonunda kimin kazançlı çıkacağını iyi bilir. Zalimler kesinlikle başaramazlar.\""},{"n":38,"t":"Firavun, \"Ey ileri gelenler, ben sizin için benden daha iyi bir tanrı bilmiyorum. Haman, benim için balçığın üzerinde ateş yak ve Musa’nın tanrısına ulaşabilmem için bir kule yap. Ben onun yalancı olduğunu sanıyorum\" dedi."},{"n":39,"t":"O ve ordusu yeryüzünde haksız yere büyüklendi ve bize dönmeyeceklerini sandılar."},{"n":40,"t":"Onları ve ordusunu yakalayıp denize attık. Zalimlerin sonunun nasıl olduğuna dikkat et."},{"n":41,"t":"Onları, ateşe çağıran önderler kıldık; diriliş gününde de yardım görmezler."},{"n":42,"t":"Bu dünyada onları lanetle etiketledik, diriliş gününde de aşağılanacaklardır."},{"n":43,"t":"İlk nesilleri (Nuh, Hud, Salih, Lut ve Şuayb’ın halklarını) yok ettikten sonra Musa’ya, halkı aydınlatan bir kılavuz ve rahmet olarak kitabı verdik; belki öğüt alırlar diye."},{"n":44,"t":"Musa’ya emri ilettiğimiz zaman sen batı tarafında bulunmuyordun; sen tanık değildin."},{"n":45,"t":"Fakat biz birçok nesiller yarattık. Üzerinden çok zaman geçti. Sen Medyen halkı arasında bulunup ayetlerimizi okuyor da değildin. Ancak, biz elçiler göndeririz."},{"n":46,"t":"(Musa’ya) Seslendiğimizde Tur’un yamacında da bulunmuyordun. Ancak, senden önce kendilerine bir uyarıcı gelmemiş bir toplumu uyarman için Efendinden bir rahmet olarak (sana bilgi veriyoruz); belki öğüt alırlar."},{"n":47,"t":"Kendi elleriyle işledikleri yüzünden başlarına bir musibet geldiğinde, \"Efendimiz, bize bir elçi gönderseydin de senin ayetlerine uysaydık ve gerçeği onaylayanlardan olsaydık\" diyemesinler diye…"},{"n":48,"t":"Tarafımızdan kendilerine gerçek ulaştığında, \"Keşke Musa’ya verilen (mucizeler) in bir benzeri bize de getirilseydi!\" dediler. (Aynı kafa yapısına sahip olanlar) daha önce de Musa’ya verilenleri inkâr etmemişler miydi? \"Birbirini destekleyen iki büyü(kitabı)dür. Biz ikisini de reddediyoruz\" dediler."},{"n":49,"t":"De ki: \"Doğru sözlü iseniz, ALLAH katından bu ikisinden daha iyi yol gösteren bir kitap getirin, ben ona uyayım.\""},{"n":50,"t":"Sana cevap vermezlerse bil ki sadece kuruntularına uyuyorlar. ALLAH’tan gelen bir yol gösterici olmadan, kuruntularına uyandan daha sapık kim olabilir? Kuşkusuz ALLAH zalim halkı doğruya iletmez."},{"n":51,"t":"Öğüt alırlar diye kendilerine mesajı iletip durduk."},{"n":52,"t":"Kendilerine daha önceki kitapları verdiklerimiz bunu onaylarlar."},{"n":53,"t":"Kendilerine okunduğu zaman, \"Onu onayladık. Bu, Efendimizden gelen gerçektir. Zaten ondan önce de Müslümanlar idik\" derler."},{"n":54,"t":"Onların ödülleri, sabretmelerinden ötürü iki kez verilecektir. Kötülüğü iyilikle savarlar ve kendilerine verdiğimiz nimetlerden verirler."},{"n":55,"t":"Boş sözleri işittiklerinde ondan yüz çevirirler ve \"Bizim işimiz bize, sizin işiniz size. Size selam (barış) olsun. Biz cahillerle uğraşmak istemeyiz\" derler."},{"n":56,"t":"Sen sevdiğini doğruya iletemezsin. Dilediğini doğruya ileten sadece ALLAH’tır. Doğruya ulaşmayı hakedenleri en iyi bilen de O’dur."},{"n":57,"t":"Dediler ki, \"Senin hidayetine uysak yurdumuzdan ediliriz.\" Onları, katımızdan her çeşit ürünün rızık olarak toplanıp götürüldüğü güvenli ve sınırlanmış bir bölgeye yerleştirmedik mi? Ne var ki çokları bilmez."},{"n":58,"t":"Kendilerine verilen nimetlere nankörlük eden nice toplumları yok etmişizdir. İşte şunlar, kendilerinden sonra pek az kimse tarafından ikametgah edinilmiş evleridir. Oralara biz varis olduk."},{"n":59,"t":"Efendin, toplumların merkezine, kendilerine ayetlerimizi okuyan bir elçi göndermedikçe onları yok etmez. Biz, halkı zalim olmayan toplumları asla yok etmeyiz."},{"n":60,"t":"Size verilen her şey, bu dünya hayatının malı ve süsüdür. ALLAH’ın yanında olanlar ise daha iyi ve süreklidir. Anlamaz mısınız?"},{"n":61,"t":"Kavuşacağı güzel bir ödülü kendisine söz verdiğimiz bir kimse, kendisini dünya hayatının malıyla nimetlendirdiğimiz ve sonra diriliş günü hesaba çekilen kimse gibi midir?"},{"n":62,"t":"Gün gelir, onlara, \"Ortaklarım olduklarını iddia etmekte olduklarınız hani nerede?\" diye seslenir."},{"n":63,"t":"Aleyhlerinde yargının gerçekleştiği kimseler, \"Efendimiz, şunlar bizim saptırdığımız kimselerdir; biz kendimiz sapmış olduğumuz için onları saptırdık. Onları bırakıp sana sığınıyoruz. Onlar aslında bize hizmet etmiyorlardı\" derler."},{"n":64,"t":"Onlara, \"Haydi ortaklarınızı (yardıma) çağırın!\" denir. Bunun üzerine onları çağırırlar, ancak kendilerine karşılık vermezler. Azabı görürler ve doğru yolda bulunmadıklarına yanarlar."},{"n":65,"t":"O gün onlara seslenerek, \"Elçilere nasıl bir cevap verdiniz?\" der."},{"n":66,"t":"O gün gerçekleşen olayları kavrayamayacaklar ve birbirlerini sorgulayamayacaklardır."},{"n":67,"t":"Kim tövbe eder, gerçeği onaylar ve erdemli davranırsa işte o zaman başarılı olabilir."},{"n":68,"t":"Efendin dilediğini yaratır, dilediğini seçer. Seçim onlara ait değildir. ALLAH onların ortak koştuklarından uzaktır, yücedir."},{"n":69,"t":"Çünkü Efendin, onların açığa vurduklarını bildiği gibi göğüslerinin gizlediklerini de bilir."},{"n":70,"t":"O ALLAH’tır; O’ndan başka tanrı yoktur. Başta da sonda da övgüler O’nadır. Tüm yargı da O’na aittir ve O’na döndürüleceksiniz."},{"n":71,"t":"De ki: \"ALLAH geceyi diriliş gününe kadar üzerinize sürekli kılsaydı ne derdiniz? ALLAH’tan başka hangi Tanrı size bir ışık getirebilir? İşitmiyor musunuz?\""},{"n":72,"t":"De ki: \"ALLAH gündüzü diriliş gününe kadar üzerinize sürekli kılsaydı ne dersiniz? ALLAH’tan başka hangi Tanrı dinleneceğiniz geceyi size getirebilir? Görmüyor musunuz?"},{"n":73,"t":"Geceyi ve gündüzü, birinde dinlenmeniz ve diğerinde onun nimetlerini aramanız için düzenlemesi O’nun rahmetindendir. Belki şükredersiniz."},{"n":74,"t":"Onlara seslendiği gün, \"Benim ortaklarım olduğunu sandığınız kimseler nerede?\" der."},{"n":75,"t":"Her bir toplumdan bir tanık seçer ve \"Delilinizi getirin\" deriz. Böylece, tüm gerçeğin ALLAH’a ait olduğunu öğrenecekler ve uydurmuş oldukları şeyler kendilerini bırakıp kaybolacaktır."},{"n":76,"t":"Karun, Musa’nın halkından olmasına rağmen ihanet edip onlara zulmetti. Kendisine öyle hazineler vermiştik ki anahtarları güçlü bir topluluğa bile ağır geliyordu. Halkı ona şöyle demişti: \"Şımarma, ALLAH şımaranları sevmez.\""},{"n":77,"t":"\"ALLAH’ın sana verdiği nimetlerle, dünyadaki payını unutmadan ahiret yurdunu ara. ALLAH sana nasıl iyilikte bulunmuşsa sen de iyilikte bulun. Yeryüzünde bozgunculuk yapmayı arama. ALLAH bozguncuları sevmez.\""},{"n":78,"t":"Dedi ki, \"Tüm bunlar bana, bilgi ve becerimden dolayı verildi.\" Ondan önce, kendisinden daha büyük bir güce ve sayısal çoğunluğa sahip nice nesilleri ALLAH’ın yok ettiğini bilmez mi? Suçluların suçları kendilerinden sorulmaz."},{"n":79,"t":"Bir ara, tüm görkemiyle halkının arasına çıkmıştı. Dünya hayatını seçenler, \"Keşke Karun’a verilenlerin bir benzeri bize de verilseydi. Gerçekten, o çok şanslı biri\" dediler."},{"n":80,"t":"Kendilerine bilgi verilmiş olanlar, \"Yazık size, gerçeği onaylayan ve erdemli davranan için ALLAH’ın ödülü daha iyidir\" dediler. Buna ancak sabredenler kavuşturulur."},{"n":81,"t":"Onu eviyle birlikte yerin dibine geçirdik. ALLAH’ın dışında kendisine yardım edecek bir bölüğü yoktu; kazananlardan olmadı."},{"n":82,"t":"Bir önceki gün onun durumuna imrenenler, \"Demek ki ALLAH kullarından dilediğine rızkı bol verir, dilediğine de kısar. ALLAH bize lütfetmeseydi bizi de batırırdı. Demek kafirler başarıya ulaşamazlar\" demeye başladılar."},{"n":83,"t":"Bu ahiret yurdunu, yeryüzünde böbürlenmeyi ve bozgunculuğu istemeyenlere ayırdık. Sonuç erdemlilerindir."},{"n":84,"t":"Kim iyilikle gelirse kendisine ondan daha iyisi verilecektir. Kim kötülük ile gelirse, o kötülükleri işleyenlere ancak yaptıkları kadar bir karşılık verilecektir."},{"n":85,"t":"Sana Kuran’ı özgüleyen, kuşkusuz seni kararlaştırılmış noktaya döndürecektir. De ki: \"Kimin hidayet getirdiğini ve kimin açık bir sapıklık içinde olduğunu Efendim iyi bilir.\""},{"n":86,"t":"Sana bu kitabın verileceğini ummazdın; ancak bu Efendinden bir rahmettir. Kafirlere arka olma."},{"n":87,"t":"Sana indirildikten sonra seni ALLAH’ın ayetlerinden saptırmasınlar. Efendine çağır; ortak koşanlardan olma."},{"n":88,"t":"ALLAH ile birlikte hiçbir tanrıyı çağırma. O’ndan başka tanrı yoktur. O’nun varlığı hariç her şey yok olmaya mahkûmdur. Yargı tümüyle O’nundur ve siz O’na döndürüleceksiniz."}]},{"id":29,"name":"Ankebut Suresi","verses":[{"n":1,"t":"A. L. M."},{"n":2,"t":"İnsanlar, sadece \"Gerçeği onayladık\" demeleriyle, hiç sınanmadan bırakılacaklarını mı sanıyor?"},{"n":3,"t":"Kendilerinden öncekileri sınadık. Elbette ALLAH doğrucuları ile yalancıları birbirinden ayıracaktır."},{"n":4,"t":"Kötülükleri işleyenler, bizi atlatacaklarını mı sanıyorlar? Ne kötü bir yargıda bulunuyorlar."},{"n":5,"t":"Kim ALLAH ile karşılaşmayı umuyorsa, (şunu bilsin ki) ALLAH’la randevu mutlaka gerçekleşecektir. O, İşitendir, Bilendir."},{"n":6,"t":"Kim bizim için çaba gösterirse, kendisi için çaba göstermiş olur. ALLAH hiç kimseye muhtaç değildir."},{"n":7,"t":"Gerçeği onaylayıp erdemli davrananların kötülüklerini elbette örteceğiz ve yapmış olduklarının daha iyisiyle onları ödüllendireceğiz."},{"n":8,"t":"Biz insana, anne ve babasına iyi davranmasını öğütlemişizdir. Ancak onlar, hakkında bilgin olmayan bir şeyi bana ortak koşman için seninle mücadele ederlerse ikisine de uyma. Hepinizin dönüşü banadır ve yaptıklarınız hakkında size bilgi vereceğim."},{"n":9,"t":"Gerçeği onaylayıp erdemli davrananları erdemliler arasına sokacağız."},{"n":10,"t":"İnsanlardan, \"ALLAH’ı onayladık\"diyenlerden bazıları var ki, ALLAH yolunda sıkıntı ile karşılaşınca halkın zulüm ve işkencesini ALLAH’ın cezası gibi sayar. Ama Efendinden sana bir zafer gelse, \"Biz sizinle birlikte idik\" derler. ALLAH herkesin en gizli düşüncelerini bilmez mi?"},{"n":11,"t":"ALLAH elbette gerçeği onaylayanlarla ikiyüzlüleri açığa çıkaracaktır."},{"n":12,"t":"İnkarcılar gerçeği onaylayanlara, \"Yolumuza uyun; günahlarınızı biz yükleniriz\" dediler. Oysa onların günahlarından hiçbir şeyi yüklenecek değillerdir; yalancıdırlar."},{"n":13,"t":"Gerçekte, kendi yüklerine ek olarak (sorumlu oldukları) başka yükleri de yüklenecekler ve uydurdukları şeylerden diriliş günü sorulacaklardır."},{"n":14,"t":"Nuh’u, halkına göndermiştik ve onların arasında bin seneden elli yıl eksik kaldı. Ancak zulmettikleri için onları tufan yakaladı."},{"n":15,"t":"Onu ve gemi halkını kurtarıp herkese ibret yaptık."},{"n":16,"t":"İbrahim’i de… Halkına demişti ki, \"ALLAH’a hizmet edin ve O’nu saygıyla dinleyin. Bilirseniz, bu sizin için daha iyidir.\""},{"n":17,"t":"\"Yalan uydurup ALLAH’tan aşağı putlara hizmet ediyorsunuz. ALLAH’ın dışında hizmet ettikleriniz size hiçbir rızık veremez. Öyleyse rızkınızı sadece ALLAH’ın yanında arayın, O’na hizmet edin ve O’na şükredin; dönüşünüz O’nadır.\""},{"n":18,"t":"Yalanlarsanız, sizden önceki toplumlar da yalanlamışlardı. Elçinin görevi ancak açıkça bildirmektir."},{"n":19,"t":"ALLAH’ın yaratılışı nasıl başlatıp, nasıl tekrarladığını görmediler mi? Bu, elbette ALLAH için kolaydır."},{"n":20,"t":"De ki: \"Yeryüzünü dolaşın ve yaratılışın nasıl başladığını görün.\" Sonra, yine ALLAH (ahiretteki) son yaratılışı başlatacaktır. ALLAH’ın her şeye gücü yeter."},{"n":21,"t":"Dilediğini cezalandırır ve dilediğine acır; O’na çevrileceksiniz."},{"n":22,"t":"Siz ne yeryüzünde ne de gökte bunu engelleyemezsiniz. Sizin ALLAH’tan başka Sahibiniz ve Yardımcınız yoktur."},{"n":23,"t":"ALLAH’ın ayet ve mucizelerini ve O’nunla karşılaşmayı inkâr edenler, Rahmetimden ümit kesenlerdir. Onlar acı bir cezayı haketmişlerdir."},{"n":24,"t":"Halkının karşılığı, \"Onu öldürün, yahut yakın\" demelerinden başka bir şey olmadı. Ancak ALLAH onu ateşten kurtardı. Gerçeği onaylayan bir toplum için bunda dersler vardır."},{"n":25,"t":"Dedi ki, \"Sizin ALLAH’ın yanında putlara hizmet etmeniz, sadece dünya hayatında aranızdaki dostluğu korumak amacıyladır. Fakat sonra, diriliş gününde birbirinizi inkâr edersiniz, birbirinizi lanetlersiniz. Varacağınız yer ateştir ve orada yardımcı bulamazsınız.\""},{"n":26,"t":"Bunun üzerine ona Lut gerçeği onayladı ve \"Ben Efendime göç ediyorum. Kuşkusuz O Üstündür, Bilgedir\"dedi."},{"n":27,"t":"O’na (İbrahim’e) İshak ve Yakub’u bağışladık. Soyuna peygamberlik ve kitap verdik. Ödülünü bu dünyada verdik ve ahirette de erdemlilerle birlikte olacaktır."},{"n":28,"t":"Lut’u da gönderdik. Halkına dedi ki: \"Sizden önce hiç kimsenin işlemediği boyutta birgünahı işliyorsunuz.\""},{"n":29,"t":"\"Siz erkeklerle cinsel ilişki kuruyor, yolları kesiyor ve toplantılarınızda her kötülüğü işliyorsunuz.\" Halkının biricik karşılığı \"Doğrulardan isen ALLAH’ın azabını getir bakalım\" demeleri oldu."},{"n":30,"t":"\"Efendim, şu bozguncu topluluğa karşı bana zafer ver\" dedi."},{"n":31,"t":"Elçilerimiz İbrahim’e müjdeyle vardıklarında, \"Bu kentin (Sodom) halkını yok etmek üzereyiz. Çünkü oranın halkı zalim oldular\" dediler."},{"n":32,"t":"Dedi ki, \"Ama orada Lut var.\" Onlar da, \"Orada kimlerin bulunduğunu iyi biliyoruz. Onu ve ailesini kurtaracağız, fakat karısı hariç; o geride kalacaklardandır\" dediler."},{"n":33,"t":"Elçilerimiz Lut’a vardıklarında elçilerimize yapılan muameleden dolayı fenalaştı, zor durumda kaldı. Kendisine dediler ki, \"Korkma, üzülme. Biz seni ve aileni kurtaracağız. Karın hariç; o geride kalanlardan olmuştur.\""},{"n":34,"t":"\"Yoldan çıktıkları için, biz bu kentin üzerine gökten bir felaket indireceğiz.\""},{"n":35,"t":"Aklını kullanan bir toplum için apaçık bir ders olarak oradan bazı kalıntılar bıraktık."},{"n":36,"t":"Medyen’e de kardeşleri Şuayb’ı… \"Halkım, ALLAH’a hizmet edin, ahiret gününü arayın ve yeryüzünde bozgunculuk yaparak karışıklık çıkarmayın\" demişti."},{"n":37,"t":"Onu yalanladılar, nihayet kendilerini bir deprem yakaladı ve evlerinde diz üstü çöküp kaldılar."},{"n":38,"t":"Aynı şekilde, Ad ve Semud’u da… Akıbetleri, oturmuş oldukları yerlerden size belli olmaktadır. Sapkın işlerini onlara süslü göstererek onları yoldan saptırdı. Halbuki görüp anlayacak yeteneğe sahiptiler."},{"n":39,"t":"Karun, Firavun ve Haman’ı da… Musa, onlara apaçık delillerle gitmişti; ancak onlar yeryüzünde büyüklük tasladılar. Atlatıp kaçamadılar."},{"n":40,"t":"Hepsini günahlarıyla yakaladık. Onlardan kimine çılgın bir fırtına gönderdik, kimini korkunç bir ses yakaladı, kimini yerin dibine geçirdik, kimini de boğduk. Onlara zulmeden ALLAH değildi; onlar kendi kendilerine zulmediyorlardı."},{"n":41,"t":"ALLAH’ın yakınından edindikleri velilerin örneği, bir ev edinen dişi örümceğin örneğine benzer. Gerçek şu ki, evlerin en çürüğü (en az güvenilir olanı) dişi örümceğin evidir, keşke bilselerdi."},{"n":42,"t":"ALLAH onların kendisinden başka hizmet etmelerinin aslında hiçbir şey olmadığını iyi bilir. O Üstündür, Bilgedir."},{"n":43,"t":"Bu örnekleri halk için veririz ve onları bilen kimselerden başkası düşünüp anlamaz."},{"n":44,"t":"ALLAH gökleri ve yeri belli bir amaç için yarattı. Bunda gerçeği onaylayanlar için bir kanıt vardır."},{"n":45,"t":"Sana vahyetmiş olduğumuz kitaptan oku ve namazı gözet. Çünkü namaz, iğrenç ve kötü şeylerden vazgeçirir. ALLAH’ı (namaz yoluyla) anmak en önemlidir. ALLAH ne yaptığınızı bilir."},{"n":46,"t":"Zalim olanları hariç, kitap halkıyla en güzel bir biçimde tartışın ve \"Bize indirileni onayladık ve size indirileni de onayladık. Bizim Tanrımız, sizin de Tanrınız birdir. Biz sadece O’na teslim olduk\" deyin."},{"n":47,"t":"İşte sana bu kitabı indirdik. Kendilerine kitap vermiş olduklarımız onu onaylayacaklardır. Şunlardan (ümmilerden) da bazıları onaylayacaktır. Kafirlerden başkası ayetlerimizi reddetmez."},{"n":48,"t":"Sen daha önceki hiçbir kitabı okumuyordun ve onları elinle de yazmıyordun. Bu durumda, yanlışı savunanların kuşkulanması için bir bahane oluşacaktı."},{"n":49,"t":"Gerçekte o, kendilerine bilgi verilmiş olanların göğsünde apaçık ayetlerdir. Zalimlerden başkası ayetlerimizi reddetmez."},{"n":50,"t":"\"Ona Efendisinden bir mucize inmeli değil miydi?\" dediler. De ki: \"Mucizeler ALLAH’ın katındadır. Ben sadece apaçık bir uyarıcıyım.\""},{"n":51,"t":"Bu kitabı sana indirmiş olmamız ve kendilerine okunması onlara yetmez mi? Bunda gerçeği onaylayan bir toplum için bir rahmet ve öğüt vardır."},{"n":52,"t":"De ki: \"Benimle sizin aranızda tanık olarak ALLAH yeter. Göklerde ve yerde ne varsa bilir. Yanlışı gerçek diye onaylayıp, ALLAH’ı onaylamayanlar, asıl zarara uğrayanlardır.\""},{"n":53,"t":"Azabı getirmen için sana meydan okuyorlar! Belirlemiş olduğumuz bir zaman olmasaydı, o azap onlara gelecekti. Onlara ansızın, haberleri olmadan gelecektir."},{"n":54,"t":"Sana azabı getirmen için meydan okuyorlar. Halbuki cehennem kafirleri kuşatmış bile."},{"n":55,"t":"Gün gelecek azap üstlerinden ve ayaklarının altından onları sarıp örtecek ve (Tanrı onlara), \"Yaptıklarınızı tadın\" diyecektir."},{"n":56,"t":"Ey gerçeği onaylayan kullarım, yerim geniştir, sadece bana hizmet edin."},{"n":57,"t":"Her nefis ölümü tadacak ve sonra bize döndürüleceksiniz."},{"n":58,"t":"Gerçeği onaylayan ve erdemli davrananları içinden ırmaklar akan bahçeyin köşklerine yerleştireceğiz; orada ebedi kalırlar. Çalışanların karşılığı ne güzeldir."},{"n":59,"t":"Onlar ki direndiler ve Rab’lerine güvendiler."},{"n":60,"t":"Rızık konusunda endişesi olmayan nice yaratıklar vardır ki onları da sizi de ALLAH besler. O işitendir, Bilendir."},{"n":61,"t":"Onlara, \"Gökleri ve yeri kim yarattı? Güneşi ve ay’ı kim emrinize verdi?\" diye sorsan, \"ALLAH\" diye karşılık verecekler. Öyleyse neden sapıyorlar?"},{"n":62,"t":"ALLAH kullarından dilediğine rızkı arttırır ve kısar. ALLAH her şeyi Bilendir."},{"n":63,"t":"Onlara, \"Gökten suyu kim indirip ölümünden sonra toprağı canlandırıyor?\" diye sorsan, \"ALLAH\" diyecekler. De ki: \"Övgü ALLAH’a aittir.\" Ancak çokları anlamaz."},{"n":64,"t":"Bu dünya hayatı bir eğlence ve oyundan başka bir şey değildir. Ahiret yurdu ise gerçek hayattır; bir bilselerdi."},{"n":65,"t":"Gemiye bindikleri zaman, dini sadece ALLAH’a ait kılarak O’nu çağırırlar. Ne zaman ki onları denizden kurtarırız ortak koşmaya tekrar başlarlar."},{"n":66,"t":"Bırak, kendilerine verdiklerimize nankörlük etsinler, zevklensinler. İleride bilecekler."},{"n":67,"t":"Çevrelerindeki insanlar kapılıp götürülürken, sınırlanmış bölgeyi güvenli kıldık. Batıla gerçek diye onaylayıp ALLAH’ın nimetini mi reddediyorlar?"},{"n":68,"t":"Yalan uydurup ALLAH’a yakıştırandan ve kendisine gelen gerçeği yalanlayandan daha zalim kim olabilir? Kafirler için cehennemde bir yer yok mu?"},{"n":69,"t":"Uğrumuzda çaba gösterenleri yollarımıza ileteceğiz. ALLAH hiç kuşkusuz iyilik edenlerle beraberdir."}]},{"id":30,"name":"Rum Suresi","verses":[{"n":1,"t":"A. L. M."},{"n":2,"t":"Romalılar yendiler,"},{"n":3,"t":"Yeryüzünün/ülkenin en alçak yerinde… Yengilerinden sonra yenileceklerdir."},{"n":4,"t":"Bir kaç sene içinde. İş, önünde sonunda ALLAH’a aittir. O gün gerçeği onaylayanlar sevineceklerdir."},{"n":5,"t":"ALLAH’ın zaferiyle… O dilediğini zafere ulaştırır. O Üstündür, Rahimdir."},{"n":6,"t":"ALLAH’ın vermiş olduğu sözdür. ALLAH sözünü bozmaz; fakat insanların çoğu bilmez."},{"n":7,"t":"Onlar dünya hayatının dış (görünen) yüzünü bilirler. Ahiretten ise habersizdirler."},{"n":8,"t":"Kendi kendilerine hiç düşünmediler mi ki ALLAH gökleri, yeri ve aralarındakileri bir amaç için ve belli bir süre için yaratmıştır. Buna rağmen, insanların çoğunluğu Rab’leriyle karşılaşmayı inkâr etmektedirler."},{"n":9,"t":"Yeryüzünde dolaşıp, kendilerinden öncekilerin sonunun nasıl olduğuna bakmazlar mı? Onlardan daha güçlü idiler, toprağı işlediler ve onlardan daha fazla üretimde bulundular. Elçileri onlara apaçık delillerle gitmişlerdi. Onlara zulmeden ALLAH değildi; onlar kendi kendilerine zulmediyorlardı."},{"n":10,"t":"Kötülük işleyenlerin sonu kötü oldu. Çünkü ALLAH’ın ayet ve mucizelerini yalanladılar ve onlarla eğlendiler."},{"n":11,"t":"Yaratılışı başlatan, sonra onu tekrarlayan ALLAH’tır. Ve sonunda siz O’na döndürüleceksiniz."},{"n":12,"t":"O anın gerçekleştiği gün suçlular şoke olurlar."},{"n":13,"t":"Koştukları ortaklarından da kendilerine şefaat eden hiçbir kimse çıkmaz; ortaklarını inkâr ederler."},{"n":14,"t":"O anın gerçekleştiği gün gruplara ayrılırlar."},{"n":15,"t":"Gerçeği onaylayıp erdemli davrananlar ise bir bahçe içinde neşelendirilirler."},{"n":16,"t":"İnkar edip, ayetlerimizi ve ahiret buluşmasını yalanlayanlar da azabın içine sokulurlar."},{"n":17,"t":"Öyleyse geceleyin bir köşeye çekildiğiniz ve sabahleyin kalktığınız zaman ALLAH’ı övgüyle anın."},{"n":18,"t":"Akşam ve öğle tatilinde göklerde ve yerde tüm övgüler O’nadır."},{"n":19,"t":"Ölüden diriyi çıkarır, diriden de ölüyü çıkarır ve ölümünden sonra yeryüzünü diriltir; siz işte böyle çıkarılacaksınız."},{"n":20,"t":"Sizi bir topraktan yaratması ve sonra yayılıp çoğalan insanlar olmanız O’nun ayetlerindendir."},{"n":21,"t":"Kendileriyle rahatlayıp huzur bulasınız diye sizin için türünüzden eşler yaratması ve aranıza dostluk sevgisi ve merhamet koyması O’nun ayetlerindendir. Düşünen bir toplum için bunda işaretler vardır."},{"n":22,"t":"Göklerin ve yerin yaratılışı, dillerinizin ve renklerinizin farklılığı da O’nun ayetlerindendir. Bilenler için bunda işaretler vardır."},{"n":23,"t":"Geceleyin ve gündüzün uyumanız ve O’nun lütfundan aramanız da O’nun ayetlerindendir. Dinleyen bir toplum için bunda işaretler vardır."},{"n":24,"t":"Korku ve umut kaynağı olarak size şimşeği göstermesi ve gökten bir su indirerek ölümünden sonra onunla yeri diriltmesi de O’nun ayetlerindendir. Aklını kullanan bir toplum için bunda işaretler vardır."},{"n":25,"t":"Göğün ve yerin O’nun buyruğuyla ayakta durması da O’nun ayetlerindendir. Sonra sizi yerden bir tek çağrıyla çağırdığı vakit siz çıkıverirsiniz."},{"n":26,"t":"Göklerde ve yerde bulunan herkes O’na aittir; hepsi O’na boyun eğmektedir."},{"n":27,"t":"Yaratılışı başlatıp tekrarlayan da O’dur; bu O’na çok kolaydır. Göklerde ve yerde en yüce örnek O’na aittir. O Üstündür, Bilgedir."},{"n":28,"t":"İşte size kendi içinizden bir örnek veriyor: Emriniz altındaki kimseleri, size verdiğimiz rızıklarda size eşit ortaklar olarak kabul eder misiniz? Birbirinizden çekindiğiniz gibi onlardan da çekinir misiniz? Aklını kullanan bir toplum için ayetleri böyle detaylı açıklarız."},{"n":29,"t":"Aslında, zalimler bilgisizce kendi kafalarına uydular. ALLAH’ın saptırdığını kim doğruya iletebilir? Onlara hiç kimse yardım etmez."},{"n":30,"t":"Bir tek Tanrıcı olarak kendini dine adamalısın. Nitekim, ALLAH insanları böyle bir yaratılış ile donatarak yaratmıştır. ALLAH’ın yaratışında değişiklik olmaz. Bu, tam yetkin bir dindir, fakat insanların çoğu bilmez."},{"n":31,"t":"O’na yönelin; O’nu sayıp dinleyin. Namazı gözetin ve ortak koşanlardan olmayın."},{"n":32,"t":"Onlar ki dinlerini parçaladılar ve mezhep mezhep oldular. Her parti kendine ait (imam ve kitap) larla sevinip övünmektedir."},{"n":33,"t":"Halka bir zarar dokunduğu gün tümüyle Rab’lerine yönelerek dua ederler. Fakat sonra, kendilerine bir rahmet tattırınca bazıları Rab’lerine ortak koşar."},{"n":34,"t":"Böylece kendilerine verdiklerimize karşı nankörlük ederler. Zevklenin bakalım; ileride bileceksiniz."},{"n":35,"t":"Yoksa onlara, ortak koşmalarını destekleyen bir delil mi indirdik?"},{"n":36,"t":"Halka bir rahmet tattırdığımız vakit onunla sevinirler. Yaptıklarının karşılığı olarak kendilerine bir kötülük dokunsa derhal umutsuzluğa düşerler."},{"n":37,"t":"ALLAH’ın, dilediğine rızkı arttırdığını ve kıstığını görmezler mi? Gerçeği onaylayan bir toplum için bunda dersler vardır."},{"n":38,"t":"Öyleyse yakınlığı bulunanlara haklarını ver, yoksula ve yolcuya da… ALLAH’ın rızasını dileyenler için bu daha iyidir; onlar başarıya ulaşanlardır."},{"n":39,"t":"Halkın malları içinde artması için verdiğiniz tefecilik parası ALLAH’ın yanında artmaz. Ancak, ALLAH’ın rızasını dileyerek verdiğiniz bir zekata gelince, onu verenler yatırımlarını katlarlar."},{"n":40,"t":"ALLAH sizi yarattı, sonra size rızık verdi, sonra sizi öldürür, sonra sizi diriltir. Ortaklarınızdan hangisi bunlardan birisini yapabilir? Övgüler O’na aittir. Onların ortak koştuklarından çok yücedir."},{"n":41,"t":"Halkın elleriyle işledikleri yüzünden karada ve denizde felaketler yaygınlaştı. Böylece, (kötülükten) dönerler diye yaptıklarının bir kısmını onlara tattırıyor."},{"n":42,"t":"De ki: \"Yeryüzünde dolaşın da öncekilerin sonunun nasıl olduğuna bakın.\" Çokları ortak koşanlardı."},{"n":43,"t":"Öyleyse, ALLAH’tan, geri çevrilmesi olanaksız birgün gelmeden önce kendini dosdoğru olan dine ada. O gün şoke olurlar."},{"n":44,"t":"Kim inkâr ederse, inkârı kendi aleyhinedir. Kimler de erdemli davranırlarsa kişiliklerini güçlendirmiş ve geliştirmiş olurlar."},{"n":45,"t":"Çünkü O, gerçeği onaylayanları ve erdemli davrananları lütfundan ödüllendirecektir. O, inkârcıları sevmez."},{"n":46,"t":"Size rahmetini tattırması, emriyle gemileri yürütmesi, lütfunu (ticaret yoluyla) aramanız ve şükretmeniz için rüzgarları müjdeci olarak göndermesi de O’nun ayetlerindendir."},{"n":47,"t":"Senden önce elçileri halklarına apaçık delillerle gönderdik. Suç işleyenleri de cezalandırdık. Gerçeği onaylayanlara yardım etmek görevimizdir."},{"n":48,"t":"ALLAH rüzgarları göndererek bulutları sürer, onları dilediği gibi gökte yayıp üstüste yığar ve sen de onların arasından yağmurun çıktığını görürsün. Kullarından dilediğinin üzerine onu yağdırınca hemen sevinirler."},{"n":49,"t":"Halbuki onlar, üzerlerine yağmur yağmasından önce umutsuzdular."},{"n":50,"t":"ALLAH’ın rahmetinin ürünlerine bak; ölümünden sonra toprağı nasıl da diriltiyor. Bunun gibi ölüleri de diriltecektir. O her şeye gücü yetendir."},{"n":51,"t":"Ancak, O bir fırtına gönderir de onlar (ekinlerin kuruyup) sarardığını görseler, hemen inkâr ve nankörlük etmeye başlarlar."},{"n":52,"t":"Sen ne ölülere işittirebilirsin, ne de arkalarını dönüp giden sağırlara çağrıyı duyurabilirsin."},{"n":53,"t":"Körü de sapıklığından kurtarıp yola getiremezsin. Sen ancak ayetlerimizi onaylayanlara işittirebilirsin ki onlar hemen teslim olurlar."},{"n":54,"t":"ALLAH sizi zayıf olarak yarattı, zayıflıktan sonra size güç verdi, güçten sonra zayıflık ve ağarmış saçlar verdi. O dilediğini yaratır. O Bilendir, Güçlüdür."},{"n":55,"t":"O an gerçekleştiği zaman, suçlular, (dünyada) ancak bir an kaldıklarına and içerler. Onlar işte böyle yanılıyorlardı."},{"n":56,"t":"Kendilerine bilgi ve gerçeği onaylama şansı verilenler, \"Siz ALLAH’ın yasasına göre, diriliş gününe kadar kaldınız. Bu, diriliş günüdür; fakat siz bilemediniz\" diyeceklerdir."},{"n":57,"t":"O gün, zalimlerin özrü kendilerine bir yarar sağlamayacaktır; kendilerini temize çıkarmaları da istenmez."},{"n":58,"t":"Biz bu Kuran’da halka her türlü örneği verdik. Onlara bir mucize getirsen, kafirler, \"Siz yanılanlarsınız\" diyeceklerdir."},{"n":59,"t":"ALLAH bilmeyenlerin kalplerini işte böyle damgalar."},{"n":60,"t":"Öyleyse sabret. ALLAH’ın sözü gerçektir. Kuşkusuz bir onaya sahip olmayanlar seni gevşekliğe sürüklemesin."}]},{"id":31,"name":"Lokman Suresi","verses":[{"n":1,"t":"A. L. M."},{"n":2,"t":"Bunlar bu bilge kitabın mucizeleridir."},{"n":3,"t":"Güzel davrananlara bir yol gösterici ve bir rahmettir."},{"n":4,"t":"Onlar ki namazı gözetirler, zekatı verirler; ahiret hakkında da kuşkuları yoktur."},{"n":5,"t":"Rab’leri tarafından gösterilen bir yolu izleyenler ve kazananlar bunlardır."},{"n":6,"t":"İnsanlardan bazısı var ki halkı bilgisizce ALLAH’ın yolundan saptırmak ve onu hafife almak için temelsiz hadislere sarılırlar. Onlar için aşağılayıcı bir azap vardır."},{"n":7,"t":"Kendisine ayetlerimiz okunduğu zaman, sanki onu hiç işitmemiş gibi, sanki kulaklarında ağırlık varmış gibi büyüklenerek ardını döner. Ona acıklı azabı müjdele!"},{"n":8,"t":"Gerçeği onaylayıp erdemli davrananlar için nimet bahçeleri vardır."},{"n":9,"t":"Orada ebedi kalırlar. ALLAH’ın sözü gerçektir. O Üstündür, Bilgedir."},{"n":10,"t":"Gökleri, gördüğün bir direk olmadan yaratmıştır. Ve sarsılmamanız için yeryüzüne denge sağlayıcılar atıp yerleştirdi ve orada her çeşit yaratığı yaydı. Gökten bir su yağdırdık ve orada her güzel çifti bitirdik."},{"n":11,"t":"Bu ALLAH’ın yaratışıdır. O’ndan başkasının neler yarattığını bana gösterin. Zalimler, gerçekten apaçık bir sapıklık içindedirler."},{"n":12,"t":"Lokman’a bilgelik verdik: \"ALLAH’a şükretmelisin.\" Kim şükrederse kendisi için şükreder; kim nankörlük ederse, elbette ALLAH muhtaç değildir, Çok Övülendir."},{"n":13,"t":"Lokman oğluna öğüt verirken şunu demişti: \"Sevgili oğlum, ALLAH’a ortak koşma, kuşkusuz şirk (Tanrı’ya ortak koşmak) büyük bir zulümdür.\""},{"n":14,"t":"Biz insana ana babasını öğütledik. Annesi onu büyük bir güçlükle taşır. Sütten kesilmesi iki yıl içinde olur. Bana ve ana babana teşekkür etmelisin. Dönüş banadır."},{"n":15,"t":"Hakkında bilgin olmayan bir şeyi bana ortak koşman için seninle mücadele ederlerse ikisine de uyma. Ancak dünyada onlara iyi davranmalısın. Bana yönelenlerin yoluna uy. Sonunda dönüşünüz banadır ve yaptığınız her şeyi size bildireceğim."},{"n":16,"t":"\"Sevgili oğlum, hardal tanesi ağırlığınca bir şey, ister bir kayanın içinde bulunsun, ister göklerde veya yerde olsun, ALLAH onu getirir. ALLAH Latiftir, Haberdardır."},{"n":17,"t":"\"Sevgili oğlum, namazı gözet, iyiliği emret, kötülükten menet ve başına gelene sabret. Bunlar temel davranışlardandır.\""},{"n":18,"t":"\"Büyüklük taslayarak halkı küçümseme, yeryüzünde de böbürlenerek dolaşma. ALLAH kendini beğenip övüneni sevmez.\""},{"n":19,"t":"\"Yürüyüşünde gösterişten kaçın ve sesini de kıs. En çirkin ses eşeklerin sesidir.\""},{"n":20,"t":"ALLAH’ın göklerde ve yerde ne varsa emrinize verdiğini, nimetlerini hem açık ve hem gizli olarak üzerinize yağdırdığını görmez misiniz? Halktan bazıları vardır ki ALLAH hakkında bilgisizce, ne bir kılavuzu, ne de bir aydınlatıcı kitabı olmadan tartışır."},{"n":21,"t":"Kendilerine, \"ALLAH’ın indirdiğine uyun\" denildiği zaman, \"Hayır, biz atalarımızı üzerinde bulduğumuz yolu izleriz\" derler. Sapkın kendilerini alevli ateşin azabına çağırıyor olsa da mı?"},{"n":22,"t":"Kim, güzel davranarak tümüyle ALLAH’a yönelirse en sağlam bağa sarılmıştır. Tüm işleri ALLAH kontrol eder."},{"n":23,"t":"İnkar edenlerin inkârları seni üzmesin. Onların dönüşü bizedir ve yapmış olduklarını onlara bildireceğiz. ALLAH gizli düşünceleri iyi bilendir."},{"n":24,"t":"Onları biraz yaşatırız, sonra da ağır bir cezaya süreriz."},{"n":25,"t":"Onlara, \"Gökleri ve yeri kim yarattı?\" diye sorarsan, \"ALLAH\" diyecekler. De ki: \"Övgü ALLAH’adır.\" Ne var ki çokları bilmiyor."},{"n":26,"t":"Göklerde ve yerde olan her şey ALLAH’ındır. Kuşkusuz ALLAH Zengindir, Övülendir."},{"n":27,"t":"Yeryüzünde bulunan tüm ağaçlar kalem olsa, denizlere yedi deniz eklenerek kullanılsa ALLAH’ın kelimeleri tükenmez. ALLAH Üstündür, Bilgedir."},{"n":28,"t":"Hepinizin yaratılışı ve dirilişi bir tek kişininki gibidir. ALLAH Dinleyendir, Görendir."},{"n":29,"t":"ALLAH’ın geceyi gündüzün içine soktuğunu, gündüzü de gecenin içine soktuğunu, güneşi ve ayı kontrolü altında tuttuğunu, her birinin belirlenmiş bir süreye kadar akıp gitmekte olduğunu ve ALLAH’ın onların yaptıklarından haberdar olduğunu görmez misin?"},{"n":30,"t":"Çünkü ALLAH gerçektir, O’nun dışında çağırdıkları batıldır ve ALLAH En Yüce ve En Büyüktür."},{"n":31,"t":"Size bazı ayetlerini göstermek için, ALLAH’ın lütfuyla gemilerin denizde akıp gittiğini görmez misin? Her sabreden ve şükreden için bunda dersler vardır."},{"n":32,"t":"Onları koca dalgalar sardığında, dini sadece ALLAH’a has kılarak O’na yalvarmaya başlarlar. Onları karaya çıkarıp kurtardığımız zaman bir kısmı orta bir yol tutar. Hain nankörlerden başkası ayetlerimizi reddetmez."},{"n":33,"t":"Ey halk, Efendinizi dinleyin, babanın çocuğuna yardım edemeyeceği ne de çocuğun babaya yardım edemeyeceği günden korkun. ALLAH’ın sözü gerçektir. Dünya hayatı sizi aldatmasın; kandırıcılar sizi ALLAH ile aldatmasınlar."},{"n":34,"t":"O anın bilgisi ALLAH’ın yanındadır. Yağmuru O yağdırır ve rahimlerde ne varsa bilir. Hiç kimse kendisine yarın ne olacağını bilmez, yine hiç kimse nerede öleceğini bilmez. ALLAH Bilendir, Haberdardır."}]},{"id":32,"name":"Secde Suresi","verses":[{"n":1,"t":"A. L. M."},{"n":2,"t":"Bu kitabın indirilişi, hiç kuşkusuz, evrenlerin Rabbi tarafındandır."},{"n":3,"t":"\"Onu uydurdu\" mu diyorlar? Halbuki bu, senden önce kendilerine bir uyarıcı ulaşmamış bir toplumu, belki yola gelirler diye uyarman için Efendinden gelen bir gerçektir."},{"n":4,"t":"ALLAH gökleri, yeri ve aralarındakileri altı günde yaratan ve sonra tüm otoriteyi kurandır. Sizin için O’ndan ayrı bir veli (sahip) ve şefaatçi (aracı) yoktur. Öğütten anlamaz mısınız?"},{"n":5,"t":"Gökten yere kadar bütün işleri O kontrol eder. Sonra sizin saydığınızdan bin yıla eşit birgün içinde kendisine yükselirler."},{"n":6,"t":"Gizliyi de açığı da bilen, Üstün ve Rahim işte böyledir."},{"n":7,"t":"O yarattığı her şeyi mükemmel hâle soktu. İnsanın yaratılışına balçıktan başladı."},{"n":8,"t":"Sonra onun soyunu bayağı bir sudan devam ettirdi."},{"n":9,"t":"Sonra onu biçimlendirip ona ruhundan üfledi. Size işitme ve görme yeteneği ile beyinler verdi; siz pek seyrek şükrediyorsunuz."},{"n":10,"t":"Ve, \"Biz toprağa karışıp kaybolduktan sonra yeniden mi yaratılacağız?\" dediler. Doğrusu, onlar Rab’leri ile kavuşmayı inkâr edenlerdir."},{"n":11,"t":"De ki: \"Üzerinize görevlendirilen ölüm meleği canınızı alacak ve sonra Efendinize döndürüleceksiniz.\""},{"n":12,"t":"Suçluları, Rab’leri huzurunda başlarını öne eğmiş durumda iken bir görseydin: \"Efendimiz, gördük ve işittik. Bizi döndür de erdemli davranalım. Şimdi biz kesin olarak onayladık.\""},{"n":13,"t":"Dileseydik herkese hidayetini verirdik. Ancak, cinlerin ve insanların bir kısmıyla cehennemi topluca dolduracağıma dair sözüm gerçekleşmiştir."},{"n":14,"t":"Bugünkü karşılaşmanızı unutmanızın sonucunu tadın, biz de sizi unutacağız. Yaptıklarınızın bir sonucu olarak ebedi azabı tadın."},{"n":15,"t":"Ayet ve mucizelerimize gerçekten gerçeği onaylayanlar, onları işittikleri zaman secdeye varırlar ve büyüklük taslamadan Rab’lerini yüceltirler."},{"n":16,"t":"Yataklarından kalkıp Rab’lerine saygı ve umutla yalvarırlar. Kendilerine verdiğimiz nimetlerden de verirler."},{"n":17,"t":"Yaptıklarının karşılığı olarak kendilerini ne kadar büyük bir neşe ve mutluluk beklediğini hiç kimse bilemez."},{"n":18,"t":"Gerçeği onaylayan biri yoldan çıkmış biri gibi midir? Elbette eşit olamazlar."},{"n":19,"t":"Gerçeği onaylayıp erdemli davrananlar için bahçe konakları vardır. Yaptıklarının bir karşılığı olarak."},{"n":20,"t":"Yoldan çıkmış olanların konağı ise ateştir. Oradan her çıkmak istediklerinde, tekrar oraya çevrilirler. Onlara, \"Yalanlamakta olduğunuz ateş azabını tadın!\" denir."},{"n":21,"t":"Belki (ibret alıp) dönerler diye büyük azaptan önce biz onlara yakın (dünya) azabı tattırırız."},{"n":22,"t":"Kendisine Efendinin ayetleri hatırlatıldıktan sonra onlardan yüz çevirenden daha zalim kim olabilir? Biz suçlulardan elbette öc alacağız."},{"n":23,"t":"Musa’ya kitabı verdik; bu konuda hiçbir kuşkun olmasın. Onu İsrailoğulları için bir rehber yaptık."},{"n":24,"t":"Sabrettikleri ve ayetlerimizi kuşkusuz bir bilgiyle onayladıkları zaman, emrimiz doğrultusunda yol gösteren önderler atamıştık içlerinden."},{"n":25,"t":"Efendin, ayrılığa düştükleri konularda onların arasında diriliş günü karar verecek olandır."},{"n":26,"t":"Kendilerinden önce nice nesilleri yok etmiş olmamız üzerinde hiç düşünmediler mi? Ki şimdi onların yurtlarında dolaşıyorlar. Bunda dersler ve işaretler vardır. İşitmezler mi?"},{"n":27,"t":"Kıraç toprağa suyu sürerek onların ve çiftlik hayvanlarının yediği ekinleri çıkardığımızı kavramazlar mı? Görmezler mi?"},{"n":28,"t":"\"O zafer ne zaman gerçekleşecek, doğru sözlüyseniz?\" diye meydan okuyorlar."},{"n":29,"t":"De ki: \"Zafer günü, inkârcıları onaylamaları bir yarar sağlamayacaktır; kendilerine bir başka şans da tanınmayacaktır.\""},{"n":30,"t":"Öyleyse onlardan yüz çevir ve bekle; onlar da beklemektedirler."}]},{"id":33,"name":"Ahzab Suresi","verses":[{"n":1,"t":"Ey peygamber, ALLAH’ı gözet, inkârcılara ve ikiyüzlülere uyma. ALLAH Bilendir, Bilgedir."},{"n":2,"t":"Efendinden sana vahyedilene uy. ALLAH yaptığınız her şeyden haber almaktadır."},{"n":3,"t":"ALLAH’a güven. Koruyucu olarak ALLAH yeter."},{"n":4,"t":"ALLAH hiçbir adamın içine iki kalp koymamıştır. Annenize benzeterek kendinize haram kıldığınız eşlerinizi annelerinize çevirmemiş, evlatlıklarınızı da öz çocuklarınız yapmamıştır. Tüm bunlar, ağzınızdan çıkan sözlerinizden ibarettir. ALLAH doğruyu söylüyor ve O doğru yola iletir."},{"n":5,"t":"Onları, öz babalarıyla bağlarını kesmeyecek biçimde çağırın. Bu davranış, ALLAH katında daha doğrudur. Babalarını bilmiyorsanız, o zaman onlar sizin din kardeşlerinizdir ve ailenizin bireyleridir. Kasıtlı olarak yaptıklarınız bir yana, yanılarak yaptığınız şeylerde size bir sorumluluk yoktur. ALLAH Bağışlayandır, Rahimdir."},{"n":6,"t":"Peygamber, gerçeği onaylayanlara, kendilerinden daha yakındır ve hanımları ise anneleridir. ALLAH’ın kitabına göre, gerçeği onaylayanlar, göçedenlerden kendilerine akraba olanlara daha öncelikli davranmalıdır. Ancak dostlarınıza iyilik yapmanız hariç. Bunlar, bu kitapta yasallaşmıştır."},{"n":7,"t":"Nebilerden (peygamberlerden) misak (söz) almıştık. Senden, Nuh’tan, İbrahim’den, Musa’dan ve Meryem oğlu İsa’dan… Onlardan sapasağlam bir söz almıştık."},{"n":8,"t":"Böylece doğrulardan doğruluklarını soracağız. İnkarcılar içinse acı bir azap hazırlamıştır."},{"n":9,"t":"Ey gerçeği onaylayanlar, size ordular saldırdığı zaman, üzerlerine bir rüzgar ve görmediğiniz orduları gönderen ALLAH’ın size yaptığı iyiliği hatırlayın. ALLAH yaptığınız her şeyi Görendir."},{"n":10,"t":"Üstünüzden ve altınızdan size saldırmışlardı. Gözler dönmüştü, yürekler ağızlara gelmişti ve siz ALLAH hakkında çeşitli kuşkular besliyordunuz."},{"n":11,"t":"Gerçeği onaylayanlar orada denenmiş ve şiddetle sarsılmışlardı."},{"n":12,"t":"İkiyüzlüler ve kalplerinde hastalık bulunan kimseler, \"ALLAH’ın ve elçisinin bize verdiği söz boş bir hayalden başka bir şey değilmiş!\" diyorlardı."},{"n":13,"t":"Onlardan bir grup ise, \"Yesrib halkı, artık tutunamazsınız; geri dönün\" diyordu. Onlardan diğer grup ise, evleri korunduğu halde, \"Evlerimiz korumasız kaldı\" diyerek peygamberden izin istiyorlardı. Tüm amaçları kaçmak idi."},{"n":14,"t":"Orası işgal edilse ve düşmana katılmaları istenseydi pek tereddüt etmeden onlara katılırlardı."},{"n":15,"t":"Daha önce de, arkalarını dönüp kaçmayacaklarına dair ALLAH’a söz vermişlerdi. ALLAH’a verilmiş her söz sorulacaktır."},{"n":16,"t":"De ki: \"Ölümden veya savaştan kaçmak size yarar sağlamayacak. Kaçsanız da pek fazla yaşamayacaksınız.\""},{"n":17,"t":"De ki: \"ALLAH sizin için bir kötülük dilese veya bir rahmet dilese O’na karşı sizi kim koruyacak? Onlar ALLAH’tan başka bir sahip ve yardımcı bulamayacaklardır."},{"n":18,"t":"ALLAH, içinizden alıkoyanları ve kardeşlerine, \"Bize gelin\" diyenleri bilmektedir. Onlar ender olarak savunmaya katılırlar."},{"n":19,"t":"Sizinle ilişkilerinde pek cimridirler. Tehlike geldiğinde, üzerine ölüm baygınlığı çökmüş kimse gibi gözleri korkudan dönmüş bir halde sana baktıklarını görürsün. Tehlike geçince de, mala düşkünlük göstererek sizi sivri dillerle incitirler. Bu tip kimseler onaylamış değillerdir. Bu yüzden ALLAH onların işlerini boşa çıkarır. Bu, ALLAH için kolaydır."},{"n":20,"t":"Partilerin gitmediğini sanıyorlar. Partiler tekrar gelse kendilerinin çöldeki bedevi Araplar arasında olmayı ve sizin haberlerinizi uzaktan sormayı dilerlerdi. Aranızda olsalardı dahi pek az savaşırlardı."},{"n":21,"t":"ALLAH’ı ve ahiret gününü arzulayan ve ALLAH’ı sıkça ananlarınız için ALLAH’ın elçisinde güzel bir örnek vardır."},{"n":22,"t":"Gerçeği onaylayanlar, partileri (saldırıya hazır) görünce, \"İşte bu, ALLAH’ın ve elçisinin bize söz verdiğidir. ALLAH ve elçisi doğru söylemiştir\" dediler. Bu (tehlikeli durum), onların ancak onaylarını ve teslimiyetlerini güçlendirdi."},{"n":23,"t":"Gerçeği onaylayanlardan öyle kimseler var ki ALLAH’a vermiş oldukları sözü gerçekleştirmişlerdir. Onlardan kimi adağını yerine getirdi (şehid oldu), kimi de hazır bekliyor. Hiçbir vakit kararsızlığa düşmediler."},{"n":24,"t":"ALLAH böylece doğruları doğrulukları ile ödüllendirir. İkiyüzlüleri de dilerse cezalandırır veya tövbelerini kabul eder. ALLAH Bağışlayandır, Rahimdir."},{"n":25,"t":"ALLAH inkârcıları öfkeleriyle birlikte elleri boş olarak geri çevirdi. ALLAH böylece gerçeği onaylayanları savaştan esirgedi. ALLAH Güçlüdür, Üstündür."},{"n":26,"t":"Ve kitap halkından onlara destek olanları kalelerinden indirdi ve yüreklerine korku düşürdü. Bir kısmını öldürüyor, bir kısmını da tutsak alıyordunuz."},{"n":27,"t":"Sizi onların toprağına, evlerine, paralarına ve henüz ayağınızı dahi basmamış olduğunuz topraklara mirasçı kıldı. ALLAH her şeye gücü yetendir."},{"n":28,"t":"Peygamber, hanımlarına De ki: \"Siz dünya hayatının süsünü istiyorsanız, gelin size bağışta bulunayım ve sizi güzellikle bırakayım.\""},{"n":29,"t":"\"Yok, siz ALLAH’ı, elçisini ve ahiret yurdunu istiyorsanız, ALLAH sizden güzel davrananlara büyük bir ödül hazırlamıştır.\""},{"n":30,"t":"Ey peygamberin hanımları, sizden kim büyük ve açık bir günah işlerse onun cezası ikiye katlanır. ALLAH için elbette bu kolaydır."},{"n":31,"t":"Sizden kim ALLAH’ın elçisine uyar ve erdemli davranırsa, onun da ödülünü iki kat veririz ve onun için bol bir rızık hazırlamışızdır."},{"n":32,"t":"Ey peygamberin hanımları, siz herhangi bir kadın gibi değilsiniz. Erdemliyseniz, işveli konuşmayın ki kalbinde hastalık bulunan birileri size yönelmesin. Güzel ve normal biçimde konuşun."},{"n":33,"t":"Evlerinizde onurlu davranın ve eski cahiliyye dönemindeki gibi aşırı süslenmeyle gösteriş yapmayınız. Namazı gözetin, zekatı verin ve ALLAH ve elçisine uyun. Ey Ev’in çevresinde oturanlar, ALLAH sizden günahları gidermek ve sizi tamamıyla arındırmak istiyor."},{"n":34,"t":"Evlerinizde okunan ALLAH’ın ayetlerini ve hikmeti hatırlayın. ALLAH Latiftir, Haberdardır."},{"n":35,"t":"Müslüman erkekler ve Müslüman kadınlar, gerçeği onaylayan erkekler ve gerçeği onaylayan kadınlar, söz dinleyen erkekler ve söz dinleyen kadınlar, doğru sözlü erkekler ve doğru sözlü kadınlar, sabreden erkekler ve sabreden kadınlar, saygılı erkekler ve saygılı kadınlar, yardımsever erkekler ve yardımsever kadınlar, oruç tutan erkekler ve oruç tutan kadınlar, iffetli erkekler ve iffetli kadınlar, ALLAH’ı çok anan erkekler ve çok anan kadınlar; işte ALLAH onların hepsine bağışlanma ve büyük bir ödül hazırlamıştır."},{"n":36,"t":"ALLAH ve elçisi bir işte hüküm verdiği zaman, hiçbir gerçeği onaylayan erkek ve kadın o işte seçim hakkına sahip değildir. Kim ALLAH’a ve elçisine isyan ederse açık bir biçimde sapmış olur."},{"n":37,"t":"ALLAH tarafından kendisine iyilik yapılan ve senin de iyilikte bulunduğun kişiye, \"Karını tut ve ALLAH’ı gözet\" diyordun. Böylece ALLAH’ın açığa vuracağı bir şeyi gizliyordun. ALLAH’tan çekinmen gerekirken halktan çekiniyordun. Zeyd eşiyle ilişiğini kestiğinde biz seni onunla evlendirmiştik ki gerçeği onaylayanlar, evlatlıkları eşleriyle ilişiklerini kestiklerinde onlarla evlenmekte güçlükle karşılaşmasın. ALLAH’ın buyruğu yerine getirilmelidir."},{"n":38,"t":"ALLAH’ın kendisine yasallaştırdığı bir konuda peygambere herhangi bir engel yoktur. Bu, öteden beri, gelmiş geçmişlere uygulanan ALLAH’ın sünneti (yasası) dır. ALLAH’ın emri, belirlenmiş ve kesinleşmiştir."},{"n":39,"t":"ALLAH’ın elçiliğini duyuranlar sadece O’nu sayarlar ve ALLAH’tan başka hiç kimseden çekinmezler. Hesap sorucu olarak ALLAH yeter."},{"n":40,"t":"Muhammed, adamlarınızdan herhangi birisinin babası olmadı. Ancak o ALLAH’ın elçisi (rasulü) ve son peygamber (nebi) oldu. ALLAH her şeyi iyi bilir."},{"n":41,"t":"Ey gerçeği onaylayanlar ALLAH’ı çok sık olarak anın."},{"n":42,"t":"O’nu sabah akşam yüceltin."},{"n":43,"t":"O ki sizi karanlıklardan ışığa çıkarmak için melekleri ile birlikte sizi destekler. O, gerçeği onaylayanlara karşı Rahimdir."},{"n":44,"t":"O’nunla karşılaştıkları gün dirlik dilekleri, Selam (Barış/Güvenlik)’dır. Onlara cömert bir ödül hazırlamıştır."},{"n":45,"t":"Ey peygamber, biz seni bir tanık olarak gönderdik, bir müjdeleyici ve bir uyarıcı,"},{"n":46,"t":"ALLAH’a, O’nun izniyle çağıran bir davetçi ve aydınlatıcı bir ışık olarak…"},{"n":47,"t":"Gerçeği onaylayanlara, ALLAH’tan büyük bir lütfa ulaşacaklarını müjdele."},{"n":48,"t":"İnkarcılara ve ikiyüzlülere uyma, eziyetlerine aldırma ve ALLAH’a güven; koruyucu olarak ALLAH yeter."},{"n":49,"t":"Ey gerçeği onaylayanlar, gerçeği onaylayan kadınları nikahladıktan sonra, onlarla cinsel ilişkiye girmeden boşarsanız, (bir başkasıyla evlenmelerinden önce) onların size bir bekleme süresi borcu yoktur. Onlara bir geçimlik verin ve onları güzellikle terkedin."},{"n":50,"t":"Ey peygamber, mehirlerini vermiş bulunduğun eşlerini ve ALLAH’ın sana bağışladığı sözleşmenle üzerlerinde hak sahibi olduğun, seninle birlikte göç eden amcanın kızlarını, halalarının kızlarını, dayının kızlarını ve teyzelerinin kızlarını sana helal kılmışızdır. Ayrıca, peygamber dilerse, kendisini gerçeği onaylayanlara değil sadece peygambere mehirsiz olarak hibe eden birisiyle nikahlanabilir. Biz, eşleri ve sözleşmelileri hakkında üzerlerine yüklediğimiz sorumlulukları bildirmiştik ki güç bir duruma düşmeyesin. ALLAH Bağışlayandır, Rahimdir."},{"n":51,"t":"Onlardan dilediğini erteler, dilediğini de yanına alabilirsin. Sırasını geri bırakmış olduğun birisini tekrar istemende bir sakınca yoktur. Böylece onlar hoşnut olurlar, üzülmezler ve senin her birisine verdiğine razı olurlar. Kalbinizde olanı ALLAH iyi bilir. ALLAH Bilendir, Şefkatlidir."},{"n":52,"t":"Bunların ötesinde kadınlar sana helal değildir ve eşlerinden herhangi birisini de onlarla değişemezsin. Güzellikleri senin ilgini çekse bile. Ancak sözleşmenle üzerlerinde hak sahibi olduklarınla yetin. ALLAH her şeyi gözetleyendir."},{"n":53,"t":"Ey gerçeği onaylayanlar, peygamberin evine, yemeye çağrılmadan girmeyin. Öyle bir çağrıyı da beklemeyin. Çağrıldığınız vakit girebilirsiniz. Yemeği yedikten sonra ayrılıp dağılın. Hadislere (sözlere) dalmayın. Bu durum peygamberi üzüyor; ancak size bildirmekten utanıyordu. ALLAH gerçeği bildirmekten çekinmez. Onun hanımlarından bir şey istediğinizde onu bir perde ardından isteyiniz. Bu sizin kalbiniz ve onların kalpleri için daha temiz bir davranıştır. ALLAH’ın elçisini üzmemelisiniz ve ondan sonra onun eşleriyle asla evlenmemelisiniz, zira bu, ALLAH katında pek büyük bir günahtır."},{"n":54,"t":"Bir şeyi açığa vursanız da, gizleseniz de ALLAH her şeyi iyi bilir."},{"n":55,"t":"Babaları, oğulları, kardeşleri, kardeşlerinin oğulları, kız kardeşlerinin oğulları, diğer kadınlar ve (kadın) hizmetçileri karşısında (serbest bir biçimde giyinmelerinde) kadınlar için bir sakınca yoktur. ALLAH’ı saysınlar. ALLAH her şeye Tanıktır."},{"n":56,"t":"ALLAH ve melekleri peygamberi desteklemektedir. Ey gerçeği onaylayanlar siz de onu destekleyin, gereken saygı ve itaati gösterin."},{"n":57,"t":"ALLAH’a ve elçisine hakaret edenlere, ALLAH dünya ve ahirette lanet eder ve onlar için aşağılayıcı bir ceza hazırlamıştır."},{"n":58,"t":"Gerçeği onaylayan erkeklere ve kadınlara, haksız yere hakaret edenler, bir iftira ve apaçık bir günah yüklenmişlerdir."},{"n":59,"t":"Ey peygamber, hanımlarına, kızlarına ve gerçeği onaylayanların kadınlarına örtülerini üzerlerine salmalarını söyle. Bu, onların (erdemli kadınlar olarak) ayırdedilip hakarete uğramamaları için daha elverişlidir. ALLAH Bağışlayandır, Rahimdir."},{"n":60,"t":"İkiyüzlüler, kalplerinde hastalık bulunanlar ve kentteki saldırganlar (size karşı olan saldırılarına) son vermezlerse seni onlara musallat ederiz; sonra orada, senin çevrende kısa bir süre kalabilirler."},{"n":61,"t":"Lanetlenirler; nerede rastlansalar, (saldırıdan vazgeçmezlerse) yakalanıp öldürülebilirler."},{"n":62,"t":"Öncekilere uygulanmış ALLAH’ın sünneti (yasasıdır). ALLAH’ın sünnetinde herhangi bir değişme bulamazsın."},{"n":63,"t":"Halk senden o anı soruyor. De ki: \"Onun bilgisi ALLAH’ın katındadır; ne bilirsin, belki de o an yakındır.\""},{"n":64,"t":"ALLAH inkârcıları lanetlemiş ve onlara cehennemi hazırlamıştır."},{"n":65,"t":"Orada ebedi kalıcıdırlar. Ne bir veli (sahip) ne de bir yardımcı bulamazlar."},{"n":66,"t":"Yüzleri ateşte çevrildiği gün, \"Keşke ALLAH’a itaat etseydik, keşke elçisine itaat etseydik\" derler."},{"n":67,"t":"Derler ki, \"Efendimiz, sadatlarımıza/şeyhlerimize ve büyüklerimize uyduk; onlar da bizi yoldan saptırdılar.\""},{"n":68,"t":"\"Efendimiz, onlara iki kat ceza ver, onları büyük bir lanetle lanetle.\""},{"n":69,"t":"Ey gerçeği onaylayanlar, Musa’yı incitenler gibi olmayın. ALLAH onu onların suçlamalarından akladı. ALLAH’ın katında itibarı olan biriydi."},{"n":70,"t":"Ey gerçeği onaylayanlar, ALLAH’ı sayın ve doğru söz söyleyin."},{"n":71,"t":"Ki işlerinizi düzeltsin, günahlarınızı bağışlasın. Kim ALLAH’a ve elçisine uyarsa büyük bir zafer kazanmıştır."},{"n":72,"t":"Biz sorumluluğu (sınanmayı) göklere, yere, dağlara sunmuştuk da onlar onu yüklenmekten çekinmişler ve kabul etmemişlerdi. Ancak onu insan yüklendi; o zalim ve cahil olmuştu."},{"n":73,"t":"Böylece, ALLAH ikiyüzlü erkekleri ve kadınları, ortak koşan erkekleri ve kadınları cezalandırır ve ALLAH gerçeği onaylayan erkeklerin ve kadınların tövbelerini kabul eder. ALLAH Bağışlayandır, Rahimdir."}]},{"id":34,"name":"Sebe Suresi","verses":[{"n":1,"t":"Övgü, göklerde ve yerde ne varsa kendisine ait bulunan ALLAH’adır. Ahirette de övgü O’nadır. O Bilgedir, Haber Alandır."},{"n":2,"t":"Yere gireni, ondan çıkanı; gökten ineni ve oraya yükseleni bilir. O Rahimdir, Bağışlayandır."},{"n":3,"t":"İnkarcılar, \"O an, hiçbir vakit gerçekleşmeyecek\" dediler. De ki: \"Kesinlikle, Efendime andolsun size gelecektir. O, geleceği Bilendir. Göklerde ve yerde bir atom ağırlığı O’ndan gizli kalmaz. İster ondan küçük olsun, yahut büyük olsun… Hepsi apaçık bir kitaptadır.\""},{"n":4,"t":"Böylece, gerçeği onaylayanları ve erdemli davrananları ödüllendirir. Onlar için bir bağışlanma ve bol rızık vardır."},{"n":5,"t":"Ayetlerimiz ve mucizelerimize karşı meydan okuyup duranlar için acıklı ve korkunç bir ceza vardır."},{"n":6,"t":"Kendilerine bilgi verilmiş olanlar, Efendinden sana indirilenin gerçek olduğunu ve onun Üstün ve en çok Övülen’in yoluna ilettiğini görürler."},{"n":7,"t":"İnkarcılar dediler, \"Siz parça parça dağıldıktan sonra yeni bir yaratılışla diriltileceğinizi bildiren bir adamı size gösterelim mi?\""},{"n":8,"t":"\"ALLAH’a yalan mı yakıştırıyor, yoksa kendisinde delilik mi var?\" Halbuki ahireti onaylamayanlar, uzak bir sapıklık ve azap içindedirler."},{"n":9,"t":"Göklerde ve yerde, önlerinde ve arkalarında bulunanlara bakmadılar mı? Dilersek onları yere batırır veya gökten bir kütle düşürürüz. Her yönelen kul için elbette bunda bir işaret vardır."},{"n":10,"t":"Katımızdan Davud’a lütufta bulunmuştuk: \"Ey dağlar, ilahisine katılın; ey kuşlar sizler de.\" Ona demiri yumuşatmıştık."},{"n":11,"t":"\"Ölçüsü ve dokumasıyla kusursuz zırhlar yap. Erdemli davranın. Ben, yaptığınız her şeyi Görenim.\""},{"n":12,"t":"Süleyman’a da, sabah gidişi bir ay(lık yol alan), akşam dönüşü de bir ay(lık yol alan) rüzgarı verdik ve onun için petrol kaynağını fışkırtarak akıttık. Efendinin izniyle, cinlerden de bir kısım emrinde çalışırdı. Onlardan kim emrimizden saparsa onu çetin bir cezayı tattırırdık."},{"n":13,"t":"O ne dilerse onun için yaparlardı: Mihraplar, heykeller, derin havuzlar ve ağır kazanlar… Ey Davut ailesi, şükür göstergesi olarak çalışın. Kullarımdan pek azı şükredicidir."},{"n":14,"t":"Ölümüne hükmettiğimiz zaman, onlara onun ölmüş olduğunu, ancak değneğini yiyen bir yer yaratığı gösterdi. Yıkıldığı zaman cinler gerçeği gördü: Görülmeyeni bilselerdi o küçültücü zor işe devam etmezlerdi."},{"n":15,"t":"Sebelilerin evleri, sağlı sollu iki bahçeyle birlikte bir harikaydı. Efendinizin rızkından yeyin ve O’na şükredin. Güzel bir ülke ve Bağışlayan bir Rab…"},{"n":16,"t":"Fakat onlar yüz çevirdiler. Biz de barajın selini onlara göndererek çifte bahçelerini, acı meyveler, ılgın ve biraz da sedir ağacı içeren çifte bahçelere çevirdik."},{"n":17,"t":"Nankörlükleri yüzünden onları böyle cezalandırdık. Biz nankörden başkasını mı cezalandırırız?"},{"n":18,"t":"Onlarla bereketli kıldığımız bölgeler arasına vahalar yerleştirdik ve orayı yolculuğa elverişli yaptık: \"Geceleri ve gündüzleri güvenlik içinde orada dolaşın.\""},{"n":19,"t":"\"Efendimiz, seferlerimizin arasını uzaklaştır\" diyerek kendilerine zulmettiler. Sonunda onları darmadağın edip tarihe gömdük. Her sabırlı ve şükreden kişi için bunda dersler vardır."},{"n":20,"t":"İblis, onlar hakkındaki zannını doğru çıkardı. Gerçeği onaylayan bir grup hariç ona uydular."},{"n":21,"t":"Aslında onun onlar üzerine hiçbir otoritesi yoktu. Ancak, ahireti onaylayanı ondan kuşku duyandan böylece ayırırız. Efendin her şeyi kontrol etmektedir."},{"n":22,"t":"De ki: \"ALLAH’ın dışında ileri sürdüklerinizi çağırın. Onlar göklerde ve yerde bir atom ağırlığına bile sahip değillerdir. Onların her ikisinde de bir ortaklıkları yoktur. O da onlardan hiçbirisini yardımcı edinmemiştir.\""},{"n":23,"t":"O’nun katında şefaat yarar sağlamaz; ancak izin verdiği hariç. Nihayet, yüreklerindeki korkuları giderilince, \"Efendiniz ne dedi?\" derler. \"Gerçeği söyledi\" derler. O En Yücedir, En Büyüktür."},{"n":24,"t":"De ki: \"Sizin için göklerden ve yerden kim besin sağlıyor?\" De ki: \"ALLAH.\" Öyleyse ya biz veya siz ya doğru yoldadır ya da açık bir sapıklık içindedir."},{"n":25,"t":"De ki: \"Bizim suçlarımızdan siz sorumlu değilsiniz, biz de sizin yaptıklarınızdan sorumlu değiliz.\""},{"n":26,"t":"De ki: \"Efendimiz hepimizi toplar ve sonra aramızda gerçeğe göre hüküm verir. O Yargıçtır, Bilendir.\""},{"n":27,"t":"De ki: \"O’na kattığınız ortakları bana gösteriniz. Asla! O Üstün ve Bilge olan ALLAH’tır.\""},{"n":28,"t":"Biz seni tüm halka bir müjdeci ve uyarıcı olarak gönderdik. Ancak halkın çoğu bilmez."},{"n":29,"t":"\"Doğru söylüyorsanız o söz ne zaman gerçekleşecek?\" diyerek meydan okuyorlar."},{"n":30,"t":"De ki: \"Size bir an gecikmeyecek, bir an da erken gelmeyecek belirlenmiş bir gününüz vardır.\""},{"n":31,"t":"İnkarcılar, \"Biz ne bu Kuran’ı ne de ondan öncekileri onaylamayız\" dediler. Zalimleri, Rab’leri huzurunda duruşma sırasında birbiriyle atışırken bir görseydin! (Öğrenim, araştırma, ekonomik, politik v.b. yönlerden) güçsüzleştirilenler, büyüklük taslamış olanlara, \"Siz olmasaydınız biz gerçeği onaylayan kişiler olurduk\" derler."},{"n":32,"t":"Büyüklenenler, güçsüzleştirilen izleyicilerine, \"Size hidayet geldikten sonra biz mi sizi saptırdık? Hayır, suçlu olanlar sizdiniz\" derler."},{"n":33,"t":"Güçsüzleştirilenler, büyüklenenlere, \"Asıl sizdiniz. Bizim ALLAH’a karşı nankörlük göstermemiz ve O’na ortaklar koşmamız için gece gündüz planlar kuruyordunuz.\" Azabı gördüklerinde içlerinde pişmanlık duyarlar. İnkarcıların boyunlarına prangalar vurmuşuzdur. Yalnız yaptıklarının karşılığını almıyorlar mı?"},{"n":34,"t":"Bir kente her ne zaman bir uyarıcı gönderirsek, elitleri, \"Sizin kendisiyle gönderildiğiniz mesajı reddediyoruz\" dediler."},{"n":35,"t":"Hatta, \"Bizim paramız ve çocuklarımız daha çoktur; biz cezalandırılmayacağız\" dediler."},{"n":36,"t":"De ki: \"Efendim nimetleri dilediğine bol verir veya kısar. Ama halkın çoğu bilmez.\""},{"n":37,"t":"Sizi bize yaklaştıran şey ne paralarınız, ne de çocuklarınızdır. Ancak gerçeği onaylayan ve erdemli davrananlar hariç. Onlara, yaptıklarının iki kat karşılığı verilecektir ve odalarında güvenlik içindedirler."},{"n":38,"t":"Ayetlerimize meydan okuyanlar azapta kalacaklar."},{"n":39,"t":"De ki: \"Efendim, kullarından dilediğine nimeti bol verir ve onu kısar. Neyi verirseniz, onu size ödeyecektir. O, rızık verenlerin en iyisidir.\""},{"n":40,"t":"Hepsini topladığı gün meleklere, \"Şunlar mı size hizmet ediyordu?\" der."},{"n":41,"t":"Dediler ki, \"Sen yücesin, velimiz (dostumuz) onlar değil, Sensin. Hayır, onlar cinlere hizmet ediyorlardı. Çokları onları onaylıyordu.\""},{"n":42,"t":"O gün birbirinize yarar ve zarar veremezsiniz. Zalimlere, \"Yalanlamakta olduğunuz ateş azabını tadın\" deriz."},{"n":43,"t":"Kendilerine apaçık ayetlerimiz okunduğunda, \"Bu, kesinlikle, sizi atalarınızın hizmet etme yolundan saptırmak isteyen bir adamdır.\" Dahası, \"Bu uydurulmuş bir iftiradan başka bir şey değildir\" dediler. İnkarcılar, kendilerine gelen gerçek için, \"Besbelli, bu bir büyüdür\" dediler."},{"n":44,"t":"Onlara, inceleyecekleri bir Kitap vermemiş ve senden önce onlara bir uyarıcı göndermemiştik."},{"n":45,"t":"Onlardan öncekiler yalanladılar. Halbuki onlara verilenlerin onda birine ulaşmamışlardı. Elçilerimi yalanladılar. Beni tanımamak da nasılmış?"},{"n":46,"t":"De ki: \"Size bir tek öğüdüm var: ALLAH için ikişer ikişer, yahut teker teker kalkın, sonra düşünün. Sizin arkadaşınızda bir delilik yoktur. O sadece, çetin bir cezadan önce sizi uyaran birisidir.\""},{"n":47,"t":"De ki: \"Ben sizden herhangi bir ücret istemiyorum; o sizin olsun. Benim ücretim ancak ALLAH’tandır. O her şeye Tanıktır.\""},{"n":48,"t":"De ki: \"Benim Efendim gerçeği etkili kılar. O tüm gizemleri Bilendir.\""},{"n":49,"t":"De ki: \"Gerçek gelmiştir; batıl ise ne yeni bir şeyi başlatabilir, ne de tekrarlayabilir.\""},{"n":50,"t":"De ki: \"Saparsam, kendi kusurumdandır, yolu bulursam Efendimin bana vahyetmesindendir. O İşitendir, Yakındır.\""},{"n":51,"t":"Korkuya kapıldıkları anı bir görsen; kaçamazlar; yakın bir yerden yakalanmışlardır."},{"n":52,"t":"\"Onu onayladık\" derler. Uzak bir yerden ona nasıl ulaşabilirler?"},{"n":53,"t":"Halbuki daha önce onu yalanlamışlardı. Bilgileri olmayan konularda uzaktan atıp tutuyorlardı."},{"n":54,"t":"Sonunda, hoşlandıkları şeylerden yoksun bırakılırlar. Kendilerinden önceki benzerlerine de aynı şey yapılmıştı. Onlar aşırı bir kuşku içinde idiler."}]},{"id":35,"name":"Fatır Suresi","verses":[{"n":1,"t":"Gökleri ve yeri yaratan; melekleri ikişer, üçer, dörder korumalı/boyutlu elçiler kılan ALLAH’a övgüler olsun. Yaratmada dilediğini güçlendirir. ALLAH her şeye gücü yetendir."},{"n":2,"t":"ALLAH’ın insanlara bağışladığı bir rahmeti engelleyebilecek yoktur. Onun alıkoyduğunu da O’ndan başka gönderebilecek yoktur. O Üstündür, Bilgedir."},{"n":3,"t":"Ey insanlar, ALLAH’ın size olan nimetlerini hatırlayın. Sizi gökten ve yerden rızıklandıran ALLAH’tan başka bir yaratıcı mı var? O’ndan başka tanrı yoktur. Nasıl da saptırılıyorsunuz?"},{"n":4,"t":"Seni yalanlarlarsa, senden önceki elçiler de yalanlandı. Tüm işlerin kontrolü ALLAH’a aittir."},{"n":5,"t":"Ey insanlar ALLAH’ın sözü gerçektir; dünya hayatı sizi aldatmasın. Kandırıcı, sizi ALLAH hakkında kandırmasın."},{"n":6,"t":"Sapkın sizin düşmanınızdır, siz de onu düşman edinin. O partisini sadece cehennem halkı olmaya çağırır."},{"n":7,"t":"İnkar edenler çetin bir cezaya mahkûm olmuştur. Gerçeği onaylayıp erdemli davrananlar ise bir bağışlanma ve büyük bir ödül haketmişlerdir."},{"n":8,"t":"Kötü işi, kendisine süslenip de onu güzel gören kimseye ne dersin? ALLAH dileyeni saptırır ve dileyeni yola iletir. Öyleyse onlar için kendini üzüp durma. ALLAH onların yaptıklarını iyi Bilir."},{"n":9,"t":"ALLAH, bulutları karıştıran rüzgarları gönderendir. Daha sonra onları ölü bir toprağa süreriz de ölümünden sonra toprağı diriltiriz. Diriliş de böyledir."},{"n":10,"t":"Onuru arzulayanlar, bilsin ki tüm onur ALLAH’a aittir. Güzel söz O’na çıkar, iyi iş de O’nu yükseltir. Kötülük planlayanlar için çetin bir azap vardır ve onların planı başarısızlıkla sonuçlanacaktır."},{"n":11,"t":"ALLAH sizi topraktan, sonra bir damlacıktan yaratmış ve sonra da sizi çiftler halinde üretmiştir. Bir dişinin gebe kalması ve doğurması ancak O’nun bilgisiyledir. Bir canlının uzun ömürlü olması da ömrünün kısa tutulması da ancak bir kitaptaki kayda göredir. Bu, ALLAH’a kolaydır."},{"n":12,"t":"İki deniz birbirine eşit değildir. Bu taze ve tatlı olup içimi yumuşaktır, şu ise tuzlu ve acıdır. Hepsinden taze et yersiniz ve takınacağınız mücevherleri çıkarırsınız. O’nun lütfunu arayan gemilerin onu yararak aktığını görürsün. Belki artık şükredersiniz."},{"n":13,"t":"Geceyi gündüzün içine sokar, gündüzü de gecenin içine sokar. Belirlenmiş bir süreye kadar akıp giden güneşi ve ayı emri altına almıştır. Efendiniz ALLAH işte böyledir; egemenlik O’na aittir. O’nun dışında çağırdıklarınız ise bir çekirdek zarını bile yönetemezler."},{"n":14,"t":"Onları çağırsanız sizin çağrınızı işitemezler. İşitseler bile size cevap veremezler. Diriliş gününde de sizin ortak koşmanızı inkâr ederler. Her şeyden Haberi Olan gibi kimse sana haber veremez."},{"n":15,"t":"Ey insanlar, siz ALLAH’a muhtaçsınız, ALLAH ise hiç kimseye muhtaç değildir, Övülendir."},{"n":16,"t":"Dilerse sizi götürür ve yerinize yeni yaratıkları getirir."},{"n":17,"t":"Bu, ALLAH için zor değildir."},{"n":18,"t":"Kimse kimsenin günahını yüklenmez. Günahla yüklenmiş birisi yükünü taşımak üzere akrabalarını bile çağırsa onun yükünden hiçbir şey taşınmaz. Sen yalnızca, kendi başlarına iken Rab’lerini sayan ve namazı gözeten kişileri uyarabilirsin. Kim kendisini arındırırsa kendisi yararına arınmıştır. Dönüş ALLAH’adır."},{"n":19,"t":"Kör ile gören bir olmaz."},{"n":20,"t":"Ne karanlıklar ile ışık."},{"n":21,"t":"Ne gölge ile sıcaklık."},{"n":22,"t":"Ne de diriler ile ölüler birdir. ALLAH, kim/kimi dilerse ona işittirir. Sen mezarlarda bulunanlara işittiremezsin."},{"n":23,"t":"Sen ancak bir uyarıcısın."},{"n":24,"t":"Seni bir müjdeci ve uyarıcı olarak gerçekle gönderdik. Her toplum içinde mutlaka bir uyarıcı gelmiştir."},{"n":25,"t":"Seni yalanlıyorlarsa, senden öncekiler de yalanlamışlardı. Elçileri kendilerine apaçık belgeler, ilahiler ve aydınlatıcı kitaplar getirdiler."},{"n":26,"t":"Sonra ben de inkâr edenleri yakaladım. Beni inkâr da nasılmış!"},{"n":27,"t":"ALLAH’ın gökten bir su indirdiğini görmedin mi? Onunla çeşitli renklerde ürünler çıkarırız. Hatta dağlarda bile beyaz, kırmızı, rengarenk veya kuzgun karası katmanlar vardır."},{"n":28,"t":"Aynı şekilde, insanlar, hayvanlar, çiftlik hayvanları da çeşitli renklerdedir. Bundan dolayıdır ki kulları arasında ALLAH’ı gereği gibi sayanlar bilim adamlarıdır. ALLAH Üstündür, Bağışlayandır."},{"n":29,"t":"ALLAH’ın kitabını okuyanlar, namazı gözetenler ve kendilerine verdiğimiz rızıklardan gizli ve açık yardım için verenler, tükenmeyen bir kazanç umarlar."},{"n":30,"t":"Çünkü onların ücretlerini tam verecek ve onlara olan lütfunu arttıracaktır. O Bağışlayandır, Takdir Edendir."},{"n":31,"t":"Bu kitapta sana vahyettiklerimiz, kendisinden öncekileri doğrulayan gerçektir. ALLAH kullarından Haberdardır, Görendir."},{"n":32,"t":"Sonra kullarımızdan seçtiklerimizi kitaba varis kıldık. Onlardan kimi kendilerine zulmedenlerdir, kimi orta yolu tutar, kimi de ALLAH’ın izniyle iyi işlerde öncüdür. İşte büyük lütuf budur."},{"n":33,"t":"Sonsuzluğa dek süren bahçelere gireceklerdir. Orada altın bilezikler ve inciler takacaklardır, oradaki elbiseleri ise ipektendir."},{"n":34,"t":"Ve derler: \"Endişelerimizi gideren ALLAH’a övgüler olsun. Efendimiz gerçekten Bağışlayandır, Takdir Edendir.\""},{"n":35,"t":"\"O ki lütfuyla bizi durulacak yurda yerleştirdi. Orada ne bir yorulma ne de bir bıkkınlık duyarız.\""},{"n":36,"t":"İnkar edenler için cehennem ateşi vardır. Ne ölmelerine izin verilir, ne de onlardan cehennem cezası hafifletilir. Nankörleri böyle cezalandırırız."},{"n":37,"t":"Orada, \"Efendimiz, bizi çıkar da yapmış olduğumuzdan farklı işler yapalım\" diye feryat ederler. Öğüt alabilecek bir kişinin öğüt alabileceği kadar uzun bir süre sizi yaşatmadık mı? Size uyarıcı da gelmişti. Öyleyse tadın. Zalimlerin yardımcısı yoktur."},{"n":38,"t":"ALLAH göklerin ve yerin geleceğini ve gizemlerini bilendir. O, göğüslerin gizlediğini Bilendir."},{"n":39,"t":"O ki sizi yeryüzünde yöneticiler kıldı. Kim inkâr ederse kendi zararına inkâr etmiştir. İnkarcıların inkârı, Rab’leri katında nefretten başka bir şey arttırmaz. İnkarcıların inkârı kayıptan başka bir şey artırmaz."},{"n":40,"t":"De ki: \"ALLAH’ın dışında çağırdığınız ortaklarınızı düşündünüz mü; onlar yeryüzünde neyi yaratmışlar bana gösterin?\" Yoksa onların gökte bir ortaklıkları mı var? Veya onlara bir kitap verdik de ondaki bir delile mi dayanıyorlar? Doğrusu, zalimler birbirlerine ancak aldatıcı sözler verirler."},{"n":41,"t":"ALLAH, gökleri ve yeri kaos içine girmekten alıkoymaktadır. Kaosa girseler O’ndan başka kim onu engelleyebilir? O Şefkatlidir, Bağışlayandır."},{"n":42,"t":"Kendilerine bir uyarıcı gelse, tüm topluluklardan daha doğru yolda olacaklarına dair var güçleriyle ALLAH’a yemin ettiler. Kendilerine bir elçi geldiğinde, bu durum, onların ancak nefretini artırdı."},{"n":43,"t":"Yeryüzünde büyüklendiler, kötülük planladılar. Halbuki kötü plan sahibine geri teper. Geçmişlere uygulanan sünnet(yasa)den başkasını mı bekliyorlar? ALLAH’ın sünnetinde bir değişiklik göremezsin; ALLAH’ın sünnetinde bir sapma göremezsin."},{"n":44,"t":"Kendilerinden öncekilerin sonunun nasıl olduğuna bakmak için yeryüzünü dolaşmadılar mı? Onlar kendilerinden daha güçlüydüler. Göklerde ve yerde hiçbir şey ALLAH’ı aciz bırakamaz. O, Bilendir, Güçlüdür."},{"n":45,"t":"ALLAH insanları yaptıkları yüzünden cezalandırsaydı yeryüzünde hiçbir yaratık bırakmazdı. Fakat, onları belli bir süreye kadar ertelemektedir. Ne zaman ki süreleri biter, işte o zaman ALLAH kullarının (hesabını) görür."}]},{"id":36,"name":"Yasin Suresi","verses":[{"n":1,"t":"Y. S."},{"n":2,"t":"Bilge Kuran’a and olsun."},{"n":3,"t":"Sen elbette elçilerden birisin."},{"n":4,"t":"Dosdoğru bir yol üzerinde."},{"n":5,"t":"Bu, Üstün ve Rahim olanın indirdiği bir vahiydir."},{"n":6,"t":"Ataları uyarılmadığından tümüyle habersiz kalmış bir toplumu uyarman için…"},{"n":7,"t":"Çoklarının gerçeği onaylamayacağına dair söz gerçekleşmiştir."},{"n":8,"t":"Boyunlarına, çenelerine kadar varan prangalar taktık da kafaları yukarıya dikilmiştir."},{"n":9,"t":"Önlerinden bir set ve arkalarından bir set çekerek onları perdeledik; artık göremezler."},{"n":10,"t":"Onları uyarsan da uyarmasan da onlar için birdir; gerçeği onaylamazlar."},{"n":11,"t":"Sen ancak, mesaja uyan ve yalnız başına iken Rahman’a karşı saygılı olan bir kimseyi uyarabilirsin. Onu bağışlanma ve bol bir ödülle müjdele."},{"n":12,"t":"Ölüleri biz, evet biz diriltiriz, onların yaptıklarını ve (ölümlerinden sonraki) sonuçlarını yazarız. Biz her şeyi apaçık bir kitapta saymışızdır."},{"n":13,"t":"Onlara, bir kent halkının kendilerine gelen elçilere gösterdiği tavrın örneğini ver."},{"n":14,"t":"Onlara iki elçi göndermiştik, ikisini de yalanladılar. Bunun üzerine üçüncü biriyle desteklemiştik. \"Biz size gönderilen elçileriz\" demişlerdi."},{"n":15,"t":"Dediler ki, \"Siz de bizim gibi insandan başka bir şey değilsiniz. Rahman ise hiçbir şey indirmemiştir. Siz yalan söylüyorsunuz.\""},{"n":16,"t":"Dediler ki, \"Efendimiz bilir ki biz size gönderildik.\""},{"n":17,"t":"\"Bizim görevimiz, açıkça duyurmaktan ibarettir.\""},{"n":18,"t":"Dediler ki, \"Sizin yüzünüzden uğursuzluğa uğradık. Eğer son vermezseniz sizi taşlarız/kovarız ve bizden size acı bir ceza dokunacaktır.\""},{"n":19,"t":"Dediler ki, \"Uğursuzluğunuz sizden kaynaklanmaktadır. Size uyarıda bulunulduğu için mi? Siz gerçekten sınırı aşan bir topluluksunuz.\""},{"n":20,"t":"Kentin en uzak yakasından bir adam koşarak, \"Ey halkım\" dedi, \"Elçilere uyun.\""},{"n":21,"t":"\"Sizden bir ücret istemeyenlere uyun. Onlar doğru yoldadır.\""},{"n":22,"t":"\"Beni yaratana ne diye hizmet etmeyeyim? Siz de O’na döneceksiniz.\""},{"n":23,"t":"\"O’nun dışında tanrılar mı edineyim? Eğer Rahman bana zarar vermek dilese, ne onların şefaati bana bir yarar sağlayabilir ne de beni kurtarabilirler.\""},{"n":24,"t":"\"O zaman tümüyle sapıtmış olurum.\""},{"n":25,"t":"\"Ben sizin Efendinizi onayladım; lütfen beni dinleyin.\""},{"n":26,"t":"(Ölüm anında) Kendisine, \"Bahçeye gir\" denir. \"Keşke benim halkım bir bilseydi…\""},{"n":27,"t":"\"Efendimin beni bağışladığını ve beni ağırladığını…\""},{"n":28,"t":"Ondan sonra biz, halkının üzerine gökten bir ordu indirmedik; indirmeye gerek duymadık."},{"n":29,"t":"Sadece bir patlama… Hemen donakaldılar."},{"n":30,"t":"Halkın durumu pek yazık. Kendilerine her ne zaman bir elçi gelse onunla alay ederlerdi."},{"n":31,"t":"Kendilerinden önce nice nesilleri yok ettiğimizi ve onların bir daha kendilerine dönmediklerini görmezler mi?"},{"n":32,"t":"Hepsi toplanıp huzurumuza getirileceklerdir."},{"n":33,"t":"Ölü toprak onlar için bir ayettir: Onu diriltiriz ve oradan taneler çıkarırız da ondan yerler."},{"n":34,"t":"Orada hurma ağaçları ve üzümlerden oluşan bağ ve bahçeler yetiştirdik ve pınarlar fışkırttık."},{"n":35,"t":"Ki onun ürünlerinden ve elleriyle yetiştirdiklerinden yesinler. Şükretmeyecekler mi?"},{"n":36,"t":"Yerin bitirdiklerinden, kendi cinslerinden ve daha bilmedikleri nice şeylerden türlü çiftleri yaratan pek yücedir."},{"n":37,"t":"Gece de onlar için bir ayettir: Ondan gündüzü soyarız da onlar karanlıkta kalırlar."},{"n":38,"t":"Güneş belirlenmiş olan rotasında akıp gitmektedir. Bu Üstün ve Bilgin olanın kurduğu bir düzendir."},{"n":39,"t":"Aya da çeşitli evreler belirledik. Nitekim eski ve eğri bir hurma dalı gibi döner."},{"n":40,"t":"Ne güneş aya yetişebilir, ne de gece, gündüzü geçebilir. Her biri bir yörüngede yüzmektedir."},{"n":41,"t":"Onlar için bir başka ayet de insan soyunu yüklü gemide taşımamızdır."},{"n":42,"t":"Aynı şekilde, onlar için buna benzer (başka) ulaşım araçları da yarattık."},{"n":43,"t":"Dileseydik onları boğardık; ne bir çığlıklarına yetişen olurdu, ne de kurtulabilirlerdi."},{"n":44,"t":"Bunun yerine, bizden bir merhamet görürler ve belli bir süreye kadar yaşatılırlar."},{"n":45,"t":"Kendilerine, \"Geçmişinizden ibret alıp geleceğiniz için sakının ki merhamet edilesiniz\" denilmişti."},{"n":46,"t":"Rab’lerinin ayetlerinden bir ayet kendilerine geldiğinde, ondan yüz çevirmeyi adet edinmişlerdi."},{"n":47,"t":"Kendilerine, \"ALLAH’ın size verdiği rızıklardan verin\" denildiğinde, inkâr edenler gerçeği onaylayanlara, \"ALLAH’ın, dilediği taktirde besleyebileceği kimseleri mi besleyelim? Siz gerçekten iyice sapıtmışsınız\" derler."},{"n":48,"t":"Aynı zamanda, \"Doğru sözlü iseniz o söz ne zaman gerçekleşecek?\" diye meydan okurlar."},{"n":49,"t":"Çekişip dururlarken kendilerini yakalayacak bir tek patlamayı beklemektedirler."},{"n":50,"t":"Ne bir vasiyet bırakmaya vakit bulurlar ne de ailelerine dönebilirler."},{"n":51,"t":"Boruya üflenince, onlar mezarlarından kalkıp Rab’lerine koşacaklar."},{"n":52,"t":"\"Vay halimize\" derler, \"Yattığımız yerden bizi kim kaldırdı? Bu, Rahman’ın söz verdiği şeydi. Demek elçiler doğru söylemişti.\""},{"n":53,"t":"Sadece bir patlama… Hemen huzurumuza toplanıp getirilirler."},{"n":54,"t":"Bugün hiç kimseye en ufak bir haksızlık edilmez ve yaptığınızın karşılığından başkasını da görmezsiniz."},{"n":55,"t":"Bahçe halkı o gün zevk ve eğlence ile meşguldürler."},{"n":56,"t":"Eşleriyle birlikte gölgeliklerde, koltuklara yaslanmışlardır."},{"n":57,"t":"Onlar için meyveler ve istedikleri her şey vardır."},{"n":58,"t":"Rahim olan Rab’den söz olarak \"selam\" vardır."},{"n":59,"t":"Ey suçlular, siz bugün ayrılın."},{"n":60,"t":"Ey Adem’in çocukları, sapkına hizmet etmeyeceğinize dair sizden söz almamış mıydım? O sizin açık düşmanınızdır."},{"n":61,"t":"Bana hizmet edin. Bu en doğru yoldur."},{"n":62,"t":"Buna rağmen o, sizden birçok nesilleri saptırdı. Hiç aklınızı kullanmaz mıydınız?"},{"n":63,"t":"İşte, size söz verilen cehennem budur!"},{"n":64,"t":"İnkarınızın bir sonucu olarak orada yanınız."},{"n":65,"t":"O gün ağızlarına mühür vururuz da, bizimle elleri konuşur ve yapmış olduklarına da ayakları tanıklık eder."},{"n":66,"t":"Dilesek gözlerini büsbütün kör ederdik. Yolu bulmaya çalıştıklarında göremezlerdi."},{"n":67,"t":"Dilesek onları oldukları yerde dondurur ne ileri gidebilir ne de geri dönebilirlerdi."},{"n":68,"t":"Kime çok ömür verirsek, yaratılışını tersine çeviririz. Anlamaz mısınız?"},{"n":69,"t":"Ona şiir öğretmiş değiliz, zaten ona uygun düşmez. Bu, ancak bir mesaj ve apaçık bir Kuran’dır."},{"n":70,"t":"Dirileri uyarır ve inkârcıları açığa çıkarır."},{"n":71,"t":"Görmezler mi, kendi ellerimizle onlar için çiftlik hayvanlarını yarattık da onlara sahip olmaktadırlar?"},{"n":72,"t":"Onları kendilerine boyun eğdirdik; bir kısmına binmekte bir kısmından da yemektedirler."},{"n":73,"t":"Ve onlar için onlarda başka yararlar ve içecekler vardır. Şükretmeyecekler mi?"},{"n":74,"t":"ALLAH’tan başka tanrılar edindiler. Belki kendilerine yardım ederler diye."},{"n":75,"t":"Oysa onlara yardım edemezler; hatta tam tersine kendileri onları korumak için nöbet bekleyen askerlerdir."},{"n":76,"t":"Sözleri seni üzmesin. Gizledikleri ve açıkladıkları her şeyi çok iyi biliriz."},{"n":77,"t":"İnsan, kendisini bir damlacıktan yarattığımızı görmez mi ki bize karşı apaçık bir düşman kesilir?"},{"n":78,"t":"Ve yaradılışını unutarak bize örnekli bir soru yöneltti: \"Çürüdükten sonra kemikleri kim diriltecek?\""},{"n":79,"t":"De ki: \"Kim onları ilk kez yarattıysa onları yine O diriltecek. O her türlü yaratmayı bilendir.\""},{"n":80,"t":"O ki, size yeşil (klorofilli) ağaçtan ateş çıkarandır. Nitekim onu yakıyorsunuz."},{"n":81,"t":"Gökleri ve yeri yaratan onların benzerini yaratmaya güç yetiremez mi? Gerçekten O, Yaratandır, Bilendir."},{"n":82,"t":"Bir şeyi dilediği zaman, ona sadece \"Ol!\" der ve o da hemen oluverir."},{"n":83,"t":"Her şeyin yönetimini elinde bulunduran çok yücedir ve siz de O’na döndürüleceksiniz."}]},{"id":37,"name":"Saffat Suresi","verses":[{"n":1,"t":"And olsun sıralar halinde dizenlere,"},{"n":2,"t":"İtekleyip sürenlere,"},{"n":3,"t":"Ve mesajı okuyanlara…"},{"n":4,"t":"Ki sizin Tanrınız birdir."},{"n":5,"t":"Göklerin, yerin ve her ikisinin arasında bulunanların Rabbidir, doğuların Rabbidir."},{"n":6,"t":"Biz en aşağıdaki göğü gezegenler ile süsleyip,"},{"n":7,"t":"Her türlü inatçı sapkına karşı bir koruma yaptık."},{"n":8,"t":"Yüce topluluğu dinleyemezler; her yandan atılırlar."},{"n":9,"t":"Kovulurlar; sürekli bir azabı haketmişlerdir."},{"n":10,"t":"Bir söz kapan olursa, onu, delici bir ışın izler."},{"n":11,"t":"Sor onlara, \"Yaratılış bakımından onlar mı daha çetin, yoksa bizim yarattıklarımız mı?\" Onları yapışkan bir balçıktan yarattık."},{"n":12,"t":"Sen hayranlık duyarken onlar alay ediyorlar."},{"n":13,"t":"Kendilerine hatırlatıldığında öğüt almıyorlar."},{"n":14,"t":"Bir delil gördüklerinde onu aşağılıyorlar."},{"n":15,"t":"Derler, \"Bu, apaçık bir büyüden başka bir şey değildir.\""},{"n":16,"t":"\"Ölüp, toprak ve kemik olduktan sonra mı, biz mi diriltilecekmişiz?\""},{"n":17,"t":"\"Hatta bizden önceki atalarımız da mı?\""},{"n":18,"t":"De ki: \"Evet, hem de horlanarak.\""},{"n":19,"t":"O, bir tek dokunmadır. O zaman (kalkıp) bakınırlar."},{"n":20,"t":"\"Vay halimize!\" derler, \"Bu Yargı Günüdür.\""},{"n":21,"t":"Bu, sizin yalanlamış olduğunuz karar günüdür."},{"n":22,"t":"Zalimleri toplayın. Eşlerini ve,"},{"n":23,"t":"ALLAH’tan başka hizmet ettiklerini… Onlara cehennemin yolunu gösterin."},{"n":24,"t":"Ve durdurun onları; sorguya çekileceklerdir."},{"n":25,"t":"\"Neden birbirinize yardım etmiyorsunuz?\""},{"n":26,"t":"Hayır, o gün tümüyle teslim olmuşlardır."},{"n":27,"t":"Dönüp birbirlerini sorgularlar."},{"n":28,"t":"\"Siz bize sağ yanımızdan yaklaşıyordunuz\" derler."},{"n":29,"t":"Derler ki, \"Aslında siz onaylamış kimseler değildiniz.\""},{"n":30,"t":"\"Bizim sizin üzerinizde herhangi bir gücümüz yoktu. Aksine siz azmış bir topluluktunuz.\""},{"n":31,"t":"\"Efendimizin hakkımızdaki sözü gerçekleşti, artık tadacağız.\""},{"n":32,"t":"\"Biz azmıştık. Sizi de azdırdık.\""},{"n":33,"t":"Böylece, o gün onlar azapta ortaktırlar."},{"n":34,"t":"Biz suçlulara böyle yaparız."},{"n":35,"t":"Kendilerine \"La ilahe illa ALLAH\" denildiğinde büyükleniyorlardı."},{"n":36,"t":"\"Tanrılarımızı deli bir şair için mi terk edeceğiz?\" diyorlardı."},{"n":37,"t":"Doğrusu, o, gerçeği getirmiş ve elçileri doğrulamıştır."},{"n":38,"t":"Siz elbette acı azabı tadacaksınız."},{"n":39,"t":"Sadece yapmış olduklarınızın karşılığını görüyorsunuz."},{"n":40,"t":"Kendilerini sadece ALLAH’a adamış kulları hariç."},{"n":41,"t":"Onlar bilinen bir rızkı haketmişlerdir."},{"n":42,"t":"Meyvelerle ağırlanacaklardır."},{"n":43,"t":"Nimet bahçelerinde."},{"n":44,"t":"Karşılıklı koltuklar üzerinde."},{"n":45,"t":"Onlara pınarlardan doldurulmuş kadehler sunulur."},{"n":46,"t":"Durudur, içenlere zevk ve lezzet verir."},{"n":47,"t":"Onda ne başağrısı ne de sarhoşluk vardır."},{"n":48,"t":"Yanlarında da, gözlerinin içine bakan güzel eşler…"},{"n":49,"t":"Korunmuş yumurtalar gibidirler."},{"n":50,"t":"Birbirlerine dönüp soruşurlar."},{"n":51,"t":"İçlerinden biri der ki, \"Benim bir arkadaşım vardı.\""},{"n":52,"t":"\"Şöyle konuşurdu, ’Sen de doğruluyor musun?’ \""},{"n":53,"t":"\"Biz toprak ve kemik olduktan sonra mı, biz mi dirileceğiz?\""},{"n":54,"t":"(Yanındakilere,) \"Bakar mısınız?\" der."},{"n":55,"t":"Baktığında, onu cehennemin ortasında bulur."},{"n":56,"t":"\"ALLAH’a andolsun, az kalsın sen beni de mahvedecektin\" der."},{"n":57,"t":"\"Efendimin nimeti olmasaydı, ben de şimdi seninle birlikte olurdum.\""},{"n":58,"t":"\"(Sana göre), biz öldüğümüzde\""},{"n":59,"t":"\"İlk ölüm hariç, cezalandırılmayacaktık hani?\""},{"n":60,"t":"İşte büyük zafer budur."},{"n":61,"t":"Çalışanlar bunun için çalışmalı."},{"n":62,"t":"Bu mu daha iyi bir duraktır, yoksa zakkum ağacı mı?"},{"n":63,"t":"Biz onu zalimler için bir test kıldık."},{"n":64,"t":"O, cehennemin dibinden çıkan bir ağaçtır."},{"n":65,"t":"Tomurcukları sapkınların başı gibidir."},{"n":66,"t":"Onlar ondan yiyerek karınlarını doyuracaklar."},{"n":67,"t":"Bunun üstüne onlar için cehennemi bir kokteyl vardır."},{"n":68,"t":"Sonra dönüşleri yine cehennemedir."},{"n":69,"t":"Onlar, atalarını sapık kimseler olarak bulmuşlardı."},{"n":70,"t":"Ve onların izlerini körükörüne izliyorlardı."},{"n":71,"t":"Kendilerinden önce de niceleri aynı şekilde sapmıştı."},{"n":72,"t":"İçlerinden uyarıcılar göndermiştik."},{"n":73,"t":"Uyarılanların sonunun nasıl olduğuna bir bak."},{"n":74,"t":"Kendilerini sadece ALLAH’a adayan kulları hariç."},{"n":75,"t":"Nuh bize seslenmişti de ne güzel karşılık vermiştik."},{"n":76,"t":"Onu ve ailesini o büyük felaketten kurtarmıştık."},{"n":77,"t":"Onun soyunu ise yaşattık."},{"n":78,"t":"Ve biz onu daha sonrakiler için bıraktık."},{"n":79,"t":"Tarih boyunca Nuh’a selam."},{"n":80,"t":"Biz güzel davrananları işte böyle ödüllendiririz."},{"n":81,"t":"O, bizim gerçeği onaylayan kullarımızdandı."},{"n":82,"t":"Sonra diğerlerini boğduk."},{"n":83,"t":"İbrahim onun bir kolundan idi."},{"n":84,"t":"Efendisine tertemiz bir kalp ile gelmişti."},{"n":85,"t":"Babasına ve halkına, \"Neye hizmet ediyorsunuz?\" demişti."},{"n":86,"t":"\"ALLAH’ın dışında, uyduruk tanrılar mı istiyorsunuz?\""},{"n":87,"t":"\"Evrenlerin Efendisini ne zannediyorsunuz?\""},{"n":88,"t":"Yıldızlara bir göz attı."},{"n":89,"t":"\"Bıktım, yoruldum artık\" dedi."},{"n":90,"t":"Onlar da onu bırakıp gittiler."},{"n":91,"t":"Sonra, tanrılarına yöneldi ve \"Yemez misiniz?\" dedi."},{"n":92,"t":"\"Neyiniz var, neden konuşmuyorsunuz?\""},{"n":93,"t":"Ve üzerlerine yürüyüp tüm gücüyle vurdu."},{"n":94,"t":"Hemen ona doğru koşuştular."},{"n":95,"t":"Dedi ki, \"Yonttuğunuz şeylere mi hizmet ediyorsunuz?.\""},{"n":96,"t":"\"ALLAH, sizi de ve yaptığınız şeyleri de yaratandır.\""},{"n":97,"t":"Dediler ki, \"Onun için bir yapı kurun ve onu ateşe atın.\""},{"n":98,"t":"Onun için bir plan düşündüler, fakat biz onları altettik."},{"n":99,"t":"Dedi ki, \"Ben Efendime gidiyorum; O bana yol gösterir.\""},{"n":100,"t":"\"Efendim, bana erdemli birini bağışla.\""},{"n":101,"t":"Biz de ona yumuşak huylu bir erkek çocuk bağışladık."},{"n":102,"t":"Onunla birlikte çalışma çağına varınca, \"Oğlum\" dedi, \"Rüyamda seni boğazlamam gerektiğini görüyorum. Ne düşünüyorsun?\" \"Babacığım\" dedi, \"Sana emredileni uygula. ALLAH dilerse beni sabırlı bulacaksın.\""},{"n":103,"t":"Böylece ikisi de teslim oldu ve onu alnı üzerine yıktı."},{"n":104,"t":"Kendisine, \"İbrahim!\" diye seslendik,"},{"n":105,"t":"\"Sen rüyanı uyguladın.\" İyileri böyle ödüllendiririz."},{"n":106,"t":"Gerçekten bu apaçık bir sınavdı."},{"n":107,"t":"Ve biz ona fidye olarak büyük bir kurban verdik."},{"n":108,"t":"Sonrakiler için onun tarihini koruduk."},{"n":109,"t":"İbrahim’e selam olsun."},{"n":110,"t":"Biz iyi davrananları böyle ödüllendiririz."},{"n":111,"t":"O, bizim gerçeği onaylayan kullarımızdandı."},{"n":112,"t":"Ona İshak’ı müjdeledik, erdemlilerden bir peygamber olarak."},{"n":113,"t":"Ona da İshak’a da lütufta bulunduk. Kuşkusuz, ikisinin de soyundan hem iyi davrananlar var, hem kendisine zulmedenler."},{"n":114,"t":"Biz Musa’ya ve Harun’a iyilikte bulunmuştuk."},{"n":115,"t":"İkisini ve halklarını o büyük felaketten kurtardık."},{"n":116,"t":"Onlara yardım ettik de üstün geldiler."},{"n":117,"t":"Ve o ikisine apaçık anlaşılan kitabı verdik."},{"n":118,"t":"Her ikisini doğru yola ilettik."},{"n":119,"t":"O ikisinin tarihini sonrakiler için koruduk."},{"n":120,"t":"Musa’ya ve Harun’a selam (barış) olsun."},{"n":121,"t":"Biz, iyi davrananları işte böyle ödüllendiririz."},{"n":122,"t":"O ikisi bizim gerçeği onaylayan kullarımızdandı."},{"n":123,"t":"İlyas elçilerden biriydi."},{"n":124,"t":"Halkına, \"Erdemli olmayacak mısınız?\" dedi."},{"n":125,"t":"En güzel Yaratanı bırakıp Ba’le mi hizmet edersiniz?"},{"n":126,"t":"ALLAH sizin ve geçmişteki atalarınızın Rabbidir."},{"n":127,"t":"Onu yalanladılar; onlar hesaba çekileceklerdir."},{"n":128,"t":"Kendilerini sadece ALLAH’a adayan kulları hariç."},{"n":129,"t":"Sonrakiler için onun tarihini koruduk."},{"n":130,"t":"İlyas ailesine selam olsun."},{"n":131,"t":"İyi davrananları biz böyle ödüllendiririz."},{"n":132,"t":"O bizim gerçeği onaylayan kullarımızdandı."},{"n":133,"t":"Lut da elçilerden biriydi."},{"n":134,"t":"Onu ve ailesini topluca kurtardık."},{"n":135,"t":"Ancak geride kalan yaşlı kadın hariç."},{"n":136,"t":"Sonra diğerlerini yok ettik."},{"n":137,"t":"Siz yıkıntılarının yanından geçiyorsunuz; sabahleyin,"},{"n":138,"t":"Ve geceleyin. Aklınızı kullanmaz mısınız?"},{"n":139,"t":"Yunus da elçilerden biriydi."},{"n":140,"t":"Dolu bir gemiye kaçmıştı."},{"n":141,"t":"Karşı çıktı ve kayanlardan oldu."},{"n":142,"t":"Balık onu yuttu, bundan o sorumluydu."},{"n":143,"t":"(Tanrı’yı) anıp düşünmeseydi,"},{"n":144,"t":"Diriliş Gününe kadar onun karnında kalacaktı."},{"n":145,"t":"Onu çöl gibi bir sahile attık, yorgun ve bitkin…"},{"n":146,"t":"Ve onun için orada geniş yapraklı ağaç yetiştirdik."},{"n":147,"t":"Biz onu yüz bin veya daha çok kişiye gönderdik."},{"n":148,"t":"Onayladılar, biz de onları bir süreye kadar geçindirdik."},{"n":149,"t":"Sor onlara, kızları senin Efendine, erkekleri kendilerine mi ayırıyorlar?\""},{"n":150,"t":"Yoksa melekleri, onların gözü önünde dişi olarak mı yarattık?"},{"n":151,"t":"Aslında onlar uydurdukları yüzünden diyorlar ki:"},{"n":152,"t":"\"ALLAH doğurdu.\" Onlar yalancıdırlar."},{"n":153,"t":"Kızları erkeklere mi tercih etti?"},{"n":154,"t":"Size ne oldu, nasıl karar veriyorsunuz?"},{"n":155,"t":"Öğüt almaz mısınız?"},{"n":156,"t":"Yoksa apaçık bir delile mi sahipsiniz?"},{"n":157,"t":"Doğruysanız kitabınızı getirin."},{"n":158,"t":"Hatta O’nunla cinler arasında bir akrabalık uydurdular. Halbuki cinler sorguya çekileceklerini bilirler."},{"n":159,"t":"ALLAH onların yakıştırmalarından çok Yücedir."},{"n":160,"t":"Kendilerini sadece ALLAH’a adayan kulları hariç."},{"n":161,"t":"Siz ve hizmet etmekte olduklarınız,"},{"n":162,"t":"O’na karşı kimseyi saptıramazsınız."},{"n":163,"t":"Ancak cehennemde yanacaklar hariç."},{"n":164,"t":"Her birimizin belli bir görevi vardır."},{"n":165,"t":"Biz, (O’nun emrinde) sıra sıra dizenleriz,"},{"n":166,"t":"Biz, anıp yüceltenleriz."},{"n":167,"t":"Diyorlardı ki,"},{"n":168,"t":"\"Yanımızda öncekilerden bir uyarı bulunsaydı\""},{"n":169,"t":"\"Kendimizi ALLAH’a adar, sadece O’na kul olurduk.\""},{"n":170,"t":"Böylece onu inkâr ettiler; ileride bilecekler."},{"n":171,"t":"Elçilikle görevli kullarımız için söz verilmiştir."},{"n":172,"t":"Onlar elbette zafere ulaşacaklar."},{"n":173,"t":"Bizim ordumuz kesinlikle üstün gelecektir."},{"n":174,"t":"Öyleyse bir süre için onlara aldırış etme."},{"n":175,"t":"Onları seyret; onlar da görecekler."},{"n":176,"t":"Azabımıza mı meydan okuyorlar?"},{"n":177,"t":"Yurtlarına inince uyarılanların sabahı ne kötü olur!"},{"n":178,"t":"Bir süreye kadar onlara aldırış etme."},{"n":179,"t":"Onları gözle; onlar da görecekler."},{"n":180,"t":"Üstünlük ve onurun sahibi olan Efendin, onların nitelemelerinden çok yücedir."},{"n":181,"t":"Gönderilmiş elçilere selam olsun."},{"n":182,"t":"Evrenlerin Rabbi olan ALLAH’a övgüler olsun."}]},{"id":38,"name":"Sad Suresi","verses":[{"n":1,"t":"S; mesajı içeren bu Kuran’a andolsun."},{"n":2,"t":"Doğrusu, inkâr edenler kibir ve ayrılık içindedir."},{"n":3,"t":"Onlardan önce nice nesilleri yok ettik. Feryat ettiler, ancak artık kurtuluş zamanı değildi."},{"n":4,"t":"Onlara, kendilerinden bir uyarıcının gelmesini yadırgadılar. İnkarcılar, \"Bu pek yalancı bir büyücüdür\" dediler,"},{"n":5,"t":"\"Tanrıları tek tanrı mı yaptı? Bu, gerçekten çok tuhaf!\""},{"n":6,"t":"Onların liderleri öne fırladılar, \"Yürüyün, tanrılarınıza bağlı kalın. Sizden istenen sadece budur.\""},{"n":7,"t":"\"Son dinde böylesini işitmedik. Bu bir uydurmadır.\""},{"n":8,"t":"\"Mesaj, neden aramızdan ona indirildi?\" Aslında, onlar mesajımdan kuşku içindedirler. Hayır, onlar azabı henüz tatmadılar."},{"n":9,"t":"Yoksa Üstün olan ve Bahşeden Efendinin rahmet hazineleri onların yanında mıdır?"},{"n":10,"t":"Yoksa göklerin, yerin ve aralarındakilerin yönetimi onlara mı aittir? Bırak, kendi kendilerini yüceltsinler."},{"n":11,"t":"Aksine onlar parti parti yenilgiye uğramış bir ordudur."},{"n":12,"t":"Onlardan önce Nuh halkı, Ad ve saltanat sahibi Firavun da yalanlamıştı."},{"n":13,"t":"Semud, Lut halkı ve Orman halkı da… Onlar partilerdi."},{"n":14,"t":"Hepsi de elçileri yalanladılar ve cezamı hakettiler."},{"n":15,"t":"Bunlar, onması olmayan bir tek patlama bekliyorlar."},{"n":16,"t":"Ve \"Efendimiz, Hesap Gününden önce acele olarak payımızı ver\" diye meydan okudular."},{"n":17,"t":"Onların sözlerine karşı sabırlı ol, becerikli bir kulumuz olan Davud’u anımsa; o (Tanrı’ya) sürekli itaat ederdi."},{"n":18,"t":"Dağları onun emrine vermiştik; onunla birlikte akşamleyin ve tan doğumu (Tanrı’yı) yüceltirlerdi."},{"n":19,"t":"Kuşlar da toplanmıştı; hepsi onun buyruğunu izlerdi."},{"n":20,"t":"Yönetimini güçlendirdik; ona bilgelik ve çok iyi bir yargılama gücü verdik."},{"n":21,"t":"Davacıların haberi sana ulaştı mı? Hani mabedine tırmanmışlardı."},{"n":22,"t":"Davud’un yanına girdiklerinde onlardan irkilmişti. \"Korkma\" demişlerdi, \"Birbirinin hakkını çiğneyen iki davacı… Aramızda gerçeğe göre hüküm ver, haksızlık etme. Bize yolun ortasını göster.\""},{"n":23,"t":"\"Bu benim kardeşimdir. Onun doksan dokuz koyunu, benim ise bir tek koyunum var. Böyle iken, \"Onu da bana ver\" dedi ve tartışmada bana üstün geldi."},{"n":24,"t":"Dedi ki, \"Senin koyununu kendi koyunlarına katmayı istemekle sana haksızlık etmiştir. Doğrusu, ortakçıların çoğu birbirinin hakkına el uzatır. Gerçeği onaylayıp erdemli davrananlar bunun dışındadır, onlar ise sayıca ne kadar azdır!\" Davud, kendisini sınadığımızı sanarak bağışlanma diledi, eğildi ve tövbe etti."},{"n":25,"t":"Böylece onu bağışladık. Yanımızda onun yakınlığı ve güzel bir yeri vardır."},{"n":26,"t":"Ey Davud, biz seni yeryüzünde yönetici kıldık. Halkın arasında adaletle yargı ver, hevesine ve duygularına kapılma, sonra seni ALLAH’ın yolundan saptırır. ALLAH’ın yolundan sapanlara, Hesap Gününü unuttukları için çetin bir ceza vardır."},{"n":27,"t":"Göğü, yeri ve aralarındakileri boş yere yaratmadık. Bu inkâr edenlerin sanısıdır. Kendilerini ateşe soktukları için inkâr edenlere yazıklar olsun."},{"n":28,"t":"Gerçeği onaylayıp iyi davrananları, yeryüzünde bozgunculuk yapanlar gibi mi tutacağız? Erdemlilere, yoldan çıkanlar gibi mi davranacağız?"},{"n":29,"t":"Sana indirdiğimiz bu kitap kutludur; ayetlerini incelesinler ve akıl sahipleri öğüt alsınlar."},{"n":30,"t":"Davud’a, Süleyman’ı verdik. İyi bir kuldu, (Tanrı’ya) sürekli yönelen biriydi."},{"n":31,"t":"Bir akşam, ona güzel koşu atları sunulmuştu."},{"n":32,"t":"Dedi ki, \"Mal ve mülk sevgisi beni Efendimi anmaktan alıkoydu. Ta ki, o (güneş) bir örtünün ardından kayboldu.\""},{"n":33,"t":"\"Onları bana geri getirin\" dedi, (veda etmek için) bacaklarını ve boyunlarını okşadı."},{"n":34,"t":"Süleyman’ı böylece sınadık; onun hükümranlığına maddi zenginlik kattık; ancak o tümüyle (Tanrı’ya) yöneldi."},{"n":35,"t":"Dedi ki, \"Efendim beni bağışla. Bana, benden sonra kimsenin ulaşamayacağı bir yönetim ver. Sen Bahşedensin.\""},{"n":36,"t":"Bunun üzerine komutuyla hareket eden rüzgarı onun emrine verdik. Dilediği yere yağmur yağdırırdı."},{"n":37,"t":"Sapkınları da, yapı ustaları ve dalgıçlar olarak…"},{"n":38,"t":"Ve zincirlerle birbirine bağlı bekleyen yedekleri de…"},{"n":39,"t":"\"Bu bizim bağışımızdır. İster ver, ister tut, tükenmez.\""},{"n":40,"t":"Onun bizim yanımızda yakınlığı ve güzel yeri vardı."},{"n":41,"t":"Kulumuz Eyyub’u an: \"Efendim, sapkın bana bitkinlik ve acı dokundurdu\" diye Efendisine seslenmişti."},{"n":42,"t":"\"Ayağını yere vur. İşte yıkanacak ve içilecek soğuk bir kaynak.\""},{"n":43,"t":"Çoluk çocuğunu bir katıyla birlikte ona geri verdik. Bu, akıl sahiplerine bizden bir rahmet ve mesajdır."},{"n":44,"t":"\"Şimdi eline bir değnek alıp yola çık. Yeminini bozma.\" Onu sabırlı bulduk. Ne iyi bir kul! Sürekli yönelirdi."},{"n":45,"t":"Kullarımız İbrahim, İshak ve Yakub’u anımsa. Becerikli idiler, ileri görüşlü idiler."},{"n":46,"t":"Salt ahireti düşündükleri için onları salt/dupduru kıldık."},{"n":47,"t":"Onlar bizim yanımızda iyilerden seçilmiş kimselerdi."},{"n":48,"t":"İsmail’i, Elyesa’ı ve Zülkifl’i de anımsa; hepsi iyilerdendi."},{"n":49,"t":"Bu bir mesajdır: Erdemliler için güzel bir gelecek,"},{"n":50,"t":"Ve kapıları kendilerine açılmış Adn bahçeleri vardır."},{"n":51,"t":"Orada konfor içinde bol meyve ve içecek isterler."},{"n":52,"t":"Yanlarında gözlerinin içine bakan yaşıtları vardır."},{"n":53,"t":"Hesap Günü için size söz verilen budur."},{"n":54,"t":"Bizim bu rızkımız tükenmez."},{"n":55,"t":"Bu böyledir; azgınlar ise kötü bir yeri hakederler."},{"n":56,"t":"Cehennemde yanarlar; ne kötü bir duraktır."},{"n":57,"t":"İşte onu tatsınlar: Kaynar su ve irin."},{"n":58,"t":"Bunlara benzer daha başkaları da vardır."},{"n":59,"t":"\"Bunlar sizinle birlikte paldır küldür sürüklenen bir gruptur.\" (denilince, cehennemdeki liderler:) \"Onlar hoş gelmediler. Onlar ateşte yanacaklar.\""},{"n":60,"t":"Onlar da derler ki, \"Aslında siz hoş gelmediniz. Bizi bu duruma siz soktunuz; ne kötü bir son!\""},{"n":61,"t":"\"Efendimiz, kim bizi bu duruma soktuysa onun cezasını ateşte ikiye katlayarak arttır\" diye eklerler."},{"n":62,"t":"\"Nasıl oluyor da kötü olarak saydığımız insanları göremiyoruz?\""},{"n":63,"t":"\"Onları aşağılayıp durduk. Yoksa onları gözlerimizden mi kaçırdık?\""},{"n":64,"t":"Cehennem halkının birbiriyle çekişmesi bir gerçektir."},{"n":65,"t":"De ki: \"Ben sadece bir uyarıcıyım. Tek ve Egemen olan ALLAH’tan başka bir tanrı yoktur.\""},{"n":66,"t":"Göklerin, yerin ve aralarındakilerin Rabbi; Üstündür, Bağışlayandır."},{"n":67,"t":"De ki: \"Bu, büyük bir haberdir.\""},{"n":68,"t":"\"Siz ise ondan yüz çeviriyorsunuz.\""},{"n":69,"t":"\"Onlar tartışırlarken Yüce Toplum’da neler olup bittiği hakkında bir bilgim yoktu.\""},{"n":70,"t":"\"Apaçık bir uyarıcı olduğum için bana vahyediliyor.\""},{"n":71,"t":"Efendin meleklere demişti ki, \"Balçıktan bir insan yaratacağım.\""},{"n":72,"t":"\"Onu düzenlediğim ve ona ruhumdan üflediğim zaman ona secdeye kapanın.\""},{"n":73,"t":"Tüm melekler ona secdeye kapandı;"},{"n":74,"t":"Ancak İblis hariç. Büyüklük tasladı ve nankör oldu."},{"n":75,"t":"\"Ey İblis, ellerimle yarattığıma secde etmekten seni alıkoyan nedir? Büyüklük mü tasladın? Yoksa baş mı kaldırdın?\" dedi."},{"n":76,"t":"\"Ben ondan daha üstünüm\" dedi, \"Beni ateşten yarattın, onu ise balçıktan yarattın.\""},{"n":77,"t":"\"Çık oradan\" dedi, \"Sen kovuldun.\""},{"n":78,"t":"\"Yargı Gününe kadar lanetimi hakettin.\""},{"n":79,"t":"Dedi ki, \"Efendim, dirilecekleri güne dek beni ertele.\""},{"n":80,"t":"Dedi ki, \"Sana süre verilmiştir;\""},{"n":81,"t":"\"Bilinen vaktin gününe kadar.\""},{"n":82,"t":"Dedi ki, \"Büyüklüğüne andolsun, tümünü azdıracağım.\""},{"n":83,"t":"\"Ancak onlardan kendilerini sadece sana adayan kulların hariç.\""},{"n":84,"t":"Dedi ki, \"Bu gerçektir ve ben sadece gerçeği söylerim:\""},{"n":85,"t":"\"Cehennemi seninle ve onlardan seni izleyenlerle topluca dolduracağım.\""},{"n":86,"t":"De ki: \"Buna karşılık olarak sizden bir ücret istemiyorum. Ben bir sahtekâr değilim.\""},{"n":87,"t":"\"Bu, tüm dünyaya bir mesajdır.\""},{"n":88,"t":"\"Ve onun haberlerini bir süre sonra öğreneceksiniz.\""}]},{"id":39,"name":"Zümer Suresi","verses":[{"n":1,"t":"Kitabın indirilmesi, Üstün ve Bilge olan ALLAH’tandır."},{"n":2,"t":"Biz bu kitabı sana gerçekle indirdik, öyleyse ALLAH’a hizmet et; dinini sadece O’na has kılarak…"},{"n":3,"t":"Kesinlikle, din sadece ALLAH’a aittir. O’nun dışındakileri evliya (dostlar) olarak edinenler, \"Onlar bizi ALLAH’a daha fazla yaklaştırsın diye biz onlara hizmet ediyoruz\" (derler). Ayrılığa düştükleri bu konuda onların arasında ALLAH karar verecektir. ALLAH kuşkusuz, yalancıları ve nankörleri doğru yola iletmez."},{"n":4,"t":"ALLAH bir çocuk dileseydi, yarattıklarının arasından dilediğini seçerdi. O çok yücedir. O, Tek ve Egemen olan ALLAH’tır."},{"n":5,"t":"Gökleri ve yeri gerçek ile yarattı. Geceyi gündüzün üzerine yuvarlar ve gündüzü de gecenin üzerine yuvarlar. Güneşi ve ayı da emri altına sokmuş ve onların her biri belli bir süreye kadar akıp gitmektedir. Kesinlikle, O Üstündür, Bağışlayandır."},{"n":6,"t":"Sizi bir tek kişiden yarattı, sonra ondan da eşini var etti. Size dört tür çiftlik hayvanı bağışladı (koyun, keçi, deve, sığır). Sizi annelerinizin karınlarında, üç karanlık içinde yaratılıştan yaratılışa geçirerek yaratmaktadır. Efendiniz olan ALLAH işte budur. Egemenlik O’na aittir. O’ndan başka tanrı yoktur. Nasıl da çevriliyorsunuz?"},{"n":7,"t":"İnkar ederseniz, ALLAH’ın size ihtiyacı yoktur. Fakat O, kullarının inkârcı olmasından hoşlanmaz. Şükrederseniz sizden hoşnut olur. Kimse kimsenin günah yükünü çekmez. Sonra dönüşünüz Efendinizedir ve yapmış olduklarınızı size haber verecektir. O, göğüslerin özünü bilir."},{"n":8,"t":"İnsana bir kötülük dokundu mu Efendisine yönelerek O’nu çağırır. Ona kendisinden bir iyilik verdi mi, daha önce kime yalvarmış olduğunu unutur ve O’nun yolundan saptırmak için ALLAH’a eşler koşmaya başlar. De ki: \"İnkarınla biraz yaşa, sen ateş halkındansın.\""},{"n":9,"t":"Geceleyin secde ederek ve ayakta durarak düşünceye dalan, ahiretin bilincinde olan ve Efendinin rahmetini uman birine ne dersiniz? De ki: \"Bilenlerle bilmeyenler bir olur mu?\" Ancak akıl sahipleri öğüt alır."},{"n":10,"t":"De ki: \"Ey gerçeği onaylayan kullar, Efendinizi sayın. Bu dünya hayatında güzel davrananlara güzellik vardır. ALLAH’ın yeri geniştir. Gerçek uğrunda direnenlerin ücreti hesapsız olarak verilecektir.\""},{"n":11,"t":"De ki: \"Dini yalnız ALLAH’a has kılarak O’na hizmet etmekle emredildim.\""},{"n":12,"t":"\"Ve en ileri derecede Müslüman olmam emredildi.\""},{"n":13,"t":"De ki: \"Efendime karşı gelirsem Büyük Günün azabından korkarım.\""},{"n":14,"t":"De ki: \"Dinimi yalnız ALLAH’a has kılarak O’na hizmet ediyorum.\""},{"n":15,"t":"\"Siz de O’nun dışında dilediğinize hizmet ediniz.\" De ki: \"Asıl kaybedenler, ahiret gününde kendilerine ve ailelerine kaybettirenlerdir.\" Apaçık kayıp budur."},{"n":16,"t":"Onların üstünde de altlarında da kat kat ateş vardır. ALLAH kullarını böylece uyarır. Kullarım, beni sayın."},{"n":17,"t":"Kim Tağut’a (azgına/küstaha) hizmet etmekten kaçınır ve ALLAH’a yönelirse onlar için müjde vardır. Kullarımı müjdele."},{"n":18,"t":"Onlar ki sözü (kavl) dinlerler ve en güzeline uyarlar. Onlar, ALLAH’ın yol gösterdiği kimselerdir. Onlar akıl sahipleridir."},{"n":19,"t":"Azap sözünü hakedenlere gelince, sen ateştekini kurtarabilir misin?"},{"n":20,"t":"Ancak Rab’lerini sayanlar için üstüste kurulmuş köşkler vardır; altlarından ırmaklar akar. ALLAH’ın sözüdür. Kuşkusuz ALLAH sözünden caymaz."},{"n":21,"t":"Görmez misin ki ALLAH gökten bir su indirir ve onu yeryüzündeki kaynaklara geçirir ve sonra onunla çeşitli renklerde bitkiler çıkarır. Sonra o kurur ve onu sararmış görürsün. Sonra da onu çerçöpe çevirir. Bunda akıl sahipleri için öğüt vardır."},{"n":22,"t":"ALLAH kimin göğsünü İslam’a açarsa o Efendisinden bir ışık üzerindedir. ALLAH’ın mesajına karşı kalpleri katılaşanların vay haline. Onlar açık bir sapıklıktadır."},{"n":23,"t":"ALLAH en güzel hadisi, tutarlı ve ikişerli bir kitap halinde indirdi. Ondan dolayı Rab’lerini sayanların tüyleri ürperir. Sonra derileri ve kalpleri ALLAH’ın mesajına karşı yumuşar. Bu, ALLAH’ın yol göstermesidir; dilediğini/dileyeni ona ulaştırır. ALLAH’ın saptırdığı bir kimseye rehber bulunmaz."},{"n":24,"t":"Diriliş Gününün azabından yüzünü koruyan kimse gibisi var mıdır? Zalimlere, \"Kazandığınızın sonucunu tadın!\" denir."},{"n":25,"t":"Onlardan öncekiler de yalanladılar ve ceza, onların beklemedikleri bir yerden gelmişti."},{"n":26,"t":"ALLAH onlara dünya hayatında rezilliği tattırdı. Ahiret cezası ise daha büyüktür. Bir bilselerdi."},{"n":27,"t":"Biz bu Kuran’da, insanlara, her türlü örneği verdik ki öğüt alsınlar."},{"n":28,"t":"Arapça, pürüzsüz bir Kuran, belki erdemli olurlar."},{"n":29,"t":"ALLAH, çelişen ortaklara sahip bir adam ile bir tek kişiye bağlı olan adamın örneğini verir. Bu ikisinin durumu hiç eşit olur mu? Övgü ALLAH’adır. Ancak çokları bilmez."},{"n":30,"t":"Sen öleceksin, onlar da ölecekler."},{"n":31,"t":"Sonra Diriliş Günü, Efendinizin huzurunda duruşmaya çıkacaksınız."},{"n":32,"t":"ALLAH’a karşı yalan uydurandan ve kendisine gerçek geldiğinde onu yalanlayandan daha zalim kim olabilir? Kafirler için cehennemde bir yer yok mu?"},{"n":33,"t":"Gerçeği getiren ve onu doğrulayana gelince, işte onlar erdemlilerdir."},{"n":34,"t":"Onlar için Rab’leri katında diledikleri her şey vardır. İyi davrananların ödülü böyledir."},{"n":35,"t":"Böylece ALLAH onların en kötü işlerini bağışlar ve yapmış olduklarının karşılığını da en güzel bir biçimde verir."},{"n":36,"t":"ALLAH kuluna yetmez mi? Seni O’ndan başkalarıyla korkutuyorlar. ALLAH kimi saptırırsa ona bir yol gösteren bulunmaz."},{"n":37,"t":"ALLAH’ın yol gösterdiğini de hiç kimse saptıramaz. ALLAH Üstün ve Öc Alan değil midir?"},{"n":38,"t":"Onlara, \"Gökleri ve yeri kim yarattı?\" diye sorsan, \"ALLAH\" diyecekler. De ki: \"ALLAH’ın dışında hizmet ettiklerinize ne dersiniz? ALLAH benim için bir zarar dilese onlar O’nun zararını giderebilir mi? Yahut O benim için bir rahmet dilese onlar O’nun rahmetini tutabilir mi? De ki: \"ALLAH bana yeter.\" Güvenenler O’na güvensinler."},{"n":39,"t":"De ki: \"Ey halkım, bildiğinizi yapın, ben de yapacağım. İleride bileceksiniz:\""},{"n":40,"t":"\"Alçaltıcı azap kime geliyormuş ve sürekli azabı kim hak ediyormuş!\""},{"n":41,"t":"Biz bu kitabı sana halk için gerçekle indirdik. Kim doğruyu bulursa kendisi içindir. Kim saparsa da kendisi aleyhine sapmış olur. Sen onların avukatı değilsin."},{"n":42,"t":"ALLAH ölümü anında nefsi (bilinci) alır; ölmeyenleri de uyku anında… Hakkında ölüm kararı verdiklerini tutar ve diğerlerini de belli bir süreye kadar salıp gönderir. Düşünen bir topluluk için bunda dersler ve işaretler vardır."},{"n":43,"t":"ALLAH’ın dışında şefaatçiler mi edindiler? De ki: \"Onlar hiçbir şeye sahip değilseler ve düşünemiyorlarsa da mı?\""},{"n":44,"t":"De ki: \"Tüm şefaat ALLAH’a aittir.\" Göklerin ve yerin yönetimi O’na aittir. Sonra O’na döndürüleceksiniz."},{"n":45,"t":"ALLAH tek başına anıldığı an ahiret gerçeğini onaylamayanların kalpleri huzursuz olarak ürker. Fakat O’nun dışındakiler anıldığı zaman hemen yüzleri güler."},{"n":46,"t":"De ki: \"Gökleri ve yeri yoktan var eden, gizliyi ve açığı Bilen Tanrım, ayrılığa düştükleri konularda kulların arasında hükmü yalnız sen verirsin.\""},{"n":47,"t":"Zalimler, yerdekilerin tümüne ve hatta onun bir katına daha sahip olsaydı bile, Diriliş Gününün o müthiş azabından kurtulmak için onu fidye olarak vereceklerdi. Kendilerine, ALLAH tarafından hiç beklemedikleri bir şey gösterilecektir."},{"n":48,"t":"İşledikleri kötülükler onlara gösterilir ve alay etmekte oldukları şeyler ise onları çepeçevre sarar."},{"n":49,"t":"İnsana bir kötülük dokunduğu zaman bizi çağırır; ancak ona bir nimet verdiğimiz zaman ise: \"Bu, bana bilgimden dolayı verilmiştir\" der. Aslında o bir testtir, ne var ki çokları bilmez."},{"n":50,"t":"Kendilerinden öncekiler aynı şeyi söylediler, ancak kazandıkları şeylerin kendilerine hiçbir yararı dokunmadı."},{"n":51,"t":"Kazandıkları kötülükler, sonunda başlarına geldi. Aynı biçimde şu zulmedenlere de kazandıkları kötülükler çatacaktır; engelleyemezler."},{"n":52,"t":"ALLAH’ın dilediğine rızkı genişletip daralttığını bilmezler mi? Gerçeği onaylayan bir toplum için bunda dersler vardır."},{"n":53,"t":"Onlara bildir: \"Kendilerine karşı sınırı aşan kullarım, ALLAH’ın rahmetinden ümit kesmeyin. ALLAH tüm günahları affedicidir. O Bağışlayandır, Rahimdir.\""},{"n":54,"t":"Efendinize yönelin ve cezaya çarpılmadan önce O’na teslim olun, zira o zaman yardım görmezsiniz."},{"n":55,"t":"O azap beklemediğiniz anda sizi ansızın yakalamadan önce, Efendiniz tarafından size indirilen en güzel öğretiye uyun."},{"n":56,"t":"Ki kişi, \"ALLAH’ın öğretisine aldırmamaktan ötürü vay halime; doğrusu ben aşağılayanlardan idim\" demesin."},{"n":57,"t":"Veya \"ALLAH beni doğruya iletseydi kesinlikle erdemlilerden biri olacaktım\" demesin."},{"n":58,"t":"Yahut azabı gördüğü an, \"Keşke ikinci bir şansım daha olsaydı da güzel davrananlardan olsaydım\" demesin."},{"n":59,"t":"Evet, sana ayet ve mucizelerim geldi, fakat sen onları yalanladın, kibirlendin ve inkârcılardan oldun."},{"n":60,"t":"Diriliş günü, ALLAH hakkında yalan uyduranların suratlarını asık görürsün. Cehennem, azgınlara tam uygun bir yer değil midir?"},{"n":61,"t":"ALLAH erdemlileri başarılarıyla kurtarır. Onlara kötülük dokunmaz ve onlar üzülmezler de."},{"n":62,"t":"ALLAH her şeyin Yaratıcısıdır. O, her şeyi kontrol eder."},{"n":63,"t":"Göklerin ve yerin kararları O’na aittir. ALLAH’ın ayetlerini yalanlayanlar asıl kaybedenlerdir."},{"n":64,"t":"De ki: \"ALLAH’tan başkasına mı hizmet etmeye beni teşvik ediyorsunuz ey cahiller?\""},{"n":65,"t":"Sana ve senden öncekilere şöyle vahyedilmiştir: Ortak koşarsan, tüm yaptıkların boşa gider ve kaybedenlerden olursun."},{"n":66,"t":"Öyleyse yalnız ALLAH’a kul ol ve şükret."},{"n":67,"t":"ALLAH’ı gereği gibi değerlendiremediler. Halbuki, diriliş günü, tüm yer O’nun avucu içindedir, gökler de O’nun sağ elinde dürülmüştür. O Yücedir ve onların ortak koştuklarından çok üstündür."},{"n":68,"t":"Boruya üflenir üflenmez göklerde ve yerde kim varsa, ALLAH’ın diledikleri hariç kendinden geçip bayılırlar. Sonra ona tekrar üflenir de onlar ayağa kalkıp bakışırlar."},{"n":69,"t":"Yer, Efendinin ışığıyla parlar. Kitap konur. Peygamberler ve tanıklar getirilir. Aralarında gerçeğe göre hüküm verilir ve onlara zulmedilmez."},{"n":70,"t":"Her kişiye yaptığının karşılığı tam olarak verilir. O, onların yapmış olduğu her şeyi en iyi bilendir."},{"n":71,"t":"İnkar edenler yığınlar halinde cehenneme götürülürler. Oraya vardıklarında onun kapıları açılır ve bekçileri onlara, \"Size, Efendinizin ayetlerini okuyan ve bugününüzle karşılaşacağınız konusunda sizi uyaran sizden elçiler gelmemiş miydi?\" derler. \"Evet. Ancak ‘ceza’ sözü inkârcılar hakkında gerçekleşmiştir\" diye karşılık verirler."},{"n":72,"t":"\"Temelli kalacağınız cehennemin kapılarından girin. Büyüklük taslayanların sonu ne de kötüymüş!\" denir."},{"n":73,"t":"Rab’lerini sayıp dinleyenler ise yığınlar halinde bahçeye götürülürler. Oraya vardıklarında onun kapıları açılır ve bekçileri onlara, \"Size barış olsun; kazandınız. Haydi temelli kalmak üzere oraya giriniz\" derler."},{"n":74,"t":"\"Bize verdiği sözü gerçekleştiren, yeri bize miras bırakan ve bahçede dilediğimiz yerde oturmamızı sağlayan ALLAH’a övgüler olsun\" derler. Çalışanların ücreti ne de güzelmiş!"},{"n":75,"t":"Denetçileri, yönetim merkezinin etrafını çevirmiş halde Rab’lerini överek yüceltirken görürsün. Aralarında gerçeğe göre hüküm verilmiştir ve \"Evrenin Rabbi ALLAH’a övgüler olsun\" denir."}]},{"id":40,"name":"Mü'min Suresi","verses":[{"n":1,"t":"H. M."},{"n":2,"t":"Bu kitabın indirilmesi, Üstün ve Her şeyi Bilen ALLAH katındandır."},{"n":3,"t":"Günahları Bağışlayan, Tövbeyi Kabul Eden, Cezası Şiddetli, Sonsuz Güç Sahibi… O’ndan başka tanrı yoktur. Dönüş O’nadır."},{"n":4,"t":"İnkarcılardan başkası ALLAH’ın ayetleri ve mucizelerine karşı tartışmaz. Onların görünür başarıları seni aldatmasın."},{"n":5,"t":"Onlardan önce Nuh’un halkı da yalanlamıştı ve onlardan sonra birçok parti de… Her topluluk elçilerini etkisiz hale getirmeye çalıştı. Gerçeği gidermek için boş ve yanlış şeylerle tartıştılar. Sonunda onları yakaladım; cezalandırmam nasılmış?"},{"n":6,"t":"Efendinin, \"Onlar cehennemin halkıdır\" diye inkârcılar hakkında verdiği sözü böylece gerçekleşir."},{"n":7,"t":"Yönetim merkezine hizmet edenler ve etrafındakiler Rab’lerini överek yüceltirler ve O’nu onaylarlar. Gerçeği onaylayanlar için bağışlanma dilerler: \"Efendimiz, rahmetin ve bilgin her şeyi içine almıştır. Tövbe edenler ve senin yoluna uyanları bağışla ve onları ateşin azabından koru.\""},{"n":8,"t":"\"Efendimiz onları, erdemli atalarını, eşlerini ve çocuklarını söz verdiğin Adn bahçelerine sok. Kuşkusuz sen Üstünsün, Bilgesin.\""},{"n":9,"t":"\"Onları kötülüklerden koru. O gün kimi kötülüklerden korursan onlara rahmet etmişsindir. Büyük zafer budur.\""},{"n":10,"t":"İnkar etmiş olanlara, \"ALLAH’ın hoşnutsuzluğu, sizin kendi kendinize olan hoşnutsuzluğunuzdan daha büyüktür. Gerçeği onaylamaya çağrıldığınızda inkâr ederdiniz\" diye seslenilir."},{"n":11,"t":"Diyecekler ki, \"Efendimiz, bizi iki kez öldürdün ve iki kez dirilttin. Şimdi günahlarımızı itiraf ettik. Buradan bir çıkış yolu var mı?\""},{"n":12,"t":"Çünkü, YALNIZ ALLAH çağrıldığı zaman inkâr ederdiniz. Ancak kendisine ortak koşulduğunda onaylardınız. Hüküm, Üstün ve Büyük olan ALLAH’a aittir."},{"n":13,"t":"O ki size ayetlerini (kanıtlarını ve işaretlerini) göstermekte ve sizin için gökten bir rızık indirmektedir. Tümüyle yönelip teslim olandan başkası ibret almaz."},{"n":14,"t":"İnkarcılar hoşlanmasa da dini sadece ALLAH’a ait kılarak O’na hizmet edin."},{"n":15,"t":"Dereceleri Yükselten, Yönetim Sahibi. Buluşma gününe karşı uyarsın diye kullarından dilediğine, emirlerini içeren vahyini indirir."},{"n":16,"t":"O gün onlar tümüyle açığa çıkarılacaklardır. Hiçbir şey onları ALLAH’tan gizleyemez. O gün yönetim kime aittir? Tek ve En Üstün olan ALLAH’a aittir."},{"n":17,"t":"O gün her kişiye yaptığının karşılığı ödenir. O gün haksızlık yoktur. ALLAH hesabı çabuk görendir."},{"n":18,"t":"Onları yaklaşan gün hakkında uyar, o zaman yürekler gırtlaklara dayanmıştır, yutkunurlar. Zalimler için ne bir dost ne de sözü dinlenir bir şefaatçi vardır."},{"n":19,"t":"Gözlerin saklamaya çalıştığını ve göğüslerin gizlediğini bilir."},{"n":20,"t":"ALLAH adaletle yargı verir. O’ndan başka çağırdıkları ise hiçbir şeye yargı veremezler. ALLAH İşitendir, Görendir."},{"n":21,"t":"Kendilerinden öncekilerin sonucunun nasıl olduğuna bakmak için yeryüzünde dolaşmıyorlar mı? Onlardan daha fazla güce sahiptiler, yeryüzünde daha çok üreticiydiler. Ancak ALLAH onları günahlarıyla yakaladı. ALLAH’a karşı onları koruyabilecek yoktur."},{"n":22,"t":"Çünkü, elçiler onlara apaçık delillerle gittiklerinde inkâr ediyorlardı. Sonunda ALLAH onları yakaladı. O Güçlüdür, Cezalandırması Şiddetlidir."},{"n":23,"t":"Musa’yı ayetlerimiz ve apaçık bir yetki ile gönderdik."},{"n":24,"t":"Firavuna, Haman’a ve Karun’a… \"Bu sihirbazın ve yalancının biridir\" dediler."},{"n":25,"t":"Onlara bizden bir gerçeği götürünce, \"Onunla birlikte gerçeği onaylayanların oğullarını öldürün, kadınlarını ise utandırın\" dediler. İnkarcıların planı hep sapıkçadır."},{"n":26,"t":"Firavun dedi, \"Beni bırakın Musa’yı öldüreyim de o da Efendisine yalvarsın. Sizin dininizi değiştireceğinden veya yeryüzünde kötülük çıkaracağından endişeleniyorum.\""},{"n":27,"t":"Musa dedi, \"Ben, hesap gününü onaylamayan her azgından Efendime ve sizin Efendinize sığındım\" dedi."},{"n":28,"t":"Gerçeği onayladığı halde Firavunun tarafından onaylamasını gizleyen bir adam dedi ki, \"Siz ‘benim Efendim ALLAH’tır’ diyen bir adamı mı öldüreceksiniz? Halbuki size Efendinizden apaçık deliller getirmiş bulunuyor. Yalancı ise, bu onun problemidir; yok doğru sözlü ise onun size anlattıkları gerçekleşir. Kuşkusuz ALLAH sınırı aşan yalancıları sevmez.\""},{"n":29,"t":"\"Ey halkım, yönetim bugün sizindir ve ülkede siz egemensiniz. Ancak ALLAH’ın hışmı bize gelirse kim ona karşı bize yardım edebilir?\" Firavun da, \"Size kendi görüşümü öğütlüyorum; size doğru yolu gösteriyorum\" dedi."},{"n":30,"t":"Gerçeği onaylayan adam dedi ki, \"Ey halkım daha önceki partilerin günü gibi bir sonuca uğramanızdan korkuyorum.\""},{"n":31,"t":"\"Nuh, Ad, Semud ve onlardan sonrakilerin durumu gibi. Elbette ALLAH kullara haksızlık etmek dilemez.\""},{"n":32,"t":"\"Halkım, sizin için Toplanma Gününden korkuyorum.\""},{"n":33,"t":"\"O gün arkanızı dönüp kaçacaksınız; ancak sizi ALLAH’tan koruyacak yoktur. ALLAH’ın saptırdığına yol gösteren bulunmaz.\""},{"n":34,"t":"Daha önce Yusuf da size apaçık delillerle gelmişti; fakat size getirdiği mesajı sürekli olarak kuşku ile karşılamıştınız. Nihayet o ölünce, \"ALLAH ondan sonra elçi göndermeyecektir (O son elçidir)\" demiştiniz. ALLAH, kuşkuda sınırı aşanı böylece saptırır.\""},{"n":35,"t":"ALLAH’ın ayet ve mucizelerine karşı, hiçbir delile sahip olmadan tartışanlar, hem ALLAH katında ve hem de gerçeği onaylayanlar katında büyük bir öfkeye muhataptır. ALLAH her kibirli zorbanın kalbini işte böyle mühürler."},{"n":36,"t":"Firavun dedi ki, \"Haman, benim için bir kule dik de yollara erişeyim.\""},{"n":37,"t":"\"Göklerin yollarına… Böylece Musa’nın tanrısına bir bakayım. Onun bir yalancı olduğunu onaylıyorum.\" Firavunun kötü tavrı kendisine böyle süslenmişti ve böylece yoldan çıkarıldı. Firavunun planı elbette boşa çıkacaktı."},{"n":38,"t":"Gerçeği onaylayan adam dedi ki, \"Ey halkım, beni izleyin ki size doğru yolu göstereyim.\""},{"n":39,"t":"\"Ey halkım, bu dünya hayatı geçici bir geçinmedir. Ahiret yurdu ise ebedi bir duraktır.\""},{"n":40,"t":"Kim kötülük işlerse kendisine ancak onun kadar bir ceza verilir. Erkek veya kadın kim gerçeği onaylamış olarak erdemli işler yaparsa onlar bahçeye girerler ve orada hesapsız olarak nimetlenirler."},{"n":41,"t":"\"Ey halkım, neden ben sizi kurtuluşa çağırırken siz beni ateşe çağırıyorsunuz?\""},{"n":42,"t":"\"Siz beni ALLAH’a karşı nankör olmaya ve hakkında bilgim olmayan şeyleri ona ortak koşmaya çağırıyorsunuz. Bense sizi O Üstün ve Bağışlayıcı olana çağırıyorum.\""},{"n":43,"t":"\"Kuşku yok ki, beni kendisine çağırdığınız şeyin ne dünyada ne de ahirette bir dayanağı yoktur. Dönüşümüz ALLAH’adır. Sınırı aşanlar, cehennemi boylayacaktır.\""},{"n":44,"t":"\"Size bu söylediklerimi ileride hatırlayacaksınız. Ben işimi ALLAH’a bırakıyorum. ALLAH kullarını Görendir.\""},{"n":45,"t":"ALLAH onu, onların planladıkları kötülüklerden korudu. Firavunun taraftarlarını azabın en kötüsü kuşattı."},{"n":46,"t":"Onlara gündüz ve akşam ateş sunulacaklar. Dünyanın son gününde: \"Firavunun taraftarlarını azabın en çetinine sokun.\""},{"n":47,"t":"Ateşte tartışırlarken, güçsüzler, büyüklük taslamış olanlara, \"Biz sizin izleyicileriniz idik, öyleyse bu ateşin bir parçasını olsun bizden savabilir misiniz?\" derler."},{"n":48,"t":"Büyüklük taslamış olanlar, \"Hepimiz onun içindeyiz. ALLAH kulları arasında artık hüküm vermiştir\" derler."},{"n":49,"t":"Ateştekiler, cehennemin gardiyanlarına, \"Efendinize yalvarın da bizden azabı hiç değilse bir gün hafifletsin\" derler."},{"n":50,"t":"Onlar da derler ki, \"Elçileriniz size apaçık delillerle gelmemiş miydi?\" \"Evet\" derler. Bunun üzerine onlar, \"Öyleyse kendiniz yalvarın. Ne var ki inkârcıların yalvarması sonuç vermez.\""},{"n":51,"t":"Biz elçilerimize ve gerçeği onaylayanlara bu dünya hayatında ve tanıkların duruşmalarda bulunacakları günde yardım ederiz."},{"n":52,"t":"O gün zalimlere özürleri bir yarar sağlamaz. Onlar laneti ve en kötü sonu hakederler."},{"n":53,"t":"Biz Musa’ya hidayeti verdik ve İsrailoğullarını kitaba varis kıldık."},{"n":54,"t":"Anlayış sahiplerine bir yol gösterici ve bir uyarı olarak."},{"n":55,"t":"Öyleyse sabret. Çünkü ALLAH’ın sözü gerçektir. Günahların için de bağışlanma iste ve Efendini akşam sabah överek yücelt."},{"n":56,"t":"Hiçbir delile sahip olmadan ALLAH’ın ayet ve mucizelerine karşı tartışanların göğüslerinde, erişemeyecekleri bir büyüklenme vardır. Öyleyse ALLAH’a sığın. O İşitendir, Görendir."},{"n":57,"t":"Göklerin ve yerin yaratılışı, insanın yaratılışından daha büyük bir şeydir. Ne var ki halkın çoğu bilmez."},{"n":58,"t":"Kör ile gören bir olmaz. Gerçeği onaylayıp erdemli davrananlarla kötülük işleyenler de bir olmaz. Ne kadar az düşünürsünüz."},{"n":59,"t":"O an elbette gelecektir, bunda kuşku olmasın. Ne var ki insanların çoğu gerçeği onaylamaz."},{"n":60,"t":"Efendiniz der ki, \"Bana yalvarın size cevap vereyim.\" Büyüklük taslayarak bana hizmet etmekten kaçınanlar aşağılanarak cehenneme gireceklerdir."},{"n":61,"t":"ALLAH, geceyi dinlenmeniz için yaratan ve gündüzü de aydınlık yapandır. ALLAH halka karşı büyük lütuf sahibidir, fakat halkın çoğu şükretmez."},{"n":62,"t":"İşte Efendiniz ALLAH, her şeyin Yaratıcısıdır; O’ndan başka tanrı yoktur. Nasıl da çevriliyorsunuz?"},{"n":63,"t":"ALLAH’ın ayet ve mucizelerini reddedenler işte böyle saptırılırlar."},{"n":64,"t":"ALLAH yeryüzünü sizin için bir yerleşim ve göğü de bir yapı kılandır. Sizi biçimlendirip biçiminizi güzel yapan ve sizi besinli gıdalarla besleyendir. Efendiniz olan ALLAH budur. Evrenin Rabbi olan ALLAH ne yücedir!"},{"n":65,"t":"O, Diridir; O’ndan başka tanrı yoktur. Dini sadece O’na ait kılarak O’nu çağırın. Evrenin Rabbi ALLAH’a övgüler olsun."},{"n":66,"t":"De ki: \"Bana açık deliller geldikten sonra, ALLAH’ın yanında yalvardıklarınıza hizmet etmekten menedildim ve evrenin Efendisine teslim olmakla emrolundum.\""},{"n":67,"t":"O ki sizi topraktan, sonra bir damladan, sonra asılı duran bir embriyodan yaratmıştır. Olgunlaşmanız ve ihtiyarlamanız için daha sonra sizi çocuk olarak dışarı çıkarır. Sizden bazılarının canı daha erken alınır. Daha önce belirlenmiş yaşa ulaşırsınız ki kavrayasınız."},{"n":68,"t":"Dirilten ve öldüren O’dur. Herhangi bir işi diledi mi, ona \"Ol\" der, o da oluverir."},{"n":69,"t":"ALLAH’ın ayet ve mucizelerine karşı mücadele edenlerin nasıl da çevrildiklerini görmez misin?"},{"n":70,"t":"Onlar, kitabı ve elçilerimiz yoluyla gönderdiğimiz mesajı yalanladılar. İleride bilecekler."},{"n":71,"t":"Boyunlarında prangalar ve zincirlerle sürüklenecekler."},{"n":72,"t":"Kaynar suda, sonra ateşte yakılacaklardır."},{"n":73,"t":"Sonra onlara şöyle denir, \"Nerde ortak koştuklarınız...\""},{"n":74,"t":"\"ALLAH’ın yanında?\" Onlar da derler ki, \"Bizi terkettiler. Meğer biz daha önce hiçbir şeye yalvarmıyormuşuz.\" ALLAH inkârcıları işte böyle saptırır."},{"n":75,"t":"Çünkü siz yeryüzünde gerçeğe dayanmadan seviniyor ve şımarıyordunuz."},{"n":76,"t":"Sürekli kalmak üzere cehennemin kapılarından giriniz. Büyüklük taslayanların yeri ne de kötüdür."},{"n":77,"t":"Öyleyse sabret; ALLAH’ın sözü gerçektir. Onlara söz verdiğimiz (cezalandırmanın) bir kısmını sana göstersek de, ondan önce hayatına son versek de, onlar bize döndürüleceklerdir."},{"n":78,"t":"Senden önce göndermiş bulunduğumuz elçilerin bir kısmından sana söz ettik, bir kısmını da sana anlatmadık. Hiçbir elçi, ALLAH’ın izni olmadan bir mucize getiremez. ALLAH’ın emri gelince gerçeğe göre yargı verilir ve yanlışı savunanlar orada hüsrana uğrarlar."},{"n":79,"t":"Binesiniz ve onlardan yiyesiniz diye çiftlik hayvanlarını sizin için yaratan ALLAH’tır."},{"n":80,"t":"Sizin için onlarda çeşitli yararlar vardır. Gönlünüz dilediği gibi onlardan yararlanırsınız. Onlarla ve gemilerle taşınırsınız."},{"n":81,"t":"Size işaretlerini gösterir. ALLAH’ın hangi işaretini inkâr ediyorsunuz?"},{"n":82,"t":"Kendilerinden öncekilerin sonunun nasıl olduğuna bakmak için yeryüzünü dolaşmazlar mı? Onlardan sayıca daha çok, daha güçlü olup yeryüzünde daha çok üretimde bulunmuşlardı. Ancak, kazandıkları şeyler kendilerini kurtaramadı."},{"n":83,"t":"Elçileri apaçık kanıtlarla kendilerine vardıklarında, yanlarındaki bilgiyle gururlandılar. Alaya aldıkları şey kendilerini sarıverdi."},{"n":84,"t":"Nihayet cezamızı gördüklerinde, \"Artık SADECE ALLAH’ı onayladık ve ortak koşmuş olduklarımızı inkâr ettik\" derler."},{"n":85,"t":"Azabımızı gördüklerinde gerçeği onaylamaları kendilerine bir yarar sağlamaz. Bu, daha önceki kulları hakkında sürekli uygulanan ALLAH’ın sünneti (yasası) dır. İşte o zaman inkârcılar hüsrana uğramışlardır."}]},{"id":41,"name":"Fussilet Suresi","verses":[{"n":1,"t":"H. M."},{"n":2,"t":"Rahman ve Rahim olandan indirilmiştir."},{"n":3,"t":"Bilen bir topluluk için, Arapça bir Kuran olarak ayetleri açıklanmış bir kitaptır."},{"n":4,"t":"Bir müjdeci ve bir uyarıcıdır. Ancak onların çoğunluğu ondan yüz çevirmiştir; onlar işitmezler."},{"n":5,"t":"Dediler ki: \"Senin bizi çağırdığın şeye karşı sabit fikirliyiz, kulaklarımızda ağırlık ve bizimle sizin aranızda bir perde vardır. İstediğini yap, biz de yapacağız.\""},{"n":6,"t":"De ki: \"Ben, sadece sizin gibi bir insanım. Bana, sizin tanrınızın bir tek tanrı olduğu vahyediliyor. O’na yönelin, O’ndan bağışlanma dileyin. Vay ortak koşanlara!\""},{"n":7,"t":"\"Ki zekatı vermezler ve onlar ahireti de inkâr ederler.\""},{"n":8,"t":"Gerçeği onaylayıp erdemli davrananlar için sürekli bir ödül vardır."},{"n":9,"t":"De ki: \"Siz yeri iki günde yaratanı mı inkâr ediyorsunuz ve O’na eşler mi koşuyorsunuz? O, evrenlerin Rabbidir.\""},{"n":10,"t":"Onun üstüne denge unsurları (olan dağlar) yerleştirdi ve onu bereketli kıldı. Tüm arayıp isteyenler için onun gıdalarını dört günde ölçüp düzenledi."},{"n":11,"t":"Sonra duman halindeki göğe yönelerek ona ve yere, \"İsteyerek veya istemeyerek (kaostan çıkıp) gelin\" dedi. Onlar da, \"İsteyerek geldik\" dediler."},{"n":12,"t":"Böylece onları iki günde yedi gök olarak tamamladı ve her göğe özel yasaları bildirdi. Ve biz en aşağıdaki göğü ise lambalarla ve koruma sistemiyle donattık. Bu, Üstün ve her şeyi Bilen’in planıdır."},{"n":13,"t":"Yüz çevirirlerse De ki: \"Sizi Ad ve Semud yıldırımına benzer bir yıldırımla uyardım.\""},{"n":14,"t":"Onlara, \"ALLAH’tan başkasına hizmet etmeyin\" diye önlerinden ve arkalarından elçiler gitmişti. Onlar ise, \"Efendimiz dileseydi bir melek indirebilirdi. Bundan ötürü getirdiğiniz mesajı onaylamıyoruz\" dediler."},{"n":15,"t":"Ad’a gelince, onlar yeryüzünde haksız yere büyüklük tasladılar ve \"Bizden daha güçlü kim var?\" dediler. Kendilerini yaratan ALLAH’ın onlardan daha güçlü olduğunu anlamadılar mı? Onlar ayet ve mucizelerimizi bilerek inkâr ediyorlardı."},{"n":16,"t":"Nihayet, onlara dünya hayatında aşağılayıcı azabı tattırmak için uğursuz günlerde üzerlerine sert bir rüzgar gönderdik. Ahiret azabı ise daha aşağılayıcıdır ve onlar yardım görmezler."},{"n":17,"t":"Semud’a gelince, onlara yolu gösterdik. Ne var ki onlar körlüğü hidayete tercih ettiler. Sonunda, kazandıklarına karşılık, onları alçaltıcı azabın yıldırımı yakaladı."},{"n":18,"t":"Gerçeği onaylayanları ve erdemli davrananları ise kurtardık."},{"n":19,"t":"ALLAH düşmanlarının ateşe sürüklenerek toplatılacakları gün…"},{"n":20,"t":"Nihayet oraya vardıklarında, onların işitme, görme organları ve derileri yaptıkları hakkında tanıklık eder."},{"n":21,"t":"Derilerine, \"Niçin bize karşı tanıklık ettiniz?\" diye sorarlar. Onlar da, \"Her şeyi konuşturan ALLAH bizi konuşturdu. Sizi ilk yaratan O’dur ve işte O’na döndürülüyorsunuz\" derler."},{"n":22,"t":"Ne işitme ve görme organlarınızın, ne de derilerinizin aleyhinizdeki tanıklığını gizlemeye gücünüz yetmez. Buna rağmen siz yaptıklarınızın çoğunu ALLAH’ın bilemeyeceğini sanıyordunuz."},{"n":23,"t":"Efendiniz hakkında bu düşünceniz sizi kaydırdı ve kaybedenlerden oldunuz."},{"n":24,"t":"Dayanırlarsa yerleri ateştir. Yok, hoş görülmek isterlerse özürleri kabul edilmeyecektir."},{"n":25,"t":"Geçmişlerini ve geleceklerini onlara güzel gösteren birtakım arkadaşları onlara atadık. Kendilerinden önce gelip geçmiş cin ve insan toplumları için gerçekleşen o söz kendileri için de geçerli oldu. Onlar kaybetmişlerdi."},{"n":26,"t":"İnkar edenler, \"Kazanmanız için, bu Kuran’ı dinlemeyin, anlaşılmasını engelleyin\" dediler."},{"n":27,"t":"İnkar edenlere şiddetli bir azabı tattıracağız ve yaptıklarının en kötüsüyle onlara karşılık vereceğiz."},{"n":28,"t":"ALLAH düşmanlarının cezası işte bu ateştir. Ayetlerimizi bile bile inkâr etmelerinin bir karşılığı olarak orası onların ebedi yurdu olacaktır."},{"n":29,"t":"İnkar edenler, \"Efendimiz, cinlerden ve insanlardan bizi saptıranları bize göster, onları ayaklarımızın altına alalım da en alçak olanlardan olsunlar\" derler."},{"n":30,"t":"\"Efendimiz ALLAH’tır\" dedikten sonra doğru yolu izleyenlerin üzerine melekler iner: \"Korkmayın, üzülmeyin ve davetli olduğunuz bahçeyle sevinin.\""},{"n":31,"t":"\"Dünya hayatında da, ahirette de sizin dostlarınız biziz. Orada canınızın çektiği ve istediğiniz her şey vardır.\""},{"n":32,"t":"\"Bağışlayan ve Rahim olandan bir ağırlama olarak.\""},{"n":33,"t":"ALLAH’a çağıran, erdemli davranan ve \"Ben teslim olanlardanım\" diyenden daha güzel sözlü kim olabilir?"},{"n":34,"t":"İyilik ile kötülük bir olmaz. Sen en iyi bir biçimde karşılık ver. O zaman, aranızda düşmanlık bulunan kişi belki en iyi dostun oluverir."},{"n":35,"t":"Bu duruma ancak dirençli olanlar eriştirilir. Bu duruma ancak alabildiğine şanslı olanlar ulaştırılır."},{"n":36,"t":"Sapkından herhangi bir düşünce seni etkisi altına alırsa ALLAH’a sığın. O İşitendir, Bilendir."},{"n":37,"t":"Gece, gündüz, güneş ve ay O’nun ayetlerindendir. Güneşe ve ay’a secde etmeyin, onları yaratan ALLAH’a secde edin. O’na hizmet edecekseniz."},{"n":38,"t":"Büyüklenirlerse, Efendinin yanındakiler hiç yorulmadan gece gündüz O’nu yüceltirler."},{"n":39,"t":"Kupkuru gördüğün toprağın üzerine su yağdırdığımızda onun titreşip kabarması da O’nun ayetlerindendir. Onu dirilten ölüleri de diriltir. O, her şeye gücü yetendir."},{"n":40,"t":"Ayetlerimiz konusunda çarpıtmalar yapanlar bizden gizli kalmaz. Ateşe atılan mı, yoksa diriliş gününde güven içinde bize gelen mi daha iyidir? Dilediğiniz gibi davranın. O, yaptıklarınızı elbette Görendir."},{"n":41,"t":"Kendilerine mesaj ulaştıktan sonra onu inkâr edenler bilsin ki o üstün bir kitaptır."},{"n":42,"t":"Batıl, onun ne önünden ne de ardından yaklaşamaz. Bilge ve övgüye layık olanın indirdiği bir vahiydir."},{"n":43,"t":"Senin için söylenilenler, senden önceki elçiler için söylenilenlerin aynısıdır. Kuşkusuz senin Efendin hem bağışlanma sahibi, hem de acı azap sahibidir."},{"n":44,"t":"Onu yabancı dilde bir Kuran kılsaydık, \"Onun ayetleri açıklanmalı değil miydi?\" diyeceklerdi. İster yabancı dil, ister Arapça olsun, de ki \"O, gerçeği onaylayanlar için (dilleri sözkonusu olmaksızın) bir rehber ve şifadır. Gerçeği onaylamayanların ise kulaklarında ağırlık vardır. Sanki uzak bir yerden sesleniliyor gibi onlara kapalıdır.\""},{"n":45,"t":"Biz Musa’ya kitabı (İbranice) verdik, onda da anlaşmazlığa düştüler. Efendinin vermiş olduğu bir söz olmasaydı aralarında yargı verilirdi. Gerçekten onlar ondan kuşku ve şüphe içindedirler."},{"n":46,"t":"Kim erdemli davranırsa kendi yararınadır. Kim kötü davranırsa kendi zararınadır. Efendin, kullara zulmetmez."},{"n":47,"t":"O anın bilgisi O’nun katındadır. O’nun bilgisi olmadan ne meyveler kabuklarından çıkabilir ne de bir dişi gebe kalır veya doğum yapar. \"Hani benim ortaklarım nerede?\" diye onlara seslendiği gün onlar: \"Hiçbirimizin buna şahitlik etmediğini sana arzederiz\" derler."},{"n":48,"t":"Daha önce yardım için çağırdıkları (dine ortak koştukları kişiler) onlardan uzaklaşmıştır. Artık kaçacak bir yerleri olmadığını anlarlar."},{"n":49,"t":"İnsan, iyilik istemekten bıkmaz. Ancak kendisine bir kötülük dokunduğunda umutsuzdur, kötümserdir."},{"n":50,"t":"Sıkıntısının ardından, kendisine bizden bir rahmet tattırsak, \"Bu bana aittir. O anın da geleceğini sanmam. Efendime döndürülürsem de O’nun katında benim için daha güzel şeyler vardır\" der. İnkarcılara, yapmış olduklarının gerçek niteliğini elbette haber vereceğiz. Çetin bir azaptan tattıracağız onlara."},{"n":51,"t":"İnsana bir nimet verdik mi, yüz çevirip yan çizer. Başına bir kötülük geldiğinde ise yalvarıp durur."},{"n":52,"t":"De ki: \"Ya o (mesaj) ALLAH’tan idiyse ve siz de onu yalanlamış iseniz? Buna karşı kesin bir tavır alandan daha sapık kim olabilir?"},{"n":53,"t":"Onun gerçek olduğu onlara apaçık oluncaya kadar onlara, ufuklarda ve kendi içlerinde ayetlerimizi (işaret ve kanıtlarımızı) göstereceğiz. Efendinin her şeye tanık olması yetmez mi?"},{"n":54,"t":"Aslında onlar Rab’lerinden bir kuşku içindedirler. O, her şeyi (bilgi ve yönetimiyle) kuşatmıştır."}]},{"id":42,"name":"Şura Suresi","verses":[{"n":1,"t":"H. M."},{"n":2,"t":"A. S. Q."},{"n":3,"t":"Üstün ve Bilge olan ALLAH sana ve senden öncekilere böyle vahyeder."},{"n":4,"t":"Göklerde, yerde ne varsa O’nundur. O Yücedir, Büyüktür."},{"n":5,"t":"Gökler (O’na olan saygıdan ötürü) nerdeyse üstlerinden çatlayacak. Denetçiler Rab’lerini överek yüceltirler ve yerdekiler için bağışlanma dilerler. ALLAH kesinlikle Bağışlayandır, Rahimdir."},{"n":6,"t":"O’ndan başkasını veliler edinenleri ALLAH’a bırak. Sen onların avukatı değilsin."},{"n":7,"t":"Kentlerin anası ve çevresini uyarman için ve gerçekleşecek olan Toplanma Gününe karşı uyarman için biz kusursuz bir dile sahip olan bir Kuran’ı böylece sana vahyediyoruz. Onlardan bir kısmı bahçeye, bir kısmı da cehenneme girecektir."},{"n":8,"t":"ALLAH dileseydi onları bir tek toplum kılardı. Ancak O, dilediğini rahmetine sokar. Zalimlerin bir sahibi ve yardımcısı yoktur."},{"n":9,"t":"O’nun dışında veliler (sahipler) mi edindiler? Biricik veli ALLAH’tır, ölüleri O diriltir ve O her şeye Kadirdir."},{"n":10,"t":"Bu mesajın herhangi bir bölümünde anlaşmazlığa düşerseniz hüküm ALLAH’a aittir. Efendim ALLAH işte böyledir. Ben O’na güvendim ve O’na yönelirim."},{"n":11,"t":"O gökleri ve yeri yararak yaratandır. İçinizden sizin için eşler yarattı ve çiftlik hayvanlarını da çiftler halinde yarattı. Böylece sizi orada üretiyor. O’na benzer hiçbir şey yoktur. O, İşitendir, Görendir."},{"n":12,"t":"Göklerin ve yerin tüm kontrolü O’na aittir. Dilediğine rızkı bol verir veya kısar. O her şeyi Bilendir."},{"n":13,"t":"Daha önce Nuh’a buyrulan dini size yasa olarak belirledik. Sana vahyettiğimiz gibi İbrahim’e, Musa’ya ve İsa’ya da öğütledik: \"Bu dini doğru tutun ve onda ayrılığa düşmeyin.\" Fakat kendilerini çağırdığın şey, ortak koşanlara ağır gelmektedir. ALLAH dileyeni kendine seçer ve kendisine yöneleni doğruya ulaştırır."},{"n":14,"t":"Kendilerine bilgi ulaştıktan sonra sırf aralarındaki çekememezlik yüzünden ayrılığa düştüler. Belli bir zaman için Efendinin verilmiş bir söz olmasaydı onların arasında hemen hüküm verilirdi. Onlardan sonra kitaba mirasçı olanlar da ondan kuşku ve şüphe içindedirler."},{"n":15,"t":"Sen buna çağır ve sana emredildiği gibi dosdoğru uygula. Onların fantazilerine ve de ki \"ALLAH’ın bana indirdiği kitabı onayladım. Sizin aranızda adaletle davranmakla emrolundum. ALLAH bizim de Efendimiz, sizin de Efendinizdir. Bizim işlediklerimiz bize, sizin işledikleriniz ise sizedir. Bizimle sizin aranızda herhangi bir tartışma yoktur. Bizi ALLAH biraraya getirecektir. Sonunda dönüş O’nadır."},{"n":16,"t":"ALLAH hakkında, O’nun çağrısına yanıt verildikten sonra tartışanların delilleri Rab’leri katında geçersizdir. Gazabı haketmişlerdir ve onlara çetin bir azap vardır."},{"n":17,"t":"O ALLAH ki kitabı gerçek ve adaletle indirmiştir. Ne bilirsin, belki o an yakındır."},{"n":18,"t":"Onu onaylamayanlar onun hakkında meydan okuyorlar. Onu onaylayanlar ise ondan kaygı duyarlar ve onun gerçek olduğunu bilirler. O an konusunda kuşku duyanlar büyük bir sapıklık içindedirler."},{"n":19,"t":"ALLAH kullarına lütfedendir. Dilediğini/dileyeni rızıklandırır. O Güçlüdür, Üstündür."},{"n":20,"t":"Kim ahiret ödülünü isterse onun ödülünü arttırırız. Dünya ödülünü isteyene de onu veririz ancak onun ahiretten bir payı olmaz."},{"n":21,"t":"Yoksa ALLAH’ın izni olmadığı halde onlar için dini kurallar ve yasalar ortaya koyan ortakları mı var? Daha önce belirlenmiş bir karar olmasaydı onların arasında yargı verilirdi. Zalimlere acı bir azap vardır."},{"n":22,"t":"Yaptıkları işler başlarına gelirken zalimleri kaygı içinde görürsün. Gerçeği onaylayıp erdemli davrananlar bahçelerin bahçelerindedir. Rab’leri katında diledikleri her şeyi alırlar. İşte bu, büyük lütuftur."},{"n":23,"t":"ALLAH, gerçeği onaylayıp erdemli davranan kullarını böyle müjdeler. De ki \"Ben sizden, akrabalık sevgisi dışında herhangi bir ücret istemiyorum.\" Kim bir iyilik işlerse onun iyiliğini arttırırız. ALLAH Bağışlayandır, takdir edendir."},{"n":24,"t":"Onlar, \"O, ALLAH hakkında yalan mı uydurdu?\" mu diyorlar? ALLAH dilese senin kalbini mühürler. ALLAH yanlışı siler ve sözleriyle gerçeği yerleştirir. O en gizli düşünceleri bilir."},{"n":25,"t":"O, kullarından tövbeleri kabul eder, günahları affeder ve yaptıklarınızı bilir."},{"n":26,"t":"Gerçeği onaylayıp erdemli davrananların çağrısına cevap verir ve onlara lütfunu arttırır. İnkarcılar ise çetin bir cezayı haketmiştir."},{"n":27,"t":"ALLAH kullarına rızkı bollaştırsaydı, yeryüzünde azacaklardı. Nitekim dilediği ölçüde gönderir. O, kullarından Haberdardır, Görendir."},{"n":28,"t":"Umutlarını kesmelerinden sonra yağmuru indiren ve rahmetini yayandır. O, Övgüye Layık bir Dosttur."},{"n":29,"t":"Gökleri ve yeri yaratıp onlarda çeşitli yaratıklar yayması O’nun ayetlerindendir. O, dilediği zaman onları toplayabilir."},{"n":30,"t":"Size dokunan bir kötülük, işlediklerinizin bir sonucudur. O, birçoğunu da affeder."},{"n":31,"t":"Siz yeryüzünde kaçamazsınız. Sizin ALLAH ‘tan başka bir sahibiniz ve yardımcınız yoktur."},{"n":32,"t":"Okyanusta dağlar gibi akıp giden gemiler de O’nun ayetlerindendir."},{"n":33,"t":"Dilerse rüzgarı durdurur ve onlar suyun üzerinde hareketsiz kalırdı. Bunda, her sabreden ve şükreden kişi için ibretler vardır."},{"n":34,"t":"Yahut, yaptıkları yüzünden onları yok eder. Bunun yerine birçoğunu da bağışlar."},{"n":35,"t":"Ayetlerimiz ve mucizelerimiz üzerinde tartışanlar kendilerinin kaçacak bir yeri olmadığını bilirler."},{"n":36,"t":"Size ne verildiyse dünya hayatının geçimliğidir. Ancak gerçeği onaylayanlar ve Rab’lerine güvenenler için ALLAH’ın yanında bulunanlar daha iyidir ve süreklidir."},{"n":37,"t":"Onlar ki büyük günahlardan çirkin işlerden kaçınırlar ve kızdıkları zaman bağışlarlar."},{"n":38,"t":"Onlar, Rab’lerinin çağrısına karşılık verirler, namazı gözetirler, işlerini aralarında danışma ile kararlaştırırlar ve kendilerine verdiğimiz rızıklardan yardım için verirler."},{"n":39,"t":"Haksızlığa uğradıklarında kendilerini savunurlar."},{"n":40,"t":"Kötülüğün cezası, benzeri bir kötülüktür ancak kim affeder ve erdemli davranırsa ALLAH tarafından ödüllendirilir. O, zalimleri sevmez."},{"n":41,"t":"Haksızlığa uğradıktan sonra hakları için direnenler kınanmazlar, cezalandırılmazlar."},{"n":42,"t":"Ancak, halka zulmedenlere ve yeryüzünde haksız yere saldıranlara karşı durulmalıdır. Onlara acı bir azap vardır."},{"n":43,"t":"Sabredip bağışlamak, sağlam bir karakteri gösterir."},{"n":44,"t":"ALLAH kimi saptırmışsa, artık O’ndan sonra onun bir koruyucusu yoktur. Azabı gördükleri zaman zalimlerin, \"Bizim için bir şans daha yok mu?\" dediklerini görürsün."},{"n":45,"t":"Aşağılanmış ve başları eğilmiş olarak ateşe sunulurlarken göz ucuyla çevrelerine bakındıklarını görürsün. Gerçeği onaylayanlar, \"Gerçek kaybedenler, Diriliş Gününde kendilerini ve ailelerini kaybedenlerdir. Zalimler sürekli bir azaba mahkûm olmuştur\" derler."},{"n":46,"t":"Onların, ALLAH’tan başka kendilerine yardım edecek bir dostları yoktur. ALLAH’ın saptırdığı kimse için bir yol bulunmaz."},{"n":47,"t":"ALLAH katından, geri çevrilmesi olanaksız olan gün gelmezden önce Efendinize cevap veriniz. O gün sizin için ne bir sığınak ne de bir koruyucu vardır."},{"n":48,"t":"Yüz çevririrlerse, biz seni onlara bir bekçi olarak göndermedik. Sana düşen sadece bildirmektir. Biz insana tarafımızdan bir rahmet tattırdığımız zaman onunla sevinir; ama kendi yaptıklarının bir sonucu olarak başlarına bir kötülük gelse, o zaman insan nankörleşir."},{"n":49,"t":"Göklerin ve yerin yönetimi ALLAH’ındır. Dilediğini yaratır. Dilediğine dişiler, dilediğine de erkekler verir."},{"n":50,"t":"Yahut hem erkek hem dişi olarak çift verir. Dilediğini de kısır yapar. O Bilendir, her şeye gücü yetendir."},{"n":51,"t":"ALLAH bir insanla ancak vahiy yoluyla veya bir perde arkasından iletişim kurar yahut bir elçi gönderip izniyle dilediğini vahyeder. O, Yücedir, Bilgedir."},{"n":52,"t":"Biz böylece sana katımızdan bir ruh vahyettik. Sen kitap nedir gerçeği onaylama nedir bilmezdin. Ancak onu, dilediğimiz kulları doğruya ulaştıran bir ışık kıldık. Sen elbette doğru yola kılavuzluk ediyorsun."},{"n":53,"t":"Göklerde ve yerde bulunan her şeyin sahibi ALLAH’ın yoluna… Kesinlikle, tüm işler ALLAH’a döner."}]},{"id":43,"name":"Zuhruf Suresi","verses":[{"n":1,"t":"H. M."},{"n":2,"t":"Apaçık kitaba andolsun ki"},{"n":3,"t":"Anlamanız için onu kusursuz bir dile sahip bir Kuran yaptık."},{"n":4,"t":"O, ana kitapta (korunur), katımızda üstündür, bilgedir."},{"n":5,"t":"Haddi aşan bir toplumsunuz diye mesajı size iletmekten vaz mı geçelim?"},{"n":6,"t":"Öncekilere nice peygamberler göndermişizdir."},{"n":7,"t":"Fakat, kendilerine giden her peygamberle alay ettiler."},{"n":8,"t":"Şunlardan daha güçlülerini yok ettik. Öncekilerin örneği geçmiştir."},{"n":9,"t":"Onlara, \"Gökleri ve yeri kim yarattı?\" diye sorsan, \"Onları, Üstün ve her şeyi bilen yarattı\" diyeceklerdir."},{"n":10,"t":"O ki, yeryüzünü oturmanıza elverişli kıldı ve doğru gitmeniz için sizin için orada yollar açtı."},{"n":11,"t":"O ki gökten bir ölçüye göre su indirdi. Nitekim onunla ölü bir ülkeyi dirilttik. İşte böyle çıkarılırsınız."},{"n":12,"t":"O ki bütün çiftleri yarattı ve binesiniz diye sizin için gemiler ve çiftlik hayvanları yarattı."},{"n":13,"t":"Ki onların üstüne binesiniz ve onlara bindiğiniz zaman Efendinizin size olan nimetini düşünerek şunları diyesiniz: \"Bunu bizim emrimize veren çok yücedir. Onları kendi başımıza kontrol altına alamazdık.\""},{"n":14,"t":"\"Ve biz, sonunda Efendimize döneceğiz.\""},{"n":15,"t":"Kullarından bazılarını O’na bir pay olarak ayırdılar. İnsan gerçekten apaçık bir nankördür."},{"n":16,"t":"Yaratıklarından kızları kendisine ayırdı da oğulları size mi seçti?"},{"n":17,"t":"Onlardan birisi, Rahman’a yakıştırdığı (kız çocuğu) ile müjdelenince, morali bozularak yüzü simsiyah kesilir:"},{"n":18,"t":"\"Süsler içinde yetiştirilmesine rağmen kavgada beceriksiz olan mı!?\""},{"n":19,"t":"Rahman’ın kulları olan melekleri dişi saydılar! Onların yaratılışlarına mı tanık oldular? Bu tanıklıkları kaydedilecek ve sorguya çekileceklerdir."},{"n":20,"t":"Hatta, \"Rahman dileseydi biz onlara hizmet etmezdik\" dediler. Onların bu konuda bir bilgileri yoktur. Onlar sadece tahminde bulunuyorlar."},{"n":21,"t":"Onlara bundan önce bir kitap mı verdik de ona mı dayanıyorlar?"},{"n":22,"t":"Hayır, \"Biz atalarımızı bir yol üzerinde bulduk ve biz onların öğretilerini izliyoruz\" dediler."},{"n":23,"t":"Tıpkı bunun gibi, senden önce, bir kente her ne zaman bir uyarıcı gönderdiysek elit tabaka, \"Biz, atalarımızı bir yol üzerinde bulduk ve biz onların öğretilerini izliyoruz\" derlerdi."},{"n":24,"t":"O da, \"Size, atalarınızı üzerinde bulduğunuzdan daha doğrusunu getirmiş isem de mi?\" derdi. Onlar da, \"Sizin getirdiğiniz mesajı inkâr ediyoruz\" derlerdi."},{"n":25,"t":"Biz de onlardan öc aldık. Yalanlayanların sonunun nasıl olduğuna bir bak."},{"n":26,"t":"İbrahim, babasına ve halkına demişti ki, \"Sizin hizmet ettiklerinizden uzağım.\""},{"n":27,"t":"\"Beni Yaratan bana doğru yolu gösterecektir.\""},{"n":28,"t":"Belki doğru yola dönerler diye onun ardından gelecekler için bunu ebedi bir ders kıldı."},{"n":29,"t":"Doğrusu, kendilerine gerçek ve apaçık bir elçi varıncaya kadar şunlara ve atalarına imkan tanıdım."},{"n":30,"t":"Kendilerine gerçek geldiği zaman, \"Bu bir büyüdür ve biz onu inkâr ediyoruz\" dediler."},{"n":31,"t":"\"Bu Kuran, şu iki kentten ünlü ve büyük bir adama indirilmeli değil miydi?\" dediler."},{"n":32,"t":"Efendinin rahmetini onlar mı paylaştırıyorlar? Dünya hayatında onların geçimliklerini aralarında biz paylaştırdık; birbirlerine iş gördürebilmeleri için onları birbirlerine derecelerle üstün kıldık. Efendinin rahmeti onların biriktirdiklerinden daha iyidir."},{"n":33,"t":"Tüm insanlar (inkârcılıkta) bir tek toplum olacak olmasaydı, Rahman’ı inkâr edenlerin evini gümüş tavanlar ve binip çıkacakları merdivenlerle donatırdık."},{"n":34,"t":"Evlerine kapılar ve konforlu mobilyalar."},{"n":35,"t":"Ve nice gösterişli maddeler. Tüm bunlar bu dünya hayatının geçici materyalidir. Ahiret ise Efendinin katında erdemlilerindir."},{"n":36,"t":"Kim Rahman’ın mesajına aldırış etmezse, ona bir sapkını sardırırız da onun arkadaşı olur."},{"n":37,"t":"Nitekim onları yoldan çıkarırlar. Buna rağmen onlar doğru yolda olduklarını sanırlar."},{"n":38,"t":"Nihayet bize geldiğinde, \"Keşke benimle senin aranda iki doğu arası kadar uzaklık olsaydı; sen ne kötü bir arkadaşmışsın sen!\" der."},{"n":39,"t":"Haksızlık etmiş olduğunuz için, o gün (pişmanlığınız) size bir yarar sağlamaz; siz cezayı paylaşacaksınız."},{"n":40,"t":"Sen mi sağıra işittireceksin, yahut körü ve apaçık bir sapıklıkta olanı yola getireceksin?"},{"n":41,"t":"Seni alıp götürsek de biz onları cezalandıracağız."},{"n":42,"t":"Yahut, onlara söz verdiğimizi sana gösteririz; bizim onlara gücümüz yeter."},{"n":43,"t":"Sana vahyedilene sarıl; çünkü sen doğru yoldasın."},{"n":44,"t":"Bu, sana ve halkına bir mesajdır; ondan sorulacaksınız."},{"n":45,"t":"Senden önce gönderdiğimiz elçileri araştır: \"Rahman’ın dışında hizmet edilecek tanrılar kabul etmiş miyiz?\""},{"n":46,"t":"Örneğin; Musa’yı ayetlerimizle Firavuna ve erkanına gönderdik ve \"Ben evrenlerin Efendisinin elçisiyim\" demişti."},{"n":47,"t":"Mucizelerimizi kendilerine götürdüğü zaman, o mucizelere gülmüşlerdi."},{"n":48,"t":"Onlara bir birinden büyük mucizeler gösterdik ve belki dönerler diye başlarına çeşitli felaketler getirdik."},{"n":49,"t":"\"Ey büyücü, bizim için Efendine dua et. Çünkü sen ona daha yakınsın; biz bundan sonra yola geleceğiz\" dediler."},{"n":50,"t":"Fakat, onlardan felaketi kaldırdığımızda, sözlerinden hemen dönüverdiler."},{"n":51,"t":"Firavun halkına şöyle seslendi: \"Ey halkım, Mısır’ın yönetimi ve şu altımda akıp giden ırmaklar bana ait değil mi? Görmüyor musunuz?\""},{"n":52,"t":"\"Yahut ben, şu aşağılık ve konuşmaktan aciz olan adamdan daha üstün değil miyim?\""},{"n":53,"t":"\"Neden ona altınlardan oluşan bir hazine verilmiyor, yahut neden yanında çalışacak melekler gelmiyor?\""},{"n":54,"t":"Böylece halkını yanılttı ve onlar da ona uydular. Onlar bayağı insanlardı."},{"n":55,"t":"Bizimle savaşmakta ısrar edince onlardan öc aldık, hepsini boğduk."},{"n":56,"t":"Onları, sonradan gelecekler için bir ibret ve örnek yaptık."},{"n":57,"t":"Meryemoğlu bir örnek olarak gösterilince senin halkın hemen reddetti."},{"n":58,"t":"\"Bizim tanrılarımız mı daha iyidir yoksa o mu?\" dediler. Sadece seninle tartışmak için bunu söylediler. Onlar gerçekte, kavgacı bir toplumdur."},{"n":59,"t":"O, kendisine iyilikte bulunduğumuz bir kuldan başka bir şey değildi. Onu İsrailoğullarına bir örnek kıldık."},{"n":60,"t":"Dileseydik sizi, yeryüzünü koloni haline getiren meleklere çevirirdik."},{"n":61,"t":"O (İsa), o an hakkında bir bilgi kaynağı ve işarettir. Öyleyse onun (zamanı) hakkında kuşku beslemeyin ve beni izleyin. Doğru yol budur."},{"n":62,"t":"Sapkın sizi yoldan çıkarmasın. O size açık bir düşmandır."},{"n":63,"t":"İsa apaçık mucizelerle gelince demişti ki \"Size bilgelik ve ayrılığa düştüğünüz konulara açıklama getirdim. ALLAH’ı dinleyiniz ve bana uyunuz.\""},{"n":64,"t":"\"ALLAH benim Efendim ve sizin de Efendinizdir, sadece O’na hizmet etmelisiniz. Dosdoğru yol budur.\""},{"n":65,"t":"Partiler ve mezhepler aralarında tartıştılar. Acı azaptan dolayı vay zalimlerin haline."},{"n":66,"t":"Onlar, farkında değilken, o anın kendilerine aniden gelmesini mi bekliyorlar?"},{"n":67,"t":"Erdemlilerin dışında, o gün yakın dostlar birbirlerine düşman kesilecek."},{"n":68,"t":"Kullarım, bugün size korku yoktur ve üzülmeyeceksiniz."},{"n":69,"t":"Ayetlerimi onaylayanlar ve teslim olanlar,"},{"n":70,"t":"Siz ve eşleriniz bahçeye girin; sevinç içinde ağırlanacaksınız."},{"n":71,"t":"Onlara altın tepsiler ve kadehlerle sunulur. Orada canların çektiği ve gözlerin hoşlandığı her şey vardır. Siz orada ebedi kalacaksınız."},{"n":72,"t":"Yaptıklarınızın bir karşılığı olarak size miras olarak verilen bahçe budur."},{"n":73,"t":"Orada sizin yemeniz için bol meyveler vardır."},{"n":74,"t":"Suçlular, cehennem azabında ebedi kalıcıdırlar."},{"n":75,"t":"Onlardan hafifletilmez ve onlar orada ümitsizdirler."},{"n":76,"t":"Biz onlara haksızlık etmedik, onlar kendi kendilerine haksızlık ettiler."},{"n":77,"t":"\"Ey Malik, artık Efendin bizim işimizi bitirsin\" diye seslenirler. O da, \"Siz böyle kalacaksınız\" der."},{"n":78,"t":"Size gerçeği getirdik; ancak çoğunuz gerçekten hoşlanmıyorsunuz."},{"n":79,"t":"Yoksa onlar bir plan mı kurdular? Biz de plan kurarız."},{"n":80,"t":"Yoksa, sırlarını ve komplolarını işitmediğimizi mi sanıyorlar. Doğrusu, yanlarındaki elçilerimiz kaydetmektedirler."},{"n":81,"t":"De ki: \"Rahman’ın bir çocuğu olsaydı, ona hizmet edenlerin ilki ben olurdum.\""},{"n":82,"t":"Göklerin ve yerin Rabbi, Yönetimin Rabbi, onların nitelemelerinden çok yücedir."},{"n":83,"t":"Bırak onları, kendilerine söz verilen günlerine kavuşuncaya kadar dalsınlar, oynasınlar."},{"n":84,"t":"Gökte de tanrı, yerde de tanrı O’dur. O Bilgedir, Bilendir."},{"n":85,"t":"Göklerin, yerin ve aralarındakilerin yönetimine sahip olan çok yücedir. O anın bilgisi O’nun yanındadır ve siz O’na döndürüleceksiniz."},{"n":86,"t":"Onların O’nun dışında çağırdıkları şefaat edemezler. Ancak bilerek gerçeğe tanıklık edenler hariç."},{"n":87,"t":"Onlara, kendilerini kimin yarattığını sorsan, \"ALLAH\" diyeceklerdir. Öyleyse neden çevriliyorlar?"},{"n":88,"t":"\"Efendim bunlar gerçeği onaylamayan bir topluluktur\" denmişti."},{"n":89,"t":"Onlara aldırma ve \"Selam\" (barış ve esenlik) de; yakında bilecekler."}]},{"id":44,"name":"Duhan Suresi","verses":[{"n":1,"t":"H. M."},{"n":2,"t":"Apaçık olan bu kitaba andolsun."},{"n":3,"t":"Biz uyarmak için onu kutlu bir gecede indirdik."},{"n":4,"t":"Onda tüm bilgelik işleri belirlenir."},{"n":5,"t":"Katımızdan bir buyruktur; biz elçiler göndeririz."},{"n":6,"t":"Efendinden bir rahmet olarak. O İşitendir, Bilendir."},{"n":7,"t":"Göklerin, yerin ve aralarındakilerin Rabbidir. Kuşkusuz bir onaya sahipseniz…"},{"n":8,"t":"O’ndan başka tanrı yoktur. Yaşatır ve öldürür. Sizin de önceki atalarınızın da Rabbidir."},{"n":9,"t":"Doğrusu, onlar bir kuşku içinde oynamaktadırlar."},{"n":10,"t":"Göğün apaçık bir dumanı getireceği günü gözetle."},{"n":11,"t":"İnsanları çepeçevre saracaktır; bu acı bir azaptır."},{"n":12,"t":"\"Efendimiz, bizden bu azabı kaldır; biz gerçeği onaylıyoruz.\""},{"n":13,"t":"Mesaja aldırış etmediler. Halbuki kendilerine apaçık bir elçi gelmişti."},{"n":14,"t":"Sonra ondan yüz çevirdiler ve \"Öğrenim görmüş bir deli!\" dediler."},{"n":15,"t":"Biz azabı birazcık kaldıracağız; ama siz yine döneceksiniz."},{"n":16,"t":"Asıl o büyük yakalama ile yakaladığımızda öc alırız."},{"n":17,"t":"Onlardan önce Firavunun halkını sınamıştık; onlara şerefli bir elçi gitmişti:"},{"n":18,"t":"\"Ey ALLAH’ın kulları, bana kulak verin. Ben size gönderilmiş güvenilir bir elçiyim.\""},{"n":19,"t":"\"ALLAH’a karşı büyüklenmeyin. Ben size apaçık bir delille gelmiş bulunuyorum.\""},{"n":20,"t":"\"Sizin beni taşlamanızdan/kovmanızdan, benim Efendime ve sizin Efendinize sığınıyorum.\""},{"n":21,"t":"\"Beni onaylamıyorsanız, bari beni yalnız bırakın.\""},{"n":22,"t":"Ve, \"Bunlar suçlu bir topluluk\" diye Efendisine yalvardı."},{"n":23,"t":"\"Kullarımla geceleyin yola çık. Siz izleniyorsunuz.\""},{"n":24,"t":"\"Denizi yarılmış olarak terket. Onlar boğulmaya mahkûm bir ordudur.\""},{"n":25,"t":"Onlar geride neler bırakmışlardı: Bahçeler, pınarlar,"},{"n":26,"t":"Ekinler ve yüksek makamlar,"},{"n":27,"t":"Ve içinde sefa sürdükleri nice nimetler…"},{"n":28,"t":"Böylece hepsini başka bir topluluğa miras bıraktık."},{"n":29,"t":"Ne gök ve ne de yer onlara ağladı; ertelenmediler de."},{"n":30,"t":"İsrailoğullarını alçaltıcı zulümden kurtarmıştık;"},{"n":31,"t":"Firavundan. O, azgın bir diktatör idi."},{"n":32,"t":"Tüm halkın arasından özellikle onları seçtik."},{"n":33,"t":"Ve onlara, açık bir sınav olarak mucizeler verdik."},{"n":34,"t":"Şunlar da diyorlar ki:"},{"n":35,"t":"\"Sadece bir kez ölürüz; dirilecek değiliz.\""},{"n":36,"t":"\"Doğru sözlüler iseniz, atalarımızı geri getirin.\""},{"n":37,"t":"Onlar mı, yoksa Tubba’ halkı ve onlardan öncekiler mi daha iyidir? Suçlu oldukları için onları yok etmiştik."},{"n":38,"t":"Biz, gökler, yer ve aralarındakileri oyun ve eğlence için yaratmadık."},{"n":39,"t":"Biz onları ancak belli bir amaca göre yarattık. Ne var ki onların çoğu bilmezler."},{"n":40,"t":"Hepsi Karar Günü topluca buluşacaklardır."},{"n":41,"t":"O gün dost, dostunu hiçbir şeyden koruyamaz ve yardım da görmezler."},{"n":42,"t":"Yalnız ALLAH’ın merhamet ettikleri hariç. O Üstündür, Rahimdir."},{"n":43,"t":"Elbette, zakkum ağacı"},{"n":44,"t":"Günahkarın yiyeceğidir."},{"n":45,"t":"Derişik asit gibi ve midelerde kaynayacaktır."},{"n":46,"t":"Sıcak suyun kaynaması gibi."},{"n":47,"t":"Onu yakalayın ve cehennemin ortasına sürükleyin."},{"n":48,"t":"Sonra başına kaynar su azabından dökün."},{"n":49,"t":"\"Tad bakalım; sen çok üstün ve şerefliydin!\""},{"n":50,"t":"\"Bu, işte kuşkulanıp durduğunuz şeydir.\""},{"n":51,"t":"Erdemli olanlar ise güvenlikli bir makamdadırlar."},{"n":52,"t":"Bahçeler ve pınarlar içerisinde."},{"n":53,"t":"İpek ve atlastan giysiler içinde karşılıklı otururlar."},{"n":54,"t":"Bu böyledir; onlara güzel eşler vermişizdir."},{"n":55,"t":"Tam bir güvenlik içinde her meyveyi isterler."},{"n":56,"t":"Orada, ilk ölümden başka ölüm tatmazlar. Onları cehennem azabından korumuştur."},{"n":57,"t":"Efendinin bir lütfu olarak. İşte büyük zafer budur."},{"n":58,"t":"Öğüt alsınlar diye senin dilinle onu kolaylaştırdık."},{"n":59,"t":"Öyleyse bekle; onlar da beklemektedirler."}]},{"id":45,"name":"Casiye Suresi","verses":[{"n":1,"t":"H. M."},{"n":2,"t":"Bu kitabın indirilmesi, Üstün ve Bilge olan ALLAH katındandır."},{"n":3,"t":"Gerçeği onaylayanlar için göklerde ve yerde ayetler var."},{"n":4,"t":"Sizin yaratılışınızda ve yaydığı tüm canlılarda kuşkusuz bir onayaa sahip bir toplum için ayetler var."},{"n":5,"t":"Gecenin ve gündüzün birbirini izlemesinde, ALLAH’ın gökten bir rızık indirerek onunla ölümünden sonra toprağı diriltmesinde ve rüzgarları yönetmesinde anlayan bir toplum için ayetler var."},{"n":6,"t":"Bunlar, sana gerçek olarak okuduğumuz ALLAH’ın ayetleridir. ALLAH’tan ve ayetlerinden sonra hangi hadisi onaylıyorlar?"},{"n":7,"t":"Vay haline her uydurukçu günahkarın!"},{"n":8,"t":"Kendisine okunan ALLAH’ın ayetlerini işittikten sonra, sanki onları hiç işitmemiş gibi büyüklük taslayarak direniyor. Onu acı bir cezayla müjdele."},{"n":9,"t":"Ayetlerimizden bir şey öğrendiği zaman onu alaya alır. Onlar için alçaltıcı bir azap vardır."},{"n":10,"t":"Onları cehennem beklemektedir. Ne işledikleri şeyler, ne de ALLAH’tan başka edindikleri dostlar onları kurtarabilir. Onlar, acı bir azabı haketmişlerdir."},{"n":11,"t":"Bu bir rehberdir. Rab’lerinin ayetlerini inkâr edenler için iğrenç ve acı bir azap vardır."},{"n":12,"t":"Lütfundan payınızı aramanız ve şükretmeniz için gemileri emriyle sürmenize uygun olarak denizi buyruğunuz altına veren ALLAH’tır."},{"n":13,"t":"Göklerde ve yerde ne varsa hepsini kendi katından buyruğunuza vermiştir. Düşünen bir topluluk için elbette bunda ibretler vardır."},{"n":14,"t":"Gerçeği onaylayanlara söyle ki, ALLAH’ın günlerini ummayanları bağışlasınlar. Zira O, yaptıkları işlere göre bir topluluğa karşılık verir."},{"n":15,"t":"Kim erdemli davranırsa kendisi içindir kim de kötülük işlerse kendi aleyhinedir. Sonra, siz Efendinize döndürüleceksiniz."},{"n":16,"t":"İsrailoğullarına kitabı, bilgeliği ve peygamberliği vermiştik. Onları iyi nimetlerle rızıklandırmış ve onları tüm halklara üstün kılmıştık."},{"n":17,"t":"Onlara apaçık emirler verdik. Kendilerine bilgi geldikten sonra, aralarındaki çekememezlikten ötürü ayrılığa düştüler. Diriliş Günü senin Efendin, ayrılığa düştükleri konularda onların arasında yargı verecektir."},{"n":18,"t":"Sonra sana da din konusunda bir yasa verdik; sen ona uymalısın, bilmeyenlerin keyfine uyma."},{"n":19,"t":"Onlar, ALLAH’tan hiçbir şeyi senden savamazlar. Zalimler birbirlerinin dostlarıdır. ALLAH da erdemlilerin dostudur."},{"n":20,"t":"Bunlar, halk için aydınlatıcı delillerdir, kuşkusuz bir onayaa sahip bir topluma bir rehber ve rahmettir."},{"n":21,"t":"Kötülükleri işleyen kimseler, dirildiklerinde ve ölümlerinde, kendilerini, gerçeği onaylayıp erdemli davrananlarla bir mi tutacağımızı sandılar? Ne kötü hüküm veriyorlar!"},{"n":22,"t":"ALLAH gökleri ve yeri belli bir amaç için yarattı ki her can, kazandığının karşılığını haksızlığa uğramadan görsün."},{"n":23,"t":"Fantazilerini tanrı edinen kimseye dikkat ettin mi? Nitekim ALLAH onu bilerek saptırmış, işitme duyusunu ve beynini mühürlemiş ve görüşüne perde koymuştur. ALLAH’tan başka kim onu doğruya iletebilir? Öğüt almaz mısınız?"},{"n":24,"t":"Onlar derler ki, \"Biz sadece dünya hayatında yaşarız. Yaşarız, ölürüz ve bizi zamandan başkası yok etmez.\" Onların bu konuda bir bilgisi yoktur. Onlar sadece zannediyorlar."},{"n":25,"t":"Onlara açık açık ayetlerimiz okunduğunda, \"Doğru sözlü iseniz atalarımızı geri getirin\" demekten başka delilleri yoktur."},{"n":26,"t":"De ki \"Sizi ALLAH diriltir ve öldürür. Sonra, gerçekleşmesinde kuşku bulunmayan Diriliş Gününde sizi bir araya toplar. Fakat insanların çoğu bilmez.\""},{"n":27,"t":"Göklerin ve yerin yönetimi ALLAH’a aittir. O an gerçekleştiği gün, işte o gün batılı savunanlar hüsrana uğrayacaktır."},{"n":28,"t":"Her toplumu diz çökmüş halde görürsün. Her toplum kendi kitabına çağrılır: \"Bugün size, yaptıklarınızın karşılığı ödenecektir.\""},{"n":29,"t":"\"Bu kitabımız size karşı gerçeği konuşmaktadır. Çünkü biz, yaptıklarınızı kaydediyorduk.\""},{"n":30,"t":"Gerçeği onaylayan ve erdemli davrananlara gelince, Rab’leri onları rahmetine sokacaktır. Apaçık zafer işte budur."},{"n":31,"t":"İnkar edenlere gelince: \"Ayetlerimiz size okunmuş ve siz de büyüklenip suçlu bir topluluk olmamış mıydınız?\""},{"n":32,"t":"Kendilerine ALLAH’ın sözünün bir gerçek ve o anın kesinleşmesi kaçınılmaz bir olay olduğu söylendiğinde siz, \"O anın ne olduğunu bilmeyiz! Biz sadece çeşitli sanılara sahibiz ve bu konuda kesin bir bilgi elde etmiş değiliz\" derdiniz."},{"n":33,"t":"Yaptıkları kötülükler kendilerine görünecek ve alay etmekte oldukları şey onları kuşatıp avlayacaktır."},{"n":34,"t":"Ve onlara şöyle denir: \"Bugünkü karşılaşmanızı unuttuğunuz için biz de bugün sizi unutuyoruz. Yeriniz ateştir ve sizin bir yardımcınız da olmayacaktır.\""},{"n":35,"t":"\"Çünkü siz ALLAH’ın ayetlerini alaya aldınız ve dünya hayatı sizi kandırdı.\" Sonuç olarak, onlar o gün oradan çıkamazlar ve özürleri de dinlenmez."},{"n":36,"t":"Göklerin Rabbi, yerin Rabbi ve evrenlerin Rabbi olan ALLAH’a övgüler olsun."},{"n":37,"t":"Göklerde ve yerde tüm büyüklükler O’na aittir. O Üstündür, Bilgedir."}]},{"id":46,"name":"Ahkaf Suresi","verses":[{"n":1,"t":"H. M."},{"n":2,"t":"Kitabın indirilmesi, Üstün ve Bilge olan ALLAH’tandır."},{"n":3,"t":"Biz gökleri, yeri ve aralarındakileri ancak belli bir amaca göre ve belli bir süre için yarattık. İnkar edenler uyarıya aldırış etmemektedirler."},{"n":4,"t":"De ki: \"ALLAH’ın dışında yalvardıklarınıza bir bakın. Onların yerden neyi yarattığını bana gösterin. Yoksa göklerde onların bir ortaklığı mı var? Bundan önce bir kitap veya bir bilimsel belge getirin, doğru sözlü iseniz?\""},{"n":5,"t":"ALLAH’ı bırakıp da Diriliş Gününe kadar kendilerine cevap veremeyen ve hatta onların dualarından bile habersiz olanları çağıranlardan daha sapık kim olabilir?"},{"n":6,"t":"Halk toplandığı zaman onlara düşman olacaklardır ve onların kendilerine hizmet etmelerine karşı çıkacaklardır."},{"n":7,"t":"Kendilerine apaçık ayetlerimiz okunduğunda, kendilerine gelen gerçeğe karşı çıkanlar, \"Bu, açıkça bir büyüdür\" dediler."},{"n":8,"t":"Yoksa \"Onu uydurdu\" mu diyorlar? De ki: \"Onu ben uydurduysam siz beni ALLAH’tan gelecek hiçbir şeye karşı koruyamazsınız. O, sizin taşkınlığınızı en iyi bilendir. Benimle sizin aranızda tanık olarak O yeter. O Bağışlayandır, Rahimdir."},{"n":9,"t":"De ki \"Ben türedi bir elçi değilim. Bana ve size ne olacağını da bilmem. Ben, ancak bana vahyedilene uyuyorum. Ben apaçık bir uyarıcıdan başka bir şey değilim.\""},{"n":10,"t":"De ki: \"Düşündünüz mü, ya o ALLAH katından ise ve siz de ona karşı çıkmışsanız ve İsrailoğullarından bir tanık da bunun benzerini görüp onayladığı halde, siz kibirlenip yüz çevirmişseniz?! Kuşkusuz ALLAH zalim topluluğu doğru yola iletmez.\""},{"n":11,"t":"İnkar edenler, gerçeği onaylayanlara, \"O iyi bir şey olsaydı onlar (İsrailoğulları) bizden öne geçemezlerdi\" derler ve ona yol bulamadıkları için, \"Bu bir efsanedir\" diyeceklerdir."},{"n":12,"t":"Bundan önce Musa’nın kitabı rehber ve rahmet idi. Bu, zalimleri uyarmak ve güzel davrananlara bir müjde olmak üzere Arapça indirilmiş doğrulayıcı bir kitaptır."},{"n":13,"t":"\"Efendimiz ALLAH’tır\" deyip dosdoğru davrananlara bir korku yoktur ve onlar üzülmezler de."},{"n":14,"t":"Onlar bahçe halkıdır; yapmış olduklarına karşılık olarak orada ebedi kalacaklardır."},{"n":15,"t":"Biz insana, ana ve babasına iyilik etmesini öğütledik. Anası onu zahmetle taşır, zahmetle doğurur. Ana karnında taşınması ile sütten kesilmesi otuz ay sürer. Nihayet olgunluk çağına erince ve kırk yaşına varınca: \"Efendim, bana, anama ve babama verdiğin nimete şükretmeye ve razı olacağın yararlı işler yapmeaya beni yönelt. Benim soyumu islah et. Ben tövbe edip, sana teslim olanlardanım\" demelidir."},{"n":16,"t":"İşlediklerinin en iyisini kabul ettiğimiz ve kötülüklerini geçtiğimiz bu kimseler bahçe halkı arasındadırlar. Bu, kendilerine verilen doğru sözdür."},{"n":17,"t":"Öte yanda bir başkası var ki anne babasına, \"Öf size, benden önce nice kuşaklar geçmiş olmasına rağmen benim diriltileceğimi mi iddia ediyorsunuz?\" O ikisi ise ALLAH’a sığınarak: \"Yazık sana; lütfen onayla. ALLAH’ın sözü gerçektir.\" Bunun üzerine o, \"Bu, eskilerin masallarından başka bir şey değil\" der."},{"n":18,"t":"Bu gibiler, gelip geçmiş cin ve insan toplumları arasında azap sözünü haketmiş kimselerdir. Onlar kaybedenlerdir."},{"n":19,"t":"Her biri için, yaptıklarına göre dereceler vardır. Yaptıklarının karşılığı, haksızlık edilmeden tam verilir."},{"n":20,"t":"İnkarcılar cehenneme sunulduğu gün, \"Dünya hayatında tüm güzel şeylerinizi boşa harcayıp onların zevkini sürdünüz. Yeryüzünde haksız yere büyüklenmenizin ve yoldan çıkmanızın karşılığında bugün alçaltıcı azabı göreceksiniz.\""},{"n":21,"t":"Ad’ın kardeşinin kum tepeciklerindeki halkını uyarmış olduğunu hatırla. Ondan önce ve sonra \"ALLAH’tan başkasına hizmet etmeyin. Sizin için büyük birgünün azabından korkarım\" diyen nice uyarıcılar geçmişti."},{"n":22,"t":"\"Bizi tanrılarımızdan saptırmak için mi bize geldin? Doğru sözlü isen bize söz verdiğini getir bakalım\" dediler."},{"n":23,"t":"\"Onun bilgisi sadece ALLAH’ın yanındadır. Ben benimle gönderilen şeyi size duyuruyorum fakat sizin cahil bir toplum olduğunuzu görüyorum.\""},{"n":24,"t":"Nihayet onun yayılarak vadilerine yönelmiş olduğunu gördüklerinde, \"Bu, bize yağmur yağdıracak bir buluttur\" dediler. Hayır! bu sizin gelmesi için meydan okuduğunuz acı bir azaba sahip bir fırtınadır."},{"n":25,"t":"Efendinin emriyle her şeyi yerle bir eder. Sabahladıklarında, evlerinden başka her şey görülmez olmuştu. Suçlu topluluğu işte böyle cezalandırırız."},{"n":26,"t":"Sizi yerleştirmediğimiz yerlere yerleştirmiştik onları. Onlara işitme ve görme duyuları ile beyinler vermiştik. ALLAH’ın ayet ve mucizelerini bile bile inkâr ettikleri için ne işitme, ne görme duyuları ve ne de beyinleri onlara hiçbir yarar sağlamadı. Alaya aldıkları şeyler kendilerini çepeçevre kuşatıverdi."},{"n":27,"t":"Çevrenizdeki nice kentleri de yok ettik. Dönerler diye onlara ayetleri açıklamıştık."},{"n":28,"t":"ALLAH’tan başka, O’na yakınlık sağlamak amacıyla edindikleri tanrılar kendilerine yardım etmeli değil miydi? Aksine, onları terkettiler. İşte onların yalanları ve uydurmaları böyledir."},{"n":29,"t":"Cinlerden bir grubu, Kuran’ı dinlemek üzere sana yöneltmiştik. Ona geldiklerinde, \"Susun\" dediler. (Okuma) bitirilince topluluklarına birer uyarıcı olarak döndüler."},{"n":30,"t":"\"Ey halkımız\" dediler, \"Biz, Musa’dan sonra, kendisinden öncekileri doğrulayıcı olarak indirilen bir kitabı dinledik. O gerçeğe ve dosdoğru yola iletmektedir.\""},{"n":31,"t":"\"Ey halkımız, ALLAH’a çağıranı yanıtlayın. O’nu onaylayın ki günahlarınızı bağışlasın ve sizi acı azaptan korusun.\""},{"n":32,"t":"ALLAH’a çağıranı yanıtlamayanlar yeryüzünde kaçamaz. Onların O’na karşı dostları da olmaz. Onlar apaçık bir sapıklık içindedirler."},{"n":33,"t":"Gökleri ve yeri yaratan ve bunları yaratmakla yorulmayan ALLAH’ın ölüleri diriltebileceğini düşünmezler mi? Evet, O her şeye gücü yetendir."},{"n":34,"t":"İnkarcılar ateşe sunuldukları gün: \"Bu gerçek değil mi?\" Derler ki \"Evet, Efendimize andolsun.\" O da, \"İnkar etmiş olduğunuz için azabı tadın\" der."},{"n":35,"t":"Karar ve azim sahibi elçiler nasıl sabrettiyse sen de sabret ve onlar için acele etme. Onlar, kendilerine söz verileni gördüklerinde, (sanki dünyada) gündüzün bir anı kadar kalmışlardır. Bu bir bildiridir: Yoldan çıkmış topluluklardan başkası mı yok edilir?"}]},{"id":47,"name":"Muhammed Suresi","verses":[{"n":1,"t":"İnkar edip ALLAH’ın yolundan ayrılanların tüm işlerini O boşa çıkarır."},{"n":2,"t":"Gerçeği onaylayıp erdemli davrananların ve Rab’lerinden bir gerçek olarak Muhammed’e indirileni onaylayanların ise günahlarını örter ve durumlarını düzeltir."},{"n":3,"t":"Çünkü inkâr edenler batıla uymakta, gerçeği onaylayanlar ise Rab’lerinden gelen gerçeğe uymaktadırlar. ALLAH halkın durumunu böyle sergiler."},{"n":4,"t":"Savaşta inkâr edenlerle karşılaştığınızda kontrol merkezlerini vurun. Sonunda üstün geldiğinizde onları esir alın; onları ya karşılıksız veya fidye karşılığında salın. Savaş durumu kalkıncaya kadar bunu uygulayın. ALLAH dileseydi sizi savaş derdinden kurtarırdı; ancak O sizi böylece birbirinizle sınamaktadır. ALLAH yolunda öldürenlere gelince, onların yaptıklarını boşa çıkarmayacaktır."},{"n":5,"t":"Onlara yol gösterecek ve işlerini düzeltecektir."},{"n":6,"t":"Onları kendilerine tanıtmış olduğu bahçeye sokacaktır."},{"n":7,"t":"Ey gerçeği onaylayanlar, ALLAH’ı desteklerseniz, O da sizi destekler ve ayaklarınızı sağlam tutar."},{"n":8,"t":"İnkar edenler ise yıkımı haketmişlerdir; onların işlerini boşa çıkarmıştır."},{"n":9,"t":"Çünkü onlar ALLAH’ın indirdiğini beğenmediler. O da onların işlerini geçersiz kılmıştır."},{"n":10,"t":"Kendilerinden öncekilerin sonunun nasıl olduğuna bakmak için yeryüzünü dolaşmazlar mı? ALLAH onları imha etmiştir ve bu inkârcıları da aynı son beklemektedir."},{"n":11,"t":"Çünkü ALLAH gerçeği onaylayanların koruyucusudur. İnkarcıların ise bir koruyucusu yoktur."},{"n":12,"t":"ALLAH gerçeği onaylayıp erdemli davrananları içlerinden ırmaklar akan bahçelere sokar. İnkarcılar ise hayvanlar gibi yiyip yaşamaktadırlar ve sonunda ateşi boylarlar."},{"n":13,"t":"Seni çıkaran ülkenden daha güçlü nice ülkeler vardı ki onları yok ettik, onlara yardım eden olmadı."},{"n":14,"t":"Efendisinden bir delil üzerinde bulunan, işlediği kötülükler kendisine güzel gözüken gibi olur mu? Onlar fantezilerine uymaktadırlar."},{"n":15,"t":"Erdemlilere söz verilen bahçenin örneği şudur: İçinde arı sudan ırmaklar, tadı bozulmayan sütten ırmaklar, içenlere lezzet veren sarhoş edici maddelerden oluşan ırmaklar ve süzme baldan ırmaklar vardır. Onlar için orada her türlü ürün ve Rab’lerinden bir bağışlanma vardır. Bunların durumu, ateşte sürekli kalan ve bağırsaklarını yırtan kaynar bir sudan içirilen kimselerin durumu gibi olur mu?"},{"n":16,"t":"Onlardan bazıları var ki seni dinlerler. Fakat senin yanından çıkınca, kendilerine bilgi verilmiş olanlara, \"Bu, demin ne söyledi?\" diye sorarlar. İşte bunlar, ALLAH’ın kalplerini damgaladığı kimselerdir ve onlar heveslerinin ardına düşmüşlerdir."},{"n":17,"t":"Doğru yolu bulanların ise hidayetini arttırır ve onların erdemli olmalarını sağlar."},{"n":18,"t":"O anın kendilerine ansızın gelmesini mi bekliyorlar? Kuşkusuz onun alametleri gelmiş bulunuyor. Onlara gelip çatınca kendilerine gelen mesajın ne yararı olur?"},{"n":19,"t":"Bil ki, ALLAH’tan başka tanrı yoktur. Kendinin, gerçeği onaylayan erkeklerin ve gerçeği onaylayan kadınların günahları için bağışlanma dile. ALLAH sizin tüm hareketlerinizi ve duracağınız yeri bilir."},{"n":20,"t":"Gerçeği onaylayanlar, \"(Savaşmaya izin veren) bir sure indirilse ya?\" diyorlardı. Ancak hükmü açık bir sure indirilip de içinde savaştan söz edilince, kalplerinde hastalık bulunanların, ölüm korkusuyla bayılan bir kimsenin bakışı gibi sana baktıklarını görürsün. Onlar için uygun olan,"},{"n":21,"t":"İtaat etmek ve güzel konuşmaktır. İş kararlaştırılınca ALLAH’a karşı dürüst olsalar kendileri için iyi olurdu."},{"n":22,"t":"Demek işbaşına gelecek olsanız yeryüzünde bozgunculuk çıkaracak ve akrabalık bağlarını koparacaksınız?"},{"n":23,"t":"İşte, ALLAH’ın lanetlediği, sağırlaştırıp körleştirdiği kimseler bunlardır."},{"n":24,"t":"Neden Kuran’ı araştırıp incelemezler? Yoksa kilitli mi beyinleri?"},{"n":25,"t":"Kendilerine doğru yol belli olduktan sonra geriye dönenleri sapkın ayartmıştır ve onlara ümit vermiştir."},{"n":26,"t":"Zira onlar, ALLAH’ın indirdiğini beğenmeyenlere, \"Bazı konularda size uyuyoruz\" demişlerdi. ALLAH onların komplolarını bilmektedir."},{"n":27,"t":"Denetçiler canlarını alırken nasıl da (pişmanlık içinde) yüzlerine ve sırtlarına vururlar?"},{"n":28,"t":"Çünkü onlar, ALLAH’ı kızdıran şeye uydular, O’nu hoşnut edecek şeyleri beğenmediler ve sonunda yaptıklarını geçersiz hale getirdiler."},{"n":29,"t":"Kalplerinde hastalık bulunanlar, ALLAH’ın, onların kinlerini açığa çıkaracağını bilmezler mi?"},{"n":30,"t":"Dileseydik onları sana gösterirdik, sen de onları yüzlerinden tanırdın. Sen onları sözlerinin eğriliğinden tanıyabilirsin. ALLAH tüm işlediklerinizi bilir."},{"n":31,"t":"Sizden çaba gösterenleri ve güçlüklere karşı direnenleri ortaya çıkarıncaya kadar sizi sınayacağız."},{"n":32,"t":"İnkar edip ALLAH’ın yolundan sapanlar ve kendilerine doğru yol belli olduktan sonra elçiye karşı gelenler ALLAH’a hiçbir zarar veremezler. Aksine, onların yaptıklarını geçersiz kılacaktır."},{"n":33,"t":"Ey gerçeği onaylayanlar, ALLAH’a uyunuz, elçiye uyunuz ve işlerinizi boşa çıkarmayınız."},{"n":34,"t":"İnkar edip ALLAH’ın yolundan saptıktan sonra inkârcılar olarak ölenleri ALLAH bağışlamayacaktır."},{"n":35,"t":"Barışa giden yolda gevşemeyin. Zafer sizindir. ALLAH sizinle beraberdir ve işlediklerinizi ziyan etmeyecektir."},{"n":36,"t":"Dünya hayatı bir oyun ve eğlenceden ibarettir. Gerçeği onaylayıp erdemli davranırsanız, ödüllerinizi verir. O sizden paralarınızı istemiyor."},{"n":37,"t":"Onları sizden isteseydi ve sizi sıkıştırsaydı cimrilik ederdiniz ve sizin gizli kötülüklerinizi açığa çıkarırdı."},{"n":38,"t":"Sizler, ALLAH yolunda harcamaya çağrılıyorsunuz, ancak bir kısmınız cimrilik etmektedir. Kim cimrilik ederse kendisine karşı cimrilik etmiş olur. ALLAH zengindir, siz ise yoksulsunuz. Yüz çevirirseniz, yerinize başka bir topluluk getirir de onlar sizin gibi olmazlar."}]},{"id":48,"name":"Fetih Suresi","verses":[{"n":1,"t":"Biz sana apaçık bir zafer verdik."},{"n":2,"t":"Ki ALLAH, geçmiş ve gelecek günahlarını bağışlasın, sana olan nimetini tamamlasın ve seni doğru yola iletsin."},{"n":3,"t":"Ve ALLAH seni üstün bir zaferle desteklesin."},{"n":4,"t":"O onaylarına onay katmak için gerçeği onaylayanların kalbine huzur indirendir. Göklerin ve yerin orduları ALLAH’ındır. ALLAH Bilendir, Bilgedir."},{"n":5,"t":"Ve gerçeği onaylayan erkeklerle gerçeği onaylayan kadınları, içinden ırmaklar akan bahçelere ebedi kalmak üzere soksun ve onların günahlarını örtsün. Elbette bu, ALLAH’ın katında büyük bir başarıdır."},{"n":6,"t":"Ve ALLAH hakkında kötü düşünceler besleyen ikiyüzlü erkeklerle ikiyüzlü kadınları ve putperest erkeklerle putperest kadınları cezalandırsın. Kötülükleri geri tepecektir. ALLAH onlara gazaplanmış, onları lanetlemiş ve onlar için cehennemi hazırlamıştır. Orası ne kötü bir dönüş yeridir."},{"n":7,"t":"Göklerin ve yerin orduları ALLAH’a aittir. ALLAH Üstündür, Bilgedir."},{"n":8,"t":"Biz seni bir tanık, bir müjdeci ve bir uyarıcı olarak gönderdik."},{"n":9,"t":"Ki siz insanlar, ALLAH’a ve elçisini onaylayasınız ve O’na saygı gösteresiniz, O’nu dinleyesiniz ve sabah akşam O’nu yüceltesiniz."},{"n":10,"t":"Sana bağlılık sözü verenler, ALLAH’a bağlılık sözü vermişlerdir. ALLAH’ın eli onların elleri üzerindedir. Kim sözünü bozarsa, kendi aleyhine bozmuş olur. ALLAH’a verdiği sözü yerine getirene ise büyük bir ödül vereceğiz."},{"n":11,"t":"Araplardan geride kalanlar, \"Paralarımız ve çoluk çocuğumuz bizi alıkoydu, bizim için bağışlanma dile\" diyeceklerdir. Onlar gönüllerinde olmayanı, dilleriyle söylerler. De ki: \"Sizin için bir zarar veya yarar dilerse ALLAH’ın bu dileğine kim engel olabilir?\" Oysa ALLAH tüm yaptıklarınızdan haberdardır."},{"n":12,"t":"Aslında siz, elçinin ve gerçeği onaylayanların ebedi olarak ailelerine dönmeyeceklerini sanmıştınız ve bu düşünce gönlünüze hoş gelmişti. Kötü hayaller kurup durdunuz ve sonunda bayağı bir topluluk oldunuz."},{"n":13,"t":"Kim ALLAH’ı ve elçisini onaylamazsa, biz inkârcılar için bir ateş hazırlamışızdır."},{"n":14,"t":"Göklerin ve yerin yönetimi ALLAH’a aittir. Dilediğini/dileyeni bağışlar ve dilediğini/dileyeni de cezalandırır. ALLAH Bağışlayandır, Rahimdir."},{"n":15,"t":"Savaştan geri kalmış olanlar, siz ganimetleri almak için gittiğinizde, \"Bırakın biz de sizinle gelelim\" diyecekler. Onlar ALLAH’ın sözünü değiştirmek istiyorlar. De ki: \"Siz bizi izlemeyeceksiniz. Bu ALLAH’ın önceden almış olduğu karardır.\" Bunun üzerine onlar, \"Siz aslında bizi çekemiyorsunuz\" diyeceklerdir. Doğrusu, onlar pek az söz anlarlar."},{"n":16,"t":"Araplardan geri kalanlara De ki: \"Siz çok güçlü bir topluluğa karşı çağrılacaksınız. Onlar teslim olana kadar onlarla savaşacaksınız. İtaat ederseniz ALLAH size güzel bir ödül verir. Daha önce yüz çevirdiğiniz gibi yüz çevirirseniz sizi acı bir azap ile cezalandırır."},{"n":17,"t":"Köre bir güçlük yoktur, felçliye bir güçlük yoktur, hastaya da bir güçlük yoktur. Kim ALLAH’a ve elçisine uyarsa, O onu içinden ırmaklar akan bahçelere sokar. Kim yüz çevirirse onu da acı bir biçimde cezalandırır."},{"n":18,"t":"ALLAH, ağacın altında sana bağlılık sözü veren gerçeği onaylayanlardan hoşnut olmuştur. Onların kalplerinde olanı bilmiş, onlara huzur indirmiş ve onları yakın bir zaferle ödüllendirmiştir."},{"n":19,"t":"Ek olarak, birçok ganimet ele geçirdiler. ALLAH Üstündür, Bilgedir."},{"n":20,"t":"ALLAH sizin birçok ganimet ele geçireceğinizi size söz vermiş bulunuyor. Size bunu çabucak verdi ve halkın ellerini sizden çekti. Böylece bunu gerçeği onaylayanlar için bir delil kıldı ve sizi dosdoğru yola iletti."},{"n":21,"t":"Güç yetiremediğiniz diğer gruba gelince, onları ALLAH kuşatmıştır. ALLAH elbette her şeye gücü yetendir."},{"n":22,"t":"İnkarcılar sizinle savaşsalardı dönüp kaçarlardı. Sonra ne bir sahip, ne de bir yardımcı bulabilirlerdi."},{"n":23,"t":"Öteden beri uygulanan ALLAH’ın sünneti (sistemi) budur. ALLAH’ın sünnetinde bir değişme bulamazsın."},{"n":24,"t":"Sizi onlara karşı üstün getirdikten sonra Mekke’nin göbeğinde onların ellerini yakanızdan sizin de ellerinizi onların yakasından çeken O’dur. ALLAH yaptıklarınızı görendir."},{"n":25,"t":"Onlar inkâr edenlerdir, sizi Sınırlanmış Mescitten ve hediyeleri yerine ulaşmaktan alıkoyanlardır. Kendilerini tanımadığınız için inciteceğiniz gerçeği onaylayan erkekler ve gerçeği onaylayan kadınlar bulunmasaydı ve böylece onlardan dolayı bilmeden kendinizi üzmeniz ihtimali olmasaydı… Böylece ALLAH dileyeni rahmetine sokar. Birbirleriyle karışmış halde olmasalardı onlardan inkâr edenleri acı bir azapla cezalandırırdık."},{"n":26,"t":"İnkar edenler, gönüllerindeki öfke ve bağnazlığı, cahiliyye döneminin fanatizmini ateşlediklerinde, ALLAH elçisinin ve gerçeği onaylayanların üzerine huzurunu indirmiş ve onların erdemlilik sözünü tutmalarını sağlamıştı. Onlar buna tam yaraşan ve hak eden kimselerdi. ALLAH her şeyi bilendir."},{"n":27,"t":"ALLAH elçisinin rüyasını gerçekleştirdi: \"ALLAH dilerse, güvenlik içinde, başlarınızı (saçlarınızı) traş etmiş ve kısaltmış olarak Sınırlanmış Mescide gireceksiniz. Bir korku duymayacaksınız. Sizin bilmediklerinizi bildiğinden, size bundan önce acil bir zafer hazırlamıştır.\""},{"n":28,"t":"O, tüm dinlere üstün kılmak üzere elçisini hidayetle ve gerçek dinle gönderendir. Tanık olarak ALLAH yeterlidir."},{"n":29,"t":"ALLAH’ın elçisi Muhammed ve beraberinde bulunanlar inkârcılara karşı sert ve kendi aralarında ise merhametlidirler. Onları, eğilip secde ederek ALLAH’tan lütuf ve hoşnutluk dilerken görürsün. Yüzlerinde secdelerin izleri vardır. Bu, onların Tevrat’taki nitelikleridir. İncil’deki nitelikleri ise, filizini çıkarıp güçlendirmiş ve kalınlaşıp gövdesi üzerine dikilerek ekincileri sevindiren bitki gibidir. O, onlarla inkârcıları öfkelendirir. ALLAH, onlardan gerçeği onaylayıp erdemli davrananlara bağışlanma ve büyük bir ödül söz vermiştir."}]},{"id":49,"name":"Hucurat Suresi","verses":[{"n":1,"t":"Ey gerçeği onaylayanlar, ALLAH’ın ve elçisinin önüne geçmeyiniz. ALLAH’ı sayınız. ALLAH İşitir, Bilir."},{"n":2,"t":"Ey gerçeği onaylayanlar, sesinizi peygamberin sesinin üstüne çıkarmayın ve birbirinize bağırdığınız gibi ona bağırmayın. Yoksa siz görmeden işleriniz boşa gider."},{"n":3,"t":"Seslerini ALLAH’ın elçisinin huzurunda kısanlar öyle kimselerdir ki, ALLAH onların kalplerini erdemlilik için uygun hale getirmiştir. Onlar için bağışlanma ve büyük bir ödül vardır."},{"n":4,"t":"Odaların/duvarların ardından sana seslenenlerin çoğu düşüncesiz kimselerdir."},{"n":5,"t":"Sen yanlarına çıkıncaya kadar sabretselerdi kendileri için daha iyi olurdu. ALLAH Bağışlayandır, Rahimdir."},{"n":6,"t":"Ey gerçeği onaylayanlar, kötü huylara sahip birisi size bir haber getirirse onu araştırınız. Yoksa bilmeden bir topluluğa karşı haksızlık edersiniz ve daha sonra yaptığınızdan pişmanlık duyarsınız."},{"n":7,"t":"Bilesiniz ki ALLAH’ın elçisi aranızdadır. İşlerin çoğunda sizlere uysaydı sıkıntıya düşerdiniz. Fakat, ALLAH gerçeği onaylamayı size sevdirdi ve onu gönüllerinizde süsledi; inkârı, kötülüğü ve isyanı ise size çirkin gösterdi. İşte doğruyu izleyenler bunlardır."},{"n":8,"t":"ALLAH’ın lütfu ve nimeti böyledir. ALLAH Bilendir, Bilgedir."},{"n":9,"t":"Gerçeği onaylayanlardan iki grup birbirleriyle savaşırlarsa onların arasını bulun. Onlardan biri ötekine saldırırsa, ALLAH’ın buyruğuna dönünceye kadar saldırgan grupla savaşın. Dönerse onların arasını tarafsızca düzeltin ve adaletli davranın. ALLAH adaletli davrananları sever."},{"n":10,"t":"Gerçeği onaylayanlar sadece kardeştirler. Kardeşlerinizin arasını düzeltin. ALLAH’ı sayın ki merhamet edilesiniz."},{"n":11,"t":"Ey gerçeği onaylayanlar, bir topluluk diğer bir topluluğu aşağılamasın, belki onlar kendilerinden daha iyidirler. Kadınlar da kadınları aşağılamasınlar, belki onlar kendilerinden daha iyidirler. Birbirinizi ayıplamayın ve birbirinizi, küçük düşürücü kelimelerle çağırmayın. Gerçeği onayladıktan sonra yoldan çıkmak ne kötü bir isimdir/niteliktir. Kim tövbe etmezse onlar zalimlerdir."},{"n":12,"t":"Ey gerçeği onaylayanlar, zandan tümüyle sakının, çünkü zannın bir kısmı günahtır. Birbirinizin gizli şeylerini araştırmayın ve birbirinizi arkadan çekiştirmeyin. Ölü kardeşinizin etini yemekten hoşlanır mısınız? Elbette ondan iğrenirsiniz. ALLAH’ı dinleyin. ALLAH tövbeleri kabul edendir, Rahimdir."},{"n":13,"t":"Ey halk, sizi bir erkek ile bir dişiden yarattık ve birbirinizle tanışmanız için sizi ırklara ve boylara ayırdık. ALLAH yanında sizin en değerliniz en erdemli olanınızdır. ALLAH Bilendir, Haberdardır."},{"n":14,"t":"Araplar \"Gerçeği onayladık\" dediler. De ki: \"Siz gerçeği onaylamadınız, fakat gerçeği onaylamak kalbinize girinceye kadar, ’teslim olduk’ deyin. ALLAH’a ve elçisine uyarsanız yaptıklarınızdan hiçbir şeyi eksiltmez. ALLAH Bağışlayandır, Rahimdir."},{"n":15,"t":"Gerçeği onaylayanlar onlardır ki, ALLAH’ı ve elçisini onayladılar, sonra kuşku beslemediler ve ALLAH yolunda paraları ve canlarıyla savaşım verdiler. Onlar doğru olanlardır."},{"n":16,"t":"De ki: \"ALLAH’a dininizi mi öğretiyorsunuz? ALLAH göklerde ve yerde olanı bilir. ALLAH her şeyi bilendir.\""},{"n":17,"t":"Müslüman (teslim) oldular diye seni minnet altında bırakmak istiyorlar. De ki: \"Müslümanlığınızı başıma kakmayın. Aslında, sizi gerçeği onaylamaya ulaştırdığı için ALLAH sizi kendisine borçlu görür, eğer doğru kimselerseniz.\""},{"n":18,"t":"ALLAH göklerin ve yerin gizemlerini bilir. ALLAH yaptıklarınızı görendir."}]},{"id":50,"name":"Kaf Suresi","verses":[{"n":1,"t":"Q, şanlı Kuran’a andolsun."},{"n":2,"t":"İçlerinden bir uyarıcının kendilerine gelmesini tuhaf karşıladılar! Kafirler, \"Bu tuhaf bir şey\" dediler,"},{"n":3,"t":"\"Ölüp toprak olduktan sonra mı? Bu imkansız bir dönüştür.\""},{"n":4,"t":"Yeryüzünün onlardan kimi alıp götürdüğünü bilmişizdir. Yanımızda koruyan bir kayıt vardır."},{"n":5,"t":"Oysa onlar gerçek kendilerine geldiği zaman onu yalanladılar; kararsızlık içindedirler."},{"n":6,"t":"Üstlerindeki göğe bakmadılar mı, onu hiçbir çatlağı olmadan nasıl yaptık ve onu nasıl süsledik?"},{"n":7,"t":"Yeri ise yaydık, içine dağlar yerleştirdik ve içinde her çeşit güzel bitkiler yetiştirdik."},{"n":8,"t":"Her yönelen kul için bu bir aydınlatma ve mesajdır."},{"n":9,"t":"Ve gökten kutlu bir su indirerek onunla bahçeler ve biçilecek taneler bitirdik."},{"n":10,"t":"Küme küme tomurcuklara sahip yüksek hurma ağaçları yetiştirdik."},{"n":11,"t":"Kullara bir besin olarak. Onunla bölgeyi dirilttik. Çıkış (diriliş) de böyledir."},{"n":12,"t":"Onlardan önce Nuh’un halkı, Res’liler ve Semud da yalanlamıştı."},{"n":13,"t":"Ad, Firavun ve Lut’un kardeşleri…"},{"n":14,"t":"Eyke’liler ve Tubba’ halkı da… Hepsi elçileri yalanladılar. Bunun üzerine tehdidim gerçekleşti."},{"n":15,"t":"İlk yaratılıştan yorulduk mu ki? Doğrusu onlar yeni bir yaratılıştan kuşku içindedirler."},{"n":16,"t":"İnsanı biz yarattık ve onun kendi kendine neyi fısıldadığını iyi biliriz. Biz ona şahdamarından daha yakınız."},{"n":17,"t":"Sağında ve solunda iki alıcı melek oturmuş kaydetmektedirler."},{"n":18,"t":"Yanında gözetleyen tanıklar olmaksızın ağzından bir söz çıkmaz."},{"n":19,"t":"Sonunda ölüm sarhoşluğu gerçekten gelmiştir; işte senin kendisinden kaçıp durduğun şey budur."},{"n":20,"t":"Boruya üflenmiştir. Bu, söz verilen gündür."},{"n":21,"t":"Her can yanında bir sürücü ve bir tanık ile gelir."},{"n":22,"t":"Sen tümüyle bundan gafildin. Şimdi biz örtünü kaldırdık; bugün gözün çelik gibi keskindir."},{"n":23,"t":"Yanındaki arkadaşı, \"İşte yanımdaki hazır\" der."},{"n":24,"t":"Haydi ikiniz atın cehenneme her inatçı kafiri,"},{"n":25,"t":"İyiliği engelleyen, azgın, kuşkucuyu…"},{"n":26,"t":"O ki ALLAH ile birlikte başka tanrı edindi. Onu o çetin cezanın içine atın."},{"n":27,"t":"Arkadaşı, \"Efendim, ben onu azdırmadım; fakat o kendisi derin bir sapıklık içindeydi\" der."},{"n":28,"t":"O da der ki, \"Huzurumda çekişmeyin. Size daha önceden uyarı göndermiştim.\""},{"n":29,"t":"\"Benim katımda söz değiştirilmez ve ben kullara asla haksızlık etmem.\""},{"n":30,"t":"O gün cehenneme, \"Doldun mu?\" deriz. O, \"Daha yok mu?\" der."},{"n":31,"t":"Erdemlilere ise bahçe yaklaştırılır, uzak değildir."},{"n":32,"t":"Bu, size söz verilendir. Her yönelen ve her koruyana,"},{"n":33,"t":"Onlar yalnız başınayken bile Rahman’ı sayarlar ve içtenlikle gelirler."},{"n":34,"t":"Oraya esenlikle girin; bu, sonsuz yaşama günüdür."},{"n":35,"t":"Diledikleri her şeyi elde ederler ve hatta katımızda fazlası da vardır."},{"n":36,"t":"Onlardan önce, onlardan daha güçlü nice nesilleri yok etmiştik. Ülke ülke dolaşmışlardı; kurtuluşu var mı?"},{"n":37,"t":"Bunda, zeka sahibi olan yahut tanık olarak kulak veren herkes için bir mesaj vardır."},{"n":38,"t":"Gökleri, yeri ve aralarındakileri altı günde yarattık. Hiçbir yorgunluk da duymadık."},{"n":39,"t":"Onların söylediklerine sabret ve güneşin doğuşundan ve batışından önce Efendini överek yücelt."},{"n":40,"t":"Geceleyin O’nu yücelt ve secdelerin ardından da…"},{"n":41,"t":"Çağırıcının yakın bir yerden çağıracağı güne kulak ver."},{"n":42,"t":"O gün o çığlığı kesinlikle duyarlar; bu, çıkış günüdür."},{"n":43,"t":"Biz diriltiriz, öldürürüz ve dönüş de bizedir."},{"n":44,"t":"O gün yer onlardan dolayı yarılıverir. Bu, bizim için kolay bir toparlamadır."},{"n":45,"t":"Biz onların ne konuştuğunu iyi biliyoruz. Sen onların üzerinde bir zorba değilsin. Uyarılarımdan korkanlara sen bu Kuran ile öğüt ver."}]},{"id":51,"name":"Zariyat Suresi","verses":[{"n":1,"t":"Savrulan atomlara,"},{"n":2,"t":"Yük yüklenenlere,"},{"n":3,"t":"Kolayca akıp gidenlere,"},{"n":4,"t":"Ve işi bölümlere ayıranlara andolsun ki"},{"n":5,"t":"Size söz verilen kuşkusuz bir gerçektir."},{"n":6,"t":"Yargılama kesinlikle gerçekleşecektir."},{"n":7,"t":"Yörüngelere sahip göğe andolsun ki"},{"n":8,"t":"Siz ihtilaf içindesiniz."},{"n":9,"t":"Çevrilen, ondan çevrilir."},{"n":10,"t":"Kahrolsun palavracılar,"},{"n":11,"t":"Ki şaşkınlıkları içinde umursamıyorlar."},{"n":12,"t":"Yargı Gününün zamanını sorarlar."},{"n":13,"t":"O gün onlar ateşe sunulacaklardır."},{"n":14,"t":"Cezanızı tadın, meydan okumakta olduğunuz şey budur işte!"},{"n":15,"t":"Erdemliler bahçelerdedir, pınar başlarındadır."},{"n":16,"t":"Rab’lerinin kendilerine verdiğini alırlar. Çünkü onlar bundan önce güzel davranıyorlardı."},{"n":17,"t":"Geceleri az uyurlardı."},{"n":18,"t":"Seherlerde/gönülden bağışlanma dilerlerdi."},{"n":19,"t":"Paralarında, isteyenler ve yoksullar için bir pay vardı."},{"n":20,"t":"Kesin gerçeği onaylayanlar için yerde ayetler (işaret ve deliller) vardır."},{"n":21,"t":"Kendi içinizde de… Görmez misiniz?"},{"n":22,"t":"Gökte rızkınız ve size söz verilenler vardır."},{"n":23,"t":"Göğün ve yerin Efendisine andolsun ki sizin konuşmanız nasıl bir gerçek ise, bu da öylece bir gerçektir."},{"n":24,"t":"İbrahim’in ağırlanan konuklarının haberini aldın mı?"},{"n":25,"t":"Onun huzuruna girmişlerdi ve \"Selam (barış)\" demişlerdi. O da, \"Selam size, yabancılar!\" demişti."},{"n":26,"t":"Ailesine yöneldi ve sonra semiz bir buzağı ile geldi."},{"n":27,"t":"Onu onların önüne sürüp, \"Yemez misiniz?\" dedi."},{"n":28,"t":"Onlardan bir korku duydu. Bunun üzerine onlar, \"Korkma\" dediler ve ona bilgin bir oğul müjdelediler."},{"n":29,"t":"Karısı hayret içinde, (hayretten) yüzüne vurarak, \"Kısır bir yaşlı kadın!\" dedi."},{"n":30,"t":"Dediler ki, \"Efendin böyle söylemiştir. O Bilgedir, Bilendir.\""},{"n":31,"t":"(İbrahim:) \"Ey elçiler asıl göreviniz nedir?\" dedi."},{"n":32,"t":"Dediler ki, \"Biz suçlu bir topluluğa gönderildik.\""},{"n":33,"t":"\"Üzerlerine balçıktan taşlar göndermek için…\""},{"n":34,"t":"\"Efendin tarafından taşkınlar için işaretlenmiş olarak.\""},{"n":35,"t":"Sonra, orada gerçeği onaylayanlardan kim varsa çıkardık."},{"n":36,"t":"Zaten orada bir evin dışında hiçbir Müslüman bulmadık."},{"n":37,"t":"Acı azaptan korkacaklar için orada bir ders bıraktık."},{"n":38,"t":"Musa’da da (bir ders vardır). Onu Firavuna apaçık bir delil ile göndermiştik."},{"n":39,"t":"Erkanıyla birlikte yüz çevirdi ve \"Ya bir büyücüdür, ya da bir deli\" dedi."},{"n":40,"t":"Onu ve askerlerini yakalayıp denize attık. Bu sonucu haketmişti."},{"n":41,"t":"Ad halkında da (bir ders vardır). Üzerlerine korkunç bir rüzgar gönderdik."},{"n":42,"t":"Rastgeldiği her şeyi toz toprağa çeviriyordu."},{"n":43,"t":"Semud’da da (bir ders vardır). Onlara, \"Belli bir süreye kadar keyfinize bakın\" denmişti."},{"n":44,"t":"Rab’lerinin emrine karşı geldiler. Bunun üzerine bakınırlarken onları bir yıldırım çarptı."},{"n":45,"t":"Ne kalkabildiler, ne de yardım görebildiler."},{"n":46,"t":"Daha önce de Nuh halkını… Onlar yoldan çıkmış bir topluluktu."},{"n":47,"t":"Göğü gücümüzle biz kurduk ve onu biz genişletmekteyiz."},{"n":48,"t":"Yeri biz döşedik; ne güzel döşeyiciyiz."},{"n":49,"t":"Öğüt almanız için de her şeyi çiftler halinde yarattık."},{"n":50,"t":"Öyleyse ALLAH’a kaçınız. Ben, O’nun tarafından size gönderilmiş bir uyarıcıyım."},{"n":51,"t":"ALLAH ile birlikte başka tanrılar edinmeyin. Ben O’nun tarafından size gönderilmiş bir uyarıcıyım."},{"n":52,"t":"İşte böyle, onlardan öncekilere her ne zaman bir elçi geldiyse, \"Bu, bir büyücüdür\" yahut \"Bu bir delidir\" derlerdi."},{"n":53,"t":"Bunu (söylemeyi) birbirlerine öğütlediler mi? Doğrusu, onlar sınırı aşan bir topluluktur."},{"n":54,"t":"Onlardan yüz çevir; sen kınanacak değilsin."},{"n":55,"t":"Hatırlat, çünkü hatırlatmak gerçeği onaylayanlara yarar sağlar."},{"n":56,"t":"Cinleri ve insanları ancak bana hizmet etmeleri için yarattım."},{"n":57,"t":"Onlardan ne bir rızık istiyorum, ne de beni beslemelerini."},{"n":58,"t":"Kuşkusuz Rızık veren, Kuvvet sahibi ve Güçlü olan ancak ALLAH’tır."},{"n":59,"t":"Elbette, bu zulmedenlerin de (geçmiş) yoldaşlarının payına benzer bir payları vardır."},{"n":60,"t":"Kendilerine söz verilen günden dolayı vay haline şu inkârcıların!"}]},{"id":52,"name":"Tur Suresi","verses":[{"n":1,"t":"Andolsun Tur’a,"},{"n":2,"t":"Kaydedilmiş kitaba,"},{"n":3,"t":"Ki parşömen üzerinde yayımlanmış."},{"n":4,"t":"Sık sık ziyaret edilen Ev’e,"},{"n":5,"t":"Yükseltilmiş tavana,"},{"n":6,"t":"Ve kaynatılmış denize…"},{"n":7,"t":"Efendinin cezalandırması kesinlikle gerçekleşecektir."},{"n":8,"t":"Onu engelleyecek hiçbir güç yoktur."},{"n":9,"t":"O gün gök sallanıp sarsılacak,"},{"n":10,"t":"Dağlar yürütülüp silinecek,"},{"n":11,"t":"Yalanlayanların vay haline o gün!"},{"n":12,"t":"Onlar ki bir bataklıkta oynamaktadırlar."},{"n":13,"t":"Cehennem ateşine itildikleri gün:"},{"n":14,"t":"İşte, yalanlamakta olduğunuz Ateş budur."},{"n":15,"t":"Bu bir büyü müdür, yoksa siz mi görmüyorsunuz?"},{"n":16,"t":"Orda yanın. İster sabredin, ister sabretmeyin sizin için değişmeyecektir. Yaptığınızın karşılığını görmektesiniz."},{"n":17,"t":"Erdemliler bahçeler ve nimetler içindedir."},{"n":18,"t":"Rab’lerinin kendilerine vermiş olduğu şeylerden zevk duyarlar. Rab’leri onları cehennem azabından korumuştur."},{"n":19,"t":"Yapmış olduklarınıza karşılık afiyetle yiyin, için."},{"n":20,"t":"Dizilmiş koltuklara yaslanmışlardır ve onları güzel eşlerle eşlendirmişizdir."},{"n":21,"t":"Soyları tarafından izlenen gerçeği onaylayanlara soylarını da katarız ve onların yaptıklarından hiçbir şeyi eksiltmeyiz. Herkes kazanmış olduğu şeylerin bir ipoteğidir."},{"n":22,"t":"Onlara canlarının istediği meyveden ve etten bol bol veririz."},{"n":23,"t":"Orada birbirlerinden kadeh kapışırlar, orda ne bir saçmalama, ne de bir günaha girme vardır."},{"n":24,"t":"Çevrelerinde, inciler gibi korunmuş kendilerine ait hizmetkarlar (servis için) dolaşıp durur."},{"n":25,"t":"Birbirlerine dönüp geçmişi anarlar:"},{"n":26,"t":"\"Daha önce halkımızın arasında çekinirdik\" derler,"},{"n":27,"t":"\"ALLAH bize iyilik etti de bizi içe işleyen azaptan korudu.\""},{"n":28,"t":"\"Biz daha önce O’na yalvarırdık; O, İyilik edendir, Rahimdir.\""},{"n":29,"t":"Sen öğüt ver. Efendinin sana olan iyiliği sayesinde sen ne bir kahinsin, ne de deli."},{"n":30,"t":"Yoksa, \"O bir şairdir, onun ölmesini bekliyoruz\" mu diyorlar?"},{"n":31,"t":"De ki: \"Bekleyedurun; ben de sizinle birlikte beklemekteyim.\""},{"n":32,"t":"Bunları rüyalarının etkisiyle mi söylüyorlar, yoksa onlar haddi aşan bir topluluk mudur?"},{"n":33,"t":"Yoksa, \"Onu kendi uydurdu\" mu diyorlar? Hayır, onlar gerçeği onaylamazlar."},{"n":34,"t":"Doğru sözlüler iseler bunun benzeri bir hadis getirsinler."},{"n":35,"t":"Onlar yokluktan mı yaratıldılar? Yoksa yaratanlar kendileri mi?"},{"n":36,"t":"Gökleri ve yeri onlar mı yarattılar? Doğrusu, onlar gerçeği kuşkusuz bir biçimde onaylamazlar."},{"n":37,"t":"Yoksa Efendinin hazineleri onların mı yanındadır? Onlar mı kontrol etmektedirler?"},{"n":38,"t":"Yoksa üzerine çıkıp (vahyi) dinledikleri bir merdivenleri mi var? Öyleyse dinleyicileri açık bir delil getirsin."},{"n":39,"t":"Yoksa kızlar O’na, oğullar size mi?"},{"n":40,"t":"Yoksa sen onlardan bir ücret istiyorsun da bu onlara ağır bir borç mu yüklüyor?"},{"n":41,"t":"Yoksa gizemlerin bilgisine mi sahipler ve onu kendileri mi yazıyorlar?"},{"n":42,"t":"Yoksa bir planı mı uygulamak istiyorlar? Halbuki kafirlerin kendileri bir plana mahkûm edilmiştir."},{"n":43,"t":"Yoksa ALLAH’tan başka tanrıları mı vardır? ALLAH onların ortak koştuklarından yücedir."},{"n":44,"t":"Gökten bir parçanın düştüğünü görseler, \"Bulut kümesidir!\" derler."},{"n":45,"t":"Çarpılacakları günlerine kavuşuncaya kadar onları bırak."},{"n":46,"t":"O gün, planları kendilerini hiçbir şeyden korumayacak ve yardım da görmeyeceklerdir."},{"n":47,"t":"Zulmedenlere bunun dışında bir ceza daha vardır, fakat çokları bilmezler."},{"n":48,"t":"Efendinin hükmü gerçekleşinceye kadar sen sabret. Gözlerimiz önündesin ve kalktığın zaman Efendini överek yücelt."},{"n":49,"t":"Geceleyin ve yıldızlar kaybolurken O’nu yücelt."}]},{"id":53,"name":"Necm Suresi","verses":[{"n":1,"t":"Düşerken yıldızlara andolsun."},{"n":2,"t":"Arkadaşınız (Muhammed) ne sapmıştır, ne de azmıştır."},{"n":3,"t":"Ne de fanteziden konuşmaktadır."},{"n":4,"t":"O (Kuran) ancak ve ancak bildirilen bir vahiydir."},{"n":5,"t":"Onu, büyük güce sahip olan öğretmiştir."},{"n":6,"t":"Üstün otoritenin sahibi göründü,"},{"n":7,"t":"En yüksek ufukta."},{"n":8,"t":"Sonra inip yaklaştı."},{"n":9,"t":"Mesafe iki yay kadar veya daha yakın oldu."},{"n":10,"t":"Ve sonra kuluna ne bildirilecekse onu vahyetti."},{"n":11,"t":"Gördüğünü gönlü yalanlamadı."},{"n":12,"t":"Onun gördüğü hakkında kendisiyle tartışıyor musunuz?"},{"n":13,"t":"Onu bir kez daha görmüştü."},{"n":14,"t":"En son noktada."},{"n":15,"t":"Ki yanında barınılacak bahçe vardır."},{"n":16,"t":"Tüm bölge olağanüstü biçimde kuşatılmıştı."},{"n":17,"t":"Göz şaşmadı, sınırı da aşmadı."},{"n":18,"t":"Efendisinin büyük ayetlerini gördü."},{"n":19,"t":"Gördünüz mü (dişi putlarınız olan) Lat ve Uzza’yı?"},{"n":20,"t":"Ve üçüncüleri olan Menat’ı?"},{"n":21,"t":"Erkekler sizin de dişiler O’nun mu?"},{"n":22,"t":"Ne de insafsız bir paylaşma!"},{"n":23,"t":"Onlar, sizin ve atalarınızın taktığı isimlerden başka bir şey değildir ve ALLAH onlar için hiçbir delil indirmemiştir. Kendilerine, Rab’lerinden bir yol gösterici geldiği halde, sadece kuruntuları ve fantezileri izliyorlar."},{"n":24,"t":"İnsan her umduğuna kavuşacak mıdır?"},{"n":25,"t":"Son da ilk de ALLAH’ındır."},{"n":26,"t":"Göklerdeki meleklerin bile şefaati bir yarar sağlamaz. Ancak ALLAH’ın dilediği kimse için izin vermesinden ve O’nun rızasına uygun olduktan sonra…"},{"n":27,"t":"Ahiret gerçeğini onaylamayanlar melekleri dişi olarak nitelendirmektedirler."},{"n":28,"t":"Onların bu konuda bir bilgileri yoktur, sadece sanıları izlemektedirler ve sanılar gerçeğin yerini tutmaz."},{"n":29,"t":"Mesajımızdan yüz çeviren ve dünya hayatından başkasını arzulamayan kimseyi önemseme."},{"n":30,"t":"İşte onların ulaştıkları bilgilerinin düzeyi budur. Elbette, Efendin yolundan sapanı iyi bilir, doğru yolda olanı da iyi bilir."},{"n":31,"t":"Göklerde ve yerde ne varsa ALLAH’ındır. Kötülük işleyenleri yaptıklarından dolayı cezalandıracaktır ve güzel davrananları da ödüllendirecektir."},{"n":32,"t":"Onlar, büyük günahlardan ve kötülüklerden kaçınırlar, yalnız küçük suçlar işlerler. Efendinin bağışlaması engindir. Sizi topraktan yaratırken ve annelerinizin karınlarında cenin (fetus) durumundayken sizi iyi bilmektedir. Öyleyse kendinizi (övüp) temize çıkarmayın. O, erdemlileri iyi bilir."},{"n":33,"t":"Gördün mü o yüz çevireni?"},{"n":34,"t":"Ender olarak ve pek az verdi."},{"n":35,"t":"Gizemlerin bilgisine mi sahiptir ki (geleceği) görüyor?"},{"n":36,"t":"Ona Musa’nın öğretisi hakkında bilgi verilmedi mi?"},{"n":37,"t":"Ve sözünü gerçekleştiren İbrahim’in?:"},{"n":38,"t":"Ki hiçbir kimse bir başkasının günah yükünü taşımaz,"},{"n":39,"t":"İnsan için ancak kendi çalışması vardır."},{"n":40,"t":"Ve onun çalışması da yakında görülecektir."},{"n":41,"t":"Sonra kendisine ödülü tam olarak verilecektir."},{"n":42,"t":"Son varış Efendinedir."},{"n":43,"t":"O’dur seni güldüren ve ağlatan."},{"n":44,"t":"O’dur öldüren ve dirilten."},{"n":45,"t":"O’dur iki çifti yaratan; erkeği ve dişiyi…"},{"n":46,"t":"Atıldığı zaman bir damlacık meniden."},{"n":47,"t":"O’na aittir tekrar yaratmak."},{"n":48,"t":"O’dur Zengin eden, yoksul yapan."},{"n":49,"t":"O’dur Şira galaksisinin Rabbi."},{"n":50,"t":"O’dur helak eden eski Ad halkını,"},{"n":51,"t":"Semud’u da bırakmadı,"},{"n":52,"t":"Ve ondan önce Nuh’un halkını da; onlar çok zalim ve çok azgın kimselerdi."},{"n":53,"t":"Yıkılıp batırılmış olanlar (Sodom ve Gomora), en bayağılardı."},{"n":54,"t":"Onları örten örttü."},{"n":55,"t":"O halde Efendinin hangi nimetlerinden kuşkulanırsın?"},{"n":56,"t":"Bu, eski uyarıcılardan bir uyarıcıdır."},{"n":57,"t":"Kaçınılmaz olan yaklaşmıştır."},{"n":58,"t":"ALLAH’tan başkası onu kaldıramaz."},{"n":59,"t":"Bu sözü mü tuhaf karşılıyorsunuz?"},{"n":60,"t":"Gülüyorsunuz da ağlamıyorsunuz?"},{"n":61,"t":"Ve aylak aylak oyalanıyorsunuz?"},{"n":62,"t":"Haydi ALLAH’a secde edin, hizmet edin."}]},{"id":54,"name":"Kamer Suresi","verses":[{"n":1,"t":"O an yaklaştı ve ay yarıldı."},{"n":2,"t":"Bir mucize görseler yüz çevirirler ve, \"Süregelen bir büyüdür\" derler."},{"n":3,"t":"Yalanladılar; fantezilerine ve her statükoya uydular."},{"n":4,"t":"Oysa, kötülüklerini engelleyecek uyarılar dolu haberler kendilerine gelmiş bulunuyor."},{"n":5,"t":"Bu üstün bir hikmettir; ancak uyarılar yarar sağlamıyor."},{"n":6,"t":"Onlara aldırma; çağırıcının, görülmemiş ve tanınmamış bir şeye çağıracağı gün,"},{"n":7,"t":"Gözleri zillet içinde mezarlardan çıkarlar; tıpkı saçılmış çekirgeler gibi…"},{"n":8,"t":"Çağırıcıya doğru koşarlarken, inkârcılar, \"Bu zorlu bir gündür\" derler."},{"n":9,"t":"Onlardan önce de Nuh’un halkı yalanlamıştı. Kulumuzu yalanlayıp, \"Delidir\" dediler. Nitekim o engellendi."},{"n":10,"t":"Efendini çağırdı, \"Ben yenildim; bana yardım et.\""},{"n":11,"t":"Bunun üzerine göğün kapılarını boşalan sularla açtık."},{"n":12,"t":"Yerden de pınarlar fışkırttık. Nihayet sular, daha önce belirlenmiş seviyeye ulaştılar."},{"n":13,"t":"Onu ağaç lifleri ile (bağlanmış) kütükler üzerinde taşıdık."},{"n":14,"t":"Reddedilmiş olan kişiye bir ödül olarak gözetimimiz altında akıp gidiyordu."},{"n":15,"t":"Bunu bir ders olarak bıraktık. Öğüt alan yok mudur?"},{"n":16,"t":"Cezalandırmam ve uyarılarım nasılmış!"},{"n":17,"t":"Kuran’ı mesaj için kolaylaştırdık; öğüt alan yok mudur?"},{"n":18,"t":"Ad da yalanladı. Cezalandırmam ve uyarılarım nasılmış!"},{"n":19,"t":"Uğursuzluk üstüne uğursuzluğa sahip bir günde üzerlerine vahşi bir rüzgar gönderdik."},{"n":20,"t":"İnsanları, sanki köklerinden koparılmış hurma kütükleriymiş gibi yıkıyordu."},{"n":21,"t":"Cezalandırmam ve uyarılarım nasılmış!"},{"n":22,"t":"Kuran’ı mesaj için kolaylaştırdık; öğüt alan yok mudur?"},{"n":23,"t":"Semud da uyarıları yalanladı."},{"n":24,"t":"Dediler ki, \"Bizden bir insana mı uyalım? O zaman biz sapar ve cehenneme gireriz.\""},{"n":25,"t":"\"Mesaj aramızdan ona mı verildi? O, yalancı küstahın biridir.\""},{"n":26,"t":"Yalancı küstahın kim olduğunu yarın öğreneceklerdir."},{"n":27,"t":"Deveyi bir sınav olarak göndereceğiz. Onları gözetle, sabırlı ol."},{"n":28,"t":"Onlara, suyun (deveyle) aralarında paylaşılacağını bildir. Her içim sırayla sunulacaktır."},{"n":29,"t":"Bir arkadaşlarını çağırdılar, o da çekip (deveyi) kesti."},{"n":30,"t":"Cezalandırmam ve uyarılarım nasılmış!"},{"n":31,"t":"Üzerlerine bir tek patlama gönderdik ve onlar ağılcının topladığı saman yığınına döndüler."},{"n":32,"t":"Kuran’ı mesaj için kolaylaştırdık; öğüt alan yok mudur?"},{"n":33,"t":"Lut halkı da uyarıları yalanlamıştı."},{"n":34,"t":"Üzerlerine taş yağdıran bir fırtına gönderdik, yalnız Lut’un ailesini seher vakti kurtardık."},{"n":35,"t":"Katımızdan bir iyilik olarak. Şükredeni işte böyle ödüllendiririz."},{"n":36,"t":"Onları bu yakalayışımıza karşı uyarmıştı; ancak onlar uyarıları kuşkuyla karşıladılar."},{"n":37,"t":"Onun konuklarına göz diktiler, biz de onları kör ettik. Azabımı ve uyarılarımı tadın bakalım."},{"n":38,"t":"Ertesi gün, yaman bir azap sabahlarını kutladı."},{"n":39,"t":"Azabımı ve uyarılarımı tadın bakalım."},{"n":40,"t":"Kuran’ı mesaj için kolaylaştırdık; öğüt alan yok mudur?"},{"n":41,"t":"Firavunun erkanına da uyarıcılar gitmişti."},{"n":42,"t":"Tüm mucizelerimizi yalanladılar ve biz de onları En Üstün ve Her şeye Gücü Yetenin yakalayışı gibi yakaladık."},{"n":43,"t":"Sizin inkârcılarınız onlarınkinden daha mı iyi? Yoksa kitaplarda kendiniz için bir af ilanına mı rastladınız?"},{"n":44,"t":"Yoksa, \"Biz, zafere ulaşacak bir cemaatiz\" mi diyorlar?"},{"n":45,"t":"O cemaat bozguna uğratılacak; dönüp kaçacaklar."},{"n":46,"t":"O an onları beklemektedir, daha korkunç ve acıdır."},{"n":47,"t":"Suçlular bir sapıklık ve cehennem içindedir."},{"n":48,"t":"Yüzükoyun ateşe sürüklenecekleri gün: \"Sakar’ın dokunuşunu tadın.\""},{"n":49,"t":"Biz her şeyi belli bir ölçüyle yaratmışızdır."},{"n":50,"t":"Buyruğumuz göz kırpması gibi anidir."},{"n":51,"t":"Sizin benzerlerinizi yok etmiştik. Yok mu öğüt alan?"},{"n":52,"t":"Tüm yaptıkları kitaplarda kayıtlıdır."},{"n":53,"t":"Küçük ve büyük hepsi yazılmıştır."},{"n":54,"t":"Erdemliler, bahçeler ve ırmaklar içindedir."},{"n":55,"t":"Güçlü Yönetici yanında onurlu makamlardadırlar."}]},{"id":55,"name":"Rahman Suresi","verses":[{"n":1,"t":"Rahman,"},{"n":2,"t":"Kuran’ı öğretti."},{"n":3,"t":"İnsanı yarattı."},{"n":4,"t":"Ona beyanı (açıklama yeteneğini) öğretti."},{"n":5,"t":"Güneş ve ay bir hesap ile (hareket etmekte) dir."},{"n":6,"t":"Yıldızlar ve ağaçlar secde etmektedirler."},{"n":7,"t":"Göğü yükseltti ve ölçüyü/dengeyi koydu."},{"n":8,"t":"Ki ölçüyü aşmayasınız."},{"n":9,"t":"Ölçüyü adaletle gözetiniz; ölçüyü kaybetmeyiniz."},{"n":10,"t":"Yeryüzünü tüm yaratıklar için yarattı."},{"n":11,"t":"Orada meyveler, salkımlı hurma ağaçları vardır."},{"n":12,"t":"Kabuklu taneler ve baharatlar."},{"n":13,"t":"(Ey insanlar ve cinler), Efendinizin hangi nimetlerini yalanlayabilirsiniz?"},{"n":14,"t":"İnsanı, çömlek gibi kuru bir çamurdan yarattı."},{"n":15,"t":"Cinleri de dumansız ateşten yarattı."},{"n":16,"t":"Efendinizin hangi nimetlerini yalanlayabilirsiniz?"},{"n":17,"t":"İki doğunun ve iki batının Rabbi."},{"n":18,"t":"Efendinizin hangi nimetlerini yalanlayabilirsiniz?"},{"n":19,"t":"İki denizi salmıştır; birbirlerine kavuşuyorlar."},{"n":20,"t":"Aralarında bir engel vardır; birbirinin sınırını aşıp karışmazlar."},{"n":21,"t":"Efendinizin hangi nimetlerini yalanlayabilirsiniz?"},{"n":22,"t":"İkisinden de inci ve mercan çıkar."},{"n":23,"t":"Efendinizin hangi nimetlerini yalanlayabilirsiniz?"},{"n":24,"t":"Denizde dağlar gibi akıp giden gemiler O’nundur."},{"n":25,"t":"Efendinizin hangi nimetlerini yalanlayabilirsiniz?"},{"n":26,"t":"Üzerinde bulunan herkes ölümlüdür."},{"n":27,"t":"Sadece Görkemli ve Onurlu Efendinin varlığı kalıcıdır."},{"n":28,"t":"Efendinizin hangi nimetlerini yalanlayabilirsiniz?"},{"n":29,"t":"Göklerde ve yerde olan herkes O’na yalvarır. O her gün kesintisiz kontrol etmektedir."},{"n":30,"t":"Efendinizin hangi nimetlerini yalanlayabilirsiniz?"},{"n":31,"t":"Ey sorumlu iki topluluk, sizi elbette sorguya çekeceğiz."},{"n":32,"t":"Efendinizin hangi nimetlerini yalanlayabilirsiniz?"},{"n":33,"t":"Ey insanlar ve cinler topluluğu, göklerin ve yerin çaplarını aşmaya gücünüz yetiyorsa, aşıp geçin. Bir yetkiye sahip olmadan geçemezsiniz."},{"n":34,"t":"Efendinizin hangi nimetlerini yalanlayabilirsiniz?"},{"n":35,"t":"Üzerinize ateşten toplar ve ışınlar gönderilir; yardım görmezsiniz."},{"n":36,"t":"Efendinizin hangi nimetlerini yalanlayabilirsiniz?"},{"n":37,"t":"Gök parçalanıp da, yağ gibi eridiği ve kırmızı bir güle dönüştüğü zaman…"},{"n":38,"t":"Efendinizin hangi nimetlerini yalanlayabilirsiniz?"},{"n":39,"t":"O gün ne insana ne de cine günahından sorulmaz."},{"n":40,"t":"Efendinizin hangi nimetlerini yalanlayabilirsiniz?"},{"n":41,"t":"Suçlular yüzlerinden tanınır ve yaka paça götürülürler."},{"n":42,"t":"Efendinizin hangi nimetlerini yalanlayabilirsiniz?"},{"n":43,"t":"İşte bu, suçluların yalanlayıp durduğu cehennemdir."},{"n":44,"t":"Onunla kaynar su arasında dönüp dolaşırlar."},{"n":45,"t":"Efendinizin hangi nimetlerini yalanlayabilirsiniz?"},{"n":46,"t":"Efendisinin görkeminden korkan (cin ve insan) lar için iki bahçe vardır."},{"n":47,"t":"Efendinizin hangi nimetlerini yalanlayabilirsiniz?"},{"n":48,"t":"Türlü besinlerle doludur her ikisi."},{"n":49,"t":"Efendinizin hangi nimetlerini yalanlayabilirsiniz?"},{"n":50,"t":"İçlerinde akan pınarlar vardır."},{"n":51,"t":"Efendinizin hangi nimetlerini yalanlayabilirsiniz?"},{"n":52,"t":"İkisinde de her meyveden iki çeşit vardır."},{"n":53,"t":"Efendinizin hangi nimetlerini yalanlayabilirsiniz?"},{"n":54,"t":"Astarları atlastan yataklara yaslanırlar, her iki bahçenin meyveleri pek yakındır."},{"n":55,"t":"Efendinizin hangi nimetlerini yalanlayabilirsiniz?"},{"n":56,"t":"Oralarda sarkan meyveler vardır; daha önce ne bir insan ne de bir cin tarafından dokunulmamış."},{"n":57,"t":"Efendinizin hangi nimetlerini yalanlayabilirsiniz?"},{"n":58,"t":"Onlar yakut ve mercan gibidirler."},{"n":59,"t":"Efendinizin hangi nimetlerini yalanlayabilirsiniz?"},{"n":60,"t":"İyiliğin karşılığı, yalnız iyilik değil midir?"},{"n":61,"t":"Efendinizin hangi nimetlerini yalanlayabilirsiniz?"},{"n":62,"t":"O ikisinin ötesinde iki bahçe daha var."},{"n":63,"t":"Efendinizin hangi nimetlerini yalanlayabilirsiniz?"},{"n":64,"t":"Yemyeşildirler."},{"n":65,"t":"Efendinizin hangi nimetlerini yalanlayabilirsiniz?"},{"n":66,"t":"İkisinde de fışkıran iki kaynak vardır."},{"n":67,"t":"Efendinizin hangi nimetlerini yalanlayabilirsiniz?"},{"n":68,"t":"Her ikisinde de meyveler, hurmalar ve narlar vardır."},{"n":69,"t":"Efendinizin hangi nimetlerini yalanlayabilirsiniz?"},{"n":70,"t":"Her ikisinde de iyilikler, güzellikler vardır."},{"n":71,"t":"Efendinizin hangi nimetlerini yalanlayabilirsiniz?"},{"n":72,"t":"Çadırlara kapanmış güzeller"},{"n":73,"t":"Efendinizin hangi nimetlerini yalanlayabilirsiniz?"},{"n":74,"t":"Daha önce onlara ne insan ne de cin dokunmamıştı."},{"n":75,"t":"Efendinizin hangi nimetlerini yalanlayabilirsiniz?"},{"n":76,"t":"Yeşil yastıklara ve işlemeli halılara yaslanırlar."},{"n":77,"t":"Efendinizin hangi nimetlerini yalanlayabilirsiniz?"},{"n":78,"t":"Görkemli ve Onurlu Efendinin ismi ne yücedir!"}]},{"id":56,"name":"Vakı'a Suresi","verses":[{"n":1,"t":"Kaçınılmaz olay gerçekleştiği zaman,"},{"n":2,"t":"Onun gerçekleşmesini artık yalanlayan çıkmaz."},{"n":3,"t":"O alçaltıcıdır, yücelticidir."},{"n":4,"t":"Yerin sallanıp sarsılacağı,"},{"n":5,"t":"Ve dağların paramparça edileceği zaman,"},{"n":6,"t":"Artık o toz duman haline gelmiştir."},{"n":7,"t":"Sizler de üç bölüme ayrılırsınız."},{"n":8,"t":"Mutlular ne kadar da mutludurlar!"},{"n":9,"t":"Mutsuzlar ne kadar da mutsuzdurlar!"},{"n":10,"t":"Bir de ileri geçen öncü seçkinler vardır."},{"n":11,"t":"Onlar (Tanrı’ya) yaklaştırılanlardır."},{"n":12,"t":"Nimet bahçelerinde…"},{"n":13,"t":"Onların büyük bir kısmı önceki nesillerden,"},{"n":14,"t":"Küçük bir kısmı da sonraki nesillerdendir."},{"n":15,"t":"Lüks mobilyalar üzerinde,"},{"n":16,"t":"Karşılıklı yaslanmışlardır."},{"n":17,"t":"Onlara ölümsüz gençler servis yaparlar."},{"n":18,"t":"Kaynaktan doldurulmuş bardaklar, sürahiler ve kadehlerle."},{"n":19,"t":"Ne ara verirler ne de yorulurlar."},{"n":20,"t":"Ve beğendikleri meyveler…"},{"n":21,"t":"Canlarının çektiği kuş etleri…"},{"n":22,"t":"Güzel eşler…"},{"n":23,"t":"Korunmuş inciler gibi…"},{"n":24,"t":"Yapmış olduklarına bir karşılık olarak verilir."},{"n":25,"t":"Orada ne bir saçmalık, ne de günaha sokan bir söz işitirler."},{"n":26,"t":"Sadece, \"Selam, selam\" derler."},{"n":27,"t":"Sağ tarafta olanlar sağ tarafta olacaklar!"},{"n":28,"t":"Dikensiz meyve ağaçları,"},{"n":29,"t":"Salkımları sarkmış muz ağaçları,"},{"n":30,"t":"Uzamış gölgeler,"},{"n":31,"t":"Fışkıran sular,"},{"n":32,"t":"Ve bol meyveler içindedirler."},{"n":33,"t":"Bunlar ne tükenirler, ne de yasak edilirler!"},{"n":34,"t":"Ve onlar yükseltilmiş mobilyalar üzerindedirler."},{"n":35,"t":"Biz kadınları yeniden biçimlendirdik."},{"n":36,"t":"Onları gençleştirdik."},{"n":37,"t":"Mükemmel biçimde eşlenmişlerdir."},{"n":38,"t":"Sağ tarafta olanlar içindir."},{"n":39,"t":"Onların birçoğu önceki nesillerdendir."},{"n":40,"t":"Onların birçoğu da sonraki nesillerdendir."},{"n":41,"t":"Sol tarafta bulunanlar, sol tarafta olacaklardır."},{"n":42,"t":"İşleyen ve kaynayan bir azap içindedirler."},{"n":43,"t":"Sıcak gölgeler altındadırlar."},{"n":44,"t":"Ne soğuktur, ne de yararlı."},{"n":45,"t":"Bundan önce onlar konfor içinde şımarmışlardı."},{"n":46,"t":"Büyük günahı işlemekte direniyorlardı."},{"n":47,"t":"Diyorlardı ki, \"Biz öldükten, toz ve kemiğe dönüştükten sonra mı diriltileceğiz?\""},{"n":48,"t":"\"Önceki atalarımız da mı?\""},{"n":49,"t":"De ki: \"Öncekiler de, sonrakiler de.\""},{"n":50,"t":"\"Bilinen günün buluşma anı için toplanacaklardır.\""},{"n":51,"t":"\"Sonra da siz, ey sapıtmışlar, ey yalanlayıcılar\""},{"n":52,"t":"\"Zakkum ağacından yiyeceksiniz.\""},{"n":53,"t":"\"Onunla karnınızı dolduracaksınız.\""},{"n":54,"t":"\"Ve üzerine kaynar su içeceksiniz.\""},{"n":55,"t":"\"Susamış devenin içişi gibi içeceksiniz.\""},{"n":56,"t":"Yargı gününde işte böyle ağırlanacaklardır."},{"n":57,"t":"Sizi biz yarattık, doğrulamanız gerekmez miydi?"},{"n":58,"t":"Attığınız meniye dikkat ettiniz mi?"},{"n":59,"t":"Siz mi onu yaratıyorsunuz, yoksa biz mi yaratıyoruz?"},{"n":60,"t":"Aranızda ölümünüzü önceden biz belirledik. Kimse bizi engelleyemez:"},{"n":61,"t":"Sizi başka nesillerle değiştirmekten, yahut sizi bilmediğiniz bir biçimde yaratmaktan…"},{"n":62,"t":"İlk yaratılışı biliyorsunuz. Öğüt almalı değil misiniz?"},{"n":63,"t":"Ektiğinize dikkat ettiniz mi?"},{"n":64,"t":"Siz mi onu yetiştiriyorsunuz, yoksa biz mi?"},{"n":65,"t":"Dileseydik onu samana çevirirdik de siz şaşardınız:"},{"n":66,"t":"\"Borca girdik.\""},{"n":67,"t":"\"Doğrusu, yoksun bırakıldık.\""},{"n":68,"t":"İçmekte olduğunuz suya dikkat ettiniz mi?"},{"n":69,"t":"Onu bulutlardan siz mi indiriyorsunuz, yoksa biz mi?"},{"n":70,"t":"Dileseydik onu tuzlu yapardık. Şükretmez misiniz?"},{"n":71,"t":"Yakmakta olduğunuz ateşe dikkat ettiniz mi?"},{"n":72,"t":"Onun ağacını siz mi başlattınız, yoksa biz mi başlatmaktayız?"},{"n":73,"t":"Kullananlar için biz onu bir ibret ve yararlı yaptık."},{"n":74,"t":"Öyleyse Büyük Efendinin ismini yücelt."},{"n":75,"t":"Yıldızların yerlerine yemin ederim."},{"n":76,"t":"Onun ne büyük bir yemin olduğunu bir bilseniz!"},{"n":77,"t":"Bu, onurlu bir Kuran’dır."},{"n":78,"t":"Korunmuş bir kitaptadır."},{"n":79,"t":"Onu ancak temizler kavrayabilir."},{"n":80,"t":"Evrenlerin Efendisinden indirilmiştir."},{"n":81,"t":"Siz bu sözü mü küçümsüyorsunuz?"},{"n":82,"t":"İnkar etmeyi iş mi ediniyorsunuz?"},{"n":83,"t":"Ya can boğaza dayandığı zaman?"},{"n":84,"t":"O anda siz bakınmaktasınız."},{"n":85,"t":"Biz ona (can çekişene) sizden daha yakınız; ancak siz göremezsiniz."},{"n":86,"t":"Yaptığınızın karşılığını görmeyeceğiniz doğruysa,"},{"n":87,"t":"Onu geri çevirsenize, eğer doğru sözlü iseniz?"},{"n":88,"t":"Ancak o, (bana) yaklaştırılanlardan ise,"},{"n":89,"t":"o zaman neşe, çiçekler ve nimet bahçeleri…"},{"n":90,"t":"O, sağda olanlardan ise,"},{"n":91,"t":"\"Sana sağdakilerden selam olsun!\""},{"n":92,"t":"Ama o yalanlayan sapıklardan ise,"},{"n":93,"t":"kaynar sudan bir ağırlanma,"},{"n":94,"t":"ve cehennemde yanma…"},{"n":95,"t":"Mutlak gerçek budur."},{"n":96,"t":"Öyleyse Büyük Efendinin ismini yücelt."}]},{"id":57,"name":"Hadid Suresi","verses":[{"n":1,"t":"Göklerde ve yerde ne varsa ALLAH’ı yüceltir. O Üstündür, Bilgedir."},{"n":2,"t":"Göklerin ve yerin yönetimi O’na aittir. Yaşatır, öldürür. O her şeye gücü yetendir."},{"n":3,"t":"O ilktir, sondur. O en dıştakidir, en içtekidir. O her şeyi bilir."},{"n":4,"t":"O’dur gökleri ve yeri altı günde yaratan ve daha sonra tüm otoriteyi kuran. Yere giren ve ondan çıkanı, gökten inen ve ona yükselen her şeyi bilir. Nerede olursanız olun O sizinle beraberdir. ALLAH tüm yaptıklarınızı görendir."},{"n":5,"t":"Göklerin ve yerin yönetimi O’na aittir. Her şey ALLAH ‘a havale edilir."},{"n":6,"t":"Geceyi gündüze sokar, gündüzü de geceye sokar. O, göğüslerin içindekini bilir."},{"n":7,"t":"ALLAH’ı ve elçisini onaylayın ve yönetiminize verdiği şeylerden yardım için verin. Sizden gerçeği onaylayıp yardım edenler için büyük bir ödül vardır."},{"n":8,"t":"Efendinizi onaylamanız için elçi sizi çağırdığı halde size ne oluyor ki hâlâ ALLAH’ı onaylamıyorsunuz? Hem O, sizden söz almıştı, eğer gerçeği onaylıyor iseniz."},{"n":9,"t":"Sizi karanlıklardan aydınlığa çıkarmak için kuluna apaçık ayetleri indiren O’dur. Kuşkusuz ALLAH size karşı Şefkatlidir, Rahimdir."},{"n":10,"t":"Size ne oluyor ki ALLAH yolunda harcamıyorsunuz? Oysa göklerin ve yerin zenginlikleri ALLAH’ındır. Zaferden önce harcayıp savaşanlarınız, daha sonra harcayıp savaşanlarla bir olmazlar; onlardan daha üstündürler. ALLAH her birine kurtuluşu söz vermiştir. ALLAH tüm yaptıklarınızdan haberdardır."},{"n":11,"t":"Kim (erdemli davranarak) ALLAH’a güzel bir borç verirse, karşılığını kat kat alır ve cömert bir ödül kazanır."},{"n":12,"t":"Gerçeği onaylayan erkeklerin ve kadınların ışıklarının önlerinden ve sağ yanlarından yayıldığını gördüğün gün, \"Müjde! Bugün, sürekli olarak kalacağınız altlarından ırmaklar akan bahçeler var. Bu, en büyük zaferdir."},{"n":13,"t":"O gün, ikiyüzlü erkekler ve kadınlar gerçeği onaylayanlara, \"Bize bakın da sizin ışığınızdan alalım\" diyecekler. Onlara, \"Geriye dönün de ışık arayın\" denir. Aralarına, iç taraftaki merhametle, dış taraftaki azabı ayıran kapılı bir engel konacaktır."},{"n":14,"t":"\"Biz sizinle birlikte değil miydik?\" diye onlara seslenirler. \"Evet\" derler, \"Ancak siz kendinizi kandırdınız, beklediniz, kuşkular beslediniz ve ALLAH’ın kararı gelinceye kadar kuruntularla oyalandınız. Kandırıcı, sizi ALLAH hakkında yanılttı.\""},{"n":15,"t":"Bugün ne sizden ne de inkâr edenlerden bir fidye kabul edilmez. Yeriniz cehennemdir; Mevlanız odur. Ne kötü bir duraktır."},{"n":16,"t":"Gerçeği onaylayanlar için ALLAH’ın mesajına ve inen gerçeğe gönüllerini açmanın vakti gelmedi mi? Daha önce kendilerine kitap verilmiş olanlar gibi olmasınlar; onların üzerinden uzun zaman geçince kalpleri katılaşmıştı. Onların çoğunluğu yoldan çıkmış kimselerdir."},{"n":17,"t":"Biliniz ki ALLAH ölümünden sonra yeri diriltir. Düşünesiniz diye size ayetleri böyle açıklıyoruz."},{"n":18,"t":"Sadaka veren erkekler ve kadınlar, ALLAH’a güzel bir borç vermişlerdir. Onlara kat kat ödenir ve onlar cömert bir ödül haketmişlerdir."},{"n":19,"t":"ALLAH’a ve elçisini onaylayanlar, dosdoğru olanlar ve tanıklardır. Rab’leri katında onlar için ödülleri ve ışıkları vardır. İnkar edip ayet ve mucizelerimizi yalanlayanlar ise cehennem halkıdır."},{"n":20,"t":"Bilesiniz ki dünya hayatı bir oyun, eğlence, süs, aranızda övünme, para ve çocuk çoğaltma yarışından ibarettir. Bu, inkârcıların hoşuna giden bir bitkiyi yetiştiren bir yağmura benzer. Ne var ki daha sonra o bitki kurur, sararır ve sonunda çerçöp olur. Ahirette ise ALLAH’tan çetin bir azap, bir bağışlanma ve hoşnutluk vardır. Dünya hayatı, kandıran, geçici bir zevkten ibarettir."},{"n":21,"t":"Efendinizden bir bağışlanmaya ve genişliği gökler ve yer kadar olan bir bahçeye koşun. ALLAH’a ve elçisini onaylayanlar için hazırlanmıştır. Bu, ALLAH’ın dilediğine ve/veya dileyene verdiği lütfudur. ALLAH Büyük Lütuf sahibidir."},{"n":22,"t":"Yeryüzünde ve aranızda oluşan hiçbir şey yoktur ki biz onu yaratmadan önce bir kitapta kayıtlı olmasın. Bu, kuşkusuz ALLAH için çok kolaydır."},{"n":23,"t":"Bu, yitirdiğiniz bir şey için üzülmemeniz ve O’nun size verdiği nimetlerle de şımarmamanız içindir. ALLAH kendini beğenip övünenleri sevmez."},{"n":24,"t":"Onlar ki cimrilik ederler ve halka cimri olmayı öğütlerler. Kim yüz çevirirse, kuşkusuz ALLAH Zengindir, Övgüye layık olandır."},{"n":25,"t":"Elçilerimizi apaçık kanıtlarla gönderdik, onlarla birlikte kitabı ve yasayı indirdik ki halk adaleti gözetsin. Büyük bir kuvvete ve halk için yararlara sahip olan demiri de indirdik ki ALLAH kendisini ve elçisini onaylayıp destekleyenleri ayırsın. ALLAH Güçlüdür, Üstündür."},{"n":26,"t":"Biz Nuh’u, İbrahim’i gönderdik, soylarına peygamberlik ve kitap bağışladık. Bir kısmı doğruyu buldu; ama onlardan çoğu yoldan çıkmışlardı."},{"n":27,"t":"Sonra onların peşinden, ard arda elçilerimizi gönderdik. Meryem oğlu İsa’yı da gönderdik ve ona İncil’i verdik. Onu izleyenlerin gönüllerine şefkat ve merhamet koyduk. Fakat, bizim kendileri için onaylamadığımız bir ruhbanlık uydurdular. Halbuki onlardan sadece ALLAH’ı hoşnut edecek hususlara uymalarını istemiştik. Üstelik ruhbanlığa hakkıyla da uymadılar. Aralarından gerçeği onaylayanlara ödüllerini verdik; ancak çokları yoldan çıkmışlardı."},{"n":28,"t":"Ey gerçeği onaylayanlar, ALLAH’ı sayıp dinleyin ve elçisini onaylayın ki rahmetinden size iki pay versin, size, aydınlığında yürüyeceğiniz bir ışık bağışlasın ve sizi bağışlasın. ALLAH Bağışlayandır, Rahimdir."},{"n":29,"t":"Böylece kitap halkı bilsin ki onlar ALLAH’ın lütfunu tekelleştiremezler, tüm lütuf ALLAH’ın elindedir, onu dilediğine ve/ veya dileyene verir. ALLAH Büyük Lütuf Sahibidir."}]},{"id":58,"name":"Mücadele Suresi","verses":[{"n":1,"t":"ALLAH, kocası hakkında seninle tartışan ve ALLAH’a şikayette bulunan kadının sözlerini işitti. ALLAH ikinizin tüm konuştuklarını işitmiştir. ALLAH İşitendir, Bilendir."},{"n":2,"t":"İçinizden, kadınlarını annelerine benzeterek yabancılaştıranlar bilirler ki onlar anaları değildir. Anneleri kendilerini doğuranlardır. Söyledikleri kötü ve asılsız bir sözdür. ALLAH Affedendir, Bağışlayandır."},{"n":3,"t":"Kadınlarını annelerine benzeterek yabancılaştırdıktan sonra sözlerinden dönenler, karılarıyla cinsel ilişkiye girmeden önce bir köleyi özgürlüğe kavuştursunlar. Size öğütlenen budur. ALLAH yaptığınız her şeyi haber alır."},{"n":4,"t":"Azad edecek bir köle bulamayan, cinsel ilişkiden önce üst üste iki ay boyunca oruç tutmalı. Buna güç yetiremeyen ise altmış yoksulu doyurmalı. ALLAH’a ve elçisini onaylamalısınız. Bunlar, ALLAH’ın belirlediği sınırdır. İnkarcılar acı bir azaba mahkûm olmuşlardır."},{"n":5,"t":"ALLAH’a ve elçisine karşı gelenler, kendilerinden öncekiler nasıl alçaltıldıysa öylece alçaltılacaklardır. Biz, apaçık ayetler indirmiş bulunuyoruz. İnkarcılar için utandırıcı bir azap vardır."},{"n":6,"t":"Gün gelir ALLAH onları topluca diriltir ve sonra yapmış olduklarını kendilerine haber verir. Onlar unutsalar da ALLAH onları saymıştır. ALLAH her şeye tanıktır."},{"n":7,"t":"ALLAH’ın göklerde ve yerde olan her şeyi bildiğini anlamaz mısın? Üç kişi gizli konuşsa, mutlaka O onların dördüncüsüdür. Beş kişi olsalar, mutlaka O onların altıncısıdır. İster bundan az veya çok ve nerede olursa olsunlar, O onlarla beraberdir. Sonra diriliş gününde onlara yaptıklarını haber verir. ALLAH her şeyi Bilendir."},{"n":8,"t":"Gizli toplantılar yapmaktan menedildikleri halde hâlâ menedildikleri işte ısrar edenler dikkatini çekmedi mi? Onlar günah işlemek, düşmanlıkta bulunmak ve elçiye itaatsizlik etmek amacıyla kulis yapıyorlar. Sana geldiklerinde, ALLAH’ın seni selamlamadığı bir biçimde selamlıyorlar. Kendi aralarında, \"Söylediklerimizden ötürü ALLAH bizi cezalandırsa ya!\" derler. Cehennem onlara yeter. Orada yanarlar; ne kötü bir duraktır orası."},{"n":9,"t":"Ey gerçeği onaylayanlar, gizli görüştüğünüz vakit günah, düşmanlık ve elçiye isyan için konuşmayın; iyilik ve erdemlilik için konuşun. Huzuruna toplanacağınız ALLAH’ı dinleyin."},{"n":10,"t":"Komplo toplantıları sapkındandır. Bu yolla gerçeği onaylayanları incitmek ister. Oysa ALLAH’ın izni olmadan onlara hiçbir zarar veremez. Gerçeği onaylayanlar ALLAH’a güvensinler."},{"n":11,"t":"Ey gerçeği onaylayanlar, toplantılarda size \"Yer açınız\" dendiğinde yer açınız ki ALLAH ta size yer açsın. Size, \"Kalkınız\" dendiğinde kalkınız ki ALLAH da içinizdeki gerçeği onaylayanları ve kendilerine bilgi verilenleri derecelerle yükseltsin. ALLAH tüm yaptıklarınızdan haberdardır."},{"n":12,"t":"Ey gerçeği onaylayanlar, elçiyle özel görüşme yapacağınız zaman, görüşmenizden önce (yoksullara) bir sadaka verin. Bu sizin için daha iyi ve daha temizdir. Veremiyorsanız, ALLAH Bağışlayandır, Rahimdir."},{"n":13,"t":"Özel görüşmenizden önce bir sadaka vermekten çekindiniz mi ki onu uygulamadınız? ALLAH tövbenizi kabul eder. Namazı gözetin, zekatı verin, ALLAH’a ve elçisine uyun. ALLAH yaptıklarınızdan haberdardır."},{"n":14,"t":"ALLAH’ın kendilerine kızgın olduğu bir topluluğu dost edinenlere dikkat etmedin mi? Onlar ne sizdendir ne de onlardandır. Onlar bile bile yalan yere yemin ederler!"},{"n":15,"t":"ALLAH onlar için çetin bir ceza hazırlamıştır. Yaptıkları ne kadar da kötüdür."},{"n":16,"t":"Anlaşmalarını/yeminlerini kalkan edinerek ALLAH’ın yolundan saptırdılar. Onlar alçaltıcı bir azabı haketmişlerdir."},{"n":17,"t":"Ne paraları, ne de evlatları, onları ALLAH’tan kurtaramayacaktır. Onlar cehennem halkıdırlar ve orada ebedi kalıcıdırlar."},{"n":18,"t":"Gün gelecek, ALLAH hepsini diriltecek ve şimdi size yemin ettikleri gibi O’na da yemin edeceklerdir. Kendilerinin (doğru) bir şey üzerinde olduklarını sanıyorlar! Doğrusu, onlar yalancılardır."},{"n":19,"t":"Sapkın onları sahiplenmiş ve onlara ALLAH’ın mesajını unutturmuştur. Onlar sapkının partisidir. Sapkının partisi kesinlikle kaybedecektir."},{"n":20,"t":"ALLAH’a ve elçisine karşı gelenler, alçaklardandır."},{"n":21,"t":"ALLAH, \"Ben ve benim elçilerim kazanacaklardır\" diye yazmıştır. ALLAH Güçlüdür, Üstündür."},{"n":22,"t":"ALLAH’ı ve ahiret gününü onaylamış bir topluluk göremezsin ki, ALLAH’a ve elçisine karşı gelenleri dost edinsin. Hatta onlar, kendilerinin anaları, babaları, çocukları, oğulları, kardeşleri ve akrabaları bile olsa… Gerçeği onaylamayı kalplerine yazmış ve katından bir vahiyle desteklemiştir. Onları içlerinden ırmaklar akan, ebedi kalacakları bahçelere sokar. ALLAH onlardan hoşnut olmuştur, onlar da O’ndan hoşnut olmuşlardır. Onlar ALLAH’ın partisidir. Hiç kuşkusuz, ALLAH’ın partisi kazanacaktır."}]},{"id":59,"name":"Haşr Suresi","verses":[{"n":1,"t":"Göklerde ve yerde ne varsa ALLAH’ı yüceltir. O Üstündür, Bilgedir."},{"n":2,"t":"O ki, kitap halkından inkârcı olanları ilk sürgün için ülkelerinden çıkarmıştır. Onların çıkacağını hiç beklemiyordunuz. Kalelerinin kendilerini ALLAH’tan koruyacağını sandılar. Ancak ALLAH onlara ummadıkları bir yerden geldi ve kalplerine korku saldı. Böylece evlerini kendi elleriyle ve gerçeği onaylayanların elleriyle yıkıyorlar. Ey görüş sahipleri ibret alınız."},{"n":3,"t":"ALLAH onları ayrılmaya zorlamasaydı, bu dünyada cezalandıracaktı. Ahirette de onlara ateş azabı vardır."},{"n":4,"t":"Çünkü onlar ALLAH’a ve elçisine karşı geldiler. Kim ALLAH’a karşı gelirse ALLAH’ın cezalandırması çetindir."},{"n":5,"t":"Bir ağacı kesseniz de yahut gövdesi üzerinde bıraksanız da bu ALLAH’ın arzusuna göredir. O, yoldan çıkanları alçaltacaktır."},{"n":6,"t":"ALLAH’ın onlardan alıp elçisine verdikleri için, siz at ve deve sürmediniz; ama ALLAH elçisini dilediğinin üstüne gönderir. ALLAH her şeye kadirdir."},{"n":7,"t":"ALLAH’ın o ülkelerin halklarından elçisine ganimet bıraktığı şeyler ALLAH’ın ve elçisinindir. Yani akrabalara, yetimlere, yoksullara ve yolda kalmışlara verilmelidir ki zenginlerinizin arasında tekelleşmesin. Elçinin size verdiğini alın; ancak onun size vermediğinden uzak durun. ALLAH’ı dinleyin. ALLAH’ın cezalandırması çetindir."},{"n":8,"t":"ALLAH’ın lütuf ve rızasını aradıkları, ALLAH’ı ve elçisini destekledikleri için yurtlarından ve mallarından edilmiş bulunan göçmenlerin fakirlerine... Doğru olanlar bunlardır."},{"n":9,"t":"Onlardan önce yurt ve onay sahibi olanlar, kendilerine göç edenleri severler ve verdiklerinden ötürü içlerinde bir burukluk duymazlar. Hatta kendileri ihtiyaç içinde bile olsalar onları kendilerinden önde tutarlar. Doğrusu, nefislerinin bencilliğinden korunanlar kurtulanlardır."},{"n":10,"t":"Onlardan sonra gelenler, \"Efendimiz, bizi ve bizden önce gerçeği onaylamış olan kardeşlerimizi bağışla; kalbimizi gerçeği onaylayanlara karşı kin beslemekten koru. Efendimiz, sen şefkatlisin, Rahimsin\" derler."},{"n":11,"t":"İkiyüzlü davrananlara dikkat etmedin mi? Kitap halkından inkârcı olan arkadaşlarına, \"Çıkartılırsanız biz de sizinle birlikte çıkacağız ve sizin aleyhinize hiçbir kimseye itaat etmeyeceğiz. Sizinle savaşılırsa, kesinlikle sizi destekleyeceğiz\" demektedirler. ALLAH onların yalancı olduğuna tanıklık eder."},{"n":12,"t":"Doğrusu, onlar çıkarılsalar, onlarla birlikte çıkmazlar. Onlarla savaşılırsa, onları desteklemezler. Destekleseler bile arkalarını dönüp kaçarlar, sonra yardım görmezler."},{"n":13,"t":"Kalplerine, ALLAH’tan daha çok siz korku salıyorsunuz. Zira onlar anlayışsız bir topluluktur."},{"n":14,"t":"Onlar, iyi korunmuş kentlerde veya duvarların ardında olmaları haricinde bir araya gelip sizinle savaşamazlar. Aralarındaki çekişmeleri çetindir. Onları birlik sanırsın, halbuki kalpleri darmadağınıktır. Zira onlar, akıllarını kullanmayan bir topluluktur."},{"n":15,"t":"Kendilerinden kısa bir süre önce geçmiş olanlara benziyorlar. Onlar, işlediklerinin karşılığını tatmışlar ve acı bir azabı hak etmişlerdi."},{"n":16,"t":"Onlar tıpkı sapkın gibidir: İnsana, \"İnkar et\" der. Sonra o inkâr edince de \"Benim seninle bir ilişkim yok. Ben, evrenlerin Rabbi ALLAH’tan korkarım\" der."},{"n":17,"t":"Her ikisi de ebedi kalacakları ateşte son buldular. Zalimlerin cezası işte böyledir."},{"n":18,"t":"Ey gerçeği onaylayanlar, ALLAH’ı sayıp dinleyin. Herkes yarın için ne hazırladığına baksın. ALLAH’ı sayıp dinleyin. ALLAH yaptıklarınızdan haberdardır."},{"n":19,"t":"ALLAH’ı unuttukları için O’nun da kendilerini kendilerine unutturduğu kimseler gibi olmayın. Onlar yoldan çıkmışlardır."},{"n":20,"t":"Bahçe halkıyla cehennem halkı bir olamaz; kazananlar ancak bahçe halkıdır."},{"n":21,"t":"Bu Kuran’ı bir dağın üzerine indirseydik, ALLAH’a olan saygıdan ötürü onun titreyip paramparça olduğunu görecektin. Belki düşünürler diye biz insana böyle örnekler vermekteyiz."},{"n":22,"t":"O ALLAH’tır ki O’ndan başka tanrı yoktur. Tüm gizemleri ve açıktakileri Bilendir. O Rahmandır, Rahimdir."},{"n":23,"t":"O ALLAH’tır ki O’ndan başka tanrı yoktur. Egemendir, Kutsaldır, Barıştır, Güvenlik Sağlayıcıdır, Koruyandır, Üstündür, Güçlüdür, Uludur. Onların ortak koştuklarından ALLAH çok yücedir."},{"n":24,"t":"O, Yaratan, Vareden ve Biçim veren ALLAH’tır. Tüm güzel isimler O’nundur. Göklerde ve yerde ne varsa O’nu yüceltir. O Üstündür, Bilgedir."}]},{"id":60,"name":"Mümtehine Suresi","verses":[{"n":1,"t":"Ey gerçeği onaylayanlar, benim düşmanımı ve sizin düşmanınızı dost edinmeyin. Size gelen gerçeği inkâr etmiş ve Efendiniz olan ALLAH’ı onayladığınız için elçiyi ve sizi (ülkenizden) çıkarmış oldukları halde siz onlara sevgi gösteriyorsunuz. Rızamı kazanmak için yolumda bir cihada çıktıysanız, onları nasıl gizlice sevebilirsiniz? Oysa ben, gizlediğinizi de açığa vurduğunuzu da çok iyi bilirim. Sizden kim böyle davranırsa doğru yoldan sapmış olur."},{"n":2,"t":"Sizi ele geçirseler size düşman kesilirler ve elleriyle, dilleriyle sizi incitirler. İnkar etmenizi isterler."},{"n":3,"t":"Yakınlarınız ve çocuklarınız size yarar sağlamaz. Diriliş Günü sizi yargılar. ALLAH yaptıklarınızı Görendir."},{"n":4,"t":"Sizin için İbrahim ve onunla beraber olanlarda güzel bir örnek vardır. Onunla beraber olanlar, halklarına, \"Biz, sizden ve sizin ALLAH’ın dışında hizmet ettiklerinizden uzağız. Sizi tanımıyoruz. Yalnız ALLAH’ı onaylayıncaya kadar bizimle sizin aranızda ebedi olarak düşmanlık ve nefret belirmiştir. Ne var ki, İbrahim’in babasına \"Senin bağışlanman için dua edeceğim, fakat ALLAH’tan gelecek hiçbir şeye karşı seni koruyamam.\" Biçimindeki sözü (bir hata olarak) bunun dışındaydı. \"Efendimiz, sana güvendik, sana yöneldik ve sonunda sana döneceğiz.\""},{"n":5,"t":"\"Efendimiz, inkârcılar için bizi bir sınanma aracı kılma, bizi bağışla. Efendimiz sen Üstünsün, Bilgesin.\""},{"n":6,"t":"ALLAH’ı ve Ahiret Gününü arzu edenleriniz için onlarda güzel bir örnek vardır. Yüz çevirenlere gelince, Zengin ve Övgüye layık olan sadece ALLAH’tır."},{"n":7,"t":"Belki de ALLAH sizinle onlar arasındaki düşmanlığı sevgiye çevirir. ALLAH Kadirdir. ALLAH Bağışlayandır, Rahimdir."},{"n":8,"t":"ALLAH, din uğrunda sizinle savaşmayan ve sizi yurdunuzdan çıkarmayan kimselere iyilik yapmanızı ve onlara adaletli davranmanızı yasaklamaz. ALLAH adaletli davrananları sever."},{"n":9,"t":"Ancak ALLAH, sadece, sizinle din uğrunda savaşan, sizi yurdunuzdan çıkaran ve sizin çıkarılmanıza yardım eden kimselerle dost olmanızı yasaklar. Onları dost edinenler zalimlerdir."},{"n":10,"t":"Ey gerçeği onaylayanlar, gerçeği onaylayan göçmen kadınlar size sığındığında onları sorgulayın. ALLAH onların onaylarını çok iyi bilir. Gerçeği onayladıklarını anlarsanız, onları kafirlere geri göndermeyin. Ne bunlar o inkârcılara helaldir ne de onlar bunlara helaldir. İnkarcıların harcadığı mehirlerini onlara geri verin. Mehirlerini ödediğiniz taktirde bunlarla evlenmenizde bir sakınca yoktur. İnkarcı kadınları sorumluluğunuzda tutmayın. Onlara harcadığınız mehirlerinizi isteyebilirsiniz, onlar da verdikleri mehirlerini isteyebilirler. Bu, ALLAH’ın hükmüdür. O, aranızda yargıda bulunur. ALLAH Bilendir, Bilgedir."},{"n":11,"t":"Kafirlere katılan eşleriniz yoluyla bir şeyler yitirdikten sonra (ganimet veya size katılanlar yoluyla bir şeyler kazanıp) üstün gelirseniz, eşlerini yitirmiş olanlara, onların harcamış oldukları mehir kadar verin. Onayladığınız ALLAH’ı sayıp dinleyin."},{"n":12,"t":"Ey peygamber, gerçeği onaylayan kadınlar sana geldiklerinde, ALLAH’a hiçbir şeyi ortak koşmamak, hırsızlık yapmamak, zina etmemek, çocuklarını öldürmemek, bir iftira uydurup getirmemek ve doğru işlerde sana karşı gelmemek üzere yemin edip söz verirlerse onların sözünü kabul et ve onlar için ALLAH’tan bağışlanma dile. ALLAH Bağışlayandır, Rahimdir."},{"n":13,"t":"Ey gerçeği onaylayanlar, ALLAH’ın kendilerine kızgın olduğu bir topluluğu dost edinmeyin. İnkarcılar, mezardakilerden nasıl umut kesmişlerse onlar da ahiretten öylesine umut kesmişlerdir."}]},{"id":61,"name":"Saf Suresi","verses":[{"n":1,"t":"Göklerde ve yerde olanlar ALLAH’ı yüceltir. O, Üstündür, Bilgedir."},{"n":2,"t":"Ey gerçeği onaylayanlar, neden yapmadığınız veya yapmayacağınız şeyleri söylüyorsunuz?"},{"n":3,"t":"Yapmadığınız şeyi söylemeniz, ALLAH katında en sevilmeyen davranışlardandır."},{"n":4,"t":"ALLAH kendi yolunda kenetlenmiş bir duvar gibi düzenli birlikler halinde savaşanları sever."},{"n":5,"t":"Hani Musa, halkına: \"Ey halkım, benim, ALLAH’ın bir elçisi olarak size geldiğimi bildiğiniz halde neden beni incitiyorsunuz?\" demişti. Onlar eğrilince, ALLAH da kalplerini eğriltti. ALLAH yoldan çıkmış toplulukları doğruya ulaştırmaz."},{"n":6,"t":"Hani İsa, halkına: \"Ey İsrailoğulları, ben, size gönderilmiş ALLAH’ın bir elçisiyim. Benden önceki Tevrat’ı onaylayıcı ve benden sonra gelecek ve ismi daha çok öven bir elçiyi müjdeliyorum.\" Sonra kendilerine apaçık delilleri gösterdiğinde, \"Bu apaçık bir büyüdür\" dediler."},{"n":7,"t":"İslam’a çağrıldığı halde ALLAH hakkında yalan uydurandan daha zalim kim olabilir? ALLAH zalim topluluğu doğruya iletmez."},{"n":8,"t":"ALLAH’ın ışığını ağızlarıyla söndürmek isterler. İnkarcılar hoşlanmasa da ALLAH ışığını tamamlayacaktır."},{"n":9,"t":"O, elçisini hidayet ve gerçek din ile gönderdi ki onu tüm dinlere üstün kılsın, ortak koşanlar hoşlanmasa da…"},{"n":10,"t":"Ey gerçeği onaylayanlar, sizi acı azaptan kurtaracak bir ticareti size göstereyim mi?"},{"n":11,"t":"ALLAH’a ve elçisini onaylarsınız, ALLAH’ın yolunda canınız ve paranızla çaba gösterirsiniz. Bu sizin için en iyisidir, bir bilseniz."},{"n":12,"t":"Günahlarınızı bağışlar ve sizi içinden ırmaklar akan bahçelere ve Adn bahçelerindeki saraylara sokar. Büyük başarı budur."},{"n":13,"t":"Bundan başka sevdiğiniz bir şey daha: ALLAH’tan bir destek ve yakın bir zafer… Gerçeği onaylayanları müjdele."},{"n":14,"t":"Ey gerçeği onaylayanlar, ALLAH’ı destekleyenler olun. Nasıl ki Meryem oğlu İsa, öğrencilerine, \"ALLAH yolunda kim benim destekçilerim olur?\" diye sormuştu. Öğrencileri, \"Biz ALLAH’ın destekçileriyiz\" demişlerdi. İsrailoğullarından bir grup gerçeği onayladı, bir grup da inkâr etti. Gerçeği onaylayanları düşmanlarına karşı destekledik; onlar üstün geldiler."}]},{"id":62,"name":"Cum'a Suresi","verses":[{"n":1,"t":"Göklerdekilerin ve yerdekilerin hepsi ALLAH’ı yüceltir. O Egemendir, En Kutsaldır, Üstündür, Bilgedir."},{"n":2,"t":"O ki, ümmilerin arasından, kendilerinden olan bir elçi göndermiştir ki onlara O’nun ayetlerini okuyor, onları temizliyor ve onlara kitabı ve bilgeliği öğretiyor. Bundan önce onlar apaçık bir sapıklık içinde bulunuyorlardı."},{"n":3,"t":"Ve henüz kendilerine katılmamış bulunan başkalarına da… O Üstündür, Bilgedir."},{"n":4,"t":"Bu, ALLAH’ın lütfudur; dileyene ve/veya dilediğine verir. ALLAH büyük lütuf sahibidir."},{"n":5,"t":"Kendilerine Tevrat verilip de onun gereğini yerine getirmeyenlerin örneği, kitaplar taşıyan eşeğin durumuna benzer. ALLAH’ın ayetlerini yalanlayan topluluğun durumu ne kötüdür. ALLAH zalim toplumu doğruya ulaştırmaz."},{"n":6,"t":"De ki: \"Ey Yahudiler, halkın arasından yalnız kendinizin ALLAH’ın dostları olduğunuzu iddia ediyorsanız, ölümü dileyin; doğru iseniz.\""},{"n":7,"t":"Onlar, yapmış olduklarından ötürü hiçbir vakit onu dileyemeyeceklerdir. ALLAH zalimleri iyi bilir."},{"n":8,"t":"De ki: \"Kaçmakta olduğunuz ölüm, mutlaka size ulaşacak ve daha sonra gizliyi ve açığı Bilenin huzuruna döndürüleceksiniz. Yaptığınız her şeyi size bildirecektir."},{"n":9,"t":"Ey gerçeği onaylayanlar, cuma (toplantı) günü namaza çağrıldığınızda ALLAH’ı anmak için acele edin ve alışverişi bırakın. Bilseniz, bu sizin için daha iyidir."},{"n":10,"t":"Namaz bitince, yeryüzüne yayılarak ALLAH’ın lütfunu arayın ve ALLAH’ı sürekli anmaya devam edin."},{"n":11,"t":"Bazıları, bir ticaret veya bir eğlence gördükleri zaman, seni ayakta bırakıp oraya akın ettiler. De ki: \"ALLAH’ın yanında bulunanlar eğlenceden ve ticaretten daha iyidir. ALLAH en iyi rızık verendir.\""}]},{"id":63,"name":"Munafikun Suresi","verses":[{"n":1,"t":"İkiyüzlüler sana geldiklerinde, \"Senin ALLAH elçisi olduğuna şehadet ederiz\" derler. ALLAH senin kendi elçisi olduğunu bilir ve ALLAH ikiyüzlülerin yalan söylediğine de şehadet eder."},{"n":2,"t":"Onlar, yeminlerini kalkan yapıp ALLAH’ın yolundan saptırmaktadırlar. Yaptıkları ne kötüdür."},{"n":3,"t":"Çünkü onlar gerçeği onayladıktan sonra inkâr ettiler; bu yüzden kalpleri mühürlendi; onlar anlamazlar."},{"n":4,"t":"Onları gördüğün zaman, görünüşleri hoşuna gider. Konuşurlarsa sözlerini dinlersin. Onlar, dikilip dayanmış kütükler gibidir. Her gürültüyü kendi aleyhlerine sanarlar; onlar gerçek düşmandır; onlardan sakın. ALLAH onları kahretsin; nasıl da çevriliyorlar!"},{"n":5,"t":"Onlara, \"Gelin de ALLAH’ın elçisi sizin için bağışlanma dilesin\" denildiğinde, başlarını çevirirler; büyüklük taslayarak saptıklarını görürsün."},{"n":6,"t":"Onlar için bağışlanma dilesen de dilemesen de birdir; ALLAH onları bağışlamayacaktır. ALLAH yoldan çıkmış topluluğu doğruya ulaştırmaz."},{"n":7,"t":"Onlar, \"ALLAH’’ın elçisinin yanında bulunanlara yardım etmeyin ki dağılıp gitsinler\" diyenlerdir. Oysa göklerin ve yerin hazineleri ALLAH’a aittir; ama ikiyüzlüler kavrayamazlar."},{"n":8,"t":"\"Kente dönersek, üstün olanlar alçakları çıkaracaktır\" diyorlar. Oysa üstünlük ALLAH’a, elçisine ve gerçeği onaylayanlara aittir. Ne var ki ikiyüzlüler bilmezler."},{"n":9,"t":"Ey gerçeği onaylayanlar, paralarınız ve çocuklarınız sizi ALLAH’ı anmaktan alıkoymasın. Böyle davrananlar kaybedenlerdir."},{"n":10,"t":"Size ölüm gelip de, \"Efendim keşke beni kısa bir süre için ertelesen de, yoksullara yardım ederek erdemlilerden olsam\" demeden önce verdiğimiz rızıklardan yardım için veriniz."},{"n":11,"t":"ALLAH süresi geldiği zaman hiçbir canı ertelemez. ALLAH yaptıklarınızdan Haberdardır."}]},{"id":64,"name":"Teğabun Suresi","verses":[{"n":1,"t":"Göklerde ve yerde ne varsa ALLAH’ı yüceltir. Yönetim O’nundur, övgü O’nadır. O her şeye Gücü yetendir."},{"n":2,"t":"Sizi O yarattı. Sonra kiminiz inkârcı olur, kiminiz de gerçeği onaylar. ALLAH tüm yaptıklarınızı Görendir."},{"n":3,"t":"Gökleri ve yeri belli bir amaç için yaratmış, size biçim vermiş ve biçiminizi güzelleştirmiştir. Dönüş O’nadır."},{"n":4,"t":"Göklerde ve yerde olanları bilir; sizin gizlediklerinizi ve açığa vurduklarınızı da bilir. ALLAH gizli düşüncelerinizi çok iyi bilir."},{"n":5,"t":"Daha önce inkâr edip de yaptıklarının karşılığını tadanların haberi size ulaşmadı mı? Onlara acı bir azap vardır."},{"n":6,"t":"Çünkü, elçileri onlara apaçık kanıtlarla gidiyorlar ve onlar ise, \"Bize doğru yolu bir insan mı gösterecek?\" diyorlardı. Böylece inkâr edip yüz çeviriyorlardı. ALLAH hiçbir şeye muhtaç değildir. ALLAH Zengindir, Övülendir."},{"n":7,"t":"İnkarcılar, diriltilmeyeceklerini ileri sürerler. De ki: \"Evet, Efendime andolsun diriltileceksiniz ve sonra yaptıklarınız size bildirilecektir. Bu, ALLAH’a kolaydır."},{"n":8,"t":"ALLAH’a, elçisini ve indirdiğimiz bu ışığı onaylayınız. ALLAH yaptıklarınızdan Haberdardır."},{"n":9,"t":"Gün gelir, sizi toplanma günü için toplarız. Bu, aldanma günüdür. Kim ALLAH’ı onaylar ve erdemli davranırsa, kötülüklerini örter ve onu altından ırmaklar akan bahçelere sokar. Orada ebedi kalırlar. Büyük başarı işte budur."},{"n":10,"t":"İnkar edenler, ayetlerimizi ve mucizelerimizi yalanlayanlar ateşin halkıdır; orada ebedi kalıcıdırlar. Ne kötü bir varış noktasıdır!"},{"n":11,"t":"Başa ne gelirse ALLAH’ın izniyledir. Kim ALLAH’ı onaylarsa, gönlüne yön gösterir. ALLAH her şeyi bilendir."},{"n":12,"t":"ALLAH’a uyunuz, elçisine uyunuz. Yüz çevirirseniz, elçimizin görevi açıkça bildirmekten ibarettir."},{"n":13,"t":"ALLAH: O’ndan başka tanrı yoktur. Gerçeği onaylayanlar yalnız ALLAH’a güvenmelidirler."},{"n":14,"t":"Ey gerçeği onaylayanlar, eşleriniz ve çocuklarınız size düşman olabilirler. Öyleyse onlardan sakının. Ama affeder, hoşgörülü davranır ve bağışlarsanız, elbette ALLAH da Bağışlayandır, Rahimdir."},{"n":15,"t":"Paralarınız ve çocuklarınız bir sınavdır. Büyük ödül ALLAH’ın yanındadır."},{"n":16,"t":"Gücünüz yettiği kadar ALLAH’ı sayın. Dinleyin, itaat edin ve kendi yararınız için yardımda bulununuz. Nefsinin bencillik ve cimriliğinden korunanlar başaranlardır."},{"n":17,"t":"ALLAH’a güzel bir ödünç sunarsanız, O da onu sizin için katlar ve sizi bağışlar. ALLAH Değer verir, Şefkatlidir."},{"n":18,"t":"Gizliyi ve açığı Bilendir; Üstündür, Bilgedir."}]},{"id":65,"name":"Talak Suresi","verses":[{"n":1,"t":"Ey peygamber, kadınları boşadığınız zaman boşama sürelerini gözetin ve bu süreyi iyice hesaplayın. Efendiniz olan ALLAH’ı dinleyin. Onları evlerinden çıkarmayın, onlar da çıkmasınlar (kötü davranarak onları buna zorlamayın). Ancak kanıtlanmış bir zina işlemeleri bunun dışındadır. ALLAH’ın yasası budur. Kim ALLAH’ın yasasını çiğnerse kendisine zulmetmiş olur. Bilmezsin, belki ALLAH bundan sonra (olumlu) bir iş ortaya çıkarır."},{"n":2,"t":"Sürelerini doldurdukları zaman, onları güzelce tutun, yahut güzelce ayırın. İçinizden adalet sahibi iki kişiyi de bu işleme tanık tutun. Tanıklığı ALLAH için yapınız. İşte bu, ALLAH’a ve ahiret gününü onaylayanlar için bir öğüttür. Kim ALLAH’ı sayıp dinlerse ona bir çıkış yolu yaratır."},{"n":3,"t":"Ve beklemediği yerden ona rızık verir. Kim ALLAH’a güvenirse O, ona yeter. ALLAH buyruğunu yerine getirendir. ALLAH her şey için bir ölçü koymuştur."},{"n":4,"t":"Menopoz dönemine girerek aybaşından kesilen kadınlarınıza gelince, kuşkunuz varsa, bekleme süreleri üç aydır. Aybaşı hali görmeyip gebe olanların süresi, yüklerini bırakmalarıyla sona erer. Kim ALLAH’ı dinlerse, onun işini kolaylaştırır."},{"n":5,"t":"Bu, ALLAH’ın size indirdiği emridir. Kim ALLAH’ı dinlerse onun kötülüklerini örter ve ödülünü büyütür."},{"n":6,"t":"O kadınları, gücünüz oranında, oturduğunuz yerde oturtun. Ayrılmaya zorlamak için onları rahatsız etmeyin. Gebe iseler, yüklerini bırakıncaya kadar onların geçimlerini sağlayın. Sizin için emzirirlerse ücretlerini ödeyin. Aranızda güzel bir ilişki kurun. Güçlükle karşılaşırsanız, onu başka bir kadın emzirecektir."},{"n":7,"t":"Varlıklı kimse varlığı oranında nafaka yardımında bulunsun. Dar gelirli ise, ALLAH’ın kendisine verdiğinden versin. ALLAH bir kimseye vermiş olduğundan fazla bir sorumluluk yüklemez. ALLAH zorluktan sonra kolaylık getirecektir."},{"n":8,"t":"Nice kentler, Rab’lerinin ve O’nun gönderdiği elçilerin emirlerine baş kaldırdı. Sonunda biz de onları çetin bir hesaba çektik ve onları görülmemiş biçimde cezalandırdık."},{"n":9,"t":"Kararlarının sonucunu tattılar. Kararlarının sonucu bir hüsran oldu."},{"n":10,"t":"ALLAH onlar için çetin bir ceza hazırlamıştır. Öyleyse, ey akıl sahibi gerçeği onaylayanlar, ALLAH’ı dinleyiniz. ALLAH size bir mesaj…"},{"n":11,"t":"Bir elçi indirmiştir. Gerçeği onaylayıp erdemli davrananları karanlıklardan aydınlığa çıkarmak için size ALLAH’ın apaçık ayetlerini okur. Kim ALLAH’ı onaylar ve erdemli davranırsa onu içinde ırmaklar akan bahçelere sokar; orada ebedi kalırlar. ALLAH ona güzel rızık vermiştir."},{"n":12,"t":"Yedi göğü ve yerden/topraktan da o kadar yaratan ALLAH’tır. Buyruklar onların arasında akıp durur. Böylece ALLAH’ın her şeye gücü yettiğini ve ALLAH’ın her şeyi bilgiyle kuşatmış olduğunu bilesiniz."}]},{"id":66,"name":"Tahrim Suresi","verses":[{"n":1,"t":"Ey peygamber, sırf eşlerini memnun etmek amacıyla, ALLAH’ın sana helal (yasal) kıldığını kendine yasaklıyorsun. ALLAH Bağışlayandır, Rahimdir."},{"n":2,"t":"ALLAH, yeminlerinizi helalleştirmenin yolunu bildirmiştir. Mevlanız (efendiniz) ALLAH’tır. O Bilendir, Bilgedir."},{"n":3,"t":"Peygamber, eşlerinden birine gizlice bir hadis söylemişti. Eşi bunu yayınca, ALLAH onu bundan haberdar kıldı. Ona durumun bir kısmını bildirmiş, bir kısmından ise vazgeçmişti. Peygamber konuyu eşine açınca eşi, \"Bunu sana kim haber verdi?\" diye sordu. \"Her şeyi Bilen ve her şeyden Haberdar olan bana bildirdi\" diye cevapladı."},{"n":4,"t":"İkiniz ALLAH’a tövbe ederseniz kalbiniz yönelmiş olur. Ona (elçiye) karşıt olarak birbirinizi desteklerseniz, onun Mevlası (koruyucusu/efendisi) ALLAH’tır; Cibril, erdemli gerçeği onaylayanlar ve melekler de onu destekler."},{"n":5,"t":"Sizi boşarsa, Rabbi ona, belki sizin yerinize sizden daha iyi, (Tanrı’ya) teslim olanlar, gerçeği onaylayanlar, adayanlar, yönelenler, hizmet edenler, aktif olanlar, duyarlılar ve öncüler verir."},{"n":6,"t":"Ey gerçeği onaylayanlar, yakıtı halk ve taşlar olan ateşten kendinizi ve ailenizi koruyun. Ateşin üzerinde sert ve güçlü melekler olup, ALLAH’ın buyruğuna karşı gelmezler ve kendilerine ne emredilmişse onu uygularlar."},{"n":7,"t":"Ey inkârcılar, bugün özür beyan etmeyin. Siz, ancak yapmış olduklarınızın karşılığını görmektesiniz."},{"n":8,"t":"Ey gerçeği onaylayanlar, ALLAH’a yürekten tövbe edin ki Efendiniz kötülüklerinizi örtsün ve altından ırmaklar akan bahçelere soksun. ALLAH, o gün peygamberi ve beraberinde bulunanları utandırmaz. Işıkları, önlerinden sağ yanlarına doğru yayılır ve, \"Efendimiz, bizim için ışığımızı tamamla ve bizi bağışla; sen her şeye gücü yetensin\" derler."},{"n":9,"t":"Ey peygamber, kafirlere ve ikiyüzlülere karşı savaşım ver ve onlara karşı sert davran. Yerleri cehennemdir. O ne kötü duraktır."},{"n":10,"t":"ALLAH inkârcılara, Nuh’un karısı ile Lut’un karısını örnek verir. İki erdemli kulumuzun nikahı altında bulunuyorlardı; ancak onlara ihanette bulundular. Kocaları ALLAH’tan gelen hiçbir şeyi o ikisinden savamadı. İkisine de \"Girenlerle birlikte cehenneme girin\" denildi."},{"n":11,"t":"ALLAH gerçeği onaylayanlara, Firavunun hanımını örnek verir. O, \"Efendim, benim için bahçede bir ev kur ve beni Firavundan ve yaptıklarından kurtar; beni bu zalim halktan kurtar\" demişti."},{"n":12,"t":"Ve İmran kızı Meryem de… O, iffetini korudu, biz de ruhumuzdan ona üfledik. O Efendisinin kelimelerini ve kitaplarını onayladı; itaat edenlerden oldu."}]},{"id":67,"name":"Mülk Suresi","verses":[{"n":1,"t":"Yönetimi elinde bulunduran çok yücedir. O her şeye Kadirdir."},{"n":2,"t":"Hanginizin daha güzel işler yapacağını sınamak için ölümü ve hayatı yaratandır. O, Üstündür, Bağışlayandır."},{"n":3,"t":"O yedi göğü biriyle uyumlu evreler yaratmıştır. Rahman’ın yaratışında herhangi bir kusur bulamazsın. Bakışlarını yönelt de bak; herhangi bir çatlak görebiliyor musun?"},{"n":4,"t":"Sonra tekrar tekrar bak; bakışların usanmış ve yenilmiş olarak sana döner."},{"n":5,"t":"En aşağı göğü lambalarla süsledik ve onları sapkınlar için bir taşlama/kovma kıldık. Onlara alevli ateş azabını hazırladık."},{"n":6,"t":"Rab’lerini inkâr edenler cehennem cezasını hak etmişlerdir. Ne kötü bir duraktır."},{"n":7,"t":"Oraya atıldıkları zaman, onun kaynayıp tüterken uğultusunu işittiler."},{"n":8,"t":"Nerede (nerdeyse) ise öfkeden patlayacak! İçine her ne zaman bir grup atılsa, oranın gardiyanları, \"Size bir uyarıcı gelmedi mi?\" diye sordular."},{"n":9,"t":"Onlar da dediler ki, \"Evet, bize bir uyarıcı gelmişti, ama biz yalanladık ve ‘ALLAH hiçbir şey indirmemiştir. Siz tümüyle sapıtmışsınız,’ dedik.\""},{"n":10,"t":"\"Dinleseydik veya aklımızı kullansaydık biz şu ateşin halkı içinde olmazdık\" dediler."},{"n":11,"t":"Böylece günahlarını itiraf ettiler. Ateşin halkı uzak olsunlar."},{"n":12,"t":"Kendi başlarına iken Rab’lerine saygı duyanlar için bir bağışlanma ve büyük bir ödül vardır."},{"n":13,"t":"İsterseniz sözünüzü gizleyin veya onu açıklayın; O gizli düşüncelerinizi çok iyi Bilir."},{"n":14,"t":"Hiç Yaratan yarattığını bilmez mi? O, Latiftir, Haberdardır."},{"n":15,"t":"O ki yeri emriniz altına verdi. Yeryüzünü dolaşın ve onun besinlerinden yiyin. Son dönüş O’nadır."},{"n":16,"t":"Yoksa, aniden sallanmaya başlayacak olan yerin dibine sizi batırmayacağına dair göktekinden güvence mi aldınız?"},{"n":17,"t":"Aynı şekilde, üstünüze gökten taş yağdıran bir fırtına göndermeyeceğine dair göktekinden güvence mi aldınız? Uyarının nasıl olduğunu öğreneceksiniz."},{"n":18,"t":"Onlardan öncekiler de inkâr etmişti. Beni tanımamak da nasılmış?"},{"n":19,"t":"Üzerlerinde düzenli sıralar halinde kanat çırpan kuşları görmezler mi? Rahman’dan başkası onları tutmuyor. O her şeyi Görendir."},{"n":20,"t":"Rahman’ın dışında size yardım edecek o ordularınız nerede? Gerçekten, inkârcılar bir aldanma içindedirler."},{"n":21,"t":"O, verdiği besinleri kesse, sizi besleyecek olan kimdir? Gerçekten azgınlık ve nefret içinde direnmektedirler."},{"n":22,"t":"Yüzüstü sürünen mi, yoksa dosdoğru yol üzerinde düzgün bir biçimde yürüyen mi daha doğru yoldadır?"},{"n":23,"t":"De ki: \"Sizi yaratan, size duyma, görme duyuları ve beyinler veren O’dur. Ne kadar seyrek şükredersiniz!\""},{"n":24,"t":"De ki: \"Sizi yeryüzünde üreten O’dur ve siz O’nun huzurunda toplanacaksınız.\""},{"n":25,"t":"\"Doğru iseniz, bu söz ne zaman gerçekleşecek?\" derler."},{"n":26,"t":"De ki: \"Bu bilgi ALLAH’ın katındadır. Ben sadece apaçık bir uyarıcıyım.\""},{"n":27,"t":"Onu yaklaşırken gördükleri zaman inkârcıların suratı asılır ve onlara \"İşte isteyip durduğunuz şey budur\" denir."},{"n":28,"t":"De ki: \"Baksanıza, ALLAH yanımdakilerle birlikte beni helak etse de, yahut bize acısa da, inkârcıları acı azaptan kim kurtarabilir?\""},{"n":29,"t":"De ki: \"O Rahman’dır; biz O’nu onayladık ve O’na güvendik. Kimin gerçekten tam bir sapıklık içinde olduğunu ileride öğreneceksiniz.\""},{"n":30,"t":"De ki: \"Hiç düşündünüz mü ki: suyunuz çekilse, size kim temiz bir su getirebilir?\""}]},{"id":68,"name":"Kalem Suresi","verses":[{"n":1,"t":"Nun, kaleme ve yazdıklarına andolsun."},{"n":2,"t":"Sen Efendinin nimetiyle delirmiş değilsin."},{"n":3,"t":"Senin için kesintisiz bir ödül vardır."},{"n":4,"t":"Kuşkusuz sen üstün ahlaki standartlar üzeresin."},{"n":5,"t":"Sen de göreceksin, onlar da görecekler;"},{"n":6,"t":"Hanginizin şaşkın olduğunu."},{"n":7,"t":"Efendin, kimin yolundan sapmış olduğunu da en iyi bilir, doğru yolda olanları da en iyi bilir."},{"n":8,"t":"Öyleyse yalanlayanlara uyma."},{"n":9,"t":"Kendilerinin ödün verip uzlaşabilmesi için senin de ödün verip uzlaşmanı istediler."},{"n":10,"t":"Şunların hiçbirine uyma: yemin edip duran, aşağılık,"},{"n":11,"t":"İftiracı, söz götürüp getiren,"},{"n":12,"t":"İyiliğe ve yardıma engel olan, saldırgan, günahkar."},{"n":13,"t":"İnsafsız ve sahtekâr."},{"n":14,"t":"Mal ve çocuk sahibidir diye (onlara uyma)."},{"n":15,"t":"Ayetlerimiz kendisine okunduğu zaman, \"Efsane\" der."},{"n":16,"t":"Onun burnunu işaretleyeceğiz."},{"n":17,"t":"Onları sınadık; tıpkı bahçe sahiplerini sınadığımız gibi. Sabahleyin devşireceklerine yemin etmişlerdi."},{"n":18,"t":"Bundan hiçbir kuşkuları yoktu."},{"n":19,"t":"Onlar uykudayken Efendin tarafından gönderilen bir ziyaretçi (fırtına) bahçelerini ziyaret etti."},{"n":20,"t":"Ve bahçe meyvesiz kalmıştı."},{"n":21,"t":"Sabahleyin birbirlerine seslendiler:"},{"n":22,"t":"\"Devşirecekseniz, haydi ekinlerinize erken varın.\""},{"n":23,"t":"Derken yola çıktılar, aralarında konuşuyorlardı."},{"n":24,"t":"\"Sakın, bugün hiçbir yoksul oraya yanınıza girmesin.\""},{"n":25,"t":"Sonuçtan emin bir halde erken vardılar."},{"n":26,"t":"Fakat bahçeyi görünce, \"Biz yolu şaşırdık\" dediler."},{"n":27,"t":"\"Yok, doğrusu biz yoksun bırakıldık.\""},{"n":28,"t":"Ortancaları (erdemlileri), \"Ben size demedim mi? Efendinizi yüceltmeniz gerekmez miydi?\" dedi."},{"n":29,"t":"Dediler ki, \"Efendimiz yücedir. Biz zalimler imişiz.\""},{"n":30,"t":"Ve hemen birbirlerini suçlamaya başladılar."},{"n":31,"t":"Dediler ki, \"Yazıklar olsun bize. Azgınmışız.\""},{"n":32,"t":"\"Belki Efendimiz bize daha iyisini verir. Biz Efendimize dönüyoruz.\""},{"n":33,"t":"İşte azap böyledir. Ahiret azabı ise daha büyüktür. Bir bilselerdi."},{"n":34,"t":"Erdemliler, Rab’lerinden nimet bahçeleri haketmişlerdir."},{"n":35,"t":"Müslümanlara suçlular gibi mi davranalım?"},{"n":36,"t":"Neyiniz var, ne biçim hüküm veriyorsunuz?"},{"n":37,"t":"Yoksa bir kitabınız var da onu mu okuyup duruyorsunuz?"},{"n":38,"t":"Ve içinde her dilediğinizi bulabiliyorsunuz?"},{"n":39,"t":"Yoksa, dilediğiniz hükmü verebileceğinize dair Diriliş Gününe kadar sürecek bir güvence mi aldınız bizden?"},{"n":40,"t":"Sor onlara, \"Bunu kim garanti etmektedir?\""},{"n":41,"t":"Yoksa onların ortakları mı var? Haydi ortaklarını getirsinler, eğer doğru kimseler iseler?"},{"n":42,"t":"Gün gelecek, onların içyüzleri açığa çıkarılacak, secdeye çağrılacaklar; ancak buna güçleri yetmeyecektir."},{"n":43,"t":"Gözleri düşmüş bir durumda, onları aşağılanma kaplar. Oysa onlar sağlam iken secdeye çağrılmışlardı."},{"n":44,"t":"Bu hadisi (sözü) yalanlayanla Beni başbaşa bırak. Onları, bilmedikleri yerden yavaş yavaş yaklaştıracağız."},{"n":45,"t":"Onlara mühlet veriyorum. Benim planım sağlamdır."},{"n":46,"t":"Yoksa sen onlardan bir ücret istiyorsun da onlar ağır bir borç altında mı kalıyorlar?"},{"n":47,"t":"Yoksa geçmişin ve geleceğin bilgisi onların yanında da onlar mı kaydediyorlar?"},{"n":48,"t":"Efendinin hükmünün gerçekleşmesi için sabret. Balığın arkadaşı (Yunus) gibi olma. Hani o, (balık tarafından) yutulmuş bir durumda iken seslenmişti."},{"n":49,"t":"Efendisinden ona bir nimet ulaşmasaydı, kınanmış olarak çorak bir sahile atılacaktı."},{"n":50,"t":"Ancak Rabbi onu seçip erdemlilerden kıldı."},{"n":51,"t":"Mesajı işittikleri zaman, inkârcılar neredeyse seni gözleriyle yiyeceklerdi. \"O, delidir!\" diyorlardı."},{"n":52,"t":"Halbuki o, tüm evrene bir mesajdır."}]},{"id":69,"name":"Hakka Suresi","verses":[{"n":1,"t":"Gerçekleşen (olay)."},{"n":2,"t":"Nedir o gerçekleşen?"},{"n":3,"t":"Gerçekleşenin ne olduğunu nerden bileceksin?"},{"n":4,"t":"Semud ve Ad (halkı) sarsıcı olayı yalanladı."},{"n":5,"t":"Ve Semud o azgın (sarsıntı) ile yok edildi."},{"n":6,"t":"Ad ise sert ve azgın bir kasırga ile yok edildi."},{"n":7,"t":"Onu, yedi gece ve sekiz gün boyunca üzerlerine bir bela olarak saldı. Halkın, çürümüş hurma gövdeleri gibi yere yıkıldıklarını görürsün."},{"n":8,"t":"Onların hiçbir kalıntısını görüyor musun?"},{"n":9,"t":"Firavun, ondan öncekiler ve altüst olan (Sodomlu)lar da kötülük işlemişti."},{"n":10,"t":"Rab’lerinin elçisine isyan ettiler. Bunun sonucu olarak da onları şiddeti gittikçe artan bir biçimde yakalamıştı."},{"n":11,"t":"Su taşınca sizi akıp giden (sal) üzerinde taşımıştık."},{"n":12,"t":"Ki o size bir ders olsun ve dinleyen kulaklar anlasın."},{"n":13,"t":"Boruya bir kez üfürüldüğü zaman,"},{"n":14,"t":"Yer ve dağlar kaldırılıp birbirine çarpılıp darmadağın edildiği zaman,"},{"n":15,"t":"İşte o gün kaçınılmaz olay gerçekleşmiştir."},{"n":16,"t":"Gök yarılmıştır, parçalanmıştır."},{"n":17,"t":"Denetçiler her yandadır. Efendinin yönetimi o gün sekiz (evren) üzerinde egemen olacaktır."},{"n":18,"t":"O gün ortaya çıkarılırsınız ve hiçbir şeyiniz gizli kalmaz."},{"n":19,"t":"Kitabı sağından verilen, \"Alın kitabımı okuyun\" der,"},{"n":20,"t":"\"Hesabımla karşılaşacağımı bekliyordum.\""},{"n":21,"t":"O mutlu bir yaşantı içindedir,"},{"n":22,"t":"Yüksek bir bahçede,"},{"n":23,"t":"Meyveleri ulaşılabilecek mesafededir."},{"n":24,"t":"Geçmiş günlerinizde yaptığınız işlerden ötürü afiyetle yiyiniz, içiniz."},{"n":25,"t":"Kitabı solundan verilenlere gelince, onlar, \"Keşke kitabım bana verilmeseydi\" der,"},{"n":26,"t":"\"Hesabımın ne olduğunu öğrenmeyeydim.\""},{"n":27,"t":"\"Keşke ölümüm sonum olsaydı.\""},{"n":28,"t":"\"Param bana yaramadı.\""},{"n":29,"t":"\"Tüm gücümü yitirdim.\""},{"n":30,"t":"Yakalayın, bağlayın onu."},{"n":31,"t":"Ve sonra cehennemde yakın."},{"n":32,"t":"Sonra, onu yetmiş arşın boyunda bir zincire vurun."},{"n":33,"t":"Çünkü o, Yüce ALLAH’ı onaylamıyordu."},{"n":34,"t":"Yoksullara yedirmeye de çalışmıyordu."},{"n":35,"t":"Bu yüzden onun buralarda bir dostu yoktur."},{"n":36,"t":"Hiçbir yiyeceği de… İrin hariç,"},{"n":37,"t":"Onu ancak günahkarlar yer."},{"n":38,"t":"Yemin ederim gördüklerinize,"},{"n":39,"t":"Ve görmediklerinize,"},{"n":40,"t":"Ki bu şerefli bir elçinin (getirdiği) sözdür."},{"n":41,"t":"O bir şair sözü değildir; ne de az onaylıyorsunuz?"},{"n":42,"t":"Kahin sözü de değildir; ne de az düşünüyorsunuz?"},{"n":43,"t":"Evrenlerin Efendisinden indirilmedir."},{"n":44,"t":"O bize bazı sözler yakıştırsa,"},{"n":45,"t":"Biz onu kuvvetle yakalar,"},{"n":46,"t":"Sonra, ondan vahyi keserdik."},{"n":47,"t":"Ve sizden kimse de buna engel olamazdı."},{"n":48,"t":"Kuşkusuz bu, erdemliler için bir hatırlatmadır."},{"n":49,"t":"İçinizden yalanlayanlar olduğunu iyi biliyoruz."},{"n":50,"t":"O, inkârcılar için bir üzüntü kaynağıdır."},{"n":51,"t":"O, kuşkusuz mutlak gerçektir."},{"n":52,"t":"Öyleyse Büyük olan Efendinin ismini yücelt."}]},{"id":70,"name":"Me'aric Suresi","verses":[{"n":1,"t":"Sorgulayan birisi, gerçekleşecek azabı sordu."},{"n":2,"t":"Onu inkârcılardan savacak kimse yoktur."},{"n":3,"t":"Yükseliş Yollarının Sahibi olan ALLAH’tandır."},{"n":4,"t":"Denetçiler ve ruh (vahiy/komutlar/Cebrail), elli bin yıla eşit birgün içinde O’na yükselir."},{"n":5,"t":"Şimdi sen güzelce sabret."},{"n":6,"t":"Onlar onu uzak görüyorlar."},{"n":7,"t":"Biz ise onu yakın görüyoruz."},{"n":8,"t":"Gün gelecek, gök erimiş maden gibi."},{"n":9,"t":"Dağlar ise atılmış yün gibi olur."},{"n":10,"t":"Dost dostun durumunu sormaz."},{"n":11,"t":"Birbirlerine gösterilirler. Suçlu, o günün azabından kurtulmak için fidye vermek ister: Oğullarını,"},{"n":12,"t":"Eşini, kardeşini,"},{"n":13,"t":"Kendisini yetiştiren tüm akrabalarını,"},{"n":14,"t":"Ve yeryüzünde bulunan herkesi, ki kurtulsun."},{"n":15,"t":"Hayır, o alevli ateştir."},{"n":16,"t":"Yakmak için isteklidir…"},{"n":17,"t":"Çağırır, sırtını dönüp gideni,"},{"n":18,"t":"Toplayıp kasaya saklayanı."},{"n":19,"t":"Doğrusu insan endişeli bir karaktere sahiptir."},{"n":20,"t":"Kendisine kötülük dokunduğu zaman ümidini keser."},{"n":21,"t":"Kendisine iyilik dokunduğu zaman ise cimridir."},{"n":22,"t":"Ancak namaz kılanlar hariç:"},{"n":23,"t":"Onlar ki namazlarını kaçırmazlar;"},{"n":24,"t":"Paralarında bilinen bir pay (zekat) ayrılmıştır,"},{"n":25,"t":"İsteyen yoksula ve yoksuna…"},{"n":26,"t":"Onlar Din Gününü doğrularlar;"},{"n":27,"t":"Rab’lerinin azabından çekinirler;"},{"n":28,"t":"Rab’lerinin azabına güven olmaz."},{"n":29,"t":"Onlar cinsel ilişkiden sakınırlar;"},{"n":30,"t":"Ancak eşleri, yani yeminlerinin/anlaşmalarının hak sahibi oldukları hariç; onlardan dolayı yerilmezler"},{"n":31,"t":"- bunun ötesini arayanlar ise aşırı gidenlerdir-"},{"n":32,"t":"Onlar güvenilirdirler, sözlerine bağlıdırlar;"},{"n":33,"t":"Gereği gibi tanıklıkta bulunurlar;"},{"n":34,"t":"Namazlarına özen gösterirler."},{"n":35,"t":"Onlar bahçelerde ağırlanırlar."},{"n":36,"t":"Peki şimdi inkârcılara ne oluyor da senin önünde koşuşuyorlar?"},{"n":37,"t":"Sağdan, soldan gruplar halinde…"},{"n":38,"t":"Her biri, nimet bahçesine sokulacağını mı umuyor?"},{"n":39,"t":"Asla; biz onları yarattık, bildikleri şeyden…"},{"n":40,"t":"Doğuların ve batıların Efendisine andolsun; bizim gücümüz yeter…"},{"n":41,"t":"Onları, kendilerinden daha iyilerle değiştirmeye… Bizi kimse yenemez."},{"n":42,"t":"Bırak onları, kendilerine söz verilen gün ile karşı karşıya gelinceye kadar dalsınlar, oynasınlar."},{"n":43,"t":"O gün mezarlarından hızlı hızlı çıkarlar; kurban taşına sürülüyorlarmış gibi…"},{"n":44,"t":"Gözleri dönmüş, kendilerini utanç sarmış olarak. İşte bu, onlara söz verilmiş olan gündür."}]},{"id":71,"name":"Nuh Suresi","verses":[{"n":1,"t":"\"Kendilerine acı azap gelmezden önce halkını uyar\" diye Nuh’u halkına gönderdik."},{"n":2,"t":"Dedi ki, \"Ey halkım, ben size apaçık bir uyarıcıyım.\""},{"n":3,"t":"\"ALLAH’a hizmet edin, O’nu sayın ve beni izleyin.\""},{"n":4,"t":"\"Ki günahlarınızı bağışlasın ve sizi belli bir süreye kadar ertelesin. Kuşkusuz, ALLAH’ın verdiği süre gelince ertelenmez; bir bilseydiniz.\""},{"n":5,"t":"Dedi ki, \"Efendim, ben halkımı gece gündüz çağırdım.\""},{"n":6,"t":"\"Ne var ki, çağrım onların kaçışını arttırmaktan başka şeye yaramadı.\""},{"n":7,"t":"\"Her ne zaman senin onları bağışlaman için onları çağırdıysam parmaklarını kulaklarına tıkadılar, elbiselerini başlarına örttüler, direndiler, büyüklendikçe büyüklendiler.\""},{"n":8,"t":"\"Sonra onları açıkça çağırdım.\""},{"n":9,"t":"\"Sonra onlara ilan ettim, gizliden gizliye de konuştum.\""},{"n":10,"t":"\"Dedim ki, «Efendinizden bağışlanma dileyin; O çok Bağışlayandır.»"},{"n":11,"t":"«Size gökten bol yağmur göndersin.»"},{"n":12,"t":"«Sizi bol para ve çocuklarla desteklesin, size bahçeler ve ırmaklar versin.»"},{"n":13,"t":"Size ne oluyor ki ALLAH’a saygı göstermek istemiyorsunuz?"},{"n":14,"t":"Oysa sizi evrimler halinde yaratan O’dur."},{"n":15,"t":"ALLAH’ın yedi göğü tabakalar halinde nasıl yarattığını görmez misiniz?"},{"n":16,"t":"Ayı bunların içinde bir ışık, güneşi de bir lamba yaptı."},{"n":17,"t":"Ve ALLAH sizi topraktan bir bitki olarak bitirdi."},{"n":18,"t":"Sonra sizi ona döndürecek ve sizi tekrar çıkaracaktır."},{"n":19,"t":"ALLAH yeryüzünü sizin için bir yerleşim yeri yaptı."},{"n":20,"t":"Ki orada geniş yollarda gidesiniz."},{"n":21,"t":"Nuh dedi ki, \"Efendim, onlar bana karşı geldiler ve parası, çocukları kendisine sadece zarar veren bir kimseye uydular.\""},{"n":22,"t":"\"Ve hatta büyük tuzaklar kurdular.\""},{"n":23,"t":"\"Dediler ki, ’Tanrılarınızı terketmeyin. Ne Vedd’i, ne Suva’ı, ne Yeğus’u, Yeuk’u ve Nesr’i bırakmayın.’»"},{"n":24,"t":"\"Çok kişiyi saptırdılar. Öyleyse, sen de zalimlerin şaşkınlığını arttır.\""},{"n":25,"t":"Suçlarından ötürü boğuldular ve ateşe sokuldular. Kendilerine ALLAH’tan başka yardımcı da bulamadılar."},{"n":26,"t":"Nuh dedi ki, \"Efendim, yeryüzünde bir tek inkârcı bırakma.\""},{"n":27,"t":"\"Onları bırakırsan kullarını saptırırlar ve ancak bayağı inkârcılar doğururlar.\""},{"n":28,"t":"\"Efendim, beni, anamı babamı, gerçeği onaylayan olarak evime girenleri, gerçeği onaylayan erkek ve kadınları bağışla; zalimlerin ise ancak yıkımlarını arttır.\""}]},{"id":72,"name":"Cin Suresi","verses":[{"n":1,"t":"De ki: \"Bana vahyedildiğine göre, cinlerden bir grup dinlediler ve şöyle dediler:\" \"Biz ilginç bir Kuran işittik.\""},{"n":2,"t":"\"O doğruya iletiyor ve biz onu onayladık; bundan böyle Efendimize hiç kimseyi ortak koşmayacağız.\""},{"n":3,"t":"\"Efendimiz çok yücedir. O ne bir eş ne de bir çocuk edinmiştir.\""},{"n":4,"t":"\"ALLAH hakkında saçma şeyler söyleyip duran bizim o beyinsizdi.\""},{"n":5,"t":"\"İnsanların ve cinlerin ALLAH’a karşı yalan uyduramayacaklarını sanmıştık.\""},{"n":6,"t":"\"Ne var ki bazı insanlar, bazı cinlere sığınırlardı ve bu da onların azgınlıklarını arttırırdı.\""},{"n":7,"t":"\"Onlar, tıpkı sizin sandığınız gibi, ALLAH’ın hiçbir kimseyi göndermeyeceğini sanıyorlardı.\""},{"n":8,"t":"\"Biz göğe dokunduk ve onu güçlü bekçilerle ve ateş toplarıyla korunmuş bulduk.\""},{"n":9,"t":"\"Biz orada casusluk için otururduk. Ancak şimdi her kim dinlemek isterse kendisini gözleyen bir ateş topu bulur.\""},{"n":10,"t":"\"Yerdekiler için bir kötülük mü planlanmıştır, yoksa Rab’leri onlar için bir iyilik mi dilemiştir, bilmiyoruz.\""},{"n":11,"t":"\"Aramızda erdemliler de var, bunun aşağısında olanlar da var; biz çeşitli tarikatlara(yollara) ayrıldık.\""},{"n":12,"t":"\"Biz, yeryüzünde ALLAH’ı aciz bırakamayacağımızı, kaçmakla da O’nu atlatamayacağımızı anladık.\""},{"n":13,"t":"\"Biz, yol gösteren (Kuran)ı işitir işitmez onu onayladık. Efendisini onaylayan hiçbir haksızlığa ve sıkıntıya uğramaz.\""},{"n":14,"t":"\"Aramızdan Müslümanlar da var uzlaşmacılar da vardır.\" Kim teslim olursa, işte gerçeği araştıranlar onlardır."},{"n":15,"t":"Uzlaşmacılara gelince, cehenneme odun olmuşlardır."},{"n":16,"t":"Doğru yola girselerdi onlara bol su verirdik."},{"n":17,"t":"Ki onunla onları sınayalım. Kim Efendisinin mesajından yüz çevirirse onu zorlu ve katlanarak artan bir cezaya çarptırırız."},{"n":18,"t":"Mescidler sadece ALLAH’a aittir; öyleyse ALLAH ile birlikte hiç kimseyi çağırmayın."},{"n":19,"t":"ALLAH’ın kulu kalkıp sadece O’na çağırdığında ona karşı nerdeyse hepsi bir bütün oldular."},{"n":20,"t":"De ki: \"Ben sadece Efendime çağırırım; ve O’na hiç kimseyi ortak koşmam.\""},{"n":21,"t":"De ki: \"Ben size ne zarar verme, ne de sizi doğruya iletme (irşad etme) gücüne sahibim.\""},{"n":22,"t":"De ki: \"Hiç kimse beni ALLAH’a karşı savunamaz, O’ndan başka sığınak da bulamam.\""},{"n":23,"t":"\"Ancak ALLAH’tan bir duyuruyu ve mesajını iletirim.\" Artık kim ALLAH’a ve elçisine karşı gelirse içinde ebedi kalacağı cehennem ateşini hakeder."},{"n":24,"t":"Kendilerine söz verilen şeyi gördüklerinde kimin yardımcısının güçsüz ve sayıca az olduğunu görecekler."},{"n":25,"t":"De ki: \"Size söz verilen yakın mıdır yoksa Efendim onun için uzun bir süre mi belirlemiştir bilmiyorum.\""},{"n":26,"t":"O geleceği bilendir; ve O sırrını hiç kimseye göstermez."},{"n":27,"t":"Ancak seçtiği bir elçi hariç; nitekim O, o elçiden önceye ve sonraya ait bir gözlem sunar."},{"n":28,"t":"Böylece, elçilerin Rab’lerinin mesajını ilettikleri ortaya çıksın. O onların yaptıklarını tümüyle kuşatmıştır ve her şeyi sayı olarak hesaplamıştır."}]},{"id":73,"name":"Müzzemmil Suresi","verses":[{"n":1,"t":"Ey bürünen,"},{"n":2,"t":"Bazı geceler hariç, geceleyin kalk."},{"n":3,"t":"Yarısında veya yarısından biraz önce."},{"n":4,"t":"Yahut yarısından biraz sonra… Kuran’ı da özenle düşüne düşüne oku."},{"n":5,"t":"Biz sana ağır bir söz bırakacağız."},{"n":6,"t":"Kuşkusuz gece fikir inşası çok daha etkili ve ifade açısından daha uygundur."},{"n":7,"t":"Seni gündüzün epeyce uğraştıracak işlerin vardır."},{"n":8,"t":"Efendinin ismini an ve tüm gönlünle O’na yönel."},{"n":9,"t":"Doğunun ve batının Rabbi; O’ndan başka tanrı yoktur. Kendine avukat olarak O’nu seç."},{"n":10,"t":"Onların sözlerine karşı sabırlı ol ve onlardan güzellikle ayrıl."},{"n":11,"t":"Varlık sahibi olup da seni yalanlayanları bana bırak; onlara biraz süre tanı."},{"n":12,"t":"Yanımızda zincirler ve cehennem vardır."},{"n":13,"t":"Yutulması güç bir yiyecek ve acı bir azap…"},{"n":14,"t":"Gün gelir, yer ve dağlar titrer ve dağlar dağılan kum yığınına dönüşür."},{"n":15,"t":"Biz, size hakkınızda tanıklık edecek bir elçi gönderdik; nasıl ki Firavuna da bir elçi göndermiştik."},{"n":16,"t":"Ancak Firavun, elçiye karşı geldi; biz de onu feci bir biçimde yakaladık."},{"n":17,"t":"Peki, inkâr ederseniz, çocukların saçlarını ağartan bir günden nasıl korunursunuz?"},{"n":18,"t":"Gök bile ondan dolayı yarılır. O’nun sözü gerçekleşir."},{"n":19,"t":"Bu bir hatırlatmadır; dileyen, Efendisine doğru yol tutar."},{"n":20,"t":"Efendin, senin ve yoldaşlarından bir grubun, gecenin üçte ikisinden az, yarısında ve üçte birinde kalktığını bilir. Gecenin ve gündüzün miktarını ALLAH belirler. O, sizin bunu yapamayacağınızı bildiği için sizi affetmiştir. Öyleyse Kuran’dan kolayınıza geldiği kadar okuyun. Aranızda hastalar, yeryüzünde ALLAH’ın lütfundan rızık arayanlar ve ALLAH yolunda savaşanlar olduğunu bilmektedir. Ondan kolayınıza geldiği kadar okuyun. Namazı gözetin, zekatı verin ve güzel davranmak yoluyla ALLAH’a bir borç sunun. Kendiniz için yaptığınız her iyiliği, ALLAH katında daha iyi ve daha büyük bir ödül olarak bulacaksınız. ALLAH’tan bağışlanma dileyin; ALLAH Bağışlayandır, Rahimdir."}]},{"id":74,"name":"Müddesir Suresi","verses":[{"n":1,"t":"Ey gizlenen,"},{"n":2,"t":"Kalk ve uyar."},{"n":3,"t":"Efendini yücelt."},{"n":4,"t":"Örtülerini temizle."},{"n":5,"t":"Kötülükten uzaklaş."},{"n":6,"t":"İhtiraslı olma."},{"n":7,"t":"Efendin için sabret."},{"n":8,"t":"Duyuru yapıldığı zaman,"},{"n":9,"t":"İşte, zorlu gün o gündür."},{"n":10,"t":"İnkarcılar için kolay değil."},{"n":11,"t":"Bir birey olarak yarattığım kişiyi bana bırak."},{"n":12,"t":"Ona hem zenginlik verdim,"},{"n":13,"t":"Hem de gözü önünde çocuklar…"},{"n":14,"t":"Ona nimetler yağdırdım."},{"n":15,"t":"Buna rağmen, daha fazlasını istiyor."},{"n":16,"t":"Asla, çünkü o, ayetlerimize karşı bir inatçı kesildi."},{"n":17,"t":"Onu sarp bir yokuşa sardıracağım."},{"n":18,"t":"Nitekim o düşündü; ölçtü biçti."},{"n":19,"t":"Kahrolası, ne biçim ölçüp biçti."},{"n":20,"t":"Kahrolası, gene ne biçim ölçüp biçti."},{"n":21,"t":"Baktı."},{"n":22,"t":"Sonra surat astı, kaşlarını çattı."},{"n":23,"t":"Ve arkasını döndü; büyüklük tasladı:"},{"n":24,"t":"\"Bu\" dedi, \"etkileyici bir büyüden başka bir şey değil.\""},{"n":25,"t":"\"Bu sadece bir insan sözüdür.\""},{"n":26,"t":"Onu Sakar’a atacağım."},{"n":27,"t":"Sakar nedir bilir misin?"},{"n":28,"t":"Ne artar, ne eksilir (tam ve mükemmel),"},{"n":29,"t":"Halklar için (evrensel) bir göstergedir/ekrandır."},{"n":30,"t":"Üzerinde ondokuz vardır."},{"n":31,"t":"Biz ateşe bekçi olarak sadece melekleri atadık. Onların sayısını (ondokuz’u) da, (1) inkârcılar için bir fitne (sınav/huzursuzluk kaynağı) yaptık, (2) kitap verilmiş olanları ikna etsin, (3) gerçeği onaylayanların onayını güçlendirsin, (4) kitap verilmiş olanlarla gerçeği onaylayanların kuşkularını ortadan kaldırsın ve (5) kalplerinde hastalık olanlarla inkârcılar da, \"ALLAH bu örnekle ne demek istiyor?\" desinler. Böylece ALLAH dilediğini/dileyeni saptırır ve dilediğini/dileyeni de doğruya iletir. Efendinin ordularını kendisinden başkası bilmez. Bu (sayı) halklara bir mesajdır."},{"n":32,"t":"Hayır, andolsun Ay’a,"},{"n":33,"t":"Geçtiği vakit geceye,"},{"n":34,"t":"Ağardığı vakit sabaha,"},{"n":35,"t":"Bu büyüklerden birisidir."},{"n":36,"t":"Halklara bir uyarıdır."},{"n":37,"t":"İlerlemek yahut geride kalmak dileyenleriniz için."},{"n":38,"t":"Her kişi kendi günahıyla mahkûm olur."},{"n":39,"t":"Ancak sağ tarafta olanlar hariç;"},{"n":40,"t":"Bahçeler içindedirler, sorarlar,"},{"n":41,"t":"Suçlulara:"},{"n":42,"t":"\"Sizi bu cezaya sokan nedir?\""},{"n":43,"t":"Diyecekler ki, \"Desteklemezdik/namaz kılmazdık\""},{"n":44,"t":"\"Yoksula da yedirmezdik.\""},{"n":45,"t":"\"Biz, boş şeylere dalanlarla birlikte dalardık.\""},{"n":46,"t":"\"Yargı gününü yalanlardık.\""},{"n":47,"t":"\"Nihayet (şimdi) kesin gerçeğe ulaştık.\""},{"n":48,"t":"Aracıların şefaati onlara bir yarar sağlamaz."},{"n":49,"t":"Öyleyse neden bu mesajdan yüz çeviriyorlar."},{"n":50,"t":"Ürkmüş zebralar gibi,"},{"n":51,"t":"Aslandan kaçan…"},{"n":52,"t":"Hayır, onlardan her biri, kendisine özel olarak açılmış sayfalar verilmesini ister."},{"n":53,"t":"Doğrusu, onlar ahiretten korkmuyor."},{"n":54,"t":"Doğrusu, bu bir öğüttür."},{"n":55,"t":"Dileyen ondan öğüt alır."},{"n":56,"t":"ALLAH dilemezse onlar öğüt alamazlar. O, erdemli davranmanın kaynağıdır; bağışlamanın kaynağıdır."}]},{"id":75,"name":"Kıyamet Suresi","verses":[{"n":1,"t":"Diriliş Gününe and içerim."},{"n":2,"t":"Sürekli özeleştiride bulunan kişiye and içerim."},{"n":3,"t":"İnsan, kemiklerini bir araya toplayamayız mı sanıyor?"},{"n":4,"t":"Evet; parmak uçlarını bile düzenlemeye gücümüz yeter."},{"n":5,"t":"Doğrusu, insan her şeyin önüne sergilenmesini ister."},{"n":6,"t":"\"Diriliş Günü ne zaman?\" diye sorar."},{"n":7,"t":"Gözün kamaştığı,"},{"n":8,"t":"Ayın tutulduğu,"},{"n":9,"t":"Ve güneş ile ay bir araya toplandığı zaman,"},{"n":10,"t":"O gün insanoğlu, \"Kaçacak yer nerede?\" der."},{"n":11,"t":"Hayır, bir sığınak yok."},{"n":12,"t":"O gün son durak Efendinin huzurudur."},{"n":13,"t":"O gün insana, yapıp yapmadığı her şey haber verilir."},{"n":14,"t":"Doğrusu, insan kendi kendisine tanıktır."},{"n":15,"t":"Birtakım özürler ortaya atsa da…"},{"n":16,"t":"Onu aceleye getirip dilini oynatma."},{"n":17,"t":"Onu toplamak da okutmak da bize düşer."},{"n":18,"t":"Biz onu okuduğumuz zaman, onun okunuşunu izle."},{"n":19,"t":"Sonra, onu açıklamak da bizim görevimizdir."},{"n":20,"t":"Ne var ki, siz geçici (dünyayı) seviyorsunuz."},{"n":21,"t":"Ahireti ise önemsemiyorsunuz."},{"n":22,"t":"O gün bazı yüzler parlar."},{"n":23,"t":"Efendisine bakar."},{"n":24,"t":"O gün bazı yüzler de vardır ki asıktır."},{"n":25,"t":"Belkemiğinin kırılacağının endişesi içindedir."},{"n":26,"t":"Doğrusu, (nefis) boğaza dayandığı,"},{"n":27,"t":"Ve, \"Çare bulan var mı?\" dendiği zaman."},{"n":28,"t":"Bunun artık o ayrılık zamanı olduğunu anlar."},{"n":29,"t":"Bacakları birbirine dolaşmıştır."},{"n":30,"t":"O gün sevk Efendisine doğrudur."},{"n":31,"t":"O ne doğruladı, ne de destekledi;"},{"n":32,"t":"Fakat yalanladı ve yüz çevirdi."},{"n":33,"t":"Sonra çalım satarak ailesine gitti."},{"n":34,"t":"Sen bunu haketmişsin."},{"n":35,"t":"Gerçekten sen bunu haketmiş bulunuyorsun."},{"n":36,"t":"İnsan, başıboş bırakılacağını mı sanıyor?"},{"n":37,"t":"Dökülen meniden bir sperm değil miydi?"},{"n":38,"t":"Ve bir embriyoya dönüştükten sonra O yaratıp biçim verdi."},{"n":39,"t":"Ve ondan erkek ve dişi olmak üzere iki çift yarattı."},{"n":40,"t":"Bunları yapanın ölüleri diriltmeye gücü yetmez mi?"}]},{"id":76,"name":"İnsan Suresi","verses":[{"n":1,"t":"İnsanın üzerinden, kendisinin anılmaya değer bir şey olmadığı bir zaman periyodu geçmemiş midir?"},{"n":2,"t":"Biz insanı bir sıvı karışımdan yarattık ki onu sınayalım. Bu yüzden onu işiten ve gören yaptık."},{"n":3,"t":"Ona yolu gösterdik ya şükredendir ya da nankör."},{"n":4,"t":"İnkarcılar için zincirler, prangalar ve alevli bir ateş hazırlamışızdır."},{"n":5,"t":"İyiler ise, kafur karıştırılmış bir kadehten içerler."},{"n":6,"t":"ALLAH’ın kullarının taşıra taşıra içtikleri bir kaynak…"},{"n":7,"t":"Onlar sözlerini yerine getirirler ve alabildiğine kötü olan bir günden korkarlar."},{"n":8,"t":"Yoksula, öksüze ve tutsağa sevdikleri yiyecekleri yedirirler."},{"n":9,"t":"\"Biz sizi ALLAH rızası için yediriyoruz. Sizden ne bir karşılık, ne de bir teşekkür beklemiyoruz.\""},{"n":10,"t":"\"Biz, suratsız ve belalı bir günden ötürü Efendimizden çekiniriz.\""},{"n":11,"t":"Nitekim, ALLAH onları o günün kötülüğünden korur ve onlara neşe ve sevinç verir."},{"n":12,"t":"Direndikleri için onları bahçe ve ipekle ödüllendirir."},{"n":13,"t":"Orada koltuklara yaslanırlar; orada ne (yakıcı) güneş ne de dondurucu soğuk görürler."},{"n":14,"t":"Ağaçların gölgesi üzerlerine sarkmış ve meyveler yaklaştırılarak koparılmaları kolaylaştırılmıştır."},{"n":15,"t":"Onlara gümüş tepsiler ve şeffaf bardaklarda sunulur."},{"n":16,"t":"Gümüşten yapılmış şeffaf bardaklar… Onları tam olarak haketmişlerdir."},{"n":17,"t":"Orada zencefil (ginger) karıştırılmış bir kadehten içirilirler."},{"n":18,"t":"Bir kaynak ki, ona \"Selsebil\" denir."},{"n":19,"t":"Onlara ölümsüz gençler servis yapacaktır. Onları görsen, kendilerini saçılmış inci sanırsın."},{"n":20,"t":"Nereye baksan nimetler ve büyük bir yönetim görürsün."},{"n":21,"t":"Üstlerinde yeşil kadifeden elbiseler ve ipekler vardır. Gümüş bilezikler takınmışlardır. Rab’leri onlara temiz bir içecek içirir."},{"n":22,"t":"Bu, ödülünüzdür ve gayretinize teşekkür edilmiştir."},{"n":23,"t":"Kuşkusuz, Kuran’ı sana bir indirişle biz indirdik."},{"n":24,"t":"Öyleyse Efendinin hükmünü izlemekte sabret; onlardan hiçbir nankör günahkara uyma."},{"n":25,"t":"Sabah akşam Efendinin ismini an."},{"n":26,"t":"Geceleyin O’na secde et ve O’nu yücelt uzunca gecelerde."},{"n":27,"t":"Bunlar şu geçici (dünya hayatını) seviyorlar ve önlerindeki ağır bir günü ise önemsemiyorlar."},{"n":28,"t":"Onları biz yarattık ve yerleştirdik. Dilediğimiz zaman da onları benzerleriyle değiştiririz."},{"n":29,"t":"Bu bir hatırlatmadır: Dileyen, Efendisine varan bir yol tutar."},{"n":30,"t":"ALLAH dilemedikçe siz dileyemezsiniz. ALLAH Bilendir, Bilgedir."},{"n":31,"t":"O, dilediğini/dileyeni Rahmetine sokar. Zalimlere ise acı bir ceza hazırlamıştır."}]},{"id":77,"name":"Mürselat Suresi","verses":[{"n":1,"t":"Andolsun ard arda gönderilenlere,"},{"n":2,"t":"Esip savuranlara,"},{"n":3,"t":"Yaydıkça yayanlara,"},{"n":4,"t":"Ayırdıkça ayıranlara,"},{"n":5,"t":"Mesajı verenlere,"},{"n":6,"t":"Bir müjde veya uyarı olarak…"},{"n":7,"t":"Size söz verilenler kesinlikle gerçekleşecektir."},{"n":8,"t":"Yıldızlar söndürüldüğü,"},{"n":9,"t":"Göğün yarıldığı,"},{"n":10,"t":"Dağların ufalanıp savrulduğu,"},{"n":11,"t":"Ve elçilere randevu verildiği zaman,"},{"n":12,"t":"Belirlenen gün için…"},{"n":13,"t":"Yani Karar Günü için!"},{"n":14,"t":"O nasıl bir yargılama günüdür bilir misin?"},{"n":15,"t":"Yalanlayanların vay haline o gün!"},{"n":16,"t":"Öncekileri helak etmedik mi?"},{"n":17,"t":"Sonra, diğerlerini de onlara katmadık mı?"},{"n":18,"t":"Suçlulara işte böyle davranırız."},{"n":19,"t":"Yalanlayanların vay haline o gün!"},{"n":20,"t":"Sizi değersiz bir sudan/sıvıdan yaratmadık mı?"},{"n":21,"t":"Ve sonra onu iyi korunan bir yere yerleştirmedik mi?"},{"n":22,"t":"Bilinen bir süreye kadar."},{"n":23,"t":"Biz ölçtük, biçtik. Biz en iyi biçim verenleriz."},{"n":24,"t":"Yalanlayanların vay haline o gün!"},{"n":25,"t":"Yeryüzünü bir toplanma yeri yapmadık mı?"},{"n":26,"t":"Yaşayanlar için, ölüler için…"},{"n":27,"t":"Üzerine yüksek dağlar yerleştirip size tatlı su içirmedik mi?"},{"n":28,"t":"Yalanlayanların vay haline o gün!"},{"n":29,"t":"Haydi yalanlamakta olduğunuz şeye doğru yürüyün."},{"n":30,"t":"Yürüyün, (cehennem alevinin) üç kollu gölgesine doğru…"},{"n":31,"t":"O ne gölgelendirir ne de alevden korur."},{"n":32,"t":"Kıvılcımlar saçar, saraylar gibi…"},{"n":33,"t":"(Rengi de) Sarı deve gibi."},{"n":34,"t":"Yalanlayanların vay haline o gün!"},{"n":35,"t":"Bu, onların konuşamayacağı bir gündür."},{"n":36,"t":"Ve özür dilemeleri için onlara izin de verilmez."},{"n":37,"t":"Yalanlayanların vay haline o gün!"},{"n":38,"t":"Bu, Karar Günüdür. Sizi ve öncekileri toplamışızdır."},{"n":39,"t":"Bir planınız varsa bana karşı onu uygulayın!"},{"n":40,"t":"Yalanlayanların vay haline o gün!"},{"n":41,"t":"Erdemliler gölgeliklerde ve pınarlar arasında…"},{"n":42,"t":"Ve canlarının çektiği meyveler…"},{"n":43,"t":"Yaptıklarınıza karşılık afiyetle yiyip için."},{"n":44,"t":"İyi davrananları işte böyle ödüllendiririz."},{"n":45,"t":"Yalanlayanların vay haline o gün!"},{"n":46,"t":"Yiyiniz ve geçici olarak eğleniniz; siz suçlularsınız."},{"n":47,"t":"Yalanlayanların vay haline o gün!"},{"n":48,"t":"Onlara eğilin dendiğinde eğilmezler."},{"n":49,"t":"Yalanlayanların vay haline o gün!"},{"n":50,"t":"Artık bundan sonra hangi hadisi (sözü) onaylıyorlar?"}]},{"id":78,"name":"Nebe Suresi","verses":[{"n":1,"t":"Neyi birbirlerine sorup duruyorlar?"},{"n":2,"t":"Büyük haberi mi?"},{"n":3,"t":"Ki onlar onda anlaşmazlık halindedirler."},{"n":4,"t":"Hayır, öğreneceklerdir."},{"n":5,"t":"Hayır, kesinlikle öğreneceklerdir."},{"n":6,"t":"Yapmadık mı yeryüzünü bir beşik,"},{"n":7,"t":"Dağları da birer kazık?"},{"n":8,"t":"Sizi çiftler halinde yarattık."},{"n":9,"t":"Uykunuzu bir dinlenme yaptık."},{"n":10,"t":"Geceyi bir örtü yaptık."},{"n":11,"t":"Gündüzü de geçimi sağlama zamanı olarak belirledik."},{"n":12,"t":"Ve üstünüze yedi sağlam (göğü) kurduk."},{"n":13,"t":"Parlayan bir lamba yerleştirdik."},{"n":14,"t":"Bulutlardan ise şarıl şarıl yağmur indirdik."},{"n":15,"t":"Ki onunla taneler ve bitkiler."},{"n":16,"t":"Ve çeşit çeşit bahçeler çıkaralım."},{"n":17,"t":"Yargılama Günü, belirlenmiş bir vakittedir."},{"n":18,"t":"Sur’a üfürüldüğü gün, hepiniz bölük bölük gelirsiniz."},{"n":19,"t":"Gök açılmış; kapı kapı olmuştur."},{"n":20,"t":"Dağlar yürütülmüş; serap olmuştur."},{"n":21,"t":"Cehennem ise gözetlemekte:"},{"n":22,"t":"Azgınlar için bir varış yeri olarak…"},{"n":23,"t":"Orada çağlar boyu kalacaklardır."},{"n":24,"t":"Orada bir serinlik ve bir içecek bulamazlar;"},{"n":25,"t":"Ancak kaynar su ve acı bir yiyecek hariç."},{"n":26,"t":"Yaptıklarına uygun bir karşılık olarak."},{"n":27,"t":"Onlar bir hesap ummuyorlardı."},{"n":28,"t":"Ve ayetlerimizi, mucizelerimizi yalanladılar."},{"n":29,"t":"Halbuki biz her şeyi sayıp yazmıştık."},{"n":30,"t":"Öyleyse tadın, sizin sadece cezanızı arttıracağız."},{"n":31,"t":"Erdemliler için kurtuluş vardır."},{"n":32,"t":"Bağlar, bahçeler…"},{"n":33,"t":"Genç ve yaşıt eşler…"},{"n":34,"t":"Dolu kadehler…"},{"n":35,"t":"Orada ne bir boş söz ne de bir yalan işitmezler."},{"n":36,"t":"Efendinden bir karşılık; hesaplanmış bir armağandır."},{"n":37,"t":"Göklerin, yerin ve aralarındakilerin Rabbidir, Rahman’dır. Hiçbir davada O’na hitap edemezler."},{"n":38,"t":"Gün gelecek Ruh ve melekler sıra sıra dururlar. Rahman’ın izin verdikleri hariç hiç kimse konuşamaz. Onlar da doğruyu söylerler."},{"n":39,"t":"İşte gerçek gün budur. Dileyen, Efendisine doğru yol tutsun."},{"n":40,"t":"Biz, sizi yakın bir azap ile uyarmış bulunuyoruz. O gün kişi yapmış olduklarına bakar ve inkârcı ise, \"Keşke toprak olsaydım!\" der."}]},{"id":79,"name":"Nazi'at Suresi","verses":[{"n":1,"t":"Andolsun söküp çıkaranlara,"},{"n":2,"t":"Rahatça çekenlere,"},{"n":3,"t":"Yüzüp akanlara,"},{"n":4,"t":"Yarışıp birbirlerini geçenlere,"},{"n":5,"t":"Ve böylece emirleri uygulayanlara…"},{"n":6,"t":"O gün o sarsıntı sarsar."},{"n":7,"t":"Ardından bir diğeri izler."},{"n":8,"t":"O gün yürekler titrer."},{"n":9,"t":"Gözleri ise alçalır."},{"n":10,"t":"Derler ki, \"Daha önceki halimize mi döndürüldük?\""},{"n":11,"t":"\"Biz çürümüş kemikler olduktan sonra ha!?\""},{"n":12,"t":"\"Öyleyse bu zararına bir dönüştür\" derler."},{"n":13,"t":"O bir tek dürtüşten ibarettir."},{"n":14,"t":"Onlar uyanıvermişlerdir."},{"n":15,"t":"Sana Musa’nın tarihi ulaştı mı?"},{"n":16,"t":"Rabbi, Kutsal Tuva vadisinde ona seslenmişti:"},{"n":17,"t":"\"Firavuna git; o azdı.\""},{"n":18,"t":"\"Ona de ki: Arınmayacak mısın?\""},{"n":19,"t":"\"Seni Efendine ileteyim de saygılı olasın.\""},{"n":20,"t":"Ona büyük mucizeyi gösterdi."},{"n":21,"t":"Fakat o yalanladı ve karşı geldi."},{"n":22,"t":"Sonra, sırtını döndü, (aleyhte) çaba gösterdi."},{"n":23,"t":"Toplayıp, ilan etti."},{"n":24,"t":"\"Ben sizin en yüce Efendinizim\" dedi."},{"n":25,"t":"Sonunda, ALLAH onu ahiret ve dünya cezasına çarptı."},{"n":26,"t":"Kuşkusuz, saygı duyanlar için bunda bir ibret vardır."},{"n":27,"t":"Siz mi, yoksa gök mü yaratılış açısından daha zorludur? Onu O yaptı."},{"n":28,"t":"Onu alabildiğine yükseltti ve düzenledi."},{"n":29,"t":"Gecesini kararttı, sabahını ise ortaya çıkardı."},{"n":30,"t":"Ve yeri de yumurta biçimine soktu."},{"n":31,"t":"Ondan suyunu ve otlağını çıkardı."},{"n":32,"t":"Dağları da çaktı."},{"n":33,"t":"Tüm bunlar sizin ve hayvanlarınızın geçimi için."},{"n":34,"t":"Büyük baskın geldiği zaman,"},{"n":35,"t":"O gün insan, neyin uğrunda çaba harcadığını anlar."},{"n":36,"t":"Cehennem göz önüne çıkarılacaktır."},{"n":37,"t":"Azgınlara,"},{"n":38,"t":"Ve dünya hayatını yeğleyenlere gelince."},{"n":39,"t":"Gidilecek yer cehennem olacaktır."},{"n":40,"t":"Efendisinin makamına karşı saygı duyan ve kendini fantezilerinden alıkoyanlara gelince"},{"n":41,"t":"Gidilecek yer bahçe olacaktır."},{"n":42,"t":"Sana o an ne zaman gerçekleşecektir diye soruyorlar."},{"n":43,"t":"Onu bildirmek, (ey Muhammed) senin görevin değildir."},{"n":44,"t":"Onun kararı Efendine aittir."},{"n":45,"t":"Senin görevin, sadece ondan korkanları uyarmaktır."},{"n":46,"t":"Onu gördükleri gün, sanki (dünyada) bir akşam veya kuşluk vakti kadar kalmışlardır."}]},{"id":80,"name":"Abese Suresi","verses":[{"n":1,"t":"Surat astı ve döndü;"},{"n":2,"t":"O kör adam geldi diye."},{"n":3,"t":"Ne bilirsin, belki de o arınacak;"},{"n":4,"t":"Yahut da öğüt alacak ve ona mesajın yararı dokunacaktı."},{"n":5,"t":"Kendisini zengin görüp önemsemeyene gelince;"},{"n":6,"t":"Sen ona yöneliyorsun."},{"n":7,"t":"Onun arınmamasından sana ne?"},{"n":8,"t":"Oysa, sana büyük bir hevesle gelen,"},{"n":9,"t":"Saygı gösterdiği halde,"},{"n":10,"t":"İlgi göstermedin ona."},{"n":11,"t":"Doğrusu, bu bir hatırlatmadır."},{"n":12,"t":"Dileyen bundan öğüt alır."},{"n":13,"t":"Onurlu kitaplardadır,"},{"n":14,"t":"Yüce ve temiz."},{"n":15,"t":"Elçilerin elleriyle (yazılmıştır)."},{"n":16,"t":"Onurlu ve güzel huylu (elçiler)."},{"n":17,"t":"Yazıklar olsun insana; ne kadar da nankördür!"},{"n":18,"t":"Onu hangi şeyden yaratmıştı?"},{"n":19,"t":"Bir spermadan onu yarattı; ölçü ve biçim verdi."},{"n":20,"t":"Sonra ona yolu kolaylaştırdı."},{"n":21,"t":"Sonra onu öldürdü, mezara koydu."},{"n":22,"t":"Dilediği zaman da onu diriltti."},{"n":23,"t":"Ne var ki O’nun kendisine emrettiğini yerine getirmedi."},{"n":24,"t":"İnsan, yiyeceğine bir baksın!"},{"n":25,"t":"Biz suyu döktükçe döktük."},{"n":26,"t":"Toprağı yardıkça yardık."},{"n":27,"t":"Ve orada taneler bitirdik,"},{"n":28,"t":"Üzümler, çayırlar,"},{"n":29,"t":"Zeytinler, hurmalar,"},{"n":30,"t":"İri ve sık ağaçlı bahçeler,"},{"n":31,"t":"Meyveler ve sebzeler…"},{"n":32,"t":"Size ve hayvanlarınıza bir geçimlik olarak."},{"n":33,"t":"Sonra, o müthiş patlama gerçekleşince,"},{"n":34,"t":"O gün kişi kaçar: kardeşinden,"},{"n":35,"t":"Annesinden, babasından,"},{"n":36,"t":"Eşinden ve çocuklarından…"},{"n":37,"t":"O gün herkesin kendisine yetecek işi vardır."},{"n":38,"t":"O gün bazı yüzler var ki aydınlık;"},{"n":39,"t":"Güleç, neşeli."},{"n":40,"t":"O gün bazı yüzler de perişan;"},{"n":41,"t":"Karanlık bürümüştür."},{"n":42,"t":"İşte onlar inkârcılardır, sapanlardır."}]},{"id":81,"name":"Tekvir Suresi","verses":[{"n":1,"t":"Güneş yuvarlandığı zaman,"},{"n":2,"t":"Yıldızlar solduğu zaman,"},{"n":3,"t":"Dağlar yürütüldüğü zaman,"},{"n":4,"t":"En değerli mallar terkedildiği zaman,"},{"n":5,"t":"Yabani hayvanlar toplandığı zaman,"},{"n":6,"t":"Denizler kaynatıldığı zaman,"},{"n":7,"t":"Nefisler/kişiler çiftleştirildiği zaman,"},{"n":8,"t":"Doğduktan hemen sonra öldürülen kız çocuğu sorulduğu zaman:"},{"n":9,"t":"Hangi suçtan ötürü öldürüldü diye."},{"n":10,"t":"Kayıtlar yayımlandığı zaman,"},{"n":11,"t":"Gök yerinden oynatıldığı zaman,"},{"n":12,"t":"Cehennem alevlendirildiği zaman,"},{"n":13,"t":"Bahçe yaklaştırıldığı zaman,"},{"n":14,"t":"Her kişi ne yapıp getirdiğini bilir."},{"n":15,"t":"Andolsun gizlenen yıldızlara,"},{"n":16,"t":"Akıp deliklerine girenlere."},{"n":17,"t":"Andolsun kararmaya başlayan geceye,"},{"n":18,"t":"Ve nefes almaya başlayan sabaha,"},{"n":19,"t":"Bu, onurlu bir elçinin sözüdür."},{"n":20,"t":"Güçlüdür; Yönetimin Sahibi katından yetkilidir."},{"n":21,"t":"Kendisine uyulmalı ve güvenilmeli."},{"n":22,"t":"Arkadaşınız deli değildir."},{"n":23,"t":"Onu apaçık bir ufukta görmüştür."},{"n":24,"t":"O, hiçbir haberi gizlemiyor."},{"n":25,"t":"O, kovulan sapkının sözü olamaz."},{"n":26,"t":"Öyleyse nereye gidiyorsunuz?"},{"n":27,"t":"Bu, tüm halklara bir mesajdır."},{"n":28,"t":"Sizden doğru davranmak isteyenler için…"},{"n":29,"t":"Ne dilerseniz, ancak evrenlerin Rabbi olan ALLAH’ın dilediğine göredir."}]},{"id":82,"name":"İnfitar Suresi","verses":[{"n":1,"t":"Gök çatladığı zaman,"},{"n":2,"t":"Gezegenler saçıldığı zaman,"},{"n":3,"t":"Denizler akıtılıp taşırıldığı zaman,"},{"n":4,"t":"Mezarların içi dışına çevrildiği zaman,"},{"n":5,"t":"Her kişi, yaptığını ve yapmadığını öğrenecektir."},{"n":6,"t":"Ey insan, seni Onurlu olan Efendisine karşı aldatan nedir?"},{"n":7,"t":"O ki seni yarattı, düzenledi, uyumlu hale soktu;"},{"n":8,"t":"Dilediği bir biçimde seni oluşturdu."},{"n":9,"t":"Doğrusu, siz, dini yalanlıyorsunuz."},{"n":10,"t":"Halbuki üstünüzde koruyucular vardır."},{"n":11,"t":"Onlar onurlu kayıtçılardır."},{"n":12,"t":"Yaptıklarınızı bilirler."},{"n":13,"t":"İyiler nimetler içindedir."},{"n":14,"t":"Kötüler ise cehennemde."},{"n":15,"t":"Din Günü oraya girerler."},{"n":16,"t":"Oradan hiç ayrılamazlar."},{"n":17,"t":"Din Gününün ne olduğunu bilir misin?"},{"n":18,"t":"Evet, Din Gününün ne olduğunu bilir misin?"},{"n":19,"t":"O gün kimsenin kimseye yardımı dokunmaz. O gün tüm kararlar yalnız ALLAH’a aittir."}]},{"id":83,"name":"Mutaffifin Suresi","verses":[{"n":1,"t":"Yazıklar olsun kandıranlara."},{"n":2,"t":"Halktan bir şey aldıklarında ölçüyü tam uygularlar."},{"n":3,"t":"Verdikleri zaman ise ölçüyü ve tartıyı eksik tutarlar."},{"n":4,"t":"Onlar hiç dirileceklerini sanmazlar mı?"},{"n":5,"t":"Büyük bir günde?"},{"n":6,"t":"O gün halk Evrenlerin Efendisinin huzurunda durur."},{"n":7,"t":"Doğrusu, kötülerin yazgısı Siccin’dedir."},{"n":8,"t":"Siccin nedir bilir misin?"},{"n":9,"t":"Rakamlanmış bir kitaptır."},{"n":10,"t":"O gün yalanlayanlara yazıklar olsun."},{"n":11,"t":"Onlar Din Gününü yalanlar."},{"n":12,"t":"Onu ancak azgın günahkarlar yalanlar."},{"n":13,"t":"Kendisine ayetlerimiz iletildiğinde, \"Efsane\" derdi."},{"n":14,"t":"Doğrusu, işledikleri günahlar kalplerini kaplamış."},{"n":15,"t":"Doğrusu, o gün onlar Rab’lerinden perdelenir."},{"n":16,"t":"Ve böylece onlar cehenneme atılır."},{"n":17,"t":"\"Yalanlamakta olduğunuz şey işte budur\" denir."},{"n":18,"t":"Doğrusu, iyilerin kitabı İlliyyun’dadır."},{"n":19,"t":"İlliyyun nedir bilir misin?"},{"n":20,"t":"Rakamlanmış bir kitaptır."},{"n":21,"t":"(Tanrı’ya) yakın olanlar ona tanık olur."},{"n":22,"t":"İyiler nimetler içindedir."},{"n":23,"t":"Koltuklar üzerinde çevreyi seyrederler."},{"n":24,"t":"Yüzlerinden nimetlerin sevinç ve parıltısını okursun."},{"n":25,"t":"Çeşni katılmış bir nektardan içirilecekler."},{"n":26,"t":"Çeşnisi misktir. Yarışanlar işte bunun için yarışsınlar."},{"n":27,"t":"Onun karışımı Tesnimdir."},{"n":28,"t":"Ki o, (Tanrı’ya) yakın olanların içtiği bir pınardır."},{"n":29,"t":"Suçlular, gerçeği onaylayanlara gülerlerdi."},{"n":30,"t":"Yanlarından geçtikleri zaman da birbirlerine göz kaş edip küçümserlerdi."},{"n":31,"t":"Taraftarlarının yanına döndükleri zaman da alaya alırlardı."},{"n":32,"t":"Onları gördüklerinde, \"Bunlar sapıklardır!\" derlerdi."},{"n":33,"t":"Oysa onların üzerine gözcü olarak gönderilmemişlerdi."},{"n":34,"t":"Bugün de gerçeği onaylayanlar inkârcılara güler."},{"n":35,"t":"Koltuklar üzerinde bakarlar:"},{"n":36,"t":"İnkarcılar yaptıklarıyla cezalandılar mı diye."}]},{"id":84,"name":"İnşikak Suresi","verses":[{"n":1,"t":"Gök yarıldığı zaman."},{"n":2,"t":"Ve doğal yapısı gereğince Efendisine kulak verdiği zaman."},{"n":3,"t":"Yer dümdüz edildiği,"},{"n":4,"t":"İçindekileri atıp boşalttığı,"},{"n":5,"t":"Ve doğal yapısı gereğince Efendisine kulak verdiği zaman."},{"n":6,"t":"Ey insan, Efendine doğru çalışıp çabalarsın ve sonunda O’nunla karşılaşırsın."},{"n":7,"t":"Kitabı sağ taraftan verilen,"},{"n":8,"t":"Kolay bir hesaba çekilecek,"},{"n":9,"t":"Ve arkadaşlarına sevinç içinde dönecektir."},{"n":10,"t":"Kitabı arkasından verilen ise,"},{"n":11,"t":"Yok olmayı arzulayacak,"},{"n":12,"t":"Ve bir ateşte yanacaktır."},{"n":13,"t":"Oysa arkadaşları arasında sevinçliydi;"},{"n":14,"t":"Bir daha (Efendisine) dönmeyeceğini sanmıştı."},{"n":15,"t":"Doğrusu, Rabbi onu görmektedir."},{"n":16,"t":"Andolsun akşamın kızıllığına,"},{"n":17,"t":"Gecenin topladığına,"},{"n":18,"t":"Dolunay halindeki aya,"},{"n":19,"t":"Siz evreden evreye binip geçeceksiniz."},{"n":20,"t":"Peki onlar neden onaylamıyorlar?"},{"n":21,"t":"Onlara Kuran okunduğunda neden kabul etmiyorlar?"},{"n":22,"t":"Aksine, inkârcılar yalanlıyorlar."},{"n":23,"t":"ALLAH onların sakladıklarını çok iyi bilir."},{"n":24,"t":"Onları acı bir azapla müjdele."},{"n":25,"t":"Gerçeği onaylayıp erdemli davrananlara ise kesilmez bir ödül var."}]},{"id":85,"name":"Büruc Suresi","verses":[{"n":1,"t":"Andolsun galaksiler sahibi göğe."},{"n":2,"t":"Söz verilen güne,"},{"n":3,"t":"Ve tanığa da tanık olunana da andolsun."},{"n":4,"t":"Kanyon halkına yazıklar olsun."},{"n":5,"t":"Tutuşturulmuş ateşin-"},{"n":6,"t":"Başında oturmuşlar,"},{"n":7,"t":"Ve gerçeği onaylayanlara yaptıkları işkenceyi seyrediyorlar."},{"n":8,"t":"Gerçeği onaylayanlardan nefret ediyorlardı. Sadece, onlar Üstün ve Övgüye layık olan ALLAH’ı onayladıkları için…"},{"n":9,"t":"Göklerin ve yerin yönetimi O’na aittir. Ve ALLAH her şeye Tanıktır."},{"n":10,"t":"Gerçeği onaylayan erkeklere ve kadınlara zulüm ve işkencede bulunan ve daha sonra tövbe etmeyenler cehennem azabını haketmişlerdir. Onlar için yakıcı bir azap vardır."},{"n":11,"t":"Gerçeği onaylayan ve erdemli davrananlar ise içlerinden ırmaklar akan bahçeleri haketmişlerdir. Büyük başarı budur."},{"n":12,"t":"Doğrusu, Efendinin yakalaması pek çetindir."},{"n":13,"t":"Başlatan ve tekrarlayan O’dur."},{"n":14,"t":"O Bağışlayandır, Sevendir."},{"n":15,"t":"Şanlı yönetimin sahibidir."},{"n":16,"t":"Dilediğini yapandır."},{"n":17,"t":"Orduların tarihinden haberin var mı?"},{"n":18,"t":"Firavunun, Semud’un?"},{"n":19,"t":"İnkarcılar, kronik yalanlayıcılardır."},{"n":20,"t":"ALLAH onları arkalarından kuşatmıştır."},{"n":21,"t":"Gerçekten, o şanlı bir Kuran’dır."},{"n":22,"t":"Korunmuş bir ana levhadadır."}]},{"id":86,"name":"Tarık Suresi","verses":[{"n":1,"t":"Göğe ve Tarık’a andolsun."},{"n":2,"t":"Tarık’ın ne olduğunu bilir misin?"},{"n":3,"t":"Parlak yıldızdır."},{"n":4,"t":"Her kişinin üzerinde mutlaka bir koruyucu vardır."},{"n":5,"t":"İnsan neden yaratılmış olduğuna bir baksın."},{"n":6,"t":"Atılan bir sıvıdan yaratıldı."},{"n":7,"t":"Omurga ile kaburga kemikleri arasından çıkar."},{"n":8,"t":"Kuşkusuz O, onu diriltmeye gücü yetendir."},{"n":9,"t":"Gizemlerin ortaya çıkarılacağı gün."},{"n":10,"t":"Onun ne bir gücü ne de bir yardımcısı olmayacaktır."},{"n":11,"t":"Geri çeviren göğe andolsun,"},{"n":12,"t":"Ve yarılan yeryüzüne andolsun ki,"},{"n":13,"t":"Bu, ayırdedici bir sözdür."},{"n":14,"t":"Şakaya alınamaz."},{"n":15,"t":"Onlar bir plan kuruyor."},{"n":16,"t":"Ben de bir plan kuruyorum."},{"n":17,"t":"Öyleyse inkârcılara az bir süre daha tanı."}]},{"id":87,"name":"A'la Suresi","verses":[{"n":1,"t":"Yüce Efendinin ismini eksikliklerden uzak tut."},{"n":2,"t":"O ki yarattı, düzene koydu."},{"n":3,"t":"O ki ölçtü, yol gösterdi."},{"n":4,"t":"O ki yeşillikler bitirdi."},{"n":5,"t":"Sonra onu kuruyup kararmış bir samana çevirir."},{"n":6,"t":"Seni okutacağız; sen de unutmayacaksın."},{"n":7,"t":"ALLAH’ın dilediği hariç; O açığı da bilir, gizliyi de."},{"n":8,"t":"Sana kolayı daha da kolaylaştıracağız."},{"n":9,"t":"Öğüt yararlı olacaksa öğüt ver."},{"n":10,"t":"Saygı duyanlar öğüt alacaktır."},{"n":11,"t":"Mutsuz ise ondan yan çizecektir."},{"n":12,"t":"Ve büyük ateşe girecektir."},{"n":13,"t":"Nitekim, orada ne ölecek, ne de yaşayacaktır."},{"n":14,"t":"Kurtulmuştur arınan,"},{"n":15,"t":"Efendisinin ismini anıp namaz kılan."},{"n":16,"t":"Ne var ki siz dünya hayatını seçiyorsunuz."},{"n":17,"t":"Oysa ahiret daha iyi ve süreklidir."},{"n":18,"t":"Bu, ilk sayfalarda/öğretilerde kayıtlıdır."},{"n":19,"t":"İbrahim’in ve Musa’nın sayfalarında."}]},{"id":88,"name":"Gaşiye Suresi","verses":[{"n":1,"t":"Sana o bunaltanın haberi ulaştı mı?"},{"n":2,"t":"O gün yüzler saygı gösterir."},{"n":3,"t":"Çalışmıştır, yorgun düşmüştür."},{"n":4,"t":"Kızgın ateşe girerler."},{"n":5,"t":"Kaynar bir pınardan içirilirler."},{"n":6,"t":"Değersiz bir yiyeceğin dışında bir şeyleri yoktur;"},{"n":7,"t":"Ne besler, ne de açlığı giderir."},{"n":8,"t":"O gün başka yüzler de var ki mutludur."},{"n":9,"t":"Yaptıklarından ötürü sevinçlidir."},{"n":10,"t":"Yüksek bir bahçededir."},{"n":11,"t":"Orada bir saçmalık işitmezler."},{"n":12,"t":"Orada akan bir kaynak var."},{"n":13,"t":"Orada yüksek mobilyalar var."},{"n":14,"t":"Kadehler konulmuş,"},{"n":15,"t":"Yastıklar dizilmiş,"},{"n":16,"t":"Ve halılar serilmiştir."},{"n":17,"t":"Bakmazlar mı develere, nasıl yaratıldı?"},{"n":18,"t":"Ve göğe, nasıl yükseltildi?"},{"n":19,"t":"Ve dağlara, nasıl dikildi?"},{"n":20,"t":"Ve yere, nasıl döşendi?"},{"n":21,"t":"Hatırlat, çünkü sen hatırlatıcısın."},{"n":22,"t":"Sen onları zorlayacak değilsin."},{"n":23,"t":"Fakat kim yüz çevirir ve inkâr ederse,"},{"n":24,"t":"ALLAH onu en büyük ceza ile cezalandırır."},{"n":25,"t":"Onların dönüşleri bizedir."},{"n":26,"t":"Hesaplarını görmek de bize düşer."}]},{"id":89,"name":"Fecr Suresi","verses":[{"n":1,"t":"Andolsun tan vaktine,"},{"n":2,"t":"On geceye,"},{"n":3,"t":"Çifte ve teke,"},{"n":4,"t":"Ve geçmekte olan geceye."},{"n":5,"t":"Zeka sahipleri için bunlar birer yemin değil midir?"},{"n":6,"t":"Görmedin mi Efendin ne yaptı Ad halkına?"},{"n":7,"t":"Yüksek kulelere sahip İrem’e ki;"},{"n":8,"t":"Hiçbir ülkede eşi ortaya konmamıştı."},{"n":9,"t":"Vadideki kayaları oyan Semud’a?"},{"n":10,"t":"Ve büyük bir güce sahip olan Firavuna?"},{"n":11,"t":"Tüm bunlar ülkelerinde azmışlardı."},{"n":12,"t":"Oralarda kötülükleri yaygınlaştırmışlardı."},{"n":13,"t":"Nitekim, Efendin de üstlerine türlü felaketler yağdırdı."},{"n":14,"t":"Efendin sürekli gözetlemektedir."},{"n":15,"t":"Rabbi, sınamak için insana bolca verip sevindirdiği zaman, \"Efendim bana cömert davrandı\" der."},{"n":16,"t":"Ancak ne zaman ki rızkını kısarak onu sınarsa, \"Efendim beni küçük düşürdü\" der."},{"n":17,"t":"Hayır! Doğrusu siz öksüze cömert davranmıyorsunuz?"},{"n":18,"t":"Yoksulu yedirmeye birbirinizi teşvik etmiyorsunuz."},{"n":19,"t":"Mirası da hak gözetmeden yiyorsunuz."},{"n":20,"t":"Parayı/malı da çok fazla seviyorsunuz."},{"n":21,"t":"Doğrusu, yer çarpılıp paralandığı zaman,"},{"n":22,"t":"Efendin, dizi dizi meleklerle birlikte geldiği zaman,"},{"n":23,"t":"Ki cehennem de o gün getirilmiştir. İşte o gün insan anlayacaktır. Artık anlamanın kendisine ne yararı var ki!"},{"n":24,"t":"\"Keşke bu hayatım için önceden bir şeyler yapsaydım\" der."},{"n":25,"t":"O gün, O’nun cezası gibi bir cezayı kimse veremez."},{"n":26,"t":"O’nun vurduğu bağ gibisini de kimse bağlayamaz."},{"n":27,"t":"Ey doygunluğa ermiş kişi,"},{"n":28,"t":"Hoşnut olarak ve hoşnut olunarak Efendine dön."},{"n":29,"t":"Kullarımın arasına hoşgeldin."},{"n":30,"t":"Bahçeme hoşgeldin."}]},{"id":90,"name":"Beled Suresi","verses":[{"n":1,"t":"Bu kente dikkat et,"},{"n":2,"t":"Ki sen bu kentte oturmaktasın."},{"n":3,"t":"Doğurana ve doğurduğuna da."},{"n":4,"t":"İnsanı zorluklar arasında (direnmesi için) yarattık."},{"n":5,"t":"Kendisine güç yetiremeyeceğimizi mi sanıyor?"},{"n":6,"t":"(Övünerek) \"Çok para harcadım\" diyor."},{"n":7,"t":"Kimsenin kendisini görmediğini mi sanıyor?"},{"n":8,"t":"Ona vermedik mi: İki göz,"},{"n":9,"t":"Bir dil ve iki dudak?"},{"n":10,"t":"Ona iki yolu göstermedik mi?"},{"n":11,"t":"Ne var ki zor yola katlanamadı."},{"n":12,"t":"Zor yolun ne olduğunu bilir misin?"},{"n":13,"t":"Boyunduruk altındakileri özgürlüklerine kavuşturmaktır;"},{"n":14,"t":"Kıtlık anında doyurmaktır:"},{"n":15,"t":"Akraba bir öksüzü,"},{"n":16,"t":"Yahut düşkün bir yoksulu…"},{"n":17,"t":"Dahası, birbirlerine sabır ve sevgiyi öğütleyen gerçeği onaylayanlardan olmaktır."},{"n":18,"t":"Nitekim mutlular onlardır."},{"n":19,"t":"Ayet ve mucizelerimizi inkâr edenlerse talihsizlerdir."},{"n":20,"t":"Onlar ateşe kapatılacaklardır."}]},{"id":91,"name":"Şems Suresi","verses":[{"n":1,"t":"Andolsun güneşe ve onun aydınlığına,"},{"n":2,"t":"Onu izleyen aya,"},{"n":3,"t":"Onu açığa çıkaran gündüze,"},{"n":4,"t":"Onu örten geceye,"},{"n":5,"t":"Göğe ve onu kurana,"},{"n":6,"t":"Yere ve onu yuvarlayıp döşeyene,"},{"n":7,"t":"Nefse ve onu düzenleyene,"},{"n":8,"t":"Sonra da ona kötülüğünü ve erdemliliğini bildirene andolsun ki;"},{"n":9,"t":"Onu temizleyen kurtulmuştur."},{"n":10,"t":"Onu başıboş bırakan ise zarar etmiştir."},{"n":11,"t":"Semud (halkı), azgınlığı yüzünden yalanladı."},{"n":12,"t":"En azgınları ayaklanmıştı."},{"n":13,"t":"ALLAH’ın elçisi, onlara, \"ALLAH’ın devesine ve onun suyuna dokunmayın\" demişti."},{"n":14,"t":"Onu yalanlayıp deveyi boğazladılar. Bunun üzerine Rab’leri suçlarından ötürü onları silip yerle bir etti."},{"n":15,"t":"Ne var ki hâlâ onların sonlarından ders alınmıyor."}]},{"id":92,"name":"Leyl Suresi","verses":[{"n":1,"t":"Bürüdüğü zaman geceye,"},{"n":2,"t":"Ortaya çıktığı zaman gündüze,"},{"n":3,"t":"Erkeği ve dişiyi yaratana dikkat edin,"},{"n":4,"t":"İşleriniz çeşit çeşittir."},{"n":5,"t":"Kim verir ve erdemli davranır,"},{"n":6,"t":"Ve iyiyi, güzeli doğrularsa,"},{"n":7,"t":"Ona iyice kolaylaştırırız."},{"n":8,"t":"Fakat, kim cimrilik edip zenginlik taslar,"},{"n":9,"t":"Ve iyiyi, güzeli yalanlarsa,"},{"n":10,"t":"Onu da zora yöneltiriz."},{"n":11,"t":"Düştüğü vakit kurtaramaz parası/malı onu."},{"n":12,"t":"Doğruya biz iletiriz;"},{"n":13,"t":"Sonu da ilki de biz kontrol ederiz."},{"n":14,"t":"Ben sizi alevli bir ateşe karşı uyardım."},{"n":15,"t":"Oraya talihsiz olandan başkası girmez."},{"n":16,"t":"O ki yalanladı ve sırtını döndü."},{"n":17,"t":"Erdemli ise ondan uzak tutulacaktır."},{"n":18,"t":"O ki malını vererek temizlenir;"},{"n":19,"t":"Hiç kimseden de buna karşılık bir iyilik beklemez."},{"n":20,"t":"Sadece En Yüce olan Efendisinin rızasını gözetir."},{"n":21,"t":"Kendisi de yakında mutlu olacaktır."}]},{"id":93,"name":"Duha Suresi","verses":[{"n":1,"t":"Andolsun kuşluk vaktine,"},{"n":2,"t":"Ve dingin olduğu zaman geceye,"},{"n":3,"t":"Efendin seni ne bıraktı ne de sana darıldı."},{"n":4,"t":"Senin için son baştan daha iyidir."},{"n":5,"t":"Efendin yakında sana verecek ve sen de beğeneceksin."},{"n":6,"t":"Seni bir öksüz olarak bulup barındırmadık mı?"},{"n":7,"t":"Seni yolunu şaşırmış olarak bulup doğruya iletmedik mi?"},{"n":8,"t":"Seni fakir bulup zengin etmedik mi?"},{"n":9,"t":"Öyleyse, öksüzü yüzüstü bırakma."},{"n":10,"t":"Dilenciyi de azarlama."},{"n":11,"t":"Ve Efendinin sana yaptığı iyilikleri de anlat."}]},{"id":94,"name":"İnşirah Suresi","verses":[{"n":1,"t":"Göğsünü genişletip seni sakinleştirmedik mi?"},{"n":2,"t":"Üzerindeki yükünü indirmedik mi?"},{"n":3,"t":"Ki belini bükmüştü."},{"n":4,"t":"Senin şanını yükseltmedik mi?"},{"n":5,"t":"Elbette, kolaylık zorlukla birliktedir."},{"n":6,"t":"Evet, kolaylık zorlukla birliktedir."},{"n":7,"t":"Ne zaman fırsat bulursan uğraş ver."},{"n":8,"t":"Ve sadece Efendini arzula."}]},{"id":95,"name":"Tin Suresi","verses":[{"n":1,"t":"Andolsun incire ve zeytine,"},{"n":2,"t":"Sina Dağına,"},{"n":3,"t":"Ve andolsun bu güvenilir kente (Mekke’ye) ki;"},{"n":4,"t":"Biz insanı en güzel olgunlukta yarattık."},{"n":5,"t":"Sonra onu aşağıların aşağısı kıldık."},{"n":6,"t":"Ancak gerçeği onaylayıp erdemli davrananlar hariç; onlara kesintisiz bir ödül vardır."},{"n":7,"t":"Artık neden hâlâ bu dini yalanlıyorsun?"},{"n":8,"t":"ALLAH bilgelerin En Bilgesi değil midir?"}]},{"id":96,"name":"Âlak Suresi","verses":[{"n":1,"t":"Yaratan Efendinin ismiyle oku."},{"n":2,"t":"O, insanı bir embriyodan yarattı."},{"n":3,"t":"Oku, Efendin En Cömert/Yüce olandır."},{"n":4,"t":"Kalem yoluyla öğretir."},{"n":5,"t":"İnsana bilmediklerini öğretti."},{"n":6,"t":"Doğrusu, insan azar;"},{"n":7,"t":"Kendini yeterli görerek."},{"n":8,"t":"Elbette, dönüş senin Efendinedir."},{"n":9,"t":"Gördün mü, şu engelleyeni:"},{"n":10,"t":"Desteklerken bir kulu?"},{"n":11,"t":"Ne dersin, o doğru yolu izleseydi?"},{"n":12,"t":"Yahut erdemliliği öğütleseydi?"},{"n":13,"t":"Ne dersin, o yalanlayıp yüz çevirdiyse?"},{"n":14,"t":"Bilmez mi ki ALLAH her şeyi görmektedir."},{"n":15,"t":"Doğrusu, buna son vermezse, yakalarız ön lobundan,"},{"n":16,"t":"O yalancı ve günahkar ön lobu."},{"n":17,"t":"O zaman haydi çağırsın kurultayını."},{"n":18,"t":"Biz de zebanileri çağıracağız.."},{"n":19,"t":"Asla, ona uyma; secde et ve yaklaş!"}]},{"id":97,"name":"Kadir Suresi","verses":[{"n":1,"t":"Biz onu Kudret Gecesinde indirdik."},{"n":2,"t":"Kudret Gecesi ne kadar önemlidir, bilir misin?"},{"n":3,"t":"Kudret Gecesi bin aydan daha hayırlıdır."},{"n":4,"t":"Denetçiler ve Ruh (Cebrail) o gece Rab’lerinin izniyle tüm buyrukları yerine getirmek için inerler."},{"n":5,"t":"O, tan yeri ağarıncaya kadar esenliktir."}]},{"id":98,"name":"Beyyine Suresi","verses":[{"n":1,"t":"Kitap halkının inkârcıları ve putperestler, kendilerine açık delil/kanıt gelmesine rağmen yollarını terketmezler."},{"n":2,"t":"ALLAH’ın bir elçisi kendilerine arındırılmış/temizlenmiş sahifeler okuyor."},{"n":3,"t":"Onda dosdoğru öğretiler vardır."},{"n":4,"t":"Gerçek şu ki, kendilerine kitap verilmiş olanlar, ancak onlara açık delil geldikten sonra ayrılığa düştüler."},{"n":5,"t":"Oysa onlardan, dini sadece ALLAH’a ait kılan tektanrıcılar (monoteist) olarak O’na hizmet etmeleri, namazı gözetmeleri ve zekatı vermeleri istenmişti. İşte dosdoğru din budur."},{"n":6,"t":"Kitap halkının inkârcıları ve putperestler, cehennem ateşinin içindedirler ve orada ebedi kalıcıdırlar. Onlar, yaratıkların en kötüsüdür."},{"n":7,"t":"Gerçeği onaylayıp erdemli davrananlar ise yaratıkların en iyisidir."},{"n":8,"t":"Rab’leri katındaki ödülleri, içinden ırmaklar akan bahçelerdir. Orada ebedi olarak kalacaklardır. ALLAH onlardan hoşnut olmuş, onlar da O’ndan hoşnut olmuşlardır. Efendisine saygı gösterenin ödülü işte böyledir."}]},{"id":99,"name":"Zilzal Suresi","verses":[{"n":1,"t":"Yerin korkunç bir depremle sarsıldığı,"},{"n":2,"t":"Yerin ağırlıklarını fışkırttığı,"},{"n":3,"t":"İnsanın da, \"Buna ne oluyor?\" dediği zaman,"},{"n":4,"t":"İşte o gün (yer), haberlerini anlatacaktır."},{"n":5,"t":"Çünkü Efendin ona vahyetmiştir."},{"n":6,"t":"O gün, insanlar yapmış oldukları kendilerine gösterilsin diye bölükler halinde çıkagelirler."},{"n":7,"t":"Kim bir atom ağırlığı iyilikte bulunursa onu görür."},{"n":8,"t":"Ve kim bir atom ağırlığı kötülükte bulunursa onu görür."}]},{"id":100,"name":"Adiyat Suresi","verses":[{"n":1,"t":"Andolsun soluyarak aşanlara,"},{"n":2,"t":"Ateş saçarak gidenlere,"},{"n":3,"t":"Sabah sabah akın edenlere,"},{"n":4,"t":"Toz koparanlara,"},{"n":5,"t":"Ve topluluğun ortasına dalanlara ki;"},{"n":6,"t":"İnsan Efendisine karşı çok nankördür."},{"n":7,"t":"Üstelik buna da tanıktır."},{"n":8,"t":"O mala çok düşkündür."},{"n":9,"t":"Bilmez mi ki, mezardakiler ortaya atıldığı,"},{"n":10,"t":"Ve göğüslerde gizlenenler açığa çıkarıldığı zaman,"},{"n":11,"t":"Evet o gün Rab’leri onların her şeyinden haberlidir."}]},{"id":101,"name":"Kari'a Suresi","verses":[{"n":1,"t":"Şok."},{"n":2,"t":"Hem de ne şok!"},{"n":3,"t":"Şoke edenin niteliği sana bildirildi mi?"},{"n":4,"t":"O gün halk, yayılmış kelebekler gibi olur."},{"n":5,"t":"Dağlar da atılmış yün gibi olur."},{"n":6,"t":"Kimin tartıları ağır gelirse,"},{"n":7,"t":"O, mutlu bir hayat içinde olacaktır."},{"n":8,"t":"Kimin de tartıları hafif gelirse,"},{"n":9,"t":"Onun da varacağı yer uçurumdur."},{"n":10,"t":"O uçurumun ne olduğunu bilir misin?"},{"n":11,"t":"O, kızgın bir ateştir!"}]},{"id":102,"name":"Tekasür Suresi","verses":[{"n":1,"t":"Çoğaltma yarışı sizi alabildiğine meşgul etti;"},{"n":2,"t":"Mezarlara varıncaya (ölünceye) kadar…"},{"n":3,"t":"Doğrusu, yakında bileceksiniz."},{"n":4,"t":"Elbette, yakında bileceksiniz."},{"n":5,"t":"Doğrusu, kesin olarak bilseydiniz."},{"n":6,"t":"Cehennemi görürdünüz."},{"n":7,"t":"Zaten, onu gözünüzle kesin olarak göreceksiniz."},{"n":8,"t":"Sonra, o gün (size verilen) nimetlerden sorulacaksınız."}]},{"id":103,"name":"Asr Suresi","verses":[{"n":1,"t":"Andolsun akıp giden zamana ki;"},{"n":2,"t":"İnsanlar zarardadır."},{"n":3,"t":"Ancak gerçeği onaylayıp erdemli davrananlar, birbirlerine gerçeği öğütleyenler ve birbirlerine sabretmeyi öğütleyenler hariç."}]},{"id":104,"name":"Hümeze Suresi","verses":[{"n":1,"t":"Yazıklar olsun her dedikoducuya ve iftiracıya."},{"n":2,"t":"Ki o para/mal biriktirir ve onu sayar durur."},{"n":3,"t":"Sanki parası/malı onu ölümsüz yapacakmış gibi."},{"n":4,"t":"Asla; onu Hutama’ya atacağım."},{"n":5,"t":"Hutama’nın ne olduğunu bilir misin?"},{"n":6,"t":"ALLAH’ın tutuşturulmuş ateşidir."},{"n":7,"t":"Ki beyinlere işler."},{"n":8,"t":"Onların üzerine kapanmıştır."},{"n":9,"t":"Yükselen direkler arasında."}]},{"id":105,"name":"Fil Suresi","verses":[{"n":1,"t":"Efendinin fil halkını ne hale soktuğuna dikkat ettin mi?"},{"n":2,"t":"Planlarını boşa çıkarıp onları şaşkına çevirmedi mi?"},{"n":3,"t":"Onların üstüne kuş sürüleri gönderdi."},{"n":4,"t":"Onlara sertleşmiş çamurdan taşlar atıyorlardı."},{"n":5,"t":"Ve böylece onları yenmiş ekin gibi perişan etmişti."}]},{"id":106,"name":"Kureyş Suresi","verses":[{"n":1,"t":"Kureyş (bu mesajı) bağrına basmalı;"},{"n":2,"t":"Kış ve yaz kervanlarını sevdikleri gibi."},{"n":3,"t":"Bu evin Efendisine hizmet etsinler."},{"n":4,"t":"O ki onları açlıktan kurtarıp doyurdu ve korkudan güvene kavuşturdu."}]},{"id":107,"name":"Ma'un Suresi","verses":[{"n":1,"t":"Dini yalanlayanı gördün mü?"},{"n":2,"t":"İşte, öksüze kötü davranan odur."},{"n":3,"t":"Yoksulları doyurmaya da yanaşmaz."},{"n":4,"t":"Yazıklar olsun o namaz kılanlara,"},{"n":5,"t":"Onlar ki namazlarından tümüyle habersizdirler."},{"n":6,"t":"Onlar ki gösteriş yaparlar."},{"n":7,"t":"Ve yardımı da engellerler."}]},{"id":108,"name":"Kevser Suresi","verses":[{"n":1,"t":"Biz sana bolca nimetler verdik."},{"n":2,"t":"Öyleyse Efendin için namaz kıl ve kendini ada/yönel."},{"n":3,"t":"Asıl mahvolacak olanlar, sana kin duyanlardır."}]},{"id":109,"name":"Kâfirun Suresi","verses":[{"n":1,"t":"De ki: \"Ey inkârcılar.\""},{"n":2,"t":"\"Ben, sizin hizmet ettiklerinize hizmet etmem.\""},{"n":3,"t":"\"Siz de benim hizmet ettiğime hizmet etmezsiniz.\""},{"n":4,"t":"\"Ben asla sizin hizmet ettiğinize hizmet edecek değilim.\""},{"n":5,"t":"\"Siz de benim hizmet ettiğime hizmet edecek değilsiniz.\""},{"n":6,"t":"\"Sizin dininiz size, benim dinim bana.\""}]},{"id":110,"name":"Nasr Suresi","verses":[{"n":1,"t":"ALLAH’ın yardımı ve zafer geldiği zaman,"},{"n":2,"t":"Halkın akın akın ALLAH’ın dinine girdiğini göreceksin."},{"n":3,"t":"Rabb’ini överek yücelt ve O’ndan bağışlanma dile. O, tövbeleri sürekli kabul edendir."}]},{"id":111,"name":"Tebbet Suresi","verses":[{"n":1,"t":"Ateş körükleyenin elleri kahrolsun, zaten kendisi kahroldu."},{"n":2,"t":"Ne parası, ne de bir kazancı ona yaramadı."},{"n":3,"t":"O, alev sahibi bir ateşe girecektir."},{"n":4,"t":"Odun taşıyan (zulmün ateşine yakıt hazırlayan) karısı da."},{"n":5,"t":"Boynunda, dikenlerden/liften örülmüş bir ip bulunduğu (kötülükleri boynuna dolanmış) halde…"}]},{"id":112,"name":"İhlas Suresi","verses":[{"n":1,"t":"De ki: \"O ALLAH bir tektir.\""},{"n":2,"t":"\"ALLAH Sonsuz ve Mutlak/İlk sebeptir.\""},{"n":3,"t":"\"Doğurmamıştır, doğurulmamıştır.\""},{"n":4,"t":"\"Hiçbir kimse de O’na denk değildir.\""}]},{"id":113,"name":"Felak Suresi","verses":[{"n":1,"t":"De ki: \"Şafağın Rabb’ine sığınırım.\""},{"n":2,"t":"\"Yarattığı şeylerin şerrinden.\""},{"n":3,"t":"\"Çöktüğü zaman karanlığın şerrinden.\""},{"n":4,"t":"\"Arabozucuların, sözleşmeleri bozanların şerrinden.\""},{"n":5,"t":"\"Kıskandığı vakit kıskananın şerrinden.\""}]},{"id":114,"name":"Nas Suresi","verses":[{"n":1,"t":"De ki: \"Sığınırım halkın Rabb’ine\""},{"n":2,"t":"\"Halkın Yöneticisine\""},{"n":3,"t":"\"Halkın Tanrısına\""},{"n":4,"t":"\"Şerrinden sinsice fısıldayanların.\""},{"n":5,"t":"\"Onlar halkın göğsüne fısıldarlar.\""},{"n":6,"t":"\"Onlar hem cinlerden hem de halktandır.\""}]}];
